This section contains the contents of the repository's files. 1: // ============================================================
 2: // AthleteOS — src/components/ui/ErrorBoundary.jsx
 3: // Filet de sécurité React : sans ça, une exception de rendu
 4: // (donnée inattendue, etc.) fait planter toute l'app en écran
 5: // blanc. Ici on affiche un message récupérable à la place.
 6: // ============================================================
 7: 
 8: import { Component } from "react";
 9: import { RefreshCw, AlertTriangle } from "lucide-react";
10: import { captureError } from "../../utils/sentry";
11: 
12: export default class ErrorBoundary extends Component {
13:   constructor(props) {
14:     super(props);
15:     this.state = { error: null };
16:   }
17: 
18:   static getDerivedStateFromError(error) {
19:     return { error };
20:   }
21: 
22:   componentDidCatch(error, info) {
23:     console.error("ErrorBoundary a intercepté une erreur:", error, info);
24:     captureError(error, { componentStack: info?.componentStack });
25:   }
26: 
27:   render() {
28:     if (!this.state.error) return this.props.children;
29: 
30:     return (
31:       <div className="min-h-screen flex items-center justify-center p-6" style={{ background: "var(--c-bg)" }}>
32:         <div className="card p-8 max-w-sm w-full text-center">
33:           <div style={{ width: 56, height: 56, borderRadius: 18, display: "flex", alignItems: "center", justifyContent: "center", margin: "0 auto 16px", background: "rgba(224,82,82,0.10)" }}>
34:             <AlertTriangle size={26} color="#E05252" strokeWidth={1.5} />
35:           </div>
36:           <p style={{ fontSize: 15, fontWeight: 600, color: "var(--c-text-1)", marginBottom: 6 }}>
37:             Une erreur inattendue s'est produite
38:           </p>
39:           <p style={{ fontSize: 12.5, color: "var(--c-text-3)", marginBottom: 22, lineHeight: 1.6 }}>
40:             L'application a rencontré un problème et ne peut pas continuer. Recharge la page — si ça se reproduit, préviens ton coach ou le support.
41:           </p>
42:           <button
43:             onClick={() => window.location.reload()}
44:             className="btn-primary"
45:             style={{ marginInline: "auto" }}
46:           >
47:             <RefreshCw size={14} /> Recharger la page
48:           </button>
49:         </div>
50:       </div>
51:     );
52:   }
53: } 1: // ============================================================
 2: // AthleteOS — src/components/ui/ErrorState.jsx
 3: // Bloc d'erreur réutilisable.
 4: // Remplace tous les blocs if (error) {...} dupliqués.
 5: //
 6: // Usage :
 7: //   import ErrorState from "../components/ui/ErrorState";
 8: //   if (error) return <ErrorState message={error} onRetry={fetchAll} />;
 9: // ============================================================
10: 
11: import { memo } from "react";
12: import { AlertTriangle, RefreshCw } from "lucide-react";
13: 
14: function ErrorState({ message = "Une erreur est survenue.", onRetry }) {
15:   return (
16:     <div className="p-6 max-w-4xl mx-auto">
17:       <div
18:         className="rounded-xl p-5"
19:         style={{ background: "rgba(224,82,82,0.08)", border: "1px solid rgba(224,82,82,0.20)" }}
20:       >
21:         <div className="flex items-start gap-3">
22:           <AlertTriangle size={20} className="flex-shrink-0 mt-0.5" style={{ color: "var(--c-dim-danger)" }} />
23:           <div className="flex-1 min-w-0">
24:             <h3 className="text-[14px] font-semibold mb-1" style={{ color: "var(--c-text-1)" }}>
25:               Impossible de charger les données
26:             </h3>
27:             <p className="text-[12px]" style={{ color: "var(--c-text-2)" }}>{message}</p>
28:           </div>
29:           {onRetry && (
30:             <button
31:               onClick={onRetry}
32:               className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-[12px] font-medium transition-colors flex-shrink-0 hover:bg-[rgba(224,82,82,0.22)]"
33:               style={{ background: "rgba(224,82,82,0.14)", color: "var(--c-dim-danger)" }}
34:             >
35:               <RefreshCw size={13} />
36:               Réessayer
37:             </button>
38:           )}
39:         </div>
40:       </div>
41:     </div>
42:   );
43: }
44: 
