50: export default memo(LoadingState); 1: // ============================================================
 2: // AthleteOS — src/hooks/useUrlView.jsx
 3: //
 4: // Routing minimal par History API — pas de react-router. La nav de
 5: // l'app est un simple switch entre vues plates (un seul niveau, pas de
 6: // route imbriquée/paramétrée), une lib de routing complète serait
 7: // disproportionnée pour ça.
 8: //
 9: // Avant ça, activeView était un simple useState : rafraîchir la page
10: // ramenait toujours au dashboard, le bouton retour du navigateur ne
11: // faisait rien, et il était impossible d'envoyer un lien direct vers
12: // une vue précise (ex. partager un lien vers "Mes performances").
13: // ============================================================
14: 
15: import { useState, useCallback, useEffect } from "react";
16: 
17: function resolveView(pathname, validIds, defaultView) {
18:   const id = pathname.replace(/^\//, "");
19:   return validIds.includes(id) ? id : defaultView;
20: }
21: 
22: export function useUrlView(validIds, defaultView) {
23:   const [activeView, setActiveView] = useState(() => resolveView(window.location.pathname, validIds, defaultView));
24:   const [viewKey, setViewKey] = useState(0);
25: 
26:   // Recadre l'URL au montage si le chemin ne correspond à aucune vue
27:   // connue (racine "/", faute de frappe, lien périmé…).
28:   useEffect(() => {
29:     const initial = resolveView(window.location.pathname, validIds, defaultView);
30:     if (window.location.pathname !== `/${initial}`) {
31:       window.history.replaceState({ view: initial }, "", `/${initial}`);
32:     }
33:     // eslint-disable-next-line react-hooks/exhaustive-deps
34:   }, []);
35: 
36:   // Bouton précédent/suivant du navigateur.
37:   useEffect(() => {
38:     const onPopState = () => {
39:       setActiveView(resolveView(window.location.pathname, validIds, defaultView));
40:       setViewKey(k => k + 1);
41:     };
42:     window.addEventListener("popstate", onPopState);
43:     return () => window.removeEventListener("popstate", onPopState);
44:   }, [validIds, defaultView]);
45: 
46:   const navigate = useCallback((view) => {
47:     const v = validIds.includes(view) ? view : defaultView;
48:     setActiveView(v);
49:     setViewKey(k => k + 1);
50:     if (window.location.pathname !== `/${v}`) {
51:       window.history.pushState({ view: v }, "", `/${v}`);
52:     }
53:   }, [validIds, defaultView]);
54: 
55:   return { activeView, navigate, viewKey };
56: } 1: // ============================================================
 2: // AthleteOS — src/utils/sentry.js
 3: // Monitoring d'erreurs en prod. Sans ça, un crash chez un
 4: // athlète est invisible — la seule information disponible était
 5: // un message verbal de l'utilisateur.
 6: //
 7: // Ne s'active que si VITE_SENTRY_DSN est renseigné (créer un
 8: // projet gratuit sur sentry.io, coller le DSN dans .env en local
 9: // ET dans les variables d'environnement du projet sur Vercel).
10: // Tant que le DSN est vide, tout ceci est un no-op silencieux.
11: // ============================================================
12: 
13: import * as Sentry from "@sentry/react";
14: 
15: const DSN = import.meta.env.VITE_SENTRY_DSN;
16: 
17: export const sentryEnabled = !!DSN;
18: 
19: export function initSentry() {
20:   if (!DSN) return;
21:   Sentry.init({
22:     dsn: DSN,
23:     environment: import.meta.env.MODE,
24:     tracesSampleRate: 0.1,
25:   });
26: }
27: 
28: export function captureError(error, context) {
29:   if (!DSN) return;
30:   Sentry.captureException(error, context ? { extra: context } : undefined);
31: }1: import { createClient } from '@supabase/supabase-js';
2: 
3: const supabaseUrl = import.meta.env.VITE_SUPABASE_URL;
4: const supabaseAnonKey = import.meta.env.VITE_SUPABASE_ANON_KEY;
5: 
6: export const supabase = createClient(supabaseUrl, supabaseAnonKey); 1: BEGIN;
 2: 
 3: -- 1) Tables that already have correct club-scoped policies — just turn RLS on.
 4: ALTER TABLE public.users ENABLE ROW LEVEL SECURITY;
 5: ALTER TABLE public.social_comments ENABLE ROW LEVEL SECURITY;
 6: ALTER TABLE public.social_posts ENABLE ROW LEVEL SECURITY;
 7: ALTER TABLE public.social_reactions ENABLE ROW LEVEL SECURITY;
 8: ALTER TABLE public.weekly_charge ENABLE ROW LEVEL SECURITY;
 9: 
10: -- 2) athlete_notifications: drop the policy that always evaluates to TRUE
11: --    (it bypassed the correct club-scoped policy for every SELECT), then enable RLS.
12: --    "athlete_notifs" (club_id = get_my_club_id()) already covers legitimate access.
13: DROP POLICY IF EXISTS "athlete can read own notifications" ON public.athlete_notifications;
14: ALTER TABLE public.athlete_notifications ENABLE ROW LEVEL SECURITY;
15: 
16: -- 3) push_subscriptions and athlete_wellness: no policy existed at all — create one
17: --    matching the same convention used everywhere else in this DB, then enable RLS.
18: CREATE POLICY "push_subscriptions_club" ON public.push_subscriptions
19:   FOR ALL TO public
20:   USING (club_id = get_my_club_id());
21: ALTER TABLE public.push_subscriptions ENABLE ROW LEVEL SECURITY;
22: 
23: CREATE POLICY "athlete_wellness_club" ON public.athlete_wellness
24:   FOR ALL TO public
25:   USING (club_id = get_my_club_id());
26: ALTER TABLE public.athlete_wellness ENABLE ROW LEVEL SECURITY;
27: 
28: COMMIT; 1: BEGIN;
 2: 
 3: -- La policy "Club members only" fait un SELECT sur users DEPUIS une policy
 4: -- sur users -> boucle infinie dès que RLS est actif sur cette table.
 5: -- get_my_club_id() est SECURITY DEFINER donc contourne RLS en interne
 6: -- (comme sur athletes/sessions/etc.) -> pas de récursion.
 7: DROP POLICY IF EXISTS "Club members only" ON public.users;
 8: 
 9: CREATE POLICY "users_club" ON public.users
10:   FOR ALL TO public
11:   USING (club_id = get_my_club_id());
12: 
13: COMMIT; 1: BEGIN;
 2: 
 3: -- session-pdfs : ajoute upload/update pour authenticated (nécessaire pour upsert:true,
 4: -- utilisé par AthletePlanning.jsx et Planning.jsx), puis retire l'accès anonyme total
 5: -- (n'importe qui pouvait uploader des fichiers sans être connecté).
 6: CREATE POLICY "authenticated upload session-pdfs" ON storage.objects
 7:   FOR INSERT TO authenticated
 8:   WITH CHECK (bucket_id = 'session-pdfs');
 9: 
10: CREATE POLICY "authenticated update session-pdfs" ON storage.objects
11:   FOR UPDATE TO authenticated
12:   USING (bucket_id = 'session-pdfs');
13: 
14: DROP POLICY IF EXISTS "Public upload access session-pdfs" ON storage.objects;
15: DROP POLICY IF EXISTS "Public read access session-pdfs" ON storage.objects;
16: 
17: -- social-photos : l'upload authentifié et l'update existent déjà et suffisent
18: -- (AthleteClub.jsx uploade toujours via un utilisateur connecté).
19: -- Retire l'upload public ouvert à tous + les 2 policies de lecture publiques
20: -- redondantes (l'app ne fait jamais de .list(), et getPublicUrl() n'a besoin
21: -- d'aucune policy vu que le bucket est déjà public côté fichier).
22: DROP POLICY IF EXISTS "Public upload access social-photos" ON storage.objects;
23: DROP POLICY IF EXISTS "Allow public read access on social-photos" ON storage.objects;
24: DROP POLICY IF EXISTS "public read social photos" ON storage.objects;
25: 
26: COMMIT; 1: BEGIN;
 2: 
 3: -- create_coach_alert : jamais appelée par l'app (les alertes sont insérées
 4: -- directement via .from("alerts").insert(...) dans notifications.js), et
 5: -- accepte p_club_id sans aucune vérification que l'appelant appartient à
 6: -- ce club -> n'importe qui, même non connecté, pouvait forger une fausse
 7: -- alerte dans n'importe quel club via /rest/v1/rpc/create_coach_alert.
 8: REVOKE EXECUTE ON FUNCTION public.create_coach_alert(integer, integer, text, text, text, text) FROM anon, authenticated;
 9: ALTER FUNCTION public.create_coach_alert(integer, integer, text, text, text, text) SET search_path TO 'public';
10: 
11: -- rls_auto_enable : fonction "event trigger" (RETURNS event_trigger),
12: -- invocable uniquement par le mécanisme de trigger lui-même, jamais par
13: -- un appel RPC direct. Aucune raison que anon/authenticated aient EXECUTE.
14: REVOKE EXECUTE ON FUNCTION public.rls_auto_enable() FROM anon, authenticated;
15: 
16: COMMIT;
17: BEGIN;
18: 
19: REVOKE EXECUTE ON FUNCTION public.create_coach_alert(integer, integer, text, text, text, text) FROM PUBLIC;
20: REVOKE EXECUTE ON FUNCTION public.rls_auto_enable() FROM PUBLIC;
21: 
22: COMMIT;1: BEGIN;
2: 
3: -- Colonne additive (nullable, défaut NULL) : permet de distinguer un post
4: -- manuel (photo/légende par un athlète) d'un post auto-généré par l'app
5: -- quand un athlète bat un record ou atteint un objectif — sans ça, le fil
6: -- du club reste vide tant que personne ne partage manuellement une photo.
7: ALTER TABLE public.social_posts ADD COLUMN IF NOT EXISTS auto_type text DEFAULT NULL;
8: 
9: COMMIT; 1: BEGIN;
 2: 
 3: -- Code d'invitation par club — permet à un nouvel athlète de s'inscrire
 4: -- tout seul et d'être rattaché automatiquement au bon club, sans action
 5: -- manuelle du coach. Colonne additive, nullable au départ.
 6: ALTER TABLE public.clubs ADD COLUMN IF NOT EXISTS invite_code text;
 7: CREATE UNIQUE INDEX IF NOT EXISTS clubs_invite_code_idx ON public.clubs (invite_code) WHERE invite_code IS NOT NULL;
 8: 
 9: -- Backfill : les clubs existants (dont le tien) reçoivent un code tout de
10: -- suite, pour pouvoir inviter de nouveaux athlètes sans étape supplémentaire.
11: UPDATE public.clubs
12: SET invite_code = upper(substr(md5(random()::text || id::text), 1, 8))
13: WHERE invite_code IS NULL;
14: 
15: COMMIT; 1: BEGIN;
 2: 
 3: -- service_role (utilisé par TOUTES les Edge Functions via SUPABASE_SERVICE_ROLE_KEY)
 4: -- n'avait de droits CRUD complets que sur 2 des 22 tables (athlete_wellness,
 5: -- push_subscriptions — celles dont les policies RLS ont été réécrites cette
 6: -- session). Sur les 20 autres, service_role n'avait que REFERENCES/TRIGGER/
 7: -- TRUNCATE, sans SELECT/INSERT/UPDATE/DELETE — un GRANT manquant, indépendant
 8: -- des policies RLS. Resté invisible jusqu'ici car aucune fonction serveur
 9: -- n'avait encore besoin d'écrire dans clubs/users/athletes (la nouvelle
10: -- fonction "signup" est la première).
11: GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO service_role;
12: 
13: -- Pour que les tables créées à l'avenir héritent automatiquement des mêmes
14: -- droits, sans devoir y repenser à chaque nouvelle table.
15: ALTER DEFAULT PRIVILEGES IN SCHEMA public
16:   GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO service_role;
17: 
18: COMMIT; 1: BEGIN;
 2: 
 3: -- Les séquences (id SERIAL / BIGSERIAL) sont des objets Postgres séparés des
 4: -- tables — le GRANT précédent sur les tables ne suffit pas pour permettre à
 5: -- service_role d'insérer une ligne dont l'id est auto-généré.
 6: GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public TO service_role;
 7: 
 8: ALTER DEFAULT PRIVILEGES IN SCHEMA public
 9:   GRANT USAGE, SELECT ON SEQUENCES TO service_role;
10: 
11: COMMIT; 1: BEGIN;
 2: 
 3: -- "users_club" (FOR ALL USING club_id = get_my_club_id()) ne vérifiait que
 4: -- l'appartenance au club, jamais "est-ce bien MA ligne" — n'importe quel
 5: -- membre authentifié pouvait donc modifier (voire changer le rôle de)
 6: -- n'importe quel AUTRE membre du même club via un appel direct à l'API,
 7: -- même si aucun écran de l'app ne le permettait dans l'UI. Découvert en
 8: -- construisant les réglages de compte.
 9: DROP POLICY IF EXISTS "users_club" ON public.users;
10: 
11: -- Lecture : tout le club (nécessaire pour messagerie, listes d'athlètes...).
12: CREATE POLICY "users_select_club" ON public.users
13:   FOR SELECT TO public
14:   USING (club_id = get_my_club_id());
15: 
16: -- Écriture : uniquement sa propre ligne.
17: CREATE POLICY "users_update_self" ON public.users
18:   FOR UPDATE TO public
19:   USING (auth_uid = auth.uid()::text)
20:   WITH CHECK (auth_uid = auth.uid()::text);
21: 
22: -- Création : un coach peut inscrire un athlète dans SON club (AthleteList.jsx).
23: CREATE POLICY "users_insert_by_coach" ON public.users
24:   FOR INSERT TO public
25:   WITH CHECK (
26:     club_id = get_my_club_id()
27:     AND EXISTS (
28:       SELECT 1 FROM public.users u
29:       WHERE u.auth_uid = auth.uid()::text AND u.club_id = get_my_club_id() AND u.role IN ('head_coach','coach')
30:     )
31:   );
32: 
33: -- Pas de policy DELETE cliente : la suppression d'un membre (avec son compte
34: -- auth) passe désormais par l'Edge Function admin-actions (service role),
35: -- jamais directement depuis le navigateur.
36: 
37: COMMIT; 1: BEGIN;
 2: 
 3: -- weekly_charge existait comme TABLE (athlete_id, week, raw_load) mais rien
 4: -- dans le code n'y écrivait jamais — vérifié : 0 ligne en base. Le seul
 5: -- lecteur (Competitions.jsx) recevait donc systématiquement une charge vide,
 6: -- alors que tous les autres écrans (Dashboard, AthleteList, Performances,
 7: -- ChargeView, AthleteApp) recalculaient la même chose côté client à partir
 8: -- de sessions + session_athletes, chacun avec sa propre implémentation JS.
 9: --
10: -- Remplacée ici par une VUE qui calcule la charge hebdomadaire directement
11: -- en base, avec la même formule que src/utils/trainingLoad.js
12: -- (computeSessionLoad = round(durée × RPE × coefficient / 10), sommée par
13: -- athlète/semaine, séances sans RPE exclues). Le nom et les colonnes restent
14: -- identiques (athlete_id, week, raw_load) : aucun changement requis côté
15: -- frontend pour Competitions.jsx.
16: --
17: -- ⚠️ Les coefficients ci-dessous DOIVENT rester synchronisés avec
18: -- LOAD_COEFFICIENTS dans athleteos/src/utils/trainingLoad.js. C'est la
19: -- même limite qu'on avait déjà côté JS avant l'unification (#3) : une
20: -- seule table de coefficients, dupliquée une fois côté SQL faute de
21: -- mécanisme partagé JS<->Postgres pour l'instant.
22: --
23: -- security_invoker = true : la vue applique les policies RLS des tables
24: -- sous-jacentes (sessions, session_athletes) pour l'utilisateur courant,
25: -- au lieu de s'exécuter avec les droits du propriétaire de la vue —
26: -- c'est ce qui préserve le cloisonnement par club.
27: 
28: DROP TABLE IF EXISTS public.weekly_charge;
29: 
30: CREATE VIEW public.weekly_charge
31: WITH (security_invoker = true)
32: AS
33: SELECT
34:   sa.athlete_id,
35:   s.week,
36:   ROUND(
37:     SUM(
38:       s.duration_minutes * sa.rpe * (
39:         CASE s.category
40:           WHEN 'force'        THEN 1.3
41:           WHEN 'sprint'       THEN 1.1
42:           WHEN 'haies'        THEN 1.1
43:           WHEN 'lancer'       THEN 1.0
44:           WHEN 'saut'         THEN 1.0
45:           WHEN 'endurance'    THEN 0.9
46:           WHEN 'technique'    THEN 0.7
47:           WHEN 'mobilite'     THEN 0.4
48:           WHEN 'recuperation' THEN 0.3
49:           ELSE 1.0
50:         END
51:       )
52:     ) / 10.0
53:   )::integer AS raw_load
54: FROM public.session_athletes sa
55: JOIN public.sessions s ON s.id = sa.session_id
56: WHERE sa.rpe IS NOT NULL
57:   AND s.duration_minutes IS NOT NULL
58:   AND s.week IS NOT NULL
59: GROUP BY sa.athlete_id, s.week;
60: 
61: GRANT SELECT ON public.weekly_charge TO authenticated;
62: 
63: COMMIT; 1: BEGIN;
 2: 
 3: -- La version initiale de la vue weekly_charge (20260726120000) arrondissait
 4: -- UNE FOIS sur la somme de la semaine (ROUND(SUM(...))). Mais
 5: -- src/utils/trainingLoad.js arrondit PAR SÉANCE (computeSessionLoad) puis
 6: -- somme les charges déjà arrondies (computeWeeklyLoadFromSessions). Les deux
 7: -- ordres d'opération peuvent diverger de ±1 selon les valeurs — exactement
 8: -- le type d'écart client/serveur que la vue est censée éliminer. Corrigé
 9: -- pour arrondir par ligne (par séance-athlète) avant de sommer, comme le JS.
10: 
11: CREATE OR REPLACE VIEW public.weekly_charge
12: WITH (security_invoker = true)
13: AS
14: SELECT
15:   sa.athlete_id,
16:   s.week,
17:   SUM(
18:     ROUND(
19:       s.duration_minutes * sa.rpe * (
20:         CASE s.category
21:           WHEN 'force'        THEN 1.3
22:           WHEN 'sprint'       THEN 1.1
23:           WHEN 'haies'        THEN 1.1
24:           WHEN 'lancer'       THEN 1.0
25:           WHEN 'saut'         THEN 1.0
26:           WHEN 'endurance'    THEN 0.9
27:           WHEN 'technique'    THEN 0.7
28:           WHEN 'mobilite'     THEN 0.4
29:           WHEN 'recuperation' THEN 0.3
30:           ELSE 1.0
31:         END
32:       ) / 10.0
33:     )
34:   )::integer AS raw_load
35: FROM public.session_athletes sa
36: JOIN public.sessions s ON s.id = sa.session_id
37: WHERE sa.rpe IS NOT NULL
38:   AND s.duration_minutes IS NOT NULL
39:   AND s.week IS NOT NULL
40: GROUP BY sa.athlete_id, s.week;
41: 
42: GRANT SELECT ON public.weekly_charge TO authenticated;
43: 
44: COMMIT; 1: BEGIN;
 2: 
 3: -- Détail par épreuve pour les disciplines combinées (Décathlon, Heptathlon) :
 4: -- une performance "Décathlon" reste une ligne unique (discipline + total en
 5: -- points), mais peut maintenant porter en plus le résultat de chaque épreuve
 6: -- individuelle de cette compétition-là, sans créer 10 lignes séparées.
 7: -- Colonne additive, nullable — aucun impact sur les performances existantes
 8: -- ni sur les disciplines simples (breakdown reste NULL pour elles).
 9: ALTER TABLE public.athlete_performances ADD COLUMN IF NOT EXISTS breakdown jsonb DEFAULT NULL;
10: 
11: COMMIT; 1: BEGIN;
 2: 
 3: -- Les policies actuelles sur storage.objects ne vérifient que le bucket_id
 4: -- ("bucket_id = 'social-photos'" etc.) — n'importe quel compte authentifié,
 5: -- de n'importe quel club, peut donc uploader ou écraser un fichier dans le
 6: -- dossier d'un autre club. On restreint désormais l'écriture au premier
 7: -- segment du chemin (storage.foldername(name)[1]), qui doit correspondre
 8: -- au club_id de l'utilisateur connecté (get_my_club_id()).
 9: --
10: -- Ne casse rien de rétroactif : les fichiers déjà uploadés (chemins plats,
11: -- sans préfixe club) restent lisibles tels quels — les buckets sont publics
12: -- en lecture, ce n'est pas ce que ces policies contrôlent. Seules les
13: -- NOUVELLES écritures doivent désormais utiliser le préfixe `${clubId}/...`
14: -- (voir les changements côté client dans AthleteClub.jsx / AthletePlanning.jsx
15: -- / modules/Planning.jsx).
16: 
17: DROP POLICY IF EXISTS "authenticated upload session-pdfs" ON storage.objects;
18: DROP POLICY IF EXISTS "authenticated update session-pdfs" ON storage.objects;
19: DROP POLICY IF EXISTS "Allow authenticated users to update photos" ON storage.objects;
20: DROP POLICY IF EXISTS "authenticated upload social photos" ON storage.objects;
21: 
22: CREATE POLICY "club-scoped upload session-pdfs" ON storage.objects
23:   FOR INSERT TO authenticated
24:   WITH CHECK (
25:     bucket_id = 'session-pdfs'
26:     AND (storage.foldername(name))[1] = get_my_club_id()::text
27:   );
28: 
29: CREATE POLICY "club-scoped update session-pdfs" ON storage.objects
30:   FOR UPDATE TO authenticated
31:   USING (
32:     bucket_id = 'session-pdfs'
33:     AND (storage.foldername(name))[1] = get_my_club_id()::text
34:   );
35: 
36: CREATE POLICY "club-scoped upload social-photos" ON storage.objects
37:   FOR INSERT TO authenticated
38:   WITH CHECK (
39:     bucket_id = 'social-photos'
40:     AND (storage.foldername(name))[1] = get_my_club_id()::text
41:   );
42: 
43: CREATE POLICY "club-scoped update social-photos" ON storage.objects
44:   FOR UPDATE TO authenticated
45:   USING (
46:     bucket_id = 'social-photos'
47:     AND (storage.foldername(name))[1] = get_my_club_id()::text
48:   );
49: 
50: COMMIT; 1: BEGIN;
 2: 
 3: -- Cron serveur réel pour les notifs hebdo (récap + rapports) — avant ça,
 4: -- checkWeeklyRecap()/checkWeeklyReports() (src/utils/notifications.js)
 5: -- n'étaient déclenchés QUE quand quelqu'un ouvrait l'app dans la bonne
 6: -- fenêtre horaire. Un dimanche soir sans personne connectée = rien
 7: -- n'était envoyé. Ici, pg_cron appelle chaque semaine la fonction edge
 8: -- weekly-cron, qui réimplémente la même logique côté serveur (mêmes
 9: -- tables, même format de titre pour le dédoublonnage — les deux chemins
10: -- restent mutuellement idempotents).
11: 
12: CREATE EXTENSION IF NOT EXISTS pg_cron;
13: CREATE EXTENSION IF NOT EXISTS pg_net;
14: 
15: -- La clé d'authentification (secret key du nouveau système Supabase) est
16: -- stockée dans Vault, jamais en clair dans une migration versionnée —
17: -- voir vault.create_secret('...', 'weekly_cron_service_role_key', ...)
18: -- exécuté une fois manuellement (hors migration) lors de la mise en place.
19: 
20: SELECT cron.schedule(
21:   'weekly-notifications',
22:   '30 18 * * 0',  -- dimanche 18h30 UTC (~19h30-20h30 heure belge selon saison)
23:   $job$
24:   SELECT net.http_post(
25:     url := 'https://kuqafsmkwajeipzolbky.supabase.co/functions/v1/weekly-cron',
26:     headers := jsonb_build_object(
27:       'Content-Type', 'application/json',
28:       'Authorization', 'Bearer ' || (
29:         SELECT decrypted_secret FROM vault.decrypted_secrets
30:         WHERE name = 'weekly_cron_service_role_key'
31:       )
32:     ),
33:     body := '{}'::jsonb
34:   );
35:   $job$
36: );
37: 
38: COMMIT; 1: BEGIN;
 2: 
 3: -- ============================================================
 4: -- Tâche 3 — durcissement de l'inscription publique (signup)
 5: -- ============================================================
 6: 
 7: -- 1) Rate limiting : une ligne par tentative d'inscription (IP + email
 8: --    normalisé), consultée par fenêtre glissante depuis l'Edge Function
 9: --    signup. Jamais accédée depuis le client — RLS activée, aucune policy
10: --    (service_role bypass RLS de toute façon ; ceinture + bretelles si un
11: --    jour cette table était exposée par erreur via l'API REST).
12: CREATE TABLE IF NOT EXISTS public.signup_attempts (
13:   id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
14:   ip text NOT NULL,
15:   email text,
16:   created_at timestamptz NOT NULL DEFAULT now()
17: );
18: CREATE INDEX IF NOT EXISTS signup_attempts_ip_idx ON public.signup_attempts (ip, created_at);
19: CREATE INDEX IF NOT EXISTS signup_attempts_email_idx ON public.signup_attempts (email, created_at);
20: ALTER TABLE public.signup_attempts ENABLE ROW LEVEL SECURITY;
21: 
22: -- 2) Création atomique club + users + athletes en une seule transaction SQL.
23: --    L'API Auth (auth.admin.createUser) ne peut pas participer à cette
24: --    transaction (c'est un appel HTTP séparé, pas du SQL) — elle reste gérée
25: --    par l'Edge Function, avec compensation (suppression du compte Auth) si
26: --    cet appel RPC échoue après coup. Mais club+users+athletes, eux, sont
27: --    tout-ou-rien : plus de club orphelin sans coach, plus de ligne users
28: --    orpheline sans sa ligne athletes (bug présent dans l'ancienne version :
29: --    un échec sur l'insert athletes ne nettoyait jamais la ligne users déjà
30: --    créée juste avant).
31: CREATE OR REPLACE FUNCTION public.signup_create_account(
32:   p_mode text,
33:   p_club_name text,
34:   p_invite_code text,
35:   p_auth_uid text,
36:   p_name text,
37:   p_email text
38: ) RETURNS jsonb
39: LANGUAGE plpgsql
40: SECURITY DEFINER
41: SET search_path = public
42: AS $$
43: DECLARE
44:   v_club_id bigint;
45:   v_user_id bigint;
46:   v_role text;
47: BEGIN
48:   IF p_mode = 'create_club' THEN
49:     INSERT INTO clubs (name, invite_code) VALUES (p_club_name, p_invite_code) RETURNING id INTO v_club_id;
50:     v_role := 'head_coach';
51:   ELSIF p_mode = 'join_club' THEN
52:     SELECT id INTO v_club_id FROM clubs WHERE invite_code = p_invite_code;
53:     IF v_club_id IS NULL THEN
54:       RAISE EXCEPTION 'invalid_invite_code';
55:     END IF;
56:     v_role := 'athlete';
57:   ELSE
58:     RAISE EXCEPTION 'invalid_mode';
59:   END IF;
60: 
61:   INSERT INTO users (auth_uid, name, email, role, club_id)
62:   VALUES (p_auth_uid, p_name, p_email, v_role, v_club_id)
63:   RETURNING id INTO v_user_id;
64: 
65:   IF p_mode = 'join_club' THEN
66:     INSERT INTO athletes (club_id, name, user_id) VALUES (v_club_id, p_name, v_user_id);
67:   END IF;
68: 
69:   RETURN jsonb_build_object('clubId', v_club_id, 'userId', v_user_id);
70: END;
71: $$;
72: 
73: REVOKE ALL ON FUNCTION public.signup_create_account(text, text, text, text, text, text) FROM PUBLIC;
74: GRANT EXECUTE ON FUNCTION public.signup_create_account(text, text, text, text, text, text) TO service_role;
75: 
76: COMMIT;  1: BEGIN;
  2: 
  3: -- ============================================================
  4: -- Tâche 16 — unifier et versionner les coefficients de charge
  5: --
  6: -- Problème (déjà signalé en commentaire dans les migrations précédentes,
  7: -- 20260726120000/123000) : les coefficients de charge par catégorie
  8: -- (LOAD_COEFFICIENTS) sont dupliqués en dur à deux endroits — le module JS
  9: -- trainingLoad.js et la vue SQL weekly_charge — sans aucun mécanisme pour
 10: -- les garder synchronisés, et sans aucune notion de version : la vue
 11: -- recalcule TOUJOURS avec les coefficients actuels, donc les changer aurait
 12: -- silencieusement modifié l'historique de TOUTES les semaines passées.
 13: --
 14: -- Solution : une table canonique versionnée (charge_model_versions), et
 15: -- chaque ligne session_athletes qui reçoit un RPE est timbrée avec la
 16: -- version active AU MOMENT de la saisie (trigger, pas le code applicatif —
 17: -- ne peut pas être oublié dans un futur écran d'écriture). La vue
 18: -- weekly_charge calcule désormais chaque ligne avec LA VERSION DE CETTE
 19: -- LIGNE, jamais "la version actuelle" : changer la version active à
 20: -- l'avenir n'altère plus les charges déjà calculées.
 21: -- ============================================================
 22: 
 23: -- 1) Table canonique versionnée des coefficients (convention de coaching
 24: --    AthleteOS, pas des valeurs publiées — voir trainingLoad.js).
 25: CREATE TABLE public.charge_model_versions (
 26:   version           text PRIMARY KEY,
 27:   load_coefficients jsonb NOT NULL,
 28:   recovery_hours    jsonb NOT NULL,
 29:   is_active         boolean NOT NULL DEFAULT false,
 30:   notes             text,
 31:   created_at        timestamptz NOT NULL DEFAULT now(),
 32:   created_by        text  -- users.id (texte pour rester cohérent avec le reste du schéma) de l'auteur du changement, une fois qu'un écran d'édition existera. NULL pour les versions créées hors app (migration, admin DB).
 33: );
 34: 
 35: -- Une seule version active à la fois — le trigger de session_athletes (plus
 36: -- bas) suppose qu'il en existe au plus une.
 37: CREATE UNIQUE INDEX charge_model_versions_single_active
 38:   ON public.charge_model_versions (is_active)
 39:   WHERE is_active;
 40: 
 41: ALTER TABLE public.charge_model_versions ENABLE ROW LEVEL SECURITY;
 42: CREATE POLICY "charge_model_versions_read" ON public.charge_model_versions
 43:   FOR SELECT TO authenticated USING (true);
 44: GRANT SELECT ON public.charge_model_versions TO authenticated;
 45: -- Pas de policy d'écriture pour authenticated : tant qu'aucun écran coach ne
 46: -- permet de créer une version, seule une action directe en base (dashboard/
 47: -- service_role) peut le faire — "configuration coach uniquement dans des
 48: -- bornes" nécessite un écran dédié, hors périmètre de cette tâche (voir
 49: -- status.md). Le contrôle des bornes ci-dessous s'applique déjà à ce
 50: -- chemin, prêt pour quand cet écran existera.
 51: 
 52: -- 2) Bornes : une valeur de coefficient ou de récupération manifestement
 53: --    aberrante (ex: coefficient 50, récupération de 0h ou 10000h) ne doit
 54: --    jamais pouvoir être enregistrée, qui que ce soit qui écrive la ligne.
 55: CREATE OR REPLACE FUNCTION public.validate_charge_model_version()
 56: RETURNS trigger
 57: LANGUAGE plpgsql
 58: AS $$
 59: DECLARE
 60:   k text;
 61:   v jsonb;
 62:   n numeric;
 63: BEGIN
 64:   FOR k, v IN SELECT * FROM jsonb_each(NEW.load_coefficients) LOOP
 65:     IF jsonb_typeof(v) <> 'number' THEN
 66:       RAISE EXCEPTION 'load_coefficients.% doit être un nombre (reçu: %)', k, v;
 67:     END IF;
 68:     n := (v#>>'{}')::numeric;
 69:     IF n < 0.1 OR n > 3.0 THEN
 70:       RAISE EXCEPTION 'load_coefficients.% doit être entre 0.1 et 3.0 (reçu: %)', k, n;
 71:     END IF;
 72:   END LOOP;
 73: 
 74:   FOR k, v IN SELECT * FROM jsonb_each(NEW.recovery_hours) LOOP
 75:     IF jsonb_typeof(v) <> 'number' THEN
 76:       RAISE EXCEPTION 'recovery_hours.% doit être un nombre (reçu: %)', k, v;
 77:     END IF;
 78:     n := (v#>>'{}')::numeric;
 79:     IF n < 1 OR n > 168 THEN
 80:       RAISE EXCEPTION 'recovery_hours.% doit être entre 1 et 168 heures (reçu: %)', k, n;
 81:     END IF;
 82:   END LOOP;
 83: 
 84:   RETURN NEW;
 85: END;
 86: $$;
 87: 
 88: CREATE TRIGGER charge_model_versions_validate
 89:   BEFORE INSERT OR UPDATE ON public.charge_model_versions
 90:   FOR EACH ROW EXECUTE FUNCTION public.validate_charge_model_version();
 91: 
 92: -- 3) Version initiale — valeurs IDENTIQUES à celles déjà en dur dans
 93: --    trainingLoad.js et l'ancienne vue weekly_charge : ce n'est pas un
 94: --    changement de modèle, seulement le fait de lui donner un nom et de le
 95: --    rendre canonique. Aucun score existant ne change de valeur.
 96: INSERT INTO public.charge_model_versions (version, load_coefficients, recovery_hours, is_active, notes)
 97: VALUES (
 98:   'v1',
 99:   '{"force":1.3,"sprint":1.1,"haies":1.1,"lancer":1.0,"saut":1.0,"endurance":0.9,"technique":0.7,"mobilite":0.4,"recuperation":0.3}'::jsonb,
100:   '{"sprint":72,"haies":72,"force":72,"saut":48,"lancer":48,"endurance":36,"technique":24,"mobilite":12,"recuperation":12}'::jsonb,
101:   true,
102:   'Version initiale — reprend telle quelle LOAD_COEFFICIENTS/RECOVERY_HOURS de trainingLoad.js (déjà en prod). Conventions de coaching AthleteOS, pas des valeurs publiées.'
103: );
104: 
105: -- 4) Chaque ligne session_athletes connaît désormais la version utilisée
106: --    pour calculer sa charge.
107: ALTER TABLE public.session_athletes
108:   ADD COLUMN model_version text REFERENCES public.charge_model_versions(version);
109: 
110: -- Backfill : toutes les lignes RPE déjà saisies ont été calculées avec les
111: -- coefficients qui sont exactement ceux de 'v1' (voir point 3) — ce n'est
112: -- donc pas un recalcul silencieux, juste nommer ce qui était déjà vrai.
113: UPDATE public.session_athletes SET model_version = 'v1' WHERE rpe IS NOT NULL AND model_version IS NULL;
114: 
115: -- 5) Timbre automatique : dès qu'un RPE est saisi ou modifié, la ligne est
116: --    associée à LA VERSION ACTIVE AU MOMENT DE LA SAISIE — pas recalculée
117: --    plus tard si la version active change. Trigger plutôt que code
118: --    applicatif : ne peut pas être oublié dans un futur écran d'écriture
119: --    (aujourd'hui déjà 2 chemins : AthleteApp.jsx et Planning.jsx).
120: CREATE OR REPLACE FUNCTION public.stamp_session_athlete_model_version()
121: RETURNS trigger
122: LANGUAGE plpgsql
123: AS $$
124: BEGIN
125:   IF NEW.rpe IS NOT NULL AND (TG_OP = 'INSERT' OR NEW.rpe IS DISTINCT FROM OLD.rpe) THEN
126:     SELECT version INTO NEW.model_version FROM public.charge_model_versions WHERE is_active LIMIT 1;
127:   END IF;
128:   RETURN NEW;
129: END;
130: $$;
131: 
132: CREATE TRIGGER session_athletes_stamp_model_version
133:   BEFORE INSERT OR UPDATE ON public.session_athletes
134:   FOR EACH ROW EXECUTE FUNCTION public.stamp_session_athlete_model_version();
135: 
136: -- 6) weekly_charge recalcule maintenant CHAQUE LIGNE avec SA PROPRE version
137: --    (jointure sur session_athletes.model_version), plus jamais avec "la"
138: --    version actuelle codée en dur. C'est le changement central : une
139: --    nouvelle version active à l'avenir ne change plus l'historique.
140: --    COALESCE(...,1.0) préserve le comportement de secours de l'ancienne
141: --    vue (catégorie inconnue -> coefficient 1.0).
142: CREATE OR REPLACE VIEW public.weekly_charge
143: WITH (security_invoker = true)
144: AS
145: SELECT
146:   sa.athlete_id,
147:   s.week,
148:   SUM(
149:     ROUND(
150:       s.duration_minutes * sa.rpe *
151:       COALESCE((cmv.load_coefficients ->> s.category)::numeric, 1.0)
152:       / 10.0
153:     )
154:   )::integer AS raw_load
155: FROM public.session_athletes sa
156: JOIN public.sessions s ON s.id = sa.session_id
157: LEFT JOIN public.charge_model_versions cmv ON cmv.version = sa.model_version
158: WHERE sa.rpe IS NOT NULL
159:   AND s.duration_minutes IS NOT NULL
160:   AND s.week IS NOT NULL
161: GROUP BY sa.athlete_id, s.week;
162: 
163: GRANT SELECT ON public.weekly_charge TO authenticated;
164: 
