  2: // ============================================================
  3: // AthleteOS — test_send_push_regression.mjs
  4: //
  5: // Vérifie l'autorisation de l'Edge Function send-push (tâche 2) :
  6: //   - un appel sans authentification est refusé (401)
  7: //   - un athlète ne peut pas cibler un athlète d'un autre club (403)
  8: //   - un athlète PEUT cibler lui-même, un coéquipier de son club, ou le
  9: //     coach de son club (200) — cas réels : auto-notif récap hebdo,
 10: //     messagerie inter-athlètes, post club, message au coach
 11: //   - un athlète ne peut pas cibler un user non-coach par userIds (403)
 12: //   - un coach du club A ne peut pas cibler un athlète du club B (403)
 13: //   - un coach du club A peut cibler ses propres athlètes (200)
 14: //   - un payload surdimensionné est refusé (400/413)
 15: //   - une origine navigateur non autorisée est refusée (403, CORS)
 16: //   - le chemin cron (secret service_role) fonctionne toujours (200)
 17: //
 18: // Crée deux clubs + un coach + un athlète (avec compte de connexion) +
 19: // un athlète cible dans l'autre club, appelle la fonction déployée en
 20: // HTTP direct (comme le fait weekly-cron), puis nettoie tout.
 21: //
 22: // Prérequis : la fonction send-push doit être déployée sur le projet
 23: // Supabase ciblé par VITE_SUPABASE_URL (ce script ne déploie rien).
 24: //
 25: // Usage :
 26: //   SUPABASE_SERVICE_ROLE_KEY=... node test_send_push_regression.mjs
 27: //
 28: // Requiert dans l'environnement (ou .env à la racine du dossier) :
 29: //   VITE_SUPABASE_URL, VITE_SUPABASE_ANON_KEY  (déjà dans .env)
 30: //   SUPABASE_SERVICE_ROLE_KEY                  (secret, jamais committé —
 31: //                                                variable d'env locale ou
 32: //                                                secret CI)
 33: // ============================================================
 34: 
 35: import { createClient } from "@supabase/supabase-js";
 36: import { readFileSync } from "node:fs";
 37: import { fileURLToPath } from "node:url";
 38: import path from "node:path";
 39: 
 40: function loadDotEnv(filePath) {
 41:   let text;
 42:   try { text = readFileSync(filePath, "utf8"); } catch { return; }
 43:   for (const rawLine of text.split("\n")) {
 44:     const line = rawLine.replace(/\r$/, "");
 45:     const m = line.match(/^([A-Z0-9_]+)=(.*)$/);
 46:     if (m && process.env[m[1]] === undefined) process.env[m[1]] = m[2].trim();
 47:   }
 48: }
 49: loadDotEnv(path.join(path.dirname(fileURLToPath(import.meta.url)), ".env"));
 50: 
 51: const SUPABASE_URL    = process.env.VITE_SUPABASE_URL;
 52: const ANON_KEY        = process.env.VITE_SUPABASE_ANON_KEY;
 53: const SERVICE_ROLE_KEY = process.env.SUPABASE_SERVICE_ROLE_KEY;
 54: 
 55: if (!SUPABASE_URL || !ANON_KEY || !SERVICE_ROLE_KEY) {
 56:   console.error(
 57:     "Variables manquantes. Requis : VITE_SUPABASE_URL, VITE_SUPABASE_ANON_KEY " +
 58:     "(dans .env) et SUPABASE_SERVICE_ROLE_KEY (variable d'environnement, jamais committée)."
 59:   );
 60:   process.exit(1);
 61: }
 62: 
 63: const FUNCTION_URL = `${SUPABASE_URL}/functions/v1/send-push`;
 64: 
 65: const admin = createClient(SUPABASE_URL, SERVICE_ROLE_KEY, {
 66:   auth: { autoRefreshToken: false, persistSession: false },
 67: });
 68: 
 69: const RUN_ID = Date.now();
 70: const results = [];
 71: function record(name, pass, detail) {
 72:   results.push({ name, pass, detail });
 73:   console.log(`${pass ? "✅" : "❌"} ${name}${detail ? " — " + detail : ""}`);
 74: }
 75: 
 76: async function insertOrThrow(table, row) {
 77:   const { data, error } = await admin.from(table).insert(row).select().single();
 78:   if (error) throw new Error(`seed ${table} : ${error.message}`);
 79:   return data;
 80: }
 81: 
 82: async function getAccessToken(email, password) {
 83:   const client = createClient(SUPABASE_URL, ANON_KEY, { auth: { autoRefreshToken: false, persistSession: false } });
 84:   const { data, error } = await client.auth.signInWithPassword({ email, password });
 85:   if (error) throw new Error(`signIn ${email} : ${error.message}`);
 86:   return { token: data.session.access_token, client };
 87: }
 88: 
 89: async function callSendPush(token, payload) {
 90:   const headers = { "Content-Type": "application/json", apikey: ANON_KEY };
 91:   if (token) headers.Authorization = `Bearer ${token}`;
 92:   const res = await fetch(FUNCTION_URL, { method: "POST", headers, body: JSON.stringify(payload) });
 93:   let body = null;
 94:   try { body = await res.json(); } catch { /* pas de corps JSON */ }
 95:   return { status: res.status, body };
 96: }
 97: 
 98: async function main() {
 99:   let clubA, clubB, coachAuth, athleteAuth, coachUser, athleteUser, athleteA, athleteB, athleteC;
100:   let coachAClient, athleteAClient;
101: 
102:   try {
103:     // ── Setup : deux clubs, un coach + un athlète (club A), un athlète cible (club B) ──
104:     clubA = await insertOrThrow("clubs", { name: `SendPush Test Club A ${RUN_ID}` });
105:     clubB = await insertOrThrow("clubs", { name: `SendPush Test Club B ${RUN_ID}` });
106: 
107:     const coachEmail   = `send-push-test-coach-${RUN_ID}@example.invalid`;
108:     const athleteEmail = `send-push-test-athlete-${RUN_ID}@example.invalid`;
109:     const password = `SendPush-Test-${RUN_ID}-Aa!`;
110: 
111:     const { data: ca, error: caErr } = await admin.auth.admin.createUser({ email: coachEmail, password, email_confirm: true });
112:     if (caErr) throw new Error(`createUser coach : ${caErr.message}`);
113:     coachAuth = ca.user;
114:     const { data: aa, error: aaErr } = await admin.auth.admin.createUser({ email: athleteEmail, password, email_confirm: true });
115:     if (aaErr) throw new Error(`createUser athlete : ${aaErr.message}`);
116:     athleteAuth = aa.user;
117: 
118:     coachUser = await insertOrThrow("users", { club_id: clubA.id, name: "Coach (test send-push)", email: coachEmail, role: "head_coach", auth_uid: coachAuth.id });
119:     athleteUser = await insertOrThrow("users", { club_id: clubA.id, name: "Athlete (test send-push)", email: athleteEmail, role: "athlete", auth_uid: athleteAuth.id });
120: 
121:     athleteA = await insertOrThrow("athletes", { club_id: clubA.id, name: "Athlete A (test send-push)", user_id: athleteUser.id });
122:     athleteB = await insertOrThrow("athletes", { club_id: clubB.id, name: "Athlete B (test send-push)" });
123:     // Coéquipier d'athleteA, même club — cible légitime pour la messagerie
124:     // inter-athlètes et le post club (notifyClubNewPost/notifyAthleteMessage).
125:     athleteC = await insertOrThrow("athletes", { club_id: clubA.id, name: "Athlete C, teammate (test send-push)" });
126: 
127:     // Abonnement factice pour athleteA — l'envoi web-push échouera (endpoint
128:     // invalide) mais ça n'affecte pas le code HTTP retourné par la fonction
129:     // (Promise.allSettled avale l'échec individuel), donc suffisant pour
130:     // vérifier l'autorisation sans dépendre d'un vrai navigateur.
131:     await insertOrThrow("push_subscriptions", {
132:       club_id: clubA.id, athlete_id: athleteA.id,
133:       endpoint: `https://example.invalid/push/${RUN_ID}`, p256dh: "x", auth: "y",
134:     });
135: 
136:     const coachSession   = await getAccessToken(coachEmail, password);
137:     const athleteSession = await getAccessToken(athleteEmail, password);
138:     coachAClient   = coachSession.client;
139:     athleteAClient = athleteSession.client;
140:     const coachToken   = coachSession.token;
141:     const athleteToken = athleteSession.token;
142: 
143:     const basePayload = { title: "Test send-push", body: "Vérification autorisation." };
144: 
145:     // ── 1. Appel sans authentification -> 401 ────────────────────────
146:     {
147:       const { status } = await callSendPush(null, { ...basePayload, athleteIds: [athleteA.id] });
148:       record("Appel sans auth -> 401", status === 401, `status=${status}`);
149:     }
150: 
151:     // ── 2. Athlète tentant un envoi arbitraire (athleteIds hors club) -> 403 ──
152:     {
153:       const { status } = await callSendPush(athleteToken, { ...basePayload, athleteIds: [athleteB.id] });
154:       record("Athlète envoi arbitraire (athlète club B) -> 403", status === 403, `status=${status}`);
155:     }
156: 
157:     // ── 2bis. Cas légitimes : athlète vers lui-même / vers un coéquipier (même club) -> succès ──
158:     // (auto-notif de récap hebdo, messagerie inter-athlètes, post club — voir
159:     // src/AthleteApp.jsx, src/athlete/views/AthleteMsgerie.jsx et AthleteClub.jsx)
160:     {
161:       const { status } = await callSendPush(athleteToken, { ...basePayload, athleteIds: [athleteA.id] });
162:       record("Athlète -> lui-même (même club) -> 200", status === 200, `status=${status}`);
163:     }
164:     {
165:       const { status } = await callSendPush(athleteToken, { ...basePayload, athleteIds: [athleteC.id] });
166:       record("Athlète -> coéquipier (même club) -> 200", status === 200, `status=${status}`);
167:     }
168:     {
169:       const { status } = await callSendPush(athleteToken, { ...basePayload, userIds: [coachUser.id] });
170:       record("Athlète -> coach de son club (userIds) -> 200", status === 200, `status=${status}`);
171:     }
172:     {
173:       const { status } = await callSendPush(athleteToken, { ...basePayload, userIds: [athleteUser.id] });
174:       record("Athlète -> userIds d'un non-coach -> 403", status === 403, `status=${status}`);
175:     }
176: 
177:     // ── 3. Coach club A ciblant un athlète du club B -> 403 ──────────
178:     {
179:       const { status } = await callSendPush(coachToken, { ...basePayload, athleteIds: [athleteB.id] });
180:       record("Coach club A -> athlète club B -> 403", status === 403, `status=${status}`);
181:     }
182: 
183:     // ── 4. Coach club A ciblant ses propres athlètes -> succès ───────
184:     {
185:       const { status } = await callSendPush(coachToken, { ...basePayload, athleteIds: [athleteA.id] });
186:       record("Coach club A -> son athlète -> 200", status === 200, `status=${status}`);
187:     }
188: 
189:     // ── 5. Payload surdimensionné -> 400/413 ──────────────────────────
190:     {
191:       const { status } = await callSendPush(coachToken, {
192:         ...basePayload, athleteIds: [athleteA.id], title: "x".repeat(50_000),
193:       });
194:       record("Payload surdimensionné -> 400/413", status === 400 || status === 413, `status=${status}`);
195:     }
196: 
197:     // ── Bonus : chemin cron (secret service_role) toujours fonctionnel ──
198:     {
199:       const res = await fetch(FUNCTION_URL, {
200:         method: "POST",
201:         headers: { "Content-Type": "application/json", apikey: ANON_KEY, Authorization: `Bearer ${SERVICE_ROLE_KEY}` },
202:         body: JSON.stringify({ ...basePayload, athleteIds: [athleteA.id] }),
203:       });
204:       record("Cron (Bearer service_role) -> 200", res.status === 200, `status=${res.status}`);
205:     }
206: 
207:     // ── Bonus : origine navigateur non autorisée -> 403 (CORS) ──────
208:     {
209:       const res = await fetch(FUNCTION_URL, {
210:         method: "POST",
211:         headers: {
212:           "Content-Type": "application/json", apikey: ANON_KEY,
213:           Authorization: `Bearer ${coachToken}`, Origin: "https://evil-untrusted-origin.example",
214:         },
215:         body: JSON.stringify({ ...basePayload, athleteIds: [athleteA.id] }),
216:       });
217:       record("Origine non autorisée -> 403", res.status === 403, `status=${res.status}`);
218:     }
219: 
220:   } finally {
221:     console.log("\nNettoyage...");
222:     if (coachAClient)   await coachAClient.auth.signOut().catch(() => {});
223:     if (athleteAClient) await athleteAClient.auth.signOut().catch(() => {});
224:     // Cascade FK sur athlete_id : nettoie push_subscriptions automatiquement.
225:     if (athleteA)    await admin.from("athletes").delete().eq("id", athleteA.id);
226:     if (athleteB)    await admin.from("athletes").delete().eq("id", athleteB.id);
227:     if (athleteC)    await admin.from("athletes").delete().eq("id", athleteC.id);
228:     if (coachUser)   await admin.from("users").delete().eq("id", coachUser.id);
229:     if (athleteUser) await admin.from("users").delete().eq("id", athleteUser.id);
230:     if (coachAuth)   await admin.auth.admin.deleteUser(coachAuth.id).catch(() => {});
231:     if (athleteAuth) await admin.auth.admin.deleteUser(athleteAuth.id).catch(() => {});
232:     if (clubA)       await admin.from("clubs").delete().eq("id", clubA.id);
233:     if (clubB)       await admin.from("clubs").delete().eq("id", clubB.id);
234:   }
235: 
236:   const failed = results.filter((r) => !r.pass);
237:   console.log(`\n${results.length - failed.length}/${results.length} vérifications OK`);
238:   if (failed.length) {
239:     console.error(`\n${failed.length} régression(s) send-push détectée(s) :`);
240:     failed.forEach((f) => console.error(`  - ${f.name}${f.detail ? " : " + f.detail : ""}`));
241:     process.exit(1);
242:   }
243:   console.log("\nAucune fuite d'autorisation détectée sur send-push.");
244:   process.exit(0);
245: }
246: 
247: main().catch((err) => {
248:   console.error("Erreur fatale :", err.message ?? err);
249:   process.exit(1);
