 2: 
 3: // Paire P-256 éphémère, exclusivement destinée à l'instance Supabase
 4: // jetable du pipeline. Rien n'est enregistré et aucune clé de production
 5: // n'est lue.
 6: const { publicKey, privateKey } = generateKeyPairSync("ec", {
 7:   namedCurve: "prime256v1",
 8: });
 9: 
10: const publicJwk = publicKey.export({ format: "jwk" });
11: const privateJwk = privateKey.export({ format: "jwk" });
12: 
13: if (!publicJwk.x || !publicJwk.y || !privateJwk.d) {
14:   throw new Error("Impossible de générer la paire VAPID de test.");
15: }
16: 
17: const publicBytes = Buffer.concat([
18:   Buffer.from([0x04]),
19:   Buffer.from(publicJwk.x, "base64url"),
20:   Buffer.from(publicJwk.y, "base64url"),
21: ]);
22: 
23: console.log(`VAPID_PUBLIC_KEY=${publicBytes.toString("base64url")}`);
24: console.log(`VAPID_PRIVATE_KEY=${privateJwk.d}`); 1: #!/usr/bin/env bash
 2: 
 3: # Exécute une commande de CI sans masquer son code de sortie et publie ses
 4: # dernières lignes dans une annotation GitHub en cas d'échec. Cela permet de
 5: # diagnostiquer les tests d'intégration sans rendre les journaux du job publics.
 6: set -uo pipefail
 7: 
 8: label=$1
 9: shift
10: log_file="${RUNNER_TEMP:-/tmp}/athleteos-${label}.log"
11: 
12: set +e
13: "$@" 2>&1 | tee "$log_file"
14: command_status=${PIPESTATUS[0]}
15: set -e
16: 
17: if [ "$command_status" -ne 0 ]; then
18:   {
19:     echo "### Échec : $label"
20:     echo '```text'
21:     tail -n 80 "$log_file"
22:     echo '```'
23:   } >> "${GITHUB_STEP_SUMMARY:-/dev/null}"
24: 
25:   diagnostic=$(tail -n 60 "$log_file")
26:   diagnostic=${diagnostic//'%'/'%25'}
27:   diagnostic=${diagnostic//$'\r'/'%0D'}
28:   diagnostic=${diagnostic//$'\n'/'%0A'}
29:   echo "::error title=Échec ${label}::$diagnostic"
30: fi
31: 
32: exit "$command_status" 1: # Preuves visuelles de l’audit
