 32: export function buildAthleteConversations(messages, contacts, currentUserId) {
 33:   const contactsByUserId = new Map(
 34:     contacts.filter(contact => contact.userId != null).map(contact => [contact.userId, contact])
 35:   );
 36:   const conversations = new Map(
 37:     contacts.filter(contact => contact.userId != null).map(contact => [contact.id, {
 38:       contactId: contact.id,
 39:       messages: [],
 40:       unread: 0,
 41:       lastMsg: null,
 42:     }])
 43:   );
 44: 
 45:   messages.forEach(message => {
 46:     if (message.senderId !== currentUserId && message.receiverId !== currentUserId) return;
 47:     const otherUserId = message.senderId === currentUserId ? message.receiverId : message.senderId;
 48:     const contact = contactsByUserId.get(otherUserId);
 49:     const conversation = contact ? conversations.get(contact.id) : null;
 50:     if (!conversation) return;
 51:     conversation.messages.push(message);
 52:     if (message.senderId === contact.userId && !message.isRead) conversation.unread += 1;
 53:   });
 54: 
 55:   conversations.forEach(conversation => {
 56:     conversation.messages.sort((a, b) => new Date(a.date) - new Date(b.date));
 57:     conversation.lastMsg = conversation.messages.at(-1) ?? null;
 58:   });
 59: 
 60:   return [...conversations.values()].sort((a, b) => {
 61:     if (!a.lastMsg && !b.lastMsg) return 0;
 62:     if (!a.lastMsg) return 1;
 63:     if (!b.lastMsg) return -1;
 64:     return new Date(b.lastMsg.date) - new Date(a.lastMsg.date);
 65:   });
 66: }
