 68: function normalizeSearch(value) {
 69:   return String(value ?? "")
 70:     .normalize("NFD")
 71:     .replace(/[\u0300-\u036f]/g, "")
 72:     .toLowerCase();
 73: }
 74: 
 75: export function filterAthleteConversations(conversations, contacts, filter, search) {
 76:   const contactsById = new Map(contacts.map(contact => [contact.id, contact]));
 77:   const query = normalizeSearch(search).trim();
 78: 
 79:   return conversations.filter(conversation => {
 80:     const contact = contactsById.get(conversation.contactId);
 81:     if (!contact) return false;
 82:     if (filter === "coaches" && contact.type !== "coach") return false;
 83:     if (filter === "athletes" && contact.type !== "athlete") return false;
 84:     if (filter === "unread" && conversation.unread === 0) return false;
 85:     if (!query) return true;
 86:     return normalizeSearch(contact.name).includes(query)
 87:       || conversation.messages.some(message => normalizeSearch(message.content).includes(query));
 88:   });
 89: }
