 91: function localDayKey(dateValue) {
 92:   const date = new Date(dateValue);
 93:   return `${date.getFullYear()}-${date.getMonth()}-${date.getDate()}`;
 94: }
 95: 
 96: export function groupMessagesByDay(messages) {
 97:   return messages.reduce((groups, message) => {
 98:     const key = localDayKey(message.date);
 99:     const lastGroup = groups.at(-1);
100:     if (lastGroup?.key === key) {
101:       lastGroup.messages.push(message);
102:     } else {
103:       groups.push({ key, date: message.date, messages: [message] });
104:     }
105:     return groups;
106:   }, []);
107: }
