109: export function formatMessageTime(dateValue) {
110:   return new Date(dateValue).toLocaleTimeString("fr-BE", { hour: "2-digit", minute: "2-digit" });
111: }
112: 
113: export function formatConversationTime(dateValue, now = new Date()) {
114:   const date = new Date(dateValue);
115:   if (localDayKey(date) === localDayKey(now)) return formatMessageTime(date);
116:   const dayDifference = Math.floor((new Date(now.getFullYear(), now.getMonth(), now.getDate()) - new Date(date.getFullYear(), date.getMonth(), date.getDate())) / 86400000);
117:   if (dayDifference > 0 && dayDifference < 7) return date.toLocaleDateString("fr-BE", { weekday: "short" });
118:   return date.toLocaleDateString("fr-BE", { day: "numeric", month: "short" });
119: }
120: 
121: export function formatMessageDay(dateValue, now = new Date()) {
122:   const date = new Date(dateValue);
123:   if (localDayKey(date) === localDayKey(now)) return "Aujourd’hui";
124:   const yesterday = new Date(now.getFullYear(), now.getMonth(), now.getDate() - 1);
125:   if (localDayKey(date) === localDayKey(yesterday)) return "Hier";
126:   return date.toLocaleDateString("fr-BE", { weekday: "long", day: "numeric", month: "long" });
127: } 1: import { describe, expect, it } from "vitest";
