  5: export function AuthField({
  6:   id,
  7:   label,
  8:   icon: Icon,
  9:   hint,
 10:   error,
 11:   className = "",
 12:   endAdornment = null,
 13:   ...inputProps
 14: }) {
 15:   const describedBy = [hint ? `${id}-hint` : null, error ? `${id}-error` : null].filter(Boolean).join(" ") || undefined;
