 20:       <div className={["auth-input-wrap", error ? "has-error" : ""].join(" ")}>
 21:         {Icon && <Icon className="auth-input-icon" size={18} aria-hidden="true" />}
 22:         <input
 23:           id={id}
 24:           className="auth-input"
 25:           aria-invalid={error ? "true" : undefined}
 26:           aria-describedby={describedBy}
 27:           {...inputProps}
 28:         />
 29:         {endAdornment}
 30:       </div>
 31:       {error ? (
 32:         <p id={`${id}-error`} className="auth-field-error">{error}</p>
 33:       ) : hint ? (
 34:         <p id={`${id}-hint`} className="auth-field-hint">{hint}</p>
 35:       ) : null}
 36:     </div>
 37:   );
