 74:       <div className="password-strength-track" aria-hidden="true">
 75:         {[1, 2, 3, 4].map((level) => (
 76:           <span key={level} className={level <= strength.score ? strength.tone : ""} />
 77:         ))}
 78:       </div>
 79:       <div className="password-strength-copy">
 80:         <span>{strength.label}</span>
 81:         <span>{password.length < 8 ? `${8 - password.length} caractère${8 - password.length > 1 ? "s" : ""} restant${8 - password.length > 1 ? "s" : ""}` : "Longueur suffisante"}</span>
