15: export function getPasswordStrength(password = "") {
16:   if (!password) return { score: 0, label: "", tone: "" };
17: 
18:   let score = 0;
19:   if (password.length >= 8) score += 1;
20:   if (password.length >= 12) score += 1;
21:   if (/[a-z]/.test(password) && /[A-Z]/.test(password)) score += 1;
22:   if (/\d/.test(password) || /[^A-Za-z0-9]/.test(password)) score += 1;
23: 
24:   if (score <= 1) return { score: 1, label: "Mot de passe fragile", tone: "weak" };
25:   if (score === 2) return { score: 2, label: "Mot de passe correct", tone: "fair" };
26:   if (score === 3) return { score: 3, label: "Bon mot de passe", tone: "good" };
27:   return { score: 4, label: "Mot de passe robuste", tone: "strong" };
