43:               </div>
44:               <span className="bottom-nav-label">{item.label}</span>
45:             </button>
46:           );
47:         })}
48: 
49:         {more && (
50:           <button
51:             ref={more.buttonRef}
52:             type="button"
53:             onClick={more.onSelect}
54:             className={["bottom-nav-item tap-feedback", more.active ? "active" : ""].join(" ")}
55:             aria-label={`${more.label}${moreBadgeLabel}`}
56:             aria-expanded={more.expanded}
57:             aria-haspopup="dialog"
58:           >
59:             <div className="relative">
60:               <MoreIcon size={21} strokeWidth={more.active ? 2.1 : 1.6} aria-hidden="true" />
61:               <NavigationBadge count={more.badge} />
62:             </div>
63:             <span className="bottom-nav-label">{more.label}</span>
64:           </button>
65:         )}
66:       </div>
67:     </nav>
68:   );
