161: /** Onglets contrôlés avec navigation clavier et cibles tactiles de 44 px. */
162: export function SegmentedTabs({
163:   items,
164:   value,
165:   onChange,
166:   ariaLabel = "Choisir une vue",
167:   className,
168: }) {
169:   const tabRefs = useRef([]);
170:   const enabledItems = items.filter((item) => !item.disabled);
171:   const fallbackId = enabledItems[0]?.id;
172:   const hasEnabledSelection = enabledItems.some((item) => item.id === value);
173:   // A real ARIA tab needs a corresponding panel. View/filter selectors without
174:   // panels use radio semantics instead of announcing tabs that control nothing.
175:   const usesTabSemantics = items.length > 0 && items.every((item) => Boolean(item.panelId));
176: 
177:   function activate(item) {
178:     if (!item || item.disabled) return;
179:     onChange?.(item.id, item);
180:   }
181: 
182:   function handleKeyDown(event, item) {
183:     const enabledIndex = enabledItems.findIndex((candidate) => candidate.id === item.id);
184:     if (enabledIndex < 0) return;
185: 
186:     let target;
187:     if (event.key === "ArrowRight" || event.key === "ArrowDown") {
188:       target = enabledItems[(enabledIndex + 1) % enabledItems.length];
189:     } else if (event.key === "ArrowLeft" || event.key === "ArrowUp") {
190:       target = enabledItems[(enabledIndex - 1 + enabledItems.length) % enabledItems.length];
191:     } else if (event.key === "Home") {
192:       target = enabledItems[0];
193:     } else if (event.key === "End") {
194:       target = enabledItems[enabledItems.length - 1];
195:     } else {
196:       return;
197:     }
198: 
199:     event.preventDefault();
200:     const targetIndex = items.findIndex((candidate) => candidate.id === target.id);
201:     tabRefs.current[targetIndex]?.focus();
202:     activate(target);
203:   }
204: 
205:   return (
206:     <div
207:       className={classes("aos-segmented-tabs", className)}
208:       role={usesTabSemantics ? "tablist" : "radiogroup"}
209:       aria-label={ariaLabel}
210:     >
211:       {items.map((item, index) => {
212:         const selected = !item.disabled && item.id === value;
213:         return (
214:           <button
215:             key={item.id}
216:             ref={(node) => { tabRefs.current[index] = node; }}
217:             type="button"
218:             role={usesTabSemantics ? "tab" : "radio"}
219:             className="aos-segmented-tabs__tab"
220:             aria-label={item.ariaLabel || (item.badge != null ? `${item.label}, ${item.badge}` : undefined)}
221:             aria-selected={usesTabSemantics ? selected : undefined}
222:             aria-checked={usesTabSemantics ? undefined : selected}
223:             aria-controls={usesTabSemantics ? item.panelId : undefined}
224:             id={item.tabId}
225:             tabIndex={selected || (!hasEnabledSelection && item.id === fallbackId) ? 0 : -1}
226:             disabled={item.disabled}
227:             onClick={() => activate(item)}
228:             onKeyDown={(event) => handleKeyDown(event, item)}
229:           >
230:             {item.icon && <Icon component={item.icon} size={15} />}
231:             <span>{item.label}</span>
232:             {item.badge != null && <span className="aos-segmented-tabs__badge">{item.badge}</span>}
233:           </button>
234:         );
235:       })}
236:     </div>
237:   );
238: }
