251: /**
252:  * Groupe label/contrôle/aide/erreur. Avec un enfant React unique, les attributs
253:  * d'association et d'invalidité sont ajoutés sans écraser ceux du contrôle.
254:  */
255: export function FormField({
256:   label,
257:   children,
258:   controlId,
259:   hint,
260:   error,
261:   required = false,
262:   optionalLabel = "Facultatif",
263:   className,
264: }) {
265:   const generatedControlId = useId();
266:   const hintId = useId();
267:   const errorId = useId();
268:   const child = isValidElement(children) ? children : null;
269:   const resolvedControlId = controlId || child?.props?.id || generatedControlId;
270:   const describedBy = [
271:     child?.props?.["aria-describedby"],
272:     hint && hintId,
273:     error && errorId,
274:   ].filter(Boolean).join(" ") || undefined;
275:   const control = child
276:     ? cloneElement(child, {
277:         id: resolvedControlId,
278:         "aria-describedby": describedBy,
279:         "aria-invalid": error ? true : child.props["aria-invalid"],
280:         required: required || child.props.required || undefined,
281:       })
282:     : children;
283: 
284:   return (
285:     <div className={classes("aos-form-field", error && "aos-form-field--error", className)}>
286:       <div className="aos-form-field__label-row">
287:         <label className="aos-form-field__label" htmlFor={resolvedControlId}>
288:           {label}
289:           {required && <span className="aos-form-field__required" aria-hidden="true"> *</span>}
290:         </label>
291:         {!required && optionalLabel && <span className="aos-form-field__optional">{optionalLabel}</span>}
292:       </div>
293:       <div className="aos-form-field__control">{control}</div>
294:       {hint && <p id={hintId} className="aos-form-field__hint">{hint}</p>}
295:       {error && <p id={errorId} className="aos-form-field__error" role="alert">{error}</p>}
296:     </div>
297:   );
298: }
