300: /** Sélecteur natif : fiable au clavier et ouvre le picker du système sur mobile. */
301: export function MobileSelect({
302:   options = [],
303:   placeholder,
304:   children,
305:   className,
306:   selectClassName,
307:   onChange,
308:   onValueChange,
309:   ariaLabel,
310:   ...selectProps
311: }) {
312:   function renderOption(option) {
313:     if (Array.isArray(option.options)) {
314:       return (
315:         <optgroup key={option.label} label={option.label} disabled={option.disabled}>
316:           {option.options.map(renderOption)}
317:         </optgroup>
318:       );
319:     }
320:     return <option key={option.value} value={option.value} disabled={option.disabled}>{option.label}</option>;
321:   }
322: 
323:   return (
324:     <span className={classes("aos-mobile-select", className)}>
325:       <select
326:         {...selectProps}
327:         className={classes("aos-mobile-select__control", selectClassName)}
328:         aria-label={ariaLabel}
329:         onChange={(event) => {
330:           onChange?.(event);
331:           onValueChange?.(event.target.value, event);
332:         }}
333:       >
334:         {placeholder && <option value="" disabled>{placeholder}</option>}
335:         {children || options.map(renderOption)}
336:       </select>
337:       <ChevronDown className="aos-mobile-select__icon" size={17} aria-hidden="true" />
338:     </span>
339:   );
340: }
