421: function focusableElements(container) {
422:   if (!container) return [];
423:   return Array.from(container.querySelectorAll(
424:     'a[href], button:not([disabled]), input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])',
