428: /** Dialogue de confirmation avec focus piégé, Échap et restauration du focus. */
429: export function ConfirmDialog({
430:   open,
431:   title,
432:   description,
433:   children,
434:   confirmLabel = "Confirmer",
435:   cancelLabel = "Annuler",
436:   loadingLabel = "Enregistrement…",
437:   tone = "danger",
438:   icon,
439:   onConfirm,
440:   onClose,
441:   confirmDisabled = false,
442:   loading = false,
443:   closeOnBackdrop = true,
444:   initialFocus = "cancel",
445: }) {
446:   const dialogRef = useRef(null);
447:   const cancelRef = useRef(null);
448:   const confirmRef = useRef(null);
449:   const onCloseRef = useRef(onClose);
450:   const loadingRef = useRef(loading);
451:   const titleId = useId();
452:   const descriptionId = useId();
453:   const contentId = useId();
454:   onCloseRef.current = onClose;
455:   loadingRef.current = loading;
456: 
457:   useEffect(() => {
458:     if (!open || typeof document === "undefined") return undefined;
459: 
460:     const previouslyFocused = document.activeElement;
461:     const previousOverflow = document.body.style.overflow;
462:     document.body.style.overflow = "hidden";
463: 
464:     const firstFocus = initialFocus === "confirm" && !confirmDisabled
465:       ? confirmRef.current
466:       : cancelRef.current;
467:     firstFocus?.focus();
468: 
469:     function handleKeyDown(event) {
470:       if (event.key === "Escape") {
471:         if (!loadingRef.current) {
472:           event.preventDefault();
473:           onCloseRef.current?.();
474:         }
475:         return;
476:       }
477: 
478:       if (event.key !== "Tab") return;
479:       const focusables = focusableElements(dialogRef.current);
480:       if (focusables.length === 0) {
481:         event.preventDefault();
482:         dialogRef.current?.focus();
483:         return;
484:       }
485: 
486:       const first = focusables[0];
487:       const last = focusables[focusables.length - 1];
488:       const active = document.activeElement;
489:       if (event.shiftKey && (active === first || !dialogRef.current?.contains(active))) {
490:         event.preventDefault();
491:         last.focus();
492:       } else if (!event.shiftKey && (active === last || !dialogRef.current?.contains(active))) {
493:         event.preventDefault();
494:         first.focus();
495:       }
496:     }
497: 
498:     window.addEventListener("keydown", handleKeyDown);
499:     return () => {
500:       window.removeEventListener("keydown", handleKeyDown);
501:       document.body.style.overflow = previousOverflow;
502:       if (previouslyFocused instanceof HTMLElement && previouslyFocused.isConnected) {
503:         previouslyFocused.focus();
504:       }
505:     };
506:   }, [open, initialFocus, confirmDisabled]);
507: 
508:   if (!open || typeof document === "undefined") return null;
509: 
510:   const DialogIcon = icon === null ? null : (icon || (tone === "danger" ? AlertTriangle : Info));
511:   const describedBy = [description && descriptionId, children && contentId].filter(Boolean).join(" ") || undefined;
512: 
513:   return createPortal(
514:     <div
515:       className="aos-confirm-dialog__backdrop"
516:       onMouseDown={(event) => {
517:         if (event.target === event.currentTarget && closeOnBackdrop && !loading) onClose?.();
518:       }}
519:     >
520:       <div
521:         ref={dialogRef}
522:         className="aos-confirm-dialog"
523:         data-tone={tone}
524:         role="dialog"
525:         aria-modal="true"
526:         aria-labelledby={titleId}
527:         aria-describedby={describedBy}
528:         tabIndex={-1}
529:       >
530:         <div className="aos-confirm-dialog__header">
531:           {DialogIcon && <span className="aos-confirm-dialog__icon"><Icon component={DialogIcon} size={22} /></span>}
532:           <div className="aos-confirm-dialog__copy">
533:             <h2 id={titleId} className="aos-confirm-dialog__title">{title}</h2>
534:             {description && <p id={descriptionId} className="aos-confirm-dialog__description">{description}</p>}
535:           </div>
536:           <button
537:             type="button"
538:             className="aos-confirm-dialog__close"
539:             onClick={onClose}
540:             disabled={loading}
541:             aria-label="Fermer"
542:           >
543:             <X size={19} aria-hidden="true" />
544:           </button>
545:         </div>
546: 
547:         {children && <div id={contentId} className="aos-confirm-dialog__content">{children}</div>}
548: 
549:         <div className="aos-confirm-dialog__actions">
550:           <button
551:             ref={cancelRef}
552:             type="button"
553:             className="aos-dialog-button aos-dialog-button--secondary"
554:             onClick={onClose}
555:             disabled={loading}
556:           >
557:             {cancelLabel}
558:           </button>
559:           <button
560:             ref={confirmRef}
561:             type="button"
562:             className="aos-dialog-button aos-dialog-button--confirm"
563:             onClick={onConfirm}
564:             disabled={confirmDisabled || loading}
565:           >
566:             {loading && <LoaderCircle className="aos-dialog-button__spinner" size={17} aria-hidden="true" />}
567:             {loading ? loadingLabel : confirmLabel}
568:           </button>
569:         </div>
570:       </div>
571:     </div>,
572:     document.body,
573:   );
574: }
