576: /** Panneau modal générique ancré en bas, adapté aux choix et formulaires mobiles. */
577: export function BottomSheet({
578:   open,
579:   title,
580:   description,
581:   children,
582:   footer,
583:   onClose,
584:   closeLabel = "Fermer le panneau",
585:   closeOnBackdrop = true,
586:   dismissDisabled = false,
587:   size = "md",
588:   className,
589: }) {
590:   const sheetRef = useRef(null);
591:   const closeRef = useRef(null);
592:   const onCloseRef = useRef(onClose);
593:   const dismissDisabledRef = useRef(dismissDisabled);
594:   const titleId = useId();
595:   const descriptionId = useId();
596:   onCloseRef.current = onClose;
597:   dismissDisabledRef.current = dismissDisabled;
598: 
599:   useEffect(() => {
600:     if (!open || typeof document === "undefined") return undefined;
601: 
602:     const previouslyFocused = document.activeElement;
603:     const previousOverflow = document.body.style.overflow;
604:     document.body.style.overflow = "hidden";
605:     closeRef.current?.focus();
606: 
607:     function handleKeyDown(event) {
608:       if (event.key === "Escape") {
609:         if (!dismissDisabledRef.current) {
610:           event.preventDefault();
611:           onCloseRef.current?.();
612:         }
613:         return;
614:       }
615:       if (event.key !== "Tab") return;
616: 
617:       const focusables = focusableElements(sheetRef.current);
618:       if (focusables.length === 0) {
619:         event.preventDefault();
620:         sheetRef.current?.focus();
621:         return;
622:       }
623:       const first = focusables[0];
624:       const last = focusables[focusables.length - 1];
625:       const active = document.activeElement;
626:       if (event.shiftKey && (active === first || !sheetRef.current?.contains(active))) {
627:         event.preventDefault();
628:         last.focus();
629:       } else if (!event.shiftKey && (active === last || !sheetRef.current?.contains(active))) {
630:         event.preventDefault();
631:         first.focus();
632:       }
633:     }
634: 
635:     window.addEventListener("keydown", handleKeyDown);
636:     return () => {
637:       window.removeEventListener("keydown", handleKeyDown);
638:       document.body.style.overflow = previousOverflow;
639:       if (previouslyFocused instanceof HTMLElement && previouslyFocused.isConnected) previouslyFocused.focus();
640:     };
641:   }, [open]);
642: 
643:   if (!open || typeof document === "undefined") return null;
644: 
645:   return createPortal(
646:     <div
647:       className="aos-bottom-sheet__backdrop"
648:       onMouseDown={(event) => {
649:         if (event.target === event.currentTarget && closeOnBackdrop && !dismissDisabled) onClose?.();
650:       }}
651:     >
652:       <section
653:         ref={sheetRef}
654:         className={classes("aos-bottom-sheet", className)}
655:         data-size={size}
656:         role="dialog"
657:         aria-modal="true"
658:         aria-labelledby={titleId}
659:         aria-describedby={description ? descriptionId : undefined}
660:         tabIndex={-1}
661:       >
662:         <div className="aos-bottom-sheet__handle" aria-hidden="true" />
663:         <header className="aos-bottom-sheet__header">
664:           <div className="aos-bottom-sheet__copy">
665:             <h2 id={titleId} className="aos-bottom-sheet__title">{title}</h2>
666:             {description && <p id={descriptionId} className="aos-bottom-sheet__description">{description}</p>}
667:           </div>
668:           <button
669:             ref={closeRef}
670:             type="button"
671:             className="aos-bottom-sheet__close"
672:             onClick={onClose}
673:             disabled={dismissDisabled}
674:             aria-label={closeLabel}
675:           >
676:             <X size={19} aria-hidden="true" />
677:           </button>
678:         </header>
679:         <div className="aos-bottom-sheet__content">{children}</div>
680:         {footer && <footer className="aos-bottom-sheet__footer">{footer}</footer>}
681:       </section>
682:     </div>,
683:     document.body,
684:   );
