  2: // AthleteOS — src/components/ui/Modal.jsx
  3: // Modal générique réutilisable.
  4: // Remplace tous les modals dupliqués dans chaque module.
  5: //
  6: // Usage :
  7: //   import Modal from "../components/ui/Modal";
  8: //
  9: //   <Modal
 10: //     title="Créer une alerte"
 11: //     onClose={handleClose}
 12: //     disabled={saving}
 13: //     onConfirm={handleSubmit}
 14: //     confirmLabel="Créer"
 15: //     confirmDisabled={!form.title.trim() || saving}
 16: //     loading={saving}
 17: //     loadingLabel="Création…"
 18: //   >
 19: //     {/* contenu du formulaire */}
 20: //   </Modal>
 21: // ============================================================
 22: 
 23: import { memo, useEffect, useId, useRef } from "react";
 24: import { X } from "lucide-react";
 25: 
 26: const FOCUSABLE_SELECTOR = [
 27:   "button:not([disabled])",
 28:   "input:not([disabled])",
 29:   "select:not([disabled])",
 30:   "textarea:not([disabled])",
 31:   "[href]",
 32:   "[tabindex]:not([tabindex='-1'])",
 33: ].join(",");
 34: 
 35: function Modal({
 36:   title,
 37:   onClose,
 38:   onConfirm,
 39:   confirmLabel  = "Confirmer",
 40:   confirmDisabled = false,
 41:   loading       = false,
 42:   loadingLabel  = "Enregistrement…",
 43:   disabled      = false,
 44:   children,
 45: }) {
 46:   const dialogRef = useRef(null);
 47:   const titleId = useId();
 48: 
 49:   useEffect(() => {
 50:     const previouslyFocused = document.activeElement;
 51:     const focusTimer = window.setTimeout(() => dialogRef.current?.focus(), 0);
 52:     return () => {
 53:       window.clearTimeout(focusTimer);
 54:       if (previouslyFocused instanceof HTMLElement && previouslyFocused.isConnected) previouslyFocused.focus();
 55:     };
 56:   }, []);
 57: 
 58:   useEffect(() => {
 59:     const handleKeyDown = (event) => {
 60:       if (event.key === "Escape") {
 61:         if (!disabled) onClose();
 62:         return;
 63:       }
 64:       if (event.key !== "Tab" || !dialogRef.current) return;
 65:       const focusable = [...dialogRef.current.querySelectorAll(FOCUSABLE_SELECTOR)];
 66:       if (!focusable.length) {
 67:         event.preventDefault();
 68:         dialogRef.current.focus();
 69:         return;
 70:       }
 71:       const first = focusable[0];
 72:       const last = focusable[focusable.length - 1];
 73:       if (event.shiftKey && (document.activeElement === first || document.activeElement === dialogRef.current)) {
 74:         event.preventDefault();
 75:         last.focus();
 76:       } else if (!event.shiftKey && document.activeElement === last) {
 77:         event.preventDefault();
 78:         first.focus();
 79:       }
 80:     };
 81:     window.addEventListener("keydown", handleKeyDown);
 82:     return () => window.removeEventListener("keydown", handleKeyDown);
 83:   }, [disabled, onClose]);
 84: 
 85:   return (
 86:     <div
 87:       className="fixed inset-0 z-50 flex items-center justify-center p-4"
 88:       style={{ background: "rgba(15,23,42,0.45)" }}
 89:       onClick={(e) => e.target === e.currentTarget && !disabled && onClose()}
 90:     >
 91:       <div
 92:         ref={dialogRef}
 93:         role="dialog"
 94:         aria-modal="true"
 95:         aria-labelledby={titleId}
 96:         tabIndex={-1}
 97:         className="rounded-2xl shadow-2xl w-full max-w-md max-h-[90vh] flex flex-col overflow-hidden"
 98:         style={{ background: "var(--c-surface)", border: "1px solid var(--c-border)" }}
 99:       >
100: 
101:         {/* ── Header ─────────────────────────────────────────────────── */}
102:         <div
103:           className="px-6 py-5 flex items-center justify-between flex-shrink-0"
104:           style={{ borderBottom: "1px solid var(--c-border)" }}
105:         >
106:           <h3 id={titleId} className="text-[16px] font-bold" style={{ color: "var(--c-text-1)" }}>{title}</h3>
107:           <button
108:             type="button"
109:             onClick={onClose}
110:             disabled={disabled}
111:             aria-label={`Fermer — ${title}`}
112:             className="p-1.5 rounded-lg transition-colors disabled:opacity-40 hover:bg-[var(--c-surface-3)]"
113:           >
114:             <X size={18} style={{ color: "var(--c-text-3)" }} />
115:           </button>
116:         </div>
117: 
118:         {/* ── Contenu (slot) ─────────────────────────────────────────── */}
119:         <div className="flex-1 overflow-y-auto px-6 py-5">
120:           {children}
121:         </div>
122: 
123:         {/* ── Footer ─────────────────────────────────────────────────── */}
124:         {onConfirm && (
125:           <div
126:             className="px-6 py-4 flex items-center justify-between gap-3 flex-shrink-0"
127:             style={{ borderTop: "1px solid var(--c-border)" }}
128:           >
129:             <button
130:               type="button"
131:               onClick={onClose}
132:               disabled={disabled}
133:               className="px-4 py-2 rounded-lg text-[13px] font-medium transition-colors disabled:opacity-40 hover:bg-[var(--c-surface-3)]"
134:               style={{ background: "var(--c-surface-2)", color: "var(--c-text-2)" }}
135:             >
136:               Annuler
137:             </button>
138:             <button
139:               type="button"
140:               onClick={onConfirm}
141:               disabled={confirmDisabled || disabled}
142:               className="flex items-center gap-2 px-5 py-2 rounded-lg text-white text-[13px] font-semibold transition-all disabled:opacity-40 disabled:cursor-not-allowed"
143:               style={{ background: "#1D9E75" }}
144:             >
145:               {loading ? (
146:                 <>
147:                   <div aria-hidden="true" className="w-3.5 h-3.5 border-2 border-white/40 border-t-white rounded-full animate-spin" />
148:                   {loadingLabel}
149:                 </>
150:               ) : (
