 4: function isStandaloneDisplay() {
 5:   if (typeof window === "undefined") return false;
 6:   return window.matchMedia?.("(display-mode: standalone)")?.matches
 7:     || window.matchMedia?.("(display-mode: minimal-ui)")?.matches
 8:     || window.navigator?.standalone === true;
 9: }
10: 
11: function detectPlatform() {
12:   if (typeof navigator === "undefined") return { isIos: false, isMobile: false };
13:   const userAgent = navigator.userAgent ?? "";
14:   const isIos = /iPad|iPhone|iPod/i.test(userAgent)
15:     || (navigator.platform === "MacIntel" && navigator.maxTouchPoints > 1);
16:   return {
17:     isIos,
18:     isMobile: isIos || /Android|Mobile/i.test(userAgent),
19:   };
20: }
21: 
22: export function PwaInstallProvider({ children }) {
23:   const [installPrompt, setInstallPrompt] = useState(null);
24:   const [installed, setInstalled] = useState(isStandaloneDisplay);
25:   const platform = useMemo(detectPlatform, []);
26: 
27:   useEffect(() => {
28:     const standaloneQuery = window.matchMedia?.("(display-mode: standalone)");
29:     const handleDisplayChange = () => setInstalled(isStandaloneDisplay());
30:     const handleBeforeInstall = (event) => {
31:       event.preventDefault();
32:       setInstallPrompt(event);
33:     };
34:     const handleInstalled = () => {
35:       setInstallPrompt(null);
36:       setInstalled(true);
37:     };
38: 
39:     window.addEventListener("beforeinstallprompt", handleBeforeInstall);
40:     window.addEventListener("appinstalled", handleInstalled);
41:     standaloneQuery?.addEventListener?.("change", handleDisplayChange);
42:     return () => {
43:       window.removeEventListener("beforeinstallprompt", handleBeforeInstall);
44:       window.removeEventListener("appinstalled", handleInstalled);
45:       standaloneQuery?.removeEventListener?.("change", handleDisplayChange);
46:     };
47:   }, []);
48: 
49:   const install = useCallback(async () => {
50:     if (!installPrompt) return { outcome: "unavailable" };
51:     await installPrompt.prompt();
52:     const choice = await installPrompt.userChoice;
53:     setInstallPrompt(null);
54:     if (choice?.outcome === "accepted") setInstalled(true);
55:     return choice ?? { outcome: "dismissed" };
56:   }, [installPrompt]);
57: 
58:   const share = useCallback(async () => {
59:     const url = window.location.origin;
60:     const data = {
61:       title: "AthleteOS",
62:       text: "Rejoins-moi sur AthleteOS, la plateforme de suivi sportif du club.",
63:       url,
64:     };
65: 
66:     if (navigator.share) {
67:       await navigator.share(data);
68:       return "shared";
69:     }
70:     if (!navigator.clipboard?.writeText) throw new Error("clipboard-unavailable");
71:     await navigator.clipboard.writeText(url);
72:     return "copied";
73:   }, []);
74: 
75:   const copyLink = useCallback(async () => {
76:     if (!navigator.clipboard?.writeText) throw new Error("clipboard-unavailable");
77:     await navigator.clipboard.writeText(window.location.origin);
78:   }, []);
79: 
80:   const value = useMemo(() => ({
81:     canInstall: Boolean(installPrompt) && !installed,
82:     installed,
83:     install,
84:     share,
85:     copyLink,
86:     ...platform,
87:   }), [copyLink, install, installPrompt, installed, platform, share]);
88: 
89:   return <PwaInstallContext.Provider value={value}>{children}</PwaInstallContext.Provider>;
90: }1: import { createContext, useContext } from "react";
