 3: function toLocalDateKey(date) {
 4:   const year = date.getFullYear();
 5:   const month = String(date.getMonth() + 1).padStart(2, "0");
 6:   const day = String(date.getDate()).padStart(2, "0");
 7:   return `${year}-${month}-${day}`;
 8: }
