10: export function getSessionArchiveCutoff(referenceDate = new Date()) {
11:   const cutoff = new Date(referenceDate.getFullYear(), referenceDate.getMonth(), referenceDate.getDate());
12:   cutoff.setDate(cutoff.getDate() - SESSION_ARCHIVE_AFTER_DAYS);
13:   return toLocalDateKey(cutoff);
14: }
