16: export function isSessionArchived(session, referenceDate = new Date()) {
17:   const sessionDate = session?.sessionDate?.slice(0, 10);
18:   if (!sessionDate) return false;
19:   return sessionDate <= getSessionArchiveCutoff(referenceDate);
