70: const ALL_FOCUSES = Object.values(TRAINING_FOCUS_GROUPS).flat();
71: const FOCUS_BY_ID = new Map(ALL_FOCUSES.map(item => [item.id, item]));
72: const FOCUS_CATEGORY_BY_ID = new Map(Object.entries(TRAINING_FOCUS_GROUPS).flatMap(([category, items]) => items.map(item => [item.id, category])));
73: 
74: export function getTrainingFocusOptions(category) {
75:   return TRAINING_FOCUS_GROUPS[category] ?? TRAINING_FOCUS_GROUPS.technique;
76: }
77: 
78: export function getDefaultTrainingFocus(category) {
79:   return getTrainingFocusOptions(category)[0]?.id ?? "technical_general";
80: }
81: 
82: export function getTrainingFocus(focusId, category) {
83:   const focus = FOCUS_BY_ID.get(focusId);
84:   if (focus && (!category || FOCUS_CATEGORY_BY_ID.get(focusId) === category)) return focus;
85:   return FOCUS_BY_ID.get(getDefaultTrainingFocus(category));
86: }
87: 
88: export function getSessionTrainingFocus(session) {
89:   return getTrainingFocus(session?.trainingFocus ?? session?.training_focus, session?.category);
90: }
91: 
92: export function isTrainingFocusCompatible(focusId, category) {
93:   return getTrainingFocusOptions(category).some(item => item.id === focusId);
