 4: describe("objectifs de séance d'athlétisme", () => {
 5:   it("couvre les intentions qui ne peuvent pas être déduites de la distance", () => {
 6:     expect(getTrainingFocusOptions("sprint").map(item => item.id)).toEqual(expect.arrayContaining(["acceleration", "max_velocity", "speed_endurance", "special_endurance"]));
 7:     expect(getTrainingFocusOptions("endurance").map(item => item.id)).toEqual(expect.arrayContaining(["easy_run", "vma_vo2", "race_pace"]));
 8:     expect(getTrainingFocusOptions("saut").map(item => item.id)).toEqual(expect.arrayContaining(["plyometrics", "bounds", "jump_technical"]));
 9:   });
10: 
11:   it("reste compatible avec les anciennes séances sans objectif détaillé", () => {
12:     expect(getSessionTrainingFocus({ category: "sprint" }).id).toBe("sprint_general");
13:     expect(getSessionTrainingFocus({ category: "endurance" }).id).toBe("endurance_general");
14:   });
15: 
16:   it("retombe sur un objectif générique si une valeur appartient à une autre catégorie", () => {
17:     expect(isTrainingFocusCompatible("vma_vo2", "sprint")).toBe(false);
18:     expect(getTrainingFocus("unknown", "saut").id).toBe(getDefaultTrainingFocus("saut"));
19:   });
20: });  1: // Cinq jauges circulaires qui résument "Ma progression > Charge
  2: // d'entraînement" pour l'athlète. Chaque jauge affiche un mot de statut
  3: // simple (jamais un chiffre brut en face avant) ; le chiffre et la formule
  4: // restent disponibles dans le détail (voir FormeDetailPanel).
  5: //
  6: // Important : contrairement à l'ancienne version retirée du produit
  7: // (src/athlete/shared.js, tableaux `legacyThresholdsDoNotUse`), aucune jauge
  8: // ici n'applique une échelle fixe 0-100 à une valeur de charge absolue (les
  9: // unités de charge sont propres à chaque athlète, sans borne universelle).
 10: // Chaque jauge compare l'athlète à SA PROPRE référence récente (vs son
 11: // habitude, vs sa semaine, vs son historique EWMA) — jamais à un seuil
 12: // universel.
 13: import { getAthleteLoadStory } from "./monitoringMetrics.js";
 14: import { getAthleteAxisProfile, LOAD_AXES } from "../utils/loadAxes.js";
 15: 
 16: export const TRAINING_GAUGE_KEYS = new Set(["weeklyLoad", "form", "fitness", "readiness", "fatigue"]);
 17: 
 18: const STATUS_WORDS = ["Faible", "Modéré", "Bon", "Élevé", "Très élevé"];
 19: 
 20: // Bandes partagées : mêmes seuils que getAthleteLoadStory (±10 %, ±25 %) pour
 21: // rester cohérent avec ce qui existe déjà, plutôt que d'inventer de nouveaux
 22: // chiffres. "polarity" décide seulement la couleur, jamais les seuils :
 23: //  - "center-good"  : le milieu ("Bon") est l'idéal, les deux extrêmes alertent.
 24: //  - "high-good"    : plus c'est haut, mieux c'est (ex. condition physique).
 25: //  - "high-caution" : plus c'est haut, plus ça mérite attention (ex. fatigue).
 26: function bandFromPercent(percent, polarity) {
 27:   if (percent == null || !Number.isFinite(percent)) return null;
 28:   const clamped = Math.max(-100, Math.min(100, percent));
 29:   const statusWord = clamped <= -25 ? "Faible"
 30:     : clamped <= -10 ? "Modéré"
 31:       : clamped < 10 ? "Bon"
 32:         : clamped < 25 ? "Élevé"
 33:           : "Très élevé";
 34: 
 35:   let color;
 36:   if (polarity === "center-good") {
 37:     color = statusWord === "Bon" ? "var(--tone-success)"
 38:       : (statusWord === "Modéré" || statusWord === "Élevé") ? "var(--tone-warning)"
 39:         : "var(--tone-danger)";
 40:   } else if (polarity === "high-good") {
 41:     color = (statusWord === "Bon" || statusWord === "Élevé" || statusWord === "Très élevé") ? "var(--tone-success)"
 42:       : statusWord === "Modéré" ? "var(--tone-info)"
 43:         : "var(--tone-warning)";
 44:   } else {
 45:     color = statusWord === "Très élevé" ? "var(--tone-danger)"
 46:       : statusWord === "Élevé" ? "var(--tone-warning)"
 47:         : (statusWord === "Bon" || statusWord === "Modéré") ? "var(--tone-success)"
 48:           : "var(--tone-info)";
 49:   }
 50:   const fillPercent = Math.max(4, Math.min(100, Math.round(clamped + 50)));
 51:   return { statusWord, color, fillPercent };
 52: }
 53: 
 54: function formatSigned(value) {
 55:   return `${value > 0 ? "+" : ""}${value}`;
 56: }
 57: 
 58: // Compare l'EWMA longue (28 j) d'aujourd'hui à sa valeur il y a ~28 jours,
 59: // en s'appuyant sur les dates réelles de ewmaHistory (jamais sur un simple
 60: // décalage d'index, qui serait faussé par des trous de données).
 61: function chronicTrendPercent(ewmaHistory) {
 62:   const known = (ewmaHistory ?? []).filter((point) => point.chronic != null);
 63:   if (!known.length) return null;
 64:   const latest = known.at(-1);
 65:   const target = new Date(latest.date);
 66:   target.setDate(target.getDate() - 28);
 67:   const past = [...known].reverse().find((point) => new Date(point.date) <= target);
 68:   if (!past || !past.chronic) return null;
 69:   return Math.round(((latest.chronic - past.chronic) / past.chronic) * 100);
 70: }
