 72: function dominantAxisOf(athleteId, sessions, currentWeek) {
 73:   const profile = getAthleteAxisProfile(athleteId, sessions, currentWeek);
 74:   if (!profile) return null;
 75:   const [id] = Object.entries(profile).sort((a, b) => b[1].currentLoad - a[1].currentLoad)[0] ?? [];
 76:   return id ? { id, ...LOAD_AXES[id] } : null;
 77: }
