 79: function weeklyLoadReading(metrics, sessions, athleteId) {
 80:   const percent = metrics.variationPercent;
 81:   const band = bandFromPercent(percent, "center-good");
 82:   const story = getAthleteLoadStory(metrics, sessions, athleteId);
 83:   return {
 84:     key: "weeklyLoad", label: "Charge de la semaine", shortLabel: "Charge semaine",
 85:     athleteMeaning: "Ce que tu as réellement effectué cette semaine, comparé à ton rythme habituel",
 86:     kind: "Comparaison descriptive", evidence: "Calcul transparent",
 87:     color: band?.color ?? "var(--c-text-3)", statusWord: band?.statusWord ?? null, fillPercent: band?.fillPercent ?? 8,
 88:     displayValue: band?.statusWord ?? "—", unit: "",
 89:     available: band != null,
 90:     interpretation: band ? story.summary : "Il manque encore quelques jours renseignés pour comparer cette semaine à tes habitudes.",
 91:     meaning: `Une charge très basse peut signaler un manque d'entraînement récent ; une charge très élevée peut signaler un risque de surcharge. Le milieu (« Bon ») correspond à ton rythme habituel, pas à un chiffre universel.${band ? ` ${story.cause}` : ""}`,
 92:     formula: `Moyenne quotidienne des 7 derniers jours comparée à celle des 21 jours précédents${percent != null ? ` : ${formatSigned(percent)} %` : ""}. Charge en points d'effort (durée réelle × RPE) : ${metrics.load7 ?? "—"} cette semaine, ${metrics.load28 ?? "—"} sur les 4 dernières semaines.`,
 93:     limits: "Le pourcentage compare l'athlète à sa propre habitude ; ce n'est ni une zone optimale ni un seuil automatique de danger.",
 94:     missingReason: band ? null : "La comparaison demande 28 jours connus et une moyenne habituelle supérieure à zéro.",
 95:     sources: ["Foster et al. (2001) · session-RPE", "Convention descriptive AthleteOS · fenêtres 7 et 21 jours"],
 96:   };
 97: }
