 99: function formReading(dailyState) {
100:   const score = dailyState?.score;
101:   const statusWord = score == null ? null
102:     : score < 35 ? "Faible" : score < 55 ? "Modéré" : score < 75 ? "Bon" : score < 90 ? "Élevé" : "Très élevé";
103:   return {
104:     key: "form", label: "Forme du jour", shortLabel: "Forme",
105:     athleteMeaning: "L'équilibre entre ton ressenti du jour et ta charge récente",
106:     kind: "Questionnaire interne + charge", evidence: "Convention AthleteOS",
107:     color: dailyState?.color ?? "var(--c-text-3)", statusWord, fillPercent: score ?? 8,
108:     displayValue: statusWord ?? "—", unit: "",
109:     available: score != null,
110:     interpretation: dailyState?.plainSummary ?? dailyState?.summary ?? "Réponds au questionnaire du jour pour voir ta forme.",
111:     meaning: `${dailyState?.loadContext ?? "Combine ton ressenti déclaré du jour et la tendance de ta charge récente."} Une forme élevée est un signal positif ; une forme basse mérite d'en parler avec ton coach, pas une alerte automatique.`,
112:     formula: `Moyenne des 5 réponses du questionnaire AthleteOS (sommeil, énergie, courbatures, humeur, stress), normalisée sur 0-100${score != null ? ` : ${score}/100` : ""}.`,
113:     limits: "Ce score subjectif n'est ni un diagnostic, ni une mesure validée de récupération physiologique.",
114:     missingReason: score != null ? null : "Le questionnaire AthleteOS du jour n'a pas encore été complété.",
115:     sources: ["AthleteOS Wellness Questionnaire v1 · instrument interne à valider"],
116:   };
117: }
