119: function fitnessReading(metrics) {
120:   const percent = chronicTrendPercent(metrics.ewmaHistory);
121:   const band = bandFromPercent(percent, "high-good");
122:   const trendSentence = percent == null ? "Il manque encore assez d'historique continu pour voir une tendance sur un mois."
123:     : percent >= 10 ? "Ta charge habituelle augmente régulièrement depuis un mois — ta base de travail s'élargit."
124:       : percent <= -10 ? "Ta charge habituelle diminue depuis un mois — ce n'est pas forcément un problème (fin de bloc, récupération programmée...), mais vaut une discussion avec ton coach si ce n'est pas prévu."
125:         : "Ta charge habituelle est stable depuis un mois.";
126:   return {
127:     key: "fitness", label: "Condition physique", shortLabel: "Condition physique",
128:     athleteMeaning: "L'évolution de ta charge habituelle sur le dernier mois",
129:     kind: "Lissage statistique", evidence: "Méthode statistique",
130:     color: band?.color ?? "var(--c-text-3)", statusWord: band?.statusWord ?? null, fillPercent: band?.fillPercent ?? 8,
131:     displayValue: band?.statusWord ?? "—", unit: "",
132:     available: band != null,
133:     interpretation: trendSentence,
134:     meaning: "Reflète la construction ou la baisse progressive de ta charge de travail habituelle. Une progression régulière est en général positive ; une baisse marquée n'est pas automatiquement négative (elle peut être planifiée).",
135:     formula: `EWMA quotidienne (λ = 2/29) comparée à sa valeur d'il y a 28 jours${percent != null ? ` : ${formatSigned(percent)} %` : ""}. Valeur actuelle : ${metrics.chronic ?? "—"} points d'effort lissés.`,
136:     limits: "Cette moyenne lissée ne représente pas la forme, la fitness ou l'adaptation physiologique au sens physiologique du terme — c'est une tendance descriptive de charge.",
137:     missingReason: band ? null : "Il faut environ 2 mois d'historique quotidien continu pour comparer deux périodes.",
138:     sources: ["Banister et al. (1975) · modèle fitness-fatigue", "Williams et al. (2017) · EWMA appliquée à la charge sportive"],
139:   };
140: }
