142: function readinessReading(metrics) {
143:   const recoveryStatus = metrics.recovery?.status;
144:   const wellness = metrics.wellnessScore;
145:   let statusWord = null;
146:   if (recoveryStatus === "spacing_active") statusWord = (wellness == null || wellness < 55) ? "Faible" : "Modéré";
147:   else if (recoveryStatus === "spacing_transition") statusWord = "Bon";
148:   else if (recoveryStatus === "window_elapsed") statusWord = (wellness != null && wellness >= 75) ? "Très élevé" : "Élevé";
149:   const fillPercent = statusWord ? { Faible: 20, Modéré: 40, Bon: 60, Élevé: 80, "Très élevé": 100 }[statusWord] : 8;
150:   const band = statusWord ? bandFromPercent(({ Faible: -40, Modéré: -15, Bon: 0, Élevé: 15, "Très élevé": 40 })[statusWord], "high-good") : null;
151:   const sentence = statusWord == null ? "Pas encore assez de séances récentes pour estimer ta préparation."
152:     : statusWord === "Faible" ? "Tu es encore dans la fenêtre d'espacement programmée après ta dernière séance exigeante — une récupération supplémentaire peut être utile avant une séance intense."
153:       : statusWord === "Modéré" ? "Tu es encore dans la fenêtre d'espacement programmée, mais ton ressenti du jour est plutôt bon."
