172: function fatigueReading(metrics, sessions, athleteId, currentWeek) {
173:   const percent = metrics.acwr != null ? Math.round((metrics.acwr - 1) * 100) : null;
174:   const band = bandFromPercent(percent, "high-caution");
175:   const axis = dominantAxisOf(athleteId, sessions, currentWeek);
176:   const axisNote = axis ? ` Tes séances ont surtout sollicité ${axis.nounPhrase} cette semaine.` : "";
177:   const sentence = percent == null ? "Pas encore assez d'historique continu (environ un mois) pour estimer ta sollicitation récente."
178:     : band.statusWord === "Très élevé" ? `Ta charge récente est nettement plus élevée que ta charge habituelle.${axisNote} Une récupération supplémentaire peut être utile.`
179:       : band.statusWord === "Élevé" ? `Ta charge récente est un peu plus élevée que ta charge habituelle.${axisNote}`
180:         : band.statusWord === "Faible" ? `Ta charge récente est nettement plus basse que ta charge habituelle — signe possible d'une récupération ou d'un volume d'entraînement réduit.${axisNote}`
181:           : `Ta charge récente est proche de ta charge habituelle.${axisNote}`;
182:   return {
183:     key: "fatigue", label: "Sollicitation récente", shortLabel: "Fatigue",
184:     athleteMeaning: "Ta charge récente comparée à ta charge habituelle des dernières semaines",
185:     kind: "Ratio descriptif", evidence: "Usage débattu dans la littérature",
186:     color: band?.color ?? "var(--c-text-3)", statusWord: band?.statusWord ?? null, fillPercent: band?.fillPercent ?? 8,
187:     displayValue: band?.statusWord ?? "—", unit: "",
188:     available: band != null,
189:     interpretation: sentence,
190:     meaning: "Compare ta charge très récente (EWMA 7 jours) à ta charge habituelle (EWMA 28 jours). Une valeur élevée ne mesure pas directement une fatigue physiologique ni un risque de blessure individuel.",
191:     formula: `Ratio EWMA courte ÷ EWMA longue, calculé uniquement après 28 jours quotidiens consécutifs connus${metrics.acwr != null ? ` : ${metrics.acwr.toFixed(2)} (${formatSigned(percent)} % vs ta charge habituelle)` : ""}.`,
192:     limits: "Ce ratio (proche de l'ACWR) fait l'objet d'un débat scientifique actif sur sa validité pour estimer un risque de blessure individuel ; il est présenté ici uniquement comme repère descriptif, jamais comme seuil de danger.",
193:     missingReason: band ? null : "Le ratio reste masqué tant que 28 jours consécutifs ne sont pas connus ou que l'EWMA longue vaut zéro.",
194:     sources: ["Impellizzeri et al. (2020) · limites conceptuelles de l'ACWR", "Gabbett (2016) · training-injury prevention paradox"],
195:   };
196: }
