198: export function getTrainingGaugeReading(key, { metrics = {}, dailyState = null, sessions = [], athleteId = null, currentWeek = null } = {}) {
199:   if (key === "weeklyLoad") return weeklyLoadReading(metrics, sessions, athleteId);
200:   if (key === "form") return formReading(dailyState);
201:   if (key === "fitness") return fitnessReading(metrics);
202:   if (key === "readiness") return readinessReading(metrics);
203:   if (key === "fatigue") return fatigueReading(metrics, sessions, athleteId, currentWeek);
204:   return null;
205: }
