  7: function urlBase64ToUint8Array(base64String) {
  8:   const padding = "=".repeat((4 - (base64String.length % 4)) % 4);
  9:   const base64 = (base64String + padding).replace(/-/g, "+").replace(/_/g, "/");
 10:   const raw = window.atob(base64);
 11:   return Uint8Array.from([...raw].map((char) => char.charCodeAt(0)));
