 14: export function usePushNotifications(athleteId, clubId, userId = null) {
 15:   const [subscribed, setSubscribed] = useState(false);
 16:   const [permissionState, setPermissionState] = useState("default");
 17:   const [swReady, setSwReady] = useState(false);
 18:   const [registration, setRegistration] = useState(null);
 19: 
 20:   useEffect(() => {
 21:     if (!("serviceWorker" in navigator) || !("PushManager" in window)) return;
 22:     navigator.serviceWorker
 23:       .register("/sw.js")
 24:       .then((reg) => {
 25:         setRegistration(reg);
 26:         setSwReady(true);
 27:         setPermissionState(Notification.permission);
 28:         setSubscribed(false);
 29:       })
 30:       .catch(console.error);
 31:   }, []);
 32: 
 33:   useEffect(() => {
 34:     if (!swReady || !registration || !clubId) return;
 35:     if (Notification.permission !== "granted") return;
 36: 
 37:     const fixSubscription = async () => {
 38:       const subscription = await registration.pushManager.getSubscription();
 39:       if (!subscription) {
 40:         setSubscribed(false);
 41:         return;
 42:       }
 43: 
 44:       const subscriptionJson = subscription.toJSON();
 45:       const { data: existing } = await supabase
 46:         .from("push_subscriptions")
 47:         .select("id, athlete_id, user_id")
 48:         .eq("endpoint", subscriptionJson.endpoint)
 49:         .maybeSingle();
 50: 
 51:       if (existing) {
 52:         const athleteMatches = athleteId ? existing.athlete_id === athleteId : true;
 53:         const userMatches = userId ? existing.user_id === userId : true;
 54:         if (athleteMatches && userMatches) {
 55:           setSubscribed(true);
 56:           return;
 57:         }
 58:       }
 59: 
 60:       const applicationServerKey = VAPID_PUBLIC_KEY ? urlBase64ToUint8Array(VAPID_PUBLIC_KEY) : null;
 61:       const { error } = await persistCurrentPushSubscription({
 62:         supabaseClient: supabase,
 63:         registration,
 64:         subscription,
 65:         applicationServerKey,
 66:         clubId,
 67:         athleteId,
 68:         userId,
 69:       });
 70:       if (error) throw error;
 71:       setSubscribed(true);
 72:     };
 73: 
 74:     fixSubscription().catch(console.error);
 75:   }, [swReady, registration, clubId, athleteId, userId]);
 76: 
 77:   const subscribe = useCallback(async () => {
 78:     if (!swReady || !registration || !VAPID_PUBLIC_KEY || subscribed) return;
 79:     try {
 80:       const permission = await Notification.requestPermission();
 81:       setPermissionState(permission);
 82:       if (permission !== "granted") return;
 83: 
 84:       let subscription = await registration.pushManager.getSubscription();
 85:       if (!subscription) {
 86:         subscription = await registration.pushManager.subscribe({
 87:           userVisibleOnly: true,
 88:           applicationServerKey: urlBase64ToUint8Array(VAPID_PUBLIC_KEY),
 89:         });
 90:       }
 91:       const { error } = await persistCurrentPushSubscription({
 92:         supabaseClient: supabase,
 93:         registration,
 94:         subscription,
 95:         applicationServerKey: urlBase64ToUint8Array(VAPID_PUBLIC_KEY),
 96:         clubId,
 97:         athleteId,
 98:         userId,
 99:       });
100:       if (error) throw error;
101:       setSubscribed(true);
102:     } catch (error) {
103:       console.error("Push subscription error:", error);
104:     }
105:   }, [swReady, registration, athleteId, clubId, userId, subscribed]);
106: 
107:   return { subscribed, subscribe, permissionState, swReady };
108: } 1: import { useCallback, useEffect, useState } from "react";
