50: export function sessionStatus(session) {
51:   const { validations, athleteIds } = session;
52:   if (!validations?.length) return "future";
53:   const done = validations.filter(validation => validation.status === "done").length;
54:   const none = validations.filter(validation => validation.status === "none").length;
55:   if (done === athleteIds.length && athleteIds.length > 0) return "done";
56:   if (none === athleteIds.length && athleteIds.length > 0) return "none";
57:   if (validations.some(validation => validation.status === "partial") || (done > 0 && done < athleteIds.length)) return "partial";
58:   return "future";
59: }
