65: export function getCalendarDays(year, month) {
66:   const firstDay = new Date(year, month, 1);
67:   const lastDay = new Date(year, month + 1, 0);
68:   const startDow = (firstDay.getDay() + 6) % 7;
69:   const days = [];
70:   for (let index = startDow - 1; index >= 0; index--) days.push({ date: new Date(year, month, -index), isCurrentMonth: false });
71:   for (let day = 1; day <= lastDay.getDate(); day++) days.push({ date: new Date(year, month, day), isCurrentMonth: true });
72:   const remaining = 7 - (days.length % 7);
73:   if (remaining < 7) {
74:     for (let day = 1; day <= remaining; day++) days.push({ date: new Date(year, month + 1, day), isCurrentMonth: false });
75:   }
76:   return days;
