111: function detectDelimiter(text) {
112:   let commas = 0;
113:   let semicolons = 0;
114:   let inQuotes = false;
115: 
116:   for (let index = 0; index < text.length; index += 1) {
117:     const char = text[index];
118:     if (char === '"') {
119:       if (inQuotes && text[index + 1] === '"') index += 1;
120:       else inQuotes = !inQuotes;
121:     } else if (!inQuotes && (char === "\n" || char === "\r")) {
122:       break;
123:     } else if (!inQuotes && char === ",") commas += 1;
124:     else if (!inQuotes && char === ";") semicolons += 1;
125:   }
126: 
127:   return semicolons > commas ? ";" : ",";
128: }
