130: function tokenizeCsv(text, delimiter, limits, startingLine = 1) {
131:   const rows = [];
132:   let cells = [];
133:   let field = "";
134:   let inQuotes = false;
135:   let line = startingLine;
136:   let rowStartLine = startingLine;
137: 
138:   const pushField = () => {
139:     if (field.length > limits.maxFieldLength) {
140:       return csvError(
141:         "field_too_long",
142:         `La ligne ${rowStartLine} contient une valeur de plus de ${limits.maxFieldLength} caractères.`,
143:         rowStartLine,
144:       );
145:     }
146:     cells.push(field);
147:     field = "";
148:     if (cells.length > limits.maxColumns) {
149:       return csvError(
150:         "too_many_columns",
151:         `La ligne ${rowStartLine} dépasse la limite de ${limits.maxColumns} colonnes.`,
152:         rowStartLine,
153:       );
154:     }
155:     return null;
156:   };
157: 
158:   const pushRow = () => {
159:     const issue = pushField();
160:     if (issue) return issue;
161:     if (cells.some((cell) => cleanField(cell) !== "")) {
162:       rows.push({ cells, row: rowStartLine });
163:     }
164:     cells = [];
165:     return null;
166:   };
167: 
168:   for (let index = 0; index < text.length; index += 1) {
169:     const char = text[index];
170: 
171:     if (inQuotes) {
172:       if (char === '"' && text[index + 1] === '"') {
173:         field += '"';
174:         index += 1;
175:       } else if (char === '"') {
176:         inQuotes = false;
177:       } else {
178:         field += char;
179:         if (char === "\n") line += 1;
180:       }
181:       continue;
182:     }
183: 
184:     if (char === '"' && field === "") {
185:       inQuotes = true;
186:     } else if (char === delimiter) {
187:       const issue = pushField();
188:       if (issue) return { rows: [], fatalError: issue };
189:     } else if (char === "\n" || char === "\r") {
190:       const issue = pushRow();
191:       if (issue) return { rows: [], fatalError: issue };
192:       if (char === "\r" && text[index + 1] === "\n") index += 1;
193:       line += 1;
194:       rowStartLine = line;
195:     } else {
196:       field += char;
197:     }
198:   }
199: 
200:   if (inQuotes) {
201:     return {
202:       rows: [],
203:       fatalError: csvError(
204:         "unclosed_quote",
205:         `Un guillemet ouvert à la ligne ${rowStartLine} n'est pas refermé.`,
206:         rowStartLine,
207:       ),
208:     };
209:   }
210: 
211:   if (field !== "" || cells.length > 0) {
212:     const issue = pushRow();
213:     if (issue) return { rows: [], fatalError: issue };
214:   }
215: 
216:   return { rows, fatalError: null };
217: }
218: 
219: function resolveHeaders(headerCells, headerRow) {
220:   const columns = new Map();
221:   const ignoredHeaders = [];
222:   const fatalErrors = [];
223: 
224:   headerCells.forEach((header, index) => {
225:     const normalized = normalizeHeader(header);
226:     const field = ALIAS_LOOKUP.get(normalized);
227: 
228:     if (!field) {
229:       if (cleanField(header)) ignoredHeaders.push(cleanField(header));
230:       return;
231:     }
232: 
233:     if (columns.has(field)) {
234:       fatalErrors.push(csvError(
235:         "duplicate_header",
236:         `La colonne « ${cleanField(header)} » apparaît plusieurs fois sous des noms équivalents.`,
237:         headerRow,
238:       ));
239:       return;
240:     }
241: 
242:     columns.set(field, index);
243:   });
244: 
245:   if (!columns.has("name") && !columns.has("firstName") && !columns.has("lastName")) {
246:     fatalErrors.push(csvError(
247:       "missing_name_header",
248:       "Ajoute une colonne « Nom complet » ou des colonnes « Prénom » et « Nom ».",
249:       headerRow,
250:     ));
251:   }
252: 
253:   return { columns, ignoredHeaders, fatalErrors };
254: }
255: 
256: function getCell(cells, columns, key) {
257:   const index = columns.get(key);
258:   return index == null ? "" : cleanField(cells[index]);
259: }
260: 
261: function buildAthlete(cells, columns, row, limits) {
262:   const payloadColumnIndexes = [...columns.values()];
263:   if (payloadColumnIndexes.some((index) => containsControlCharacter(cells[index]))) {
264:     return { error: csvError("control_character", "La ligne contient un caractère de contrôle non autorisé.", row) };
265:   }
266: 
267:   const directName = getCell(cells, columns, "name");
268:   const firstName = getCell(cells, columns, "firstName");
269:   const lastName = getCell(cells, columns, "lastName");
270:   const name = directName || [firstName, lastName].filter(Boolean).join(" ");
271:   const email = getCell(cells, columns, "email").toLowerCase();
272:   const ageValue = getCell(cells, columns, "age");
273: 
274:   if (!name) {
275:     return { error: csvError("missing_name", "Le nom de l'athlète est obligatoire.", row) };
276:   }
277:   if (name.length > limits.maxNameLength) {
278:     return { error: csvError("name_too_long", `Le nom ne peut pas dépasser ${limits.maxNameLength} caractères.`, row) };
279:   }
280:   if (email && (!EMAIL_PATTERN.test(email) || email.length > 254)) {
281:     return { error: csvError("invalid_email", `L'adresse email « ${email} » n'est pas valide.`, row) };
282:   }
283: 
284:   let age = "";
285:   if (ageValue) {
286:     const numericAge = Number(ageValue);
287:     if (!/^\d{1,3}$/u.test(ageValue) || !Number.isInteger(numericAge) || numericAge < 5 || numericAge > 100) {
288:       return { error: csvError("invalid_age", `L'âge « ${ageValue} » doit être un nombre entier entre 5 et 100.`, row) };
289:     }
290:     age = String(numericAge);
291:   }
292: 
293:   const boundedFields = [
294:     ["discipline principale", getCell(cells, columns, "mainDiscipline")],
295:     ["groupe", getCell(cells, columns, "group")],
296:     ["niveau", getCell(cells, columns, "level")],
297:   ];
298:   const oversized = boundedFields.find(([, value]) => value.length > limits.maxTextValueLength);
299:   if (oversized) {
300:     return { error: csvError("value_too_long", `La valeur « ${oversized[0]} » dépasse ${limits.maxTextValueLength} caractères.`, row) };
301:   }
302: 
303:   const secondaryDisciplines = getCell(cells, columns, "secondaryDisciplines")
304:     .split(/[,|]/gu)
305:     .map((value) => cleanField(value))
306:     .filter(Boolean);
307:   if (secondaryDisciplines.length > limits.maxSecondaryDisciplines) {
308:     return { error: csvError("too_many_secondary_disciplines", `Maximum ${limits.maxSecondaryDisciplines} disciplines secondaires par athlète.`, row) };
309:   }
310:   if (secondaryDisciplines.some((value) => value.length > limits.maxTextValueLength)) {
311:     return { error: csvError("value_too_long", `Chaque discipline secondaire est limitée à ${limits.maxTextValueLength} caractères.`, row) };
312:   }
313: 
314:   return {
315:     athlete: {
316:       name,
317:       email,
318:       age,
319:       mainDiscipline: boundedFields[0][1],
320:       secondaryDisciplines: secondaryDisciplines.join(", "),
321:       group: boundedFields[1][1],
322:       level: boundedFields[2][1],
323:       ...DEFAULT_PROFILE,
324:     },
325:   };
326: }
