328: /**
329:  * Analyse un CSV d'athlètes. Les erreurs de ligne n'empêchent pas l'import des
330:  * autres lignes ; les erreurs fatales (structure/limites) bloquent tout import.
331:  */
332: export function parseAthleteCsv(source, options = {}) {
333:   const limits = { ...ATHLETE_CSV_LIMITS, ...(options.limits ?? {}) };
334:   let text = String(source ?? "").replace(/^\uFEFF/u, "");
335: 
336:   if (!text.trim()) {
337:     return emptyResult([csvError("empty_file", "Le fichier CSV est vide.")]);
338:   }
339:   if (text.length > limits.maxCharacters) {
340:     return emptyResult([csvError(
341:       "content_too_large",
342:       `Le contenu dépasse la limite de ${limits.maxCharacters.toLocaleString("fr-BE")} caractères.`,
343:     )]);
344:   }
345: 
346:   // Certains exports Excel européens ajoutent une ligne « sep=; ». Elle ne
347:   // contient aucune donnée et sert seulement à indiquer le séparateur.
348:   const separatorHint = text.match(/^sep=([;,])(?:\r\n|\n|\r)/iu);
349:   const delimiter = separatorHint?.[1] ?? detectDelimiter(text);
350:   const startingLine = separatorHint ? 2 : 1;
351:   if (separatorHint) text = text.slice(separatorHint[0].length);
352:   if (!text.trim()) {
353:     return emptyResult([csvError("empty_file", "Le fichier CSV ne contient aucune donnée.")], delimiter);
354:   }
355: 
356:   const { rows, fatalError } = tokenizeCsv(text, delimiter, limits, startingLine);
357:   if (fatalError) return emptyResult([fatalError], delimiter);
358:   if (!rows.length) return emptyResult([csvError("empty_file", "Le fichier CSV est vide.")], delimiter);
359: 
360:   const [header, ...dataRows] = rows;
361:   const { columns, ignoredHeaders, fatalErrors } = resolveHeaders(header.cells, header.row);
362:   if (fatalErrors.length) {
363:     return emptyResult(fatalErrors, delimiter, { totalRows: dataRows.length, ignoredHeaders });
364:   }
365:   if (dataRows.length > limits.maxDataRows) {
366:     return emptyResult([csvError(
367:       "too_many_rows",
368:       `Le fichier contient ${dataRows.length} lignes : la limite est de ${limits.maxDataRows} athlètes par import.`,
369:     )], delimiter, { totalRows: dataRows.length, ignoredHeaders });
370:   }
371: 
372:   const errors = [];
373:   const entries = [];
374:   const seenEmails = new Set(
375:     (options.existingEmails ?? []).map((email) => cleanField(email).toLowerCase()).filter(Boolean),
376:   );
377:   let duplicateRows = 0;
378: 
379:   dataRows.forEach(({ cells, row }) => {
380:     const { athlete, error } = buildAthlete(cells, columns, row, limits);
381:     if (error) {
382:       errors.push(error);
383:       return;
384:     }
385: 
386:     if (athlete.email && seenEmails.has(athlete.email)) {
387:       duplicateRows += 1;
388:       errors.push(csvError(
389:         "duplicate_email",
390:         `L'adresse « ${athlete.email} » est déjà utilisée ; cette ligne a été ignorée.`,
391:         row,
392:       ));
393:       return;
394:     }
395: 
396:     if (athlete.email) seenEmails.add(athlete.email);
397:     entries.push({ row, athlete });
398:   });
399: 
400:   const warnings = ignoredHeaders.length
401:     ? [{
402:         code: "ignored_headers",
403:         message: `Colonnes non reconnues et ignorées : ${ignoredHeaders.join(", ")}.`,
404:       }]
405:     : [];
406: 
407:   return {
408:     athletes: entries.map(({ athlete }) => athlete),
409:     entries,
410:     errors,
411:     fatalErrors: [],
412:     warnings,
413:     canImport: entries.length > 0,
414:     meta: {
415:       delimiter,
416:       totalRows: dataRows.length,
417:       validRows: entries.length,
418:       invalidRows: errors.length,
419:       duplicateRows,
420:       ignoredHeaders,
421:     },
422:   };
423: }
424: 
425: export function validateAthleteCsvFile(file, limits = ATHLETE_CSV_LIMITS) {
426:   if (!file) return csvError("missing_file", "Choisis un fichier CSV.");
427:   const fileName = String(file.name ?? "").toLowerCase();
428:   if (!fileName.endsWith(".csv")) {
429:     return csvError("invalid_file_type", "Format non pris en charge : choisis un fichier .csv (pas un fichier Excel .xlsx).");
430:   }
431:   if (!file.size) return csvError("empty_file", "Le fichier CSV est vide.");
432:   if (file.size > limits.maxFileBytes) {
433:     return csvError("file_too_large", `Le fichier dépasse la limite de ${Math.round(limits.maxFileBytes / 1024 / 1024)} Mo.`);
434:   }
435:   return null;
436: }
