440:     "Nom complet;Email;Âge;Discipline principale;Disciplines secondaires;Groupe;Niveau",
441:     "Nora Vandenberghe;nora@example.com;21;100 m;200 m | 4 × 100 m;Sprint;National",
442:     "Liam Dubois;liam@example.com;19;Saut en longueur;;Sauts;Régional",
443:   ].join("\r\n");
444: }
