446: /** Convertit le numéro ordinal du payload RPC vers la vraie ligne du CSV. */
447: export function getAthleteCsvImportError(error, sourceRows = []) {
448:   const rawMessage = typeof error?.message === "string" && error.message.trim()
449:     ? error.message.trim()
450:     : "L'import a été refusé par le serveur. Vérifie le fichier puis réessaie.";
451:   const message = rawMessage.replace(/\bLigne\s+(\d+)\b/giu, (match, ordinalText) => {
452:     const ordinal = Number(ordinalText);
453:     const csvRow = sourceRows[ordinal - 1];
454:     return Number.isInteger(csvRow) && csvRow > 0 ? `Ligne ${csvRow} du CSV` : match;
455:   });
456:   return new Error(message);
