 8: export function getISOWeek(date) {
 9:   return getISOWeekInfo(date).week;
10: }
11: 
12: export function getISOWeekYear(date) {
13:   return getISOWeekInfo(date).year;
14: }
15: 
16: export function getISOWeekInfo(date) {
17:   const localDate = new Date(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()));
18:   const isoDay = localDate.getUTCDay() || 7;
19:   const monday = new Date(localDate);
20:   monday.setUTCDate(monday.getUTCDate() - isoDay + 1);
21:   const sunday = new Date(monday);
22:   sunday.setUTCDate(sunday.getUTCDate() + 6);
23:   const d = new Date(localDate);
24:   d.setUTCDate(d.getUTCDate() - (d.getUTCDay() + 6) % 7 + 3);
25:   const jan4 = new Date(Date.UTC(d.getUTCFullYear(), 0, 4));
26:   return {
27:     week: 1 + Math.round((d - jan4) / (7 * 24 * 60 * 60 * 1000)),
28:     year: d.getUTCFullYear(),
29:     startDate: monday.toISOString().slice(0, 10),
30:     endDate: sunday.toISOString().slice(0, 10),
31:   };
32: }
33: 
34: export function parseLocalDate(s) {
35:   const [y, m, d] = s.split("-").map(Number);
36:   return new Date(y, m - 1, d);
37: }
38: 
39: export function matchesISOWeek(row, week, year) {
40:   if (!row) return false;
41:   const explicitYear = Number(row.isoYear ?? row.iso_year);
42:   const explicitWeek = Number(row.week);
43:   if (Number.isInteger(explicitWeek) && explicitWeek !== week) return false;
44:   if (Number.isInteger(explicitYear)) {
45:     return explicitYear === year && (!Number.isInteger(explicitWeek) || explicitWeek === week);
46:   }
47: 
48:   const dateValue = row.sessionDate ?? row.session_date ?? row.date ?? row.loadDate ?? row.load_date;
49:   if (typeof dateValue === "string" && /^\d{4}-\d{2}-\d{2}/.test(dateValue)) {
50:     const info = getISOWeekInfo(parseLocalDate(dateValue.slice(0, 10)));
51:     return info.week === week && info.year === year;
52:   }
53:   return Number.isInteger(explicitWeek) && explicitWeek === week;
54: }
