14: async function replaceDatabaseSubscription(supabaseClient, subscription, identity) {
15:   const payload = subscriptionPayload(subscription, identity);
16:   await supabaseClient.from("push_subscriptions").delete().eq("endpoint", payload.endpoint);
17:   const { error } = await supabaseClient.from("push_subscriptions").insert(payload);
18:   return { error, payload };
19: }
