21: // Réattribue l'abonnement du navigateur au compte courant. Si un ancien compte
22: // possède encore le même endpoint et que la RLS empêche sa suppression, on
23: // révoque cet endpoint côté push puis on en crée un nouveau : l'ancien compte
24: // ne peut ainsi plus recevoir de notification sur cet appareil partagé.
25: export async function persistCurrentPushSubscription({
26:   supabaseClient,
27:   registration,
28:   subscription,
29:   applicationServerKey,
30:   clubId,
31:   athleteId = null,
32:   userId = null,
33: }) {
34:   const identity = { clubId, athleteId, userId };
35:   let current = subscription;
36:   let result = await replaceDatabaseSubscription(supabaseClient, current, identity);
37: 
38:   if (result.error?.code === "23505" && applicationServerKey) {
39:     await current.unsubscribe();
40:     current = await registration.pushManager.subscribe({
41:       userVisibleOnly: true,
42:       applicationServerKey,
43:     });
44:     result = await replaceDatabaseSubscription(supabaseClient, current, identity);
45:   }
46: 
47:   return { subscription: current, error: result.error ?? null };
48: }
