50: // À appeler avant supabase.auth.signOut(), tant que la RLS reconnaît encore
51: // le propriétaire de la ligne. Même si la suppression DB échoue, la révocation
52: // navigateur invalide l'endpoint ; send-push le nettoiera ensuite sur 404/410.
53: export async function revokeCurrentPushSubscription(supabaseClient, serviceWorkerContainer = navigator.serviceWorker) {
54:   if (!serviceWorkerContainer?.getRegistration) return { found: false, databaseError: null, browserRevoked: false };
55: 
56:   const registration = await serviceWorkerContainer.getRegistration();
57:   const subscription = await registration?.pushManager?.getSubscription();
58:   if (!subscription) return { found: false, databaseError: null, browserRevoked: false };
59: 
60:   const endpoint = subscription.endpoint ?? subscription.toJSON?.().endpoint;
61:   let databaseError = null;
62:   if (endpoint) {
63:     const result = await supabaseClient.from("push_subscriptions").delete().eq("endpoint", endpoint);
64:     databaseError = result.error ?? null;
65:   }
66: 
67:   const browserRevoked = await subscription.unsubscribe();
68:   return { found: true, databaseError, browserRevoked };
69: } 1: import { describe, expect, it, vi } from "vitest";
