84: }); 1: export type IsoWeekContext = {
 2:   week: number;
 3:   year: number;
 4:   key: string;
 5:   startDate: string;
 6:   endDate: string;
 7: };
 8: 
 9: const DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;
10: 
11: function formatUtcDate(date: Date): string {
12:   return date.toISOString().slice(0, 10);
13: }
14: 
15: export function localDateInTimeZone(now: Date, timeZone: string): string {
16:   return new Intl.DateTimeFormat("en-CA", {
17:     timeZone,
18:     year: "numeric",
19:     month: "2-digit",
20:     day: "2-digit",
21:   }).format(now);
22: }
23: 
24: export function getIsoWeekContext(localDate: string): IsoWeekContext {
25:   if (!DATE_PATTERN.test(localDate)) throw new Error("Date locale invalide.");
26:   const date = new Date(`${localDate}T12:00:00.000Z`);
27:   if (Number.isNaN(date.getTime())) throw new Error("Date locale invalide.");
28: 
29:   const isoDay = date.getUTCDay() || 7;
30:   const monday = new Date(date);
31:   monday.setUTCDate(monday.getUTCDate() - isoDay + 1);
32:   const sunday = new Date(monday);
33:   sunday.setUTCDate(sunday.getUTCDate() + 6);
34: 
35:   const thursday = new Date(date);
36:   thursday.setUTCDate(thursday.getUTCDate() + 4 - isoDay);
37:   const year = thursday.getUTCFullYear();
38:   const yearStart = new Date(Date.UTC(year, 0, 1));
39:   const week = Math.ceil((((thursday.getTime() - yearStart.getTime()) / 86_400_000) + 1) / 7);
40: 
41:   return {
42:     week,
43:     year,
44:     key: `${year}-W${String(week).padStart(2, "0")}`,
45:     startDate: formatUtcDate(monday),
46:     endDate: formatUtcDate(sunday),
47:   };
48: }  1: // ============================================================
  2: // AthleteOS — supabase/functions/send-push/index.ts
  3: //
  4: // Sécurité (tâche 2) : cette fonction utilise la clé service_role, qui
  5: // contourne toute RLS — la protection doit donc être entièrement gérée
  6: // ici, en code applicatif :
  7: //   - Chemin cron (weekly-cron) : Authorization = Bearer <SERVICE_ROLE_KEY>,
  8: //     déjà vérifié en amont par weekly-cron/index.ts. Accès total,
  9: //     inchangé.
 10: //   - Chemin utilisateur (app) : JWT extrait du header Authorization,
 11: //     résolu vers users(id, club_id, role) comme le fait déjà
 12: //     admin-actions/index.ts. Les destinataires (athleteIds/userIds)
 13: //     envoyés par le client ne sont JAMAIS utilisés tels quels : ils
 14: //     sont re-résolus côté serveur contre le club de l'appelant.
 15: //     - athleteIds : toujours limité aux athlètes du club de l'appelant
 16: //       (coach ou athlete) — un athlète a des cas d'usage légitimes vers
 17: //       d'autres athlètes de son club (post club diffusé à l'équipe via
 18: //       notifyClubNewPost, messagerie inter-athlètes via
 19: //       notifyAthleteMessage) et vers lui-même (récap hebdo). La seule
 20: //       limite pour ce vecteur est le club, pas le rôle.
 21: //     - userIds : head_coach/coach peuvent cibler n'importe quel user de
 22: //       leur club ; athlete uniquement les coachs (head_coach/coach) de
 23: //       son club (cas du message à son coach) — jamais un autre athlète
 24: //       par ce vecteur.
 25: // ============================================================
