 33: const MAX_MESSAGE_LEN         = 500;
 34: const MAX_TAG_LEN             = 100;
 35: const MAX_URL_LEN             = 200;
 36: const MAX_REQUESTED_RECIPIENTS = 300; // largement au-dessus de la taille d'un club réel
