 40: // Origines autorisées pour les appels navigateur (CORS). Domaine de
 41: // production connu inclus par défaut (URL publique, pas un secret) + ports
 42: // Vite locaux pour le dev. Surchargeable/complétable sans redéploiement via
 43: // la variable d'env ALLOWED_ORIGINS (liste séparée par des virgules) dans
 44: // les secrets de la fonction Supabase — utile si un autre domaine
 45: // (custom domain, preview Vercel...) doit être ajouté plus tard.
 46: const DEFAULT_ALLOWED_ORIGINS = [
 47:   "https://athleteos-by-samuelmuhadri.vercel.app",
 48:   "http://localhost:5173",
 49:   "http://localhost:4173",
 50:   "http://127.0.0.1:5173",
 51:   "http://127.0.0.1:4173",
 52: ];
 53: const configuredOrigins = (Deno.env.get("ALLOWED_ORIGINS") ?? "")
 54:   .split(",")
 55:   .map((o) => o.trim())
 56:   .filter(Boolean);
 57: // Additif, pas un remplacement : ALLOWED_ORIGINS sert à AJOUTER un domaine
 58: // (custom domain, preview...), pas à retirer le domaine de prod par défaut.
 59: const allowedOrigins = [...new Set([...DEFAULT_ALLOWED_ORIGINS, ...configuredOrigins])];
