 61: function corsHeaders(origin: string | null): Record<string, string> {
 62:   const headers: Record<string, string> = {
 63:     "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
 64:     "Access-Control-Allow-Methods": "POST, OPTIONS",
 65:   };
 66:   // Pas d'Origin (appel serveur à serveur, ex. weekly-cron) : pas concerné
 67:   // par CORS, on ne pose pas l'en-tête. Origin présent : on ne l'autorise
 68:   // que s'il est dans la liste configurée.
