 76: function json(status: number, origin: string | null, body: Record<string, unknown>) {
 77:   return new Response(JSON.stringify(body), {
 78:     status,
 79:     headers: { ...corsHeaders(origin), "Content-Type": "application/json" },
 80:   });
 81: }
