 85: function toPositiveIntArray(value: unknown): number[] {
 86:   if (!Array.isArray(value)) return [];
 87:   const out = new Set<number>();
 88:   for (const v of value) {
 89:     const n = Number(v);
 90:     if (Number.isInteger(n) && n > 0) out.add(n);
 91:   }
 92:   return [...out];
 93: }
