 12: const MAX_BODY_BYTES = 2_000;
 13: 
 14: function computeWeeklyStats(athleteId: number, sessions: Session[]) {
 15:   const relevant = sessions.filter((session) => session.athleteIds.includes(athleteId));
 16:   let done = 0;
 17:   let partial = 0;
 18:   let none = 0;
 19:   for (const session of relevant) {
 20:     const validation = session.validations.find((row) => row.athleteId === athleteId);
 21:     if (validation?.status === "done") done += 1;
 22:     else if (validation?.status === "partial") partial += 1;
 23:     else if (validation?.status === "none") none += 1;
 24:   }
 25:   return { total: relevant.length, done, partial, none };
 26: }
