 28: async function requireData<T>(
 29:   request: PromiseLike<{ data: T | null; error: { message: string } | null }>,
 30:   operation: string,
 31: ): Promise<T> {
 32:   const { data, error } = await request;
 33:   if (error) throw new Error(`${operation}: ${error.message}`);
 34:   return data as T;
 35: }
