 37: async function sendPush(
 38:   supabaseUrl: string,
 39:   serviceKey: string,
 40:   payload: { title: string; body: string; tag: string },
 41:   athleteIds: number[],
 42:   userIds: number[],
 43:   dryRun: boolean,
 44:   log: string[],
 45: ) {
 46:   log.push(`push athletes=${athleteIds.length} users=${userIds.length} tag=${payload.tag}`);
 47:   if (dryRun) return;
 48:   const response = await fetch(`${supabaseUrl}/functions/v1/send-push`, {
 49:     method: "POST",
 50:     headers: { "Content-Type": "application/json", "Authorization": `Bearer ${serviceKey}` },
 51:     body: JSON.stringify({ athleteIds, userIds, ...payload }),
 52:   });
 53:   if (!response.ok) {
 54:     const requestId = response.headers.get("x-request-id") ?? "unknown";
 55:     throw new Error(`send-push HTTP ${response.status}, request=${requestId}`);
 56:   }
 57: }
