245:       if (!dryRun) {
246:         insertedReports = await requireData<typeof athleteReportRows>(
247:           admin.from("athlete_notifications")
248:             .upsert(athleteReportRows, { onConflict: "athlete_id,type,dedupe_key", ignoreDuplicates: true })
249:             .select("athlete_id, club_id, type, title, description, is_read, dedupe_key"),
250:           "création rapports athlètes",
251:         ) ?? [];
252:       }
253:       for (const row of insertedReports) {
254:         await sendPush(
255:           supabaseUrl,
256:           serviceKey,
257:           { title: row.title, body: row.description, tag: row.dedupe_key },
258:           [row.athlete_id],
259:           [],
260:           dryRun,
261:           log,
262:         );
263:       }
264: 
265:       clubSummaries.push({ athletes: athletes.length });
266:     }
267: 
268:     return new Response(JSON.stringify({
269:       ok: true,
270:       dryRun,
271:       week: week.key,
272:       clubsProcessed: clubSummaries.length,
273:       clubSummaries,
274:       log,
275:     }), { headers: { "Content-Type": "application/json" } });
276:   } catch (error) {
277:     console.error("weekly-cron error:", error instanceof Error ? error.message : error);
278:     return new Response(JSON.stringify({ error: "weekly_cron_failed", week: week.key }), {
279:       status: 500,
280:       headers: { "Content-Type": "application/json" },
281:     });
282:   }
283: }); 1: BEGIN;
