 3: -- ============================================================
 4: -- Tâche 5 — reproductibilité complète depuis zéro : compléments au socle
 5: --
 6: -- En comparant systématiquement le socle de la tâche 7
 7: -- (20260720000000) à l'inventaire réel de la base distante (index,
 8: -- triggers, event triggers — via `supabase db query --linked`, lecture
 9: -- seule), deux écarts trouvés : des index de performance jamais
10: -- versionnés, et l'event trigger `ensure_rls` (qui appelle
11: -- `rls_auto_enable()`, déjà recréée dans le socle, mais jamais
12: -- enregistrée comme trigger). Aucun des deux n'empêchait les tests RLS
13: -- de passer (d'où l'écart non détecté à la tâche 7), mais leur absence
14: -- viole la Definition of Done de la tâche 5 : "le schéma généré
15: -- correspond aux besoins du code" et "recréés de façon déterministe".
16: -- ============================================================
17: 
18: -- Index de performance manquants du socle (confirmés un par un contre
19: -- la base réelle via pg_indexes — pas de clé primaire/unique manquante,
20: -- celles-ci sont déjà couvertes par les contraintes du socle).
21: CREATE INDEX IF NOT EXISTS athlete_notifications_athlete_id_is_read_idx
22:   ON public.athlete_notifications (athlete_id, is_read);
23: CREATE INDEX IF NOT EXISTS athlete_notifications_club_id_created_at_idx
24:   ON public.athlete_notifications (club_id, created_at DESC);
25: CREATE INDEX IF NOT EXISTS athlete_performances_athlete_id_discipline_idx
26:   ON public.athlete_performances (athlete_id, discipline);
27: CREATE INDEX IF NOT EXISTS athlete_performances_club_id_idx
28:   ON public.athlete_performances (club_id);
29: CREATE INDEX IF NOT EXISTS idx_push_subs_athlete
30:   ON public.push_subscriptions (athlete_id);
31: 
32: -- Event trigger réel en production : chaque nouvelle table créée dans
33: -- public reçoit automatiquement RLS activée, sans y penser à chaque
34: -- migration. Absent du socle (seule la fonction rls_auto_enable() y
35: -- était) — sans lui, une future table créée par un développeur qui
36: -- oublierait le ENABLE ROW LEVEL SECURITY resterait ouverte en local
37: -- alors qu'elle serait protégée en production (comportement différent,
38: -- contraire à l'objectif "reproductible depuis zéro" de cette tâche).
39: -- Filtre WHEN confirmé identique à la production (pg_event_trigger.evttags).
40: DROP EVENT TRIGGER IF EXISTS ensure_rls;
41: CREATE EVENT TRIGGER ensure_rls
42:   ON ddl_command_end
43:   WHEN tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
44:   EXECUTE FUNCTION public.rls_auto_enable();
45: 
46: COMMIT; 1: BEGIN;
