 3: -- ============================================================
 4: -- Tâche 18 — versionner les poids du profil de charge à 6 axes
 5: --
 6: -- Même problème que les coefficients de charge (tâche 16, voir
 7: -- charge_model_versions) : AXIS_WEIGHTS (poids catégorie -> axe) était
 8: -- codé en dur dans src/utils/loadAxes.js, sans version ni audit. Contrairement
 9: -- à LOAD_COEFFICIENTS, ces poids ne sont dupliqués nulle part en SQL (le
10: -- profil à 6 axes est 100% calculé côté client — voir le commentaire en
11: -- tête de loadAxes.js) : pas de risque de divergence JS/SQL à corriger ici,
12: -- mais le même besoin de gouvernance (versionné, borné, audité, "convention
13: -- AthleteOS" explicite) s'applique.
14: --
15: -- Portée volontairement limitée : cette migration crée la table
16: -- canonique et ses garde-fous, pas un écran de configuration par club —
17: -- tant qu'aucun écran coach n'existe pour créer une nouvelle version,
18: -- une seule version active = mode par défaut verrouillé pour le pilote.
19: -- ============================================================
20: 
21: CREATE TABLE public.axis_model_versions (
22:   version      text PRIMARY KEY,
23:   axis_weights jsonb NOT NULL,  -- { categorie: { axe: poids (0-1), ... }, ... }
24:   is_active    boolean NOT NULL DEFAULT false,
25:   notes        text,
26:   created_at   timestamptz NOT NULL DEFAULT now(),
27:   created_by   text  -- users.id de l'auteur, une fois qu'un écran d'édition existera. NULL pour les versions créées hors app.
28: );
29: 
30: CREATE UNIQUE INDEX axis_model_versions_single_active
31:   ON public.axis_model_versions (is_active)
32:   WHERE is_active;
33: 
34: ALTER TABLE public.axis_model_versions ENABLE ROW LEVEL SECURITY;
35: CREATE POLICY "axis_model_versions_read" ON public.axis_model_versions
36:   FOR SELECT TO authenticated USING (true);
37: GRANT SELECT ON public.axis_model_versions TO authenticated;
38: -- Pas de policy d'écriture pour authenticated — même raison que
39: -- charge_model_versions (migration 20260727040000) : pas d'écran coach
40: -- encore construit pour créer une version.
41: 
42: -- Bornes : chaque poids doit être un nombre entre 0 et 1 (0 = catégorie
43: -- n'affecte pas cet axe, 1 = affecte l'axe à pleine intensité relative).
44: CREATE OR REPLACE FUNCTION public.validate_axis_model_version()
45: RETURNS trigger
46: LANGUAGE plpgsql
47: AS $$
48: DECLARE
49:   cat      text;
50:   cat_val  jsonb;
51:   axis     text;
52:   axis_val jsonb;
53:   n        numeric;
54: BEGIN
55:   FOR cat, cat_val IN SELECT * FROM jsonb_each(NEW.axis_weights) LOOP
56:     IF jsonb_typeof(cat_val) <> 'object' THEN
57:       RAISE EXCEPTION 'axis_weights.% doit être un objet {axe: poids} (reçu: %)', cat, jsonb_typeof(cat_val);
58:     END IF;
59:     FOR axis, axis_val IN SELECT * FROM jsonb_each(cat_val) LOOP
60:       IF jsonb_typeof(axis_val) <> 'number' THEN
61:         RAISE EXCEPTION 'axis_weights.%.% doit être un nombre (reçu: %)', cat, axis, jsonb_typeof(axis_val);
62:       END IF;
63:       n := (axis_val#>>'{}')::numeric;
64:       IF n < 0 OR n > 1 THEN
65:         RAISE EXCEPTION 'axis_weights.%.% doit être entre 0 et 1 (reçu: %)', cat, axis, n;
66:       END IF;
67:     END LOOP;
68:   END LOOP;
69:   RETURN NEW;
70: END;
71: $$;
72: 
73: CREATE TRIGGER axis_model_versions_validate
74:   BEFORE INSERT OR UPDATE ON public.axis_model_versions
75:   FOR EACH ROW EXECUTE FUNCTION public.validate_axis_model_version();
76: 
