89:     "technique":    {"neuromuscular":0.3, "elastic":0.3, "metabolic":0.2, "muscular":0.2, "technical":1.0, "mental":0.3},
90:     "mobilite":     {"neuromuscular":0.1, "elastic":0.2, "metabolic":0.1, "muscular":0.1, "technical":0.2, "mental":0.2},
91:     "recuperation": {"neuromuscular":0.05,"elastic":0.05,"metabolic":0.1, "muscular":0.05,"technical":0.05,"mental":0.1}
