  3: -- ============================================================
  4: -- Tâche 6 — audit RLS/grants/vues/fonctions par rôle
  5: --
  6: -- Constat principal (base réelle inspectée en lecture seule via
  7: -- `supabase db query --linked`, pas seulement les migrations locales —
  8: -- la table `users` porte une colonne `auth_id` (uuid) totalement morte,
  9: -- jamais écrite par aucun code applicatif (grep sur src/ et
 10: -- supabase/functions/ : zéro résultat), reliquat d'avant le passage au
 11: -- système actuel basé sur `auth_uid` (text).
 12: --
 13: -- Une policy "Club members only" (FOR ALL, roles public) sur `users`
 14: -- n'a jamais été supprimée et utilise encore `auth_id = auth.uid()`.
 15: -- Comme les policies RLS permissives se combinent en OR (pas en AND),
 16: -- cette policy s'ajoute à users_insert_by_coach/users_update_self au
 17: -- lieu de les remplacer : un compte authentifié quelconque peut
 18: -- s'insérer une ligne `users` avec `auth_id = auth.uid()` (sa propre
 19: -- valeur), et n'importe quel `club_id`/`role` — ce qui contourne
 20: -- entièrement le contrôle "coach de CE club uniquement" de
 21: -- users_insert_by_coach. Une fois cette ligne insérée, elle réactive
 22: -- aussi les policies "Club members only" identiques (mais jusqu'ici
 23: -- mortes, car elles dépendent de la même colonne `auth_id`) sur alerts,
 24: -- athletes, clubs, competition_athletes, competition_results,
 25: -- competitions, injuries, messages, performance_history, records,
 26: -- session_athletes, sessions — donnant accès en lecture/écriture à
 27: -- N'IMPORTE QUEL club. Un athlète peut aussi, plus simplement, changer
 28: -- SON PROPRE rôle en tête via users_update_self (aucune colonne n'y est
 29: -- protégée).
 30: --
 31: -- Correctif : supprime la policy dangereuse + ses 12 équivalentes
 32: -- mortes-mais-dormantes sur les autres tables (chaque table ne garde
 33: -- plus qu'un seul jeu de policies, actif et documenté), et verrouille
 34: -- `role`/`club_id` contre toute auto-modification (trigger, service_role
 35: -- uniquement).
 36: -- ============================================================
 37: 
 38: -- 1) Nettoyage des policies héritées mortes/dangereuses (aucune n'a de
 39: --    raison de coexister avec les policies "_club" actuelles — chaque
 40: --    table ne doit avoir qu'un seul propriétaire de policy documenté,
 41: --    cf. DoD tâche 6).
 42: DROP POLICY IF EXISTS "Club members only" ON public.alerts;
 43: DROP POLICY IF EXISTS "Club members only" ON public.athletes;
 44: DROP POLICY IF EXISTS "Club members only" ON public.clubs;
 45: DROP POLICY IF EXISTS "Club members only" ON public.competition_athletes;
 46: DROP POLICY IF EXISTS "Club members only" ON public.competition_results;
 47: DROP POLICY IF EXISTS "Club members only" ON public.competitions;
 48: DROP POLICY IF EXISTS "Club members only" ON public.injuries;
 49: DROP POLICY IF EXISTS "Club members only" ON public.messages;
 50: DROP POLICY IF EXISTS "Club members only" ON public.performance_history;
 51: DROP POLICY IF EXISTS "Club members only" ON public.records;
 52: DROP POLICY IF EXISTS "Club members only" ON public.session_athletes;
 53: DROP POLICY IF EXISTS "Club members only" ON public.sessions;
 54: DROP POLICY IF EXISTS "club members only" ON public.users;
 55: 
 56: -- 2) Nouveaux helpers, même convention que get_my_club_id() (SQL,
 57: --    STABLE, SECURITY DEFINER, search_path fixé) — nécessaires pour
 58: --    distinguer coach/athlète et retrouver sa propre ligne athletes/
 59: --    users sans dupliquer la sous-requête dans chaque policy.
 60: CREATE OR REPLACE FUNCTION public.get_my_role()
 61: RETURNS text
 62: LANGUAGE sql STABLE SECURITY DEFINER
 63: SET search_path TO 'public'
 64: AS $$
 65:   SELECT role FROM users
 66:   WHERE lower(trim(auth_uid)) = lower(trim(auth.uid()::text))
 67:   LIMIT 1;
 68: $$;
 69: 
 70: CREATE OR REPLACE FUNCTION public.get_my_user_id()
 71: RETURNS integer
 72: LANGUAGE sql STABLE SECURITY DEFINER
 73: SET search_path TO 'public'
 74: AS $$
 75:   SELECT id FROM users
 76:   WHERE lower(trim(auth_uid)) = lower(trim(auth.uid()::text))
 77:   LIMIT 1;
 78: $$;
 79: 
 80: CREATE OR REPLACE FUNCTION public.get_my_athlete_id()
 81: RETURNS integer
 82: LANGUAGE sql STABLE SECURITY DEFINER
 83: SET search_path TO 'public'
 84: AS $$
 85:   SELECT a.id FROM athletes a
 86:   JOIN users u ON u.id = a.user_id
 87:   WHERE lower(trim(u.auth_uid)) = lower(trim(auth.uid()::text))
 88:   LIMIT 1;
 89: $$;
 90: 
 91: REVOKE ALL ON FUNCTION public.get_my_role() FROM PUBLIC;
 92: REVOKE ALL ON FUNCTION public.get_my_user_id() FROM PUBLIC;
 93: REVOKE ALL ON FUNCTION public.get_my_athlete_id() FROM PUBLIC;
 94: GRANT EXECUTE ON FUNCTION public.get_my_role() TO authenticated;
 95: GRANT EXECUTE ON FUNCTION public.get_my_user_id() TO authenticated;
 96: GRANT EXECUTE ON FUNCTION public.get_my_athlete_id() TO authenticated;
 97: 
 98: -- get_my_club_id() n'a jamais besoin d'être appelée par anon (anon n'a
 99: -- pas de ligne dans `users`, la fonction renvoie toujours NULL pour ce
100: -- rôle) — advisor "authenticated/anon can execute SECURITY DEFINER".
101: REVOKE EXECUTE ON FUNCTION public.get_my_club_id() FROM anon;
102: 
103: -- 3) users : verrouille role/club_id contre l'auto-modification.
104: --    users_update_self (migration 20260725190500) autorise déjà la
105: --    modification de sa propre ligne sans restreindre les colonnes —
106: --    un athlète peut aujourd'hui se PATCHer role="head_coach" tout
107: --    seul. Un trigger (pas une policy) car RLS ne peut pas comparer
108: --    OLD/NEW colonne par colonne. Bloque uniquement les requêtes REST
109: --    d'un utilisateur connecté (auth.role() = 'authenticated') — laisse
110: --    passer service_role (Edge Functions/futur écran admin) ET le
111: --    contexte migration/SQL editor (auth.role() est alors NULL, hors
112: --    requête PostgREST), pour ne pas se piéger soi-même en dashboard.
113: CREATE OR REPLACE FUNCTION public.prevent_users_role_self_escalation()
114: RETURNS trigger
115: LANGUAGE plpgsql
116: SET search_path TO 'public'
117: AS $$
118: BEGIN
119:   IF auth.role() = 'authenticated' THEN
120:     IF NEW.role IS DISTINCT FROM OLD.role OR NEW.club_id IS DISTINCT FROM OLD.club_id THEN
121:       RAISE EXCEPTION 'role et club_id ne peuvent être modifiés que par service_role';
122:     END IF;
123:   END IF;
124:   RETURN NEW;
125: END;
126: $$;
127: 
128: DROP TRIGGER IF EXISTS users_prevent_role_self_escalation ON public.users;
129: CREATE TRIGGER users_prevent_role_self_escalation
130:   BEFORE UPDATE ON public.users
131:   FOR EACH ROW EXECUTE FUNCTION public.prevent_users_role_self_escalation();
132: 
133: -- users_insert_by_coach (migration 20260725190500) laissait un coach
134: -- (pas head_coach) créer une ligne avec n'importe quel rôle, y compris
135: -- head_coach/coach, dans son propre club — vérifié dans AthleteList.jsx :
136: -- le seul insert coach->users existant pose toujours role="athlete",
137: -- donc resserrer ne casse rien de réel.
138: DROP POLICY IF EXISTS "users_insert_by_coach" ON public.users;
139: CREATE POLICY "users_insert_by_coach" ON public.users
140:   FOR INSERT TO public
141:   WITH CHECK (
142:     club_id = get_my_club_id()
143:     AND get_my_role() IN ('head_coach','coach')
144:     AND (role = 'athlete' OR get_my_role() = 'head_coach')
145:   );
146: 
147: -- 4) athlete_wellness : coach voit tout le club (Rapports.jsx),
148: --    l'athlète ne voit/écrit que ses propres entrées (WellnessModal.jsx,
149: --    AthleteApp.jsx) — plus d'accès entre coéquipiers.
150: DROP POLICY IF EXISTS "athlete_wellness_club" ON public.athlete_wellness;
151: 
152: CREATE POLICY "athlete_wellness_coach_read" ON public.athlete_wellness
153:   FOR SELECT TO public
154:   USING (club_id = get_my_club_id() AND get_my_role() IN ('head_coach','coach'));
155: 
156: CREATE POLICY "athlete_wellness_self" ON public.athlete_wellness
157:   FOR ALL TO public
158:   USING (athlete_id = get_my_athlete_id())
159:   WITH CHECK (athlete_id = get_my_athlete_id() AND club_id = get_my_club_id());
160: 
161: -- 5) injuries (données médicales) : coach = CRUD sur tout le club
162: --    (AthleteList.jsx : addInjury/updateInjury/deleteInjury sur tous les
163: --    athleteIds du club) ; athlète = lecture + signalement de ses
164: --    propres blessures uniquement (AthleteApp.jsx, InjuryReportModal.jsx),
165: --    jamais les blessures d'un coéquipier.
166: DROP POLICY IF EXISTS "injuries_club" ON public.injuries;
167: 
168: CREATE POLICY "injuries_coach_all" ON public.injuries
169:   FOR ALL TO public
170:   USING (
171:     get_my_role() IN ('head_coach','coach')
172:     AND EXISTS (SELECT 1 FROM athletes a WHERE a.id = injuries.athlete_id AND a.club_id = get_my_club_id())
173:   )
174:   WITH CHECK (
175:     get_my_role() IN ('head_coach','coach')
176:     AND EXISTS (SELECT 1 FROM athletes a WHERE a.id = injuries.athlete_id AND a.club_id = get_my_club_id())
177:   );
178: 
179: CREATE POLICY "injuries_athlete_read_own" ON public.injuries
180:   FOR SELECT TO public
181:   USING (athlete_id = get_my_athlete_id());
182: 
183: CREATE POLICY "injuries_athlete_insert_own" ON public.injuries
184:   FOR INSERT TO public
185:   WITH CHECK (athlete_id = get_my_athlete_id());
186: 
187: -- 6) push_subscriptions : chacun ne gère que son propre abonnement
188: --    (athlete_id pour un athlète, user_id pour un coach — les deux
189: --    colonnes sont posées par usePushNotifications.jsx selon le rôle).
190: --    L'envoi réel (send-push, weekly-cron) passe par service_role et
191: --    n'est pas concerné par RLS.
192: DROP POLICY IF EXISTS "push_subscriptions_club" ON public.push_subscriptions;
193: 
194: CREATE POLICY "push_subscriptions_own" ON public.push_subscriptions
195:   FOR ALL TO public
196:   USING (
197:     (athlete_id IS NOT NULL AND athlete_id = get_my_athlete_id())
198:     OR (user_id IS NOT NULL AND user_id = get_my_user_id())
199:   )
200:   WITH CHECK (
201:     club_id = get_my_club_id()
202:     AND (
203:       (athlete_id IS NOT NULL AND athlete_id = get_my_athlete_id())
204:       OR (user_id IS NOT NULL AND user_id = get_my_user_id())
205:     )
206:   );
207: 
208: -- 7) anon : révoque les droits CRUD hérités par défaut sur les tables
209: --    métier (aucune page pré-connexion — Login/Signup/ResetPassword —
210: --    ne fait le moindre supabase.from(...) : signup passe par l'Edge
211: --    Function signup en service_role, login par supabase.auth). RLS
212: --    bloquait déjà anon en pratique (get_my_club_id() renvoie NULL sans
213: --    ligne users), mais laisser le GRANT grand ouvert est un filet de
214: --    sécurité en moins si une policy future devient trop permissive.
215: REVOKE INSERT, UPDATE, DELETE, SELECT ON ALL TABLES IN SCHEMA public FROM anon;
216: ALTER DEFAULT PRIVILEGES IN SCHEMA public
217:   REVOKE INSERT, UPDATE, DELETE, SELECT ON TABLES FROM anon;
218: 
219: -- 8) search_path non fixé sur les fonctions triggers ajoutées aux
220: --    tâches 16/18 (advisor "function_search_path_mutable", WARN).
221: ALTER FUNCTION public.validate_charge_model_version() SET search_path TO 'public';
222: ALTER FUNCTION public.validate_axis_model_version() SET search_path TO 'public';
223: ALTER FUNCTION public.stamp_session_athlete_model_version() SET search_path TO 'public';
224: 
225: COMMIT; 1: BEGIN;
