 3: -- ============================================================
 4: -- Tâche 4 — journal d'audit pour admin-actions
 5: --
 6: -- admin-actions/index.ts (renommage club, rotation code invitation,
 7: -- suppression de membre, changement de rôle) n'écrivait jusqu'ici aucune
 8: -- trace : impossible de savoir qui a fait quoi, quand, ni de distinguer
 9: -- une tentative refusée d'une action réussie. Sert aussi de registre
10: -- pour les clés d'idempotence (voir index unique plus bas) — un rejeu
11: -- de la même requête avec la même clé ne déclenche pas une seconde fois
12: -- l'effet, sans bloquer un nouvel essai après une erreur.
13: -- ============================================================
14: 
15: CREATE TABLE public.audit_logs (
16:   id              bigserial PRIMARY KEY,
17:   actor_user_id   integer REFERENCES public.users(id) ON DELETE SET NULL,
18:   actor_club_id   integer REFERENCES public.clubs(id) ON DELETE SET NULL,
19:   action          text NOT NULL,
20:   target_user_id  integer REFERENCES public.users(id) ON DELETE SET NULL,
21:   target_club_id  integer REFERENCES public.clubs(id) ON DELETE SET NULL,
22:   payload         jsonb,
23:   result          text NOT NULL CHECK (result IN ('success', 'denied', 'error')),
24:   error_message   text,
25:   idempotency_key text,
26:   created_at      timestamptz NOT NULL DEFAULT now()
27: );
28: 
29: -- Au plus UNE ligne "success" par (clé d'idempotence, action) : une
30: -- tentative refusée ou en erreur peut être rejouée (retry légitime),
31: -- mais un succès ne peut jamais être exécuté deux fois avec la même clé.
32: CREATE UNIQUE INDEX audit_logs_idempotency_success_idx
33:   ON public.audit_logs (idempotency_key, action)
34:   WHERE idempotency_key IS NOT NULL AND result = 'success';
35: 
36: CREATE INDEX audit_logs_actor_club_id_created_at_idx ON public.audit_logs (actor_club_id, created_at DESC);
37: CREATE INDEX audit_logs_idempotency_key_idx ON public.audit_logs (idempotency_key) WHERE idempotency_key IS NOT NULL;
38: 
39: ALTER TABLE public.audit_logs ENABLE ROW LEVEL SECURITY;
40: 
41: -- Lecture réservée au head coach de son propre club — un coach ou un
42: -- athlète n'a pas à voir qui a fait quoi (et surtout pas ce qui se passe
43: -- dans un autre club). Écriture : uniquement service_role (admin-actions),
44: -- aucune policy d'écriture cliente.
45: CREATE POLICY "audit_logs_head_coach_read" ON public.audit_logs
46:   FOR SELECT TO authenticated
47:   USING (actor_club_id = get_my_club_id() AND get_my_role() = 'head_coach');
48: 
49: REVOKE ALL ON public.audit_logs FROM anon;
50: GRANT SELECT ON public.audit_logs TO authenticated;
51: 
52: COMMIT;  1: BEGIN;
  2: 
  3: -- ============================================================
  4: -- Tâche 14 — compétitions et résultats transactionnels
  5: --
  6: -- Problème : Competitions.jsx (createCompetition/addResult) et
  7: -- AthletePerfs.jsx (handleAddComp) écrivent en plusieurs `insert`/`update`
  8: -- successifs depuis le client (compétition, puis lien athlète, puis
  9: -- résultat, puis performance, puis record), sans aucune garantie
 10: -- d'atomicité. Une panne réseau ou une erreur entre deux étapes laisse un
 11: -- état incohérent (compétition sans participant, résultat sans mise à
 12: -- jour de record, etc.) qu'il faut réparer à la main. Pire : dans
 13: -- addResult, si la mise à jour du record échoue, l'erreur est juste
 14: -- loguée (`console.error`) et le code continue quand même à envoyer les
 15: -- notifications — exactement "notification envoyée alors que l'écriture
 16: -- a échoué".
 17: --
 18: -- Un deuxième risque, non lié aux pannes : deux résultats battant le même
 19: -- record soumis à quelques millisecondes d'écart (deux onglets, un
 20: -- double-clic) peuvent tous les deux lire "pas de record existant" côté
 21: -- client et écraser le travail l'un de l'autre sans jamais se voir.
 22: --
 23: -- Solution : 3 RPC SQL (SECURITY DEFINER, transaction implicite d'une
 24: -- fonction Postgres — tout réussit ou rien n'est appliqué), avec
 25: -- verrouillage de ligne (`FOR UPDATE`) sur `records` pour rendre la
 26: -- comparaison/mise à jour du record sûre en cas de concurrence,
 27: -- idempotence via une clé fournie par le client, et un outbox de
 28: -- notifications écrit DANS la même transaction (jamais après un commit
 29: -- non garanti côté client).
 30: -- ============================================================
 31: 
 32: -- ── Colonnes numériques sur records : la comparaison "ce résultat bat-il
 33: --    le record" doit se faire EN SQL (verrou de ligne), sans réimplémenter
 34: --    parsePerf() côté serveur à chaque appel — le client (source de vérité
 35: --    unique, tâche 11) envoie déjà la valeur parsée en paramètre pour un
 36: --    NOUVEAU résultat ; il faut aussi connaître la valeur numérique du
 37: --    record déjà stocké pour comparer. ──────────────────────────────────
 38: ALTER TABLE public.records ADD COLUMN IF NOT EXISTS pr_value numeric;
 39: ALTER TABLE public.records ADD COLUMN IF NOT EXISTS sb_value numeric;
 40: 
 41: -- Nécessaire pour verrouiller/upserter une ligne records de façon sûre en
 42: -- cas de concurrence (voir _apply_competition_result plus bas) — confirmé
 43: -- au préalable qu'aucun doublon (athlete_id, discipline) n'existe déjà en
 44: -- base (lecture seule, `select ... group by ... having count(*) > 1`,
 45: -- zéro résultat).
 46: ALTER TABLE public.records ADD CONSTRAINT records_athlete_discipline_key UNIQUE (athlete_id, discipline);
 47: 
 48: -- Backfill unique, au moment de cette migration seulement : reproduit
 49: -- fidèlement parsePerf() (src/athlete/shared.js) — "1:02" style
 50: -- minutes:secondes, sinon nombre décimal. Utilisée UNE FOIS ici, jamais
 51: -- appelée par les RPC ci-dessous (qui reçoivent toujours la valeur déjà
 52: -- parsée du client — seule source de vérité pour ne pas dupliquer la
 53: -- règle de parsing, comme pour higherIsBetter).
 54: CREATE OR REPLACE FUNCTION public._backfill_parse_perf(p_str text)
 55: RETURNS numeric
 56: LANGUAGE plpgsql IMMUTABLE
 57: AS $$
 58: DECLARE
 59:   parts text[];
 60:   v_leading text;
 61: BEGIN
 62:   IF p_str IS NULL OR btrim(p_str) = '' THEN RETURN NULL; END IF;
 63:   IF btrim(p_str) ~ '^\d+:\d+' THEN
 64:     parts := regexp_split_to_array(btrim(p_str), ':');
 65:     RETURN parts[1]::numeric * 60 + parts[2]::numeric;
 66:   END IF;
 67:   BEGIN
 68:     RETURN btrim(p_str)::numeric;
 69:   EXCEPTION WHEN OTHERS THEN
 70:     -- parseFloat() JS est tolérant (ignore un suffixe non numérique,
 71:     -- "14.20m" -> 14.20) ; le cast SQL direct ne l'est pas — on extrait le
 72:     -- préfixe numérique en secours avant d'abandonner (NULL).
 73:     v_leading := substring(btrim(p_str) from '^-?\d+\.?\d*');
 74:     IF v_leading IS NULL OR v_leading = '' OR v_leading = '-' THEN RETURN NULL; END IF;
 75:     RETURN v_leading::numeric;
 76:   END;
 77: END;
 78: $$;
 79: 
 80: UPDATE public.records SET pr_value = public._backfill_parse_perf(pr) WHERE pr_value IS NULL AND pr IS NOT NULL;
 81: UPDATE public.records SET sb_value = public._backfill_parse_perf(sb) WHERE sb_value IS NULL AND sb IS NOT NULL;
 82: 
 83: DROP FUNCTION public._backfill_parse_perf(text);
 84: 
 85: -- ── Idempotence générique, réutilisée par les 3 RPC ci-dessous ─────────────
 86: CREATE TABLE public.rpc_idempotency (
 87:   fn_name         text NOT NULL,
 88:   idempotency_key text NOT NULL,
 89:   actor_user_id   integer REFERENCES public.users(id) ON DELETE SET NULL,
 90:   result          jsonb NOT NULL,
 91:   created_at      timestamptz NOT NULL DEFAULT now(),
 92:   PRIMARY KEY (fn_name, idempotency_key)
 93: );
 94: ALTER TABLE public.rpc_idempotency ENABLE ROW LEVEL SECURITY;
 95: -- Aucune policy cliente : uniquement lue/écrite par les fonctions
 96: -- SECURITY DEFINER ci-dessous (elles s'exécutent avec les droits du
 97: -- propriétaire de la fonction, qui contourne RLS sur ses propres tables —
 98: -- même mécanisme que get_my_club_id()/signup_create_account existants).
 99: 
100: -- ── Outbox de notifications : écrit DANS la même transaction que le
101: --    résultat/record, jamais après (le client ne dépêche les vraies
102: --    notifications qu'une fois le RPC revenu avec succès = commit
103: --    confirmé). ─────────────────────────────────────────────────────────
104: CREATE TABLE public.notification_outbox (
105:   id           bigserial PRIMARY KEY,
106:   club_id      integer REFERENCES public.clubs(id) ON DELETE SET NULL,
107:   athlete_id   integer REFERENCES public.athletes(id) ON DELETE SET NULL,
108:   event_type   text NOT NULL CHECK (event_type IN ('competition_result_added', 'competition_new_record')),
109:   payload      jsonb NOT NULL,
110:   status       text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'sent', 'failed')),
111:   created_at   timestamptz NOT NULL DEFAULT now(),
112:   processed_at timestamptz
113: );
114: CREATE INDEX notification_outbox_pending_idx ON public.notification_outbox (created_at) WHERE status = 'pending';
115: 
116: ALTER TABLE public.notification_outbox ENABLE ROW LEVEL SECURITY;
117: CREATE POLICY "notification_outbox_head_coach_read" ON public.notification_outbox
118:   FOR SELECT TO authenticated
119:   USING (club_id = get_my_club_id() AND get_my_role() = 'head_coach');
120: REVOKE ALL ON public.notification_outbox FROM anon;
121: GRANT SELECT ON public.notification_outbox TO authenticated;
122: 
123: -- ── Logique interne partagée (verrouillage + comparaison + record + outbox),
124: --    appelée par les deux RPC publiques qui enregistrent un résultat
125: --    (coach : add_competition_result ; athlète solo :
126: --    create_solo_competition_result) pour ne pas dupliquer la partie la
127: --    plus sensible (le verrou anti-concurrence sur records). ─────────────
128: CREATE OR REPLACE FUNCTION public._apply_competition_result(
129:   p_competition_id  integer,
130:   p_athlete_id      integer,
131:   p_club_id         integer,
132:   p_athlete_name    text,
133:   p_event           text,
134:   p_result          text,
135:   p_result_value    numeric,
136:   p_higher_is_better boolean,
137:   p_context         text,
138:   p_competition_name text,
139:   p_also_log_performance boolean,
140:   p_performance_date date,
141:   p_breakdown       jsonb DEFAULT NULL
142: ) RETURNS jsonb
143: LANGUAGE plpgsql
144: SET search_path TO 'public'
145: AS $$
146: DECLARE
147:   v_result_id      integer;
148:   v_performance_id integer;
149:   v_existing_pr    numeric;
150:   v_existing_sb    numeric;
151:   v_is_pr          boolean;
152:   v_is_sb          boolean;
153:   v_record_id      integer;
154:   v_outbox         jsonb := '[]'::jsonb;
155:   v_outbox_id      bigint;
156:   v_outbox_payload jsonb;
157:   v_this_year      boolean;
158: BEGIN
159:   INSERT INTO competition_results (competition_id, athlete_id, event, result, context)
160:   VALUES (p_competition_id, p_athlete_id, p_event, p_result, p_context)
161:   RETURNING id INTO v_result_id;
162: 
163:   IF p_also_log_performance THEN
164:     INSERT INTO athlete_performances (athlete_id, club_id, discipline, discipline_type, value, performance_date, context, breakdown)
165:     VALUES (p_athlete_id, p_club_id, p_event, p_event, p_result, p_performance_date, p_competition_name, p_breakdown)
166:     RETURNING id INTO v_performance_id;
167:   END IF;
168: 
169:   v_this_year := date_part('year', p_performance_date) = date_part('year', now());
170: 
171:   -- Tentative de création atomique de la ligne. Grâce à la contrainte
172:   -- UNIQUE(athlete_id, discipline), si deux transactions concurrentes
173:   -- tentent ceci EN MÊME TEMPS pour le tout premier résultat d'une
174:   -- discipline, Postgres n'en laisse réellement créer qu'UNE (l'autre
175:   -- devient un no-op) — RETURNING nous dit de façon fiable si C'EST NOUS
176:   -- qui avons gagné la course, sans fenêtre où les deux se croient "les
177:   -- premiers".
178:   INSERT INTO records (athlete_id, discipline, pr, pr_value, pr_date, sb, sb_value)
179:   VALUES (p_athlete_id, p_event, p_result, p_result_value, p_performance_date, p_result, p_result_value)
180:   ON CONFLICT (athlete_id, discipline) DO NOTHING
181:   RETURNING id INTO v_record_id;
182: 
183:   IF v_record_id IS NOT NULL THEN
184:     -- On a bien créé la ligne : premier résultat pour cette discipline
185:     -- (ou on a gagné la course face à une insertion concurrente) — dans
186:     -- les deux cas, c'est ce résultat qui est désormais stocké tel quel.
187:     v_is_pr := true;
188:     v_is_sb := v_this_year;
189:   ELSE
190:     -- La ligne existait déjà (ou vient d'être créée par une transaction
191:     -- concurrente juste avant nous) : verrou de ligne avant de comparer,
192:     -- pour que deux résultats concurrents battant le même record ne
193:     -- lisent jamais "pas encore battu" en même temps.
194:     SELECT id, pr_value, sb_value INTO v_record_id, v_existing_pr, v_existing_sb
195:     FROM records WHERE athlete_id = p_athlete_id AND discipline = p_event
196:     FOR UPDATE;
197: 
198:     -- v_existing_pr/sb NULL malgré une ligne existante : cas résiduel du
199:     -- backfill (ancien texte non interprétable par _backfill_parse_perf)
200:     -- — traité comme "rien à comparer, donc battu" plutôt que de bloquer
201:     -- silencieusement une vraie amélioration derrière un NULL.
202:     v_is_pr := v_existing_pr IS NULL OR (p_higher_is_better AND p_result_value > v_existing_pr) OR (NOT p_higher_is_better AND p_result_value < v_existing_pr);
203:     v_is_sb := v_this_year AND (v_existing_sb IS NULL OR (p_higher_is_better AND p_result_value > v_existing_sb) OR (NOT p_higher_is_better AND p_result_value < v_existing_sb));
204: 
205:     IF v_is_pr OR v_is_sb THEN
206:       UPDATE records SET
207:         pr       = CASE WHEN v_is_pr THEN p_result ELSE pr END,
208:         pr_value = CASE WHEN v_is_pr THEN p_result_value ELSE pr_value END,
209:         pr_date  = CASE WHEN v_is_pr THEN p_performance_date ELSE pr_date END,
210:         sb       = CASE WHEN v_is_sb THEN p_result ELSE sb END,
211:         sb_value = CASE WHEN v_is_sb THEN p_result_value ELSE sb_value END
212:       WHERE id = v_record_id;
213:     END IF;
214:   END IF;
215: 
216:   -- Outbox : écrit ici, dans la transaction — jamais après. Le client ne
217:   -- dépêchera les vraies notifications qu'après le retour en succès de
218:   -- cette fonction (donc après COMMIT confirmé) — le payload complet est
219:   -- renvoyé avec chaque événement pour que le client n'ait pas besoin
220:   -- d'un second aller-retour pour connaître le contenu à envoyer.
221:   IF v_is_pr THEN
222:     INSERT INTO notification_outbox (club_id, athlete_id, event_type, payload)
223:     VALUES (p_club_id, p_athlete_id, 'competition_new_record',
224:       jsonb_build_object('clubId', p_club_id, 'athleteId', p_athlete_id, 'athleteName', p_athlete_name,
225:         'discipline', p_event, 'result', p_result, 'competitionName', p_competition_name))
226:     RETURNING id, payload INTO v_outbox_id, v_outbox_payload;
227:     v_outbox := v_outbox || jsonb_build_object('outboxId', v_outbox_id, 'type', 'competition_new_record', 'payload', v_outbox_payload);
228:   END IF;
229: 
230:   INSERT INTO notification_outbox (club_id, athlete_id, event_type, payload)
231:   VALUES (p_club_id, p_athlete_id, 'competition_result_added',
232:     jsonb_build_object('clubId', p_club_id, 'athleteId', p_athlete_id, 'athleteName', p_athlete_name,
233:       'discipline', p_event, 'result', p_result, 'competitionName', p_competition_name))
234:   RETURNING id, payload INTO v_outbox_id, v_outbox_payload;
235:   v_outbox := v_outbox || jsonb_build_object('outboxId', v_outbox_id, 'type', 'competition_result_added', 'payload', v_outbox_payload);
236: 
237:   RETURN jsonb_build_object(
238:     'resultId', v_result_id, 'performanceId', v_performance_id, 'isNewRecord', v_is_pr,
239:     'recordId', v_record_id, 'notifications', v_outbox
240:   );
241: END;
242: $$;
243: 
244: -- ── RPC 1 : créer une compétition + lister ses participants ────────────────
245: -- Autorisé pour : un coach/head coach de son propre club (n'importe quels
246: -- athlètes DE CE CLUB), ou un athlète créant une compétition pour
247: -- LUI-MÊME uniquement (un seul athlète dans p_athlete_entries, qui doit
248: -- être lui — utilisé par AthletePerfs.jsx, l'auto-déclaration d'une
249: -- compétition).
250: CREATE OR REPLACE FUNCTION public.create_competition_with_athletes(
251:   p_name             text,
252:   p_date             date,
253:   p_location         text,
254:   p_type             text,
255:   p_athlete_entries  jsonb,       -- [{"athleteId": 1, "plannedEvent": "100m"}, ...]
256:   p_idempotency_key  text DEFAULT NULL
257: ) RETURNS jsonb
258: LANGUAGE plpgsql
259: SET search_path TO 'public'
260: AS $$
261: DECLARE
262:   v_caller_id     integer;
263:   v_club_id       integer;
264:   v_role          text;
265:   v_my_athlete_id integer;
266:   v_cached        jsonb;
267:   v_comp_id       integer;
268:   v_entry         jsonb;
269:   v_entry_count   integer;
270:   v_result        jsonb;
271: BEGIN
272:   SELECT id, club_id, role INTO v_caller_id, v_club_id, v_role
273:   FROM users WHERE lower(trim(auth_uid)) = lower(trim(auth.uid()::text)) LIMIT 1;
274:   IF v_caller_id IS NULL THEN RAISE EXCEPTION 'Profil introuvable.'; END IF;
275: 
276:   IF p_idempotency_key IS NOT NULL THEN
277:     SELECT result INTO v_cached FROM rpc_idempotency
278:     WHERE fn_name = 'create_competition_with_athletes' AND idempotency_key = p_idempotency_key;
279:     IF v_cached IS NOT NULL THEN RETURN v_cached; END IF;
280:   END IF;
281: 
282:   IF p_name IS NULL OR btrim(p_name) = '' THEN RAISE EXCEPTION 'Nom de compétition manquant.'; END IF;
283:   IF p_date IS NULL THEN RAISE EXCEPTION 'Date manquante.'; END IF;
284: 
285:   v_entry_count := jsonb_array_length(coalesce(p_athlete_entries, '[]'::jsonb));
286: 
287:   IF v_role IN ('head_coach', 'coach') THEN
288:     -- Le coach peut engager n'importe quel athlète de SON club — vérifié
289:     -- ligne par ligne plus bas (pas de confiance dans un club_id envoyé
290:     -- par le client).
291:     NULL;
292:   ELSE
293:     -- Un non-coach (athlète) ne peut créer une compétition QUE pour
294:     -- lui-même, seul participant.
295:     SELECT a.id INTO v_my_athlete_id FROM athletes a WHERE a.user_id = v_caller_id LIMIT 1;
296:     IF v_my_athlete_id IS NULL THEN RAISE EXCEPTION 'Profil athlète introuvable.'; END IF;
297:     IF v_entry_count <> 1 OR (p_athlete_entries->0->>'athleteId')::integer <> v_my_athlete_id THEN
298:       RAISE EXCEPTION 'Un athlète ne peut créer une compétition que pour lui-même.';
299:     END IF;
300:   END IF;
301: 
302:   INSERT INTO competitions (club_id, name, date, location, type)
303:   VALUES (v_club_id, btrim(p_name), p_date, nullif(btrim(coalesce(p_location, '')), ''), p_type)
304:   RETURNING id INTO v_comp_id;
305: 
306:   FOR v_entry IN SELECT * FROM jsonb_array_elements(coalesce(p_athlete_entries, '[]'::jsonb)) LOOP
307:     IF NOT EXISTS (SELECT 1 FROM athletes WHERE id = (v_entry->>'athleteId')::integer AND club_id = v_club_id) THEN
308:       RAISE EXCEPTION 'Un des athlètes engagés n''est pas dans ton club.';
309:     END IF;
310:     INSERT INTO competition_athletes (competition_id, athlete_id, planned_event)
311:     VALUES (v_comp_id, (v_entry->>'athleteId')::integer, nullif(v_entry->>'plannedEvent', ''));
312:   END LOOP;
313: 
314:   v_result := jsonb_build_object('competitionId', v_comp_id, 'athleteCount', v_entry_count);
315: 
316:   IF p_idempotency_key IS NOT NULL THEN
317:     INSERT INTO rpc_idempotency (fn_name, idempotency_key, actor_user_id, result)
318:     VALUES ('create_competition_with_athletes', p_idempotency_key, v_caller_id, v_result)
319:     ON CONFLICT (fn_name, idempotency_key) DO NOTHING;
320:   END IF;
321: 
322:   RETURN v_result;
323: END;
324: $$;
325: 
326: -- ── RPC 2 : un coach ajoute le résultat d'un athlète à une compétition
327: --    existante ───────────────────────────────────────────────────────────
328: CREATE OR REPLACE FUNCTION public.add_competition_result(
329:   p_competition_id   integer,
330:   p_athlete_id       integer,
331:   p_event            text,
332:   p_result           text,
333:   p_result_value     numeric,
334:   p_higher_is_better boolean,
335:   p_context          text DEFAULT NULL,
336:   p_idempotency_key  text DEFAULT NULL
337: ) RETURNS jsonb
338: LANGUAGE plpgsql
339: SET search_path TO 'public'
340: AS $$
341: DECLARE
342:   v_caller_id  integer;
343:   v_club_id    integer;
344:   v_role       text;
345:   v_cached     jsonb;
346:   v_comp       record;
347:   v_athlete    record;
348:   v_result     jsonb;
349: BEGIN
350:   SELECT id, club_id, role INTO v_caller_id, v_club_id, v_role
351:   FROM users WHERE lower(trim(auth_uid)) = lower(trim(auth.uid()::text)) LIMIT 1;
352:   IF v_caller_id IS NULL THEN RAISE EXCEPTION 'Profil introuvable.'; END IF;
353:   IF v_role NOT IN ('head_coach', 'coach') THEN RAISE EXCEPTION 'Action réservée au coach.'; END IF;
354: 
355:   IF p_idempotency_key IS NOT NULL THEN
356:     SELECT result INTO v_cached FROM rpc_idempotency
357:     WHERE fn_name = 'add_competition_result' AND idempotency_key = p_idempotency_key;
358:     IF v_cached IS NOT NULL THEN RETURN v_cached; END IF;
359:   END IF;
360: 
361:   IF p_event IS NULL OR btrim(p_event) = '' THEN RAISE EXCEPTION 'Discipline manquante.'; END IF;
362:   IF p_result IS NULL OR btrim(p_result) = '' THEN RAISE EXCEPTION 'Résultat manquant.'; END IF;
363:   IF p_result_value IS NULL THEN RAISE EXCEPTION 'Résultat non interprétable.'; END IF;
364: 
365:   SELECT id, name, date, club_id INTO v_comp FROM competitions WHERE id = p_competition_id;
366:   IF v_comp.id IS NULL OR v_comp.club_id <> v_club_id THEN RAISE EXCEPTION 'Compétition introuvable dans ton club.'; END IF;
367: 
368:   SELECT id, name, club_id INTO v_athlete FROM athletes WHERE id = p_athlete_id;
369:   IF v_athlete.id IS NULL OR v_athlete.club_id <> v_club_id THEN RAISE EXCEPTION 'Athlète introuvable dans ton club.'; END IF;
370: 
371:   v_result := _apply_competition_result(
372:     p_competition_id, p_athlete_id, v_club_id, v_athlete.name, p_event, p_result, p_result_value,
373:     p_higher_is_better, p_context, v_comp.name, false, v_comp.date
374:   );
375: 
376:   IF p_idempotency_key IS NOT NULL THEN
377:     INSERT INTO rpc_idempotency (fn_name, idempotency_key, actor_user_id, result)
378:     VALUES ('add_competition_result', p_idempotency_key, v_caller_id, v_result)
379:     ON CONFLICT (fn_name, idempotency_key) DO NOTHING;
380:   END IF;
381: 
382:   RETURN v_result;
383: END;
384: $$;
385: 
386: -- ── RPC 3 : un athlète déclare seul une compétition + son résultat (tout
387: --    en une fois — le flux "handleAddComp" de AthletePerfs.jsx faisait
388: --    jusqu'à 5 écritures successives sans filet). ───────────────────────
389: CREATE OR REPLACE FUNCTION public.create_solo_competition_result(
390:   p_name             text,
391:   p_date             date,
392:   p_location         text,
393:   p_type             text,
394:   p_event            text,
395:   p_result           text,
396:   p_result_value     numeric,
397:   p_higher_is_better boolean,
398:   p_context          text DEFAULT NULL,
399:   p_idempotency_key  text DEFAULT NULL,
400:   p_breakdown        jsonb DEFAULT NULL
401: ) RETURNS jsonb
402: LANGUAGE plpgsql
403: SET search_path TO 'public'
404: AS $$
405: DECLARE
406:   v_caller_id     integer;
407:   v_club_id       integer;
408:   v_my_athlete_id integer;
409:   v_my_name       text;
410:   v_cached        jsonb;
411:   v_comp_id       integer;
412:   v_result        jsonb;
413: BEGIN
414:   SELECT id, club_id INTO v_caller_id, v_club_id
415:   FROM users WHERE lower(trim(auth_uid)) = lower(trim(auth.uid()::text)) LIMIT 1;
416:   IF v_caller_id IS NULL THEN RAISE EXCEPTION 'Profil introuvable.'; END IF;
417: 
418:   SELECT id, name INTO v_my_athlete_id, v_my_name FROM athletes WHERE user_id = v_caller_id LIMIT 1;
419:   IF v_my_athlete_id IS NULL THEN RAISE EXCEPTION 'Profil athlète introuvable.'; END IF;
420: 
421:   IF p_idempotency_key IS NOT NULL THEN
422:     SELECT result INTO v_cached FROM rpc_idempotency
423:     WHERE fn_name = 'create_solo_competition_result' AND idempotency_key = p_idempotency_key;
424:     IF v_cached IS NOT NULL THEN RETURN v_cached; END IF;
425:   END IF;
426: 
427:   IF p_name IS NULL OR btrim(p_name) = '' THEN RAISE EXCEPTION 'Nom de compétition manquant.'; END IF;
428:   IF p_date IS NULL THEN RAISE EXCEPTION 'Date manquante.'; END IF;
429:   IF p_event IS NULL OR btrim(p_event) = '' THEN RAISE EXCEPTION 'Discipline manquante.'; END IF;
430:   IF p_result IS NULL OR btrim(p_result) = '' THEN RAISE EXCEPTION 'Résultat manquant.'; END IF;
431:   IF p_result_value IS NULL THEN RAISE EXCEPTION 'Résultat non interprétable.'; END IF;
432: 
433:   INSERT INTO competitions (club_id, name, date, location, type)
434:   VALUES (v_club_id, btrim(p_name), p_date, nullif(btrim(coalesce(p_location, '')), ''), p_type)
435:   RETURNING id INTO v_comp_id;
436: 
437:   INSERT INTO competition_athletes (competition_id, athlete_id, planned_event)
438:   VALUES (v_comp_id, v_my_athlete_id, p_event);
439: 
440:   v_result := _apply_competition_result(
441:     v_comp_id, v_my_athlete_id, v_club_id, v_my_name, p_event, p_result, p_result_value,
442:     p_higher_is_better, p_context, btrim(p_name), true, p_date, p_breakdown
443:   );
444:   v_result := v_result || jsonb_build_object('competitionId', v_comp_id);
445: 
446:   IF p_idempotency_key IS NOT NULL THEN
447:     INSERT INTO rpc_idempotency (fn_name, idempotency_key, actor_user_id, result)
448:     VALUES ('create_solo_competition_result', p_idempotency_key, v_caller_id, v_result)
449:     ON CONFLICT (fn_name, idempotency_key) DO NOTHING;
450:   END IF;
451: 
452:   RETURN v_result;
453: END;
454: $$;
455: 
456: -- ── RPC 4 : marquer des événements outbox comme traités (après dispatch
457: --    réel des notifications côté client) — jamais d'UPDATE direct sur
458: --    notification_outbox depuis le client (aucune policy d'écriture),
459: --    seulement via cette fonction, qui vérifie que l'appelant a bien le
460: --    droit de voir ces lignes (même club). ─────────────────────────────
461: CREATE OR REPLACE FUNCTION public.mark_notification_outbox_sent(p_ids bigint[])
462: RETURNS void
463: LANGUAGE plpgsql
464: SET search_path TO 'public'
465: AS $$
466: DECLARE
467:   v_club_id integer;
468: BEGIN
469:   SELECT club_id INTO v_club_id FROM users WHERE lower(trim(auth_uid)) = lower(trim(auth.uid()::text)) LIMIT 1;
470:   IF v_club_id IS NULL THEN RAISE EXCEPTION 'Profil introuvable.'; END IF;
471: 
472:   UPDATE notification_outbox
473:   SET status = 'sent', processed_at = now()
474:   WHERE id = ANY(p_ids) AND club_id = v_club_id AND status = 'pending';
475: END;
476: $$;
477: 
478: -- ── Grants : exécution réservée à authenticated, jamais anon ────────────────
479: REVOKE ALL ON FUNCTION public.create_competition_with_athletes(text, date, text, text, jsonb, text) FROM PUBLIC;
480: REVOKE ALL ON FUNCTION public.add_competition_result(integer, integer, text, text, numeric, boolean, text, text) FROM PUBLIC;
481: REVOKE ALL ON FUNCTION public.create_solo_competition_result(text, date, text, text, text, text, numeric, boolean, text, text, jsonb) FROM PUBLIC;
482: REVOKE ALL ON FUNCTION public.mark_notification_outbox_sent(bigint[]) FROM PUBLIC;
483: GRANT EXECUTE ON FUNCTION public.create_competition_with_athletes(text, date, text, text, jsonb, text) TO authenticated;
484: GRANT EXECUTE ON FUNCTION public.add_competition_result(integer, integer, text, text, numeric, boolean, text, text) TO authenticated;
485: GRANT EXECUTE ON FUNCTION public.create_solo_competition_result(text, date, text, text, text, text, numeric, boolean, text, text, jsonb) TO authenticated;
486: GRANT EXECUTE ON FUNCTION public.mark_notification_outbox_sent(bigint[]) TO authenticated;
487: 
488: COMMIT; 1: BEGIN;
