 3: -- ============================================================
 4: -- Tâche 8 — bucket session-pdfs en stockage privé
 5: --
 6: -- Avant cette migration : bucket public, sans limite de taille ni de
 7: -- type MIME côté serveur. N'importe quel lien de PDF de séance (URL
 8: -- publique permanente) donnait accès au fichier à quiconque le devine
 9: -- ou l'intercepte, connecté ou non — les policies INSERT/UPDATE
10: -- existantes (20260727010000_scope_storage_policies_by_club.sql)
11: -- protègent l'écriture mais jamais la LECTURE, qui contournait
12: -- totalement RLS via l'endpoint public.
13: --
14: -- Aucune ligne `sessions.pdf_url` n'existe en prod à ce jour (vérifié
15: -- avant d'écrire cette migration) : aucune conversion d'anciennes URLs
16: -- publiques n'est nécessaire.
17: --
18: -- social-photos n'est PAS concerné : hors périmètre de la tâche 8 (fil
19: -- social intentionnellement partagé dans tout le club, pas un document
20: -- sensible).
21: -- ============================================================
22: 
23: -- Bucket privé + limites appliquées par Supabase lui-même (et pas
24: -- seulement par une vérification côté client, contournable).
25: UPDATE storage.buckets
26: SET
27:   public = false,
28:   file_size_limit = 31457280, -- 30 Mo (scans/photos multi-pages)
29:   allowed_mime_types = ARRAY['application/pdf']
30: WHERE id = 'session-pdfs';
31: 
32: -- Lecture : même règle que l'écriture, scopée par le 1er segment du
33: -- chemin (club_id). Nécessaire pour createSignedUrl() côté client, qui
34: -- exige que l'appelant ait un droit SELECT sur la ligne storage.objects
35: -- correspondante.
36: CREATE POLICY "club-scoped read session-pdfs" ON storage.objects
37:   FOR SELECT TO authenticated
38:   USING (
39:     bucket_id = 'session-pdfs'
40:     AND (storage.foldername(name))[1] = get_my_club_id()::text
41:   );
42: 
43: -- Suppression : nécessaire pour purger le fichier storage quand une
44: -- séance est supprimée (voir fix Planning.jsx deleteSession).
45: CREATE POLICY "club-scoped delete session-pdfs" ON storage.objects
46:   FOR DELETE TO authenticated
47:   USING (
48:     bucket_id = 'session-pdfs'
49:     AND (storage.foldername(name))[1] = get_my_club_id()::text
50:   );
51: 
52: COMMIT;  1: BEGIN;
