  3: -- ============================================================
  4: -- Tâche 12 — normaliser le stockage des performances
  5: --
  6: -- Problème : ni athlete_performances.value ni competition_results.result
  7: -- n'ont de contrepartie numérique en base — seul du texte libre ("11.20",
  8: -- "32m", "1:52.30"). Tout tri/comparaison/agrégation ne peut se faire
  9: -- QUE côté client, en ré-analysant la chaîne à chaque lecture
 10: -- (parsePerf(), tâche 11). records.pr_value/sb_value existent déjà
 11: -- (tâche 14) mais seulement pour la comparaison "ce résultat bat-il le
 12: -- record" côté serveur — jamais lus par l'UI, et un futur import
 13: -- montre/FIT n'a ni valeur canonique fiable ni moyen de se dédupliquer.
 14: --
 15: -- Solution : ajoute une valeur numérique canonique + unité + identifiant
 16: -- de discipline résolu + provenance sur athlete_performances et
 17: -- competition_results (le texte brut existant, value/result, reste
 18: -- inchangé — c'est déjà la "valeur brute pour l'affichage" demandée,
 19: -- pas besoin d'une colonne raw_value redondante). Sur records, seulement
 20: -- unit/discipline_id : pr_value/sb_value jouent déjà le rôle de valeur
 21: -- canonique (une paire, pas une seule valeur) et c'est une table dérivée
 22: -- (le meilleur résultat vu), pas une donnée importée en soi — source/
 23: -- source_external_id/quality_flags n'ont pas de sens dessus.
 24: --
 25: -- Backfill via une fonction de parsing jetable (même approche et même
 26: -- corps que _backfill_parse_perf de la tâche 14, recréée puis supprimée
 27: -- ici) + une table de correspondance disciplines->unité construite à la
 28: -- main à partir du registre JS (src/domain/disciplines.js, tâche 9) —
 29: -- aucune table disciplines n'existe en base (décision déjà prise et
 30: -- documentée tâche 9 : l'identifiant canonique EST le libellé, pas une
 31: -- clé étrangère vers une table à part). Cette correspondance ne sert
 32: -- qu'à CE backfill ponctuel ; les nouvelles écritures envoient déjà
 33: -- l'unité/l'id résolus depuis le registre JS.
 34: -- ============================================================
 35: 
 36: CREATE OR REPLACE FUNCTION public._backfill_parse_perf(p_str text)
 37: RETURNS numeric
 38: LANGUAGE plpgsql IMMUTABLE
 39: AS $$
 40: DECLARE
 41:   parts text[];
 42:   v_leading text;
 43: BEGIN
 44:   IF p_str IS NULL OR btrim(p_str) = '' THEN RETURN NULL; END IF;
 45:   IF btrim(p_str) ~ '^\d+:\d+' THEN
 46:     parts := regexp_split_to_array(btrim(p_str), ':');
 47:     RETURN parts[1]::numeric * 60 + parts[2]::numeric;
 48:   END IF;
 49:   BEGIN
 50:     RETURN btrim(p_str)::numeric;
 51:   EXCEPTION WHEN OTHERS THEN
 52:     v_leading := substring(btrim(p_str) from '^-?\d+\.?\d*');
 53:     IF v_leading IS NULL OR v_leading = '' OR v_leading = '-' THEN RETURN NULL; END IF;
 54:     RETURN v_leading::numeric;
 55:   END;
 56: END;
 57: $$;
 58: 
 59: -- Table de correspondance discipline -> (id canonique, unité, format
 60: -- "minutes:secondes" attendu) — une ligne par identifiant officiel ET
 61: -- par alias connu du registre JS, clé de recherche normalisée en
 62: -- minuscules/espaces uniques (même logique que normalizeKey() côté JS).
 63: CREATE TEMP TABLE _disc_lookup (
 64:   search_key    text PRIMARY KEY,
 65:   canonical_id  text NOT NULL,
 66:   unit          text NOT NULL,
 67:   is_time_long  boolean NOT NULL
 68: );
 69: INSERT INTO _disc_lookup (search_key, canonical_id, unit, is_time_long) VALUES
 70:   ('100m','100m','s',false), ('100 m','100m','s',false), ('100 metres','100m','s',false), ('100m.','100m','s',false),
 71:   ('200m','200m','s',false), ('200 m','200m','s',false),
 72:   ('400m','400m','s',false), ('400 m','400m','s',false),
 73:   ('800m','800m','s',true),  ('800 m','800m','s',true),
 74:   ('1500m','1500m','s',true), ('1500 m','1500m','s',true), ('1 500m','1500m','s',true),
 75:   ('3000m','3000m','s',true), ('3000 m','3000m','s',true), ('3 000m','3000m','s',true),
 76:   ('60m haies','60m haies','s',false), ('60 m haies','60m haies','s',false), ('60m hurdles','60m haies','s',false),
 77:   ('100m haies','100m haies','s',false), ('100 m haies','100m haies','s',false),
 78:   ('110m haies','110m haies','s',false), ('110 m haies','110m haies','s',false),
 79:   ('400m haies','400m haies','s',false), ('400 m haies','400m haies','s',false),
 80:   ('longueur','Longueur','m',false), ('saut en longueur','Longueur','m',false),
 81:   ('triple saut','Triple saut','m',false),
 82:   ('hauteur','Hauteur','m',false), ('saut en hauteur','Hauteur','m',false),
 83:   ('perche','Perche','m',false), ('saut à la perche','Perche','m',false),
 84:   ('poids','Poids','m',false), ('lancer de poids','Poids','m',false),
 85:   ('disque','Disque','m',false), ('lancer de disque','Disque','m',false),
 86:   ('javelot','Javelot','m',false), ('lancer de javelot','Javelot','m',false),
 87:   ('marteau','Marteau','m',false), ('lancer de marteau','Marteau','m',false),
 88:   ('décathlon','Décathlon','pts',false), ('decathlon','Décathlon','pts',false),
 89:   ('heptathlon','Heptathlon','pts',false);
