 91: -- ── athlete_performances ─────────────────────────────────────────────────
 92: ALTER TABLE public.athlete_performances ADD COLUMN IF NOT EXISTS normalized_value numeric;
 93: ALTER TABLE public.athlete_performances ADD COLUMN IF NOT EXISTS unit text;
 94: ALTER TABLE public.athlete_performances ADD COLUMN IF NOT EXISTS discipline_id text;
 95: ALTER TABLE public.athlete_performances ADD COLUMN IF NOT EXISTS source_external_id text;
 96: ALTER TABLE public.athlete_performances ADD COLUMN IF NOT EXISTS quality_flags text[] NOT NULL DEFAULT '{}';
 97: ALTER TABLE public.athlete_performances ADD CONSTRAINT athlete_performances_unit_check CHECK (unit IS NULL OR unit IN ('s','m','pts'));
 98: 
 99: UPDATE public.athlete_performances t SET
100:   discipline_id     = COALESCE(d.canonical_id, btrim(t.discipline)),
101:   unit               = d.unit,
102:   normalized_value   = public._backfill_parse_perf(t.value),
103:   quality_flags      = CASE
104:     WHEN public._backfill_parse_perf(t.value) IS NULL AND btrim(coalesce(t.value, '')) <> '' THEN ARRAY['unparsable']
105:     WHEN d.is_time_long AND t.value !~ ':' THEN ARRAY['format_ambiguous']
106:     ELSE '{}'::text[]
107:   END
108: FROM (
109:   SELECT ap.id, dl.canonical_id, dl.unit, dl.is_time_long
110:   FROM public.athlete_performances ap
111:   LEFT JOIN _disc_lookup dl ON dl.search_key = lower(btrim(regexp_replace(ap.discipline, '\s+', ' ', 'g')))
112: ) d
113: WHERE d.id = t.id;
114: 
115: -- Empêche un même point importé deux fois par le même fournisseur (ex:
116: -- une activité Garmin ré-importée) — ne s'applique qu'aux lignes qui
117: -- déclarent une provenance externe, jamais aux saisies manuelles.
118: CREATE UNIQUE INDEX athlete_performances_source_external_id_key
119:   ON public.athlete_performances (source, source_external_id)
120:   WHERE source_external_id IS NOT NULL;
121: 
122: -- ── competition_results ──────────────────────────────────────────────────
123: ALTER TABLE public.competition_results ADD COLUMN IF NOT EXISTS result_value numeric;
124: ALTER TABLE public.competition_results ADD COLUMN IF NOT EXISTS unit text;
125: ALTER TABLE public.competition_results ADD COLUMN IF NOT EXISTS discipline_id text;
126: ALTER TABLE public.competition_results ADD COLUMN IF NOT EXISTS source text NOT NULL DEFAULT 'club';
127: ALTER TABLE public.competition_results ADD COLUMN IF NOT EXISTS source_external_id text;
128: ALTER TABLE public.competition_results ADD COLUMN IF NOT EXISTS quality_flags text[] NOT NULL DEFAULT '{}';
129: ALTER TABLE public.competition_results ADD CONSTRAINT competition_results_unit_check CHECK (unit IS NULL OR unit IN ('s','m','pts'));
130: 
131: UPDATE public.competition_results t SET
132:   discipline_id  = COALESCE(d.canonical_id, btrim(t.event)),
133:   unit            = d.unit,
134:   result_value    = public._backfill_parse_perf(t.result),
135:   quality_flags   = CASE
136:     WHEN public._backfill_parse_perf(t.result) IS NULL AND btrim(coalesce(t.result, '')) <> '' THEN ARRAY['unparsable']
137:     WHEN d.is_time_long AND t.result !~ ':' THEN ARRAY['format_ambiguous']
138:     ELSE '{}'::text[]
139:   END
140: FROM (
141:   SELECT cr.id, dl.canonical_id, dl.unit, dl.is_time_long
142:   FROM public.competition_results cr
143:   LEFT JOIN _disc_lookup dl ON dl.search_key = lower(btrim(regexp_replace(coalesce(cr.event, ''), '\s+', ' ', 'g')))
144: ) d
145: WHERE d.id = t.id;
146: 
147: -- ── records (déjà pr_value/sb_value depuis la tâche 14 — juste l'unité et
148: --    l'identifiant de discipline résolu manquent encore) ─────────────────
149: ALTER TABLE public.records ADD COLUMN IF NOT EXISTS unit text;
150: ALTER TABLE public.records ADD COLUMN IF NOT EXISTS discipline_id text;
151: ALTER TABLE public.records ADD CONSTRAINT records_unit_check CHECK (unit IS NULL OR unit IN ('s','m','pts'));
152: 
153: UPDATE public.records t SET
154:   discipline_id = COALESCE(d.canonical_id, btrim(t.discipline)),
155:   unit           = d.unit
156: FROM (
157:   SELECT r.id, dl.canonical_id, dl.unit
158:   FROM public.records r
159:   LEFT JOIN _disc_lookup dl ON dl.search_key = lower(btrim(regexp_replace(coalesce(r.discipline, ''), '\s+', ' ', 'g')))
160: ) d
161: WHERE d.id = t.id;
162: 
163: DROP TABLE _disc_lookup;
164: DROP FUNCTION public._backfill_parse_perf(text);
165: 
166: COMMIT;  1: BEGIN;
