  3: -- ============================================================
  4: -- Tâche 12 (suite) — les 3 RPC de compétition (tâche 14) renseignent
  5: -- désormais les colonnes canoniques ajoutées par la migration
  6: -- précédente sur les NOUVELLES lignes qu'elles écrivent.
  7: --
  8: -- p_event est déjà l'identifiant canonique de discipline au moment où
  9: -- ces fonctions le reçoivent (résolu côté client via resolveDisciplineId,
 10: -- tâche 9, avant l'appel RPC — voir Competitions.jsx/AthletePerfs.jsx) :
 11: -- pas besoin d'un nouveau paramètre, discipline_id = p_event directement.
 12: -- p_result_value est déjà validé non NULL avant d'atteindre l'écriture
 13: -- (RAISE EXCEPTION 'Résultat non interprétable' sinon) : les nouvelles
 14: -- lignes ont donc toujours une valeur canonique valide, quality_flags
 15: -- reste '{}' par défaut — ce marquage ne concerne que les anciennes
 16: -- données réparées par le backfill précédent.
 17: --
 18: -- Seule l'unité manquait côté serveur (le registre de disciplines est
 19: -- JS-only, tâche 9) : ajoutée en paramètre p_unit, calculée côté client
 20: -- via getDisciplineUnit(), avec DEFAULT NULL pour rester compatible si
 21: -- le déploiement frontend/Supabase n'est pas parfaitement synchronisé.
 22: --
 23: -- CREATE OR REPLACE avec UNIQUEMENT des paramètres additionnels à
 24: -- valeur par défaut en fin de liste : remplace bien la même fonction
 25: -- (même OID, mêmes grants), ne crée pas une surcharge séparée.
 26: -- ============================================================
 27: 
 28: CREATE OR REPLACE FUNCTION public._apply_competition_result(
 29:   p_competition_id  integer,
 30:   p_athlete_id      integer,
 31:   p_club_id         integer,
 32:   p_athlete_name    text,
 33:   p_event           text,
 34:   p_result          text,
 35:   p_result_value    numeric,
 36:   p_higher_is_better boolean,
 37:   p_context         text,
 38:   p_competition_name text,
 39:   p_also_log_performance boolean,
 40:   p_performance_date date,
 41:   p_breakdown       jsonb DEFAULT NULL,
 42:   p_unit            text DEFAULT NULL
 43: ) RETURNS jsonb
 44: LANGUAGE plpgsql
 45: SECURITY DEFINER
 46: SET search_path TO 'public'
 47: AS $$
 48: DECLARE
 49:   v_result_id      integer;
 50:   v_performance_id integer;
 51:   v_existing_pr    numeric;
 52:   v_existing_sb    numeric;
 53:   v_is_pr          boolean;
 54:   v_is_sb          boolean;
 55:   v_record_id      integer;
 56:   v_outbox         jsonb := '[]'::jsonb;
 57:   v_outbox_id      bigint;
 58:   v_outbox_payload jsonb;
 59:   v_this_year      boolean;
 60: BEGIN
 61:   INSERT INTO competition_results (competition_id, athlete_id, event, result, context, result_value, unit, discipline_id)
 62:   VALUES (p_competition_id, p_athlete_id, p_event, p_result, p_context, p_result_value, p_unit, p_event)
 63:   RETURNING id INTO v_result_id;
 64: 
 65:   IF p_also_log_performance THEN
 66:     INSERT INTO athlete_performances (athlete_id, club_id, discipline, discipline_type, value, performance_date, context, breakdown, normalized_value, unit, discipline_id)
 67:     VALUES (p_athlete_id, p_club_id, p_event, p_event, p_result, p_performance_date, p_competition_name, p_breakdown, p_result_value, p_unit, p_event)
 68:     RETURNING id INTO v_performance_id;
 69:   END IF;
 70: 
 71:   v_this_year := date_part('year', p_performance_date) = date_part('year', now());
 72: 
 73:   INSERT INTO records (athlete_id, discipline, pr, pr_value, pr_date, sb, sb_value, unit, discipline_id)
 74:   VALUES (p_athlete_id, p_event, p_result, p_result_value, p_performance_date, p_result, p_result_value, p_unit, p_event)
 75:   ON CONFLICT (athlete_id, discipline) DO NOTHING
 76:   RETURNING id INTO v_record_id;
 77: 
 78:   IF v_record_id IS NOT NULL THEN
 79:     v_is_pr := true;
 80:     v_is_sb := v_this_year;
 81:   ELSE
 82:     SELECT id, pr_value, sb_value INTO v_record_id, v_existing_pr, v_existing_sb
 83:     FROM records WHERE athlete_id = p_athlete_id AND discipline = p_event
 84:     FOR UPDATE;
 85: 
 86:     v_is_pr := v_existing_pr IS NULL OR (p_higher_is_better AND p_result_value > v_existing_pr) OR (NOT p_higher_is_better AND p_result_value < v_existing_pr);
 87:     v_is_sb := v_this_year AND (v_existing_sb IS NULL OR (p_higher_is_better AND p_result_value > v_existing_sb) OR (NOT p_higher_is_better AND p_result_value < v_existing_sb));
 88: 
 89:     IF v_is_pr OR v_is_sb THEN
 90:       UPDATE records SET
 91:         pr           = CASE WHEN v_is_pr THEN p_result ELSE pr END,
 92:         pr_value     = CASE WHEN v_is_pr THEN p_result_value ELSE pr_value END,
 93:         pr_date      = CASE WHEN v_is_pr THEN p_performance_date ELSE pr_date END,
 94:         sb           = CASE WHEN v_is_sb THEN p_result ELSE sb END,
 95:         sb_value     = CASE WHEN v_is_sb THEN p_result_value ELSE sb_value END,
 96:         unit         = coalesce(p_unit, unit),
 97:         discipline_id = coalesce(discipline_id, p_event)
 98:       WHERE id = v_record_id;
 99:     END IF;
100:   END IF;
101: 
102:   IF v_is_pr THEN
103:     INSERT INTO notification_outbox (club_id, athlete_id, event_type, payload)
104:     VALUES (p_club_id, p_athlete_id, 'competition_new_record',
105:       jsonb_build_object('clubId', p_club_id, 'athleteId', p_athlete_id, 'athleteName', p_athlete_name,
106:         'discipline', p_event, 'result', p_result, 'competitionName', p_competition_name))
107:     RETURNING id, payload INTO v_outbox_id, v_outbox_payload;
108:     v_outbox := v_outbox || jsonb_build_object('outboxId', v_outbox_id, 'type', 'competition_new_record', 'payload', v_outbox_payload);
109:   END IF;
110: 
111:   INSERT INTO notification_outbox (club_id, athlete_id, event_type, payload)
112:   VALUES (p_club_id, p_athlete_id, 'competition_result_added',
113:     jsonb_build_object('clubId', p_club_id, 'athleteId', p_athlete_id, 'athleteName', p_athlete_name,
114:       'discipline', p_event, 'result', p_result, 'competitionName', p_competition_name))
115:   RETURNING id, payload INTO v_outbox_id, v_outbox_payload;
116:   v_outbox := v_outbox || jsonb_build_object('outboxId', v_outbox_id, 'type', 'competition_result_added', 'payload', v_outbox_payload);
117: 
118:   RETURN jsonb_build_object(
119:     'resultId', v_result_id, 'performanceId', v_performance_id, 'isNewRecord', v_is_pr,
120:     'recordId', v_record_id, 'notifications', v_outbox
121:   );
122: END;
123: $$;
124: 
125: CREATE OR REPLACE FUNCTION public.add_competition_result(
126:   p_competition_id   integer,
127:   p_athlete_id       integer,
128:   p_event            text,
129:   p_result           text,
130:   p_result_value     numeric,
131:   p_higher_is_better boolean,
132:   p_context          text DEFAULT NULL,
133:   p_idempotency_key  text DEFAULT NULL,
134:   p_unit             text DEFAULT NULL
135: ) RETURNS jsonb
136: LANGUAGE plpgsql
137: SECURITY DEFINER
138: SET search_path TO 'public'
139: AS $$
140: DECLARE
141:   v_caller_id  integer;
142:   v_club_id    integer;
143:   v_role       text;
144:   v_cached     jsonb;
145:   v_comp       record;
146:   v_athlete    record;
147:   v_result     jsonb;
148: BEGIN
149:   SELECT id, club_id, role INTO v_caller_id, v_club_id, v_role
150:   FROM users WHERE lower(trim(auth_uid)) = lower(trim(auth.uid()::text)) LIMIT 1;
151:   IF v_caller_id IS NULL THEN RAISE EXCEPTION 'Profil introuvable.'; END IF;
152:   IF v_role NOT IN ('head_coach', 'coach') THEN RAISE EXCEPTION 'Action réservée au coach.'; END IF;
153: 
154:   IF p_idempotency_key IS NOT NULL THEN
155:     SELECT result INTO v_cached FROM rpc_idempotency
156:     WHERE fn_name = 'add_competition_result' AND idempotency_key = p_idempotency_key;
157:     IF v_cached IS NOT NULL THEN RETURN v_cached; END IF;
158:   END IF;
159: 
160:   IF p_event IS NULL OR btrim(p_event) = '' THEN RAISE EXCEPTION 'Discipline manquante.'; END IF;
161:   IF p_result IS NULL OR btrim(p_result) = '' THEN RAISE EXCEPTION 'Résultat manquant.'; END IF;
162:   IF p_result_value IS NULL THEN RAISE EXCEPTION 'Résultat non interprétable.'; END IF;
163: 
164:   SELECT id, name, date, club_id INTO v_comp FROM competitions WHERE id = p_competition_id;
165:   IF v_comp.id IS NULL OR v_comp.club_id <> v_club_id THEN RAISE EXCEPTION 'Compétition introuvable dans ton club.'; END IF;
166: 
167:   SELECT id, name, club_id INTO v_athlete FROM athletes WHERE id = p_athlete_id;
168:   IF v_athlete.id IS NULL OR v_athlete.club_id <> v_club_id THEN RAISE EXCEPTION 'Athlète introuvable dans ton club.'; END IF;
169: 
170:   v_result := _apply_competition_result(
171:     p_competition_id, p_athlete_id, v_club_id, v_athlete.name, p_event, p_result, p_result_value,
172:     p_higher_is_better, p_context, v_comp.name, false, v_comp.date, NULL, p_unit
173:   );
174: 
175:   IF p_idempotency_key IS NOT NULL THEN
176:     INSERT INTO rpc_idempotency (fn_name, idempotency_key, actor_user_id, result)
177:     VALUES ('add_competition_result', p_idempotency_key, v_caller_id, v_result)
178:     ON CONFLICT (fn_name, idempotency_key) DO NOTHING;
179:   END IF;
180: 
181:   RETURN v_result;
182: END;
183: $$;
184: 
185: CREATE OR REPLACE FUNCTION public.create_solo_competition_result(
186:   p_name             text,
187:   p_date             date,
188:   p_location         text,
189:   p_type             text,
190:   p_event            text,
191:   p_result           text,
192:   p_result_value     numeric,
193:   p_higher_is_better boolean,
194:   p_context          text DEFAULT NULL,
195:   p_idempotency_key  text DEFAULT NULL,
196:   p_breakdown        jsonb DEFAULT NULL,
197:   p_unit             text DEFAULT NULL
198: ) RETURNS jsonb
199: LANGUAGE plpgsql
200: SECURITY DEFINER
201: SET search_path TO 'public'
202: AS $$
203: DECLARE
204:   v_caller_id     integer;
205:   v_club_id       integer;
206:   v_my_athlete_id integer;
207:   v_my_name       text;
208:   v_cached        jsonb;
209:   v_comp_id       integer;
210:   v_result        jsonb;
211: BEGIN
212:   SELECT id, club_id INTO v_caller_id, v_club_id
213:   FROM users WHERE lower(trim(auth_uid)) = lower(trim(auth.uid()::text)) LIMIT 1;
214:   IF v_caller_id IS NULL THEN RAISE EXCEPTION 'Profil introuvable.'; END IF;
215: 
216:   SELECT id, name INTO v_my_athlete_id, v_my_name FROM athletes WHERE user_id = v_caller_id LIMIT 1;
217:   IF v_my_athlete_id IS NULL THEN RAISE EXCEPTION 'Profil athlète introuvable.'; END IF;
218: 
219:   IF p_idempotency_key IS NOT NULL THEN
220:     SELECT result INTO v_cached FROM rpc_idempotency
221:     WHERE fn_name = 'create_solo_competition_result' AND idempotency_key = p_idempotency_key;
222:     IF v_cached IS NOT NULL THEN RETURN v_cached; END IF;
223:   END IF;
224: 
225:   IF p_name IS NULL OR btrim(p_name) = '' THEN RAISE EXCEPTION 'Nom de compétition manquant.'; END IF;
226:   IF p_date IS NULL THEN RAISE EXCEPTION 'Date manquante.'; END IF;
227:   IF p_event IS NULL OR btrim(p_event) = '' THEN RAISE EXCEPTION 'Discipline manquante.'; END IF;
228:   IF p_result IS NULL OR btrim(p_result) = '' THEN RAISE EXCEPTION 'Résultat manquant.'; END IF;
229:   IF p_result_value IS NULL THEN RAISE EXCEPTION 'Résultat non interprétable.'; END IF;
230: 
231:   INSERT INTO competitions (club_id, name, date, location, type)
232:   VALUES (v_club_id, btrim(p_name), p_date, nullif(btrim(coalesce(p_location, '')), ''), p_type)
233:   RETURNING id INTO v_comp_id;
234: 
235:   INSERT INTO competition_athletes (competition_id, athlete_id, planned_event)
236:   VALUES (v_comp_id, v_my_athlete_id, p_event);
237: 
238:   v_result := _apply_competition_result(
239:     v_comp_id, v_my_athlete_id, v_club_id, v_my_name, p_event, p_result, p_result_value,
240:     p_higher_is_better, p_context, btrim(p_name), true, p_date, p_breakdown, p_unit
241:   );
242:   v_result := v_result || jsonb_build_object('competitionId', v_comp_id);
243: 
244:   IF p_idempotency_key IS NOT NULL THEN
245:     INSERT INTO rpc_idempotency (fn_name, idempotency_key, actor_user_id, result)
246:     VALUES ('create_solo_competition_result', p_idempotency_key, v_caller_id, v_result)
247:     ON CONFLICT (fn_name, idempotency_key) DO NOTHING;
248:   END IF;
249: 
250:   RETURN v_result;
251: END;
252: $$;
253: 
254: -- Grants réaffirmés explicitement sur les nouvelles signatures (CREATE OR
255: -- REPLACE conserve normalement les grants existants sur le même OID, mais
256: -- on les réaffirme ici pour ne rien laisser au hasard, comme pour les
257: -- fonctions déjà corrigées à la tâche 14).
258: REVOKE ALL ON FUNCTION public._apply_competition_result(integer, integer, integer, text, text, text, numeric, boolean, text, text, boolean, date, jsonb, text) FROM PUBLIC;
259: REVOKE ALL ON FUNCTION public.add_competition_result(integer, integer, text, text, numeric, boolean, text, text, text) FROM PUBLIC;
260: REVOKE ALL ON FUNCTION public.create_solo_competition_result(text, date, text, text, text, text, numeric, boolean, text, text, jsonb, text) FROM PUBLIC;
261: GRANT EXECUTE ON FUNCTION public.add_competition_result(integer, integer, text, text, numeric, boolean, text, text, text) TO authenticated;
262: GRANT EXECUTE ON FUNCTION public.create_solo_competition_result(text, date, text, text, text, text, numeric, boolean, text, text, jsonb, text) TO authenticated;
263: 
264: COMMIT;  1: BEGIN;
  2: 
  3: -- ============================================================
  4: -- Personnalisation visuelle du club
  5: --
  6: -- Les chemins sont stockés (et non des URL signées temporaires) afin
  7: -- que le client puisse générer une URL courte durée au moment de
  8: -- l'affichage. Toutes les colonnes sont additives : les clubs existants
  9: -- gardent leur fonctionnement et reçoivent simplement la couleur
 10: -- AthleteOS historique comme valeur par défaut.
 11: -- ============================================================
 12: 
 13: ALTER TABLE public.clubs
 14:   ADD COLUMN IF NOT EXISTS logo_path text,
 15:   ADD COLUMN IF NOT EXISTS cover_path text,
 16:   ADD COLUMN IF NOT EXISTS accent_color text NOT NULL DEFAULT '#1D9E75';
 17: 
 18: -- Défense en profondeur : même service_role ne peut pas enregistrer
 19: -- accidentellement l'image d'un autre club ou une URL externe dans la
 20: -- fiche. Le premier segment du chemin doit toujours être l'id de la ligne.
 21: DO $$
 22: BEGIN
 23:   IF NOT EXISTS (
 24:     SELECT 1 FROM pg_constraint
 25:     WHERE conrelid = 'public.clubs'::regclass
 26:       AND conname = 'clubs_accent_color_hex_check'
 27:   ) THEN
 28:     ALTER TABLE public.clubs
 29:       ADD CONSTRAINT clubs_accent_color_hex_check
 30:       CHECK (accent_color ~ '^#[0-9A-Fa-f]{6}$');
 31:   END IF;
 32: 
 33:   IF NOT EXISTS (
 34:     SELECT 1 FROM pg_constraint
 35:     WHERE conrelid = 'public.clubs'::regclass
 36:       AND conname = 'clubs_logo_path_scoped_check'
 37:   ) THEN
 38:     ALTER TABLE public.clubs
 39:       ADD CONSTRAINT clubs_logo_path_scoped_check
 40:       CHECK (
 41:         logo_path IS NULL OR (
 42:           logo_path LIKE (id::text || '/%')
 43:           AND char_length(logo_path) <= 500
 44:           AND position('..' IN logo_path) = 0
 45:           AND position('//' IN logo_path) = 0
 46:           AND position('?' IN logo_path) = 0
 47:           AND position('#' IN logo_path) = 0
 48:           AND position(chr(92) IN logo_path) = 0
 49:           AND logo_path ~* '\.(png|jpe?g|webp)$'
 50:         )
 51:       );
 52:   END IF;
 53: 
 54:   IF NOT EXISTS (
 55:     SELECT 1 FROM pg_constraint
 56:     WHERE conrelid = 'public.clubs'::regclass
 57:       AND conname = 'clubs_cover_path_scoped_check'
 58:   ) THEN
 59:     ALTER TABLE public.clubs
 60:       ADD CONSTRAINT clubs_cover_path_scoped_check
 61:       CHECK (
 62:         cover_path IS NULL OR (
 63:           cover_path LIKE (id::text || '/%')
 64:           AND char_length(cover_path) <= 500
 65:           AND position('..' IN cover_path) = 0
 66:           AND position('//' IN cover_path) = 0
 67:           AND position('?' IN cover_path) = 0
 68:           AND position('#' IN cover_path) = 0
 69:           AND position(chr(92) IN cover_path) = 0
 70:           AND cover_path ~* '\.(png|jpe?g|webp)$'
 71:         )
 72:       );
 73:   END IF;
 74: END;
 75: $$;
 76: 
 77: COMMENT ON COLUMN public.clubs.logo_path IS
 78:   'Chemin privé dans le bucket club-branding, préfixé par le club_id.';
 79: COMMENT ON COLUMN public.clubs.cover_path IS
 80:   'Chemin privé de la couverture dans club-branding, préfixé par le club_id.';
 81: COMMENT ON COLUMN public.clubs.accent_color IS
 82:   'Couleur d''accent du club au format hexadécimal strict #RRGGBB.';
 83: 
 84: -- Bucket volontairement privé. Supabase contrôle la taille et le MIME
 85: -- côté serveur ; le client ne peut donc pas contourner ces limites.
 86: INSERT INTO storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
 87: VALUES (
 88:   'club-branding',
 89:   'club-branding',
 90:   false,
 91:   5242880, -- 5 Mo
 92:   ARRAY['image/png', 'image/jpeg', 'image/webp']
 93: )
 94: ON CONFLICT (id) DO UPDATE
 95: SET
 96:   public = EXCLUDED.public,
 97:   file_size_limit = EXCLUDED.file_size_limit,
 98:   allowed_mime_types = EXCLUDED.allowed_mime_types;
 99: 
100: -- Les membres voient uniquement les images de leur club. Cette policy est
101: -- nécessaire à createSignedUrl() sur un bucket privé.
102: DROP POLICY IF EXISTS "club members read club-branding" ON storage.objects;
103: CREATE POLICY "club members read club-branding" ON storage.objects
104:   FOR SELECT TO authenticated
105:   USING (
106:     bucket_id = 'club-branding'
107:     AND (storage.foldername(name))[1] = public.get_my_club_id()::text
108:   );
109: 
110: -- Seul le head coach peut modifier l'identité visuelle. WITH CHECK sur
111: -- UPDATE empêche aussi de déplacer un objet vers le dossier d'un autre
112: -- club pendant un remplacement/upsert.
113: DROP POLICY IF EXISTS "head coach upload club-branding" ON storage.objects;
114: CREATE POLICY "head coach upload club-branding" ON storage.objects
115:   FOR INSERT TO authenticated
116:   WITH CHECK (
117:     bucket_id = 'club-branding'
118:     AND public.get_my_role() = 'head_coach'
119:     AND (storage.foldername(name))[1] = public.get_my_club_id()::text
120:   );
121: 
122: DROP POLICY IF EXISTS "head coach update club-branding" ON storage.objects;
123: CREATE POLICY "head coach update club-branding" ON storage.objects
124:   FOR UPDATE TO authenticated
125:   USING (
126:     bucket_id = 'club-branding'
127:     AND public.get_my_role() = 'head_coach'
128:     AND (storage.foldername(name))[1] = public.get_my_club_id()::text
129:   )
130:   WITH CHECK (
131:     bucket_id = 'club-branding'
132:     AND public.get_my_role() = 'head_coach'
133:     AND (storage.foldername(name))[1] = public.get_my_club_id()::text
134:   );
135: 
136: DROP POLICY IF EXISTS "head coach delete club-branding" ON storage.objects;
137: CREATE POLICY "head coach delete club-branding" ON storage.objects
138:   FOR DELETE TO authenticated
139:   USING (
140:     bucket_id = 'club-branding'
141:     AND public.get_my_role() = 'head_coach'
142:     AND (storage.foldername(name))[1] = public.get_my_club_id()::text
143:   );
144: 
145: COMMIT;  1: BEGIN;
  2: 
  3: -- ============================================================
  4: -- Import CSV transactionnel d'athlètes
  5: --
  6: -- Le client ne transmet jamais le club cible : il est déduit du JWT via
  7: -- la ligne users de l'appelant. Une exception sur n'importe quelle ligne
  8: -- annule implicitement toute la fonction PostgreSQL ; aucun demi-import
  9: -- users/athletes ne peut donc rester en base.
 10: --
 11: -- Contrat p_rows (camelCase, identique au client) :
 12: -- [{
 13: --   "name": "Nora Vandenberghe",
 14: --   "email": "nora@example.com",       -- optionnel
 15: --   "age": 21,                          -- optionnel, 5..100
 16: --   "mainDiscipline": "100 m",          -- optionnel
 17: --   "secondaryDisciplines": ["200 m"],  -- optionnel
 18: --   "group": "Sprint",                  -- optionnel
 19: --   "level": "National"                 -- optionnel
 20: -- }]
 21: -- ============================================================
 22: 
 23: -- Les contrôles sont insensibles à la casse et aux espaces de bord. Cet
 24: -- index non unique accélère les recherches sans risquer de bloquer la
 25: -- migration si d'anciennes données contiennent déjà des variantes de casse.
 26: CREATE INDEX IF NOT EXISTS users_email_normalized_lookup_idx
 27:   ON public.users (lower(btrim(email)))
 28:   WHERE email IS NOT NULL;
 29: 
 30: CREATE OR REPLACE FUNCTION public.import_club_athletes(p_rows jsonb)
 31: RETURNS jsonb
 32: LANGUAGE plpgsql
 33: SECURITY DEFINER
 34: SET search_path TO 'public'
 35: AS $$
 36: DECLARE
 37:   v_caller_id          integer;
 38:   v_club_id            integer;
 39:   v_caller_role        text;
 40:   v_row_count          integer;
 41:   v_row_number         integer;
 42:   v_row                jsonb;
 43:   v_name               text;
 44:   v_email              text;
 45:   v_age_text           text;
 46:   v_age                integer;
 47:   v_main_discipline    text;
 48:   v_group_name         text;
 49:   v_level              text;
 50:   v_secondary          jsonb;
 51:   v_user_id            integer;
 52:   v_imported_count     integer := 0;
 53:   v_created_user_count integer := 0;
 54:   v_seen_emails        text[] := ARRAY[]::text[];
 55: BEGIN
 56:   -- Identité et club toujours issus du JWT, jamais de p_rows.
 57:   IF auth.uid() IS NULL THEN
 58:     RAISE EXCEPTION 'Authentification requise.' USING ERRCODE = '42501';
 59:   END IF;
 60: 
 61:   SELECT u.id, u.club_id, u.role
 62:   INTO v_caller_id, v_club_id, v_caller_role
 63:   FROM public.users u
 64:   WHERE lower(btrim(u.auth_uid)) = lower(auth.uid()::text)
 65:   LIMIT 1;
 66: 
 67:   IF v_caller_id IS NULL OR v_club_id IS NULL THEN
 68:     RAISE EXCEPTION 'Profil ou club introuvable.' USING ERRCODE = '42501';
 69:   END IF;
 70:   IF v_caller_role IS DISTINCT FROM 'head_coach' THEN
 71:     RAISE EXCEPTION 'Import réservé au head coach.' USING ERRCODE = '42501';
 72:   END IF;
 73: 
 74:   IF p_rows IS NULL OR jsonb_typeof(p_rows) <> 'array' THEN
 75:     RAISE EXCEPTION 'p_rows doit être un tableau JSON.' USING ERRCODE = '22023';
 76:   END IF;
 77:   IF octet_length(p_rows::text) > 2000000 THEN
 78:     RAISE EXCEPTION 'Import trop volumineux (maximum 2 000 000 octets).' USING ERRCODE = '22023';
 79:   END IF;
 80: 
 81:   v_row_count := jsonb_array_length(p_rows);
 82:   IF v_row_count = 0 THEN
 83:     RAISE EXCEPTION 'Aucun athlète à importer.' USING ERRCODE = '22023';
 84:   END IF;
 85:   IF v_row_count > 500 THEN
 86:     RAISE EXCEPTION 'Maximum 500 athlètes par import.' USING ERRCODE = '22023';
 87:   END IF;
 88: 
 89:   -- Première passe : tout valider avant la moindre écriture. La fonction
 90:   -- est déjà atomique, mais cette passe rend aussi les erreurs rapides et
 91:   -- évite de consommer inutilement des valeurs de séquences.
 92:   FOR v_row, v_row_number IN
 93:     SELECT item, ordinality::integer
 94:     FROM jsonb_array_elements(p_rows) WITH ORDINALITY AS rows(item, ordinality)
 95:   LOOP
 96:     IF jsonb_typeof(v_row) <> 'object' THEN
 97:       RAISE EXCEPTION 'Ligne % : un objet JSON est attendu.', v_row_number USING ERRCODE = '22023';
 98:     END IF;
 99: 
100:     IF NOT (v_row ? 'name') OR jsonb_typeof(v_row -> 'name') <> 'string' THEN
101:       RAISE EXCEPTION 'Ligne % : le nom est obligatoire.', v_row_number USING ERRCODE = '22023';
102:     END IF;
103:     v_name := btrim(v_row ->> 'name');
104:     IF v_name = '' OR char_length(v_name) > 120 OR v_name ~ '[[:cntrl:]]' THEN
105:       RAISE EXCEPTION 'Ligne % : le nom doit contenir entre 1 et 120 caractères sans caractère de contrôle.', v_row_number USING ERRCODE = '22023';
106:     END IF;
107: 
108:     IF (v_row ? 'email') AND jsonb_typeof(v_row -> 'email') NOT IN ('string', 'null') THEN
109:       RAISE EXCEPTION 'Ligne % : email invalide.', v_row_number USING ERRCODE = '22023';
110:     END IF;
111:     v_email := nullif(lower(btrim(coalesce(v_row ->> 'email', ''))), '');
112:     IF v_email IS NOT NULL AND (
113:       char_length(v_email) > 254
114:       OR v_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]{2,}$'
115:     ) THEN
116:       RAISE EXCEPTION 'Ligne % : adresse email invalide.', v_row_number USING ERRCODE = '22023';
117:     END IF;
118: 
119:     IF (v_row ? 'age') AND jsonb_typeof(v_row -> 'age') NOT IN ('number', 'string', 'null') THEN
120:       RAISE EXCEPTION 'Ligne % : âge invalide.', v_row_number USING ERRCODE = '22023';
121:     END IF;
122:     v_age_text := btrim(coalesce(v_row ->> 'age', ''));
123:     IF v_age_text = '' THEN
124:       v_age := NULL;
125:     ELSIF v_age_text !~ '^[0-9]{1,3}$' THEN
126:       RAISE EXCEPTION 'Ligne % : l''âge doit être un entier entre 5 et 100.', v_row_number USING ERRCODE = '22023';
127:     ELSE
128:       v_age := v_age_text::integer;
129:       IF v_age NOT BETWEEN 5 AND 100 THEN
130:         RAISE EXCEPTION 'Ligne % : l''âge doit être un entier entre 5 et 100.', v_row_number USING ERRCODE = '22023';
131:       END IF;
132:     END IF;
133: 
134:     IF (v_row ? 'mainDiscipline') AND jsonb_typeof(v_row -> 'mainDiscipline') NOT IN ('string', 'null') THEN
135:       RAISE EXCEPTION 'Ligne % : discipline principale invalide.', v_row_number USING ERRCODE = '22023';
136:     END IF;
137:     IF (v_row ? 'group') AND jsonb_typeof(v_row -> 'group') NOT IN ('string', 'null') THEN
138:       RAISE EXCEPTION 'Ligne % : groupe invalide.', v_row_number USING ERRCODE = '22023';
139:     END IF;
140:     IF (v_row ? 'level') AND jsonb_typeof(v_row -> 'level') NOT IN ('string', 'null') THEN
141:       RAISE EXCEPTION 'Ligne % : niveau invalide.', v_row_number USING ERRCODE = '22023';
142:     END IF;
143: 
144:     v_main_discipline := nullif(btrim(coalesce(v_row ->> 'mainDiscipline', '')), '');
145:     v_group_name := nullif(btrim(coalesce(v_row ->> 'group', '')), '');
146:     v_level := nullif(btrim(coalesce(v_row ->> 'level', '')), '');
147:     IF char_length(coalesce(v_main_discipline, '')) > 160 OR coalesce(v_main_discipline, '') ~ '[[:cntrl:]]' THEN
148:       RAISE EXCEPTION 'Ligne % : discipline principale trop longue ou invalide (maximum 160 caractères).', v_row_number USING ERRCODE = '22023';
149:     END IF;
150:     IF char_length(coalesce(v_group_name, '')) > 160 OR coalesce(v_group_name, '') ~ '[[:cntrl:]]' THEN
151:       RAISE EXCEPTION 'Ligne % : groupe trop long ou invalide (maximum 160 caractères).', v_row_number USING ERRCODE = '22023';
152:     END IF;
153:     IF char_length(coalesce(v_level, '')) > 160 OR coalesce(v_level, '') ~ '[[:cntrl:]]' THEN
154:       RAISE EXCEPTION 'Ligne % : niveau trop long ou invalide (maximum 160 caractères).', v_row_number USING ERRCODE = '22023';
155:     END IF;
156: 
157:     IF NOT (v_row ? 'secondaryDisciplines') OR jsonb_typeof(v_row -> 'secondaryDisciplines') = 'null' THEN
158:       v_secondary := '[]'::jsonb;
159:     ELSE
160:       IF jsonb_typeof(v_row -> 'secondaryDisciplines') <> 'array' THEN
161:         RAISE EXCEPTION 'Ligne % : secondaryDisciplines doit être un tableau.', v_row_number USING ERRCODE = '22023';
162:       END IF;
163:       IF jsonb_array_length(v_row -> 'secondaryDisciplines') > 20 THEN
164:         RAISE EXCEPTION 'Ligne % : maximum 20 disciplines secondaires.', v_row_number USING ERRCODE = '22023';
165:       END IF;
166:       IF EXISTS (
167:         SELECT 1
168:         FROM jsonb_array_elements(v_row -> 'secondaryDisciplines') AS discipline(item)
169:         WHERE jsonb_typeof(item) <> 'string'
170:           OR char_length(btrim(item #>> '{}')) > 160
171:           OR btrim(item #>> '{}') ~ '[[:cntrl:]]'
172:       ) THEN
173:         RAISE EXCEPTION 'Ligne % : chaque discipline secondaire doit être un texte de 160 caractères maximum.', v_row_number USING ERRCODE = '22023';
174:       END IF;
175:     END IF;
176: 
177:     IF v_email IS NOT NULL THEN
178:       IF v_email = ANY(v_seen_emails) THEN
179:         RAISE EXCEPTION 'Ligne % : email présent plusieurs fois dans cet import.', v_row_number USING ERRCODE = '23505';
180:       END IF;
181:       IF EXISTS (
182:         SELECT 1 FROM public.users existing
183:         WHERE existing.club_id = v_club_id
184:           AND lower(btrim(existing.email)) = v_email
185:       ) THEN
186:         RAISE EXCEPTION 'Ligne % : cet email est déjà présent dans le club.', v_row_number USING ERRCODE = '23505';
187:       END IF;
188:       -- users.email est globalement UNIQUE dans le schéma historique. On
189:       -- refuse donc aussi un email d'un autre club, sans divulguer lequel.
190:       IF EXISTS (
191:         SELECT 1 FROM public.users existing
192:         WHERE lower(btrim(existing.email)) = v_email
193:       ) THEN
194:         RAISE EXCEPTION 'Ligne % : cet email est déjà utilisé.', v_row_number USING ERRCODE = '23505';
195:       END IF;
196:       v_seen_emails := array_append(v_seen_emails, v_email);
197:     END IF;
198:   END LOOP;
199: 
200:   -- Deuxième passe : création cohérente. Une ligne sans email reste un
201:   -- athlète autonome (comportement existant de createAthlete) ; avec email,
202:   -- la ligne users est créée puis reliée dans la même transaction.
203:   FOR v_row, v_row_number IN
204:     SELECT item, ordinality::integer
205:     FROM jsonb_array_elements(p_rows) WITH ORDINALITY AS rows(item, ordinality)
206:   LOOP
207:     v_name := btrim(v_row ->> 'name');
208:     v_email := nullif(lower(btrim(coalesce(v_row ->> 'email', ''))), '');
209:     v_age_text := btrim(coalesce(v_row ->> 'age', ''));
210:     v_age := CASE WHEN v_age_text = '' THEN NULL ELSE v_age_text::integer END;
211:     v_main_discipline := nullif(btrim(coalesce(v_row ->> 'mainDiscipline', '')), '');
212:     v_group_name := nullif(btrim(coalesce(v_row ->> 'group', '')), '');
213:     v_level := nullif(btrim(coalesce(v_row ->> 'level', '')), '');
214: 
215:     IF NOT (v_row ? 'secondaryDisciplines') OR jsonb_typeof(v_row -> 'secondaryDisciplines') = 'null' THEN
216:       v_secondary := '[]'::jsonb;
217:     ELSE
218:       SELECT coalesce(
219:         jsonb_agg(to_jsonb(btrim(item #>> '{}')) ORDER BY ordinality)
220:           FILTER (WHERE btrim(item #>> '{}') <> ''),
221:         '[]'::jsonb
222:       )
223:       INTO v_secondary
224:       FROM jsonb_array_elements(v_row -> 'secondaryDisciplines')
225:         WITH ORDINALITY AS disciplines(item, ordinality);
226:     END IF;
227: 
228:     v_user_id := NULL;
229:     IF v_email IS NOT NULL THEN
230:       BEGIN
231:         INSERT INTO public.users (club_id, name, email, role)
232:         VALUES (v_club_id, v_name, v_email, 'athlete')
233:         RETURNING id INTO v_user_id;
234:       EXCEPTION WHEN unique_violation THEN
235:         -- Protection contre deux imports concurrents du même email. Lever
236:         -- l'erreur ici annule aussi toutes les lignes déjà créées.
237:         RAISE EXCEPTION 'Ligne % : cet email vient d''être utilisé par un autre import.', v_row_number USING ERRCODE = '23505';
238:       END;
239:       v_created_user_count := v_created_user_count + 1;
240:     END IF;
241: 
242:     INSERT INTO public.athletes (
243:       club_id,
244:       name,
245:       age,
246:       main_discipline,
247:       group_name,
248:       user_id,
249:       profile_data
250:     ) VALUES (
251:       v_club_id,
252:       v_name,
253:       v_age,
254:       v_main_discipline,
255:       v_group_name,
256:       v_user_id,
257:       jsonb_build_object(
258:         'level', v_level,
259:         'secondary_disciplines', v_secondary,
260:         'profile', jsonb_build_object(
261:           'speed', 50,
262:           'strength', 50,
263:           'explosivity', 50,
264:           'endurance', 50,
265:           'technique', 50,
266:           'recoveryRate', 'normale',
267:           'volumeTolerance', 'modérée',
268:           'intensityTolerance', 'modérée',
269:           'psychProfile', NULL
270:         )
271:       )
272:     );
273: 
274:     v_imported_count := v_imported_count + 1;
275:   END LOOP;
276: 
277:   RETURN jsonb_build_object(
278:     'importedCount', v_imported_count,
279:     'createdUserCount', v_created_user_count
280:   );
281: END;
282: $$;
283: 
284: COMMENT ON FUNCTION public.import_club_athletes(jsonb) IS
285:   'Import atomique de 1 à 500 athlètes dans le club du head coach authentifié.';
286: 
287: REVOKE ALL ON FUNCTION public.import_club_athletes(jsonb) FROM PUBLIC;
288: REVOKE ALL ON FUNCTION public.import_club_athletes(jsonb) FROM anon;
289: GRANT EXECUTE ON FUNCTION public.import_club_athletes(jsonb) TO authenticated;
290: 
291: COMMIT;  1: BEGIN;
  2: 
  3: -- ============================================================
  4: -- Rattachement d'un athlète précréé lors de join_club
  5: --
  6: -- L'import CSV crée volontairement users + athletes avant que l'athlète
  7: -- possède un compte Auth. Sans ce chemin de réclamation, users.email
  8: -- (UNIQUE) ferait échouer signup_create_account après la création Auth.
  9: --
 10: -- Règles de sécurité :
 11: --   - uniquement join_club et le club résolu par son code d'invitation ;
 12: --   - email normalisé identique dans CE club ;
 13: --   - ligne role=athlete sans auth_uid/auth_id ;
 14: --   - exactement un profil athletes déjà relié dans ce même club ;
 15: --   - verrouillage FOR UPDATE puis UPDATE conditionnel anti-concurrence ;
 16: --   - aucun nom/profil sportif importé n'est écrasé ;
 17: --   - aucune nouvelle ligne athletes n'est créée lors d'une réclamation.
 18: -- ============================================================
 19: 
 20: CREATE OR REPLACE FUNCTION public.signup_create_account(
 21:   p_mode text,
 22:   p_club_name text,
 23:   p_invite_code text,
 24:   p_auth_uid text,
 25:   p_name text,
 26:   p_email text
 27: ) RETURNS jsonb
 28: LANGUAGE plpgsql
 29: SECURITY DEFINER
 30: SET search_path TO 'public'
 31: AS $$
 32: DECLARE
 33:   v_club_id                integer;
 34:   v_user_id                integer;
 35:   v_role                   text;
 36:   v_email                  text;
 37:   v_precreated_count       integer;
 38:   v_precreated_user_id     integer;
 39:   v_athlete_count          integer;
 40:   v_athlete_in_club_count  integer;
 41:   v_updated_count          integer;
 42: BEGIN
 43:   v_email := lower(btrim(coalesce(p_email, '')));
 44:   IF v_email = '' OR char_length(v_email) > 254
 45:     OR v_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]{2,}$'
 46:   THEN
 47:     RAISE EXCEPTION 'invalid_email' USING ERRCODE = '22023';
 48:   END IF;
 49:   IF p_auth_uid IS NULL OR p_auth_uid !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
 50:     RAISE EXCEPTION 'invalid_auth_uid' USING ERRCODE = '22023';
 51:   END IF;
 52:   IF p_name IS NULL OR btrim(p_name) = '' OR char_length(btrim(p_name)) > 100 THEN
 53:     RAISE EXCEPTION 'invalid_name' USING ERRCODE = '22023';
 54:   END IF;
 55:   IF EXISTS (
 56:     SELECT 1 FROM public.users existing
 57:     WHERE lower(btrim(existing.auth_uid)) = lower(p_auth_uid)
 58:   ) THEN
 59:     RAISE EXCEPTION 'auth_uid_already_linked' USING ERRCODE = '23505';
 60:   END IF;
 61: 
 62:   IF p_mode = 'create_club' THEN
 63:     INSERT INTO public.clubs (name, invite_code)
 64:     VALUES (p_club_name, p_invite_code)
 65:     RETURNING id INTO v_club_id;
 66:     v_role := 'head_coach';
 67: 
 68:   ELSIF p_mode = 'join_club' THEN
 69:     SELECT c.id
 70:     INTO v_club_id
 71:     FROM public.clubs c
 72:     WHERE c.invite_code = p_invite_code;
 73:     IF v_club_id IS NULL THEN
 74:       RAISE EXCEPTION 'invalid_invite_code' USING ERRCODE = '22023';
 75:     END IF;
 76:     v_role := 'athlete';
 77: 
 78:     -- Compte précréé par import dans CE club uniquement. Le comptage
 79:     -- explicite refuse une ancienne anomalie de casse plutôt que de choisir
 80:     -- arbitrairement une identité parmi plusieurs lignes.
 81:     SELECT count(*)::integer
 82:     INTO v_precreated_count
 83:     FROM public.users imported
 84:     WHERE imported.club_id = v_club_id
 85:       AND imported.role = 'athlete'
 86:       AND imported.auth_uid IS NULL
 87:       AND imported.auth_id IS NULL
 88:       AND lower(btrim(imported.email)) = v_email;
 89: 
 90:     IF v_precreated_count > 1 THEN
 91:       RAISE EXCEPTION 'ambiguous_imported_athlete' USING ERRCODE = '23505';
 92:     END IF;
 93: 
 94:     IF v_precreated_count = 1 THEN
 95:       SELECT imported.id
 96:       INTO v_precreated_user_id
 97:       FROM public.users imported
 98:       WHERE imported.club_id = v_club_id
 99:         AND imported.role = 'athlete'
100:         AND imported.auth_uid IS NULL
101:         AND imported.auth_id IS NULL
102:         AND lower(btrim(imported.email)) = v_email
103:       FOR UPDATE;
104: 
105:       -- La ligne doit provenir d'une création cohérente users+athletes.
106:       -- On ne "répare" pas silencieusement une ligne orpheline et on ne
107:       -- crée surtout jamais un second profil sportif.
108:       SELECT
109:         count(*)::integer,
110:         (count(*) FILTER (WHERE a.club_id = v_club_id))::integer
111:       INTO v_athlete_count, v_athlete_in_club_count
112:       FROM public.athletes a
113:       WHERE a.user_id = v_precreated_user_id;
114: 
115:       IF v_athlete_count <> 1 OR v_athlete_in_club_count <> 1 THEN
116:         RAISE EXCEPTION 'invalid_imported_athlete_profile' USING ERRCODE = '23514';
117:       END IF;
118: 
119:       UPDATE public.users
120:       SET auth_uid = p_auth_uid
121:       WHERE id = v_precreated_user_id
122:         AND club_id = v_club_id
123:         AND role = 'athlete'
124:         AND auth_uid IS NULL
125:         AND auth_id IS NULL;
126:       GET DIAGNOSTICS v_updated_count = ROW_COUNT;
127:       IF v_updated_count <> 1 THEN
128:         RAISE EXCEPTION 'imported_athlete_already_claimed' USING ERRCODE = '23505';
129:       END IF;
130: 
131:       RETURN jsonb_build_object(
132:         'clubId', v_club_id,
133:         'userId', v_precreated_user_id,
134:         'claimedImportedAthlete', true
135:       );
136:     END IF;
137:   ELSE
138:     RAISE EXCEPTION 'invalid_mode' USING ERRCODE = '22023';
139:   END IF;
140: 
141:   -- Aucun compte importé réclamable. Une ligne portant déjà cet email
142:   -- (même club lié, autre club, ou autre rôle) ne doit jamais être prise
143:   -- ni contournée : l'Edge Function supprimera le compte Auth nouvellement
144:   -- créé en compensation de cette erreur transactionnelle.
145:   IF EXISTS (
146:     SELECT 1 FROM public.users existing
147:     WHERE lower(btrim(existing.email)) = v_email
148:   ) THEN
149:     RAISE EXCEPTION 'email_already_reserved' USING ERRCODE = '23505';
150:   END IF;
151: 
152:   INSERT INTO public.users (auth_uid, name, email, role, club_id)
153:   VALUES (p_auth_uid, btrim(p_name), v_email, v_role, v_club_id)
154:   RETURNING id INTO v_user_id;
155: 
156:   IF p_mode = 'join_club' THEN
157:     INSERT INTO public.athletes (club_id, name, user_id)
158:     VALUES (v_club_id, btrim(p_name), v_user_id);
159:   END IF;
160: 
161:   RETURN jsonb_build_object(
162:     'clubId', v_club_id,
163:     'userId', v_user_id,
164:     'claimedImportedAthlete', false
165:   );
166: END;
167: $$;
168: 
169: REVOKE ALL ON FUNCTION public.signup_create_account(text, text, text, text, text, text) FROM PUBLIC;
170: REVOKE ALL ON FUNCTION public.signup_create_account(text, text, text, text, text, text) FROM anon;
171: REVOKE ALL ON FUNCTION public.signup_create_account(text, text, text, text, text, text) FROM authenticated;
172: GRANT EXECUTE ON FUNCTION public.signup_create_account(text, text, text, text, text, text) TO service_role;
173: 
174: COMMIT;  1: BEGIN;
  2: 
  3: -- AthleteOS Performance Metadata v1. Ces colonnes sont additives : les
  4: -- anciennes lignes restent lisibles et sont marquées "unknown" lorsqu'une
  5: -- condition de compétition ne peut pas être reconstruite honnêtement.
  6: ALTER TABLE public.athlete_performances
  7:   ADD COLUMN measurement_type text,
  8:   ADD COLUMN performance_direction text,
  9:   ADD COLUMN venue_type text NOT NULL DEFAULT 'unknown',
 10:   ADD COLUMN wind_mps numeric,
 11:   ADD COLUMN timing_method text NOT NULL DEFAULT 'unknown',
 12:   ADD COLUMN implement_weight_kg numeric,
 13:   ADD COLUMN hurdle_height_m numeric,
 14:   ADD COLUMN official_status text NOT NULL DEFAULT 'unknown',
 15:   ADD COLUMN scoring_table_version text,
 16:   ADD COLUMN metadata_version text NOT NULL DEFAULT 'athleteos-performance-v1';
 17: 
 18: ALTER TABLE public.competition_results
 19:   ADD COLUMN measurement_type text,
 20:   ADD COLUMN performance_direction text,
 21:   ADD COLUMN venue_type text NOT NULL DEFAULT 'unknown',
 22:   ADD COLUMN wind_mps numeric,
 23:   ADD COLUMN timing_method text NOT NULL DEFAULT 'unknown',
 24:   ADD COLUMN implement_weight_kg numeric,
 25:   ADD COLUMN hurdle_height_m numeric,
 26:   ADD COLUMN official_status text NOT NULL DEFAULT 'unknown',
 27:   ADD COLUMN scoring_table_version text,
 28:   ADD COLUMN metadata_version text NOT NULL DEFAULT 'athleteos-performance-v1';
 29: 
 30: ALTER TABLE public.records
 31:   ADD COLUMN measurement_type text,
 32:   ADD COLUMN performance_direction text,
 33:   ADD COLUMN metadata_version text NOT NULL DEFAULT 'athleteos-performance-v1';
 34: 
 35: -- Le catalogue officiel utilise s/m/pts, mais une épreuve club explicite
 36: -- peut avoir une autre unité courte. On interdit seulement le vide et les
 37: -- chaînes déraisonnablement longues au lieu de la réinterpréter en chrono.
 38: ALTER TABLE public.athlete_performances DROP CONSTRAINT athlete_performances_unit_check;
 39: ALTER TABLE public.competition_results DROP CONSTRAINT competition_results_unit_check;
 40: ALTER TABLE public.records DROP CONSTRAINT records_unit_check;
 41: ALTER TABLE public.athlete_performances ADD CONSTRAINT athlete_performances_unit_check CHECK (unit IS NULL OR char_length(btrim(unit)) BETWEEN 1 AND 16);
 42: ALTER TABLE public.competition_results ADD CONSTRAINT competition_results_unit_check CHECK (unit IS NULL OR char_length(btrim(unit)) BETWEEN 1 AND 16);
 43: ALTER TABLE public.records ADD CONSTRAINT records_unit_check CHECK (unit IS NULL OR char_length(btrim(unit)) BETWEEN 1 AND 16);
 44: 
 45: ALTER TABLE public.athlete_performances
 46:   ADD CONSTRAINT athlete_performances_measurement_type_check CHECK (measurement_type IS NULL OR measurement_type IN ('time', 'distance', 'points', 'unknown')),
 47:   ADD CONSTRAINT athlete_performances_direction_check CHECK (performance_direction IS NULL OR performance_direction IN ('lower', 'higher', 'unknown')),
 48:   ADD CONSTRAINT athlete_performances_venue_check CHECK (venue_type IN ('indoor', 'outdoor', 'road', 'unknown')),
 49:   ADD CONSTRAINT athlete_performances_timing_check CHECK (timing_method IN ('fully_automatic', 'hand', 'transponder', 'unknown', 'not_applicable')),
 50:   ADD CONSTRAINT athlete_performances_official_check CHECK (official_status IN ('official', 'unofficial', 'unknown')),
 51:   ADD CONSTRAINT athlete_performances_wind_check CHECK (wind_mps IS NULL OR wind_mps BETWEEN -20 AND 20),
 52:   ADD CONSTRAINT athlete_performances_implement_check CHECK (implement_weight_kg IS NULL OR implement_weight_kg > 0),
 53:   ADD CONSTRAINT athlete_performances_hurdle_check CHECK (hurdle_height_m IS NULL OR hurdle_height_m > 0);
 54: 
 55: ALTER TABLE public.competition_results
 56:   ADD CONSTRAINT competition_results_measurement_type_check CHECK (measurement_type IS NULL OR measurement_type IN ('time', 'distance', 'points', 'unknown')),
 57:   ADD CONSTRAINT competition_results_direction_check CHECK (performance_direction IS NULL OR performance_direction IN ('lower', 'higher', 'unknown')),
 58:   ADD CONSTRAINT competition_results_venue_check CHECK (venue_type IN ('indoor', 'outdoor', 'road', 'unknown')),
 59:   ADD CONSTRAINT competition_results_timing_check CHECK (timing_method IN ('fully_automatic', 'hand', 'transponder', 'unknown', 'not_applicable')),
 60:   ADD CONSTRAINT competition_results_official_check CHECK (official_status IN ('official', 'unofficial', 'unknown')),
 61:   ADD CONSTRAINT competition_results_wind_check CHECK (wind_mps IS NULL OR wind_mps BETWEEN -20 AND 20),
 62:   ADD CONSTRAINT competition_results_implement_check CHECK (implement_weight_kg IS NULL OR implement_weight_kg > 0),
 63:   ADD CONSTRAINT competition_results_hurdle_check CHECK (hurdle_height_m IS NULL OR hurdle_height_m > 0);
 64: 
 65: ALTER TABLE public.records
 66:   ADD CONSTRAINT records_measurement_type_check CHECK (measurement_type IS NULL OR measurement_type IN ('time', 'distance', 'points', 'unknown')),
 67:   ADD CONSTRAINT records_direction_check CHECK (performance_direction IS NULL OR performance_direction IN ('lower', 'higher', 'unknown'));
 68: 
 69: -- Backfill prudent fondé sur l'unité déjà normalisée. Aucune unité absente
 70: -- n'est inventée et aucune ancienne valeur libre n'est supposée être un temps.
 71: UPDATE public.athlete_performances SET
 72:   measurement_type = CASE WHEN unit = 's' THEN 'time' WHEN unit = 'm' THEN 'distance' WHEN unit = 'pts' THEN 'points' ELSE 'unknown' END,
 73:   performance_direction = CASE WHEN unit = 's' THEN 'lower' WHEN unit IN ('m', 'pts') THEN 'higher' ELSE 'unknown' END,
 74:   timing_method = CASE WHEN unit = 's' THEN 'unknown' ELSE 'not_applicable' END;
 75: 
 76: UPDATE public.competition_results SET
 77:   measurement_type = CASE WHEN unit = 's' THEN 'time' WHEN unit = 'm' THEN 'distance' WHEN unit = 'pts' THEN 'points' ELSE 'unknown' END,
 78:   performance_direction = CASE WHEN unit = 's' THEN 'lower' WHEN unit IN ('m', 'pts') THEN 'higher' ELSE 'unknown' END,
 79:   timing_method = CASE WHEN unit = 's' THEN 'unknown' ELSE 'not_applicable' END;
 80: 
 81: UPDATE public.records SET
 82:   measurement_type = CASE WHEN unit = 's' THEN 'time' WHEN unit = 'm' THEN 'distance' WHEN unit = 'pts' THEN 'points' ELSE 'unknown' END,
 83:   performance_direction = CASE WHEN unit = 's' THEN 'lower' WHEN unit IN ('m', 'pts') THEN 'higher' ELSE 'unknown' END;
 84: 
 85: CREATE OR REPLACE FUNCTION public.add_athlete_performance(
 86:   p_discipline text,
 87:   p_value text,
 88:   p_result_value numeric,
 89:   p_performance_date date,
 90:   p_context text DEFAULT NULL,
 91:   p_breakdown jsonb DEFAULT NULL,
 92:   p_metadata jsonb DEFAULT '{}'::jsonb,
 93:   p_idempotency_key text DEFAULT NULL
 94: ) RETURNS jsonb
 95: LANGUAGE plpgsql
 96: SECURITY DEFINER
 97: SET search_path TO 'public'
 98: AS $$
 99: DECLARE
100:   v_user_id integer;
101:   v_club_id integer;
102:   v_athlete_id integer;
103:   v_cached jsonb;
104:   v_performance_id bigint;
105:   v_record_id integer;
106:   v_existing_pr numeric;
107:   v_existing_sb numeric;
108:   v_is_pr boolean := false;
109:   v_is_sb boolean := false;
110:   v_this_year boolean;
111:   v_direction text := coalesce(nullif(p_metadata->>'performance_direction', ''), 'unknown');
112:   v_unit text := nullif(p_metadata->>'unit', '');
113:   v_measurement text := coalesce(nullif(p_metadata->>'measurement_type', ''), 'unknown');
114:   v_result jsonb;
115: BEGIN
116:   SELECT id, club_id INTO v_user_id, v_club_id FROM public.users
117:   WHERE lower(trim(auth_uid)) = lower(trim(auth.uid()::text)) LIMIT 1;
118:   IF v_user_id IS NULL THEN RAISE EXCEPTION 'Profil introuvable.'; END IF;
119:   SELECT id INTO v_athlete_id FROM public.athletes WHERE user_id = v_user_id AND club_id = v_club_id LIMIT 1;
120:   IF v_athlete_id IS NULL THEN RAISE EXCEPTION 'Profil athlète introuvable.'; END IF;
121: 
122:   IF p_idempotency_key IS NOT NULL THEN
123:     SELECT result INTO v_cached FROM public.rpc_idempotency
124:     WHERE fn_name = 'add_athlete_performance' AND idempotency_key = p_idempotency_key AND actor_user_id = v_user_id;
125:     IF v_cached IS NOT NULL THEN RETURN v_cached; END IF;
126:   END IF;
127: 
128:   IF nullif(btrim(p_discipline), '') IS NULL THEN RAISE EXCEPTION 'Discipline manquante.'; END IF;
129:   IF nullif(btrim(p_value), '') IS NULL OR p_result_value IS NULL THEN RAISE EXCEPTION 'Résultat non interprétable.'; END IF;
130:   IF p_performance_date IS NULL THEN RAISE EXCEPTION 'Date manquante.'; END IF;
131:   IF v_direction NOT IN ('lower', 'higher') THEN RAISE EXCEPTION 'Sens de performance à préciser.'; END IF;
132:   IF v_measurement NOT IN ('time', 'distance', 'points') THEN RAISE EXCEPTION 'Type de mesure à préciser.'; END IF;
133:   IF v_unit IS NULL THEN RAISE EXCEPTION 'Unité de performance à préciser.'; END IF;
134: 
135:   INSERT INTO public.athlete_performances (
136:     athlete_id, club_id, discipline, discipline_type, value, performance_date,
137:     context, breakdown, normalized_value, unit, discipline_id, quality_flags,
138:     measurement_type, performance_direction, venue_type, wind_mps, timing_method,
139:     implement_weight_kg, hurdle_height_m, official_status, scoring_table_version, metadata_version
140:   ) VALUES (
141:     v_athlete_id, v_club_id, p_discipline, p_discipline, p_value, p_performance_date,
142:     nullif(p_context, ''), p_breakdown, p_result_value, v_unit, p_discipline, '{}',
143:     v_measurement, v_direction, coalesce(p_metadata->>'venue_type', 'unknown'),
144:     nullif(p_metadata->>'wind_mps', '')::numeric, coalesce(p_metadata->>'timing_method', 'unknown'),
145:     nullif(p_metadata->>'implement_weight_kg', '')::numeric, nullif(p_metadata->>'hurdle_height_m', '')::numeric,
146:     coalesce(p_metadata->>'official_status', 'unknown'), nullif(p_metadata->>'scoring_table_version', ''),
147:     coalesce(p_metadata->>'metadata_version', 'athleteos-performance-v1')
148:   ) RETURNING id INTO v_performance_id;
149: 
150:   v_this_year := date_part('year', p_performance_date) = date_part('year', now());
151:   INSERT INTO public.records (athlete_id, discipline, pr, pr_value, pr_date, sb, sb_value, unit, discipline_id, measurement_type, performance_direction)
152:   VALUES (v_athlete_id, p_discipline, p_value, p_result_value, p_performance_date,
153:     CASE WHEN v_this_year THEN p_value END, CASE WHEN v_this_year THEN p_result_value END,
154:     v_unit, p_discipline, v_measurement, v_direction)
155:   ON CONFLICT (athlete_id, discipline) DO NOTHING RETURNING id INTO v_record_id;
156: 
157:   IF v_record_id IS NOT NULL THEN
158:     v_is_pr := true;
159:     v_is_sb := v_this_year;
160:   ELSE
161:     SELECT id, pr_value, sb_value INTO v_record_id, v_existing_pr, v_existing_sb
162:     FROM public.records WHERE athlete_id = v_athlete_id AND discipline = p_discipline FOR UPDATE;
163:     v_is_pr := v_existing_pr IS NULL OR (v_direction = 'higher' AND p_result_value > v_existing_pr) OR (v_direction = 'lower' AND p_result_value < v_existing_pr);
164:     v_is_sb := v_this_year AND (v_existing_sb IS NULL OR (v_direction = 'higher' AND p_result_value > v_existing_sb) OR (v_direction = 'lower' AND p_result_value < v_existing_sb));
165:     UPDATE public.records SET
166:       pr = CASE WHEN v_is_pr THEN p_value ELSE pr END,
167:       pr_value = CASE WHEN v_is_pr THEN p_result_value ELSE pr_value END,
168:       pr_date = CASE WHEN v_is_pr THEN p_performance_date ELSE pr_date END,
169:       sb = CASE WHEN v_is_sb THEN p_value ELSE sb END,
170:       sb_value = CASE WHEN v_is_sb THEN p_result_value ELSE sb_value END,
171:       unit = v_unit, discipline_id = p_discipline,
172:       measurement_type = v_measurement, performance_direction = v_direction
173:     WHERE id = v_record_id;
174:   END IF;
175: 
176:   v_result := jsonb_build_object('performanceId', v_performance_id, 'recordId', v_record_id, 'isNewRecord', v_is_pr, 'isNewSeasonBest', v_is_sb);
177:   IF p_idempotency_key IS NOT NULL THEN
178:     INSERT INTO public.rpc_idempotency (fn_name, idempotency_key, actor_user_id, result)
179:     VALUES ('add_athlete_performance', p_idempotency_key, v_user_id, v_result)
180:     ON CONFLICT (fn_name, idempotency_key) DO NOTHING;
181:   END IF;
182:   RETURN v_result;
183: END;
184: $$;
185: 
186: -- V2 enveloppe les RPC de compétition existantes : même transaction, aucun
187: -- retrait de compatibilité, et contexte structuré ajouté après leur écriture.
188: CREATE OR REPLACE FUNCTION public.add_competition_result_v2(
189:   p_competition_id integer, p_athlete_id integer, p_event text, p_result text,
190:   p_result_value numeric, p_higher_is_better boolean, p_context text DEFAULT NULL,
191:   p_idempotency_key text DEFAULT NULL, p_unit text DEFAULT NULL,
192:   p_metadata jsonb DEFAULT '{}'::jsonb
193: ) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $$
194: DECLARE v_result jsonb;
195: BEGIN
196:   IF coalesce(p_metadata->>'measurement_type', 'unknown') NOT IN ('time', 'distance', 'points')
197:     OR coalesce(p_metadata->>'performance_direction', 'unknown') NOT IN ('lower', 'higher')
198:     OR nullif(coalesce(p_unit, p_metadata->>'unit'), '') IS NULL
199:   THEN RAISE EXCEPTION 'Métadonnées de performance incomplètes.'; END IF;
200:   IF (p_metadata->>'performance_direction' = 'higher') IS DISTINCT FROM p_higher_is_better
201:   THEN RAISE EXCEPTION 'Sens de comparaison incohérent.'; END IF;
202:   v_result := public.add_competition_result(p_competition_id, p_athlete_id, p_event, p_result, p_result_value, p_higher_is_better, p_context, p_idempotency_key, p_unit);
203:   IF NOT EXISTS (
204:     SELECT 1 FROM public.competition_results cr
205:     JOIN public.competitions c ON c.id = cr.competition_id
206:     JOIN public.users u ON u.club_id = c.club_id
207:     WHERE cr.id = (v_result->>'resultId')::integer
208:       AND lower(trim(u.auth_uid)) = lower(trim(auth.uid()::text))
209:       AND u.role IN ('head_coach', 'coach')
210:   ) THEN RAISE EXCEPTION 'Résultat inaccessible.'; END IF;
211:   UPDATE public.competition_results SET
212:     measurement_type = p_metadata->>'measurement_type', performance_direction = p_metadata->>'performance_direction',
213:     venue_type = coalesce(p_metadata->>'venue_type', 'unknown'), wind_mps = nullif(p_metadata->>'wind_mps', '')::numeric,
214:     timing_method = coalesce(p_metadata->>'timing_method', 'unknown'), implement_weight_kg = nullif(p_metadata->>'implement_weight_kg', '')::numeric,
215:     hurdle_height_m = nullif(p_metadata->>'hurdle_height_m', '')::numeric, official_status = coalesce(p_metadata->>'official_status', 'unknown'),
216:     scoring_table_version = nullif(p_metadata->>'scoring_table_version', ''), metadata_version = coalesce(p_metadata->>'metadata_version', 'athleteos-performance-v1')
217:   WHERE id = (v_result->>'resultId')::integer;
218:   UPDATE public.records SET measurement_type = p_metadata->>'measurement_type', performance_direction = p_metadata->>'performance_direction'
219:   WHERE id = (v_result->>'recordId')::integer;
220:   RETURN v_result;
221: END; $$;
222: 
223: CREATE OR REPLACE FUNCTION public.create_solo_competition_result_v2(
224:   p_name text, p_date date, p_location text, p_type text, p_event text, p_result text,
225:   p_result_value numeric, p_higher_is_better boolean, p_context text DEFAULT NULL,
226:   p_idempotency_key text DEFAULT NULL, p_breakdown jsonb DEFAULT NULL, p_unit text DEFAULT NULL,
227:   p_metadata jsonb DEFAULT '{}'::jsonb
228: ) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $$
229: DECLARE v_result jsonb;
230: BEGIN
231:   IF coalesce(p_metadata->>'measurement_type', 'unknown') NOT IN ('time', 'distance', 'points')
232:     OR coalesce(p_metadata->>'performance_direction', 'unknown') NOT IN ('lower', 'higher')
233:     OR nullif(coalesce(p_unit, p_metadata->>'unit'), '') IS NULL
234:   THEN RAISE EXCEPTION 'Métadonnées de performance incomplètes.'; END IF;
235:   IF (p_metadata->>'performance_direction' = 'higher') IS DISTINCT FROM p_higher_is_better
236:   THEN RAISE EXCEPTION 'Sens de comparaison incohérent.'; END IF;
237:   v_result := public.create_solo_competition_result(p_name, p_date, p_location, p_type, p_event, p_result, p_result_value, p_higher_is_better, p_context, p_idempotency_key, p_breakdown, p_unit);
238:   IF NOT EXISTS (
239:     SELECT 1 FROM public.athlete_performances ap
240:     JOIN public.athletes a ON a.id = ap.athlete_id
241:     JOIN public.users u ON u.id = a.user_id
242:     WHERE ap.id = (v_result->>'performanceId')::bigint
243:       AND lower(trim(u.auth_uid)) = lower(trim(auth.uid()::text))
244:   ) THEN RAISE EXCEPTION 'Performance inaccessible.'; END IF;
245:   UPDATE public.competition_results SET
246:     measurement_type = p_metadata->>'measurement_type', performance_direction = p_metadata->>'performance_direction',
247:     venue_type = coalesce(p_metadata->>'venue_type', 'unknown'), wind_mps = nullif(p_metadata->>'wind_mps', '')::numeric,
248:     timing_method = coalesce(p_metadata->>'timing_method', 'unknown'), implement_weight_kg = nullif(p_metadata->>'implement_weight_kg', '')::numeric,
249:     hurdle_height_m = nullif(p_metadata->>'hurdle_height_m', '')::numeric, official_status = coalesce(p_metadata->>'official_status', 'unknown'),
250:     scoring_table_version = nullif(p_metadata->>'scoring_table_version', ''), metadata_version = coalesce(p_metadata->>'metadata_version', 'athleteos-performance-v1')
251:   WHERE id = (v_result->>'resultId')::integer;
252:   UPDATE public.athlete_performances SET
253:     measurement_type = p_metadata->>'measurement_type', performance_direction = p_metadata->>'performance_direction',
254:     venue_type = coalesce(p_metadata->>'venue_type', 'unknown'), wind_mps = nullif(p_metadata->>'wind_mps', '')::numeric,
255:     timing_method = coalesce(p_metadata->>'timing_method', 'unknown'), implement_weight_kg = nullif(p_metadata->>'implement_weight_kg', '')::numeric,
256:     hurdle_height_m = nullif(p_metadata->>'hurdle_height_m', '')::numeric, official_status = coalesce(p_metadata->>'official_status', 'unknown'),
257:     scoring_table_version = nullif(p_metadata->>'scoring_table_version', ''), metadata_version = coalesce(p_metadata->>'metadata_version', 'athleteos-performance-v1')
258:   WHERE id = (v_result->>'performanceId')::bigint;
259:   UPDATE public.records SET measurement_type = p_metadata->>'measurement_type', performance_direction = p_metadata->>'performance_direction'
260:   WHERE id = (v_result->>'recordId')::integer;
261:   RETURN v_result;
262: END; $$;
