264: REVOKE ALL ON FUNCTION public.add_athlete_performance(text, text, numeric, date, text, jsonb, jsonb, text) FROM PUBLIC;
265: REVOKE ALL ON FUNCTION public.add_competition_result_v2(integer, integer, text, text, numeric, boolean, text, text, text, jsonb) FROM PUBLIC;
266: REVOKE ALL ON FUNCTION public.create_solo_competition_result_v2(text, date, text, text, text, text, numeric, boolean, text, text, jsonb, text, jsonb) FROM PUBLIC;
267: GRANT EXECUTE ON FUNCTION public.add_athlete_performance(text, text, numeric, date, text, jsonb, jsonb, text) TO authenticated;
268: GRANT EXECUTE ON FUNCTION public.add_competition_result_v2(integer, integer, text, text, numeric, boolean, text, text, text, jsonb) TO authenticated;
269: GRANT EXECUTE ON FUNCTION public.create_solo_competition_result_v2(text, date, text, text, text, text, numeric, boolean, text, text, jsonb, text, jsonb) TO authenticated;
