 93:     invite_code_last_used_at = now()
 94:   WHERE upper(btrim(invite_code)) = upper(btrim(p_invite_code))
 95:     AND (invite_code_expires_at IS NULL OR invite_code_expires_at > now());
 96: END;
 97: $$;
