 54: CREATE OR REPLACE FUNCTION public.protect_session_day_coach_fields()
 55: RETURNS trigger
 56: LANGUAGE plpgsql
 57: SET search_path TO 'public'
 58: AS $$
 59: BEGIN
 60:   IF auth.role() = 'authenticated' AND public.get_my_role() = 'athlete' THEN
 61:     IF NEW.session_id IS DISTINCT FROM OLD.session_id
 62:       OR NEW.athlete_id IS DISTINCT FROM OLD.athlete_id
 63:       OR NEW.attendance_status IS DISTINCT FROM OLD.attendance_status
 64:       OR NEW.attendance_marked_at IS DISTINCT FROM OLD.attendance_marked_at
 65:       OR NEW.coach_note IS DISTINCT FROM OLD.coach_note THEN
 66:       RAISE EXCEPTION 'Les présences réelles et observations sont réservées au staff.';
 67:     END IF;
 68:   END IF;
 69:   IF NEW.rpe IS NOT NULL
 70:     AND NEW.actual_duration_minutes IS NOT NULL
 71:     AND NEW.duration_source = 'reported'
 72:     AND (OLD.rpe IS DISTINCT FROM NEW.rpe OR OLD.actual_duration_minutes IS DISTINCT FROM NEW.actual_duration_minutes) THEN
 73:     NEW.feedback_submitted_at := now();
 74:   END IF;
 75:   RETURN NEW;
 76: END;
 77: $$;
 78: DROP TRIGGER IF EXISTS session_day_protect_coach_fields ON public.session_athletes;
 79: CREATE TRIGGER session_day_protect_coach_fields
 80:   BEFORE UPDATE ON public.session_athletes
 81:   FOR EACH ROW EXECUTE FUNCTION public.protect_session_day_coach_fields();
 82: 
 83: CREATE OR REPLACE FUNCTION public.protect_session_lifecycle_fields()
 84: RETURNS trigger
 85: LANGUAGE plpgsql
 86: SET search_path TO 'public'
 87: AS $$
 88: BEGIN
 89:   IF auth.role() = 'authenticated' AND public.get_my_role() = 'athlete'
 90:     AND (NEW.lifecycle_status IS DISTINCT FROM OLD.lifecycle_status
 91:       OR NEW.started_at IS DISTINCT FROM OLD.started_at
 92:       OR NEW.closed_at IS DISTINCT FROM OLD.closed_at
 93:       OR NEW.closed_by IS DISTINCT FROM OLD.closed_by) THEN
 94:     RAISE EXCEPTION 'Le démarrage et la clôture sont réservés au staff.';
 95:   END IF;
 96:   RETURN NEW;
 97: END;
 98: $$;
 99: DROP TRIGGER IF EXISTS session_day_protect_lifecycle ON public.sessions;
100: CREATE TRIGGER session_day_protect_lifecycle
101:   BEFORE UPDATE ON public.sessions
102:   FOR EACH ROW EXECUTE FUNCTION public.protect_session_lifecycle_fields();
