104: DROP POLICY IF EXISTS "sessions_club" ON public.sessions;
105: DROP POLICY IF EXISTS "sessions_club_read" ON public.sessions;
106: DROP POLICY IF EXISTS "sessions_coach_manage" ON public.sessions;
107: DROP POLICY IF EXISTS "sessions_athlete_create" ON public.sessions;
108: DROP POLICY IF EXISTS "sessions_athlete_update_own" ON public.sessions;
109: DROP POLICY IF EXISTS "sessions_athlete_delete_own" ON public.sessions;
110: CREATE POLICY "sessions_club_read" ON public.sessions
111:   FOR SELECT TO authenticated USING (club_id = public.get_my_club_id());
112: CREATE POLICY "sessions_coach_manage" ON public.sessions
113:   FOR ALL TO authenticated
114:   USING (club_id = public.get_my_club_id() AND public.get_my_role() IN ('head_coach','coach'))
115:   WITH CHECK (club_id = public.get_my_club_id() AND public.get_my_role() IN ('head_coach','coach'));
116: CREATE POLICY "sessions_athlete_create" ON public.sessions
117:   FOR INSERT TO authenticated
118:   WITH CHECK (club_id = public.get_my_club_id() AND created_by = public.get_my_user_id() AND public.get_my_role() = 'athlete');
119: CREATE POLICY "sessions_athlete_update_own" ON public.sessions
120:   FOR UPDATE TO authenticated
121:   USING (club_id = public.get_my_club_id() AND created_by = public.get_my_user_id() AND public.get_my_role() = 'athlete')
122:   WITH CHECK (club_id = public.get_my_club_id() AND created_by = public.get_my_user_id() AND public.get_my_role() = 'athlete');
123: CREATE POLICY "sessions_athlete_delete_own" ON public.sessions
124:   FOR DELETE TO authenticated
125:   USING (club_id = public.get_my_club_id() AND created_by = public.get_my_user_id() AND public.get_my_role() = 'athlete');
