127: -- Les anciennes policies donnaient à tout membre du club le droit de modifier
128: -- les réponses des autres athlètes. On conserve toutes les fonctions légitimes
129: -- en séparant lecture, gestion coach et réponse personnelle.
130: DROP POLICY IF EXISTS "session_athletes_club" ON public.session_athletes;
131: DROP POLICY IF EXISTS "session_athletes_club_read" ON public.session_athletes;
132: DROP POLICY IF EXISTS "session_athletes_coach_manage" ON public.session_athletes;
133: DROP POLICY IF EXISTS "session_athletes_athlete_respond" ON public.session_athletes;
134: DROP POLICY IF EXISTS "session_athletes_athlete_link_created_session" ON public.session_athletes;
135: CREATE POLICY "session_athletes_club_read" ON public.session_athletes
136:   FOR SELECT TO authenticated
137:   USING (EXISTS (
138:     SELECT 1 FROM public.sessions s
139:     WHERE s.id = session_athletes.session_id AND s.club_id = public.get_my_club_id()
140:   ));
141: CREATE POLICY "session_athletes_coach_manage" ON public.session_athletes
142:   FOR ALL TO authenticated
143:   USING (
144:     public.get_my_role() IN ('head_coach','coach')
145:     AND EXISTS (SELECT 1 FROM public.sessions s WHERE s.id = session_athletes.session_id AND s.club_id = public.get_my_club_id())
146:   )
147:   WITH CHECK (
148:     public.get_my_role() IN ('head_coach','coach')
149:     AND EXISTS (SELECT 1 FROM public.sessions s WHERE s.id = session_athletes.session_id AND s.club_id = public.get_my_club_id())
150:   );
151: CREATE POLICY "session_athletes_athlete_respond" ON public.session_athletes
152:   FOR UPDATE TO authenticated
153:   USING (athlete_id = public.get_my_athlete_id())
154:   WITH CHECK (athlete_id = public.get_my_athlete_id());
155: CREATE POLICY "session_athletes_athlete_link_created_session" ON public.session_athletes
