 3: -- Suppression métier tout-ou-rien. Cette migration ne supprime aucune donnée
 4: -- à son application : elle expose uniquement l'opération appelée explicitement
 5: -- par admin-actions après confirmation du head coach.
 6: CREATE OR REPLACE FUNCTION public.remove_club_user_transactional(
 7:   p_actor_user_id integer,
 8:   p_target_user_id integer
 9: ) RETURNS jsonb
10: LANGUAGE plpgsql
11: SECURITY DEFINER
12: SET search_path TO 'public'
13: AS $$
14: DECLARE
15:   v_actor public.users%ROWTYPE;
16:   v_target public.users%ROWTYPE;
17:   v_other_head_coaches integer;
18: BEGIN
19:   SELECT actor.* INTO v_actor
20:   FROM public.users actor
21:   WHERE actor.id = p_actor_user_id;
22:   IF NOT FOUND OR v_actor.role <> 'head_coach' THEN
23:     RAISE EXCEPTION 'permission_denied' USING ERRCODE = '42501';
24:   END IF;
25: 
26:   -- Sérialise les mutations structurelles d'un même club avant de verrouiller
27:   -- les lignes utilisateur, afin d'éviter deux suppressions concurrentes.
28:   PERFORM pg_advisory_xact_lock(85001, v_actor.club_id);
29: 
30:   SELECT actor.* INTO v_actor
31:   FROM public.users actor
32:   WHERE actor.id = p_actor_user_id
33:   FOR UPDATE;
34:   IF NOT FOUND OR v_actor.role <> 'head_coach' THEN
35:     RAISE EXCEPTION 'actor_no_longer_authorized' USING ERRCODE = '42501';
36:   END IF;
37:   SELECT target.* INTO v_target
38:   FROM public.users target
39:   WHERE target.id = p_target_user_id
40:   FOR UPDATE;
41: 
42:   IF NOT FOUND THEN
43:     RAISE EXCEPTION 'target_not_found' USING ERRCODE = 'P0002';
44:   END IF;
45:   IF v_target.club_id <> v_actor.club_id THEN
46:     RAISE EXCEPTION 'cross_club_target' USING ERRCODE = '42501';
47:   END IF;
48:   IF v_target.id = v_actor.id THEN
49:     RAISE EXCEPTION 'self_removal_forbidden' USING ERRCODE = '42501';
50:   END IF;
51: 
52:   IF v_target.role = 'head_coach' THEN
53:     SELECT count(*)::integer INTO v_other_head_coaches
54:     FROM public.users member
55:     WHERE member.club_id = v_actor.club_id
56:       AND member.role = 'head_coach'
57:       AND member.id <> v_target.id;
58:     IF v_other_head_coaches = 0 THEN
59:       RAISE EXCEPTION 'last_head_coach' USING ERRCODE = '23514';
60:     END IF;
61:   END IF;
62: 
63:   -- Les dépendances athlete_id configurées ON DELETE CASCADE sont supprimées
64:   -- dans cette même transaction. Si users ne peut ensuite pas être supprimé,
65:   -- PostgreSQL annule également ce premier DELETE.
66:   DELETE FROM public.athletes WHERE user_id = v_target.id;
67:   DELETE FROM public.users WHERE id = v_target.id;
68:   IF NOT FOUND THEN
69:     RAISE EXCEPTION 'target_delete_failed' USING ERRCODE = 'P0002';
70:   END IF;
71: 
72:   RETURN jsonb_build_object('authUid', v_target.auth_uid);
73: END;
74: $$;
75: 
76: REVOKE ALL ON FUNCTION public.remove_club_user_transactional(integer, integer) FROM PUBLIC;
77: REVOKE ALL ON FUNCTION public.remove_club_user_transactional(integer, integer) FROM anon;
78: REVOKE ALL ON FUNCTION public.remove_club_user_transactional(integer, integer) FROM authenticated;
79: GRANT EXECUTE ON FUNCTION public.remove_club_user_transactional(integer, integer) TO service_role;
80: 
81: COMMIT; 1: BEGIN;
 2: 
 3: -- Enveloppe transactionnelle du RPC historique : pour une invitation
 4: -- individuelle, la création/réclamation du compte métier et la consommation
 5: -- du lien réussissent ensemble ou sont toutes deux annulées.
 6: CREATE OR REPLACE FUNCTION public.signup_create_account_with_invitation(
 7:   p_mode text,
 8:   p_club_name text,
 9:   p_invite_code text,
10:   p_auth_uid text,
11:   p_name text,
12:   p_email text,
13:   p_individual_invitation_id uuid,
14:   p_reservation_token uuid
15: ) RETURNS jsonb
16: LANGUAGE plpgsql
17: SECURITY DEFINER
18: SET search_path TO 'public'
19: AS $$
20: DECLARE
21:   v_invitation public.club_invitations%ROWTYPE;
22:   v_club_invite_code text;
23:   v_result jsonb;
24:   v_updated_count integer;
25: BEGIN
26:   IF p_individual_invitation_id IS NULL THEN
27:     RETURN public.signup_create_account(
28:       p_mode, p_club_name, p_invite_code, p_auth_uid, p_name, p_email
29:     );
30:   END IF;
31: 
32:   IF p_mode <> 'join_club' OR p_reservation_token IS NULL THEN
33:     RAISE EXCEPTION 'invalid_individual_invitation_context' USING ERRCODE = '22023';
34:   END IF;
35: 
36:   SELECT invitation.* INTO v_invitation
37:   FROM public.club_invitations invitation
38:   WHERE invitation.id = p_individual_invitation_id
39:   FOR UPDATE;
40:   IF NOT FOUND THEN
41:     RAISE EXCEPTION 'invitation_not_found' USING ERRCODE = 'P0002';
42:   END IF;
43:   IF v_invitation.status <> 'active' OR v_invitation.accepted_at IS NOT NULL THEN
44:     RAISE EXCEPTION 'invitation_not_active' USING ERRCODE = '23514';
45:   END IF;
46:   IF v_invitation.expires_at IS NOT NULL AND v_invitation.expires_at <= now() THEN
47:     RAISE EXCEPTION 'invitation_expired' USING ERRCODE = '23514';
48:   END IF;
49:   IF v_invitation.reservation_token IS DISTINCT FROM p_reservation_token
50:     OR v_invitation.reserved_until IS NULL
51:     OR v_invitation.reserved_until <= now()
52:   THEN
53:     RAISE EXCEPTION 'invitation_reservation_lost' USING ERRCODE = '40001';
54:   END IF;
55:   IF v_invitation.recipient_email IS NOT NULL
56:     AND lower(btrim(v_invitation.recipient_email)) <> lower(btrim(coalesce(p_email, '')))
57:   THEN
58:     RAISE EXCEPTION 'invitation_email_mismatch' USING ERRCODE = '42501';
59:   END IF;
60: 
61:   SELECT club.invite_code INTO v_club_invite_code
62:   FROM public.clubs club
63:   WHERE club.id = v_invitation.club_id;
64:   IF NOT FOUND OR upper(btrim(v_club_invite_code)) <> upper(btrim(coalesce(p_invite_code, ''))) THEN
65:     RAISE EXCEPTION 'invitation_club_mismatch' USING ERRCODE = '42501';
66:   END IF;
67: 
68:   v_result := public.signup_create_account(
69:     p_mode, p_club_name, p_invite_code, p_auth_uid, p_name, p_email
70:   );
71: 
72:   UPDATE public.club_invitations
73:   SET accepted_at = now(),
74:       accepted_user_id = (v_result ->> 'userId')::integer,
75:       reservation_token = NULL,
76:       reserved_until = NULL
77:   WHERE id = v_invitation.id
78:     AND status = 'active'
79:     AND accepted_at IS NULL
80:     AND reservation_token = p_reservation_token;
81:   GET DIAGNOSTICS v_updated_count = ROW_COUNT;
82:   IF v_updated_count <> 1 THEN
83:     RAISE EXCEPTION 'invitation_acceptance_conflict' USING ERRCODE = '40001';
84:   END IF;
85: 
86:   RETURN v_result;
87: END;
88: $$;
89: 
90: REVOKE ALL ON FUNCTION public.signup_create_account_with_invitation(text, text, text, text, text, text, uuid, uuid) FROM PUBLIC;
91: REVOKE ALL ON FUNCTION public.signup_create_account_with_invitation(text, text, text, text, text, text, uuid, uuid) FROM anon;
92: REVOKE ALL ON FUNCTION public.signup_create_account_with_invitation(text, text, text, text, text, text, uuid, uuid) FROM authenticated;
93: GRANT EXECUTE ON FUNCTION public.signup_create_account_with_invitation(text, text, text, text, text, text, uuid, uuid) TO service_role;
94: 
95: COMMIT; 1: -- Prevent collisions between the same ISO week number in different years and
 2: -- make weekly/session reminder creation safe under retries and concurrent cron
 3: -- invocations. Existing nullable dedupe keys keep historical writes compatible.
