19: CREATE OR REPLACE VIEW public.daily_training_load
20: WITH (security_invoker = true)
21: AS
22: SELECT
23:   sa.athlete_id,
24:   s.session_date AS load_date,
25:   s.week,
26:   CASE
27:     WHEN bool_and(
28:       sa.status = 'none'
29:       OR (sa.rpe IS NOT NULL AND sa.actual_duration_minutes IS NOT NULL)
30:     ) THEN SUM(
31:       CASE
32:         WHEN sa.status = 'none' THEN 0
33:         ELSE sa.actual_duration_minutes * sa.rpe
34:       END
35:     )::integer
36:     ELSE NULL
37:   END AS raw_load,
38:   bool_and(
39:     sa.status = 'none'
40:     OR (sa.rpe IS NOT NULL AND sa.actual_duration_minutes IS NOT NULL)
41:   ) AS is_complete,
42:   bool_or(
43:     sa.status IS DISTINCT FROM 'none'
44:     AND sa.rpe IS NOT NULL
45:     AND sa.duration_source = 'planned_legacy'
46:   ) AS is_estimated,
47:   count(*)::integer AS assigned_session_count,
48:   count(*) FILTER (
49:     WHERE sa.status IS DISTINCT FROM 'none'
50:       AND (sa.rpe IS NULL OR sa.actual_duration_minutes IS NULL)
51:   )::integer AS unknown_session_count,
52:   EXTRACT(ISOYEAR FROM s.session_date)::integer AS iso_year
53: FROM public.session_athletes sa
54: JOIN public.sessions s ON s.id = sa.session_id
55: WHERE s.session_date IS NOT NULL
56: GROUP BY
57:   sa.athlete_id,
58:   s.session_date,
59:   s.week,
60:   EXTRACT(ISOYEAR FROM s.session_date);
61: 
62: GRANT SELECT ON public.daily_training_load TO authenticated;
63: 
64: CREATE OR REPLACE VIEW public.weekly_charge
65: WITH (security_invoker = true)
66: AS
67: SELECT
68:   d.athlete_id,
69:   d.week,
70:   CASE
71:     WHEN bool_and(d.raw_load IS NOT NULL) THEN SUM(d.raw_load)::integer
72:     ELSE NULL
73:   END AS raw_load,
74:   jsonb_agg(
75:     jsonb_build_object(
76:       'date', d.load_date,
77:       'load', d.raw_load,
78:       'estimated', d.is_estimated,
79:       'complete', d.is_complete
80:     ) ORDER BY d.load_date
81:   ) AS daily_loads,
82:   count(*) FILTER (WHERE d.raw_load IS NOT NULL)::integer AS known_days,
83:   count(*) FILTER (WHERE d.raw_load IS NULL)::integer AS unknown_days,
84:   count(*) FILTER (WHERE d.is_estimated)::integer AS estimated_days,
85:   d.iso_year
86: FROM public.daily_training_load d
87: GROUP BY d.athlete_id, d.week, d.iso_year;
88: 
89: GRANT SELECT ON public.weekly_charge TO authenticated;
90: 
91: COMMIT; 1: BEGIN;
 2: 
 3: -- Consomme une invitation individuelle pour un compte déjà existant sous
 4: -- verrou de ligne. Deux clics concurrents deviennent idempotents pour le même
 5: -- utilisateur et ne peuvent jamais annoncer un succès à deux utilisateurs.
 6: CREATE OR REPLACE FUNCTION public.accept_existing_member_club_invitation(
 7:   p_invitation_id uuid,
 8:   p_user_id integer,
 9:   p_email text
10: ) RETURNS jsonb
11: LANGUAGE plpgsql
12: SECURITY DEFINER
13: SET search_path TO 'public'
14: AS $$
15: DECLARE
16:   v_invitation public.club_invitations%ROWTYPE;
17:   v_user_club_id integer;
18:   v_club_name text;
19: BEGIN
20:   SELECT invitation.* INTO v_invitation
21:   FROM public.club_invitations invitation
22:   WHERE invitation.id = p_invitation_id
23:   FOR UPDATE;
24: 
25:   IF NOT FOUND THEN
26:     RETURN jsonb_build_object('status', 'invalid');
27:   END IF;
28: 
29:   IF v_invitation.accepted_at IS NOT NULL THEN
30:     IF v_invitation.accepted_user_id = p_user_id THEN
31:       SELECT name INTO v_club_name FROM public.clubs WHERE id = v_invitation.club_id;
32:       RETURN jsonb_build_object('status', 'accepted_by_caller', 'clubName', coalesce(v_club_name, 'Ton club'));
33:     END IF;
34:     RETURN jsonb_build_object('status', 'accepted');
35:   END IF;
36: 
37:   IF v_invitation.status = 'revoked' THEN
38:     RETURN jsonb_build_object('status', 'revoked');
39:   END IF;
40:   IF v_invitation.expires_at IS NOT NULL AND v_invitation.expires_at <= now() THEN
41:     RETURN jsonb_build_object('status', 'expired');
42:   END IF;
43:   IF v_invitation.recipient_email IS NOT NULL
44:     AND lower(btrim(v_invitation.recipient_email)) <> lower(btrim(coalesce(p_email, '')))
45:   THEN
46:     RETURN jsonb_build_object('status', 'email_mismatch');
47:   END IF;
48: 
49:   SELECT app_user.club_id INTO v_user_club_id
50:   FROM public.users app_user
51:   WHERE app_user.id = p_user_id;
52:   IF NOT FOUND OR v_user_club_id <> v_invitation.club_id THEN
53:     RETURN jsonb_build_object('status', 'different_club');
54:   END IF;
55: 
56:   UPDATE public.club_invitations
57:   SET accepted_at = now(),
58:       accepted_user_id = p_user_id,
59:       reservation_token = NULL,
60:       reserved_until = NULL
61:   WHERE id = v_invitation.id;
62: 
63:   SELECT name INTO v_club_name FROM public.clubs WHERE id = v_invitation.club_id;
64:   RETURN jsonb_build_object('status', 'accepted_by_caller', 'clubName', coalesce(v_club_name, 'Ton club'));
65: END;
66: $$;
67: 
