69: REVOKE ALL ON FUNCTION public.accept_existing_member_club_invitation(uuid, integer, text) FROM anon;
70: REVOKE ALL ON FUNCTION public.accept_existing_member_club_invitation(uuid, integer, text) FROM authenticated;
71: GRANT EXECUTE ON FUNCTION public.accept_existing_member_club_invitation(uuid, integer, text) TO service_role;
