 3: -- Le bucket garde son identifiant historique pour préserver tous les chemins
 4: -- déjà stockés dans sessions.pdf_url. Il devient un bucket de pièces jointes
 5: -- de séance : privé, limité à 30 Mo et restreint aux images/documents usuels.
 6: -- Les policies RLS par club existantes continuent de s'appliquer sans changement.
 7: UPDATE storage.buckets
 8: SET
 9:   public = false,
10:   file_size_limit = 31457280,
11:   allowed_mime_types = ARRAY[
12:     'application/pdf',
13:     'image/jpeg', 'image/png', 'image/webp', 'image/gif',
14:     'image/heic', 'image/heif', 'image/avif', 'image/bmp', 'image/tiff',
15:     'application/msword',
16:     'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
17:     'application/vnd.ms-excel',
18:     'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
19:     'application/vnd.ms-powerpoint',
20:     'application/vnd.openxmlformats-officedocument.presentationml.presentation',
21:     'application/vnd.oasis.opendocument.text',
22:     'application/vnd.oasis.opendocument.spreadsheet',
23:     'application/vnd.oasis.opendocument.presentation',
24:     'application/rtf', 'text/plain', 'text/csv'
25:   ]
26: WHERE id = 'session-pdfs';
27: 
28: COMMIT; 1: BEGIN;
 2: 
 3: -- L'ajout de p_unit en 20260801020000 a créé une surcharge au lieu de
 4: -- remplacer la signature historique. L'ancienne fonction, SECURITY DEFINER,
 5: -- conservait alors le droit EXECUTE implicite de PUBLIC. Elle n'est plus
 6: -- appelée par aucun RPC et ne doit jamais constituer une API cliente.
 7: DROP FUNCTION IF EXISTS public._apply_competition_result(
 8:   integer, integer, integer, text, text, text, numeric, boolean,
 9:   text, text, boolean, date, jsonb
10: );
11: 
12: -- La seule signature restante est une aide interne appelée par les RPC
13: -- SECURITY DEFINER contrôlées. Son propriétaire postgres peut toujours
14: -- l'exécuter, mais aucun rôle Data API ne le peut directement.
15: REVOKE ALL ON FUNCTION public._apply_competition_result(
16:   integer, integer, integer, text, text, text, numeric, boolean,
17:   text, text, boolean, date, jsonb, text
18: ) FROM PUBLIC, anon, authenticated;
19: 
20: GRANT EXECUTE ON FUNCTION public._apply_competition_result(
21:   integer, integer, integer, text, text, text, numeric, boolean,
22:   text, text, boolean, date, jsonb, text
23: ) TO postgres;
24: 
25: COMMIT; 1: BEGIN;
 2: 
 3: -- RLS ne s'applique pas à TRUNCATE. Les rôles de la Data API n'ont pas
 4: -- non plus à créer des triggers ni des contraintes de référence. Les
 5: -- droits DML utiles à authenticated restent inchangés et toujours filtrés
 6: -- par les policies.
 7: REVOKE TRUNCATE, REFERENCES, TRIGGER
 8:   ON ALL TABLES IN SCHEMA public
 9:   FROM anon, authenticated;
10: 
11: -- Aucun parcours anonyme n'insère directement dans une table publique :
12: -- signup passe par une Edge Function et service_role. Les séquences n'ont
13: -- donc pas à être consommables par anon.
14: REVOKE USAGE
15:   ON ALL SEQUENCES IN SCHEMA public
16:   FROM anon;
