 3: -- Les migrations historiques créent les jobs avec l'URL du projet hébergé.
 4: -- Sur une instance locale/CI sans secret Vault, ces jobs ne doivent jamais
 5: -- tenter un appel distant. On les recrée uniquement lorsque le secret serveur
 6: -- attendu existe réellement dans l'environnement cible.
 7: SELECT cron.unschedule('weekly-notifications')
 8: WHERE EXISTS (SELECT 1 FROM cron.job WHERE jobname = 'weekly-notifications');
 9: SELECT cron.unschedule('daily-session-reminders')
10: WHERE EXISTS (SELECT 1 FROM cron.job WHERE jobname = 'daily-session-reminders');
11: 
12: DO $migration$
13: BEGIN
14:   IF EXISTS (
15:     SELECT 1
16:     FROM vault.decrypted_secrets
17:     WHERE name = 'weekly_cron_service_role_key'
18:       AND nullif(btrim(decrypted_secret), '') IS NOT NULL
19:   ) THEN
20:     PERFORM cron.schedule(
21:       'weekly-notifications',
22:       '30 18 * * 0',
23:       $cron$
24:       SELECT net.http_post(
25:         url := 'https://kuqafsmkwajeipzolbky.supabase.co/functions/v1/weekly-cron',
26:         headers := jsonb_build_object(
27:           'Content-Type', 'application/json',
28:           'Authorization', 'Bearer ' || (
29:             SELECT decrypted_secret FROM vault.decrypted_secrets
30:             WHERE name = 'weekly_cron_service_role_key'
31:           )
32:         ),
33:         body := '{}'::jsonb
34:       );
35:       $cron$
36:     );
37: 
38:     PERFORM cron.schedule(
39:       'daily-session-reminders',
40:       '30 5 * * *',
41:       $cron$
42:       SELECT net.http_post(
43:         url := 'https://kuqafsmkwajeipzolbky.supabase.co/functions/v1/session-reminders',
44:         headers := jsonb_build_object(
45:           'Content-Type', 'application/json',
46:           'Authorization', 'Bearer ' || (
47:             SELECT decrypted_secret FROM vault.decrypted_secrets
48:             WHERE name = 'weekly_cron_service_role_key'
49:           )
50:         ),
51:         body := '{}'::jsonb
52:       );
53:       $cron$
54:     );
55:   ELSE
56:     RAISE NOTICE 'Crons distants non planifiés : secret Vault absent dans cet environnement.';
57:   END IF;
58: END;
59: $migration$;
