 35: function loadDotEnv(filePath) {
 36:   let text;
 37:   try { text = readFileSync(filePath, "utf8"); } catch { return; }
 38:   for (const rawLine of text.split("\n")) {
 39:     const line = rawLine.replace(/\r$/, "");
 40:     const m = line.match(/^([A-Z0-9_]+)=(.*)$/);
 41:     if (m && process.env[m[1]] === undefined) process.env[m[1]] = m[2].trim();
 42:   }
 43: }
 44: loadDotEnv(path.join(path.dirname(fileURLToPath(import.meta.url)), ".env"));
 45: 
 46: const SUPABASE_URL     = process.env.VITE_SUPABASE_URL;
 47: const SERVICE_ROLE_KEY = process.env.SUPABASE_SERVICE_ROLE_KEY;
 48: 
 49: if (!SUPABASE_URL || !SERVICE_ROLE_KEY) {
 50:   console.error(
 51:     "Variables manquantes. Requis : VITE_SUPABASE_URL (dans .env) et " +
 52:     "SUPABASE_SERVICE_ROLE_KEY (variable d'environnement, jamais committée)."
 53:   );
 54:   process.exit(1);
 55: }
