 61: const RUN_ID = Date.now();
 62: const results = [];
 63: function record(name, pass, detail) {
 64:   results.push({ name, pass, detail });
 65:   console.log(`${pass ? "✅" : "❌"} ${name}${detail ? " — " + detail : ""}`);
 66: }
