 68: async function insertOrThrow(table, row) {
 69:   const { data, error } = await admin.from(table).insert(row).select().single();
 70:   if (error) throw new Error(`seed ${table} : ${error.message}`);
 71:   return data;
 72: }
 73: 
 74: function sameCoefficients(dbObj, jsObj) {
 75:   const dbKeys = Object.keys(dbObj ?? {}).sort();
 76:   const jsKeys = Object.keys(jsObj ?? {}).sort();
 77:   if (dbKeys.length !== jsKeys.length) return false;
 78:   if (dbKeys.some((k, i) => k !== jsKeys[i])) return false;
 79:   return dbKeys.every((k) => Number(dbObj[k]) === Number(jsObj[k]));
 80: }
