 91:     if (activeErr) throw new Error(`lecture charge_model_versions : ${activeErr.message}`);
 92:     record("Une version active existe", !!active, active ? `version=${active.version}` : "aucune version active !");
 93: 
 94:     if (active) {
 95:       record("Version active en base === CURRENT_MODEL_VERSION (JS)", active.version === CURRENT_MODEL_VERSION,
 96:         `db=${active.version} js=${CURRENT_MODEL_VERSION}`);
 97:       record("load_coefficients : base === JS", sameCoefficients(active.load_coefficients, LOAD_COEFFICIENTS),
 98:         `db=${JSON.stringify(active.load_coefficients)} js=${JSON.stringify(LOAD_COEFFICIENTS)}`);
 99:       record("recovery_hours : base === JS", sameCoefficients(active.recovery_hours, RECOVERY_HOURS),
100:         `db=${JSON.stringify(active.recovery_hours)} js=${JSON.stringify(RECOVERY_HOURS)}`);
101:     }
102: 
103:     // ── 2. Golden dataset : JS et weekly_charge (SQL) doivent tomber sur
104:     //    le même total, pour un athlète, une semaine, plusieurs catégories ──
105:     club = await insertOrThrow("clubs", { name: `Charge Parity Test ${RUN_ID}` });
106:     athlete = await insertOrThrow("athletes", { club_id: club.id, name: `Athlete Parity Test ${RUN_ID}` });
107: 
108:     const WEEK = 1;
109:     const fixtures = [
110:       { category: "sprint",    duration_minutes: 60, rpe: 7, session_date: "2026-01-01" },
111:       { category: "force",     duration_minutes: 45, rpe: 8, session_date: "2026-01-02" },
112:       { category: "technique", duration_minutes: 90, rpe: 4, session_date: "2026-01-03" },
113:     ];
114: 
115:     let expectedTotal = 0;
116:     for (const f of fixtures) {
117:       const session = await insertOrThrow("sessions", {
118:         club_id: club.id, title: `Parity ${f.category} ${RUN_ID}`,
119:         category: f.category, week: WEEK, duration_minutes: f.duration_minutes, session_date: f.session_date,
120:       });
121:       sessionIds.push(session.id);
122:       await insertOrThrow("session_athletes", {
123:         session_id: session.id, athlete_id: athlete.id, status: "done", rpe: f.rpe,
124:         actual_duration_minutes: f.duration_minutes, duration_source: "reported",
125:       });
126:       expectedTotal += computeSessionLoad(f.duration_minutes, f.rpe, f.category);
127:     }
128: 
129:     const { data: charge, error: chargeErr } = await admin
130:       .from("weekly_charge").select("raw_load").eq("athlete_id", athlete.id).eq("week", WEEK).maybeSingle();
131:     if (chargeErr) throw new Error(`lecture weekly_charge : ${chargeErr.message}`);
132:     record("weekly_charge (SQL) === somme computeSessionLoad (JS)", charge?.raw_load === expectedTotal,
133:       `sql=${charge?.raw_load} js=${expectedTotal}`);
134: 
135:     // ── 3. Le trigger a bien timbré les lignes avec la version active ──
136:     const { data: stampedRows, error: stampErr } = await admin
137:       .from("session_athletes").select("model_version").eq("athlete_id", athlete.id).in("session_id", sessionIds);
138:     if (stampErr) throw new Error(`lecture session_athletes : ${stampErr.message}`);
139:     const allStamped = (stampedRows ?? []).length === fixtures.length &&
140:       stampedRows.every((r) => r.model_version === (active?.version ?? CURRENT_MODEL_VERSION));
141:     record("Chaque ligne RPE timbrée avec la version active", allStamped, JSON.stringify(stampedRows));
142: 
143:     // ── 4. Modifier un champ non-RPE ne change PAS le model_version ────
144:     const firstSessionId = sessionIds[0];
145:     const before = stampedRows.find((_, i) => sessionIds[i] === firstSessionId);
146:     await admin.from("session_athletes").update({ status: "done" })
147:       .eq("session_id", firstSessionId).eq("athlete_id", athlete.id);
148:     const { data: afterRow } = await admin.from("session_athletes")
149:       .select("model_version, status").eq("session_id", firstSessionId).eq("athlete_id", athlete.id).maybeSingle();
150:     record("Update d'un champ non-RPE -> model_version inchangé", afterRow?.model_version === before?.model_version,
151:       `avant=${before?.model_version} après=${afterRow?.model_version} status=${afterRow?.status}`);
152: 
153:     // ── 5. Bornes : coefficient hors bornes rejeté, dans les bornes accepté ──
154:     {
155:       const { error: badErr } = await admin.from("charge_model_versions").insert({
156:         version: `test-bad-${RUN_ID}`,
157:         load_coefficients: { force: 50 }, // hors bornes (max 3.0)
158:         recovery_hours: { force: 72 },
159:         is_active: false,
160:       });
161:       record("Coefficient hors bornes (50) -> rejeté", !!badErr, badErr?.message);
162:     }
163:     {
164:       const { error: goodErr } = await admin.from("charge_model_versions").insert({
165:         version: `test-ok-${RUN_ID}`,
166:         load_coefficients: { force: 1.5 },
167:         recovery_hours: { force: 60 },
168:         is_active: false,
169:       });
170:       record("Coefficient dans les bornes (1.5) -> accepté", !goodErr, goodErr?.message);
171:     }
172: 
173:     // ── 6. Une seule version active à la fois ───────────────────────────
174:     {
175:       const { error: dupActiveErr } = await admin.from("charge_model_versions").insert({
176:         version: `test-active-${RUN_ID}`,
177:         load_coefficients: { force: 1.2 },
178:         recovery_hours: { force: 60 },
179:         is_active: true,
180:       });
181:       record("Deuxième version active -> rejetée (contrainte unique)", !!dupActiveErr, dupActiveErr?.message);
182:     }
183: 
184:   } finally {
185:     console.log("\nNettoyage...");
186:     for (const v of scratchVersions) await admin.from("charge_model_versions").delete().eq("version", v);
187:     // Cascade FK sur athlete_id : nettoie session_athletes automatiquement.
188:     if (athlete) await admin.from("athletes").delete().eq("id", athlete.id);
189:     for (const id of sessionIds) await admin.from("sessions").delete().eq("id", id);
190:     if (club) await admin.from("clubs").delete().eq("id", club.id);
191:   }
192: 
193:   const failed = results.filter((r) => !r.pass);
194:   console.log(`\n${results.length - failed.length}/${results.length} vérifications OK`);
195:   if (failed.length) {
196:     console.error(`\n${failed.length} régression(s) détectée(s) :`);
197:     failed.forEach((f) => console.error(`  - ${f.name}${f.detail ? " : " + f.detail : ""}`));
198:     process.exit(1);
199:   }
200:   console.log("\nParité JS/SQL confirmée, bornes et versionnement fonctionnels.");
201:   process.exit(0);
202: }
203: 
204: main().catch((err) => {
205:   console.error("Erreur fatale :", err.message ?? err);
206:   process.exit(1);
207: });  1: #!/usr/bin/env node
  2: // ============================================================
  3: // AthleteOS — test_import_club_athletes.mjs
  4: //
  5: // Vérifie le RPC transactionnel import_club_athletes(jsonb) contre une
  6: // instance Supabase réelle/local CI : autorisation head coach, club dérivé
  7: // du JWT, validations et limites serveur, absence de demi-import, refus
  8: // des doublons email, cohérence users/athletes, comptage du résultat et
  9: // rattachement signup ultérieur sans doublon ni prise de compte inter-club.
 10: // ============================================================
 11: 
 12: import { createClient } from "@supabase/supabase-js";
 13: import { readFileSync } from "node:fs";
 14: import { fileURLToPath } from "node:url";
 15: import path from "node:path";
 16: import crypto from "node:crypto";
 17: 
 18: function loadDotEnv(filePath) {
 19:   let text;
 20:   try { text = readFileSync(filePath, "utf8"); } catch { return; }
 21:   for (const rawLine of text.split("\n")) {
 22:     const line = rawLine.replace(/\r$/u, "");
 23:     const match = line.match(/^([A-Z0-9_]+)=(.*)$/u);
 24:     if (match && process.env[match[1]] === undefined) process.env[match[1]] = match[2].trim();
 25:   }
 26: }
 27: loadDotEnv(path.join(path.dirname(fileURLToPath(import.meta.url)), ".env"));
 28: 
 29: const SUPABASE_URL = process.env.VITE_SUPABASE_URL ?? process.env.API_URL;
 30: const ANON_KEY = process.env.VITE_SUPABASE_ANON_KEY ?? process.env.ANON_KEY;
 31: const SERVICE_ROLE_KEY = process.env.SUPABASE_SERVICE_ROLE_KEY ?? process.env.SERVICE_ROLE_KEY;
 32: 
 33: if (!SUPABASE_URL || !ANON_KEY || !SERVICE_ROLE_KEY) {
 34:   console.error(
 35:     "Variables manquantes : VITE_SUPABASE_URL/API_URL, "
 36:     + "VITE_SUPABASE_ANON_KEY/ANON_KEY et SUPABASE_SERVICE_ROLE_KEY/SERVICE_ROLE_KEY.",
 37:   );
 38:   process.exit(1);
 39: }
 40: 
 41: const admin = createClient(SUPABASE_URL, SERVICE_ROLE_KEY, {
 42:   auth: { autoRefreshToken: false, persistSession: false },
 43: });
 44: const RUN_ID = Date.now();
 45: const results = [];
 46: 
 47: function record(name, pass, detail) {
 48:   results.push({ name, pass, detail });
 49:   console.log(`${pass ? "✅" : "❌"} ${name}${detail ? ` — ${detail}` : ""}`);
 50: }
 51: 
 52: async function insertOrThrow(table, row) {
 53:   const { data, error } = await admin.from(table).insert(row).select().single();
 54:   if (error) throw new Error(`seed ${table} : ${error.message}`);
 55:   return data;
 56: }
 57: 
 58: async function makeUser(email, password, clubId, role, name) {
 59:   const { data: authData, error: authError } = await admin.auth.admin.createUser({
 60:     email,
 61:     password,
 62:     email_confirm: true,
 63:   });
 64:   if (authError) throw new Error(`createUser ${email} : ${authError.message}`);
 65: 
 66:   const row = await insertOrThrow("users", {
 67:     club_id: clubId,
 68:     name,
 69:     email,
 70:     role,
 71:     auth_uid: authData.user.id,
 72:   });
 73:   const client = createClient(SUPABASE_URL, ANON_KEY, {
 74:     auth: { autoRefreshToken: false, persistSession: false },
 75:   });
 76:   const { error: signInError } = await client.auth.signInWithPassword({ email, password });
 77:   if (signInError) throw new Error(`signIn ${email} : ${signInError.message}`);
 78:   return { auth: authData.user, row, client };
 79: }
 80: 
 81: async function athleteCount(clubId) {
 82:   const { count, error } = await admin
 83:     .from("athletes")
 84:     .select("id", { count: "exact", head: true })
 85:     .eq("club_id", clubId);
 86:   if (error) throw error;
 87:   return count ?? 0;
 88: }
