109:     const coachA = await makeUser(
110:       `import-coach-a-${RUN_ID}@example.invalid`, password, clubA.id, "coach", "Coach A",
111:     );
112:     const athleteA = await makeUser(
113:       `import-athlete-a-${RUN_ID}@example.invalid`, password, clubA.id, "athlete", "Athlete A",
