351:       });
352:       const { data: stillClaimed } = await admin.from("users").select("auth_uid").eq("id", importedUser.id).single();
353:       record(
354:         "un compte importé déjà lié ne peut pas être réclamé une seconde fois",
355:         Boolean(error) && stillClaimed?.auth_uid === claimedAuthUid,
356:         error ? "refusé, OK" : "COMPTE ÉCRASÉ !",
357:       );
