362:     const clubBEmail = `import-club-b-${RUN_ID}@example.invalid`;
363:     const { data: resultB, error: errorB } = await headB.client.rpc("import_club_athletes", {
364:       p_rows: [{ name: clubBName, email: clubBEmail, secondaryDisciplines: [], clubId: clubA.id }],
