  2: // ============================================================
  3: // AthleteOS — test_performance_normalization.mjs
  4: //
  5: // Vérifie en conditions réelles (tâche 12) les "Vérifications
  6: // obligatoires" et la Definition of Done :
  7: //   1. Les nouvelles performances/résultats ont une valeur canonique
  8: //      valide (normalized_value / result_value), une unité et un
  9: //      discipline_id, écrits par les RPC de compétition (tâche 14) et
 10: //      par l'ajout manuel d'une performance (écriture directe côté
 11: //      athlète).
 12: //   2. Les anciennes données (déjà en base avant cette tâche) restent
 13: //      lisibles telles quelles (texte brut intact).
 14: //   3. Une ligne non interprétable est identifiable (quality_flags),
 15: //      pas silencieusement fausse.
 16: //   4. Un tri SQL sur la valeur canonique produit le bon ordre — sur
 17: //      une épreuve chronométrée ET une épreuve de distance — là où un
 18: //      tri sur le texte brut donnerait un ordre incorrect.
 19: //   5. Contrainte d'unicité (source, source_external_id) : un même
 20: //      point importé deux fois par le même fournisseur est refusé.
 21: //
 22: // Ne peut pas re-tester le backfill lui-même (ponctuel, déjà exécuté
 23: // au déploiement de la migration) — vérifie à la place que les lignes
 24: // réelles pré-existantes sont toujours lisibles ET ont bien été
 25: // backfillées (lecture seule, aucune donnée modifiée).
 26: //
 27: // Usage :
 28: //   SUPABASE_SERVICE_ROLE_KEY=... node test_performance_normalization.mjs
 29: // ============================================================
 30: 
 31: import { createClient } from "@supabase/supabase-js";
 32: import { readFileSync } from "node:fs";
 33: import { fileURLToPath } from "node:url";
 34: import path from "node:path";
 35: import crypto from "node:crypto";
 36: 
 37: function loadDotEnv(filePath) {
 38:   let text;
 39:   try { text = readFileSync(filePath, "utf8"); } catch { return; }
 40:   for (const rawLine of text.split("\n")) {
 41:     const line = rawLine.replace(/\r$/, "");
 42:     const m = line.match(/^([A-Z0-9_]+)=(.*)$/);
 43:     if (m && process.env[m[1]] === undefined) process.env[m[1]] = m[2].trim();
 44:   }
 45: }
 46: loadDotEnv(path.join(path.dirname(fileURLToPath(import.meta.url)), ".env"));
 47: 
 48: const SUPABASE_URL     = process.env.VITE_SUPABASE_URL;
 49: const ANON_KEY          = process.env.VITE_SUPABASE_ANON_KEY;
 50: const SERVICE_ROLE_KEY  = process.env.SUPABASE_SERVICE_ROLE_KEY;
 51: 
 52: if (!SUPABASE_URL || !ANON_KEY || !SERVICE_ROLE_KEY) {
 53:   console.error(
 54:     "Variables manquantes. Requis : VITE_SUPABASE_URL, VITE_SUPABASE_ANON_KEY " +
 55:     "(dans .env) et SUPABASE_SERVICE_ROLE_KEY (variable d'environnement, jamais committée)."
 56:   );
 57:   process.exit(1);
 58: }
 59: 
 60: const admin = createClient(SUPABASE_URL, SERVICE_ROLE_KEY, { auth: { autoRefreshToken: false, persistSession: false } });
 61: 
 62: const RUN_ID = Date.now();
 63: const results = [];
 64: function record(name, pass, detail) {
 65:   results.push({ name, pass, detail });
 66:   console.log(`${pass ? "✅" : "❌"} ${name}${detail ? " — " + detail : ""}`);
 67: }
