 86: async function main() {
 87:   let club, athleteRowA;
 88:   const auths = [];
 89:   const perfIds = [];
 90:   const compIds = [];
 91:   const password = `Norm-Test-${RUN_ID}-Aa!`;
 92: 
 93:   try {
 94:     club = await insertOrThrow("clubs", { name: `Norm Test Club ${RUN_ID}` });
 95:     const coach = await makeUser(`norm-test-coach-${RUN_ID}@example.invalid`, password, club.id, "coach", "Coach N"); auths.push(coach);
 96:     const athleteUser = await makeUser(`norm-test-athlete-${RUN_ID}@example.invalid`, password, club.id, "athlete", "Athlete N"); auths.push(athleteUser);
 97:     athleteRowA = athleteUser.athlete;
 98: 
 99:     // ── 0. Lecture seule : les vraies lignes pré-existantes (backfill déjà
100:     //    exécuté au déploiement) restent lisibles avec leur texte brut
101:     //    intact ET leur valeur canonique renseignée. ─────────────────────
102:     {
103:       const { data, error } = await admin.from("records").select("discipline, pr, pr_value, unit, discipline_id").limit(5);
104:       const ok = !error && (data ?? []).length > 0 && data.every(r => r.pr != null);
105:       record("anciennes lignes records lisibles (texte brut intact)", ok, error?.message ?? `${data?.length ?? 0} ligne(s), ex: ${JSON.stringify(data?.[0])}`);
106:     }
107: 
108:     // ── 1. RPC add_competition_result : résultat coach avec valeur canonique ──
109:     {
110:       const { data: comp, error: ce } = await coach.client.rpc("create_competition_with_athletes", {
111:         p_name: `Meeting Norm ${RUN_ID}`, p_date: new Date().toISOString().slice(0, 10),
112:         p_location: null, p_type: "Régionale",
113:         p_athlete_entries: [{ athleteId: athleteRowA.id, plannedEvent: "100m" }],
114:         p_idempotency_key: crypto.randomUUID(),
115:       });
116:       if (ce) throw ce;
117:       const compId = comp.competitionId;
118:       compIds.push(compId);
119: 
120:       const { data, error } = await coach.client.rpc("add_competition_result", {
121:         p_competition_id: compId, p_athlete_id: athleteRowA.id, p_event: "100m",
122:         p_result: "11.20s", p_result_value: 11.20, p_higher_is_better: false,
123:         p_idempotency_key: crypto.randomUUID(), p_unit: "s",
124:       });
125:       record("add_competition_result réussit", !error, error?.message);
126:       if (data?.resultId) {
127:         const { data: row } = await admin.from("competition_results").select("result_value, unit, discipline_id, quality_flags, source").eq("id", data.resultId).single();
128:         record("competition_results a une valeur canonique + unité + discipline_id", row?.result_value === 11.2 && row?.unit === "s" && row?.discipline_id === "100m", JSON.stringify(row));
129:         record("competition_results.quality_flags vide (résultat valide)", Array.isArray(row?.quality_flags) && row.quality_flags.length === 0, JSON.stringify(row?.quality_flags));
130:         record("competition_results.source par défaut = 'club'", row?.source === "club", row?.source);
131:       } else {
132:         record("competition_results a une valeur canonique + unité + discipline_id", false, "pas de resultId retourné");
133:       }
134: 
135:       const { data: rec } = await admin.from("records").select("unit, discipline_id, pr_value").eq("athlete_id", athleteRowA.id).eq("discipline", "100m").maybeSingle();
136:       record("records mis à jour avec unit + discipline_id par le RPC", rec?.unit === "s" && rec?.discipline_id === "100m", JSON.stringify(rec));
137:     }
138: 
139:     // ── 2. RPC create_solo_competition_result : discipline longue (minutes:secondes) ──
140:     {
141:       const { data, error } = await athleteUser.client.rpc("create_solo_competition_result", {
142:         p_name: `Solo Norm ${RUN_ID}`, p_date: new Date().toISOString().slice(0, 10),
143:         p_location: null, p_type: "Régionale", p_event: "1500m", p_result: "4:32",
144:         p_result_value: 272, p_higher_is_better: false,
145:         p_idempotency_key: crypto.randomUUID(), p_unit: "s",
146:       });
147:       record("create_solo_competition_result (1500m, format minutes) réussit", !error, error?.message);
148:       if (data?.competitionId) compIds.push(data.competitionId);
149:       if (data?.performanceId) {
150:         perfIds.push(data.performanceId);
151:         const { data: perf } = await admin.from("athlete_performances").select("normalized_value, unit, discipline_id, quality_flags").eq("id", data.performanceId).single();
152:         record("athlete_performances : 4:32 normalisé en 272 secondes", perf?.normalized_value === 272 && perf?.unit === "s", JSON.stringify(perf));
153:       } else {
154:         record("athlete_performances : 4:32 normalisé en 272 secondes", false, "pas de performanceId retourné");
155:       }
156:     }
157: 
158:     // ── 3. Écriture directe (ajout manuel d'une performance, hors RPC) ──────
159:     {
160:       const { data, error } = await athleteUser.client.from("athlete_performances").insert({
161:         athlete_id: athleteRowA.id, club_id: club.id, discipline: "longueur", discipline_type: "longueur",
162:         value: "6.45m", performance_date: new Date().toISOString().slice(0, 10),
163:         normalized_value: 6.45, unit: "m", discipline_id: "Longueur", quality_flags: [],
164:       }).select().single();
165:       record("ajout manuel direct (athlete_performances) réussit", !error, error?.message);
166:       if (data) {
167:         perfIds.push(data.id);
168:         record("discipline_id résolu même écrit hors RPC (Longueur, pas 'longueur')", data.discipline_id === "Longueur" && data.normalized_value === 6.45, JSON.stringify({ discipline_id: data.discipline_id, normalized_value: data.normalized_value }));
169:       }
170:     }
171: 
172:     // ── 4. Ligne ambiguë : identifiable, pas silencieusement fausse ────────
173:     {
174:       const { data, error } = await admin.from("athlete_performances").insert({
175:         athlete_id: athleteRowA.id, club_id: club.id, discipline: "100m", discipline_type: "100m",
176:         value: "DNF", performance_date: new Date().toISOString().slice(0, 10),
177:         normalized_value: null, unit: "s", discipline_id: "100m", quality_flags: ["unparsable"],
178:       }).select().single();
179:       record("ligne non interprétable (DNF) acceptée en base", !error, error?.message);
180:       if (data) {
181:         perfIds.push(data.id);
182:         const { data: flagged } = await admin.from("athlete_performances")
183:           .select("id, value").eq("athlete_id", athleteRowA.id).contains("quality_flags", ["unparsable"]);
184:         record("ligne ambiguë retrouvable via quality_flags (pas perdue silencieusement)", (flagged ?? []).some(r => r.id === data.id), `${flagged?.length ?? 0} ligne(s) trouvée(s)`);
185:       }
186:     }
187: 
188:     // ── 5. Tri SQL sur la valeur canonique — chrono ET distance ────────────
189:     {
190:       // 3 performances 100m : 11.20, 9.50 (record perso), 11.44 — un tri
191:       // texte donnerait "11.20" < "11.44" < "9.50" (ordre alphabétique,
192:       // FAUX) ; le tri numérique doit donner 9.50, 11.20, 11.44.
193:       const vals = ["11.20", "9.50", "11.44"];
194:       for (const v of vals) {
195:         const { data } = await admin.from("athlete_performances").insert({
196:           athlete_id: athleteRowA.id, club_id: club.id, discipline: "sort-test-100m", discipline_type: "sort-test-100m",
197:           value: v, performance_date: new Date().toISOString().slice(0, 10),
198:           normalized_value: parseFloat(v), unit: "s", discipline_id: "sort-test-100m", quality_flags: [],
199:         }).select().single();
200:         if (data) perfIds.push(data.id);
201:       }
202:       const { data: sorted, error } = await admin.from("athlete_performances")
203:         .select("value, normalized_value").eq("discipline_id", "sort-test-100m").order("normalized_value", { ascending: true });
204:       const order = (sorted ?? []).map(r => r.value);
205:       record("tri SQL chrono par normalized_value donne le bon ordre", !error && JSON.stringify(order) === JSON.stringify(["9.50", "11.20", "11.44"]), JSON.stringify(order));
206: 
207:       // Distance : 6.10, 7.60, 6.95 — même vérification, unité 'm'.
208:       const distVals = ["6.10", "7.60", "6.95"];
209:       for (const v of distVals) {
210:         const { data } = await admin.from("athlete_performances").insert({
211:           athlete_id: athleteRowA.id, club_id: club.id, discipline: "sort-test-longueur", discipline_type: "sort-test-longueur",
212:           value: v, performance_date: new Date().toISOString().slice(0, 10),
213:           normalized_value: parseFloat(v), unit: "m", discipline_id: "sort-test-longueur", quality_flags: [],
214:         }).select().single();
215:         if (data) perfIds.push(data.id);
216:       }
217:       const { data: sortedDist, error: ed } = await admin.from("athlete_performances")
218:         .select("value").eq("discipline_id", "sort-test-longueur").order("normalized_value", { ascending: true });
219:       const orderDist = (sortedDist ?? []).map(r => r.value);
220:       record("tri SQL distance par normalized_value donne le bon ordre", !ed && JSON.stringify(orderDist) === JSON.stringify(["6.10", "6.95", "7.60"]), JSON.stringify(orderDist));
221:     }
222: 
223:     // ── 6. Unicité (source, source_external_id) — anti double-import ───────
224:     {
225:       const externalId = `garmin-activity-${RUN_ID}`;
226:       const { data: first, error: e1 } = await admin.from("athlete_performances").insert({
227:         athlete_id: athleteRowA.id, club_id: club.id, discipline: "100m", discipline_type: "100m",
228:         value: "11.00", performance_date: new Date().toISOString().slice(0, 10),
229:         normalized_value: 11.0, unit: "s", discipline_id: "100m", quality_flags: [],
230:         source: "garmin", source_external_id: externalId,
231:       }).select().single();
232:       record("1er import externe accepté", !e1, e1?.message);
233:       if (first) perfIds.push(first.id);
234: 
235:       const { data: second, error: e2 } = await admin.from("athlete_performances").insert({
236:         athlete_id: athleteRowA.id, club_id: club.id, discipline: "100m", discipline_type: "100m",
237:         value: "11.00", performance_date: new Date().toISOString().slice(0, 10),
238:         normalized_value: 11.0, unit: "s", discipline_id: "100m", quality_flags: [],
239:         source: "garmin", source_external_id: externalId,
240:       }).select().single();
241:       record("ré-import du même id externe par le même fournisseur refusé", !!e2, e2 ? "refusé, OK" : "AUTORISÉ !");
242:       if (second) perfIds.push(second.id);
243:     }
244: 
245:   } finally {
246:     console.log("\nNettoyage...");
247:     if (perfIds.length) await admin.from("athlete_performances").delete().in("id", perfIds);
248:     if (compIds.length) {
