250:       await admin.from("competition_athletes").delete().in("competition_id", compIds);
251:       await admin.from("competitions").delete().in("id", compIds);
252:     }
253:     if (athleteRowA) await admin.from("records").delete().eq("athlete_id", athleteRowA.id);
254:     for (const u of auths) {
255:       if (!u) continue;
256:       await u.client.auth.signOut().catch(() => {});
257:       await admin.from("athletes").delete().eq("user_id", u.user.id);
258:       await admin.from("users").delete().eq("id", u.user.id);
259:       await admin.auth.admin.deleteUser(u.auth.id).catch(() => {});
260:     }
261:     if (club) await admin.from("clubs").delete().eq("id", club.id);
262:   }
