201: export default InjuryReportModal; 1: import { memo, useEffect, useState } from "react";
 2: 
 3: // Anneau circulaire partagé pour les 5 jauges de "Charge d'entraînement" —
 4: // même animation que l'ancien anneau "Comment tu te sens", mais le centre
 5: // affiche un mot de statut (Faible/Modéré/Bon/Élevé/Très élevé) au lieu d'un
 6: // chiffre brut : le chiffre reste disponible dans le détail au tap.
 7: // Rendu en carte compacte (comme les autres tuiles de l'app) plutôt qu'en
 8: // anneau flottant nu, pour rester net dans une bande de 5 jauges.
 9: const TrainingGauge = memo(({ value, color = "var(--c-text-3)", statusWord, label, size = 64, onClick }) => {
10:   const hasValue = value != null && Number.isFinite(Number(value));
11:   const [animated, setAnimated] = useState(0);
12:   useEffect(() => {
13:     const timeout = setTimeout(() => setAnimated(hasValue ? Number(value) : 0), 150);
14:     return () => clearTimeout(timeout);
15:   }, [value, hasValue]);
16: 
17:   const stroke = 6;
18:   const r = (size - stroke) / 2;
19:   const circumference = 2 * Math.PI * r;
20:   const dash = (Math.max(0, Math.min(100, animated)) / 100) * circumference;
21: 
22:   return (
23:     <button type="button" onClick={onClick} className="tap-feedback"
24:       style={{
25:         display: "flex", flexDirection: "column", alignItems: "center", gap: 6,
26:         background: "var(--c-surface-2)", border: "1px solid var(--c-border)", borderRadius: 14,
27:         padding: "12px 6px 10px", cursor: "pointer", width: "100%", minWidth: 84, flexShrink: 0,
28:         scrollSnapAlign: "start",
29:       }}>
30:       <div style={{ position: "relative", width: size, height: size, flexShrink: 0 }}>
31:         <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`} style={{ filter: hasValue ? `drop-shadow(0 0 8px ${color}30)` : "none" }}>
32:           <circle cx={size / 2} cy={size / 2} r={r} fill="none" stroke="var(--c-border-strong)" strokeWidth={stroke} />
33:           <circle cx={size / 2} cy={size / 2} r={r} fill="none" stroke={color} strokeWidth={stroke}
34:             strokeDasharray={`${dash} ${circumference}`} strokeLinecap="round"
35:             transform={`rotate(-90 ${size / 2} ${size / 2})`}
36:             style={{ transition: "stroke-dasharray 1.1s cubic-bezier(0.16,1,0.3,1)", opacity: hasValue ? 1 : 0.4 }} />
37:         </svg>
38:         <div style={{ position: "absolute", inset: 0, display: "flex", alignItems: "center", justifyContent: "center", padding: "0 10%" }}>
39:           <span style={{ fontSize: 9.5, fontWeight: 700, color: hasValue ? color : "var(--c-text-3)", lineHeight: 1.1, textAlign: "center", letterSpacing: "-0.01em" }}>
40:             {hasValue ? statusWord : "—"}
41:           </span>
42:         </div>
43:       </div>
44:       <span style={{ fontSize: 10, fontWeight: 600, letterSpacing: "0.04em", textTransform: "uppercase", color: "var(--c-text-3)", textAlign: "center", lineHeight: 1.25 }}>
45:         {label}
46:       </span>
47:     </button>
48:   );
49: });
