195:           .neq("id", athlete.id),
196:         supabase.from("users")
197:           .select("id, name, role")
198:           .eq("club_id", clubId)
199:           .neq("role", "athlete"),
200:       ]);
201:       if (athletesResult.error) throw athletesResult.error;
202:       if (usersResult.error) throw usersResult.error;
203: 
204:       const coachContacts = (usersResult.data ?? []).map(user => ({
205:         id:`user-${user.id}`, userId:user.id, name:user.name ?? "Coach", type:"coach",
206:         subtitle:user.role === "head_coach" ? "Head coach" : "Coach", color:"#5B8DEF",
207:       }));
208:       const athleteContacts = (athletesResult.data ?? [])
209:         .filter(item => item.user_id != null)
210:         .map((item, index) => ({
211:           id:`athlete-${item.id}`, athleteId:item.id, userId:item.user_id,
212:           name:item.name ?? "Athlète", type:"athlete", subtitle:item.main_discipline ?? "Athlète",
213:           color:CONTACT_COLORS[index % CONTACT_COLORS.length],
214:         }));
215:       const nextContacts = [...coachContacts, ...athleteContacts];
216:       const contactUserIds = nextContacts.map(contact => contact.userId).filter(Boolean);
217: 
218:       let messageRows = [];
219:       if (contactUserIds.length) {
220:         const messagesResult = await supabase.from("messages")
221:           .select("*")
222:           .or(`and(sender_id.eq.${athleteUserId},receiver_id.in.(${contactUserIds.join(",")})),and(receiver_id.eq.${athleteUserId},sender_id.in.(${contactUserIds.join(",")}))`)
223:           .order("created_at", { ascending:true });
224:         if (messagesResult.error) throw messagesResult.error;
225:         messageRows = messagesResult.data ?? [];
226:       }
227: 
228:       setContacts(nextContacts);
229:       setAllMessages(messageRows.map(mapMessageRow));
230:       setActiveId(current => current && nextContacts.some(contact => contact.id === current) ? current : null);
231: 
232:       if (!initializedRef.current) {
233:         const defaultCoach = nextContacts.find(contact => contact.userId === coachUserId);
234:         const desktop = typeof window !== "undefined" && (window.matchMedia?.("(min-width: 768px)")?.matches ?? window.innerWidth >= 768);
235:         if (defaultCoach && desktop) setActiveId(defaultCoach.id);
236:         initializedRef.current = true;
237:       }
238:     } catch (error) {
239:       console.error("AthleteMsgerie — chargement :", error);
240:       setLoadError("La messagerie n’a pas pu être chargée. Réessaie dans un instant.");
241:     } finally {
242:       setLoading(false);
243:     }
244:   }, [athlete.id, athleteUserId, clubId, coachUserId]);
245: 
246:   useEffect(() => { fetchAll(); }, [fetchAll]);
247: 
248:   useEffect(() => {
249:     if (!athleteUserId) return undefined;
250:     const applyRealtimeMessage = (row, isUpdate = false) => {
251:       if (row.receiver_id !== athleteUserId && row.sender_id !== athleteUserId) return;
252:       const message = mapMessageRow(row);
253:       if (isUpdate) {
254:         setAllMessages(previous => previous.map(item => item.id === message.id ? message : item));
255:         return;
256:       }
257: 
258:       const openContact = contactsRef.current.find(contact => contact.id === activeIdRef.current);
259:       const receivedInOpenThread = row.receiver_id === athleteUserId && openContact?.userId === row.sender_id;
260:       if (receivedInOpenThread) message.isRead = true;
261:       setAllMessages(previous => appendUniqueMessage(previous, message));
262: 
263:       if (receivedInOpenThread) {
264:         supabase.from("messages").update({ is_read:true }).eq("id", row.id).then(({ error }) => {
265:           if (!error) return;
266:           setAllMessages(previous => previous.map(item => item.id === row.id ? { ...item, isRead:false } : item));
267:           setActionError("Le message est arrivé, mais son statut de lecture n’a pas pu être synchronisé.");
268:         });
269:       }
270:     };
271: 
272:     const channel = supabase.channel(`athlete-messaging-${athleteUserId}`)
273:       .on("postgres_changes", { event:"INSERT", schema:"public", table:"messages" }, payload => applyRealtimeMessage(payload.new))
274:       .on("postgres_changes", { event:"UPDATE", schema:"public", table:"messages" }, payload => applyRealtimeMessage(payload.new, true))
275:       .subscribe();
276:     return () => supabase.removeChannel(channel);
277:   }, [athleteUserId]);
278: 
279:   const conversations = useMemo(
280:     () => buildAthleteConversations(allMessages, contacts, athleteUserId),
281:     [allMessages, contacts, athleteUserId]
282:   );
283:   const filteredConversations = useMemo(
284:     () => filterAthleteConversations(conversations, contacts, activeFilter, search),
285:     [conversations, contacts, activeFilter, search]
286:   );
287:   const activeConversation = useMemo(
288:     () => conversations.find(conversation => conversation.contactId === activeId) ?? null,
289:     [conversations, activeId]
290:   );
291:   const activeContact = useMemo(
292:     () => contacts.find(contact => contact.id === activeId) ?? null,
293:     [contacts, activeId]
294:   );
295:   const messageGroups = useMemo(
296:     () => groupMessagesByDay(activeConversation?.messages ?? []),
297:     [activeConversation?.messages]
298:   );
299:   const totalUnread = useMemo(() => conversations.reduce((total, conversation) => total + conversation.unread, 0), [conversations]);
300:   const filterCounts = useMemo(() => ({
301:     all:conversations.length,
302:     coaches:conversations.filter(conversation => contacts.find(contact => contact.id === conversation.contactId)?.type === "coach").length,
303:     athletes:conversations.filter(conversation => contacts.find(contact => contact.id === conversation.contactId)?.type === "athlete").length,
304:     unread:totalUnread,
305:   }), [conversations, contacts, totalUnread]);
306: 
307:   const selectContact = useCallback(async contactId => {
308:     setActiveId(contactId);
309:     setDraft("");
310:     setActionError(null);
311:     const contact = contacts.find(item => item.id === contactId);
312:     if (!contact?.userId) return;
313:     const unreadIds = allMessages
314:       .filter(message => message.senderId === contact.userId && message.receiverId === athleteUserId && !message.isRead)
315:       .map(message => message.id);
316:     if (!unreadIds.length) return;
317: 
318:     const unreadSet = new Set(unreadIds);
319:     setAllMessages(previous => previous.map(message => unreadSet.has(message.id) ? { ...message, isRead:true } : message));
320:     const { error } = await supabase.from("messages").update({ is_read:true }).in("id", unreadIds);
321:     if (error) {
322:       setAllMessages(previous => previous.map(message => unreadSet.has(message.id) ? { ...message, isRead:false } : message));
323:       setActionError("Impossible de synchroniser les messages lus. Vérifie ta connexion.");
324:     }
325:   }, [contacts, allMessages, athleteUserId]);
326: 
327:   const handleSend = useCallback(async rawText => {
328:     const text = rawText.trim().slice(0, MESSAGE_MAX_LENGTH);
329:     if (!text || !activeId || !athleteUserId || sendingRef.current) return false;
330:     const contact = contacts.find(item => item.id === activeId);
331:     if (!contact?.userId) return false;
332: 
333:     sendingRef.current = true;
334:     setSending(true);
335:     setActionError(null);
336:     try {
337:       const { data, error } = await supabase.from("messages")
338:         .insert({ sender_id:athleteUserId, receiver_id:contact.userId, content:text, is_read:false })
339:         .select()
340:         .single();
341:       if (error) throw error;
342: 
343:       setAllMessages(previous => appendUniqueMessage(previous, mapMessageRow(data)));
344: 
345:       // Notifications existantes : conservées volontairement et déclenchées
346:       // uniquement après l'enregistrement réussi du message.
347:       if (contact.type === "coach") {
348:         notifyCoachMessage(contact.userId, athlete.name, text).catch(console.warn);
349:       } else if (contact.type === "athlete" && contact.athleteId) {
350:         notifyAthleteMessage(clubId, contact.athleteId, athlete.name, text).catch(console.warn);
351:       }
352:       return true;
353:     } catch (error) {
354:       console.error("AthleteMsgerie — envoi :", error);
355:       setActionError("Ton message n’a pas été envoyé. Le brouillon est conservé pour réessayer.");
356:       return false;
357:     } finally {
358:       sendingRef.current = false;
359:       setSending(false);
360:     }
361:   }, [activeId, athlete.name, athleteUserId, clubId, contacts]);
362: 
363:   const submitDraft = useCallback(async () => {
364:     const sent = await handleSend(draft);
365:     if (!sent) return;
366:     setDraft("");
367:     requestAnimationFrame(() => textareaRef.current?.focus());
368:   }, [draft, handleSend]);
369: 
370:   const handleKeyDown = useCallback(event => {
371:     if (event.key === "Enter" && !event.shiftKey && !event.nativeEvent.isComposing) {
372:       event.preventDefault();
373:       submitDraft();
374:     }
375:   }, [submitDraft]);
376: 
377:   const chooseSuggestion = useCallback(suggestion => {
378:     setDraft(suggestion);
379:     requestAnimationFrame(() => textareaRef.current?.focus());
380:   }, []);
381: 
382:   useEffect(() => {
383:     const container = threadScrollRef.current;
384:     if (!container) return;
385:     requestAnimationFrame(() => container.scrollTo({ top:container.scrollHeight, behavior:"smooth" }));
386:   }, [activeId, activeConversation?.messages.length]);
387: 
388:   useEffect(() => {
389:     const textarea = textareaRef.current;
390:     if (!textarea) return;
391:     textarea.style.height = "auto";
392:     textarea.style.height = `${Math.min(textarea.scrollHeight, 120)}px`;
393:   }, [draft]);
394: 
395:   if (loading) return <LoadingState message="Chargement de la messagerie…"/>;
396:   if (loadError) return <ErrorState message={loadError} onRetry={fetchAll}/>;
397: 
398:   return (
399:     <div className="h-[calc(100dvh-56px-80px)] md:h-[calc(100dvh-56px)] md:p-4" style={{ boxSizing:"border-box", overflow:"hidden", background:"var(--c-bg)" }}>
400:       <section className="card" style={{ width:"100%", height:"100%", display:"flex", overflow:"hidden", background:"var(--c-surface)" }}>
401:         <aside className={["flex-col flex-shrink-0", activeId ? "hidden md:flex md:w-[340px]" : "flex w-full md:w-[340px]"].join(" ")}
402:           style={{ borderRight:"1px solid var(--c-border)", background:"linear-gradient(180deg, rgba(91,141,239,0.05), var(--c-surface) 22%)" }}>
403:           <div style={{ padding:"18px 16px 14px", borderBottom:"1px solid var(--c-border)", flexShrink:0 }}>
404:             <div style={{ display:"flex", alignItems:"flex-start", justifyContent:"space-between", gap:12 }}>
405:               <div>
406:                 <div style={{ display:"flex", alignItems:"center", gap:6, marginBottom:6 }}>
407:                   <Sparkles size={13} color="#8DB1F6"/>
408:                   <span style={{ fontSize:12, fontWeight:800, letterSpacing:"0.06em", textTransform:"uppercase", color:"var(--tone-info)" }}>Espace équipe</span>
409:                 </div>
410:                 <h1 style={{ fontSize:24, lineHeight:1.15, fontWeight:800, letterSpacing:"-0.025em", color:"var(--c-text-1)" }}>Messages</h1>
411:                 <p style={{ marginTop:5, fontSize:13, color:"var(--c-text-2)" }}>{contacts.length} contact{contacts.length > 1 ? "s" : ""} dans ton club</p>
412:               </div>
413:               {totalUnread > 0 && (
414:                 <span style={{ minHeight:32, padding:"0 10px", borderRadius:99, display:"inline-flex", alignItems:"center", background:"rgba(224,82,82,0.12)", border:"1px solid rgba(224,82,82,0.20)", color:"var(--tone-danger)", fontSize:12, fontWeight:800 }}>
415:                   {totalUnread} non lu{totalUnread > 1 ? "s" : ""}
416:                 </span>
417:               )}
418:             </div>
419: 
420:             <div style={{ minHeight:48, marginTop:16, padding:"0 14px", borderRadius:14, display:"flex", alignItems:"center", gap:10, background:"var(--c-surface-2)", border:"1px solid var(--c-border)" }}>
421:               <Search size={17} color="var(--c-text-2)" aria-hidden="true"/>
422:               <label htmlFor="athlete-message-search" className="sr-only">Rechercher une conversation</label>
423:               <input id="athlete-message-search" type="search" placeholder="Nom ou contenu d’un message…" value={search} onChange={event => setSearch(event.target.value)}
424:                 style={{ flex:1, minWidth:0, background:"transparent", border:"none", outline:"none", color:"var(--c-text-1)", fontSize:14 }}/>
425:               {search && (
426:                 <button type="button" aria-label="Effacer la recherche" onClick={() => setSearch("")}
427:                   style={{ width:44, height:44, marginRight:-12, display:"flex", alignItems:"center", justifyContent:"center", border:"none", background:"transparent", color:"var(--c-text-2)", cursor:"pointer" }}>
428:                   <X size={16}/>
429:                 </button>
430:               )}
431:             </div>
432: 
433:             <nav aria-label="Filtrer les conversations" style={{ marginTop:12, display:"flex", gap:8, overflowX:"auto", scrollbarWidth:"none" }}>
434:               {MESSAGE_FILTERS.map(filter => {
435:                 const active = activeFilter === filter.id;
436:                 return (
437:                   <button key={filter.id} type="button" aria-pressed={active} onClick={() => setActiveFilter(filter.id)} className="tap-feedback"
438:                     style={{ minHeight:44, padding:"0 12px", borderRadius:12, flexShrink:0, border:`1px solid ${active ? "rgba(77,201,160,0.30)" : "var(--c-border)"}`, background:active ? "rgba(29,158,117,0.13)" : "transparent", color:active ? "#7BD8B4" : "var(--c-text-2)", fontSize:13, fontWeight:800, cursor:"pointer" }}>
439:                     {filter.label} · {filterCounts[filter.id]}
440:                   </button>
441:                 );
442:               })}
443:             </nav>
444:           </div>
445: 
446:           <div style={{ flex:1, padding:8, overflowY:"auto" }}>
447:             {filteredConversations.length ? filteredConversations.map(conversation => (
448:               <ConversationItem
449:                 key={conversation.contactId}
450:                 conversation={conversation}
451:                 contact={contacts.find(contact => contact.id === conversation.contactId)}
452:                 currentUserId={athleteUserId}
453:                 active={conversation.contactId === activeId}
454:                 onSelect={selectContact}
455:               />
456:             )) : (
457:               <div style={{ minHeight:260, padding:24, display:"flex", flexDirection:"column", alignItems:"center", justifyContent:"center", textAlign:"center" }}>
458:                 <div style={{ width:56, height:56, borderRadius:18, display:"flex", alignItems:"center", justifyContent:"center", background:"var(--c-surface-2)", border:"1px solid var(--c-border)" }}>
459:                   <Users size={23} color="var(--c-text-3)"/>
460:                 </div>
461:                 <p style={{ marginTop:14, fontSize:15, fontWeight:800, color:"var(--c-text-1)" }}>{search ? "Aucun résultat" : "Aucune conversation"}</p>
462:                 <p style={{ marginTop:5, maxWidth:240, fontSize:13, lineHeight:1.5, color:"var(--c-text-2)" }}>
463:                   {search ? "Essaie un autre nom ou un mot présent dans tes messages." : "Aucun contact ne correspond à ce filtre."}
464:                 </p>
465:                 {(search || activeFilter !== "all") && (
466:                   <button type="button" onClick={() => { setSearch(""); setActiveFilter("all"); }} className="btn-secondary" style={{ marginTop:16 }}>Réinitialiser</button>
467:                 )}
468:               </div>
469:             )}
470:           </div>
471:         </aside>
472: 
473:         <div className={["flex-col flex-1 min-w-0 overflow-hidden", activeId ? "flex" : "hidden md:flex"].join(" ")}>
474:           {activeConversation && activeContact ? (
475:             <>
476:               <header style={{ minHeight:72, padding:"10px 16px", display:"flex", alignItems:"center", gap:12, flexShrink:0, borderBottom:"1px solid var(--c-border)", background:"rgba(18,20,24,0.88)", backdropFilter:"blur(16px)" }}>
477:                 <button type="button" aria-label="Retour aux conversations" onClick={() => setActiveId(null)} className="md:hidden tap-feedback"
478:                   style={{ width:44, height:44, borderRadius:12, display:"flex", alignItems:"center", justifyContent:"center", flexShrink:0, border:"1px solid var(--c-border)", background:"var(--c-surface-2)", color:"var(--c-text-1)", cursor:"pointer" }}>
479:                   <ChevronLeft size={21}/>
480:                 </button>
481:                 <ContactAvatar contact={activeContact} size={44}/>
482:                 <div style={{ flex:1, minWidth:0 }}>
483:                   <div style={{ display:"flex", alignItems:"center", gap:8 }}>
484:                     <h2 style={{ fontSize:15, fontWeight:800, color:"var(--c-text-1)", overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>{activeContact.name}</h2>
485:                     {activeContact.type === "coach" && (
486:                       <span style={{ padding:"3px 8px", borderRadius:99, background:"rgba(91,141,239,0.13)", border:"1px solid rgba(91,141,239,0.20)", color:"var(--tone-info)", fontSize:12, fontWeight:800 }}>Coach</span>
487:                     )}
488:                   </div>
489:                   <p style={{ marginTop:3, fontSize:12, color:"var(--c-text-2)" }}>{activeContact.subtitle} · conversation privée</p>
490:                 </div>
491:                 <div className="hidden sm:flex" style={{ minHeight:36, padding:"0 10px", alignItems:"center", gap:6, borderRadius:99, background:"rgba(29,158,117,0.08)", color:"var(--tone-success)", fontSize:12, fontWeight:700 }}>
492:                   <span style={{ width:7, height:7, borderRadius:"50%", background:"#4DC9A0", boxShadow:"0 0 0 4px rgba(77,201,160,0.10)" }}/>
493:                   Temps réel
494:                 </div>
495:               </header>
496: 
497:               <div ref={threadScrollRef} style={{ flex:1, overflowY:"auto", padding:"16px clamp(14px, 3vw, 32px) 24px", background:"radial-gradient(circle at 50% 0%, rgba(91,141,239,0.05), transparent 36%), var(--c-bg)" }}>
498:                 {messageGroups.length === 0 ? <EmptyThread onSuggestion={chooseSuggestion}/> : messageGroups.map(group => (
499:                   <section key={group.key} aria-label={formatMessageDay(group.date)}>
500:                     <div style={{ margin:"20px 0 16px", display:"flex", alignItems:"center", gap:12 }}>
501:                       <span aria-hidden="true" style={{ height:1, flex:1, background:"var(--c-border)" }}/>
502:                       <span style={{ padding:"5px 10px", borderRadius:99, border:"1px solid var(--c-border)", background:"var(--c-surface-2)", color:"var(--c-text-2)", fontSize:12, fontWeight:700, textTransform:"capitalize" }}>{formatMessageDay(group.date)}</span>
503:                       <span aria-hidden="true" style={{ height:1, flex:1, background:"var(--c-border)" }}/>
504:                     </div>
505:                     <div style={{ display:"flex", flexDirection:"column", gap:6 }}>
506:                       {group.messages.map((message, index) => {
507:                         const own = message.senderId === athleteUserId;
508:                         const next = group.messages[index + 1];
509:                         const clustered = next && next.senderId === message.senderId && new Date(next.date) - new Date(message.date) <= 120000;
510:                         return (
511:                           <MessageBubble key={message.id} message={message} own={own} contact={activeContact} showAvatar={!own && !clustered} showMeta={!clustered}/>
512:                         );
513:                       })}
514:                     </div>
515:                   </section>
516:                 ))}
517:               </div>
518: 
519:               <footer style={{ flexShrink:0, background:"var(--c-surface)", borderTop:"1px solid var(--c-border)" }}>
520:                 {actionError && (
521:                   <div role="alert" style={{ minHeight:48, padding:"8px 12px 8px 16px", display:"flex", alignItems:"center", gap:10, background:"rgba(224,82,82,0.08)", borderBottom:"1px solid rgba(224,82,82,0.16)" }}>
522:                     <p style={{ flex:1, fontSize:13, lineHeight:1.4, color:"var(--tone-danger)" }}>{actionError}</p>
523:                     <button type="button" aria-label="Fermer le message d’erreur" onClick={() => setActionError(null)} style={{ width:44, height:44, display:"flex", alignItems:"center", justifyContent:"center", border:"none", background:"transparent", color:"var(--tone-danger)", cursor:"pointer" }}><X size={17}/></button>
524:                   </div>
525:                 )}
526:                 <div style={{ padding:"10px 12px max(10px, env(safe-area-inset-bottom))", display:"flex", alignItems:"flex-end", gap:10 }}>
527:                   <div style={{ flex:1, minWidth:0, padding:"10px 14px", borderRadius:18, background:"var(--c-surface-2)", border:"1px solid var(--c-border)" }}>
528:                     <textarea
529:                       ref={textareaRef}
530:                       rows={1}
531:                       maxLength={MESSAGE_MAX_LENGTH}
532:                       aria-label={`Message à ${activeContact.name}`}
533:                       placeholder={`Message à ${activeContact.name.split(" ")[0]}…`}
534:                       value={draft}
535:                       onChange={event => setDraft(event.target.value)}
536:                       onKeyDown={handleKeyDown}
537:                       style={{ width:"100%", minHeight:24, maxHeight:120, display:"block", resize:"none", overflowY:"auto", border:"none", outline:"none", background:"transparent", color:"var(--c-text-1)", fontSize:15, lineHeight:1.5 }}
538:                     />
539:                     {draft.length >= MESSAGE_MAX_LENGTH * 0.8 && (
540:                       <p style={{ marginTop:4, textAlign:"right", fontSize:12, color:draft.length === MESSAGE_MAX_LENGTH ? "#F19A9A" : "var(--c-text-3)" }}>{draft.length}/{MESSAGE_MAX_LENGTH}</p>
541:                     )}
542:                   </div>
543:                   <button type="button" aria-label="Envoyer le message" onClick={submitDraft} disabled={!draft.trim() || sending} className="tap-feedback"
544:                     style={{ width:48, height:48, borderRadius:"50%", flexShrink:0, display:"flex", alignItems:"center", justifyContent:"center", border:"1px solid rgba(77,201,160,0.22)", background:"linear-gradient(135deg, #1D9E75, #16826C)", color:"white", cursor:"pointer", opacity:!draft.trim() || sending ? 0.38 : 1, boxShadow:draft.trim() ? "0 6px 18px rgba(29,158,117,0.25)" : "none" }}>
545:                     {sending
546:                       ? <span aria-label="Envoi en cours" style={{ width:17, height:17, borderRadius:"50%", border:"2px solid rgba(255,255,255,0.35)", borderTopColor:"white", animation:"spin-smooth 0.65s linear infinite" }}/>
547:                       : <Send size={18} strokeWidth={2.5}/>
548:                     }
549:                   </button>
550:                 </div>
551:               </footer>
552:             </>
553:           ) : (
554:             <div style={{ flex:1, padding:24, display:"flex", flexDirection:"column", alignItems:"center", justifyContent:"center", textAlign:"center", background:"radial-gradient(circle at 50% 40%, rgba(29,158,117,0.07), transparent 34%), var(--c-bg)" }}>
555:               <div style={{ width:76, height:76, borderRadius:24, display:"flex", alignItems:"center", justifyContent:"center", background:"linear-gradient(145deg, rgba(29,158,117,0.16), rgba(91,141,239,0.10))", border:"1px solid rgba(77,201,160,0.18)" }}>
556:                 <MessageSquare size={32} color="#7BD8B4" strokeWidth={1.6}/>
557:               </div>
558:               <h2 style={{ marginTop:20, fontSize:20, fontWeight:800, letterSpacing:"-0.02em", color:"var(--c-text-1)" }}>Ta messagerie d’équipe</h2>
559:               <p style={{ marginTop:7, maxWidth:390, fontSize:14, lineHeight:1.55, color:"var(--c-text-2)" }}>Sélectionne un coach ou un athlète pour échanger dans un espace privé et synchronisé en temps réel.</p>
560:               <div style={{ marginTop:18, minHeight:40, padding:"0 12px", borderRadius:99, display:"flex", alignItems:"center", gap:7, background:"var(--c-surface)", border:"1px solid var(--c-border)", color:"var(--c-text-2)", fontSize:12, fontWeight:700 }}>
561:                 <ShieldCheck size={15} color="#7BD8B4"/> Réservé aux membres du club
562:               </div>
563:             </div>
564:           )}
565:         </div>
566:       </section>
567:     </div>
568:   );
569: }  1: // ============================================================
