 14: // ─── Confettis — célébration d'un nouveau record personnel ───────────────────
 15: const CONFETTI_COLORS = ["#1D9E75", "#EAB308", "#5B8DEF", "#EC4899", "#38BDF8", "#FB923C"];
 16: 
 17: export function ConfettiBurst({ onDone }) {
 18:   const particles = useMemo(() => Array.from({ length: 28 }, (_, i) => ({
 19:     id: i,
 20:     left: Math.random() * 100,
 21:     color: CONFETTI_COLORS[i % CONFETTI_COLORS.length],
 22:     delay: Math.random() * 0.3,
 23:     duration: 1.3 + Math.random() * 0.7,
 24:     width: 5 + Math.random() * 5,
 25:     rotate: Math.round(Math.random() * 360),
 26:     drift: Math.round((Math.random() - 0.5) * 100),
 27:   })), []);
 28: 
 29:   useEffect(() => {
 30:     const t = setTimeout(onDone, 2100);
 31:     return () => clearTimeout(t);
 32:   }, [onDone]);
 33: 
 34:   return (
 35:     <div style={{ position: "fixed", inset: 0, zIndex: 10000, pointerEvents: "none", overflow: "hidden" }}>
 36:       {particles.map(p => (
 37:         <span key={p.id} style={{
 38:           position: "absolute", top: -12, left: `${p.left}%`,
 39:           width: p.width, height: p.width * 0.4, background: p.color, borderRadius: 2,
 40:           animation: `confetti-fall ${p.duration}s cubic-bezier(0.4,0,0.6,1) ${p.delay}s both`,
 41:           "--confetti-drift": `${p.drift}px`,
 42:           "--confetti-rotate": `${p.rotate}deg`,
 43:         }} />
 44:       ))}
 45:     </div>
 46:   );
 47: }
