 49: // ─── Tooltip graphique (dark) ─────────────────────────────────────────────────
 50: export function PerfTooltip({ active, payload, label }) {
 51:   if (!active || !payload?.length) return null;
 52:   const d = payload[0].payload;
 53:   return (
 54:     <div style={{ background: "var(--c-surface-2)", border: "1px solid var(--c-border-strong)", borderRadius: 14, padding: "12px 14px", minWidth: 128, boxShadow: "var(--shadow-md)" }}>
 55:       <p style={{ fontSize: 12, fontWeight: 600, color: "var(--c-text-2)", marginBottom: 4 }}>{label}</p>
 56:       <p style={{ fontSize: 20, fontWeight: 700, color: "var(--c-accent)" }}>{d.raw}</p>
 57:       {d.ctx && <p style={{ fontSize: 12, color: "var(--c-text-2)", fontStyle: "italic", marginTop: 4 }}>{d.ctx}</p>}
 58:       {d.breakdown && Object.keys(d.breakdown).length > 0 && (
 59:         <div style={{ marginTop: 8, paddingTop: 8, borderTop: "1px solid var(--c-border)" }}>
 60:           {Object.entries(d.breakdown).map(([ev, val]) => (
 61:             <div key={ev} style={{ display: "flex", justifyContent: "space-between", gap: 12, fontSize: 12, color: "var(--c-text-2)", marginTop: 4 }}>
 62:               <span>{ev}</span>
 63:               <span style={{ fontWeight: 600, color: "var(--c-text-2)" }}>{val}</span>
 64:             </div>
 65:           ))}
 66:         </div>
 67:       )}
 68:     </div>
 69:   );
 70: }
