 72: // ─── Ring de progression générique ────────────────────────────────────────────
 73: export function ProgressRing({ pct, color, size = 64, label, stroke = 6 }) {
 74:   const r = (size - stroke) / 2;
 75:   const circ = 2 * Math.PI * r;
 76:   const clamped = pct === null ? 0 : Math.max(0, Math.min(100, pct));
 77:   return (
 78:     <div style={{ position: "relative", width: size, height: size, flexShrink: 0 }}>
 79:       <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`}>
 80:         <circle cx={size/2} cy={size/2} r={r} fill="none" stroke="var(--c-surface-3)" strokeWidth={stroke} />
 81:         {pct !== null && (
 82:           <circle cx={size/2} cy={size/2} r={r} fill="none" stroke={color} strokeWidth={stroke}
 83:             strokeDasharray={`${(clamped/100)*circ} ${circ}`} strokeLinecap="round"
 84:             transform={`rotate(-90 ${size/2} ${size/2})`}
 85:             style={{ transition: "stroke-dasharray 0.7s cubic-bezier(0.16,1,0.3,1)" }} />
 86:         )}
 87:       </svg>
 88:       <div style={{ position: "absolute", inset: 0, display: "flex", alignItems: "center", justifyContent: "center", flexDirection: "column" }}>
 89:         <span style={{ fontSize: 12, fontWeight: 700, color }}>{pct !== null ? `${pct}%` : "—"}</span>
 90:         {label && <span style={{ fontSize: 12, color: "var(--c-text-2)", marginTop: 1 }}>{label}</span>}
 91:       </div>
 92:     </div>
 93:   );
 94: }
