 96: // ─── Card discipline / record — façon "carte de crédit sportive" : le PR en
 97: // typo monumentale (ce qui compte le plus), SB juste en dessous en discret,
 98: // barre fine SB→PR colorée selon le statut, glow ambiant assorti.
 99: function TrendSparkline({ discipline, series, color }) {
100:   const points = (series ?? []).slice(-8);
101:   if (points.length < 2) {
102:     return (
103:       <div style={{ height: 58, display: "flex", alignItems: "center", justifyContent: "center", borderRadius: 12, background: "var(--c-surface-2)", border: "1px solid var(--c-border)" }}>
104:         <span style={{ fontSize: 12, color: "var(--c-text-3)" }}>Courbe après 2 mesures</span>
105:       </div>
106:     );
107:   }
108: 
109:   const higherIsBetter = getDiscHib(discipline);
110:   const scores = points.map(point => higherIsBetter ? point.value : -point.value);
111:   const min = Math.min(...scores);
112:   const max = Math.max(...scores);
113:   const range = max - min || 1;
114:   const coords = scores.map((score, index) => ({
115:     x: 8 + (index / (scores.length - 1)) * 164,
116:     y: 45 - ((score - min) / range) * 34,
117:   }));
118:   const line = coords.map(point => `${point.x},${point.y}`).join(" ");
119:   const area = `8,52 ${line} 172,52`;
120:   const gradientId = `record-spark-${discipline.replace(/[^a-z0-9]/gi, "-")}`;
121: 
122:   return (
123:     <svg viewBox="0 0 180 56" width="100%" height="58" preserveAspectRatio="none" aria-hidden="true">
124:       <defs>
125:         <linearGradient id={gradientId} x1="0" y1="0" x2="0" y2="1">
126:           <stop offset="0%" stopColor={color} stopOpacity="0.22" />
127:           <stop offset="100%" stopColor={color} stopOpacity="0" />
128:         </linearGradient>
129:       </defs>
130:       <path d={`M ${area} Z`} fill={`url(#${gradientId})`} />
131:       <polyline points={line} fill="none" stroke={color} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" vectorEffect="non-scaling-stroke" />
132:       {coords.map((point, index) => (
133:         <circle key={index} cx={point.x} cy={point.y} r={index === coords.length - 1 ? 3.5 : 2} fill={index === coords.length - 1 ? color : "var(--c-surface)"} stroke={color} strokeWidth="1.5" vectorEffect="non-scaling-stroke" />
134:       ))}
135:     </svg>
136:   );
137: }
