139: export function RecordCard({ disc, rec, onSeeEvolution, stats }) {
140:   const col = discColor(disc);
141:   // hib (higher-is-better) : indispensable pour les disciplines chronométrées
142:   // (sprint...) où SB ≥ PR est la norme — sbN/prN donnerait alors toujours
143:   // ~100%, peu importe l'écart réel. On raisonne dans le bon sens ici.
144:   const hib = getDiscHib(disc);
145:   const sbP = parsePerf(rec.sb);
146:   const prP = parsePerf(rec.pr);
147:   const pct = (sbP.value != null && prP.value != null && prP.value !== 0)
148:     ? Math.min(100, Math.max(0, Math.round(hib ? (sbP.value / prP.value) * 100 : (prP.value / sbP.value) * 100)))
149:     : null;
150:   const statusColor = recordStatusColor(pct) ?? col;
151: 
152:   return (
153:     <button type="button" onClick={onSeeEvolution} className="card card-hover tap-feedback" style={{ position: "relative", overflow: "hidden", width: "100%", padding: 20, textAlign: "left", cursor: "pointer" }}>
154:       <div style={{
155:         position: "absolute", right: -48, top: -58, width: 190, height: 190, borderRadius: "50%",
156:         background: `radial-gradient(circle, ${col}20 0%, transparent 68%)`, pointerEvents: "none",
157:       }} />
158: 
159:       <div style={{ position: "relative", display: "flex", alignItems: "center", justifyContent: "space-between", gap: 8, marginBottom: 20 }}>
160:         <div style={{ display: "flex", alignItems: "center", gap: 8, minWidth: 0 }}>
161:           <span style={{ width: 7, height: 7, borderRadius: "50%", background: col, boxShadow: `0 0 12px ${col}`, flexShrink: 0 }} />
162:           <p style={{ fontSize: 13, fontWeight: 700, letterSpacing: "0.04em", textTransform: "uppercase", color: "var(--c-text-2)" }} className="truncate">{disc}</p>
163:         </div>
164:         <span style={{ fontSize: 12, fontWeight: 700, color: statusColor, background: `${statusColor}14`, border: `1px solid ${statusColor}2E`, borderRadius: 99, padding: "4px 8px", flexShrink: 0 }}>
165:           {pct !== null ? `${pct}% du PR` : "Saison"}
166:         </span>
167:       </div>
168: 
169:       <div style={{ position: "relative", display: "grid", gridTemplateColumns: "minmax(0, 1fr) minmax(110px, 0.9fr)", alignItems: "end", gap: 16 }}>
170:         <div style={{ minWidth: 0 }}>
171:           <p style={{ fontSize: 12, fontWeight: 600, color: "var(--c-text-2)", marginBottom: 6 }}>Record personnel</p>
172:           <p style={{ fontSize: "clamp(28px, 7vw, 36px)", fontWeight: 700, color: "var(--c-text-1)", letterSpacing: "-0.04em", lineHeight: 1, fontVariantNumeric: "tabular-nums" }} className="truncate">
173:             {rec.pr ?? "—"}
174:           </p>
175:         </div>
176:         <TrendSparkline discipline={disc} series={stats?.series} color={col} />
177:       </div>
178: 
179:       <div style={{ position: "relative", display: "grid", gridTemplateColumns: "repeat(3, minmax(0, 1fr))", gap: 8, marginTop: 16, paddingTop: 16, borderTop: "1px solid var(--c-border)" }}>
180:         <div>
181:           <p style={{ fontSize: 12, color: "var(--c-text-3)" }}>Saison</p>
182:           <p style={{ fontSize: 13, fontWeight: 700, color: "var(--c-text-1)", marginTop: 2 }}>{rec.sb ?? "—"}</p>
183:         </div>
184:         <div>
185:           <p style={{ fontSize: 12, color: "var(--c-text-3)" }}>Mesures</p>
186:           <p style={{ fontSize: 13, fontWeight: 700, color: "var(--c-text-1)", marginTop: 2 }}>{stats?.count ?? 0}</p>
187:         </div>
188:         <div style={{ textAlign: "right" }}>
189:           <p style={{ fontSize: 12, color: "var(--c-text-3)" }}>Record établi</p>
190:           <p style={{ fontSize: 12, fontWeight: 600, color: "var(--c-text-2)", marginTop: 2 }}>
191:             {rec.prDate ? parseLocalDate(rec.prDate.slice(0, 10)).toLocaleDateString("fr-BE", { day: "numeric", month: "short", year: "numeric" }) : "—"}
192:           </p>
193:         </div>
194:       </div>
195:       <span style={{ position: "relative", display: "flex", alignItems: "center", justifyContent: "flex-end", gap: 4, marginTop: 14, fontSize: 12, fontWeight: 700, color: col }}>
196:         Voir l’évolution <ChevronRight size={14} aria-hidden="true" />
197:       </span>
198:     </button>
199:   );
200: }
