202: // ─── Barre de progression PR → objectif ──────────────────────────────────────
203: export function GoalProgressBar({ pr, target, discipline, color }) {
204:   if (!pr || !target) return null;
205:   // Tâche 11 : parsePerf (pas parseFloat, qui tronque "4:32" à 4) +
206:   // pctOfReference (pas un ratio PR/target écrit à la main, qui donnait
207:   // ~100%+ dès le départ pour un objectif chronométré plus rapide que le PR).
208:   const prN = parsePerf(pr).value;
209:   const tgN = parsePerf(target).value;
210:   const pct = pctOfReference(prN, tgN, discipline);
211:   if (pct === null) return null;
212:   return (
213:     <div style={{ marginTop: 12 }}>
214:       <div style={{ display: "flex", justifyContent: "space-between", gap: 8, fontSize: 12, fontWeight: 500, color: "var(--c-text-2)", marginBottom: 8 }}>
215:         <span>PR {pr}</span>
216:         <span style={{ color }}>{pct}%</span>
217:         <span>Objectif {target}</span>
218:       </div>
219:       <div className="progress-bar">
220:         <div className="progress-fill" style={{ width: `${pct}%`, background: color }} />
221:       </div>
222:     </div>
223:   );
