10: export function getTodayFocus({ wellnessCompleted, restConfirmed = false, todaySessions = [], athleteId }) {
11:   const sessions = Array.isArray(todaySessions) ? todaySessions : [];
12:   const pendingSessions = sessions.filter(
13:     session => !TERMINAL_SESSION_STATUSES.has(getAthleteSessionStatus(session, athleteId))
14:   );
15:   const completedSessions = sessions.length - pendingSessions.length;
16:   const restStep = sessions.length === 0;
17:   const completedSteps = completedSessions + (wellnessCompleted ? 1 : 0) + (restStep && restConfirmed ? 1 : 0);
18:   const totalSteps = sessions.length + 1 + (restStep ? 1 : 0);
19: 
20:   if (!wellnessCompleted) {
21:     return {
22:       kind: "wellness",
23:       completedSteps,
24:       totalSteps,
25:       completedSessions,
26:       pendingSessions,
27:       focusSession: pendingSessions[0] ?? null,
28:     };
29:   }
30: 
31:   if (pendingSessions.length > 0) {
32:     return {
33:       kind: "session",
34:       completedSteps,
35:       totalSteps,
36:       completedSessions,
37:       pendingSessions,
38:       focusSession: pendingSessions[0],
39:     };
40:   }
41: 
42:   if (restStep && !restConfirmed) {
43:     return {
44:       kind: "rest",
45:       completedSteps,
46:       totalSteps,
47:       completedSessions,
48:       pendingSessions,
49:       focusSession: null,
50:     };
51:   }
52: 
53:   return {
54:     kind: sessions.length > 0 ? "complete" : "free",
55:     completedSteps,
56:     totalSteps,
57:     completedSessions,
58:     pendingSessions,
59:     focusSession: null,
60:   };
