 79: export function getNotificationPresentation(notificationOrType) {
 80:   const type = typeof notificationOrType === "string" ? notificationOrType : notificationOrType?.type;
 81:   return { ...DEFAULT_PRESENTATION, ...(PRESENTATIONS[type] ?? {}) };
 82: }
 83: 
 84: export function filterNotificationItems(notifications, filter) {
 85:   if (filter === "all") return notifications;
 86:   if (filter === "unread") return notifications.filter(notification => !notification.is_read);
 87:   return notifications.filter(notification => getNotificationPresentation(notification).category === filter);
 88: }
 89: 
 90: export function mergeIncomingNotification(notifications, incoming, limit = 20) {
 91:   const withoutDuplicate = notifications.filter(notification => notification.id !== incoming.id);
 92:   return [incoming, ...withoutDuplicate]
 93:     .sort((a, b) => new Date(b.created_at) - new Date(a.created_at))
 94:     .slice(0, limit);
 95: }
 96: 
 97: export function formatNotificationTime(dateValue, now = new Date()) {
 98:   const date = new Date(dateValue);
 99:   const seconds = Math.max(0, Math.floor((now - date) / 1000));
100:   if (seconds < 60) return "À l’instant";
101:   if (seconds < 3600) return `Il y a ${Math.floor(seconds / 60)} min`;
102:   if (seconds < 86400) return `Il y a ${Math.floor(seconds / 3600)} h`;
103:   if (seconds < 172800) return "Hier";
104:   if (seconds < 604800) return `Il y a ${Math.floor(seconds / 86400)} j`;
105:   return date.toLocaleDateString("fr-BE", { day: "numeric", month: "short" });
106: } 1: import { describe, expect, it } from "vitest";
