 5: export default function AppStatusBanner() {
 6:   const [online, setOnline] = useState(() => navigator.onLine !== false);
 7:   const [updateAvailable, setUpdateAvailable] = useState(false);
 8: 
 9:   useEffect(() => {
10:     const handleOnline = () => setOnline(true);
11:     const handleOffline = () => setOnline(false);
12:     window.addEventListener("online", handleOnline);
13:     window.addEventListener("offline", handleOffline);
14: 
15:     const serviceWorker = navigator.serviceWorker;
16:     let removeRegistrationListener;
17:     let hadController = Boolean(serviceWorker?.controller);
18:     const handleControllerChange = () => {
19:       if (hadController) setUpdateAvailable(true);
20:       hadController = true;
21:     };
22: 
23:     serviceWorker?.addEventListener?.("controllerchange", handleControllerChange);
24:     serviceWorker?.ready?.then((registration) => {
25:       const handleUpdateFound = () => {
26:         const worker = registration.installing;
27:         if (!worker) return;
28:         const handleStateChange = () => {
29:           if (worker.state === "installed" && serviceWorker.controller) setUpdateAvailable(true);
30:         };
31:         worker.addEventListener("statechange", handleStateChange);
32:       };
33:       registration.addEventListener?.("updatefound", handleUpdateFound);
34:       removeRegistrationListener = () => registration.removeEventListener?.("updatefound", handleUpdateFound);
35:       registration.update?.().catch((error) => {
36:         captureError(error, { operation: "service_worker_update" });
37:       });
38:     }).catch((error) => {
39:       captureError(error, { operation: "service_worker_ready" });
40:     });
41: 
42:     return () => {
43:       window.removeEventListener("online", handleOnline);
44:       window.removeEventListener("offline", handleOffline);
45:       serviceWorker?.removeEventListener?.("controllerchange", handleControllerChange);
46:       removeRegistrationListener?.();
47:     };
48:   }, []);
49: 
50:   if (!online) {
51:     return (
52:       <aside className="app-status-banner offline" role="status">
53:         <span className="app-status-icon"><WifiOff size={18} aria-hidden="true" /></span>
54:         <span>
55:           <strong>Mode hors connexion</strong>
56:           <small>L’application reste accessible, mais certaines données peuvent être indisponibles.</small>
57:         </span>
58:       </aside>
59:     );
60:   }
61: 
62:   if (!updateAvailable) return null;
63: 
64:   return (
65:     <aside className="app-status-banner update" role="status">
66:       <span className="app-status-icon"><RefreshCw size={18} aria-hidden="true" /></span>
67:       <span>
68:         <strong>Nouvelle version prête</strong>
69:         <small>Actualise AthleteOS pour profiter des dernières améliorations.</small>
70:       </span>
71:       <button type="button" className="btn-primary" onClick={() => window.location.reload()}>
72:         Actualiser
73:       </button>
74:       <button type="button" className="app-status-dismiss" onClick={() => setUpdateAvailable(false)} aria-label="Masquer">
75:         <X size={17} aria-hidden="true" />
76:       </button>
77:     </aside>
78:   );
