338: }  1: import { getAthleteMetricsForWeek } from "../utils/chargeCalculations.js";
  2: import { getISOWeekYear, matchesISOWeek } from "../utils/helpers.js";
  3: 
  4: const finite = (value) => Number.isFinite(Number(value)) && value !== null && value !== "";
  5: 
  6: export function getWeeklyLoadRow(
  7:   weeklyCharge,
  8:   athleteId,
  9:   week,
 10:   isoYear = getISOWeekYear(new Date()),
 11: ) {
 12:   return (weeklyCharge ?? []).find((row) =>
 13:     row.athleteId === athleteId && matchesISOWeek(row, week, isoYear)
 14:   ) ?? null;
 15: }
 16: 
 17: export function getWeeklyLoadState(row) {
 18:   if (!row) {
 19:     return {
 20:       kind: "missing",
 21:       value: null,
 22:       label: "À renseigner",
 23:       detail: "Aucune journée n'est encore renseignée pour cette semaine.",
 24:       color: "#64748B",
 25:       badgeClass: "bg-[rgba(100,116,139,0.15)] text-[#A8B4C5]",
 26:     };
 27:   }
 28: 
 29:   if (!finite(row.rawLoad)) {
 30:     return {
 31:       kind: "incomplete",
 32:       value: null,
 33:       label: "À compléter",
 34:       detail: "Au moins une séance attend encore sa durée réelle ou son effort ressenti.",
 35:       color: "#EF9F27",
 36:       badgeClass: "bg-[rgba(239,159,39,0.14)] text-[#F3C77D]",
 37:     };
 38:   }
 39: 
 40:   const value = Number(row.rawLoad);
 41:   if (value === 0) {
 42:     return {
 43:       kind: "zero",
 44:       value,
 45:       label: "0 renseigné",
 46:       detail: "Le repos ou l'absence de charge a bien été confirmé : ce zéro est une donnée connue.",
 47:       color: "#14B8A6",
 48:       badgeClass: "bg-[rgba(20,184,166,0.14)] text-[#76D7CC]",
 49:     };
 50:   }
 51: 
 52:   return {
 53:     kind: "observed",
 54:     value,
 55:     label: "Renseignée",
 56:     detail: "La durée réellement effectuée et l'effort ressenti ont permis de calculer cette charge.",
 57:     color: "#378ADD",
 58:     badgeClass: "bg-[rgba(55,138,221,0.15)] text-[#A9CBFB]",
 59:   };
 60: }
