 62: export function describeLoadVariation(value) {
 63:   const variation = finite(value) ? Number(value) : null;
 64:   if (variation == null) {
 65:     return {
 66:       tone: "neutral",
 67:       label: "Habitude en construction",
 68:       summary: "Il manque encore des journées connues pour comparer les 7 derniers jours aux 3 semaines précédentes.",
 69:       valueLabel: "Comparaison indisponible",
 70:     };
 71:   }
 72: 
 73:   const rounded = Math.round(variation);
 74:   const valueLabel = `${rounded > 0 ? "+" : ""}${rounded} %`;
 75:   if (rounded >= 25) return {
 76:     tone: "up",
 77:     label: "Nettement plus que d'habitude",
 78:     summary: "La moyenne quotidienne des 7 derniers jours est nettement plus élevée que celle des 3 semaines précédentes.",
 79:     valueLabel,
 80:   };
 81:   if (rounded >= 10) return {
 82:     tone: "up",
 83:     label: "Un peu plus que d'habitude",
 84:     summary: "La moyenne quotidienne des 7 derniers jours est un peu plus élevée que celle des 3 semaines précédentes.",
 85:     valueLabel,
 86:   };
 87:   if (rounded <= -25) return {
 88:     tone: "down",
 89:     label: "Nettement moins que d'habitude",
 90:     summary: "La moyenne quotidienne des 7 derniers jours est nettement plus basse que celle des 3 semaines précédentes.",
