107: export function buildGroupLoadOverview(rows) {
108:   const current = (rows ?? []).filter((item) => finite(item.rawLoad));
109:   const paired = current.filter((item) => finite(item.previousRawLoad));
110:   const load7 = (rows ?? []).map((item) => item.metrics?.load7).filter(finite).map(Number);
111:   const positive = current.filter((item) => Number(item.rawLoad) > 0);
112:   const mean = (values) => values.length
113:     ? values.reduce((sum, value) => sum + Number(value), 0) / values.length
114:     : null;
115:   const pairedCurrentMean = mean(paired.map((item) => item.rawLoad));
116:   const pairedPreviousMean = mean(paired.map((item) => item.previousRawLoad));
117:   const trendPercent = pairedCurrentMean != null && pairedPreviousMean > 0
118:     ? Math.round(((pairedCurrentMean - pairedPreviousMean) / pairedPreviousMean) * 100)
119:     : null;
120: 
121:   return {
122:     avgLoad: current.length ? Math.round(mean(current.map((item) => item.rawLoad))) : null,
123:     avgLoad7: load7.length ? Math.round(mean(load7)) : null,
124:     topLoader: positive.sort((a, b) => Number(b.rawLoad) - Number(a.rawLoad))[0] ?? null,
125:     observedCount: current.length,
126:     pairedCount: paired.length,
127:     trendPercent,
128:   };
129: }
