131: export function buildGroupLoadStory(rows) {
132:   const known = (rows ?? []).filter((item) => finite(item.metrics?.variationPercent));
133:   const higher = known.filter((item) => Number(item.metrics.variationPercent) >= 10);
134:   const lower = known.filter((item) => Number(item.metrics.variationPercent) <= -10);
135:   const stable = known.filter((item) => Math.abs(Number(item.metrics.variationPercent)) < 10);
136: 
137:   if (!known.length) return {
138:     headline: "L'habitude du groupe est encore en construction",
139:     detail: "Confirme les jours de repos et complète les durées réelles et efforts ressentis. Dès que 28 jours sont connus, AthleteOS compare les 7 derniers jours aux 3 semaines précédentes.",
140:     counts: { higher: 0, stable: 0, lower: 0, known: 0 },
141:   };
142: 
143:   let headline = "La charge du groupe reste proche de ses habitudes";
144:   if (higher.length && lower.length) headline = "Les charges évoluent différemment dans le groupe";
145:   else if (higher.length) headline = `${higher.length} athlète${higher.length > 1 ? "s ont" : " a"} davantage chargé récemment`;
146:   else if (lower.length) headline = `${lower.length} athlète${lower.length > 1 ? "s ont" : " a"} moins chargé récemment`;
147: 
148:   return {
149:     headline,
150:     detail: `Comparaison lisible pour ${known.length} athlète${known.length > 1 ? "s" : ""} : ${higher.length} au-dessus de l'habitude, ${stable.length} proche${stable.length > 1 ? "s" : ""} de l'habitude et ${lower.length} en dessous. Ces mots décrivent un changement, pas un danger ni une prescription.`,
151:     counts: { higher: higher.length, stable: stable.length, lower: lower.length, known: known.length },
152:   };
153: }
