159: export function buildExperimentalAcwrSeries(athletes, weeklyCharge) {
160:   const allWeeks = [...new Map((weeklyCharge ?? []).map((row) => {
161:     const isoYear = Number.isInteger(Number(row.isoYear)) ? Number(row.isoYear) : null;
162:     const key = `${isoYear ?? "legacy"}-${row.week}`;
163:     const cutoffDate = (row.dailyLoads ?? []).map((day) => day.date).filter(Boolean).sort().at(-1) ?? null;
164:     return [key, { week: row.week, isoYear, cutoffDate }];
165:   })).values()].sort((a, b) => (a.isoYear ?? 0) - (b.isoYear ?? 0) || a.week - b.week);
166:   return allWeeks.map(({ week, isoYear, cutoffDate }) => {
167:     const point = { label: isoYear == null ? `S${week}` : `S${week} · ${isoYear}` };
168:     (athletes ?? []).forEach((athlete) => {
169:       point[athleteSeriesKey(athlete.id)] = getAthleteMetricsForWeek(
170:         athlete.id,
171:         weeklyCharge,
172:         week,
173:         [],
174:         [],
175:         cutoffDate,
176:       ).acwr;
177:     });
178:     return point;
179:   });
