 7: export function hasCompleteSessionFeedback(validation) {
 8:   return (validation?.status === "done" || validation?.status === "partial")
 9:     && validation?.rpe != null
10:     && validation?.durationSource === "reported"
11:     && Number(validation?.actualDurationMinutes) > 0;
12: }
