14: export function getSessionDaySummary(session) {
15:   const validations = session?.validations ?? [];
16:   const summary = {
17:     total: session?.athleteIds?.length ?? validations.length,
18:     feedbackComplete: 0, feedbackMissing: 0, difficult: 0,
19:     totalLoad: 0, averageRpe: null,
20:   };
21:   const rpes = [];
22:   validations.forEach((validation) => {
23:     if (hasCompleteSessionFeedback(validation)) {
24:       summary.feedbackComplete += 1;
25:       rpes.push(Number(validation.rpe));
26:       summary.totalLoad += Math.round(Number(validation.actualDurationMinutes) * Number(validation.rpe));
27:       if (Number(validation.rpe) >= 8 || (validation.feeling != null && Number(validation.feeling) <= 2)) summary.difficult += 1;
28:     } else if (validation.status !== "none") {
29:       summary.feedbackMissing += 1;
30:     }
31:   });
32:   summary.averageRpe = rpes.length ? Math.round((rpes.reduce((sum, value) => sum + value, 0) / rpes.length) * 10) / 10 : null;
33:   return summary;
34: }
