 21: async function resolveAssetUrl(client, path) {
 22:   if (!path) return null;
 23:   if (/^https?:\/\//i.test(path)) return path;
 24:   const { data, error } = await client.storage
 25:     .from("club-branding")
 26:     .createSignedUrl(path, SIGNED_URL_TTL_SECONDS);
 27:   if (error) return null;
 28:   return data?.signedUrl ?? null;
 29: }
