 31: export async function loadClubBranding(client, clubId) {
 32:   if (!clubId) return EMPTY_CLUB_BRAND;
 33: 
 34:   let { data, error } = await client
 35:     .from("clubs")
 36:     .select(TRACKED_CLUB_SELECT)
 37:     .eq("id", clubId)
 38:     .single();
 39: 
 40:   // Compatibilité pendant le déploiement : on garde d'abord toute l'identité
 41:   // visuelle si seuls les champs de suivi d'invitation ne sont pas encore là.
 42:   if (error) {
 43:     const brandingResult = await client
 44:       .from("clubs")
 45:       .select(FULL_CLUB_SELECT)
 46:       .eq("id", clubId)
 47:       .single();
 48:     data = brandingResult.data;
 49:     error = brandingResult.error;
 50:   }
 51:   if (error) {
 52:     const legacyResult = await client
 53:       .from("clubs")
 54:       .select(LEGACY_CLUB_SELECT)
 55:       .eq("id", clubId)
 56:       .single();
 57:     if (legacyResult.error) throw legacyResult.error;
 58:     data = legacyResult.data;
 59:   }
 60: 
 61:   const [logoUrl, coverUrl] = await Promise.all([
 62:     resolveAssetUrl(client, data?.logo_path),
 63:     resolveAssetUrl(client, data?.cover_path),
 64:   ]);
 65: 
 66:   return {
 67:     name: data?.name ?? "",
 68:     inviteCode: data?.invite_code ?? null,
 69:     logoPath: data?.logo_path ?? null,
 70:     coverPath: data?.cover_path ?? null,
 71:     logoUrl,
 72:     coverUrl,
 73:     accentColor: normalizeClubAccent(data?.accent_color),
 74:     inviteStatus: data?.invite_code ? {
 75:       active: !data?.invite_code_expires_at || new Date(data.invite_code_expires_at) > new Date(),
 76:       createdAt: data?.invite_code_created_at ?? null,
 77:       useCount: data?.invite_code_use_count ?? 0,
 78:       lastUsedAt: data?.invite_code_last_used_at ?? null,
 79:       expiresAt: data?.invite_code_expires_at ?? null,
 80:     } : null,
 81:   };
 82: }
