 84: export function useClubBranding(clubId) {
 85:   const [club, setClub] = useState(EMPTY_CLUB_BRAND);
 86:   const [loading, setLoading] = useState(Boolean(clubId));
 87:   const [error, setError] = useState(null);
 88: 
 89:   const refresh = useCallback(async () => {
 90:     if (!clubId) {
 91:       setClub(EMPTY_CLUB_BRAND);
 92:       setLoading(false);
 93:       return EMPTY_CLUB_BRAND;
 94:     }
 95:     setLoading(true);
 96:     setError(null);
 97:     try {
 98:       const nextClub = await loadClubBranding(supabase, clubId);
 99:       setClub(nextClub);
100:       return nextClub;
101:     } catch (loadError) {
102:       setError(loadError);
103:       return null;
104:     } finally {
105:       setLoading(false);
106:     }
107:   }, [clubId]);
108: 
109:   useEffect(() => { refresh(); }, [refresh]);
110: 
111:   return { club, loading, error, refresh };
