 3: const FOCUSABLE_SELECTOR = [
 4:   "a[href]",
 5:   "button:not([disabled])",
 6:   "input:not([disabled])",
 7:   "select:not([disabled])",
 8:   "textarea:not([disabled])",
 9:   "[tabindex]:not([tabindex='-1'])",
10: ].join(",");
11: 
12: function getFocusableElements(container) {
13:   if (!container) return [];
14:   return [...container.querySelectorAll(FOCUSABLE_SELECTOR)]
15:     .filter((element) => element.getAttribute("aria-hidden") !== "true");
16: }
