18: /**
19:  * Cycle de vie accessible commun aux dialogues AthleteOS : focus initial,
20:  * focus piégé, fermeture par Échap, verrouillage du fond et restauration.
21:  */
22: export function useModalAccessibility({
23:   dialogRef,
24:   initialFocusRef,
25:   onClose,
26:   enabled = true,
27:   closeDisabled = false,
28: }) {
29:   const onCloseRef = useRef(onClose);
30:   const closeDisabledRef = useRef(closeDisabled);
31:   onCloseRef.current = onClose;
32:   closeDisabledRef.current = closeDisabled;
33: 
34:   useEffect(() => {
35:     if (!enabled || typeof document === "undefined") return undefined;
36: 
37:     const previouslyFocused = document.activeElement;
38:     const previousOverflow = document.body.style.overflow;
39:     document.body.style.overflow = "hidden";
40: 
41:     const initialTarget = initialFocusRef?.current
42:       ?? getFocusableElements(dialogRef.current)[0]
43:       ?? dialogRef.current;
44:     initialTarget?.focus?.();
45: 
46:     const handleKeyDown = (event) => {
47:       if (event.key === "Escape") {
48:         event.preventDefault();
49:         if (!closeDisabledRef.current) onCloseRef.current?.();
50:         return;
51:       }
52:       if (event.key !== "Tab") return;
53: 
54:       const focusable = getFocusableElements(dialogRef.current);
55:       if (!focusable.length) {
56:         event.preventDefault();
57:         dialogRef.current?.focus?.();
58:         return;
59:       }
60: 
61:       const first = focusable[0];
62:       const last = focusable[focusable.length - 1];
63:       const active = document.activeElement;
64:       if (event.shiftKey && (active === first || !dialogRef.current?.contains(active))) {
65:         event.preventDefault();
66:         last.focus();
67:       } else if (!event.shiftKey && (active === last || !dialogRef.current?.contains(active))) {
68:         event.preventDefault();
69:         first.focus();
70:       }
71:     };
72: 
73:     globalThis.addEventListener("keydown", handleKeyDown);
74:     return () => {
75:       globalThis.removeEventListener("keydown", handleKeyDown);
76:       document.body.style.overflow = previousOverflow;
77:       if (previouslyFocused instanceof HTMLElement && previouslyFocused.isConnected) {
78:         previouslyFocused.focus();
79:       }
80:     };
81:   }, [dialogRef, enabled, initialFocusRef]);
