 12: const AddResultInline = memo(({ athlete, competitionId, defaultEvent, onAdd }) => {
 13:   const [open,   setOpen]   = useState(false);
 14:   const emptyForm = () => ({ event: defaultEvent || "", result: "", context: "", metadata: createPerformanceMetadata(defaultEvent || "") });
 15:   const [form,   setForm]   = useState(emptyForm);
 16:   const [saving, setSaving] = useState(false);
 17:   const [saveError, setSaveError] = useState(null);
 18: 
 19:   const set = (key, val) => setForm((f) => ({ ...f, [key]: val }));
 20: 
 21:   const handleSubmit = async (event) => {
 22:     event?.preventDefault();
 23:     if (!form.event.trim() || !form.result.trim()) return;
 24:     setSaving(true);
 25:     setSaveError(null);
 26:     try {
 27:       await onAdd(competitionId, athlete.id, form);
 28:       setOpen(false);
 29:       setForm(emptyForm());
 30:     } catch (error) {
 31:       setSaveError(error.message ?? "Impossible d'enregistrer ce résultat");
 32:     } finally {
 33:       setSaving(false);
 34:     }
 35:   };
 36: 
 37:   if (!open) {
 38:     return (
 39:       <button
 40:         type="button"
 41:         onClick={() => setOpen(true)}
 42:         className="text-[12px] font-semibold text-[var(--color-success)] hover:text-[var(--c-accent)] mt-2 min-h-11 flex items-center gap-1.5"
 43:       >
 44:         <Plus size={14} /> Ajouter un résultat
 45:       </button>
 46:     );
 47:   }
 48: 
 49:   return (
 50:     <form onSubmit={handleSubmit} className="mt-3 space-y-2 bg-[var(--c-surface-2)] border border-[var(--c-border-strong)] rounded-xl p-3">
 51:       <label htmlFor={`result-event-${athlete.id}`} className="sr-only">Épreuve</label>
 52:       <input
 53:         id={`result-event-${athlete.id}`}
 54:         className="input-premium"
 55:         placeholder="Épreuve (ex: 100m)"
 56:         value={form.event}
 57:         onChange={(e) => set("event", e.target.value)}
 58:       />
 59:       <label htmlFor={`result-value-${athlete.id}`} className="sr-only">Résultat</label>
 60:       <input
 61:         id={`result-value-${athlete.id}`}
 62:         className="input-premium"
 63:         placeholder="Résultat (ex: 10.94s)"
 64:         value={form.result}
 65:         onChange={(e) => set("result", e.target.value)}
 66:       />
 67:       <label htmlFor={`result-context-${athlete.id}`} className="sr-only">Contexte optionnel</label>
 68:       <input
 69:         id={`result-context-${athlete.id}`}
 70:         className="input-premium"
 71:         placeholder="Contexte (optionnel)"
 72:         value={form.context}
 73:         onChange={(e) => set("context", e.target.value)}
 74:       />
 75:       <PerformanceMetadataFields
 76:         discipline={form.event}
 77:         metadata={form.metadata}
 78:         setMetadata={(updater) => setForm((current) => ({
 79:           ...current,
 80:           metadata: typeof updater === "function" ? updater(current.metadata) : updater,
 81:         }))}
 82:         idPrefix={`result-meta-${athlete.id}`}
 83:       />
 84:       {saveError && <p role="alert" className="text-[12px] text-[var(--color-danger)]">{saveError}</p>}
 85:       <div className="flex items-center gap-2 pt-0.5">
 86:         <button
 87:           type="button"
 88:           onClick={() => { setOpen(false); setSaveError(null); }}
 89:           disabled={saving}
 90:           className="btn-ghost"
 91:         >
 92:           Annuler
 93:         </button>
 94:         <button
 95:           type="submit"
 96:           disabled={!form.event.trim() || !form.result.trim() || saving}
 97:           className="btn-primary"
 98:         >
 99:           {saving ? "…" : "Valider"}
100:         </button>
101:       </div>
102:     </form>
103:   );
104: });
