366:                             <td className="px-3 py-3 text-[12px]" style={{ color: "var(--c-text-2)" }}>{athlete.group || "—"}</td>
367:                           </tr>
368:                         ))}
369:                       </tbody>
370:                     </table>
371:                   </div>
372:                 ) : (
373:                   <div className="rounded-2xl p-4 text-[13px]" style={{ background: "var(--c-surface-2)", color: "var(--c-text-2)" }}>
374:                     Aucun profil valide à importer. Corrige les lignes indiquées puis sélectionne à nouveau le fichier.
375:                   </div>
376:                 )}
377:                 {result.entries.length > PREVIEW_LIMIT && (
378:                   <p className="text-[12px]" style={{ color: "var(--c-text-3)" }}>
379:                     Aperçu limité aux {PREVIEW_LIMIT} premiers profils ; les {result.entries.length} profils valides seront bien transmis.
380:                   </p>
381:                 )}
382:               </section>
383: 
384:               {result.errors.length > 0 && (
385:                 <section aria-labelledby={`${titleId}-errors`}>
386:                   <h3 id={`${titleId}-errors`} className="text-[14px] font-bold mb-2" style={{ color: "var(--c-text-1)" }}>
387:                     Lignes à corriger
388:                   </h3>
389:                   <ul
390:                     className="rounded-2xl divide-y overflow-hidden"
391:                     style={{ border: "1px solid var(--c-border)" }}
392:                   >
393:                     {result.errors.slice(0, ERROR_PREVIEW_LIMIT).map((error, index) => (
394:                       <li key={`${error.row}-${error.code}-${index}`} className="px-4 py-3 flex items-start gap-3 text-[13px]" style={{ color: "var(--c-text-2)" }}>
395:                         <span className="font-bold flex-shrink-0" style={{ color: "var(--tone-warning)" }}>Ligne {error.row ?? "—"}</span>
396:                         <span>{error.message}</span>
397:                       </li>
398:                     ))}
399:                   </ul>
400:                   {result.errors.length > ERROR_PREVIEW_LIMIT && (
401:                     <p className="text-[12px] mt-2" style={{ color: "var(--c-text-3)" }}>
402:                       {result.errors.length - ERROR_PREVIEW_LIMIT} autre(s) ligne(s) incorrecte(s) ne sont pas affichées.
403:                     </p>
404:                   )}
405:                 </section>
406:               )}
407:             </>
408:           )}
409: 
410:           {importError && (
411:             <div role="alert" className="rounded-2xl px-4 py-3 text-[13px]" style={{ background: "rgba(226,75,74,0.1)", color: "var(--tone-danger)" }}>
412:               {importError}
413:             </div>
414:           )}
415:         </div>
416: 
417:         <footer
418:           className="px-5 sm:px-6 py-4 flex items-center justify-between gap-3 flex-shrink-0"
419:           style={{ borderTop: "1px solid var(--c-border)" }}
420:         >
421:           <button type="button" onClick={onClose} disabled={busy} className="btn-secondary">
422:             Annuler
423:           </button>
424:           <button
425:             type="button"
426:             onClick={handleImport}
427:             disabled={!result?.canImport || busy}
428:             className="btn-primary"
429:           >
430:             {importing ? (
431:               <>
432:                 <span className="w-3.5 h-3.5 border-2 border-white/40 border-t-white rounded-full animate-spin" aria-hidden="true" />
433:                 Import en cours…
434:               </>
435:             ) : (
436:               <>
437:                 <Upload size={15} aria-hidden="true" />
438:                 {validCount
439:                   ? `Importer ${validCount} athlète${validCount > 1 ? "s" : ""}`
440:                   : "Importer les athlètes"}
441:               </>
442:             )}
443:           </button>
444:         </footer>
445:       </div>
446:     </div>,
447:     document.body,
448:   );
449: }
