451: export default memo(ImportAthletesCsvModal);  1: // ============================================================
  2: // AthleteOS — src/modules/Messaging.jsx
  3: // ★ MESSAGERIE UNIVERSELLE :
  4: //   Le coach peut écrire à TOUS les membres du club :
  5: //   - Athlètes (via athletes.user_id)
  6: //   - Autres coachs / staff (users avec role != athlete)
  7: //   Les contacts sont unifiés sous une liste "contacts"
  8: //   chacun avec { id, name, avatar, userId, type, subtitle }
  9: // ============================================================
 10: 
 11: import {
 12:   memo, useState, useMemo, useCallback,
 13:   useEffect, useRef,
 14: } from "react";
 15: import { Send, Search, MessageSquare, Check, CheckCheck, Users, User } from "lucide-react";
 16: import { supabase }              from "../utils/supabaseClient";
 17: import { notifyAthleteMessage }  from "../utils/notifications";
 18: import { useAuth }               from "../hooks/useAuth";
 19: import LoadingState              from "../components/ui/LoadingState";
 20: import ErrorState                from "../components/ui/ErrorState";
 21: import { SegmentedTabs }         from "../components/ui/premium";
 22: import { initialsFromName }      from "../utils/helpers.js";
 23: 
 24: // ─── Constantes ───────────────────────────────────────────────────────────────
 25: 
 26: const CONTACT_COLORS = [
 27:   "#1D9E75", "#378ADD", "#A855F7", "#EF9F27",
 28:   "#E24B4A", "#14B8A6", "#F97316", "#EC4899",
 29:   "#0EA5E9", "#84CC16",
 30: ];
 31: 
 32: // ─── Helpers ──────────────────────────────────────────────────────────────────
 33: 
 34: function contactColor(contact, contacts) {
 35:   if (!contact) return "#94a3b8";
 36:   const idx = contacts.findIndex((c) => c.id === contact.id);
 37:   return CONTACT_COLORS[idx % CONTACT_COLORS.length] ?? "#94a3b8";
 38: }
 39: 
 40: function formatTime(dateStr) {
 41:   return new Date(dateStr).toLocaleTimeString("fr-BE", { hour: "2-digit", minute: "2-digit" });
 42: }
 43: 
 44: function formatDateHeader(dateStr) {
 45:   const d   = new Date(dateStr);
 46:   const now = new Date();
 47:   const isToday     = d.toDateString() === now.toDateString();
 48:   const isYesterday = d.toDateString() === new Date(now - 86400000).toDateString();
 49:   if (isToday)     return "Aujourd'hui";
 50:   if (isYesterday) return "Hier";
 51:   return d.toLocaleDateString("fr-BE", { weekday: "long", day: "numeric", month: "long" });
 52: }
 53: 
 54: function groupByDate(msgs) {
 55:   const groups = [];
 56:   let currentDate = null;
 57:   msgs.forEach((m) => {
 58:     const d = new Date(m.date).toDateString();
 59:     if (d !== currentDate) {
 60:       currentDate = d;
 61:       groups.push({ type: "separator", date: m.date, key: `sep-${m.date}` });
 62:     }
 63:     groups.push({ type: "message", data: m, key: m.id });
 64:   });
 65:   return groups;
 66: }
 67: 
 68: // Construit les conversations depuis messages + contacts
 69: // Un "contact" a : { id (unique), userId (int dans users), name, avatar, type, subtitle }
 70: function buildConversations(msgs, contacts, coachUserId) {
 71:   const convMap = new Map();
 72: 
 73:   contacts.forEach((c) => {
 74:     if (c.userId == null) return;
 75:     convMap.set(c.id, { contactId: c.id, userId: c.userId, messages: [], unread: 0 });
 76:   });
 77: 
 78:   msgs.forEach((m) => {
 79:     const otherUserId = m.senderId === coachUserId ? m.receiverId : m.senderId;
 80:     const contact     = contacts.find((c) => c.userId === otherUserId);
 81:     if (!contact) return;
 82:     const conv = convMap.get(contact.id);
 83:     if (!conv) return;
 84:     conv.messages.push(m);
 85:     if (!m.isRead && m.senderId !== coachUserId) conv.unread++;
 86:   });
 87: 
 88:   convMap.forEach((conv) => {
 89:     conv.messages.sort((a, b) => new Date(a.date) - new Date(b.date));
 90:   });
 91: 
 92:   return [...convMap.values()].sort((a, b) => {
 93:     const la = a.messages[a.messages.length - 1]?.date ?? "";
 94:     const lb = b.messages[b.messages.length - 1]?.date ?? "";
 95:     if (!la && !lb) return 0;
 96:     if (!la) return 1;
 97:     if (!lb) return -1;
 98:     return new Date(lb) - new Date(la);
 99:   });
100: }
101: 
102: // ─── Sous-composants ──────────────────────────────────────────────────────────
103: 
