219: const ChatThread = memo(({ conv, contact, contacts, onSend, coachUserId }) => {
220:   const [input,   setInput]   = useState("");
221:   const [sending, setSending] = useState(false);
222:   const bottomRef = useRef(null);
223:   const color     = contactColor(contact, contacts);
224:   const grouped   = useMemo(() => groupByDate(conv.messages), [conv.messages]);
225: 
226:   useEffect(() => {
227:     bottomRef.current?.scrollIntoView({ behavior: "smooth" });
228:   }, [conv.messages.length]);
229: 
230:   const handleSend = useCallback(async () => {
231:     const text = input.trim();
232:     if (!text) return;
233:     setInput("");
234:     setSending(true);
235:     try { await onSend(text); } finally { setSending(false); }
236:   }, [input, onSend]);
237: 
238:   const handleKeyDown = useCallback((e) => {
239:     if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); handleSend(); }
240:   }, [handleSend]);
241: 
242:   return (
243:     <div className="flex flex-col h-full">
244:       {/* Header thread */}
245:       <div className="flex-shrink-0 px-5 py-4 border-b border-[var(--c-border)] bg-[var(--c-surface)] flex items-center gap-3">
246:         <div
247:           className="w-10 h-10 rounded-full flex items-center justify-center text-white text-[11px] font-bold flex-shrink-0"
248:           style={{ background: color }}
249:         >
250:           {initialsFromName(contact?.name ?? "?")}
251:         </div>
252:         <div>
253:           <div className="flex items-center gap-2">
254:             <p className="text-[14px] font-bold text-[var(--c-text-1)]">{contact?.name ?? "Contact"}</p>
255:             {contact?.type === "coach" && (
256:               <span className="text-[10px] font-bold px-2 py-0.5 rounded-full bg-[rgba(91,141,239,0.15)] text-[#5B8DEF]">
257:                 Coach
258:               </span>
259:             )}
260:           </div>
261:           <p className="text-[11px] text-[var(--c-text-3)]">{contact?.subtitle ?? ""}</p>
262:         </div>
263:       </div>
264: 
265:       {/* Messages */}
266:       <div className="flex-1 overflow-y-auto px-5 py-4 space-y-3" style={{ background: "var(--c-bg)" }}>
267:         {grouped.length === 0 ? (
268:           <div className="h-full flex flex-col items-center justify-center gap-2 text-[var(--c-text-4)]">
269:             <MessageSquare size={28} strokeWidth={1.5} />
270:             <p className="text-[12.5px]">Aucun message — écris le premier !</p>
271:           </div>
272:         ) : (
273:           grouped.map((item) =>
274:             item.type === "separator"
275:               ? <DateSeparator key={item.key} date={item.date} />
276:               : <MessageBubble
277:                   key={item.key}
278:                   msg={item.data}
279:                   isOwn={item.data.senderId === coachUserId}
280:                   contact={contact}
281:                   contacts={contacts}
282:                 />
283:           )
284:         )}
285:         <div ref={bottomRef} />
286:       </div>
287: 
288:       {/* Input */}
289:       <div className="flex-shrink-0 px-4 py-3 border-t border-[var(--c-border)] bg-[var(--c-surface)] flex items-end gap-2">
290:         <div className="flex-1 bg-[var(--c-surface-2)] rounded-2xl px-4 py-2.5">
291:           <textarea
292:             className="w-full bg-transparent resize-none text-[13px] text-[var(--c-text-1)] placeholder-[var(--c-text-3)] focus:outline-none max-h-28 min-h-[20px]"
293:             rows={1}
294:             placeholder={`Message à ${contact?.name?.split(" ")[0] ?? "…"}…`}
295:             value={input}
296:             onChange={(e) => setInput(e.target.value)}
297:             onKeyDown={handleKeyDown}
298:             style={{ lineHeight: "1.5" }}
299:           />
300:         </div>
301:         <button
302:           onClick={handleSend}
303:           disabled={!input.trim() || sending}
304:           className="w-10 h-10 rounded-full flex items-center justify-center text-white transition-all flex-shrink-0 disabled:opacity-40 disabled:cursor-not-allowed hover:scale-105 active:scale-95"
305:           style={{ background: "#1D9E75" }}
306:         >
307:           <Send size={16} strokeWidth={2.5} />
308:         </button>
309:       </div>
310:     </div>
311:   );
312: });
