314: const EmptyConvState = () => (
315:   <div className="flex-1 flex flex-col items-center justify-center gap-3 text-[var(--c-text-3)] bg-[var(--c-bg)]">
316:     <MessageSquare size={40} strokeWidth={1.5} />
317:     <p className="text-[14px] font-semibold">Sélectionnez une conversation</p>
318:     <p className="text-[12px] text-[var(--c-text-4)] text-center max-w-[200px]">
319:       Cliquez sur un athlète ou un coach pour démarrer
320:     </p>
321:   </div>
322: );
