324: // ─── Composant principal ──────────────────────────────────────────────────────
325: function Messaging() {
326:   const { profile, clubId } = useAuth();
327:   const coachUserId = profile?.id ?? null;
328: 
329:   // "contacts" = liste unifiée athlètes + autres users du club
330:   const [contacts,    setContacts]    = useState([]);
331:   const [allMessages, setAllMessages] = useState([]);
332:   const [loading,     setLoading]     = useState(true);
333:   const [error,       setError]       = useState(null);
334:   const [activeContactId, setActiveContactId] = useState(null);
335:   const [search,      setSearch]      = useState("");
336:   const [activeTab,   setActiveTab]   = useState("tous"); // "tous" | "athletes" | "coachs"
337: 
338:   // ═══ Chargement ═══════════════════════════════════════════════════════════
339:   const fetchAll = useCallback(async () => {
340:     if (!clubId || !coachUserId) return;
341:     try {
342:       setLoading(true);
343:       setError(null);
344: 
345:       // 1. Athlètes du club
346:       const athletesRes = await supabase
347:         .from("athletes")
348:         .select("id, name, main_discipline, user_id, profile_data")
349:         .eq("club_id", clubId);
350:       if (athletesRes.error) throw athletesRes.error;
351: 
352:       // 2. Autres users du club (coachs, staff) — exclut le coach connecté
353:       const usersRes = await supabase
354:         .from("users")
355:         .select("id, name, role")
356:         .eq("club_id", clubId)
357:         .neq("id", coachUserId); // on s'exclut soi-même
358:       if (usersRes.error) throw usersRes.error;
359: 
360:       // Construire la liste unifiée de contacts
361:       // Chaque contact a un id unique (préfixé pour éviter collision)
362:       const athleteContacts = (athletesRes.data ?? []).map((a) => ({
363:         id:       `athlete-${a.id}`,       // id unique dans la liste
364:         athleteId: a.id,
365:         userId:   a.user_id,               // peut être null si non lié
366:         name:     a.name,
367:         avatar:   a.profile_data?.avatar ?? initialsFromName(a.name),
368:         type:     "athlete",
369:         subtitle: a.main_discipline ?? "Athlète",
370:         linked:   a.user_id != null,
371:       }));
372: 
373:       const coachContacts = (usersRes.data ?? [])
374:         .filter((u) => u.role !== "athlete") // on ne met pas les users-athlètes ici (déjà dans athleteContacts)
375:         .map((u) => ({
376:           id:       `user-${u.id}`,
377:           userId:   u.id,
378:           name:     u.name,
379:           avatar:   initialsFromName(u.name),
380:           type:     "coach",
381:           subtitle: u.role === "head_coach" ? "Head coach" : "Coach",
382:           linked:   true, // les users ont forcément un compte
383:         }));
384: 
385:       const allContacts = [...athleteContacts, ...coachContacts];
386: 
387:       // 3. Messages avec tous ces users
388:       const allUserIds = allContacts
389:         .map((c) => c.userId)
390:         .filter((id) => id != null);
391: 
392:       const messagesRes = allUserIds.length
393:         ? await supabase
394:             .from("messages")
395:             .select("*")
396:             .or(
397:               `and(sender_id.eq.${coachUserId},receiver_id.in.(${allUserIds.join(",")})),` +
398:               `and(receiver_id.eq.${coachUserId},sender_id.in.(${allUserIds.join(",")}))`
399:             )
400:         : { data: [], error: null };
401:       if (messagesRes.error) throw messagesRes.error;
402: 
403:       setContacts(allContacts);
404:       setAllMessages((messagesRes.data ?? []).map((m) => ({
405:         id:         m.id,
406:         senderId:   m.sender_id,
407:         receiverId: m.receiver_id,
408:         content:    m.content,
409:         date:       m.created_at,
410:         isRead:     m.is_read,
411:       })));
412:     } catch (err) {
413:       console.error("Messaging — chargement :", err);
414:       setError(err.message ?? "Erreur inconnue");
415:     } finally {
416:       setLoading(false);
417:     }
418:   }, [clubId, coachUserId]);
419: 
420:   useEffect(() => { fetchAll(); }, [fetchAll]);
421: 
422:   // ═══ Conversations dérivées ═══════════════════════════════════════════════
423:   const conversations = useMemo(
424:     () => buildConversations(allMessages, contacts, coachUserId),
425:     [allMessages, contacts, coachUserId]
426:   );
427: 
428:   const unlinkedAthletes = useMemo(
429:     () => contacts.filter((c) => c.type === "athlete" && !c.linked),
430:     [contacts]
431:   );
432: 
433:   const totalUnread = useMemo(
434:     () => conversations.reduce((s, c) => s + c.unread, 0),
435:     [conversations]
436:   );
437: 
438:   // Filtre recherche + onglet
439:   const filteredConvs = useMemo(() => {
440:     let list = conversations;
441: 
442:     // Filtre par onglet
443:     if (activeTab === "athletes") {
444:       list = list.filter((conv) => {
445:         const c = contacts.find((x) => x.id === conv.contactId);
446:         return c?.type === "athlete";
447:       });
448:     } else if (activeTab === "coachs") {
449:       list = list.filter((conv) => {
450:         const c = contacts.find((x) => x.id === conv.contactId);
451:         return c?.type === "coach";
452:       });
453:     }
454: 
455:     // Filtre recherche
456:     if (search.trim()) {
457:       const q = search.toLowerCase();
458:       list = list.filter((conv) => {
459:         const c = contacts.find((x) => x.id === conv.contactId);
460:         return c?.name.toLowerCase().includes(q) ||
461:           conv.messages.some((m) => m.content.toLowerCase().includes(q));
462:       });
463:     }
464: 
465:     return list;
466:   }, [conversations, search, contacts, activeTab]);
467: 
468:   const activeConv    = useMemo(() => conversations.find((c) => c.contactId === activeContactId) ?? null, [conversations, activeContactId]);
469:   const activeContact = useMemo(() => contacts.find((c) => c.id === activeContactId) ?? null, [contacts, activeContactId]);
470: 
471:   // ═══ Actions ══════════════════════════════════════════════════════════════
472: 
473:   const selectConv = useCallback(async (contactId) => {
474:     setActiveContactId(contactId);
475:     const contact = contacts.find((c) => c.id === contactId);
476:     if (!contact?.userId) return;
477: 
478:     // Marquer comme lu
479:     const hasUnread = allMessages.some(
480:       (m) => m.senderId === contact.userId && m.receiverId === coachUserId && !m.isRead
481:     );
482:     if (!hasUnread) return;
483: 
484:     setAllMessages((prev) => prev.map((m) =>
485:       m.senderId === contact.userId && m.receiverId === coachUserId && !m.isRead
486:         ? { ...m, isRead: true }
487:         : m
488:     ));
489: 
490:     const { error: err } = await supabase
491:       .from("messages")
492:       .update({ is_read: true })
493:       .eq("sender_id", contact.userId)
494:       .eq("receiver_id", coachUserId)
495:       .eq("is_read", false);
496: 
497:     if (err) { console.error("Messaging — markRead :", err); fetchAll(); }
498:   }, [contacts, allMessages, coachUserId, fetchAll]);
499: 
500:   const handleSend = useCallback(async (text) => {
501:     if (!activeContactId || !coachUserId) return;
502:     const contact = contacts.find((c) => c.id === activeContactId);
503:     if (!contact?.userId) return;
504: 
505:     const { data, error: err } = await supabase
506:       .from("messages")
507:       .insert({
508:         sender_id:   coachUserId,
509:         receiver_id: contact.userId,
510:         content:     text,
511:         is_read:     false,
512:       })
513:       .select()
514:       .single();
515: 
516:     if (err) { console.error("Messaging — send :", err); return; }
517: 
518:     // Ajout optimiste
519:     setAllMessages((prev) => [...prev, {
520:       id:         data.id,
521:       senderId:   data.sender_id,
522:       receiverId: data.receiver_id,
523:       content:    data.content,
524:       date:       data.created_at,
525:       isRead:     data.is_read,
526:     }]);
527: 
528:     // Push notif si c'est un athlète
529:     if (contact.type === "athlete" && contact.athleteId) {
530:       await notifyAthleteMessage(
531:         clubId,
532:         contact.athleteId,
533:         profile?.name ?? "Coach",
534:         text
535:       ).catch(console.warn);
536:     }
537:   }, [activeContactId, contacts, coachUserId, clubId, profile]);
538: 
539:   // ═══ Render ═══════════════════════════════════════════════════════════════
540:   if (loading) return <LoadingState message="Chargement de la messagerie…" />;
541:   if (error)   return <ErrorState  message={error} onRetry={fetchAll} />;
542: 
543:   const coachCount   = contacts.filter((c) => c.type === "coach").length;
544:   const athleteCount = contacts.filter((c) => c.type === "athlete" && c.linked).length;
545: 
546:   return (
547:     <div className="flex h-full overflow-hidden" style={{ height: "calc(100vh - 64px)" }}>
548: 
549:       {/* ── Panneau gauche ─────────────────────────────────────────────── */}
550:       <div className="w-72 flex-shrink-0 bg-[var(--c-surface)] border-r border-[var(--c-border)] flex flex-col">
551: 
552:         {/* Header */}
553:         <div className="px-4 py-4 border-b border-[var(--c-border)] flex-shrink-0">
554:           <div className="flex items-center justify-between mb-3">
555:             <h2 className="text-[15px] font-bold text-[var(--c-text-1)]">Messagerie</h2>
556:             {totalUnread > 0 && (
557:               <span
558:                 className="text-[12px] font-bold px-2 py-0.5 rounded-full text-white"
559:                 style={{ background: "#E24B4A" }}
560:               >
561:                 {totalUnread} non lu{totalUnread > 1 ? "s" : ""}
562:               </span>
563:             )}
564:           </div>
565: 
566:           {/* Recherche */}
567:           <div className="flex items-center gap-2 bg-[var(--c-surface-2)] rounded-xl px-3 py-2 mb-3">
568:             <Search size={13} className="text-[var(--c-text-3)] flex-shrink-0" />
569:             <input
570:               type="text"
571:               placeholder="Rechercher…"
572:               value={search}
573:               onChange={(e) => setSearch(e.target.value)}
574:               className="flex-1 bg-transparent text-[12.5px] text-[var(--c-text-1)] placeholder-[var(--c-text-3)] focus:outline-none"
575:             />
576:           </div>
577: 
578:           {/* Onglets filtre */}
579:           <SegmentedTabs
580:             ariaLabel="Filtrer les conversations"
581:             items={[
582:               { id: "tous", label: "Tous", badge: athleteCount + coachCount },
583:               { id: "athletes", label: "Athlètes", badge: athleteCount },
584:               { id: "coachs", label: "Coachs", badge: coachCount },
585:             ]}
586:             value={activeTab}
587:             onChange={setActiveTab}
588:           />
589:         </div>
590: 
591:         {/* Coach connecté */}
592:         <div className="px-4 py-3 border-b border-[var(--c-border)] flex items-center gap-2.5 flex-shrink-0 bg-[var(--c-surface-2)]">
593:           <div
594:             className="w-7 h-7 rounded-full flex items-center justify-center text-white text-[9px] font-bold flex-shrink-0"
595:             style={{ background: "#378ADD" }}
596:           >
597:             {initialsFromName(profile?.name ?? "")}
598:           </div>
599:           <div>
600:             <p className="text-[11.5px] font-semibold text-[var(--c-text-1)]">{profile?.name ?? "Coach"}</p>
601:             <p className="text-[10px] text-[var(--c-text-3)]">Connecté · {profile?.role === "head_coach" ? "Head coach" : "Coach"}</p>
602:           </div>
603:           <div className="ml-auto w-2 h-2 rounded-full bg-emerald-400 flex-shrink-0" />
604:         </div>
605: 
606:         {/* Avertissement athlètes sans compte */}
607:         {unlinkedAthletes.length > 0 && (
608:           <div className="px-4 py-2 bg-[rgba(232,160,32,0.1)] border-b border-[rgba(232,160,32,0.2)] flex-shrink-0">
609:             <p className="text-[10.5px] text-[#E8A020] leading-relaxed">
610:               ⚠️ {unlinkedAthletes.length} athlète{unlinkedAthletes.length > 1 ? "s" : ""} sans compte —
611:               {" "}{unlinkedAthletes.map((a) => a.name.split(" ")[0]).join(", ")}
612:             </p>
613:           </div>
614:         )}
615: 
616:         {/* Liste conversations */}
617:         <div className="flex-1 overflow-y-auto divide-y divide-[var(--c-border)]">
618:           {filteredConvs.length === 0 ? (
619:             <div className="px-4 py-8 text-center">
620:               <Users size={24} className="mx-auto mb-2 text-[var(--c-text-4)]" />
621:               <p className="text-[12px] text-[var(--c-text-4)]">
622:                 {search ? "Aucun résultat" : "Aucune conversation"}
623:               </p>
624:             </div>
625:           ) : (
626:             filteredConvs.map((conv) => {
627:               const contact = contacts.find((c) => c.id === conv.contactId);
628:               return (
629:                 <ConvItem
630:                   key={conv.contactId}
631:                   conv={conv}
632:                   contact={contact}
633:                   contacts={contacts}
634:                   isActive={conv.contactId === activeContactId}
635:                   onClick={selectConv}
636:                   coachUserId={coachUserId}
637:                 />
638:               );
639:             })
640:           )}
641:         </div>
642:       </div>
643: 
644:       {/* ── Panneau droit ──────────────────────────────────────────────── */}
645:       <div className="flex-1 flex flex-col overflow-hidden">
646:         {activeConv && activeContact ? (
647:           <ChatThread
648:             key={activeContactId}
649:             conv={activeConv}
650:             contact={activeContact}
651:             contacts={contacts}
652:             onSend={handleSend}
653:             coachUserId={coachUserId}
654:           />
655:         ) : (
656:           <EmptyConvState />
657:         )}
658:       </div>
659:     </div>
660:   );
661: }
