 12: const HEX_COLOR_PATTERN = /^#[0-9A-F]{6}$/;
 13: 
 14: export function normalizeClubAccent(value, fallback = DEFAULT_CLUB_ACCENT) {
 15:   const normalized = typeof value === "string" ? value.trim().toUpperCase() : "";
 16:   return HEX_COLOR_PATTERN.test(normalized) ? normalized : fallback;
 17: }
 18: 
 19: export function hexToRgb(value) {
 20:   const normalized = normalizeClubAccent(value);
 21:   return {
 22:     r: Number.parseInt(normalized.slice(1, 3), 16),
 23:     g: Number.parseInt(normalized.slice(3, 5), 16),
 24:     b: Number.parseInt(normalized.slice(5, 7), 16),
 25:   };
 26: }
 27: 
 28: export function darkenHex(value, amount = 0.16) {
 29:   const { r, g, b } = hexToRgb(value);
 30:   const factor = Math.max(0, Math.min(1, 1 - amount));
 31:   const channel = (part) => Math.round(part * factor).toString(16).padStart(2, "0");
 32:   return `#${channel(r)}${channel(g)}${channel(b)}`.toUpperCase();
 33: }
 34: 
 35: export function getClubThemeVariables(accentColor) {
 36:   const accent = normalizeClubAccent(accentColor);
 37:   const { r, g, b } = hexToRgb(accent);
 38:   return {
 39:     "--club-accent": accent,
 40:     "--club-accent-rgb": `${r}, ${g}, ${b}`,
 41:     "--color-accent": accent,
 42:     "--color-accent-strong": darkenHex(accent),
 43:     "--c-accent-light": `rgba(${r}, ${g}, ${b}, 0.15)`,
 44:     "--c-accent-glow": `rgba(${r}, ${g}, ${b}, 0.20)`,
 45:   };
 46: }
 47: 
 48: export function normalizeInviteCode(value) {
 49:   return typeof value === "string"
 50:     ? value.trim().toUpperCase().replace(/[\s-]+/gu, "").slice(0, 8)
 51:     : "";
 52: }
 53: 
 54: export function buildInviteUrl(inviteCode, origin = globalThis.location?.origin) {
 55:   if (!inviteCode || !origin) return "";
 56:   const url = new URL("/", origin);
 57:   url.searchParams.set("invite", normalizeInviteCode(String(inviteCode)));
 58:   return url.toString();
 59: }
