14:   });
15: 
16:   it("rattache la fin décembre à la semaine 1 de l'année suivante quand l'ISO l'exige", () => {
17:     // Le 31/12/2029 est un lundi : ISO le place en semaine 1 de 2030.
18:     expect(getISOWeek(new Date(2029, 11, 31))).toBe(1);
19:     expect(getISOWeekYear(new Date(2029, 11, 31))).toBe(2030);
20:   });
21: 
22:   it("rattache début janvier à la dernière semaine de l'année précédente quand l'ISO l'exige", () => {
23:     // Le 01/01/2027 est un vendredi : ISO le place encore en semaine 53 de 2026.
24:     expect(getISOWeek(new Date(2027, 0, 1))).toBe(53);
25:     expect(getISOWeekInfo(new Date(2027, 0, 1))).toMatchObject({
26:       week: 53,
27:       year: 2026,
28:       startDate: "2026-12-28",
29:       endDate: "2027-01-03",
30:     });
31:   });
32: 
33:   it("avance d'une semaine chaque lundi", () => {
34:     const week1 = getISOWeek(new Date(2026, 2, 2));
35:     const week2 = getISOWeek(new Date(2026, 2, 9));
36:     expect(week2).toBe(week1 + 1);
37:   });
38: });
