  9: const SIGNED_URL_TTL_SECONDS = 60;
 10: export const SESSION_ATTACHMENT_MAX_BYTES = 30 * 1024 * 1024;
 11: 
 12: const ATTACHMENT_FORMATS = [
 13:   { extensions: ["pdf"], mime: "application/pdf", signature: "pdf" },
 14:   { extensions: ["jpg", "jpeg"], mime: "image/jpeg", signature: "jpeg" },
 15:   { extensions: ["png"], mime: "image/png", signature: "png" },
 16:   { extensions: ["webp"], mime: "image/webp", signature: "webp" },
 17:   { extensions: ["gif"], mime: "image/gif", signature: "gif" },
 18:   { extensions: ["heic"], mime: "image/heic", signature: "heif" },
 19:   { extensions: ["heif"], mime: "image/heif", signature: "heif" },
 20:   { extensions: ["avif"], mime: "image/avif", signature: "avif" },
 21:   { extensions: ["bmp"], mime: "image/bmp", signature: "bmp" },
 22:   { extensions: ["tif", "tiff"], mime: "image/tiff", signature: "tiff" },
 23:   { extensions: ["doc"], mime: "application/msword", signature: "compound" },
 24:   { extensions: ["docx"], mime: "application/vnd.openxmlformats-officedocument.wordprocessingml.document", signature: "zip" },
 25:   { extensions: ["xls"], mime: "application/vnd.ms-excel", signature: "compound" },
 26:   { extensions: ["xlsx"], mime: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet", signature: "zip" },
 27:   { extensions: ["ppt"], mime: "application/vnd.ms-powerpoint", signature: "compound" },
 28:   { extensions: ["pptx"], mime: "application/vnd.openxmlformats-officedocument.presentationml.presentation", signature: "zip" },
 29:   { extensions: ["odt"], mime: "application/vnd.oasis.opendocument.text", signature: "zip" },
 30:   { extensions: ["ods"], mime: "application/vnd.oasis.opendocument.spreadsheet", signature: "zip" },
 31:   { extensions: ["odp"], mime: "application/vnd.oasis.opendocument.presentation", signature: "zip" },
 32:   { extensions: ["rtf"], mime: "application/rtf", signature: "rtf" },
 33:   { extensions: ["txt"], mime: "text/plain", signature: "text" },
 34:   { extensions: ["csv"], mime: "text/csv", signature: "text" },
 35: ];
 36: 
 37: export const SESSION_ATTACHMENT_ACCEPT = ATTACHMENT_FORMATS
 38:   .flatMap(format => format.extensions.map(extension => `.${extension}`))
 39:   .join(",");
 40: 
 41: const ALLOWED_DECLARED_MIMES = new Set([
 42:   ...ATTACHMENT_FORMATS.map(format => format.mime),
 43:   "application/octet-stream",
 44:   "application/zip",
 45:   "application/csv",
 46:   "text/rtf",
 47:   "image/pjpeg",
 48: ]);
 49: 
 50: function extensionOf(name = "") {
 51:   return name.toLowerCase().match(/\.([a-z0-9]+)$/)?.[1] ?? "";
 52: }
 53: 
 54: function startsWith(bytes, expected) {
 55:   return expected.every((value, index) => bytes[index] === value);
 56: }
 57: 
 58: function hasIsoBrand(bytes, brands) {
 59:   const header = new TextDecoder("latin1").decode(bytes.slice(4, 32));
 60:   return brands.some(brand => header.includes(brand));
 61: }
 62: 
 63: function hasExpectedSignature(bytes, signature) {
 64:   switch (signature) {
 65:     case "pdf": return new TextDecoder("latin1").decode(bytes).includes("%PDF-");
 66:     case "jpeg": return startsWith(bytes, [0xff, 0xd8, 0xff]);
 67:     case "png": return startsWith(bytes, [0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]);
 68:     case "webp": return startsWith(bytes, [0x52, 0x49, 0x46, 0x46]) && new TextDecoder("latin1").decode(bytes.slice(8, 12)) === "WEBP";
 69:     case "gif": return ["GIF87a", "GIF89a"].includes(new TextDecoder("latin1").decode(bytes.slice(0, 6)));
 70:     case "heif": return hasIsoBrand(bytes, ["heic", "heix", "hevc", "hevx", "mif1", "msf1"]);
 71:     case "avif": return hasIsoBrand(bytes, ["avif", "avis"]);
 72:     case "bmp": return startsWith(bytes, [0x42, 0x4d]);
 73:     case "tiff": return startsWith(bytes, [0x49, 0x49, 0x2a, 0x00]) || startsWith(bytes, [0x4d, 0x4d, 0x00, 0x2a]);
 74:     case "compound": return startsWith(bytes, [0xd0, 0xcf, 0x11, 0xe0, 0xa1, 0xb1, 0x1a, 0xe1]);
 75:     case "zip": return startsWith(bytes, [0x50, 0x4b, 0x03, 0x04]) || startsWith(bytes, [0x50, 0x4b, 0x05, 0x06]);
 76:     case "rtf": return new TextDecoder("latin1").decode(bytes.slice(0, 5)) === "{\\rtf";
 77:     case "text": return !bytes.includes(0);
 78:     default: return false;
 79:   }
 80: }
