 82: export async function validateSessionAttachment(file) {
 83:   if (!file) return null;
 84:   if (file.size > SESSION_ATTACHMENT_MAX_BYTES) return "Fichier trop volumineux (30 Mo max).";
 85: 
 86:   const format = ATTACHMENT_FORMATS.find(candidate => candidate.extensions.includes(extensionOf(file.name)));
 87:   if (!format) return "Format non accepté. Utilise une image, un PDF ou un document bureautique.";
 88: 
 89:   const declaredType = file.type?.toLowerCase();
 90:   if (declaredType && !ALLOWED_DECLARED_MIMES.has(declaredType)) {
 91:     return "Ce type de fichier n'est pas accepté.";
 92:   }
 93: 
 94:   try {
 95:     const header = new Uint8Array(await file.slice(0, 1024).arrayBuffer());
 96:     if (!hasExpectedSignature(header, format.signature)) return "Le fichier sélectionné semble invalide ou corrompu.";
 97:   } catch {
 98:     return "Impossible de lire le fichier sélectionné.";
 99:   }
100: 
101:   return null;
102: }
103: 
104: export async function uploadSessionAttachment(clubId, file) {
105:   if (!clubId) throw new Error("Club introuvable : impossible d'envoyer le fichier.");
106:   const validationError = await validateSessionAttachment(file);
107:   if (validationError) throw new Error(validationError);
108: 
109:   const extension = extensionOf(file.name);
110:   const format = ATTACHMENT_FORMATS.find(candidate => candidate.extensions.includes(extension));
111:   const uniqueId = globalThis.crypto?.randomUUID?.()
112:     ?? `${Date.now()}-${Math.random().toString(36).slice(2)}`;
113:   const path = `${clubId}/${uniqueId}.${extension}`;
114:   const { error } = await supabase.storage.from("session-pdfs").upload(path, file, {
115:     contentType: format.mime,
116:   });
117:   if (error) throw error;
118:   return path;
119: }
120: 
121: export async function openSessionAttachment(path) {
122:   if (!path) return false;
123:   const win = window.open("about:blank", "_blank");
124:   if (win) win.opener = null;
125:   const { data, error } = await supabase.storage.from("session-pdfs").createSignedUrl(path, SIGNED_URL_TTL_SECONDS);
126:   if (error || !data?.signedUrl) {
127:     console.error("Erreur génération URL de pièce jointe :", error);
128:     win?.close();
129:     return false;
130:   }
131:   if (win) win.location.replace(data.signedUrl);
132:   else window.location.assign(data.signedUrl);
133:   return true;
134: }
