  5: const MAX_BODY_BYTES = 2_000;
  6: 
  7: serve(async (req) => {
  8:   const serviceKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");
  9:   const supabaseUrl = Deno.env.get("SUPABASE_URL");
 10:   if (!serviceKey || !supabaseUrl) {
 11:     console.error("session-reminders: configuration Supabase manquante");
 12:     return new Response(JSON.stringify({ error: "configuration_error" }), { status: 503 });
 13:   }
 14:   if (req.method !== "POST") {
 15:     return new Response(JSON.stringify({ error: "method_not_allowed" }), { status: 405 });
 16:   }
 17:   if ((req.headers.get("Authorization") ?? "") !== `Bearer ${serviceKey}`) {
 18:     return new Response(JSON.stringify({ error: "unauthorized" }), { status: 401 });
 19:   }
 20: 
 21:   let dryRun = false;
 22:   try {
 23:     const rawBody = await req.text();
 24:     if (new TextEncoder().encode(rawBody).byteLength > MAX_BODY_BYTES) {
 25:       return new Response(JSON.stringify({ error: "payload_too_large" }), { status: 413 });
 26:     }
 27:     dryRun = rawBody ? Boolean(JSON.parse(rawBody)?.dry_run) : false;
 28:   } catch {
 29:     return new Response(JSON.stringify({ error: "invalid_json" }), { status: 400 });
 30:   }
 31: 
 32:   const admin = createClient(supabaseUrl, serviceKey);
 33:   const today = localDateInTimeZone(new Date(), "Europe/Brussels");
 34:   const log: string[] = [];
 35: 
 36:   try {
 37:     const { data: sessions, error } = await admin.from("sessions")
 38:       .select("id, club_id, title, time, lifecycle_status, session_athletes(athlete_id)")
 39:       .eq("session_date", today)
 40:       .in("lifecycle_status", ["planned", "live"]);
 41:     if (error) throw error;
 42: 
 43:     for (const session of sessions ?? []) {
 44:       const athleteIds = [...new Set(
 45:         (session.session_athletes ?? []).map((row: { athlete_id: number }) => row.athlete_id),
 46:       )];
 47:       if (!athleteIds.length) continue;
 48: 
 49:       const time = session.time ? String(session.time).slice(0, 5) : null;
 50:       const title = `Séance aujourd’hui — ${session.title}`;
 51:       const description = time
 52:         ? `Ta séance commence à ${time}. Pense à confirmer ta présence.`
 53:         : "Ta séance est prévue aujourd’hui. Pense à confirmer ta présence.";
 54:       const dedupeKey = `session-day-${session.id}`;
 55:       const rows = athleteIds.map((athleteId: number) => ({
 56:         athlete_id: athleteId,
 57:         club_id: session.club_id,
 58:         session_id: session.id,
 59:         type: "session_day_reminder",
 60:         title,
 61:         description,
 62:         is_read: false,
 63:         dedupe_key: dedupeKey,
 64:       }));
 65: 
 66:       let targets = athleteIds;
 67:       if (!dryRun) {
 68:         const { data: inserted, error: insertError } = await admin
 69:           .from("athlete_notifications")
 70:           .upsert(rows, { onConflict: "athlete_id,type,dedupe_key", ignoreDuplicates: true })
 71:           .select("athlete_id");
 72:         if (insertError) throw insertError;
 73:         targets = (inserted ?? []).map((row: { athlete_id: number }) => row.athlete_id);
 74:       }
 75:       if (!targets.length) continue;
 76: 
 77:       log.push(`sessionReminder athletes=${targets.length}`);
 78:       if (dryRun) continue;
 79:       const pushResponse = await fetch(`${supabaseUrl}/functions/v1/send-push`, {
 80:         method: "POST",
 81:         headers: { "Content-Type": "application/json", "Authorization": `Bearer ${serviceKey}` },
 82:         body: JSON.stringify({
 83:           athleteIds: targets,
 84:           userIds: [],
 85:           title,
 86:           body: description,
 87:           url: "/planning",
 88:           tag: dedupeKey,
 89:         }),
 90:       });
 91:       if (!pushResponse.ok) {
 92:         throw new Error(`send-push HTTP ${pushResponse.status}`);
 93:       }
 94:     }
 95: 
 96:     return new Response(JSON.stringify({ ok: true, dryRun, date: today, log }), {
 97:       headers: { "Content-Type": "application/json" },
 98:     });
 99:   } catch (error) {
100:     console.error("session-reminders error:", error instanceof Error ? error.message : error);
101:     return new Response(JSON.stringify({ error: "session_reminders_failed", date: today }), {
102:       status: 500,
103:       headers: { "Content-Type": "application/json" },
104:     });
105:   }
