 63: -- Fonction utilisée par (quasi) toutes les policies plus bas — DOIT venir
 64: -- après `users` : pour une fonction LANGUAGE sql, Postgres résout et
 65: -- vérifie les tables référencées dès la création (contrairement à
 66: -- plpgsql, où le corps n'est vérifié qu'à la première exécution) — la
 67: -- créer avant que `users` existe échoue immédiatement ("relation "users"
 68: -- does not exist"). C'est exactement ce qui a fait échouer le 1er essai
 69: -- de cette migration en CI.
 70: CREATE OR REPLACE FUNCTION public.get_my_club_id()
 71: RETURNS integer
 72: LANGUAGE sql STABLE SECURITY DEFINER
 73: SET search_path TO 'public'
 74: AS $$
 75:   SELECT club_id FROM users
 76:   WHERE lower(trim(auth_uid)) = lower(trim(auth.uid()::text))
 77:   LIMIT 1;
 78: $$;
