298: -- ── RLS : activation + policies d'origine (avant tout durcissement) ────────
299: -- Convention observée sur la vraie base : deux policies FOR ALL par table,
300: -- une ancienne ("Club members only", role authenticated, via une
301: -- sous-requête sur users.auth_id — colonne devenue orpheline) et une plus
302: -- récente ("<table>_club", role public, via get_my_club_id()). Les deux
303: -- coexistaient déjà en production avant le début du suivi des migrations
304: -- (c'est exactement ce que la tâche 6 a corrigé plus tard dans l'historique
305: -- — cette migration ne fait que reproduire l'état de départ pour que
306: -- l'historique complet rejoue correctement).
307: 
308: ALTER TABLE public.clubs ENABLE ROW LEVEL SECURITY;
309: CREATE POLICY "Club members only" ON public.clubs FOR SELECT TO authenticated
310:   USING (id = (SELECT u.club_id FROM public.users u WHERE u.auth_id = auth.uid()));
311: CREATE POLICY "clubs_own" ON public.clubs FOR SELECT TO public
312:   USING (id = get_my_club_id());
313: 
314: ALTER TABLE public.users ENABLE ROW LEVEL SECURITY;
315: -- Casse exacte confirmée sur la vraie base (tâche 6) : "club members only"
316: -- en minuscules ici, contrairement aux 12 autres tables ci-dessous qui
317: -- utilisent toutes "Club members only" — la migration 20260728130618 (tâche
318: -- 6) cible précisément ce nom, sensible à la casse, pour la supprimer.
319: CREATE POLICY "club members only" ON public.users FOR ALL TO public
320:   USING (auth_id = auth.uid());
321: 
322: ALTER TABLE public.athletes ENABLE ROW LEVEL SECURITY;
323: CREATE POLICY "Club members only" ON public.athletes FOR ALL TO authenticated
324:   USING (club_id = (SELECT u.club_id FROM public.users u WHERE (u.auth_uid)::uuid = auth.uid()))
325:   WITH CHECK (club_id = (SELECT u.club_id FROM public.users u WHERE (u.auth_uid)::uuid = auth.uid()));
326: CREATE POLICY "athletes_club" ON public.athletes FOR ALL TO public
327:   USING (club_id = get_my_club_id());
