446: CREATE OR REPLACE FUNCTION public.rls_auto_enable()
447: RETURNS event_trigger
448: LANGUAGE plpgsql SECURITY DEFINER
449: SET search_path TO 'pg_catalog'
450: AS $$
451: DECLARE
452:   cmd record;
453: BEGIN
454:   FOR cmd IN
455:     SELECT * FROM pg_event_trigger_ddl_commands()
456:     WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
457:       AND object_type IN ('table','partitioned table')
458:   LOOP
459:      IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') THEN
460:       BEGIN
461:         EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
462:       EXCEPTION WHEN OTHERS THEN NULL;
463:       END;
464:      END IF;
465:   END LOOP;
466: END;
467: $$;
