  3: -- AthleteOS charge model v2
  4: -- Global internal load = actual duration in minutes x session RPE CR10.
  5: -- Category-specific constraints stay in the separate axis model and are no
  6: -- longer hidden multipliers of the global session-RPE value.
  7: 
  8: ALTER TABLE public.session_athletes
  9:   ADD COLUMN IF NOT EXISTS actual_duration_minutes integer,
 10:   ADD COLUMN IF NOT EXISTS duration_source text;
 11: 
 12: DO $$
 13: BEGIN
 14:   IF NOT EXISTS (
 15:     SELECT 1 FROM pg_constraint
 16:     WHERE conrelid = 'public.session_athletes'::regclass
 17:       AND conname = 'session_athletes_actual_duration_check'
 18:   ) THEN
 19:     ALTER TABLE public.session_athletes
 20:       ADD CONSTRAINT session_athletes_actual_duration_check
 21:       CHECK (actual_duration_minutes IS NULL OR actual_duration_minutes BETWEEN 1 AND 1440);
 22:   END IF;
 23:   IF NOT EXISTS (
 24:     SELECT 1 FROM pg_constraint
 25:     WHERE conrelid = 'public.session_athletes'::regclass
 26:       AND conname = 'session_athletes_duration_source_check'
 27:   ) THEN
 28:     ALTER TABLE public.session_athletes
 29:       ADD CONSTRAINT session_athletes_duration_source_check
 30:       CHECK (duration_source IS NULL OR duration_source IN ('reported', 'planned_legacy'));
 31:   END IF;
 32: END;
 33: $$;
 34: 
 35: COMMENT ON COLUMN public.session_athletes.actual_duration_minutes IS
 36:   'Durée réellement effectuée et déclarée pour le calcul session-RPE standard.';
 37: COMMENT ON COLUMN public.session_athletes.duration_source IS
 38:   'reported = durée déclarée; planned_legacy = ancienne durée planifiée conservée et signalée comme estimation.';
 39: 
 40: -- Preserve historical charts without pretending that the planned duration was
 41: -- measured. Scientific daily metrics can exclude these estimated points.
 42: UPDATE public.session_athletes sa
 43: SET
 44:   actual_duration_minutes = s.duration_minutes,
 45:   duration_source = 'planned_legacy'
 46: FROM public.sessions s
 47: WHERE s.id = sa.session_id
 48:   AND sa.rpe IS NOT NULL
 49:   AND sa.actual_duration_minutes IS NULL
 50:   AND s.duration_minutes IS NOT NULL;
 51: 
 52: -- Certaines anciennes lignes ont un RPE sans durée récupérable. Une CHECK
 53: -- NOT VALID bloquerait encore toute modification annexe de ces lignes (par
 54: -- exemple confirmer la présence). Le trigger protège donc uniquement les
 55: -- nouvelles écritures de charge : insertion avec RPE, changement de RPE ou
 56: -- changement de durée. Les historiques incomplets restent lisibles et sont
 57: -- classés comme données inconnues dans les vues ci-dessous.
 58: ALTER TABLE public.session_athletes
 59:   DROP CONSTRAINT IF EXISTS session_athletes_rpe_requires_duration_check;
 60: 
 61: CREATE OR REPLACE FUNCTION public.enforce_session_rpe_duration_on_write()
 62: RETURNS trigger
 63: LANGUAGE plpgsql
 64: SET search_path TO 'public'
 65: AS $$
 66: DECLARE
 67:   v_load_changed boolean;
 68: BEGIN
 69:   IF TG_OP = 'INSERT' THEN
 70:     v_load_changed := true;
 71:   ELSE
 72:     v_load_changed := NEW.rpe IS DISTINCT FROM OLD.rpe
 73:       OR NEW.actual_duration_minutes IS DISTINCT FROM OLD.actual_duration_minutes
 74:       OR NEW.duration_source IS DISTINCT FROM OLD.duration_source;
 75:   END IF;
 76: 
 77:   IF v_load_changed
 78:   AND NEW.rpe IS NOT NULL
 79:   AND NEW.status IS DISTINCT FROM 'none'
 80:   AND (NEW.actual_duration_minutes IS NULL OR NEW.duration_source IS NULL)
 81:   THEN
 82:     RAISE EXCEPTION 'Une durée réelle est obligatoire avec le RPE.';
 83:   END IF;
 84:   RETURN NEW;
 85: END;
 86: $$;
 87: 
 88: DROP TRIGGER IF EXISTS session_athletes_enforce_rpe_duration ON public.session_athletes;
 89: CREATE TRIGGER session_athletes_enforce_rpe_duration
 90:   BEFORE INSERT OR UPDATE ON public.session_athletes
 91:   FOR EACH ROW EXECUTE FUNCTION public.enforce_session_rpe_duration_on_write();
 92: 
 93: UPDATE public.charge_model_versions SET is_active = false WHERE is_active;
 94: INSERT INTO public.charge_model_versions (
 95:   version, load_coefficients, recovery_hours, is_active, notes
 96: ) VALUES (
 97:   'v2-session-rpe-standard',
 98:   '{"force":1,"sprint":1,"haies":1,"lancer":1,"saut":1,"endurance":1,"technique":1,"mobilite":1,"recuperation":1}'::jsonb,
 99:   '{"sprint":72,"haies":72,"force":72,"saut":48,"lancer":48,"endurance":36,"technique":24,"mobilite":12,"recuperation":12}'::jsonb,
100:   true,
101:   'Session-RPE standard durée réelle x RPE, sans coefficient ni division. recovery_hours est une règle configurable d espacement de programmation, pas une estimation physiologique.'
102: )
103: ON CONFLICT (version) DO UPDATE SET
104:   load_coefficients = EXCLUDED.load_coefficients,
105:   recovery_hours = EXCLUDED.recovery_hours,
106:   is_active = true,
107:   notes = EXCLUDED.notes;
