109: CREATE OR REPLACE VIEW public.daily_training_load
110: WITH (security_invoker = true)
111: AS
112: SELECT
113:   sa.athlete_id,
114:   s.session_date AS load_date,
115:   s.week,
116:   CASE
117:     WHEN bool_and(
118:       sa.status = 'none'
119:       OR (
120:         sa.rpe IS NOT NULL
121:         AND sa.actual_duration_minutes IS NOT NULL
122:       )
123:     ) THEN SUM(
124:       CASE
125:         WHEN sa.status = 'none' THEN 0
126:         ELSE sa.actual_duration_minutes * sa.rpe
127:       END
128:     )::integer
129:     ELSE NULL
130:   END AS raw_load,
131:   bool_and(
132:     sa.status = 'none'
133:     OR (sa.rpe IS NOT NULL AND sa.actual_duration_minutes IS NOT NULL)
134:   ) AS is_complete,
135:   bool_or(
136:     sa.status IS DISTINCT FROM 'none'
137:     AND sa.rpe IS NOT NULL
138:     AND sa.duration_source = 'planned_legacy'
139:   ) AS is_estimated,
140:   count(*)::integer AS assigned_session_count,
141:   count(*) FILTER (
142:     WHERE sa.status IS DISTINCT FROM 'none'
143:       AND (sa.rpe IS NULL OR sa.actual_duration_minutes IS NULL)
144:   )::integer AS unknown_session_count
145: FROM public.session_athletes sa
146: JOIN public.sessions s ON s.id = sa.session_id
147: WHERE s.session_date IS NOT NULL
148: GROUP BY sa.athlete_id, s.session_date, s.week;
