152: -- Keep the historical API shape and add daily detail/quality columns at the
153: -- end. Existing pages continue reading athlete_id/week/raw_load unchanged.
154: CREATE OR REPLACE VIEW public.weekly_charge
155: WITH (security_invoker = true)
156: AS
157: SELECT
158:   d.athlete_id,
159:   d.week,
160:   CASE
161:     WHEN bool_and(d.raw_load IS NOT NULL) THEN SUM(d.raw_load)::integer
162:     ELSE NULL
163:   END AS raw_load,
164:   jsonb_agg(
165:     jsonb_build_object(
166:       'date', d.load_date,
167:       'load', d.raw_load,
168:       'estimated', d.is_estimated,
169:       'complete', d.is_complete
170:     ) ORDER BY d.load_date
171:   ) AS daily_loads,
172:   count(*) FILTER (WHERE d.raw_load IS NOT NULL)::integer AS known_days,
173:   count(*) FILTER (WHERE d.raw_load IS NULL)::integer AS unknown_days,
174:   count(*) FILTER (WHERE d.is_estimated)::integer AS estimated_days
175: FROM public.daily_training_load d
176: GROUP BY d.athlete_id, d.week;
177: 
178: GRANT SELECT ON public.weekly_charge TO authenticated;
179: 
180: COMMIT;  1: BEGIN;
