 51: CREATE OR REPLACE VIEW public.daily_training_load
 52: WITH (security_invoker = true)
 53: AS
 54: WITH session_days AS (
 55:   SELECT
 56:     sa.athlete_id,
 57:     s.session_date AS load_date,
 58:     s.week,
 59:     CASE
 60:       WHEN bool_and(
 61:         sa.status = 'none'
 62:         OR (
 63:           sa.rpe IS NOT NULL
 64:           AND sa.actual_duration_minutes IS NOT NULL
 65:         )
 66:       )
 67:       THEN sum(
 68:         CASE
 69:           WHEN sa.status = 'none' THEN 0
 70:           ELSE sa.actual_duration_minutes * sa.rpe
 71:         END
 72:       )::integer
 73:       ELSE NULL
 74:     END AS raw_load,
 75:     bool_and(
 76:       sa.status = 'none'
 77:       OR (
 78:         sa.rpe IS NOT NULL
 79:         AND sa.actual_duration_minutes IS NOT NULL
 80:       )
 81:     ) AS is_complete,
 82:     bool_or(
 83:       sa.status IS DISTINCT FROM 'none'
 84:       AND sa.rpe IS NOT NULL
 85:       AND sa.duration_source = 'planned_legacy'
 86:     ) AS is_estimated,
 87:     count(*)::integer AS assigned_session_count,
 88:     count(*) FILTER (
 89:       WHERE sa.status IS DISTINCT FROM 'none'
 90:         AND (
 91:           sa.rpe IS NULL
 92:           OR sa.actual_duration_minutes IS NULL
 93:         )
 94:     )::integer AS unknown_session_count
 95:   FROM public.session_athletes sa
 96:   JOIN public.sessions s ON s.id = sa.session_id
 97:   WHERE s.session_date IS NOT NULL
 98:   GROUP BY sa.athlete_id, s.session_date, s.week
 99: )
100: SELECT * FROM session_days
101: UNION ALL
102: SELECT
103:   rest.athlete_id,
104:   rest.load_date,
105:   EXTRACT(WEEK FROM rest.load_date)::integer AS week,
106:   0 AS raw_load,
107:   true AS is_complete,
108:   false AS is_estimated,
109:   0 AS assigned_session_count,
110:   0 AS unknown_session_count
111: FROM public.athlete_daily_load_days rest
112: WHERE rest.state = 'rest_confirmed'
113:   AND NOT EXISTS (
114:     SELECT 1
115:     FROM session_days day
116:     WHERE day.athlete_id = rest.athlete_id
117:       AND day.load_date = rest.load_date
118:   );
119: 
120: GRANT SELECT ON public.daily_training_load TO authenticated;
121: 
122: COMMIT; 1: BEGIN;
