18:   created_at timestamptz NOT NULL DEFAULT now(),
19:   CONSTRAINT club_invitations_code_format_check CHECK (code ~ '^[ABCDEFGHJKLMNPQRSTUVWXYZ23456789]{8}$'),
20:   CONSTRAINT club_invitations_recipient_name_check CHECK (recipient_name IS NULL OR char_length(btrim(recipient_name)) BETWEEN 1 AND 100),
21:   CONSTRAINT club_invitations_recipient_email_check CHECK (recipient_email IS NULL OR char_length(recipient_email) <= 254)
22: );
