31: -- Aucune policy cliente : les coordonnées et l'historique sont servis par
32: -- admin-actions après vérification head_coach. L'inspection publique ci-dessous
33: -- ne renvoie ni nom du destinataire, ni email, ni identifiant interne.
34: 
35: CREATE OR REPLACE FUNCTION public.inspect_club_invitation(p_code text)
36: RETURNS jsonb
37: LANGUAGE plpgsql
38: SECURITY DEFINER
39: SET search_path TO 'public'
40: AS $$
41: DECLARE
42:   v_code text;
43:   v_invitation public.club_invitations%ROWTYPE;
44:   v_club_name text;
45:   v_status text;
46: BEGIN
47:   v_code := upper(regexp_replace(coalesce(p_code, ''), '[[:space:]-]+', '', 'g'));
48:   IF v_code !~ '^[A-Z0-9]{8}$' THEN
49:     RETURN jsonb_build_object('status', 'invalid');
50:   END IF;
51: 
52:   SELECT invitation.*
53:   INTO v_invitation
54:   FROM public.club_invitations invitation
55:   WHERE upper(btrim(invitation.code)) = v_code
56:   LIMIT 1;
57: 
58:   IF FOUND THEN
59:     SELECT club.name INTO v_club_name
60:     FROM public.clubs club
61:     WHERE club.id = v_invitation.club_id;
62:     v_status := CASE
63:       WHEN v_invitation.status = 'revoked' THEN 'revoked'
64:       WHEN v_invitation.accepted_at IS NOT NULL THEN 'accepted'
65:       WHEN v_invitation.expires_at IS NOT NULL AND v_invitation.expires_at <= now() THEN 'expired'
66:       ELSE 'active'
67:     END;
68:     IF v_status = 'active' AND v_invitation.opened_at IS NULL THEN
69:       UPDATE public.club_invitations SET opened_at = now() WHERE id = v_invitation.id;
70:     END IF;
71:     RETURN jsonb_build_object(
72:       'status', v_status,
73:       'kind', 'individual',
74:       'clubName', v_club_name,
75:       'expiresAt', v_invitation.expires_at
76:     );
77:   END IF;
78: 
79:   SELECT club.name
80:   INTO v_club_name
81:   FROM public.clubs club
82:   WHERE upper(btrim(club.invite_code)) = v_code
83:     AND (club.invite_code_expires_at IS NULL OR club.invite_code_expires_at > now())
84:   LIMIT 1;
85:   IF FOUND THEN
86:     RETURN jsonb_build_object('status', 'active', 'kind', 'club', 'clubName', v_club_name);
87:   END IF;
88: 
89:   RETURN jsonb_build_object('status', 'invalid');
90: END;
91: $$;
92: 
93: REVOKE ALL ON FUNCTION public.inspect_club_invitation(text) FROM PUBLIC;
94: GRANT EXECUTE ON FUNCTION public.inspect_club_invitation(text) TO anon, authenticated;
95: 
