25: -- Les compteurs et bandeaux ouverts dans l'application écoutent ces tables.
26: -- L'ajout est idempotent afin de fonctionner aussi si Realtime a déjà été
27: -- activé manuellement depuis le dashboard Supabase.
28: do $$
29: begin
30:   if exists (select 1 from pg_publication where pubname = 'supabase_realtime') then
31:     if not exists (
32:       select 1 from pg_publication_tables
33:       where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'alerts'
34:     ) then
35:       alter publication supabase_realtime add table public.alerts;
36:     end if;
37:     if not exists (
38:       select 1 from pg_publication_tables
39:       where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'athlete_notifications'
40:     ) then
41:       alter publication supabase_realtime add table public.athlete_notifications;
42:     end if;
43:   end if;
44: end $$;  1: # For detailed configuration reference documentation, visit:
