  2: // ============================================================
  3: // AthleteOS — test_axis_model_parity.mjs
  4: //
  5: // Vérifie le versionnement des poids du profil à 6 axes (tâche 18) :
  6: //   - la version active en base a EXACTEMENT les mêmes poids que la
  7: //     constante JS AXIS_WEIGHTS (parité JS/DB, comme charge_model_versions
  8: //     en tâche 16)
  9: //   - un poids hors bornes ([0,1]) est rejeté à l'insertion (trigger)
 10: //   - un poids dans les bornes est accepté
 11: //   - une seconde version "active" est rejetée (une seule à la fois)
 12: //   - une nouvelle version peut être créée sans toucher la version 'v1'
 13: //     existante (changement de configuration = nouvelle ligne, pas une
 14: //     mutation de l'historique)
 15: //
 16: // Usage :
 17: //   SUPABASE_SERVICE_ROLE_KEY=... node test_axis_model_parity.mjs
 18: //
 19: // Requiert dans l'environnement (ou .env à la racine du dossier) :
 20: //   VITE_SUPABASE_URL           (déjà dans .env)
 21: //   SUPABASE_SERVICE_ROLE_KEY   (secret, jamais committé)
 22: // ============================================================
 23: 
 24: import { createClient } from "@supabase/supabase-js";
 25: import { readFileSync } from "node:fs";
 26: import { fileURLToPath } from "node:url";
 27: import path from "node:path";
 28: import { AXIS_WEIGHTS, CURRENT_AXIS_MODEL_VERSION, LOAD_AXES } from "./src/utils/loadAxes.js";
 29: 
 30: function loadDotEnv(filePath) {
 31:   let text;
 32:   try { text = readFileSync(filePath, "utf8"); } catch { return; }
 33:   for (const rawLine of text.split("\n")) {
 34:     const line = rawLine.replace(/\r$/, "");
 35:     const m = line.match(/^([A-Z0-9_]+)=(.*)$/);
 36:     if (m && process.env[m[1]] === undefined) process.env[m[1]] = m[2].trim();
 37:   }
 38: }
 39: loadDotEnv(path.join(path.dirname(fileURLToPath(import.meta.url)), ".env"));
 40: 
 41: const SUPABASE_URL     = process.env.VITE_SUPABASE_URL;
 42: const SERVICE_ROLE_KEY = process.env.SUPABASE_SERVICE_ROLE_KEY;
 43: 
 44: if (!SUPABASE_URL || !SERVICE_ROLE_KEY) {
 45:   console.error(
 46:     "Variables manquantes. Requis : VITE_SUPABASE_URL (dans .env) et " +
 47:     "SUPABASE_SERVICE_ROLE_KEY (variable d'environnement, jamais committée)."
 48:   );
 49:   process.exit(1);
 50: }
 51: 
 52: const admin = createClient(SUPABASE_URL, SERVICE_ROLE_KEY, {
 53:   auth: { autoRefreshToken: false, persistSession: false },
 54: });
 55: 
 56: const AXIS_IDS = Object.keys(LOAD_AXES);
 57: const results = [];
 58: function record(name, pass, detail) {
 59:   results.push({ name, pass, detail });
 60:   console.log(`${pass ? "✅" : "❌"} ${name}${detail ? " — " + detail : ""}`);
 61: }
 62: 
 63: function sameWeights(dbWeights, jsWeights) {
 64:   const catsDb = Object.keys(dbWeights ?? {}).sort();
 65:   const catsJs = Object.keys(jsWeights ?? {}).sort();
 66:   if (catsDb.length !== catsJs.length || catsDb.some((c, i) => c !== catsJs[i])) return false;
 67:   return catsDb.every((cat) => AXIS_IDS.every((axis) => Number(dbWeights[cat][axis]) === Number(jsWeights[cat][axis])));
 68: }
 69: 
 70: async function main() {
 71:   const RUN_ID = Date.now();
 72:   const scratchVersions = [`test-ok-${RUN_ID}`, `test-active-${RUN_ID}`];
 73: 
 74:   try {
 75:     // ── 1. Parité : version active en base === AXIS_WEIGHTS (JS) ─────────
 76:     const { data: active, error: activeErr } = await admin
 77:       .from("axis_model_versions").select("*").eq("is_active", true).maybeSingle();
 78:     if (activeErr) throw new Error(`lecture axis_model_versions : ${activeErr.message}`);
 79:     record("Une version active existe", !!active, active ? `version=${active.version}` : "aucune version active !");
 80: 
 81:     if (active) {
 82:       record("Version active en base === CURRENT_AXIS_MODEL_VERSION (JS)", active.version === CURRENT_AXIS_MODEL_VERSION,
 83:         `db=${active.version} js=${CURRENT_AXIS_MODEL_VERSION}`);
 84:       record("axis_weights : base === JS (les 9 catégories x 6 axes)", sameWeights(active.axis_weights, AXIS_WEIGHTS),
 85:         `db=${JSON.stringify(active.axis_weights)}`);
 86:     }
 87: 
 88:     // ── 2. Bornes : poids hors [0,1] rejeté, dans les bornes accepté ──────
 89:     {
 90:       const { error: badErr } = await admin.from("axis_model_versions").insert({
 91:         version: `test-bad-${RUN_ID}`,
 92:         axis_weights: { sprint: { neuromuscular: 1.7 } }, // hors bornes (max 1.0)
 93:         is_active: false,
 94:       });
 95:       record("Poids hors bornes (1.7) -> rejeté", !!badErr, badErr?.message);
 96:     }
 97:     {
 98:       const { error: goodErr } = await admin.from("axis_model_versions").insert({
 99:         version: `test-ok-${RUN_ID}`,
100:         axis_weights: { sprint: { neuromuscular: 0.8 } },
101:         is_active: false,
102:       });
103:       record("Poids dans les bornes (0.8) -> accepté", !goodErr, goodErr?.message);
104:     }
105: 
106:     // ── 3. Une seule version active à la fois ─────────────────────────────
107:     {
108:       const { error: dupActiveErr } = await admin.from("axis_model_versions").insert({
109:         version: `test-active-${RUN_ID}`,
110:         axis_weights: { sprint: { neuromuscular: 0.5 } },
111:         is_active: true,
112:       });
113:       record("Deuxième version active -> rejetée (contrainte unique)", !!dupActiveErr, dupActiveErr?.message);
114:     }
115: 
116:     // ── 4. Une version scratch ne modifie ni la version courante ni v1 ────
117:     {
118:       const { data: currentAfter } = await admin.from("axis_model_versions")
119:         .select("axis_weights, is_active")
120:         .eq("version", CURRENT_AXIS_MODEL_VERSION)
121:         .maybeSingle();
122:       const { data: v1After } = await admin.from("axis_model_versions")
123:         .select("axis_weights, is_active")
124:         .eq("version", "v1")
125:         .maybeSingle();
126:       record("La version courante reste active après création d'une version scratch", currentAfter?.is_active === true);
127:       record("La version courante reste inchangée après création d'une version scratch",
128:         JSON.stringify(active?.axis_weights) === JSON.stringify(currentAfter?.axis_weights));
129:       record("'v1' reste disponible dans l'historique sans être active",
130:         !!v1After && v1After.is_active === false);
131:     }
132: 
133:   } finally {
134:     console.log("\nNettoyage...");
135:     for (const v of scratchVersions) await admin.from("axis_model_versions").delete().eq("version", v);
136:   }
137: 
138:   const failed = results.filter((r) => !r.pass);
139:   console.log(`\n${results.length - failed.length}/${results.length} vérifications OK`);
140:   if (failed.length) {
141:     console.error(`\n${failed.length} régression(s) détectée(s) :`);
142:     failed.forEach((f) => console.error(`  - ${f.name}${f.detail ? " : " + f.detail : ""}`));
143:     process.exit(1);
144:   }
145:   console.log("\nParité JS/DB confirmée, bornes et versionnement fonctionnels.");
146:   process.exit(0);
147: }
148: 
149: main().catch((err) => {
150:   console.error("Erreur fatale :", err.message ?? err);
151:   process.exit(1);
152: });  1: #!/usr/bin/env node
  2: // ============================================================
  3: // AthleteOS — test_competition_transactions.mjs
  4: //
  5: // Vérifie les RPC transactionnelles de la tâche 14
  6: // (create_competition_with_athletes / add_competition_result /
  7: // create_solo_competition_result / mark_notification_outbox_sent) en
  8: // conditions réelles, contre les fonctions DÉPLOYÉES :
  9: //   1. Un coach crée une compétition avec plusieurs athlètes en un seul
 10: //      appel — la compétition ET tous les participants existent, ou rien.
 11: //   2. Un coach ajoute un résultat : record créé/mis à jour, outbox
 12: //      écrite, notifications dépêchées après coup.
 13: //   3. Un athlète déclare seul une compétition + son résultat en un seul
 14: //      appel (compétition + lien + résultat + performance + record).
 15: //   4. Autorisation directe sur RPC : un athlète ne peut pas appeler
 16: //      add_competition_result (réservé coach), un coach d'un autre club
 17: //      ne peut pas viser une compétition/un athlète qui n'est pas le
 18: //      sien, un athlète ne peut pas créer une compétition pour un tiers.
 19: //   5. Rejeu de la même clé d'idempotence : pas de second résultat, pas
 20: //      de second effet sur le record.
 21: //   6. Deux résultats CONCURRENTS battant le même record (Promise.all) :
 22: //      un seul record final cohérent, aucune ligne dupliquée dans
 23: //      `records`.
 24: //
 25: // Crée deux clubs, comptes et fixtures éphémères ; nettoie tout à la fin.
 26: //
 27: // Usage :
 28: //   SUPABASE_SERVICE_ROLE_KEY=... node test_competition_transactions.mjs
 29: // ============================================================
 30: 
 31: import { createClient } from "@supabase/supabase-js";
 32: import { readFileSync } from "node:fs";
 33: import { fileURLToPath } from "node:url";
 34: import path from "node:path";
 35: import crypto from "node:crypto";
 36: 
 37: function loadDotEnv(filePath) {
 38:   let text;
 39:   try { text = readFileSync(filePath, "utf8"); } catch { return; }
 40:   for (const rawLine of text.split("\n")) {
 41:     const line = rawLine.replace(/\r$/, "");
 42:     const m = line.match(/^([A-Z0-9_]+)=(.*)$/);
 43:     if (m && process.env[m[1]] === undefined) process.env[m[1]] = m[2].trim();
 44:   }
 45: }
 46: loadDotEnv(path.join(path.dirname(fileURLToPath(import.meta.url)), ".env"));
 47: 
 48: const SUPABASE_URL    = process.env.VITE_SUPABASE_URL;
 49: const ANON_KEY         = process.env.VITE_SUPABASE_ANON_KEY;
 50: const SERVICE_ROLE_KEY = process.env.SUPABASE_SERVICE_ROLE_KEY;
 51: 
 52: if (!SUPABASE_URL || !ANON_KEY || !SERVICE_ROLE_KEY) {
 53:   console.error(
 54:     "Variables manquantes. Requis : VITE_SUPABASE_URL, VITE_SUPABASE_ANON_KEY " +
 55:     "(dans .env) et SUPABASE_SERVICE_ROLE_KEY (variable d'environnement, jamais committée)."
 56:   );
 57:   process.exit(1);
 58: }
 59: 
 60: const admin = createClient(SUPABASE_URL, SERVICE_ROLE_KEY, { auth: { autoRefreshToken: false, persistSession: false } });
 61: 
 62: const RUN_ID = Date.now();
 63: const results = [];
 64: function record(name, pass, detail) {
 65:   results.push({ name, pass, detail });
 66:   console.log(`${pass ? "✅" : "❌"} ${name}${detail ? " — " + detail : ""}`);
 67: }
