 69: async function insertOrThrow(table, row) {
 70:   const { data, error } = await admin.from(table).insert(row).select().single();
 71:   if (error) throw new Error(`seed ${table} : ${error.message}`);
 72:   return data;
 73: }
 74: 
 75: async function makeUser(email, password, clubId, role, name) {
 76:   const { data: a, error: ea } = await admin.auth.admin.createUser({ email, password, email_confirm: true });
 77:   if (ea) throw new Error(`createUser ${email} : ${ea.message}`);
 78:   const userRow = await insertOrThrow("users", { club_id: clubId, name, email, role, auth_uid: a.user.id });
 79:   const athleteRow = await insertOrThrow("athletes", { club_id: clubId, name, user_id: userRow.id });
 80:   const client = createClient(SUPABASE_URL, ANON_KEY, { auth: { autoRefreshToken: false, persistSession: false } });
 81:   const { error: es } = await client.auth.signInWithPassword({ email, password });
 82:   if (es) throw new Error(`signIn ${email} : ${es.message}`);
 83:   return { auth: a.user, user: userRow, athlete: athleteRow, client };
 84: }
 85: 
 86: async function main() {
 87:   let clubA, clubB, compA;
 88:   const auths = [];
 89:   const password = `Comp-Test-${RUN_ID}-Aa!`;
 90: 
 91:   try {
 92:     clubA = await insertOrThrow("clubs", { name: `Comp Test Club A ${RUN_ID}` });
 93:     clubB = await insertOrThrow("clubs", { name: `Comp Test Club B ${RUN_ID}` });
 94: 
 95:     const coachA   = await makeUser(`comp-test-coacha-${RUN_ID}@example.invalid`,   password, clubA.id, "head_coach", "Coach A"); auths.push(coachA);
 96:     const athleteA = await makeUser(`comp-test-athletea-${RUN_ID}@example.invalid`, password, clubA.id, "athlete",    "Athlete A"); auths.push(athleteA);
 97:     const athleteA2= await makeUser(`comp-test-athletea2-${RUN_ID}@example.invalid`,password, clubA.id, "athlete",    "Athlete A2"); auths.push(athleteA2);
 98:     const headB    = await makeUser(`comp-test-headb-${RUN_ID}@example.invalid`,    password, clubB.id, "head_coach", "Head B"); auths.push(headB);
 99: 
100:     // ── 1. Coach crée une compétition avec plusieurs athlètes (atomique) ───
101:     {
102:       const { data, error } = await coachA.client.rpc("create_competition_with_athletes", {
103:         p_name: `Meeting Test ${RUN_ID}`, p_date: "2026-08-15", p_location: "Stade", p_type: "Régionale",
104:         p_athlete_entries: [{ athleteId: athleteA.athlete.id, plannedEvent: "100m" }, { athleteId: athleteA2.athlete.id, plannedEvent: "Longueur" }],
105:         p_idempotency_key: crypto.randomUUID(),
106:       });
107:       record("create_competition_with_athletes (coach, positif)", !error && !!data?.competitionId, error?.message);
108:       compA = data;
109:       const { data: links } = await admin.from("competition_athletes").select("athlete_id").eq("competition_id", data?.competitionId);
110:       record("les 2 athlètes sont bien liés à la compétition", (links ?? []).length === 2, `${links?.length ?? 0} lien(s)`);
111:     }
112: 
113:     // Tous les tests suivants ont besoin d'une compétition valide — si le
114:     // test 1 a échoué, mieux vaut s'arrêter proprement ici (et nettoyer)
115:     // que de planter en cascade sur `compA.competitionId` undefined,
116:     // ce qui masquerait le vrai échec derrière une erreur JS confuse.
117:     if (!compA?.competitionId) {
118:       record("Arrêt anticipé : pas de compétition valide, tests suivants ignorés", false, "voir l'échec ci-dessus");
119:       return;
120:     }
121: 
122:     // ── 4a. Un athlète ne peut pas appeler add_competition_result ──────────
123:     {
124:       const { error } = await athleteA.client.rpc("add_competition_result", {
125:         p_competition_id: compA.competitionId, p_athlete_id: athleteA.athlete.id, p_event: "100m",
126:         p_result: "11.50", p_result_value: 11.5, p_higher_is_better: false,
127:       });
128:       record("add_competition_result refusé pour un athlète", !!error, error ? "bloqué, OK" : "AUTORISÉ !");
129:     }
130: 
131:     // ── 4b. Un coach d'un AUTRE club ne peut pas viser cette compétition ───
132:     {
133:       const { error } = await headB.client.rpc("add_competition_result", {
134:         p_competition_id: compA.competitionId, p_athlete_id: athleteA.athlete.id, p_event: "100m",
135:         p_result: "11.50", p_result_value: 11.5, p_higher_is_better: false,
136:       });
137:       record("add_competition_result refusé (coach club B sur compétition club A)", !!error, error ? "bloqué, OK" : "AUTORISÉ !");
138:     }
139: 
140:     // ── 4c. Un athlète ne peut pas créer une compétition pour un tiers ──────
141:     {
142:       const { error } = await athleteA.client.rpc("create_competition_with_athletes", {
143:         p_name: "Triche", p_date: "2026-08-16", p_location: null, p_type: "Régionale",
144:         p_athlete_entries: [{ athleteId: athleteA2.athlete.id, plannedEvent: null }],
145:       });
146:       record("create_competition_with_athletes refusé (athlète engage un tiers)", !!error, error ? "bloqué, OK" : "AUTORISÉ !");
147:     }
148: 
149:     // ── 2. Coach ajoute un résultat (positif) — 1er résultat pour cette
150:     //    discipline = record automatique ──────────────────────────────────
151:     let firstResultRecordId;
152:     {
153:       const { data, error } = await coachA.client.rpc("add_competition_result", {
154:         p_competition_id: compA.competitionId, p_athlete_id: athleteA.athlete.id, p_event: "100m",
155:         p_result: "11.50", p_result_value: 11.5, p_higher_is_better: false, p_idempotency_key: crypto.randomUUID(),
156:       });
157:       record("add_competition_result (coach, positif)", !error && !!data?.resultId, error?.message);
158:       record("1er résultat = nouveau record automatique", data?.isNewRecord === true, `isNewRecord=${data?.isNewRecord}`);
159:       record("outbox contient les 2 événements attendus", (data?.notifications ?? []).length === 2, `${data?.notifications?.length ?? 0} événement(s)`);
160:       firstResultRecordId = data?.recordId;
161: 
162:       const { data: rec } = await admin.from("records").select("pr, pr_value").eq("id", firstResultRecordId).single();
163:       record("le record en base correspond au résultat", rec?.pr === "11.50" && Number(rec?.pr_value) === 11.5, JSON.stringify(rec));
164:     }
165: 
166:     // ── 5. Idempotence : rejouer la même clé ne duplique pas le résultat ────
167:     {
168:       const key = crypto.randomUUID();
169:       const r1 = await coachA.client.rpc("add_competition_result", {
170:         p_competition_id: compA.competitionId, p_athlete_id: athleteA2.athlete.id, p_event: "Longueur",
171:         p_result: "5.80", p_result_value: 5.8, p_higher_is_better: true, p_idempotency_key: key,
172:       });
173:       const r2 = await coachA.client.rpc("add_competition_result", {
174:         p_competition_id: compA.competitionId, p_athlete_id: athleteA2.athlete.id, p_event: "Longueur",
175:         p_result: "5.80", p_result_value: 5.8, p_higher_is_better: true, p_idempotency_key: key,
176:       });
177:       record("rejeu idempotent : les deux appels réussissent", !r1.error && !r2.error, `${r1.error?.message ?? ""} ${r2.error?.message ?? ""}`.trim());
178:       record("rejeu idempotent : même resultId renvoyé (pas de second insert)", r1.data?.resultId === r2.data?.resultId, `${r1.data?.resultId} vs ${r2.data?.resultId}`);
179:       const { count } = await admin.from("competition_results").select("id", { count: "exact", head: true })
180:         .eq("competition_id", compA.competitionId).eq("athlete_id", athleteA2.athlete.id).eq("event", "Longueur");
181:       record("un seul competition_results créé malgré le rejeu", count === 1, `count=${count}`);
182:     }
183: 
184:     // ── 6. Deux résultats CONCURRENTS battant le même record ────────────────
185:     // athleteA (100m, record actuel 11.50) : deux coachs (ici le même coach,
186:     // deux appels simultanés) soumettent 11.20 et 11.10 en même temps.
187:     {
188:       const [ra, rb] = await Promise.all([
189:         coachA.client.rpc("add_competition_result", {
190:           p_competition_id: compA.competitionId, p_athlete_id: athleteA.athlete.id, p_event: "100m",
191:           p_result: "11.20", p_result_value: 11.2, p_higher_is_better: false, p_idempotency_key: crypto.randomUUID(),
192:         }),
193:         coachA.client.rpc("add_competition_result", {
194:           p_competition_id: compA.competitionId, p_athlete_id: athleteA.athlete.id, p_event: "100m",
195:           p_result: "11.10", p_result_value: 11.1, p_higher_is_better: false, p_idempotency_key: crypto.randomUUID(),
196:         }),
197:       ]);
198:       record("les deux résultats concurrents réussissent (pas de deadlock/erreur)", !ra.error && !rb.error, `${ra.error?.message ?? ""} ${rb.error?.message ?? ""}`.trim());
199: 
200:       const { data: recRows } = await admin.from("records").select("id, pr, pr_value").eq("athlete_id", athleteA.athlete.id).eq("discipline", "100m");
201:       record("une seule ligne records pour cet athlète+discipline après la course", (recRows ?? []).length === 1, `${recRows?.length ?? 0} ligne(s)`);
202:       record("le record final est bien le meilleur temps (11.10, le plus petit)", recRows?.[0]?.pr === "11.10" && Number(recRows?.[0]?.pr_value) === 11.1, JSON.stringify(recRows));
203: 
204:       const { count: resCount } = await admin.from("competition_results").select("id", { count: "exact", head: true })
205:         .eq("competition_id", compA.competitionId).eq("athlete_id", athleteA.athlete.id).eq("event", "100m");
206:       record("les deux résultats concurrents sont bien tous les deux enregistrés (pas juste le record)", resCount === 3, `count=${resCount} (attendu 3 : 11.50 initial + 11.20 + 11.10)`);
207:     }
208: 
209:     // ── 3. Athlète déclare seul une compétition + résultat (atomique) ──────
210:     {
211:       const { data, error } = await athleteA2.client.rpc("create_solo_competition_result", {
212:         p_name: `Meeting solo ${RUN_ID}`, p_date: "2026-08-20", p_location: null, p_type: "Préparation",
213:         p_event: "400m", p_result: "58.00", p_result_value: 58, p_higher_is_better: false,
214:         p_idempotency_key: crypto.randomUUID(),
215:       });
216:       record("create_solo_competition_result (athlète, positif)", !error && !!data?.resultId && !!data?.performanceId, error?.message);
217:       const { data: perf } = await admin.from("athlete_performances").select("id").eq("id", data?.performanceId).maybeSingle();
218:       record("la performance solo est bien journalisée (Évolution)", !!perf, "introuvable");
219:     }
220: 
221:     // ── mark_notification_outbox_sent : accessible et scoping club ─────────
222:     {
223:       const { data: pending } = await admin.from("notification_outbox").select("id").eq("club_id", clubA.id).eq("status", "pending").limit(5);
224:       const ids = (pending ?? []).map(r => r.id);
225:       if (ids.length) {
226:         const { error } = await coachA.client.rpc("mark_notification_outbox_sent", { p_ids: ids });
227:         record("mark_notification_outbox_sent réussit pour son propre club", !error, error?.message);
228:         const { data: after } = await admin.from("notification_outbox").select("status").in("id", ids);
229:         record("les événements marqués sont bien 'sent'", (after ?? []).every(r => r.status === "sent"), JSON.stringify(after?.map(r=>r.status)));
230:       } else {
231:         record("mark_notification_outbox_sent (aucun événement pending à tester)", true, "ignoré");
232:       }
233:     }
234:     {
235:       // headB (club B) ne doit pas pouvoir marquer des événements du club A.
236:       const { data: pending } = await admin.from("notification_outbox").select("id").eq("club_id", clubA.id).eq("status", "pending").limit(1);
237:       if (pending?.length) {
238:         const { error } = await headB.client.rpc("mark_notification_outbox_sent", { p_ids: [pending[0].id] });
239:         const { data: still } = await admin.from("notification_outbox").select("status").eq("id", pending[0].id).single();
240:         record("mark_notification_outbox_sent (club B) ne touche pas les événements du club A", !error && still?.status === "pending", `error=${error?.message} status=${still?.status}`);
241:       } else {
242:         record("mark_notification_outbox_sent scoping club (aucun événement à tester)", true, "ignoré");
243:       }
244:     }
245: 
246:   } finally {
247:     console.log("\nNettoyage...");
248:     for (const u of auths) {
249:       if (!u) continue;
250:       await u.client.auth.signOut().catch(() => {});
251:     }
252:     if (compA?.competitionId) {
253:       await admin.from("competition_results").delete().eq("competition_id", compA.competitionId);
254:       await admin.from("competition_athletes").delete().eq("competition_id", compA.competitionId);
255:       await admin.from("competitions").delete().eq("id", compA.competitionId);
256:     }
257:     // Retrouve et nettoie aussi la compétition solo + celle de la tentative refusée (jamais créée, rien à faire).
258:     const { data: soloComps } = await admin.from("competitions").select("id").in("club_id", [clubA?.id, clubB?.id].filter(Boolean));
259:     for (const c of soloComps ?? []) {
260:       await admin.from("competition_results").delete().eq("competition_id", c.id);
261:       await admin.from("competition_athletes").delete().eq("competition_id", c.id);
262:     }
263:     if (soloComps?.length) await admin.from("competitions").delete().in("id", soloComps.map(c => c.id));
264: 
265:     await admin.from("notification_outbox").delete().in("club_id", [clubA?.id, clubB?.id].filter(Boolean));
266:     await admin.from("rpc_idempotency").delete().in("actor_user_id", auths.map(u => u?.user?.id).filter(Boolean));
267:     for (const u of auths) {
268:       if (!u) continue;
269:       await admin.from("records").delete().eq("athlete_id", u.athlete.id);
270:       await admin.from("athlete_performances").delete().eq("athlete_id", u.athlete.id);
271:       await admin.from("athletes").delete().eq("id", u.athlete.id);
272:       await admin.from("users").delete().eq("id", u.user.id);
273:       await admin.auth.admin.deleteUser(u.auth.id).catch(() => {});
274:     }
275:     if (clubA) await admin.from("clubs").delete().eq("id", clubA.id);
276:     if (clubB) await admin.from("clubs").delete().eq("id", clubB.id);
277:   }
