 13: export default function AddCompModal({ compForm, setCompForm, onClose, onSubmit, saving, error }) {
 14:   const { dialogRef } = useAccessibleDialog({ onClose, closeDisabled: saving });
 15:   const labelStyle = { display: "block", fontSize: 12, fontWeight: 700, letterSpacing: "0.06em", textTransform: "uppercase", color: "var(--c-text-2)", marginBottom: 8 };
 16:   return createPortal(
 17:     <div className="fixed inset-0 z-50 flex items-end sm:items-center justify-center sm:p-4 modal-backdrop"
 18:       onClick={e => e.target === e.currentTarget && !saving && onClose()}>
 19:       <form ref={dialogRef} tabIndex={-1} onSubmit={event => { event.preventDefault(); onSubmit(); }} role="dialog" aria-modal="true" aria-labelledby="add-comp-title"
 20:         className="rounded-t-3xl sm:rounded-3xl shadow-2xl w-full sm:max-w-sm max-h-[90vh] flex flex-col overflow-hidden modal-content"
 21:         style={{ background: "var(--c-surface)" }}>
 22:         <div style={{ display: "flex", justifyContent: "center", paddingTop: 10, paddingBottom: 4 }}>
 23:           <div style={{ width: 32, height: 3, borderRadius: 99, background: "var(--c-border-strong)" }} />
 24:         </div>
 25:         <div style={{ padding: "14px 20px", borderBottom: "1px solid var(--c-border)", display: "flex", alignItems: "center", justifyContent: "space-between" }}>
 26:           <div>
 27:             <h2 id="add-comp-title" style={{ fontSize: 17, fontWeight: 700, color: "var(--c-text-1)" }}>Ajouter une compétition</h2>
 28:             <p style={{ fontSize: 13, color: "var(--c-text-2)", marginTop: 3 }}>Le résultat sera enregistré dans ton profil.</p>
 29:           </div>
 30:           <button type="button" aria-label="Fermer" onClick={onClose} disabled={saving}
 31:             style={{ width: 44, height: 44, borderRadius: 12, background: "var(--c-surface-2)", border: "1px solid var(--c-border)", display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer", color: "var(--c-text-2)" }}>
 32:             <X size={18} aria-hidden="true" />
 33:           </button>
 34:         </div>
 35:         <div style={{ flex: 1, overflowY: "auto", padding: "16px 20px", display: "flex", flexDirection: "column", gap: 12 }}>
 36:           {[
 37:             { key: "name",     label: "Nom de la compétition *", placeholder: "Ex: Championnat provincial" },
 38:             { key: "location", label: "Lieu",                    placeholder: "Ex: Namur" },
 39:             { key: "event",    label: "Épreuve *",               placeholder: "Ex: 100m ou Décathlon" },
 40:             { key: "result",   label: COMBINE_EVENTS[compForm.event] ? "Total (points) *" : "Résultat *", placeholder: "Ex: 10.94" },
 41:             { key: "context",  label: "Contexte",                placeholder: "Ex: Vent +1.2, finale" },
 42:           ].map(f => (
 43:             <div key={f.key}>
 44:               <label htmlFor={`comp-${f.key}`} style={labelStyle}>
 45:                 {f.label}
 46:               </label>
 47:               <input id={`comp-${f.key}`} className="input-premium" placeholder={f.placeholder}
 48:                 required={["name", "event", "result"].includes(f.key)}
 49:                 value={compForm[f.key]}
 50:                 onChange={e => setCompForm(p => ({ ...p, [f.key]: e.target.value }))} />
 51:             </div>
 52:           ))}
 53:           {COMBINE_EVENTS[compForm.event] && (
 54:             <div>
 55:               <label style={labelStyle}>
 56:                 Détail par épreuve (optionnel)
 57:               </label>
 58:               <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8 }}>
 59:                 {COMBINE_EVENTS[compForm.event].map(ev => (
