 67:               </div>
 68:             </div>
 69:           )}
 70:           <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
 71:             <div>
 72:               <label htmlFor="comp-date" style={labelStyle}>Date *</label>
 73:               <input id="comp-date" type="date" className="input-premium" required
 74:                 value={compForm.date}
 75:                 onChange={e => setCompForm(p => ({ ...p, date: e.target.value }))} />
 76:             </div>
 77:             <div>
 78:               <label htmlFor="comp-type" style={labelStyle}>Type</label>
 79:               <select id="comp-type" className="input-premium"
 80:                 value={compForm.type}
