 82:                 {["Régionale","Provinciale","Nationale","Internationale","Autre"].map(t => (
 83:                   <option key={t} value={t}>{t}</option>
 84:                 ))}
 85:               </select>
 86:             </div>
 87:           </div>
 88:           <PerformanceMetadataFields
 89:             discipline={compForm.event}
 90:             metadata={compForm.metadata}
 91:             setMetadata={(updater) => setCompForm((current) => ({
 92:               ...current,
 93:               metadata: typeof updater === "function" ? updater(current.metadata) : updater,
 94:             }))}
 95:             idPrefix="comp-meta"
 96:           />
 97:           {error && <p role="alert" className="rounded-xl border px-3 py-2.5 text-[13px]" style={{ color: "var(--color-danger)", borderColor: "rgba(226,75,74,0.28)", background: "rgba(226,75,74,0.08)" }}>{error}</p>}
 98:         </div>
 99:         <div style={{ padding: "12px 20px", borderTop: "1px solid var(--c-border)", display: "flex", gap: 10 }}>
100:           <button type="button" onClick={onClose} className="btn-secondary">Annuler</button>
101:           <button type="submit"
102:             disabled={!compForm.name.trim() || !compForm.event.trim() || !compForm.result.trim() || saving}
103:             className="btn-primary" style={{ flex: 1 }}>
104:             {saving ? <><div className="loader-ring loader-ring-sm" />Enregistrement…</> : <><Plus size={14} />Ajouter</>}
105:           </button>
106:         </div>
107:       </form>
108:     </div>,
109:     document.body
110:   );
