17: export const discColor = (disc) => getDisciplineColor(disc);
18: 
19: // Indice visuel non plafonné : 100 = record de référence, >100 = record
20: // dépassé. Contrairement à pctOfReference(), il doit pouvoir afficher un
21: // objectif au-delà de 100 dans le graphique d'évolution.
22: export function performanceIndex(currentValue, referenceValue, discipline) {
23:   if (currentValue == null || referenceValue == null || currentValue === 0 || referenceValue === 0) return null;
24:   const higherIsBetter = getDisciplineHib(discipline);
25:   if (higherIsBetter == null) return null;
26:   const ratio = higherIsBetter
27:     ? currentValue / referenceValue
28:     : referenceValue / currentValue;
29:   return Math.round(ratio * 1000) / 10;
30: }
