33: // côté coach (Performances.jsx) : ≥97% optimal, ≥90% correct, en-dessous à
34: // travailler.
35: export function recordStatusColor(pct) {
36:   if (pct === null) return null;
37:   if (pct >= 97) return "#1D9E75";
38:   if (pct >= 90) return "#EF9F27";
39:   return "#E24B4A";
