 24:       type="button"
 25:       className={["pwa-install-quick", expanded ? "" : "compact"].join(" ")}
 26:       onClick={handleClick}
 27:       title={canInstall ? "Installer AthleteOS sur cet appareil" : "Afficher les options d’installation"}
 28:       aria-label={expanded ? undefined : "Installer AthleteOS"}
 29:     >
 30:       <Download size={17} aria-hidden="true" />
 31:       {expanded && <span>Installer AthleteOS</span>}
 32:     </button>
 33:   );
 34: }
