 45:       else if (result?.outcome === "dismissed") setFeedback("Installation annulée. Tu peux réessayer quand tu veux.");
 46:       else if (result?.outcome === "unavailable") setFeedback("Ce navigateur ne permet pas de lancer l’installation automatiquement.");
 47:     } catch {
 48:       setFeedback("L’installation n’a pas pu être ouverte. Utilise le menu de ton navigateur.");
