 51: 
 52:   const runShare = async () => {
 53:     setFeedback("");
 54:     try {
 55:       const result = await share();
 56:       if (result === "copied") setFeedback("Le lien AthleteOS a été copié.");
 57:     } catch (error) {
 58:       if (error?.name !== "AbortError") setFeedback("Le partage n’a pas pu être ouvert.");
 59:     }
 60:   };
 61: 
 62:   const runCopy = async () => {
 63:     setFeedback("");
 64:     try {
 65:       await copyLink();
 66:       setFeedback("Le lien AthleteOS a été copié.");
 67:     } catch {
 68:       setFeedback("La copie automatique n’est pas disponible dans ce navigateur.");
 69:     }
 70:   };
 71: 
 72:   let guidance = "Dans le menu de ton navigateur, choisis « Installer AthleteOS » ou « Créer un raccourci » pour l’ajouter au bureau.";
 73:   if (isIos) guidance = "Sur iPhone ou iPad : touche Partager, puis « Sur l’écran d’accueil ».";
 74:   else if (isMobile) guidance = "Dans le menu du navigateur, choisis « Ajouter à l’écran d’accueil » ou « Installer l’application ».";
 75: 
 76:   return (
 77:     <section className="pwa-access-card" aria-labelledby="pwa-access-title">
 78:       <div className="pwa-access-heading">
 79:         <span>{isMobile ? <Smartphone size={19} aria-hidden="true" /> : <MonitorDown size={19} aria-hidden="true" />}</span>
 80:         <div>
 81:           <h3 id="pwa-access-title">AthleteOS sur ton appareil</h3>
 82:           <p>Installe l’application pour l’ouvrir directement depuis ton écran d’accueil ou ton bureau.</p>
 83:         </div>
 84:       </div>
 85: 
 86:       {installed ? (
