 99:       )}
100: 
101:       <div className="pwa-access-actions">
102:         <button type="button" className="btn-secondary" onClick={runShare}>
103:           <Share2 size={16} aria-hidden="true" /> Partager AthleteOS
104:         </button>
105:         <button type="button" className="btn-ghost" onClick={runCopy}>
106:           <Copy size={16} aria-hidden="true" /> Copier le lien
107:         </button>
108:       </div>
109:       {feedback && <p className="pwa-access-feedback" role="status">{feedback}</p>}
110:     </section>
