 36: const AxisRadarCard = memo(({
 37:   profile, title = "Ce que les séances ont surtout sollicité", subtitle = "Lecture descriptive de la dernière semaine connue, basée sur l'objectif déclaré de chaque séance.",
 38:   sessions = null, athleteId = null, currentWeek = null,
 39: }) => {
 40:   const [expanded, setExpanded] = useState(null); // axisId ouvert, ou null
 41:   if (!profile) return null;
 42: 
 43:   const data = AXIS_IDS.map(id => ({
 44:     axis: LOAD_AXES[id].label,
 45:     score: profile[id].score,
 46:     color: profile[id].color,
 47:   }));
 48: 
 49:   return (
 50:     <div className="card p-4">
 51:       <p className="card-title">{title}</p>
 52:       <p className="card-subtitle mb-2">{subtitle}</p>
 53: 
 54:       <ResponsiveContainer width="100%" height={200}>
 55:         <RadarChart data={data} cx="50%" cy="50%" outerRadius="70%">
 56:           <PolarGrid stroke="var(--c-border)" />
 57:           <PolarAngleAxis dataKey="axis" tick={{ fontSize: 12, fill: "var(--c-text-2)", fontWeight: 600 }} />
 58:           <PolarRadiusAxis angle={90} domain={[0, 100]} tick={false} axisLine={false} />
 59:           <Radar
 60:             dataKey="score"
 61:             stroke="rgba(255,255,255,0.30)"
 62:             fill="#1D9E75"
 63:             fillOpacity={0.10}
 64:             strokeWidth={1.5}
 65:             dot={<RadarDot />}
 66:             isAnimationActive={false}
 67:           />
 68:         </RadarChart>
 69:       </ResponsiveContainer>
 70: 
 71:       <div className="space-y-1.5 mt-1">
 72:         {AXIS_IDS.map(id => {
 73:           const axis     = LOAD_AXES[id];
 74:           const p        = profile[id];
 75:           const flagged  = p.label === "Dominant";
 76:           const isOpen   = expanded === id;
 77:           const contributors = isOpen && sessions && athleteId != null && currentWeek != null
 78:             ? getAxisTopContributors(athleteId, sessions, id, currentWeek)
 79:             : [];
 80:           return (
 81:             <div key={id} style={{ borderRadius: 10, background: flagged ? `${p.color}12` : "var(--c-surface-2)", overflow: "hidden" }}>
 82:               <button
 83:                 type="button" onClick={() => setExpanded(isOpen ? null : id)}
 84:                 className="tap-feedback" style={{ width: "100%", padding: "7px 10px", background: "none", border: "none", cursor: "pointer", textAlign: "left" }}
 85:               >
 86:                 <div className="flex items-center gap-2.5">
 87:                   <span style={{ width: 7, height: 7, borderRadius: "50%", background: p.color, flexShrink: 0 }} />
 88:                   <span style={{ fontSize: 13, fontWeight: 600, color: "var(--c-text-1)", flex: 1 }}>{axis.label}</span>
 89:                   <span style={{ fontSize: 12, fontWeight: 700, color: p.color, flexShrink: 0 }}>{p.label}</span>
 90:                 </div>
 91:                 {flagged && (
 92:                   <p style={{ fontSize: 12, color: "var(--c-text-2)", marginTop: 4, marginLeft: 17, lineHeight: 1.5 }}>
 93:                     {axis.what}
 94:                   </p>
 95:                 )}
 96:               </button>
 97: 
 98:               {isOpen && (
 99:                 <div style={{ padding: "2px 10px 12px 17px", fontSize: 12, color: "var(--c-text-2)", lineHeight: 1.6 }}>
100:                   <div className="flex items-center gap-1.5 mb-2">
101:                     <span className="chip chip-warning">Lecture descriptive</span>
102:                     <span>modèle {CURRENT_AXIS_MODEL_VERSION}</span>
103:                   </div>
104:                   <p><strong style={{ color: "var(--c-text-1)" }}>{axis.scientificLabel}</strong> · {axis.what}</p>
105:                   <p>
106:                     Charge de la semaine S{p.currentWeek} : <strong style={{ color: "var(--c-text-2)" }}>{p.currentLoad}</strong>
107:                     {p.habitualLoad != null && <> · Moyenne précédente : <strong style={{ color: "var(--c-text-2)" }}>{p.habitualLoad}</strong></>}
108:                   </p>
109:                   <p style={{ marginTop: 2 }}>
110:                     Historique disponible : <strong style={{ color: "var(--c-text-1)" }}>{p.dataQuality}</strong> ({p.weeksOfData} semaine{p.weeksOfData > 1 ? "s" : ""}). Cette lecture répartit la charge globale pour aider à comprendre le contenu ; ce n'est ni une mesure physiologique directe ni une estimation de risque.
111:                   </p>
112:                   {contributors.length > 0 && (
113:                     <div style={{ marginTop: 6 }}>
114:                       <p style={{ fontWeight: 500, color: "var(--c-text-2)" }}>Séances qui contribuent le plus :</p>
115:                       {contributors.map(c => (
