  2: // AthleteOS — src/context/AuthContext.jsx
  3: //
  4: // Fournit à toute l'app :
  5: //   - user        : objet Supabase Auth (email, id, etc.)
  6: //   - profile     : ligne de la table `users` (name, role, club_id, avatar)
  7: //   - clubId      : raccourci vers profile.club_id (remplace la constante =1)
  8: //   - loading     : true pendant la vérification initiale de session
  9: //   - signIn(email, password) → { error }
 10: //   - signOut()
 11: //
 12: // Pattern :
 13: //   1. Au montage, on écoute onAuthStateChange (Supabase gère le refresh token).
 14: //   2. Quand un user est connecté, on charge son profil depuis la table `users`.
 15: //   3. Tous les modules lisent useAuth() au lieu d'un ID hardcodé.
 16: // ============================================================
 17: 
 18: import { useEffect, useState, useCallback } from "react";
 19: import { supabase } from "../utils/supabaseClient";
 20: import { revokeCurrentPushSubscription } from "../utils/pushSubscriptions";
 21: import { AuthContext } from "./authContextValue";
 22: 
 23: export function AuthProvider({ children }) {
 24:   const [user,    setUser]    = useState(null);   // objet supabase.auth.user
 25:   const [profile, setProfile] = useState(null);   // ligne table users
 26:   const [loading, setLoading] = useState(true);   // vrai jusqu'à la 1ère résolution
 27:   // true entre le moment où on clique le lien "mot de passe oublié" reçu par
 28:   // email et le moment où un nouveau mot de passe est effectivement défini —
 29:   // pendant ce laps de temps il ne faut PAS router vers le dashboard normal.
 30:   const [passwordRecovery, setPasswordRecovery] = useState(false);
 31: 
 32:   // ─── Charge le profil métier depuis la table `users` ─────────────────────────
 33:   // Appelé à chaque changement de session (connexion, refresh, déconnexion).
 34:   const loadProfile = useCallback(async (authUser) => {
 35:     if (!authUser) {
 36:       setProfile(null);
 37:       return;
 38:     }
 39:     try {
 40:       // users.id est l'identifiant métier entier. Le lien avec Supabase Auth
 41:       // passe exclusivement par users.auth_uid = auth.users.id.
 42:       const { data, error } = await supabase
 43:         .from("users")
 44:      .select("id, name, role, club_id")
 45:        .eq("auth_uid", authUser.id)
 46:         .single();
 47: 
 48:       if (error) {
 49:         console.error("AuthContext — profil introuvable :", error.message);
 50:         setProfile(null);
 51:       } else {
 52:         setProfile(data);
 53:       }
 54:     } catch (err) {
 55:       console.error("AuthContext — erreur inattendue :", err);
 56:       setProfile(null);
 57:     }
 58:   }, []);
 59: 
 60:   // ─── Écoute les changements de session Supabase ───────────────────────────────
 61:   useEffect(() => {
 62:     // Vérifie la session existante au montage (page refresh, retour sur l'onglet).
 63:     supabase.auth.getSession().then(async ({ data: { session } }) => {
 64:       const authUser = session?.user ?? null;
 65:       setUser(authUser);
 66:       await loadProfile(authUser);
 67:       setLoading(false);
 68:     });
 69: 
 70:     // Puis écoute les événements suivants :
 71:     // SIGNED_IN, SIGNED_OUT, TOKEN_REFRESHED, USER_UPDATED, PASSWORD_RECOVERY
 72:     const { data: { subscription } } = supabase.auth.onAuthStateChange(
 73:       async (_event, session) => {
 74:         if (_event === "PASSWORD_RECOVERY") setPasswordRecovery(true);
 75:         const authUser = session?.user ?? null;
 76:         setUser(authUser);
 77:         await loadProfile(authUser);
 78:         // loading reste false après la 1ère résolution (géré dans getSession ci-dessus)
 79:       }
 80:     );
 81: 
 82:     // Nettoyage : on se désabonne quand AuthProvider est démonté
 83:     return () => subscription.unsubscribe();
 84:   }, [loadProfile]);
 85: 
 86:   // ─── Actions exposées ─────────────────────────────────────────────────────────
 87: 
 88:   const signIn = useCallback(async (email, password) => {
 89:     const { error } = await supabase.auth.signInWithPassword({ email, password });
 90:     return { error };
 91:   }, []);
 92: 
 93:   const signOut = useCallback(async () => {
 94:     try {
 95:       const result = await revokeCurrentPushSubscription(supabase);
 96:       if (result.databaseError) console.error("Suppression de l’abonnement push :", result.databaseError.message);
 97:     } catch (error) {
 98:       // La déconnexion reste possible même si le navigateur refuse la
 99:       // révocation. L'endpoint sera aussi nettoyé par send-push sur 404/410.
100:       console.error("Révocation de l’abonnement push :", error);
101:     }
102:     const { error } = await supabase.auth.signOut();
103:     if (error) throw error;
104:     // onAuthStateChange va déclencher setUser(null) + setProfile(null) automatiquement
105:   }, []);
106: 
107:   const sendPasswordReset = useCallback(async (email) => {
108:     const { error } = await supabase.auth.resetPasswordForEmail(email, {
109:       redirectTo: window.location.origin,
110:     });
111:     return { error };
112:   }, []);
113: 
114:   const updatePassword = useCallback(async (newPassword) => {
115:     const { error } = await supabase.auth.updateUser({ password: newPassword });
116:     if (!error) setPasswordRecovery(false);
117:     return { error };
118:   }, []);
119: 
120:   // ─── Valeur du contexte ───────────────────────────────────────────────────────
121:   const value = {
122:     user,
123:     profile,
124:     // clubId est le raccourci critique : remplace partout `.eq("club_id", 1)`
125:     clubId: profile?.club_id ?? null,
126:     loading,
127:     passwordRecovery,
128:     signIn,
129:     signOut,
130:     sendPasswordReset,
131:     updatePassword,
132:   };
133: 
134:   return (
135:     <AuthContext.Provider value={value}>
136:       {children}
137:     </AuthContext.Provider>
138:   );
139: } 1: import { computeWellnessScore } from "../utils/trainingLoad";
 2: 
 3: const FACTORS = Object.freeze([
 4:   { key: "sleep", label: "Sommeil", inverted: false, positive: "Ton sommeil t'aide aujourd'hui", attention: "Ton sommeil semble moins bon aujourd'hui" },
 5:   { key: "energy", label: "Énergie", inverted: false, positive: "Tu déclares une bonne énergie", attention: "Tu déclares peu d'énergie" },
 6:   { key: "soreness", label: "Courbatures", inverted: true, positive: "Tu déclares peu de courbatures", attention: "Tes courbatures sont marquées" },
 7:   { key: "mood", label: "Humeur", inverted: false, positive: "Ton humeur est positive", attention: "Ton humeur est plus basse" },
 8:   { key: "stress", label: "Stress", inverted: true, positive: "Tu déclares peu de stress", attention: "Ton stress est marqué" },
 9: ]);
10: 
11: function factorReading(factor, value) {
12:   if (value == null) return { ...factor, value: null, oriented: null, tone: "unknown", meaning: "Non renseigné" };
13:   const oriented = factor.inverted ? 6 - Number(value) : Number(value);
14:   const tone = oriented >= 4 ? "positive" : oriented <= 2 ? "attention" : "neutral";
15:   const meaning = tone === "positive"
16:     ? factor.positive
17:     : tone === "attention"
18:       ? factor.attention
19:       : "Ta réponse est au milieu de l'échelle";
20:   return { ...factor, value: Number(value), oriented, tone, meaning };
21: }
22: 
23: export function buildDailyState({ wellness, history = [], metrics = {} }) {
24:   const score = computeWellnessScore(wellness);
25:   const factors = FACTORS.map(factor => factorReading(factor, wellness?.[factor.key]));
26:   const pastScores = history
27:     .filter(row => row && row.date !== wellness?.date)
28:     .map(computeWellnessScore)
29:     .filter(value => value != null);
30:   const baseline = pastScores.length >= 3
31:     ? Math.round(pastScores.reduce((sum, value) => sum + value, 0) / pastScores.length)
32:     : null;
33:   const delta = score != null && baseline != null ? score - baseline : null;
34:   const rawVariation = metrics.variationPercent ?? metrics.variation;
35:   const variation = rawVariation == null
36:     ? null
37:     : Number.isFinite(Number(rawVariation)) ? Number(rawVariation) : null;
38: 
39:   if (score == null) return {
40:     score: null, label: "Comment te sens-tu aujourd'hui ?", legacyLabel: "Ton check-in manque", color: "#8A9B90", tone: "unknown",
41:     summary: "Réponds aux cinq questions pour donner à ton coach une image simple de ton ressenti.",
42:     plainHeadline: "Ton ressenti n'est pas encore renseigné",
43:     plainSummary: "Cinq réponses suffisent pour voir ce qui t'aide et ce qui mérite une discussion.",
44:     helps: [], watch: [], coachPrompt: "Complète ton check-in avant la séance si tu le peux.",
45:     factors, baseline, delta, variation, known: factors.filter(item => item.value != null).length,
46:   };
47: 
48:   let descriptor = score >= 75
49:     ? { label: "De bonnes ressources aujourd'hui", legacyLabel: "Plutôt favorable", color: "var(--tone-success)", tone: "positive" }
50:     : score >= 55
51:       ? { label: baseline == null ? "Un état globalement équilibré" : "Un état proche de tes habitudes", legacyLabel: baseline == null ? "Ressenti plutôt équilibré" : "Dans tes habitudes", color: "var(--tone-info)", tone: "neutral" }
52:       : score >= 35
53:         ? { label: "Quelques points à adapter", legacyLabel: "À adapter aujourd'hui", color: "var(--tone-warning)", tone: "attention" }
54:         : { label: "Une journée à aborder avec prudence", legacyLabel: "Journée exigeante", color: "var(--tone-danger)", tone: "attention" };
55:   if (baseline != null && score >= 55 && score < 75 && delta >= 12) descriptor = { label: "Tu te sens mieux que d'habitude", legacyLabel: "Mieux que ton habitude", color: "var(--tone-success)", tone: "positive" };
56:   if (baseline != null && score >= 55 && score < 75 && delta <= -12) descriptor = { label: "Tu te sens moins bien que d'habitude", legacyLabel: "En dessous de ton habitude", color: "var(--tone-warning)", tone: "attention" };
57:   const attention = factors.filter(item => item.tone === "attention");
58:   const positive = factors.filter(item => item.tone === "positive");
59:   const helps = positive.map(item => item.meaning);
60:   const watch = attention.map(item => item.meaning);
61:   let summary = attention.length
62:     ? `${attention.slice(0, 2).map(item => item.label).join(" et ")} mérite${attention.length > 1 ? "nt" : ""} une attention particulière.`
63:     : "Aucun des cinq ressentis déclarés ne ressort comme un point d'attention marqué.";
64:   if (positive.length) summary = `${positive.slice(0, 2).map(item => item.label).join(" et ")} ${positive.length > 1 ? "sont" : "est"} plutôt favorable${positive.length > 1 ? "s" : ""}. ${summary}`;
65:   const loadContext = variation == null
66:     ? "Ta charge récente reste affichée séparément dès que suffisamment de séances sont renseignées."
67:     : variation > 20
68:       ? "Ta charge récente est plus élevée que ton rythme habituel."
69:       : variation < -20
70:         ? "Ta charge récente est plus basse que ton rythme habituel."
71:         : "Ta charge récente est proche de ton rythme habituel.";
72:   const coachPrompt = attention.length
73:     ? `Parle à ton coach de ${attention.slice(0, 2).map(item => item.label.toLowerCase()).join(" et ")} avant d'adapter la séance.`
74:     : "Si ton ressenti change pendant l'échauffement, signale-le simplement à ton coach.";
75: 
76:   return {
77:     ...descriptor, score, summary, plainHeadline: descriptor.label,
78:     plainSummary: summary, loadContext, helps, watch, coachPrompt,
79:     factors, baseline, delta, variation, known: 5,
80:   };
81: }
