83: export function buildGroupDailyState(athletes, wellnessRows, metricsByAthlete = new Map()) {
84:   const states = athletes.map(athlete => ({
85:     athlete,
86:     state: buildDailyState({ wellness: wellnessRows.find(row => row.athleteId === athlete.id), metrics: metricsByAthlete.get(athlete.id) ?? {} }),
87:   }));
88:   const completed = states.filter(item => item.state.score != null);
89:   return {
90:     states,
91:     completed: completed.length,
92:     favorable: completed.filter(item => item.state.tone === "positive").length,
93:     attention: completed.filter(item => item.state.tone === "attention").length,
94:     average: completed.length ? Math.round(completed.reduce((sum, item) => sum + item.state.score, 0) / completed.length) : null,
95:   };
