117: // Contexte technique nécessaire à l'interprétation d'un résultat. Ces
118: // champs décrivent les conditions ; ils ne valident jamais seuls une perf.
119: const WIND_EVENTS = new Set(["100m", "200m", "60m haies", "100m haies", "110m haies", "Longueur", "Triple saut"]);
120: const HURDLE_EVENTS = new Set(["60m haies", "100m haies", "110m haies", "400m haies"]);
121: const THROW_EVENTS = new Set(["Poids", "Disque", "Javelot", "Marteau"]);
122: 
123: for (const [id, discipline] of Object.entries(DISCIPLINES)) {
124:   discipline.performanceDirection = discipline.higherIsBetter
125:     ? PERFORMANCE_DIRECTION.HIGHER
126:     : PERFORMANCE_DIRECTION.LOWER;
127:   discipline.windMeasurement = WIND_EVENTS.has(id) ? "required_for_official_review" : "not_applicable";
128:   discipline.requiresHurdleHeight = HURDLE_EVENTS.has(id);
129:   discipline.requiresImplementWeight = THROW_EVENTS.has(id);
130:   discipline.scoringTableVersion ??= SCORING_TABLE_VERSIONS.GENERAL;
131:   discipline.catalogVersion = PERFORMANCE_METADATA_VERSION;
132: }
