144: // Discipline personnalisée / inconnue (nom tapé librement par un coach ou
145: // un athlète, jamais ajouté au registre officiel) : ne doit JAMAIS faire
146: // planter l'app. Ces valeurs par défaut reproduisent exactement le
147: // comportement déjà en place avant cette tâche (getDiscType -> "sprint",
148: // getDiscHib -> false), pour ne rien changer au jugement porté sur les
149: // disciplines déjà utilisées en pratique par les clubs.
150: const UNKNOWN_DISCIPLINE_DEFAULTS = {
151:   type: "custom", measurementType: MEASUREMENT_TYPE.UNKNOWN, unit: null,
152:   higherIsBetter: null, performanceDirection: PERFORMANCE_DIRECTION.UNKNOWN,
153:   decimals: 2, inputFormat: INPUT_FORMAT.METERS,
154:   environments: [VENUE_TYPE.UNKNOWN], timingMethods: [TIMING_METHOD.UNKNOWN],
155:   windMeasurement: "unknown", requiresHurdleHeight: false,
156:   requiresImplementWeight: false, scoringTableVersion: null,
157:   catalogVersion: PERFORMANCE_METADATA_VERSION,
158: };
