160: function normalizeKey(s) {
161:   return s.toString().trim().toLowerCase().replace(/\s+/g, " ");
162: }
163: 
164: // ─── Index des alias (construit une fois, au chargement du module) ────────
165: // Toute collision (deux disciplines revendiquant la même clé normalisée)
166: // est enregistrée plutôt qu'écrasée silencieusement — voir
167: // validateRegistry() plus bas, qui l'expose pour être testée.
168: const ALIAS_INDEX = new Map();
169: const ALIAS_COLLISIONS = [];
170: for (const [id, disc] of Object.entries(DISCIPLINES)) {
171:   const keys = [id, ...(disc.aliases ?? [])];
172:   for (const key of keys) {
173:     const norm = normalizeKey(key);
174:     if (ALIAS_INDEX.has(norm) && ALIAS_INDEX.get(norm) !== id) {
175:       ALIAS_COLLISIONS.push({ key: norm, claimedBy: [ALIAS_INDEX.get(norm), id] });
176:       continue; // garde le premier mapping, ne pas écraser silencieusement
177:     }
178:     ALIAS_INDEX.set(norm, id);
179:   }
180: }
181: 
182: // Résout un texte saisi (identifiant officiel, alias connu, ou simple
183: // variation d'espacement/casse — "100 m" / "100M" / " 100m ") vers
184: // l'identifiant canonique. Une discipline personnalisée qui ne correspond
185: // à rien de connu est renvoyée telle quelle (trim uniquement) : le
186: // registre officiel n'est jamais "cassé" ni pollué par une saisie libre.
187: export function resolveDisciplineId(rawText) {
188:   if (rawText == null) return rawText;
189:   const trimmed = rawText.toString().trim();
190:   if (!trimmed) return trimmed;
191:   return ALIAS_INDEX.get(normalizeKey(trimmed)) ?? trimmed;
192: }
193: 
194: // Fiche complète d'une discipline (résout les alias), ou null si inconnue.
195: export function getDiscipline(rawText) {
196:   if (!rawText) return null;
197:   const id = resolveDisciplineId(rawText);
198:   return DISCIPLINES[id] ?? null;
199: }
