234: // Sous-épreuves d'une combinée (Décathlon/Heptathlon), ou null pour toute
235: // autre discipline (y compris personnalisée).
236: export function getDisciplineSubEvents(rawText) {
237:   return getDiscipline(rawText)?.subEvents ?? null;
