244: export function createPerformanceMetadata(rawText, overrides = {}) {
245:   const discipline = getDiscipline(rawText) ?? UNKNOWN_DISCIPLINE_DEFAULTS;
246:   return {
247:     measurement_type: discipline.measurementType,
248:     performance_direction: discipline.performanceDirection,
249:     unit: discipline.unit,
250:     venue_type: VENUE_TYPE.UNKNOWN,
251:     wind_mps: null,
252:     timing_method: discipline.measurementType === MEASUREMENT_TYPE.TIME
253:       ? TIMING_METHOD.UNKNOWN
254:       : TIMING_METHOD.NOT_APPLICABLE,
255:     implement_weight_kg: null,
256:     hurdle_height_m: null,
257:     official_status: OFFICIAL_STATUS.UNKNOWN,
258:     scoring_table_version: discipline.scoringTableVersion,
259:     metadata_version: PERFORMANCE_METADATA_VERSION,
260:     ...overrides,
261:   };
262: }
263: 
264: export function normalizePerformanceMetadata(rawText, metadata = {}) {
265:   const discipline = getDiscipline(rawText);
266:   const defaults = createPerformanceMetadata(rawText);
267:   const merged = { ...defaults, ...metadata };
268:   if (discipline) {
269:     merged.measurement_type = defaults.measurement_type;
270:     merged.performance_direction = defaults.performance_direction;
271:     merged.unit = defaults.unit;
272:     merged.scoring_table_version = defaults.scoring_table_version;
273:     merged.metadata_version = defaults.metadata_version;
274:   }
275:   const numberOrNull = (value) => value === "" || value == null ? null : Number(value);
276:   return {
277:     ...merged,
278:     wind_mps: numberOrNull(merged.wind_mps),
279:     implement_weight_kg: numberOrNull(merged.implement_weight_kg),
280:     hurdle_height_m: numberOrNull(merged.hurdle_height_m),
281:   };
282: }
283: 
284: export function validatePerformanceMetadata(rawText, metadata = {}) {
285:   const discipline = getDiscipline(rawText);
286:   const normalized = normalizePerformanceMetadata(rawText, metadata);
287:   const issues = [];
288:   if (!discipline && ![PERFORMANCE_DIRECTION.HIGHER, PERFORMANCE_DIRECTION.LOWER].includes(normalized.performance_direction)) {
289:     issues.push("Indique si une valeur plus haute ou plus basse est meilleure.");
290:   }
291:   if (!discipline && ![MEASUREMENT_TYPE.TIME, MEASUREMENT_TYPE.DISTANCE, MEASUREMENT_TYPE.POINTS].includes(normalized.measurement_type)) {
292:     issues.push("Indique le type de mesure de cette épreuve personnalisée.");
293:   }
294:   if (!discipline && !normalized.unit?.trim()) issues.push("Indique l'unité de cette épreuve personnalisée.");
295:   if (!Object.values(VENUE_TYPE).includes(normalized.venue_type)) issues.push("Environnement invalide.");
296:   if (!Object.values(OFFICIAL_STATUS).includes(normalized.official_status)) issues.push("Statut officiel invalide.");
297:   if (normalized.wind_mps != null && !Number.isFinite(normalized.wind_mps)) issues.push("Vent invalide.");
298:   if (normalized.implement_weight_kg != null && !(normalized.implement_weight_kg > 0)) issues.push("Poids de l'engin invalide.");
299:   if (normalized.hurdle_height_m != null && !(normalized.hurdle_height_m > 0)) issues.push("Hauteur des haies invalide.");
300:   return issues;
301: }
