303: // { "Décathlon": [...], "Heptathlon": [...] } — forme objet pratique pour
304: // un lookup direct `COMBINE_EVENTS[disc]` (compat perfsShared.js).
305: export const COMBINE_EVENTS = Object.fromEntries(
306:   Object.entries(DISCIPLINES).filter(([, d]) => d.subEvents).map(([id, d]) => [id, d.subEvents])
307: );
