309: const REQUIRED_FIELDS = ["label", "type", "measurementType", "unit", "higherIsBetter", "performanceDirection", "decimals", "inputFormat", "color", "environments", "timingMethods", "windMeasurement", "requiresImplementWeight", "requiresHurdleHeight", "scoringTableVersion", "catalogVersion"];
