311: // Auto-vérification du registre — utilisée par test_discipline_registry.mjs,
312: // mais exportée (pas juste un script ponctuel) pour pouvoir être rappelée
313: // si le registre grossit plus tard. Ne lève jamais d'exception : renvoie
314: // la liste des problèmes trouvés, vide si tout est cohérent.
315: export function validateRegistry() {
316:   const issues = [];
317: 
318:   for (const collision of ALIAS_COLLISIONS) {
319:     issues.push(`Alias "${collision.key}" revendiqué par plusieurs disciplines : ${collision.claimedBy.join(", ")}`);
320:   }
321: 
322:   for (const [id, disc] of Object.entries(DISCIPLINES)) {
323:     for (const field of REQUIRED_FIELDS) {
324:       if (disc[field] === undefined) issues.push(`${id} : champ obligatoire manquant "${field}"`);
325:     }
326:     if (disc.subEvents) {
327:       for (const sub of disc.subEvents) {
328:         if (!DISCIPLINES[sub]) issues.push(`${id} : sous-épreuve "${sub}" ne correspond à aucune discipline du registre`);
329:       }
330:     }
331:   }
332: 
333:   return issues;
334: }  1: // ============================================================
