  2: // AthleteOS — src/modules/Alerts.jsx
  3: // Version nettoyée Phase 2 :
  4: // - Utilise <LoadingState> et <ErrorState> (fini les blocs dupliqués)
  5: // - Utilise <Modal> générique pour la création d'alerte
