 10: import { memo, useState, useMemo, useEffect, useCallback } from "react";
 11: import {
 12:   Bell, Activity, AlertTriangle, Users,
 13:   TrendingUp, CheckCheck, Filter, Plus, Trash2, Trophy, BarChart2,
 14: } from "lucide-react";
 15: import { supabase }    from "../utils/supabaseClient";
 16: import { useAuth }     from "../hooks/useAuth";
 17: import LoadingState    from "../components/ui/LoadingState";
 18: import ErrorState      from "../components/ui/ErrorState";
 19: import Modal           from "../components/ui/Modal";
 20: import { initialsFromName } from "../utils/helpers.js";
 21: 
 22: // ─── Config UI statique ───────────────────────────────────────────────────────
 23: 
 24: // Les clés doivent correspondre exactement aux valeurs `type` écrites en base
 25: // (voir src/utils/notifications.js) : "charge" pour surcharge/sous-charge ACWR,
 26: // pas "surcharge" — sinon l'alerte tombe dans le fallback gris sans couleur.
 27: const TYPE_CONFIG = {
 28:   charge:      { label: "Charge",      icon: Activity,      color: "var(--tone-danger)", bg: "rgba(226,75,74,0.15)" },
 29:   blessure:    { label: "Blessure",    icon: AlertTriangle, color: "#EF9F27", bg: "rgba(239,159,39,0.15)" },
 30:   absence:     { label: "Absence",     icon: Users,         color: "#378ADD", bg: "rgba(55,138,221,0.15)" },
 31:   performance: { label: "Performance", icon: TrendingUp,    color: "#1D9E75", bg: "rgba(29,158,117,0.15)" },
 32:   competition: { label: "Compétition", icon: Trophy,        color: "var(--tone-mental)", bg: "rgba(155,132,240,0.15)" },
 33:   recap:       { label: "Récap semaine", icon: BarChart2,   color: "#5B8DEF", bg: "rgba(91,141,239,0.15)" },
 34:   session_response: { label: "Réponse séance", icon: Users, color: "#EF9F27", bg: "rgba(239,159,39,0.15)" },
 35:   athlete_session: { label: "Séance athlète", icon: Activity, color: "#378ADD", bg: "rgba(55,138,221,0.15)" },
 36:   social_post: { label: "Vie du club", icon: Users, color: "var(--tone-mental)", bg: "rgba(155,132,240,0.15)" },
 37: };
 38: 
 39: const SEVERITY_CONFIG = {
 40:   critique: { cls: "bg-[rgba(224,82,82,0.15)] text-[#E05252]",     label: "Critique" },
 41:   modérée:  { cls: "bg-[rgba(232,160,32,0.15)] text-[#E8A020]",    label: "Modérée"  },
 42:   légère:   { cls: "bg-[rgba(255,255,255,0.08)] text-[var(--c-text-2)]", label: "Légère" },
 43:   info:     { cls: "bg-[rgba(91,141,239,0.15)] text-[#5B8DEF]",    label: "Info"     },
 44: };
 45: 
 46: const EMPTY_FORM = {
 47:   type: "charge", athleteId: "", title: "", description: "", severity: "modérée",
 48: };
 49: 
 50: const inputCls = "w-full border border-[var(--c-border-strong)] rounded-lg px-3 py-2 text-[13px] text-[var(--c-text-1)] focus:outline-none focus:ring-2 focus:ring-emerald-400 bg-[var(--c-surface-2)]";
 51: const labelCls = "block text-[11px] font-semibold text-[var(--c-text-3)] uppercase tracking-wider mb-1";
 52: 
 53: function formatDate(dateStr) {
 54:   if (!dateStr) return "—";
 55:   return new Date(dateStr).toLocaleDateString("fr-BE", {
 56:     weekday: "long", day: "numeric", month: "long",
 57:   });
 58: }
 59: 
 60: // ─── Contenu du formulaire de création (utilisé dans <Modal>) ────────────────
 61: const AlertFormContent = memo(({ form, set, athletes, saveError }) => (
 62:   <div className="space-y-4">
 63:     {saveError && (
 64:       <div className="bg-[rgba(224,82,82,0.12)] border border-[rgba(224,82,82,0.25)] rounded-lg px-3 py-2.5 text-[12px] text-[#F19A9A]">
 65:         {saveError}
 66:       </div>
 67:     )}
 68: 
 69:     <div>
 70:       <label className={labelCls}>Type d'alerte</label>
 71:       <select className={inputCls} value={form.type} onChange={(e) => set("type", e.target.value)}>
 72:         {Object.entries(TYPE_CONFIG).map(([key, c]) => (
 73:           <option key={key} value={key}>{c.label}</option>
 74:         ))}
 75:       </select>
 76:     </div>
 77: 
 78:     <div>
 79:       <label className={labelCls}>Athlète concerné</label>
 80:       <select className={inputCls} value={form.athleteId} onChange={(e) => set("athleteId", e.target.value)}>
 81:         <option value="">Aucun athlète spécifique</option>
 82:         {athletes.map((a) => (
 83:           <option key={a.id} value={a.id}>{a.name}</option>
 84:         ))}
 85:       </select>
 86:     </div>
 87: 
 88:     <div>
 89:       <label className={labelCls}>Titre *</label>
 90:       <input
 91:         className={inputCls}
 92:         placeholder="Ex: Douleur signalée à l'entraînement"
 93:         value={form.title}
 94:         onChange={(e) => set("title", e.target.value)}
 95:       />
 96:     </div>
 97: 
 98:     <div>
 99:       <label className={labelCls}>Description</label>
100:       <textarea
101:         className={`${inputCls} resize-none`}
102:         rows={3}
103:         placeholder="Détails de la situation…"
104:         value={form.description}
105:         onChange={(e) => set("description", e.target.value)}
106:       />
107:     </div>
108: 
109:     <div>
110:       <label className={labelCls}>Gravité</label>
111:       <div className="flex gap-2">
112:         {Object.entries(SEVERITY_CONFIG).map(([key, c]) => (
113:           <button
114:             key={key}
115:             type="button"
116:             onClick={() => set("severity", key)}
117:             className={[
118:               "flex-1 px-2 py-1.5 rounded-lg text-[12px] font-semibold transition-all border",
119:               form.severity === key
120:                 ? "border-[var(--c-accent)] bg-[var(--c-accent)] text-white"
121:                 : "border-[var(--c-border)] text-[var(--c-text-2)] hover:border-[var(--c-border-strong)]",
122:             ].join(" ")}
123:           >
124:             {c.label}
125:           </button>
126:         ))}
127:       </div>
128:     </div>
129:   </div>
130: ));
