132: // ─── Composant principal ──────────────────────────────────────────────────────
133: function Alerts({ onNavigate }) {
134:   const { clubId } = useAuth(); // remplace club_id: 1
135: 
136:   const [alertList, setAlertList] = useState([]);
137:   const [athletes,  setAthletes]  = useState([]);
138:   const [loading,   setLoading]   = useState(true);
139:   const [error,     setError]     = useState(null);
140: 
141:   const [filterType,    setFilterType]    = useState("tous");
142:   const [filterRead,    setFilterRead]    = useState("tous");
143:   const [filterAthlete, setFilterAthlete] = useState("tous");
144:   const [showCreateModal, setShowCreateModal] = useState(false);
145: 
146:   // État du formulaire de création
147:   const [form,      setForm]      = useState(EMPTY_FORM);
148:   const [saving,    setSaving]    = useState(false);
149:   const [saveError, setSaveError] = useState(null);
150:   const set = useCallback((key, val) => setForm((f) => ({ ...f, [key]: val })), []);
151: 
152:   // ═══ Chargement ═══════════════════════════════════════════════════════════
153:   const fetchAll = useCallback(async (silent = false) => {
154:     if (!clubId) return;
155:     try {
156:       if (!silent) setLoading(true);
157:       setError(null);
158: 
159:       const [alertsRes, athletesRes] = await Promise.all([
160:         supabase.from("alerts").select("*").eq("club_id", clubId).order("created_at", { ascending: false }),
161:         supabase.from("athletes").select("id, name, profile_data").eq("club_id", clubId),
162:       ]);
163:       if (alertsRes.error)   throw alertsRes.error;
164:       if (athletesRes.error) throw athletesRes.error;
165: 
166:       setAlertList(alertsRes.data.map((a) => ({
167:         id:          a.id,
168:         type:        a.type,
169:         athleteId:   a.athlete_id,
170:         title:       a.title,
171:         description: a.description,
172:         severity:    a.severity,
173:         isRead:      a.is_read,
174:         date:        a.created_at,
175:       })));
176: 
177:       setAthletes(athletesRes.data.map((a) => ({
178:         id:     a.id,
179:         name:   a.name,
180:         avatar: a.profile_data?.avatar ?? initialsFromName(a.name),
181:       })));
182:     } catch (err) {
183:       console.error("Alerts — chargement :", err);
184:       setError(err.message ?? "Erreur inconnue");
185:     } finally {
186:       if (!silent) setLoading(false);
187:     }
188:   }, [clubId]);
189: 
190:   useEffect(() => { fetchAll(); }, [fetchAll]);
191: 
192:   useEffect(() => {
193:     if (!clubId) return undefined;
194:     const channel = supabase
195:       .channel(`coach-alert-list-${clubId}`)
196:       .on("postgres_changes", {
197:         event: "*", schema: "public", table: "alerts", filter: `club_id=eq.${clubId}`,
198:       }, () => { fetchAll(true); })
199:       .subscribe();
200:     return () => { supabase.removeChannel(channel); };
201:   }, [clubId, fetchAll]);
202: 
203:   // ═══ Écritures ════════════════════════════════════════════════════════════
204: 
205:   const markRead = async (id) => {
206:     // Mise à jour optimiste
207:     setAlertList((prev) => prev.map((a) => (a.id === id ? { ...a, isRead: true } : a)));
208:     const { error: err } = await supabase.from("alerts").update({ is_read: true }).eq("id", id);
209:     if (err) {
210:       console.error("Alerts — markRead :", err);
211:       setAlertList((prev) => prev.map((a) => (a.id === id ? { ...a, isRead: false } : a)));
212:     }
213:   };
214: 
215:   const markAllRead = async () => {
216:     const unreadIds = alertList.filter((a) => !a.isRead).map((a) => a.id);
217:     if (unreadIds.length === 0) return;
218:     setAlertList((prev) => prev.map((a) => ({ ...a, isRead: true })));
219:     const { error: err } = await supabase.from("alerts").update({ is_read: true }).in("id", unreadIds);
220:     if (err) { console.error("Alerts — markAllRead :", err); fetchAll(); }
221:   };
222: 
223:   const deleteAlert = async (id) => {
224:     const previous = alertList;
225:     setAlertList((prev) => prev.filter((a) => a.id !== id));
226:     const { error: err } = await supabase.from("alerts").delete().eq("id", id);
227:     if (err) { console.error("Alerts — delete :", err); setAlertList(previous); }
228:   };
229: 
230:   const handleCreate = async () => {
231:     if (!form.title.trim()) return;
232:     setSaving(true);
233:     setSaveError(null);
234:     try {
235:       const { data, error: insertError } = await supabase
236:         .from("alerts")
237:         .insert({
238:           club_id:     clubId,
239:           athlete_id:  form.athleteId ? Number(form.athleteId) : null,
240:           type:        form.type,
241:           title:       form.title,
242:           description: form.description || null,
243:           severity:    form.severity,
244:           is_read:     false,
245:         })
246:         .select()
247:         .single();
248:       if (insertError) throw insertError;
249: 
250:       setAlertList((prev) => [{
251:         id:          data.id,
252:         type:        data.type,
253:         athleteId:   data.athlete_id,
254:         title:       data.title,
255:         description: data.description,
256:         severity:    data.severity,
257:         isRead:      data.is_read,
258:         date:        data.created_at,
259:       }, ...prev]);
260: 
261:       setForm(EMPTY_FORM);
262:       setShowCreateModal(false);
263:     } catch (err) {
264:       setSaveError(err.message ?? "Erreur lors de la création");
265:     } finally {
266:       setSaving(false);
267:     }
268:   };
269: 
270:   // ═══ Filtrage ═════════════════════════════════════════════════════════════
271:   const filtered = useMemo(() => alertList
272:     .filter((a) => filterType === "tous" || a.type === filterType)
273:     .filter((a) => {
274:       if (filterRead === "lues")     return  a.isRead;
275:       if (filterRead === "non_lues") return !a.isRead;
276:       return true;
277:     })
278:     .filter((a) => filterAthlete === "tous" || String(a.athleteId) === filterAthlete)
279:     .sort((a, b) => new Date(b.date) - new Date(a.date)),
280:   [alertList, filterType, filterRead, filterAthlete]);
281: 
282:   const unreadCount = alertList.filter((a) => !a.isRead).length;
283: 
284:   // ═══ Render ═══════════════════════════════════════════════════════════════
285:   if (loading) return <LoadingState message="Chargement des alertes…" />;
286:   if (error)   return <ErrorState  message={error} onRetry={fetchAll} />;
287: 
288:   return (
289:     <div className="p-6 max-w-4xl mx-auto space-y-5">
290: 
291:       {/* ── En-tête ──────────────────────────────────────────────────────── */}
292:       <div className="flex items-center justify-between flex-wrap gap-3">
293:         <div>
294:           <h2 className="text-[22px] font-bold text-[var(--c-text-1)] tracking-tight">Alertes</h2>
295:           <p className="text-[13px] text-[var(--c-text-3)] mt-0.5">
296:             {unreadCount > 0
297:               ? `${unreadCount} alerte${unreadCount > 1 ? "s" : ""} non lue${unreadCount > 1 ? "s" : ""}`
298:               : "Tout est à jour"}
299:           </p>
300:         </div>
301:         <div className="flex items-center gap-2">
302:           {unreadCount > 0 && (
303:             <button
304:               onClick={markAllRead}
305:               className="flex items-center gap-1.5 text-[12px] font-medium text-[#4DC9A0] hover:text-white border border-[rgba(29,158,117,0.3)] bg-[var(--c-accent-light)] px-3 py-1.5 rounded-lg transition-colors"
306:             >
307:               <CheckCheck size={14} />
308:               Tout marquer comme lu
309:             </button>
310:           )}
311:           <button
312:             onClick={() => { setForm(EMPTY_FORM); setSaveError(null); setShowCreateModal(true); }}
313:             className="flex items-center gap-1.5 text-[12px] font-semibold text-white px-3 py-1.5 rounded-lg transition-colors shadow-sm hover:shadow-md"
314:             style={{ background: "#1D9E75" }}
315:           >
316:             <Plus size={14} />
317:             Créer une alerte
318:           </button>
319:         </div>
320:       </div>
321: 
322:       {/* ── Filtres ──────────────────────────────────────────────────────── */}
323:       <div className="card p-4 space-y-3">
324:         <div className="flex items-center gap-2 flex-wrap">
325:           <Filter size={13} className="text-[var(--c-text-3)]" />
326:           <span className="text-[12px] font-semibold text-[var(--c-text-3)] uppercase tracking-wider mr-2">Type</span>
327:           {["tous", "charge", "blessure", "absence", "performance", "competition", "recap"].map((t) => (
328:             <button
329:               key={t}
330:               onClick={() => setFilterType(t)}
331:               className={[
332:                 "px-3 py-1 rounded-full text-[12px] font-medium transition-all",
333:                 filterType === t ? "bg-[var(--c-accent)] text-white" : "bg-[var(--c-surface-2)] text-[var(--c-text-2)] hover:bg-[var(--c-surface-3)]",
334:               ].join(" ")}
335:             >
336:               {t === "tous" ? "Tous" : TYPE_CONFIG[t]?.label ?? t}
337:             </button>
338:           ))}
339: 
340:           <div className="w-px h-5 bg-[var(--c-border-strong)] mx-1" />
341: 
342:           <span className="text-[12px] font-semibold text-[var(--c-text-3)] uppercase tracking-wider mr-2">Statut</span>
343:           {[{ id: "tous", label: "Tous" }, { id: "non_lues", label: "Non lues" }, { id: "lues", label: "Lues" }].map((f) => (
344:             <button
345:               key={f.id}
346:               onClick={() => setFilterRead(f.id)}
347:               className={[
348:                 "px-3 py-1 rounded-full text-[12px] font-medium transition-all",
349:                 filterRead === f.id ? "bg-[var(--c-accent)] text-white" : "bg-[var(--c-surface-2)] text-[var(--c-text-2)] hover:bg-[var(--c-surface-3)]",
350:               ].join(" ")}
351:             >
352:               {f.label}
353:             </button>
354:           ))}
355:         </div>
356: 
357:         {athletes.length > 0 && (
358:           <div className="flex items-center gap-2 flex-wrap pt-2 border-t border-[var(--c-border)]">
359:             <span className="text-[12px] font-semibold text-[var(--c-text-3)] uppercase tracking-wider mr-2">Athlète</span>
360:             <select
361:               value={filterAthlete}
362:               onChange={(e) => setFilterAthlete(e.target.value)}
363:               className="text-[12px] font-medium bg-[var(--c-surface-2)] text-[var(--c-text-2)] rounded-full px-3 py-1 border-none focus:outline-none focus:ring-2 focus:ring-emerald-400"
364:             >
365:               <option value="tous">Tous les athlètes</option>
366:               {athletes.map((a) => (
367:                 <option key={a.id} value={String(a.id)}>{a.name}</option>
368:               ))}
369:             </select>
370:           </div>
371:         )}
372:       </div>
373: 
374:       {/* ── Liste des alertes ────────────────────────────────────────────── */}
375:       {filtered.length === 0 ? (
376:         <div className="card p-12 flex flex-col items-center gap-3 text-[var(--c-text-3)]">
377:           <Bell size={32} strokeWidth={1.5} />
378:           <p className="text-[14px] font-medium">
379:             {alertList.length === 0 ? "Aucune alerte pour l'instant" : "Aucune alerte pour ce filtre"}
380:           </p>
381:           {alertList.length === 0 && (
382:             <p className="text-[12px] text-[var(--c-text-4)] text-center max-w-xs">
383:               Les alertes automatiques apparaîtront ici, ou crée-en une manuellement.
384:             </p>
385:           )}
386:         </div>
387:       ) : (
388:         <div className="space-y-3">
389:           {filtered.map((alert) => {
390:             const typeConf = TYPE_CONFIG[alert.type] ?? { label: alert.type, icon: Bell, color: "var(--c-text-3)", bg: "var(--c-surface-3)" };
391:             const Icon     = typeConf.icon;
392:             const sevConf  = SEVERITY_CONFIG[alert.severity] ?? SEVERITY_CONFIG.légère;
393:             const athlete  = athletes.find((a) => a.id === alert.athleteId);
394: 
395:             return (
396:               <div
397:                 key={alert.id}
398:                 className={[
399:                   "card transition-all overflow-hidden group",
400:                   alert.isRead ? "" : "border-l-4",
401:                 ].join(" ")}
402:                 style={!alert.isRead ? { borderLeftColor: typeConf.color } : {}}
403:               >
404:                 <div className="p-5 flex items-start gap-4">
405:                   <div
406:                     className="w-10 h-10 rounded-xl flex items-center justify-center flex-shrink-0"
407:                     style={{ background: typeConf.bg }}
408:                   >
409:                     <Icon size={18} color={typeConf.color} strokeWidth={2} />
410:                   </div>
411: 
412:                   <div className="flex-1 min-w-0">
413:                     <div className="flex items-start justify-between gap-2 flex-wrap">
414:                       <div className="flex items-center gap-2 flex-wrap">
415:                         <h4 className="text-[14px] font-semibold text-[var(--c-text-1)]">{alert.title}</h4>
416:                         {!alert.isRead && (
417:                           <span className="w-2 h-2 rounded-full flex-shrink-0" style={{ background: typeConf.color }} />
418:                         )}
419:                         <span className={`text-[10px] font-semibold px-2 py-0.5 rounded-full ${sevConf.cls}`}>
420:                           {sevConf.label}
421:                         </span>
422:                       </div>
423: 
424:                       <div className="flex items-center gap-3 flex-shrink-0">
425:                         {!alert.isRead && (
426:                           <button
427:                             onClick={() => markRead(alert.id)}
428:                             className="text-[11px] text-[var(--c-text-3)] hover:text-emerald-600 flex items-center gap-1 transition-colors"
429:                           >
430:                             <CheckCheck size={13} />
431:                             Marquer lu
432:                           </button>
433:                         )}
434:                         <button
435:                           onClick={() => deleteAlert(alert.id)}
436:                           className="text-[var(--c-text-4)] hover:text-[#E05252] transition-colors opacity-0 group-hover:opacity-100"
437:                           title="Supprimer l'alerte"
438:                         >
439:                           <Trash2 size={14} />
440:                         </button>
441:                       </div>
442:                     </div>
443: 
444:                     <p className="text-[12.5px] text-[var(--c-text-2)] mt-1.5 leading-relaxed">
445:                       {alert.description || "Aucune description."}
446:                     </p>
447: 
448:                     {(alert.type === "session_response" || alert.type === "athlete_session") && onNavigate && (
449:                       <button
450:                         type="button"
451:                         className="btn-ghost mt-2.5"
452:                         style={{ minHeight: 34, paddingInline: 0, color: typeConf.color }}
