 13: export default function ResetPasswordPage() {
 14:   const { updatePassword, signOut } = useAuth();
 15:   const [password, setPassword] = useState("");
 16:   const [confirm, setConfirm] = useState("");
 17:   const [loading, setLoading] = useState(false);
 18:   const [error, setError] = useState(null);
 19:   const [done, setDone] = useState(false);
 20: 
 21:   const passwordsMatch = Boolean(confirm) && password === confirm;
 22:   const confirmError = confirm && password !== confirm ? "Les deux mots de passe ne correspondent pas." : null;
 23:   const canSubmit = password.length >= 8 && passwordsMatch;
 24: 
 25:   const handleSubmit = async (event) => {
 26:     event.preventDefault();
 27:     if (!canSubmit || loading) {
 28:       if (password.length < 8) setError("Le mot de passe doit contenir au moins 8 caractères.");
 29:       else if (!passwordsMatch) setError("Les deux mots de passe ne correspondent pas.");
 30:       return;
 31:     }
 32: 
 33:     setLoading(true);
 34:     setError(null);
 35:     try {
 36:       const { error: updateError } = await updatePassword(password);
 37:       setLoading(false);
 38:       if (updateError) {
 39:         setError(translateAuthError(updateError, "Le mot de passe n’a pas pu être mis à jour."));
 40:         return;
 41:       }
 42:       setDone(true);
 43:     } catch (updateError) {
 44:       setLoading(false);
 45:       setError(translateAuthError(updateError, "Le mot de passe n’a pas pu être mis à jour."));
 46:     }
 47:   };
 48: 
 49:   return (
 50:     <AuthShell
 51:       eyebrow="Sécurité du compte"
 52:       title={done ? "Ton mot de passe est prêt" : "Choisis un nouveau mot de passe"}
 53:       description={done
 54:         ? "La modification est enregistrée. Reconnecte-toi maintenant avec ton nouveau mot de passe."
 55:         : "Utilise au moins 8 caractères. Une phrase courte et unique est plus facile à retenir."}
 56:     >
 57:       {done ? (
 58:         <div className="auth-form">
 59:           <AuthFeedback type="success">Ton mot de passe a bien été mis à jour.</AuthFeedback>
 60:           <button type="button" onClick={signOut} className="auth-submit tap-feedback">
 61:             Aller à la connexion
 62:           </button>
 63:         </div>
 64:       ) : (
 65:         <form className="auth-form" onSubmit={handleSubmit} noValidate>
 66:           {error && <AuthFeedback>{error}</AuthFeedback>}
 67: 
 68:           <AuthPasswordField
 69:             id="new-password"
 70:             label="Nouveau mot de passe"
 71:             icon={Lock}
 72:             autoComplete="new-password"
 73:             placeholder="8 caractères minimum"
 74:             value={password}
 75:             onChange={(event) => {
 76:               setPassword(event.target.value);
 77:               if (error) setError(null);
 78:             }}
 79:             disabled={loading}
 80:             required
 81:             showStrength
