 83: 
 84:           <AuthPasswordField
 85:             id="confirm-password"
 86:             label="Confirmer le mot de passe"
 87:             icon={Lock}
 88:             autoComplete="new-password"
 89:             placeholder="••••••••"
 90:             value={confirm}
 91:             onChange={(event) => {
 92:               setConfirm(event.target.value);
 93:               if (error) setError(null);
 94:             }}
 95:             error={confirmError}
 96:             disabled={loading}
 97:             required
 98:           />
