100:           <AuthSubmitButton loading={loading} loadingLabel="Mise à jour…" disabled={loading || !canSubmit}>
101:             Définir le nouveau mot de passe
102:           </AuthSubmitButton>
103: 
104:           <AuthTrustNote>
105:             Après la modification, les autres sessions pourront demander une nouvelle connexion.
106:           </AuthTrustNote>
107:         </form>
108:       )}
