 43: const INVITE_CODE_LEN    = 8;
 44: const MIN_SUBMIT_MS      = 1500; // en dessous, personne ne remplit un vrai formulaire
 45: 
 46: const RATE_LIMIT_IP_MAX        = 8;   // tentatives
 47: const RATE_LIMIT_IP_WINDOW_MIN = 15;
 48: const RATE_LIMIT_EMAIL_MAX        = 3;
 49: const RATE_LIMIT_EMAIL_WINDOW_MIN = 60;
 50: const ATTEMPT_RETENTION_HOURS = 24;
