 52: const EMAIL_RE = /^[^\s@]{1,64}@[^\s@]{1,190}\.[^\s@]{2,24}$/;
 53: const CODE_CHARS = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789"; // sans 0/O/1/I/L
 54: // Les nouveaux codes évitent les caractères ambigus. La lecture accepte
 55: // aussi 0/1/I/L/O car les premiers clubs ont reçu un code issu d'un MD5.
 56: const CODE_RE = new RegExp(`^[A-Z0-9]{${INVITE_CODE_LEN}}$`);
