 69: function corsHeaders(origin: string | null): Record<string, string> {
 70:   const headers: Record<string, string> = {
 71:     "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
 72:     "Access-Control-Allow-Methods": "POST, OPTIONS",
 73:   };
 74:   if (origin && allowedOrigins.includes(origin)) {
 75:     headers["Access-Control-Allow-Origin"] = origin;
 76:     headers["Vary"] = "Origin";
 77:   }
 78:   return headers;
 79: }
