 81: function genCode(): string {
 82:   let s = "";
 83:   for (let i = 0; i < INVITE_CODE_LEN; i++) s += CODE_CHARS[Math.floor(Math.random() * CODE_CHARS.length)];
 84:   return s;
 85: }
