 91: function isDuplicateEmailError(err: { message?: string; code?: string; status?: number } | null): boolean {
 92:   if (!err) return false;
 93:   if (err.code === "email_exists") return true;
 94:   if (err.status === 422 && /already/i.test(err.message ?? "")) return true;
 95:   return /already registered|already exists/i.test(err.message ?? "");
 96: }
