 98: serve(async (req) => {
 99:   const origin = req.headers.get("Origin");
100:   const correlationId = crypto.randomUUID();
101: 
102:   if (req.method === "OPTIONS") return new Response("ok", { headers: corsHeaders(origin) });
103:   if (req.method !== "POST") {
104:     return new Response(JSON.stringify({ success: false, error: "Méthode non autorisée.", correlationId }), {
105:       status: 405, headers: { ...corsHeaders(origin), "Content-Type": "application/json" },
106:     });
107:   }
108:   if (origin && !allowedOrigins.includes(origin)) {
109:     return new Response(JSON.stringify({ success: false, error: "Origine non autorisée.", correlationId }), {
110:       status: 403, headers: { ...corsHeaders(origin), "Content-Type": "application/json" },
111:     });
112:   }
113: 
114:   const supabaseUrl = Deno.env.get("SUPABASE_URL");
115:   const serviceRoleKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");
116:   if (!supabaseUrl || !serviceRoleKey) {
117:     console.error(`signup[${correlationId}] configuration Supabase manquante`);
118:     return new Response(JSON.stringify({
119:       success: false,
120:       error: "Service temporairement indisponible.",
121:       correlationId,
122:     }), {
123:       status: 503,
124:       headers: { ...corsHeaders(origin), "Content-Type": "application/json" },
125:     });
126:   }
127:   const admin = createClient(supabaseUrl, serviceRoleKey);
128: 
129:   function fail(status: number, error: string) {
130:     console.error(`signup[${correlationId}] ${status} — ${error}`);
131:     return new Response(JSON.stringify({ success: false, error, correlationId }), {
132:       status, headers: { ...corsHeaders(origin), "Content-Type": "application/json" },
133:     });
134:   }
135:   // "Faux succès" volontaire — utilisé uniquement pour l'anti-énumération
136:   // d'email (voir en-tête de fichier). N'affiche pas les détails internes.
137:   function fakeSuccess() {
138:     return new Response(JSON.stringify({ success: true, correlationId }), {
139:       status: 200, headers: { ...corsHeaders(origin), "Content-Type": "application/json" },
140:     });
141:   }
142: 
143:   let createdAuthUserId: string | null = null;
144:   let reservedInvitationId: string | null = null;
145:   let reservationToken: string | null = null;
