147:   async function cleanupAuthUser(authUserId: string, reason: string) {
148:     try {
149:       const { error } = await admin.auth.admin.deleteUser(authUserId);
150:       if (error) console.error(`signup[${correlationId}] auth cleanup (${reason}):`, error.message);
