229:     const password = typeof body.password === "string" ? body.password : "";
230:     if (password.length < MIN_PASSWORD_LEN || password.length > MAX_PASSWORD_LEN) {
231:       return fail(400, `Le mot de passe doit faire entre ${MIN_PASSWORD_LEN} et ${MAX_PASSWORD_LEN} caractères.`);
