244:       const { data: individualInvitation, error: individualError } = await admin
245:         .from("club_invitations")
246:         .select("id, club_id, status, expires_at, accepted_at, recipient_email")
247:         .ilike("code", inviteCode)
248:         .maybeSingle();
249:       if (individualError && individualError.code !== "42P01") return fail(500, "Erreur serveur.");
250:       if (individualInvitation) {
