259:           return fail(400, "Cette invitation a expiré. Demande un nouveau lien à ton coach.");
260:         }
261:         const { data: invitationClub, error: invitationClubError } = await admin
262:           .from("clubs").select("invite_code").eq("id", individualInvitation.club_id).single();
