286:     if (mode === "create_club") {
287:       let code = "";
288:       for (let attempt = 0; attempt < 6; attempt++) {
289:         code = genCode();
290:         const { data: exists } = await admin.from("clubs").select("id").eq("invite_code", code).maybeSingle();
291:         if (!exists) break;
292:       }
293:       inviteCode = code;
294:     }
295: 
296:     // ── Compte Auth (seul appel hors transaction SQL) ───────────────────
297:     const { data: authData, error: authErr } = await admin.auth.admin.createUser({
298:       email: emailRaw,
299:       password,
300:       email_confirm: true, // pilote : voir stratégie documentée en en-tête de fichier
301:     });
302:     if (authErr) {
303:       if (isDuplicateEmailError(authErr)) return fakeSuccess(); // anti-énumération
304:       console.error(`signup[${correlationId}] createUser error:`, authErr.message);
305:       return fail(400, "Impossible de créer le compte.");
306:     }
307:     createdAuthUserId = authData.user.id;
308: 
309:     if (individualInvitationId) {
310:       reservationToken = crypto.randomUUID();
311:       const nowIso = new Date().toISOString();
312:       const reservedUntil = new Date(Date.now() + 5 * 60_000).toISOString();
313:       const { data: reserved, error: reserveError } = await admin.from("club_invitations").update({
314:         reservation_token: reservationToken,
315:         reserved_until: reservedUntil,
316:       })
317:         .eq("id", individualInvitationId)
318:         .eq("status", "active")
319:         .is("accepted_at", null)
320:         .or(`reserved_until.is.null,reserved_until.lt.${nowIso}`)
321:         .select("id")
322:         .maybeSingle();
323:       if (reserveError || !reserved) {
324:         await cleanupAuthUser(createdAuthUserId, "reservation refusée");
325:         createdAuthUserId = null;
326:         return fail(409, "Cette invitation est déjà utilisée ou en cours d’utilisation.");
327:       }
328:       reservedInvitationId = individualInvitationId;
329:     }
330: 
331:     // ── Test uniquement : force un échec après création Auth, pour vérifier
332:     // la compensation. Double verrou : sans SIGNUP_TEST_MODE=true dans les
333:     // secrets de la fonction, ce bloc est totalement inerte quel que soit le
334:     // contenu du body — NE JAMAIS définir SIGNUP_TEST_MODE=true en prod.
335:     if (Deno.env.get("SIGNUP_TEST_MODE") === "true" && body.__test_force_db_failure === true) {
336:       throw new Error("test_forced_db_failure");
337:     }
338: 
339:     // ── club + users + athletes, atomique (migration 20260727030000) ────
340:     const { data: rpcData, error: rpcErr } = await admin.rpc("signup_create_account_with_invitation", {
341:       p_mode: mode, p_club_name: clubName, p_invite_code: inviteCode,
342:       p_auth_uid: authData.user.id, p_name: name, p_email: emailRaw,
343:       p_individual_invitation_id: individualInvitationId,
344:       p_reservation_token: reservationToken,
345:     });
346:     if (rpcErr) throw rpcErr;
347: 
348:     if (individualInvitationId) {
349:       // La nouvelle RPC a consommé l'invitation dans la même transaction que
350:       // la création métier. On désarme donc la compensation locale.
351:       reservedInvitationId = null;
352:       reservationToken = null;
353:     } else if (mode === "join_club") {
354:       const { error: trackingError } = await admin.rpc("mark_club_invitation_used", {
355:         p_invite_code: inviteCode,
356:       });
357:       // Le rattachement est déjà validé et transactionnel. Un éventuel retard
358:       // de migration du compteur ne doit jamais annuler le compte créé.
359:       if (trackingError) console.error(`signup[${correlationId}] invitation tracking:`, trackingError.message);
360:     }
361: 
362:     return new Response(JSON.stringify({ success: true, correlationId }), {
363:       headers: { ...corsHeaders(origin), "Content-Type": "application/json" },
364:     });
365:   } catch (err) {
366:     // Compensation : le compte Auth ne doit jamais survivre seul, sans les
367:     // lignes club/users/athletes qui vont avec (club+users+athletes eux-
368:     // mêmes sont déjà tout-ou-rien grâce au RPC).
369:     if (createdAuthUserId) await cleanupAuthUser(createdAuthUserId, "transaction métier");
370:     if (reservedInvitationId && reservationToken) {
371:       const { error: releaseError } = await admin.from("club_invitations")
372:         .update({ reservation_token: null, reserved_until: null })
373:         .eq("id", reservedInvitationId).eq("reservation_token", reservationToken);
374:       if (releaseError) {
375:         console.error(`signup[${correlationId}] invitation release:`, releaseError.message);
376:       }
377:     }
378:     console.error(`signup[${correlationId}] error:`, err instanceof Error ? err.message : err);
379:     return fail(500, "Erreur serveur.");
380:   }
