49: }  1: #!/usr/bin/env node
  2: // ============================================================
  3: // AthleteOS — test_signup_regression.mjs
  4: //
  5: // Vérifie le durcissement de l'Edge Function signup (tâche 3) :
  6: //   - création de club valide (mode create_club)
  7: //   - adhésion par code valide (mode join_club)
  8: //   - réclamation d'un user+athlete précréé par import, sans doublon
  9: //   - code d'invitation invalide -> rejeté, sans créer de compte Auth
 10: //   - email déjà existant -> réponse IDENTIQUE à un succès (anti-énumération)
 11: //   - honeypot rempli -> rejeté (anti-bot, équivalent CAPTCHA)
 12: //   - soumission trop rapide (< délai minimum) -> rejetée (anti-bot)
 13: //   - rate limit par IP dépassé -> 429
 14: //   - échec forcé après création Auth -> compensation (compte Auth supprimé,
 15: //     aucune ligne club/users/athletes orpheline) — nécessite
 16: //     SIGNUP_TEST_MODE=true dans les secrets de la fonction pendant ce test
 17: //     (à retirer juste après, ce flag ne doit jamais rester actif en prod)
 18: //
 19: // Usage :
 20: //   SUPABASE_SERVICE_ROLE_KEY=... node test_signup_regression.mjs
 21: //
 22: // Requiert dans l'environnement (ou .env à la racine du dossier) :
 23: //   VITE_SUPABASE_URL, VITE_SUPABASE_ANON_KEY  (déjà dans .env)
 24: //   SUPABASE_SERVICE_ROLE_KEY                  (secret, jamais committé)
 25: // ============================================================
 26: 
 27: import { createClient } from "@supabase/supabase-js";
 28: import { readFileSync } from "node:fs";
 29: import { fileURLToPath } from "node:url";
 30: import path from "node:path";
 31: 
 32: function loadDotEnv(filePath) {
 33:   let text;
 34:   try { text = readFileSync(filePath, "utf8"); } catch { return; }
 35:   for (const rawLine of text.split("\n")) {
 36:     const line = rawLine.replace(/\r$/, "");
 37:     const m = line.match(/^([A-Z0-9_]+)=(.*)$/);
 38:     if (m && process.env[m[1]] === undefined) process.env[m[1]] = m[2].trim();
 39:   }
 40: }
 41: loadDotEnv(path.join(path.dirname(fileURLToPath(import.meta.url)), ".env"));
 42: 
 43: const SUPABASE_URL     = process.env.VITE_SUPABASE_URL;
 44: const ANON_KEY         = process.env.VITE_SUPABASE_ANON_KEY;
 45: const SERVICE_ROLE_KEY = process.env.SUPABASE_SERVICE_ROLE_KEY;
 46: 
 47: if (!SUPABASE_URL || !ANON_KEY || !SERVICE_ROLE_KEY) {
 48:   console.error(
 49:     "Variables manquantes. Requis : VITE_SUPABASE_URL, VITE_SUPABASE_ANON_KEY " +
 50:     "(dans .env) et SUPABASE_SERVICE_ROLE_KEY (variable d'environnement, jamais committée)."
 51:   );
 52:   process.exit(1);
 53: }
 54: 
 55: const FUNCTION_URL = `${SUPABASE_URL}/functions/v1/signup`;
 56: const admin = createClient(SUPABASE_URL, SERVICE_ROLE_KEY, {
 57:   auth: { autoRefreshToken: false, persistSession: false },
 58: });
 59: 
 60: const RUN_ID = Date.now();
 61: // Adresse IPv6 de documentation (RFC 3849), unique à ce run. La pile
 62: // Supabase locale ajoute ensuite ses propres sauts à X-Forwarded-For ; la
 63: // fonction utilise volontairement la première valeur. Ainsi, le test peut
 64: // saturer son quota sans empoisonner les exécutions suivantes sur 127.0.0.1.
 65: const TEST_IP = `2001:db8::${RUN_ID.toString(16)}`;
 66: 
 67: // Même alphabet que CODE_CHARS côté serveur (supabase/functions/signup) —
 68: // sans 0/O/1/I/L pour éviter les confusions. Un code de test qui contient un
 69: // caractère hors de cet alphabet est rejeté par la validation serveur (à
 70: // raison), peu importe qu'un club existe avec ce code — d'où l'utilisation
 71: // d'un vrai code aléatoire plutôt que des chiffres bruts d'un timestamp
 72: // (qui contiennent presque toujours un 0 ou un 1).
 73: const CODE_CHARS = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789";
 74: function randomTestCode(len = 8) {
 75:   let s = "";
 76:   for (let i = 0; i < len; i++) s += CODE_CHARS[Math.floor(Math.random() * CODE_CHARS.length)];
 77:   return s;
 78: }
 79: const results = [];
 80: function record(name, pass, detail) {
 81:   results.push({ name, pass, detail });
 82:   console.log(`${pass ? "✅" : "❌"} ${name}${detail ? " — " + detail : ""}`);
 83: }
 84: 
 85: // Body "propre" : passe le honeypot et le délai minimum anti-bot.
 86: function baseBody(overrides) {
 87:   return {
 88:     company: "",
 89:     formLoadedAt: Date.now() - 3000, // 3s avant l'appel, au-dessus du seuil (1.5s)
 90:     ...overrides,
 91:   };
 92: }
 93: 
 94: async function callSignup(body) {
 95:   const res = await fetch(FUNCTION_URL, {
 96:     method: "POST",
 97:     // Reproduit `supabase.functions.invoke()` utilisé par SignupPage : même
 98:     // un visiteur non connecté envoie la clé anon comme JWT de plateforme.
 99:     // Sans ce header, la passerelle rejette l'appel avant la fonction et le
100:     // test ne vérifie jamais la logique d'inscription.
101:     headers: {
102:       "Content-Type": "application/json",
103:       apikey: ANON_KEY,
104:       Authorization: `Bearer ${ANON_KEY}`,
105:       "X-Forwarded-For": TEST_IP,
106:     },
107:     body: JSON.stringify(body),
108:   });
109:   let json = null;
110:   try { json = await res.json(); } catch { /* pas de corps JSON */ }
111:   return { status: res.status, json };
112: }
113: 
114: async function cleanupByEmail(email) {
115:   const { data: userRow } = await admin.from("users").select("id, club_id, auth_uid").eq("email", email).maybeSingle();
116:   if (userRow) {
117:     await admin.from("athletes").delete().eq("user_id", userRow.id);
118:     await admin.from("users").delete().eq("id", userRow.id);
119:     if (userRow.club_id) await admin.from("clubs").delete().eq("id", userRow.club_id);
120:     if (userRow.auth_uid) await admin.auth.admin.deleteUser(userRow.auth_uid).catch(() => {});
121:   }
122:   // Au cas où la ligne users n'a pas été créée mais le compte Auth oui
123:   // (ne devrait pas arriver grâce à la compensation, mais on nettoie large).
124:   const { data: authList } = await admin.auth.admin.listUsers();
125:   const orphan = authList?.users?.find((u) => u.email === email);
126:   if (orphan) await admin.auth.admin.deleteUser(orphan.id).catch(() => {});
127: }
