129: async function main() {
130:   const createdEmails = [];
131:   let existingClub;
132: 
133:   try {
134:     // ── Setup : un club existant avec un code valide, pour tester join_club ──
135:     existingClub = await admin.from("clubs")
136:       .insert({ name: `Signup Test Club ${RUN_ID}`, invite_code: randomTestCode() })
137:       .select().single().then((r) => { if (r.error) throw r.error; return r.data; });
138:     const validInviteCode = existingClub.invite_code;
139: 
140:     // ── 1. Création de club valide ──────────────────────────────────
141:     const createEmail = `signup-test-create-${RUN_ID}@example.invalid`;
142:     createdEmails.push(createEmail);
143:     {
144:       const { status, json } = await callSignup(baseBody({
145:         mode: "create_club", name: "Coach Test", email: createEmail, password: `Test-${RUN_ID}-Aa!`,
146:         clubName: `Nouveau Club ${RUN_ID}`,
147:       }));
148:       record("Création club valide -> succès", status === 200 && json?.success === true, `status=${status} body=${JSON.stringify(json)}`);
149:     }
150: 
151:     // ── 2. Adhésion par code valide ─────────────────────────────────
152:     const joinEmail = `signup-test-join-${RUN_ID}@example.invalid`;
153:     createdEmails.push(joinEmail);
154:     {
155:       const { status, json } = await callSignup(baseBody({
156:         mode: "join_club", name: "Athlete Test", email: joinEmail, password: `Test-${RUN_ID}-Aa!`,
157:         inviteCode: validInviteCode,
158:       }));
159:       record("Adhésion code valide -> succès", status === 200 && json?.success === true, `status=${status} body=${JSON.stringify(json)}`);
160:     }
161:     // Vérifie que l'athlète a bien été rattaché au bon club (RPC atomique).
162:     {
163:       const { data: row } = await admin.from("users").select("club_id, role").eq("email", joinEmail).maybeSingle();
164:       record("Adhésion -> rattaché au bon club + rôle athlete", row?.club_id === existingClub.id && row?.role === "athlete", JSON.stringify(row));
165:     }
166: 
167:     // ── Réclamation d'un athlète importé ─────────────────────────────────
168:     // Un athlète importé doit réclamer ses lignes existantes, sans que le
169:     // signup ne crée un deuxième profil ou n'écrase les données du coach.
170:     const importedClaimEmail = `signup-test-imported-${RUN_ID}@example.invalid`;
171:     createdEmails.push(importedClaimEmail);
172:     const importedUser = await admin.from("users").insert({
173:       club_id: existingClub.id,
174:       name: "Nom précréé par import",
175:       email: importedClaimEmail,
176:       role: "athlete",
177:       auth_uid: null,
178:     }).select().single().then((result) => { if (result.error) throw result.error; return result.data; });
179:     const importedAthlete = await admin.from("athletes").insert({
180:       club_id: existingClub.id,
181:       name: "Nom précréé par import",
182:       user_id: importedUser.id,
183:       profile_data: { level: "National", secondary_disciplines: ["200 m"] },
184:     }).select().single().then((result) => { if (result.error) throw result.error; return result.data; });
185:     {
186:       const { status, json } = await callSignup(baseBody({
187:         mode: "join_club",
188:         name: "Nom différent saisi au signup",
189:         email: importedClaimEmail,
190:         password: `Test-${RUN_ID}-Aa!`,
191:         inviteCode: validInviteCode,
192:       }));
193:       const { data: claimedUser } = await admin
194:         .from("users")
195:         .select("id, club_id, name, auth_uid")
196:         .eq("email", importedClaimEmail)
197:         .single();
198:       const { data: athleteRows } = await admin
199:         .from("athletes")
200:         .select("id, name, profile_data")
201:         .eq("user_id", importedUser.id);
202:       record(
203:         "Signup d'un athlète importé -> succès",
204:         status === 200 && json?.success === true && Boolean(claimedUser?.auth_uid),
205:         `status=${status} body=${JSON.stringify(json)}`,
206:       );
207:       record(
208:         "Signup importé -> même user, même athlete, aucun profil écrasé",
209:         claimedUser?.id === importedUser.id
210:           && claimedUser?.club_id === existingClub.id
211:           && claimedUser?.name === "Nom précréé par import"
212:           && athleteRows?.length === 1
213:           && athleteRows[0].id === importedAthlete.id
214:           && athleteRows[0].name === "Nom précréé par import"
215:           && athleteRows[0].profile_data?.level === "National",
216:         `users=${claimedUser?.id} athletes=${athleteRows?.length ?? 0}`,
217:       );
