220:     // ── 3. Code d'invitation invalide ───────────────────────────────
221:     {
222:       const { status, json } = await callSignup(baseBody({
223:         mode: "join_club", name: "Nobody", email: `signup-test-badcode-${RUN_ID}@example.invalid`,
224:         password: `Test-${RUN_ID}-Aa!`, inviteCode: "ZZZZZZZZ",
225:       }));
226:       record("Code invalide -> rejeté (400)", status === 400 && json?.success === false, `status=${status}`);
227:     }
228: 
229:     // ── 4. Email déjà existant -> réponse identique à un succès ─────
230:     {
231:       const { status, json } = await callSignup(baseBody({
232:         mode: "create_club", name: "Coach Test", email: createEmail, // déjà utilisé à l'étape 1
233:         password: `Autre-${RUN_ID}-Bb!`, clubName: "Club Fantome",
234:       }));
235:       record("Email existant -> même forme qu'un succès (anti-énumération)", status === 200 && json?.success === true, `status=${status} body=${JSON.stringify(json)}`);
236:     }
237:     // Vérifie qu'aucun second compte/club n'a été créé pour cet email.
238:     {
239:       const { data: rows } = await admin.from("users").select("id").eq("email", createEmail);
240:       record("Email existant -> aucun doublon créé", (rows ?? []).length === 1, `count=${(rows ?? []).length}`);
241:     }
242: 
243:     // ── 5. Honeypot rempli -> rejeté (équivalent CAPTCHA) ────────────
244:     {
245:       const { status, json } = await callSignup(baseBody({
246:         mode: "create_club", name: "Bot", email: `signup-test-bot-${RUN_ID}@example.invalid`,
247:         password: `Test-${RUN_ID}-Aa!`, clubName: "Bot Club", company: "http://spam.example",
248:       }));
249:       record("Honeypot rempli -> rejeté (400)", status === 400 && json?.success === false, `status=${status}`);
250:     }
251: 
252:     // ── 6. Soumission trop rapide -> rejetée (équivalent CAPTCHA) ────
253:     {
254:       const { status, json } = await callSignup(baseBody({
255:         mode: "create_club", name: "Bot", email: `signup-test-fast-${RUN_ID}@example.invalid`,
256:         password: `Test-${RUN_ID}-Aa!`, clubName: "Fast Club", formLoadedAt: Date.now(), // 0ms écoulé
257:       }));
258:       record("Soumission trop rapide -> rejetée (400)", status === 400 && json?.success === false, `status=${status}`);
259:     }
