261:     // ── 7. Échec forcé après création Auth -> compensation ───────────
262:     // Nécessite SIGNUP_TEST_MODE=true dans les secrets de la fonction.
263:     // Si ce n'est pas le cas, le flag est inerte et ce test est ignoré
264:     // (annoncé explicitement, pas de faux positif). Fait AVANT le test de
265:     // rate limit ci-dessous : celui-ci épuise volontairement le quota IP,
266:     // ce qui ferait échouer cet appel-ci en 429 s'il passait après.
267:     {
268:       const compEmail = `signup-test-compensation-${RUN_ID}@example.invalid`;
269:       const { status, json } = await callSignup(baseBody({
270:         mode: "create_club", name: "Compensation Test", email: compEmail,
271:         password: `Test-${RUN_ID}-Aa!`, clubName: "Compensation Club",
272:         __test_force_db_failure: true,
273:       }));
274:       if (status === 500) {
275:         const { data: authList } = await admin.auth.admin.listUsers();
276:         const orphanAuth = authList?.users?.find((u) => u.email === compEmail);
277:         const { data: orphanUserRow } = await admin.from("users").select("id").eq("email", compEmail).maybeSingle();
278:         record("Compensation : pas de compte Auth orphelin", !orphanAuth, orphanAuth ? "compte Auth encore présent !" : "nettoyé, OK");
279:         record("Compensation : pas de ligne users orpheline", !orphanUserRow, orphanUserRow ? "ligne users encore présente !" : "aucune, OK");
280:       } else {
281:         console.log(`⚠️  Test de compensation ignoré (SIGNUP_TEST_MODE n'est probablement pas activé sur la fonction) — status=${status} body=${JSON.stringify(json)}`);
282:       }
283:     }
284: 
285:     // ── 8. Rate limit par IP dépassé ─────────────────────────────────
286:     // La limite est à 8 tentatives/15min par IP ; les appels précédents dans
287:     // ce run en comptent déjà plusieurs (même IP source : ce script). On
288:     // envoie des tentatives supplémentaires jusqu'à obtenir un 429, avec un
289:     // plafond de sécurité pour ne pas boucler indéfiniment si jamais la
290:     // limite ne déclenche pas. Dernier test métier du script — après ça,
291:     // l'IP est volontairement au-dessus du quota.
292:     {
293:       let hit429 = false;
294:       for (let i = 0; i < 10 && !hit429; i++) {
295:         const { status } = await callSignup(baseBody({
296:           mode: "join_club", name: "Rate Test", email: `signup-test-rate-${RUN_ID}-${i}@example.invalid`,
297:           password: `Test-${RUN_ID}-Aa!`, inviteCode: "ZZZZZZZZ", // volontairement invalide, peu importe ici
298:         }));
