 13: const WellnessModal = memo(({ athlete, clubId, onClose, onSaved }) => {
 14:   const [form, setForm] = useState({
 15:     sleep: null, energy: null, soreness: null, mood: null, stress: null,
 16:   });
 17:   const [notes,  setNotes]  = useState("");
 18:   const [saving, setSaving] = useState(false);
 19:   const [err,    setErr]    = useState(null);
 20:   const { dialogRef } = useAccessibleDialog({ onClose, closeDisabled: saving });
 21: 
 22:   const allAnswered   = Object.values(form).every(v => v !== null);
 23:   const answeredCount = Object.values(form).filter(v => v !== null).length;
 24:   const previewScore  = useMemo(() => computeWellnessScore(form), [form]);
 25: 
 26:   const scoreColor = previewScore === null ? "var(--c-text-3)"
 27:     : previewScore >= 75 ? "#1D9E75"
 28:     : previewScore >= 50 ? "#E8A020"
 29:     : "#E05252";
 30: 
 31:   const scoreLabel = previewScore === null ? "—"
 32:     : previewScore >= 75 ? "Plutôt favorable"
 33:     : previewScore >= 55 ? "Ressenti équilibré"
 34:     : "À adapter";
 35: 
 36:   const handleSubmit = async () => {
 37:     if (!allAnswered) return;
 38:     setSaving(true); setErr(null);
 39:     try {
 40:       const today = toLocalDateStr(new Date());
 41:       const { error } = await supabase.from("athlete_wellness").upsert({
 42:         athlete_id: athlete.id,
 43:         club_id:    clubId,
 44:         date:       today,
 45:         sleep:    form.sleep,
 46:         energy:   form.energy,
 47:         soreness: form.soreness,
 48:         mood:     form.mood,
 49:         stress:   form.stress,
 50:         notes:    notes.trim() || null,
 51:       }, { onConflict: "athlete_id,date" });
 52:       if (error) throw error;
 53:       const saved = { ...form, notes: notes.trim() || null, date: today };
 54:       // Fermer D'ABORD, puis notifier le parent
 55:       onClose();
 56:       onSaved(saved);
 57:     } catch(e) {
 58:       setErr(e.message ?? "Erreur lors de l'enregistrement");
 59:       setSaving(false);
 60:     }
 61:   };
 62: 
 63:   return (
 64:     <div
 65:       style={{
 66:         position: "fixed", inset: 0, zIndex: 9999,
 67:         display: "flex", alignItems: "flex-end", justifyContent: "center",
 68:         background: "rgba(0,0,0,0.72)",
