 72:       onClick={e => e.target === e.currentTarget && onClose()}
 73:     >
 74:       <div ref={dialogRef} tabIndex={-1} role="dialog" aria-modal="true" aria-labelledby="wellness-dialog-title" style={{
 75:         background: "var(--c-surface)",
