 79:         width: "100%",
 80:         maxWidth: 480,
 81:         maxHeight: "92dvh",
 82:         display: "flex",
 83:         flexDirection: "column",
 84:         overflow: "hidden",
 85:         boxShadow: "0 -8px 40px rgba(0,0,0,0.50)",
 86:         animation: "sheet-up 0.32s cubic-bezier(0.16,1,0.3,1) both",
 87:       }}>
 88: 
 89:         {/* Poignée */}
 90:         <div style={{ display: "flex", justifyContent: "center", paddingTop: 10, paddingBottom: 4, flexShrink: 0 }}>
 91:           <div style={{ width: 32, height: 3, borderRadius: 99, background: "var(--c-border-strong)" }} />
 92:         </div>
 93: 
 94:         {/* Header dark */}
 95:         <div style={{
 96:           padding: "14px 20px 16px",
 97:           flexShrink: 0,
 98:           background: "rgba(29,158,117,0.08)",
 99:           borderBottom: "1px solid rgba(29,158,117,0.12)",
100:         }}>
101:           <div style={{ display: "flex", alignItems: "flex-start", justifyContent: "space-between", gap: 12, marginBottom: 14 }}>
102:             <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
103:               <div style={{ width: 38, height: 38, borderRadius: 10, background: "rgba(29,158,117,0.15)", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
104:                 <Activity size={17} color="#1D9E75" strokeWidth={2} />
105:               </div>
106:               <div>
107:                 <h3 id="wellness-dialog-title" style={{ fontSize: 14, fontWeight: 500, color: "var(--c-text-1)", lineHeight: 1.3 }}>
108:                   Comment tu vas ce matin ?
109:                 </h3>
110:                 <p style={{ fontSize: 11, color: "var(--c-text-3)", marginTop: 2 }}>
111:                   {new Date().toLocaleDateString("fr-BE", { weekday: "long", day: "numeric", month: "long" })}
112:                 </p>
113:               </div>
114:             </div>
115:             <button type="button" onClick={onClose} aria-label="Fermer le questionnaire bien-être"
116:               style={{ width: 32, height: 32, borderRadius: 9, background: "var(--c-surface-2)", border: "1px solid var(--c-border)", display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer", color: "var(--c-text-2)", flexShrink: 0 }}>
117:               <X size={15} />
