162:                 <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 10 }}>
163:                   <div style={{ width: 30, height: 30, borderRadius: 8, background: q.color + "18", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
164:                     <Icon size={14} color={q.color} strokeWidth={2} />
165:                   </div>
166:                   <div style={{ flex: 1, minWidth: 0 }}>
167:                     <span style={{ fontSize: 13, fontWeight: 500, color: "var(--c-text-1)" }}>{q.label}</span>
168:                     {q.inverted && (
169:                       <span style={{ marginLeft: 6, fontSize: 9.5, fontWeight: 500, color: "var(--c-text-4)", textTransform: "uppercase", letterSpacing: "0.06em" }}>
170:                         moins = mieux
171:                       </span>
172:                     )}
173:                   </div>
174:                   {answered && <CheckCircle size={14} color="#1D9E75" style={{ flexShrink: 0 }} />}
175:                 </div>
176: 
177:                 {/* Boutons 1-5 */}
178:                 <div style={{ display: "flex", gap: 6 }}>
179:                   {[1, 2, 3, 4, 5].map((v) => {
180:                     const selected   = form[q.key] === v;
