203:                           {q.desc[v - 1]}
204:                         </span>
205:                       </button>
206:                     );
207:                   })}
208:                 </div>
209:               </div>
210:             );
211:           })}
212: 
213:           {/* Note optionnelle */}
214:           <div>
215:             <label style={{ display: "block", fontSize: 9.5, fontWeight: 500, letterSpacing: "0.08em", textTransform: "uppercase", color: "var(--c-text-3)", marginBottom: 7 }}>
