 24: function StatusIcon({ status }) {
 25:   if (status === "done")    return <CheckCircle2 size={15} color="#1D9E75" />;
 26:   if (status === "partial") return <AlertCircle  size={15} color="#EF9F27" />;
 27:   if (status === "none")    return <XCircle      size={15} color="#E24B4A" />;
 28:   return <div style={{ width: 15, height: 15, borderRadius: "50%", border: "1.5px dashed var(--c-text-3)" }} />;
 29: }
 30: 
 31: function MiniLoadSpark({ data }) {
 32:   if (data.length < 2) return <div style={{ width: 72, height: 28 }} />;
 33:   return (
 34:     <div style={{ width: 72, height: 28 }}>
 35:       <ResponsiveContainer width="100%" height="100%">
 36:         <LineChart data={data} margin={{ top: 2, right: 2, bottom: 2, left: 2 }}>
 37:           <Line type="monotone" dataKey="load" stroke="#1D9E75" strokeWidth={2} dot={false} />
 38:         </LineChart>
 39:       </ResponsiveContainer>
 40:     </div>
 41:   );
 42: }
 43: 
 44: function TrendArrow({ trend }) {
 45:   if (trend === "up")   return <span style={{ display: "inline-flex", alignItems: "center", gap: 2, color: "var(--tone-success)" }}><TrendingUp size={12} /> Hausse</span>;
 46:   if (trend === "down") return <span style={{ display: "inline-flex", alignItems: "center", gap: 2, color: "var(--tone-danger)" }}><TrendingDown size={12} /> Baisse</span>;
 47:   return <span style={{ display: "inline-flex", alignItems: "center", gap: 4, color: "var(--c-text-2)" }}><Minus size={14} /> Stable</span>;
 48: }
 49: 
 50: function WeekCard({ week, dateRange, sessionCount, onClick }) {
 51:   return (
 52:     <button type="button" onClick={onClick} className="card card-hover tap-feedback"
 53:       style={{ width: "100%", textAlign: "left", padding: "16px 18px", display: "flex", alignItems: "center", gap: 14, cursor: "pointer" }}>
 54:       <div style={{ width: 40, height: 40, borderRadius: 12, background: "rgba(29,158,117,0.10)", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
 55:         <FileText size={17} color="#1D9E75" strokeWidth={1.8} />
 56:       </div>
 57:       <div style={{ flex: 1, minWidth: 0 }}>
 58:         <p style={{ fontSize: 15, fontWeight: 700, color: "var(--c-text-1)" }}>{formatWeekLabel(week, dateRange)}</p>
 59:         <p style={{ fontSize: 12, color: "var(--c-text-2)", marginTop: 3 }}>{sessionCount} séance{sessionCount > 1 ? "s" : ""}</p>
 60:       </div>
 61:       <ChevronRight size={17} color="var(--c-text-3)" aria-hidden="true" />
 62:     </button>
 63:   );
 64: }
