 66: // ─── Détail d'une semaine (inline, pas de modal — un seul athlète) ───────
 67: function WeekReportDetail({ report }) {
 68:   const { stats, metrics, categoriesWorked, categoriesAbsent, wellnessAvg, summary, sessions } = report;
 69: 
 70:   return (
 71:     <div className="space-y-4">
 72:       <div style={{ padding: 14, borderRadius: 14, background: "rgba(29,158,117,0.06)", border: "1px solid rgba(29,158,117,0.15)" }}>
 73:         <p style={{ fontSize: 13, lineHeight: 1.6, color: "var(--c-text-2)" }}>{summary}</p>
 74:       </div>
 75: 
 76:       <div style={{ display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gap: 8 }}>
 77:         <div style={{ padding: "12px 10px", borderRadius: 14, background: "var(--c-surface-2)", border: "1px solid var(--c-border)", textAlign: "center" }}>
 78:           <p style={{ fontSize: 12, fontWeight: 700, color: "var(--c-text-2)", textTransform: "uppercase", letterSpacing: "0.05em" }}>EWMA courte</p>
 79:           <p style={{ fontSize: 19, fontWeight: 700, color: "var(--c-text-1)", marginTop: 4 }}>{stats.total > 0 ? metrics.acute : "—"}</p>
 80:         </div>
 81:         <div style={{ padding: "12px 10px", borderRadius: 14, background: "var(--c-surface-2)", border: "1px solid var(--c-border)", textAlign: "center" }}>
 82:           <p style={{ fontSize: 12, fontWeight: 700, color: "var(--c-text-2)", textTransform: "uppercase", letterSpacing: "0.05em" }}>Cette semaine</p>
 83:           <p style={{ fontSize: 19, fontWeight: 700, color: "var(--tone-info)", marginTop: 4 }}>
 84:             {stats.total > 0 ? (metrics.load7 ?? "—") : "—"}
 85:           </p>
 86:         </div>
 87:         <div style={{ padding: "12px 10px", borderRadius: 14, background: "var(--c-surface-2)", border: "1px solid var(--c-border)", textAlign: "center" }}>
 88:           <p style={{ fontSize: 12, fontWeight: 700, color: "var(--c-text-2)", textTransform: "uppercase", letterSpacing: "0.05em" }}>Wellness moy.</p>
 89:           <p style={{ fontSize: 19, fontWeight: 700, color: "var(--c-text-1)", marginTop: 4 }}>{wellnessAvg != null ? wellnessAvg : "—"}</p>
 90:         </div>
 91:       </div>
 92: 
 93:       {categoriesWorked.length > 0 && (
 94:         <div>
 95:           <p style={{ fontSize: 12, fontWeight: 700, color: "var(--c-text-2)", textTransform: "uppercase", letterSpacing: "0.06em", marginBottom: 8 }}>Répartition de la charge</p>
 96:           <div style={{ display: "flex", flexWrap: "wrap", gap: 6 }}>
 97:             {categoriesWorked.map(c => {
 98:               const col = colorsFor(c.id);
 99:               return (
100:                 <span key={c.id} style={{ fontSize: 12, fontWeight: 700, padding: "6px 10px", borderRadius: 10, background: col.bg, color: col.text, border: `1px solid ${col.border}33` }}>
101:                   {c.label} · {c.load} points
102:                 </span>
103:               );
104:             })}
105:           </div>
106:           {categoriesAbsent.length > 0 && categoriesAbsent.length < CATEGORIES.length && (
107:             <p style={{ fontSize: 12, color: "var(--c-text-2)", marginTop: 8 }}>
108:               Non travaillées : {categoriesAbsent.map(id => CATEGORIES.find(c => c.id === id)?.label ?? id).join(", ")}
109:             </p>
110:           )}
111:         </div>
112:       )}
113: 
114:       <div>
115:         <p style={{ fontSize: 12, fontWeight: 700, color: "var(--c-text-2)", textTransform: "uppercase", letterSpacing: "0.06em", marginBottom: 8 }}>
116:           Séances ({sessions.length})
117:         </p>
118:         {sessions.length === 0 ? (
119:           <p style={{ fontSize: 13, color: "var(--c-text-2)" }}>Aucune séance planifiée cette semaine.</p>
120:         ) : (
121:           <div className="card" style={{ overflow: "hidden" }}>
122:             {sessions.map((s, i) => {
123:               const col = colorsFor(s.category);
124:               const rpe = getRPELabel(s.rpe);
125:               return (
126:                 <div key={s.id} style={{ padding: "12px 14px", display: "flex", alignItems: "flex-start", gap: 10, borderTop: i > 0 ? "1px solid var(--c-border)" : "none" }}>
127:                   <div style={{ marginTop: 2, flexShrink: 0 }}><StatusIcon status={s.status} /></div>
128:                   <div style={{ flex: 1, minWidth: 0 }}>
129:                     <div style={{ display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap" }}>
130:                       <p style={{ fontSize: 14, fontWeight: 700, color: "var(--c-text-1)" }}>{s.title}</p>
131:                       <span style={{ fontSize: 12, fontWeight: 700, padding: "3px 8px", borderRadius: 7, background: col.bg, color: col.text }}>
132:                         {CATEGORIES.find(c => c.id === s.category)?.label ?? s.category}
133:                       </span>
134:                       <span className="chip chip-neutral">{getSessionTrainingFocus(s).shortLabel}</span>
135:                     </div>
136:                     <div style={{ display: "flex", alignItems: "center", gap: 8, marginTop: 3, flexWrap: "wrap" }}>
137:                       <span style={{ fontSize: 12, color: "var(--c-text-2)" }}>
138:                         {s.sessionDate ? parseLocalDate(s.sessionDate.slice(0, 10)).toLocaleDateString("fr-BE", { weekday: "short", day: "numeric", month: "short" }) : s.day}
139:                       </span>
140:                       {s.rpe != null && <span style={{ fontSize: 12, fontWeight: 700, color: rpe.color }}>RPE {s.rpe} · {rpe.label}</span>}
141:                       {s.load != null && <span style={{ fontSize: 12, color: "var(--c-text-2)" }}>{s.load} points d'effort</span>}
142:                     </div>
143:                     {s.comment && <p style={{ fontSize: 13, lineHeight: 1.5, color: "var(--c-text-2)", fontStyle: "italic", marginTop: 5 }}>« {s.comment} »</p>}
144:                   </div>
145:                 </div>
146:               );
147:             })}
148:           </div>
149:         )}
150:       </div>
151:     </div>
152:   );
153: }
