155: // ─── Composant principal ───────────────────────────────────────────────────
156: export default function MesRapports({ athlete, sessions, weeklyCharge }) {
157:   const [wellnessRows, setWellnessRows] = useState([]);
158:   const [viewMode,     setViewMode]     = useState("week"); // "week" | "month"
159:   const [selectedWeek, setSelectedWeek] = useState(null);
160: 
161:   useEffect(() => {
162:     if (!athlete?.id) return;
163:     supabase.from("athlete_wellness").select("*").eq("athlete_id", athlete.id)
164:       .then(({ data }) => {
165:         setWellnessRows((data ?? []).map(w => ({
166:           athleteId: w.athlete_id, date: w.date, sleep: w.sleep, energy: w.energy,
167:           soreness: w.soreness, mood: w.mood, stress: w.stress,
168:         })));
169:       });
170:   }, [athlete?.id]);
171: 
172:   const weeks = useMemo(() => getAvailableWeeks(sessions, athlete.id), [sessions, athlete.id]);
173: 
174:   const selectedReport = useMemo(() => {
175:     if (selectedWeek == null) return null;
176:     return buildWeeklyReport({ athleteId: athlete.id, week: selectedWeek, sessions, weeklyCharge, wellnessRows });
177:   }, [selectedWeek, athlete.id, sessions, weeklyCharge, wellnessRows]);
178: 
179:   const last4Weeks = useMemo(() => weeks.slice(0, 4).map(w => w.week), [weeks]);
180:   const monthAggregate = useMemo(() => {
181:     if (viewMode !== "month" || last4Weeks.length === 0) return null;
182:     return buildMonthlyAggregate({ athleteId: athlete.id, weeks: last4Weeks, sessions, weeklyCharge, wellnessRows });
183:   }, [viewMode, last4Weeks, athlete.id, sessions, weeklyCharge, wellnessRows]);
184: 
185:   const selectedWeekMeta = weeks.find(w => w.week === selectedWeek);
186: 
187:   return (
188:     <div className="space-y-5">
189:       <div>
190:         <h2 className="section-title">Rapports d’entraînement</h2>
191:         <p style={{ fontSize: 13, color: "var(--c-text-2)", marginTop: 4 }}>Charge, régularité et contenu de tes dernières semaines.</p>
192:       </div>
193:       <div className="flex gap-1 rounded-2xl p-1.5" style={{ background: "var(--c-surface)", border: "1px solid var(--c-border)" }}>
194:         {[{ id: "week", label: "Semaine" }, { id: "month", label: "Mois" }].map(m => (
195:           <button key={m.id} type="button" aria-pressed={viewMode === m.id} onClick={() => { setViewMode(m.id); setSelectedWeek(null); }}
196:             className="flex-1"
197:             style={{
198:               minHeight: 44, padding: "0 12px", borderRadius: 12, fontSize: 13, fontWeight: 700,
199:               background: viewMode === m.id ? "rgba(29,158,117,0.16)" : "transparent",
200:               color: viewMode === m.id ? "#7BD8B4" : "var(--c-text-2)",
201:               border: "none", cursor: "pointer",
202:             }}>
203:             {m.label}
204:           </button>
205:         ))}
206:       </div>
207: 
208:       {viewMode === "week" && selectedWeek == null && (
209:         weeks.length === 0 ? (
210:           <div className="card p-12 text-center">
211:             <div style={{ width: 56, height: 56, borderRadius: 18, display: "flex", alignItems: "center", justifyContent: "center", margin: "0 auto 14px", background: "var(--c-surface-2)" }}>
212:               <CalendarDays size={26} color="var(--c-text-3)" strokeWidth={1.5} />
213:             </div>
214:             <p style={{ fontSize: 15, fontWeight: 700, color: "var(--c-text-1)" }}>Aucun rapport disponible</p>
215:             <p style={{ fontSize: 13, color: "var(--c-text-2)", marginTop: 4 }}>Il apparaîtra dès ta première semaine avec des séances.</p>
216:           </div>
217:         ) : (
218:           <div className="space-y-2.5">
219:             {weeks.map(w => (
220:               <WeekCard key={w.week} week={w.week} dateRange={w.dateRange} sessionCount={w.sessionCount}
221:                 onClick={() => setSelectedWeek(w.week)} />
222:             ))}
223:           </div>
224:         )
225:       )}
226: 
227:       {viewMode === "week" && selectedWeek != null && selectedReport && (
228:         <div className="space-y-3">
229:           <button type="button" onClick={() => setSelectedWeek(null)} className="tap-feedback"
230:             style={{ minHeight: 44, display: "flex", alignItems: "center", gap: 6, fontSize: 13, fontWeight: 700, color: "var(--tone-success)", background: "none", border: "none", cursor: "pointer", padding: "0 4px" }}>
231:             <ChevronLeft size={16} aria-hidden="true" /> Toutes mes semaines
232:           </button>
233:           <p style={{ fontSize: 17, fontWeight: 700, color: "var(--c-text-1)" }}>
234:             {formatWeekLabel(selectedWeek, selectedWeekMeta?.dateRange)}
235:           </p>
236:           <WeekReportDetail report={selectedReport} />
237:         </div>
238:       )}
239: 
240:       {viewMode === "month" && (
241:         !monthAggregate ? (
242:           <div className="card p-12 text-center">
243:             <p style={{ fontSize: 15, fontWeight: 700, color: "var(--c-text-1)" }}>Pas encore assez de données pour une vue mensuelle</p>
244:           </div>
245:         ) : (
246:           <div className="card" style={{ padding: 20 }}>
247:             <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 16 }}>
248:               <p className="card-title" style={{ flex: 1 }}>4 dernières semaines</p>
249:               <MiniLoadSpark data={monthAggregate.weeks.map(w => ({ load: w.stats.totalLoad }))} />
250:             </div>
251:             <div style={{ display: "flex", alignItems: "baseline", gap: 6, marginBottom: 6 }}>
252:               <span style={{ fontSize: 22, fontWeight: 700, color: "var(--c-text-1)" }}>{monthAggregate.totalLoad}</span>
253:               <span style={{ fontSize: 12, color: "var(--c-text-2)" }}>points d'effort cumulés</span>
254:             </div>
255:             <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 12 }}>
256:               <span style={{ fontSize: 12, color: "var(--c-text-2)" }}>{monthAggregate.doneTotal}/{monthAggregate.sessionsTotal} séances faites</span>
257:               <TrendArrow trend={monthAggregate.trend} />
258:             </div>
259:             {monthAggregate.categoriesWorked.length > 0 && (
260:               <div style={{ display: "flex", flexWrap: "wrap", gap: 5 }}>
261:                 {monthAggregate.categoriesWorked.slice(0, 5).map(c => {
262:                   const col = colorsFor(c.id);
263:                   return (
264:                     <span key={c.id} style={{ fontSize: 12, fontWeight: 700, padding: "5px 9px", borderRadius: 8, background: col.bg, color: col.text }}>
265:                       {c.label}
266:                     </span>
267:                   );
268:                 })}
269:               </div>
270:             )}
271:           </div>
272:         )
273:       )}
274:     </div>
275:   );
276: }  1: // ============================================================
  2: // AthleteOS — src/athlete/shared.test.js
  3: //
  4: // Moteur central de comparaison de performances (tâche 11), porté ici
  5: // en Vitest (tâche 19) depuis test_perf_engine.mjs — fonctions pures,
  6: // aucune base de données requise.
  7: //
  8: // Le bloc de test isNewRecord() de l'ancien script n'a PAS été porté :
  9: // cette fonction a été supprimée de competitionsShared.js à la tâche 14
 10: // (comparaison de record déplacée côté serveur, RPC _apply_competition_
 11: // result) — l'ancien test_perf_engine.mjs ne le savait pas et plantait
 12: // silencieusement (TypeError: isNewRecord is not a function) depuis,
 13: // jamais ré-exécuté entre-temps. Trouvé en portant ce test — exactement
 14: // le genre de régression que la tâche 19 doit empêcher désormais.
