 24: describe("parsePerf", () => {
 25:   it.each([
 26:     ["11.20", 11.2],
 27:     ["4:32", 272],
 28:     ["7.60m", 7.6],
 29:     ["14.20", 14.2],
 30:     [null, null],
 31:   ])("parsePerf(%s) -> %s", (input, expected) => {
 32:     expect(parsePerf(input).value).toBe(expected);
 33:   });
 34: 
 35:   it("ne renvoie plus de champ hib/higherIsBetter (le sens vient de la discipline, jamais du format)", () => {
 36:     const parsed = parsePerf("11.20");
 37:     expect("hib" in parsed).toBe(false);
 38:     expect("higherIsBetter" in parsed).toBe(false);
 39:   });
 40: 
 41:   it("précision différente = même valeur numérique", () => {
 42:     expect(parsePerf("11.2").value).toBe(parsePerf("11.20").value);
 43:   });
 44: 
 45:   it("texte non numérique -> null, jamais NaN", () => {
 46:     expect(parsePerf("abandon").value).toBeNull();
 47:   });
 48: });
 49: 
 50: describe("getDiscHib — sens correct par discipline", () => {
 51:   it.each([
 52:     ["100m", false],
 53:     ["1500m", false],
 54:     ["Longueur", true],
 55:     ["Poids", true],
 56:     ["Décathlon", true],
