 62: describe("isBetterOrEqual", () => {
 63:   it("100m : 11.00 est meilleur que 11.20 (chrono, plus petit = mieux)", () => {
 64:     expect(isBetterOrEqual(11.0, 11.2, "100m")).toBe(true);
 65:     expect(isBetterOrEqual(11.2, 11.0, "100m")).toBe(false);
 66:   });
 67: 
 68:   it("Longueur : 7.60 est meilleur que 7.20 (distance, plus grand = mieux)", () => {
 69:     expect(isBetterOrEqual(7.6, 7.2, "Longueur")).toBe(true);
 70:     expect(isBetterOrEqual(7.2, 7.6, "Longueur")).toBe(false);
 71:   });
 72: 
 73:   it("Poids : 14.50 est meilleur que 14.20", () => {
 74:     expect(isBetterOrEqual(14.5, 14.2, "Poids")).toBe(true);
 75:   });
 76: 
 77:   it("Décathlon : 7800 pts est meilleur que 7500 pts", () => {
 78:     expect(isBetterOrEqual(7800, 7500, "Décathlon")).toBe(true);
 79:   });
 80: 
 81:   it("égalité -> toujours vrai", () => {
 82:     expect(isBetterOrEqual(11.2, 11.2, "100m")).toBe(true);
 83:   });
 84: 
 85:   it("valeur candidate absente -> jamais meilleure", () => {
 86:     expect(isBetterOrEqual(null, 11.2, "100m")).toBe(false);
 87:   });
 88: 
 89:   it("valeur de référence absente -> toujours meilleure (rien à battre)", () => {
 90:     expect(isBetterOrEqual(11.2, null, "100m")).toBe(true);
 91:   });
 92: });
