 94: describe("compareValues — tri correct pour un classement", () => {
 95:   it("100m : trié du plus rapide au plus lent", () => {
 96:     const sorted = [11.8, 10.95, 11.2].sort((a, b) => compareValues(a, b, "100m"));
 97:     expect(sorted).toEqual([10.95, 11.2, 11.8]);
 98:   });
 99: 
100:   it("Longueur : trié du plus loin au moins loin", () => {
101:     const sorted = [6.2, 7.1, 6.8].sort((a, b) => compareValues(a, b, "Longueur"));
102:     expect(sorted).toEqual([7.1, 6.8, 6.2]);
103:   });
104: 
105:   it("ne classe pas une épreuve libre dont le sens est inconnu", () => {
