245: });  1: import { useMemo, useState } from "react";
  2: import { BellRing, CheckCircle2, CircleDot, ClipboardCheck, Play, RotateCcw, Users } from "lucide-react";
  3: import { getSessionDayMessage, getSessionDaySummary } from "../../domain/sessionDay";
  4: 
  5: export default function CoachSessionDayPanel({
  6:   session, athletes, onSetCoachNote, onSetLifecycle, onRemindFeedback,
  7: }) {
  8:   const summary = useMemo(() => getSessionDaySummary(session), [session]);
  9:   const [busyKeys, setBusyKeys] = useState(() => new Set());
 10:   const [feedback, setFeedback] = useState(null);
 11:   const lifecycle = session.lifecycleStatus ?? "planned";
 12: 
 13:   const run = async (key, action, success) => {
 14:     if (busyKeys.has(key)) return;
 15:     setBusyKeys(previous => new Set(previous).add(key)); setFeedback(null);
 16:     try {
 17:       await action();
 18:       if (success) setFeedback({ type: "success", text: success });
 19:     } catch (error) {
 20:       setFeedback({ type: "error", text: error?.message || "La modification n’a pas pu être enregistrée." });
 21:     } finally {
 22:       setBusyKeys(previous => {
 23:         const next = new Set(previous);
 24:         next.delete(key);
 25:         return next;
 26:       });
 27:     }
 28:   };
 29: 
 30:   const metrics = [
 31:     { label: "Convoqués", value: summary.total, Icon: Users },
 32:     { label: "Retours reçus", value: `${summary.feedbackComplete}/${summary.total}`, Icon: ClipboardCheck },
 33:     { label: "Charge totale", value: summary.totalLoad || "—", Icon: CircleDot },
 34:   ];
 35: 
 36:   return (
 37:     <section className="rounded-2xl border overflow-hidden" style={{ borderColor: "rgba(77,201,160,0.25)", background: "linear-gradient(145deg, rgba(29,158,117,0.10), rgba(91,141,239,0.05))" }}>
 38:       <div className="p-4 border-b" style={{ borderColor: "var(--c-border)" }}>
 39:         <div className="flex flex-wrap items-start justify-between gap-3">
 40:           <div>
 41:             <p className="meta-text font-bold uppercase tracking-wide" style={{ color: "var(--tone-success)" }}>Jour de séance</p>
 42:             <h3 className="mt-1 text-[15px] font-bold" style={{ color: "var(--c-text-1)" }}>
 43:               {lifecycle === "completed" ? "Séance clôturée" : lifecycle === "live" ? "Séance en cours" : "Prête à démarrer"}
 44:             </h3>
 45:             <p className="mt-1 text-[13px]" style={{ color: "var(--c-text-2)" }}>{getSessionDayMessage(summary)}</p>
 46:           </div>
 47:           <div className="flex flex-wrap gap-2">
 48:             {lifecycle === "planned" && (
 49:               <button type="button" className="btn-secondary" disabled={busyKeys.size > 0}
 50:                 onClick={() => run("start", () => onSetLifecycle(session.id, "live"), "Le suivi de séance est ouvert.")}>
 51:                 <Play size={14} /> Démarrer
 52:               </button>
 53:             )}
 54:             {lifecycle === "live" && (
 55:               <button type="button" className="btn-primary" disabled={busyKeys.size > 0}
 56:                 onClick={() => run("close", () => onSetLifecycle(session.id, "completed"), "Séance clôturée et rappels envoyés.")}>
 57:                 <CheckCircle2 size={14} /> Clôturer
 58:               </button>
 59:             )}
 60:             {lifecycle === "completed" && (
 61:               <button type="button" className="btn-ghost" disabled={busyKeys.size > 0}
 62:                 onClick={() => run("reopen", () => onSetLifecycle(session.id, "live"), "La séance est de nouveau ouverte.")}>
 63:                 <RotateCcw size={14} /> Rouvrir
 64:               </button>
 65:             )}
 66:             {summary.feedbackMissing > 0 && (
 67:               <button type="button" className="btn-ghost" disabled={busyKeys.size > 0}
 68:                 onClick={() => run("remind", () => onRemindFeedback(session), "Rappel envoyé aux athlètes concernés.")}>
 69:                 <BellRing size={14} /> Rappeler ({summary.feedbackMissing})
 70:               </button>
 71:             )}
 72:           </div>
 73:         </div>
 74: 
 75:         <div className="grid grid-cols-3 gap-2 mt-4">
 76:           {metrics.map(({ label, value, Icon }) => (
 77:             <div key={label} className="rounded-xl border p-3" style={{ borderColor: "var(--c-border)", background: "var(--surface-recessed)" }}>
 78:               <Icon size={14} style={{ color: "var(--tone-success)" }} />
 79:               <p className="mt-2 text-[17px] font-bold" style={{ color: "var(--c-text-1)" }}>{value}</p>
 80:               <p className="meta-text mt-0.5">{label}</p>
 81:             </div>
 82:           ))}
 83:         </div>
 84:       </div>
 85: 
 86:       <div className="p-4 space-y-3">
 87:         <h4 className="text-[14px] font-bold" style={{ color: "var(--c-text-1)" }}>Athlètes convoqués</h4>
 88:         {session.athleteIds.map((athleteId) => {
 89:           const athlete = athletes.find((item) => item.id === athleteId);
 90:           const validation = session.validations?.find((item) => item.athleteId === athleteId) ?? {};
 91:           return (
 92:             <div key={athleteId} className="rounded-xl border p-3" style={{ borderColor: "var(--c-border)", background: "var(--c-surface-2)" }}>
 93:               <div className="flex items-center gap-2 mb-2.5">
 94:                 <div className="w-8 h-8 rounded-xl flex items-center justify-center text-[12px] font-bold" style={{ background: "var(--c-surface-3)", color: "var(--c-text-1)" }}>{athlete?.avatar ?? "?"}</div>
 95:                 <div className="min-w-0 flex-1">
 96:                   <p className="text-[13px] font-bold truncate" style={{ color: "var(--c-text-1)" }}>{athlete?.name ?? `Athlète #${athleteId}`}</p>
 97:                   {validation.rsvpStatus && <p className="meta-text">Réponse : {validation.rsvpStatus === "going" ? "présent prévu" : validation.rsvpStatus === "unavailable" ? "indisponible" : "incertain"}</p>}
 98:                 </div>
 99:               </div>
100:               {validation.rsvpNote && (
101:                 <p className="mb-2.5 min-h-9 rounded-lg px-3 py-2 text-[12px] leading-relaxed" style={{ color: "var(--c-text-2)", background: "rgba(91,141,239,0.08)", border: "1px solid rgba(91,141,239,0.18)" }}>
102:                   « {validation.rsvpNote} »
103:                 </p>
104:               )}
105:               <textarea defaultValue={validation.coachNote ?? ""} rows={1} maxLength={1000}
106:                 aria-label={`Observation coach pour ${athlete?.name ?? athleteId}`}
107:                 onBlur={(event) => {
108:                   const note = event.target.value.trim();
109:                   if (note !== (validation.coachNote ?? "")) run(`note-${athleteId}`, () => onSetCoachNote(session.id, athleteId, note));
110:                 }}
111:                 className="input-premium resize-none mt-2.5" placeholder="Observation coach facultative…" />
112:             </div>
113:           );
114:         })}
115:       </div>
116:       {feedback && <p role={feedback.type === "error" ? "alert" : "status"} className="mx-4 mb-4 rounded-xl px-3 py-2 text-[13px]" style={{ color: feedback.type === "error" ? "#F29B9A" : "#7BD8B4", background: feedback.type === "error" ? "rgba(226,75,74,0.10)" : "rgba(29,158,117,0.10)" }}>{feedback.text}</p>}
117:     </section>
118:   );
119: }  1: // Mesures de suivi descriptives affichées dans AthleteOS.
