128: function formatNumber(value) {
129:   return Number.isInteger(value) ? String(value) : Number(value).toFixed(2).replace(/\.00$/u, "");
130: }
131: 
132: export function getMonitoringReading(key, metrics = {}) {
133:   const definition = MONITORING_METRICS[key];
134:   if (!definition) return null;
135: 
136:   let value = null;
137:   let displayValue = "—";
138:   let unit = "";
139:   let interpretation = "Donnée indisponible.";
140:   let missingReason = "L'historique quotidien n'est pas encore assez complet.";
141: 
142:   if (key === "wellness") {
143:     value = metrics.wellnessScore;
144:     unit = "/100";
145:     if (value != null) {
146:       displayValue = formatNumber(value);
147:       interpretation = `Tes cinq réponses du jour donnent un résumé de ${displayValue}/100. Lis surtout ce qui t'aide et ce qui mérite ton attention.`;
148:     } else missingReason = "Le questionnaire AthleteOS du jour n'a pas encore été complété.";
149:   } else if (key === "load7" || key === "load28") {
150:     value = metrics[key];
151:     if (value != null) {
152:       displayValue = formatNumber(value);
153:       interpretation = key === "load7"
154:         ? `Tu as cumulé ${displayValue} points d'effort sur les 7 derniers jours.`
155:         : `Tu as cumulé ${displayValue} points d'effort sur les 4 dernières semaines. C'est ton rythme récent de comparaison.`;
156:     } else missingReason = `La fenêtre de ${key === "load7" ? 7 : 28} jours contient au moins un jour inconnu.`;
157:   } else if (key === "ewmaAcute" || key === "ewmaChronic") {
158:     value = key === "ewmaAcute" ? metrics.acute : metrics.chronic;
159:     if (value != null) {
160:       displayValue = formatNumber(value);
161:       interpretation = key === "ewmaAcute"
162:         ? `Le calcul donne davantage d'importance à tes tout derniers jours : ${displayValue}.`
163:         : `Le calcul lisse ton dernier mois pour obtenir une tendance plus stable : ${displayValue}.`;
164:     } else missingReason = "Aucune séquence quotidienne connue ne permet encore le lissage.";
165:   } else if (key === "variation") {
166:     value = metrics.variationPercent;
167:     unit = "%";
168:     if (value != null) {
169:       displayValue = `${value > 0 ? "+" : ""}${formatNumber(value)}`;
170:       const direction = value >= 10 ? "plus élevée que d'habitude" : value <= -10 ? "plus basse que d'habitude" : "stable par rapport à ton habitude";
171:       interpretation = `Ta charge est ${direction} (${displayValue} %). Le pourcentage explique l'écart ; ce n'est ni une note ni un seuil de danger.`;
172:     } else missingReason = "La comparaison demande 28 jours connus et une moyenne habituelle supérieure à zéro.";
173:   } else if (key === "monotony") {
174:     value = metrics.monotony;
175:     if (metrics.monotonyStatus === "undefined_zero_variance") {
176:       displayValue = "Indéfinie";
177:       interpretation = "Tes sept journées ont exactement la même charge. L'écart-type est nul : le calcul mathématique ne peut donc pas produire un nombre utile.";
178:       missingReason = null;
179:     } else if (value != null) {
180:       displayValue = formatNumber(value);
181:       interpretation = `Ce nombre décrit à quel point les charges de tes sept journées se ressemblent : ${displayValue}. Il ne juge pas la qualité du programme.`;
182:     } else missingReason = "Sept charges quotidiennes connues sont nécessaires.";
183:   } else if (key === "spacing") {
184:     const recovery = metrics.recovery;
185:     if (recovery?.status === "window_elapsed") {
186:       displayValue = "Terminée";
187:       interpretation = "La fenêtre d'espacement configurée est terminée ; cela ne prouve pas une récupération complète.";
188:       missingReason = null;
189:     } else if (recovery?.rangeHoursMin != null && recovery?.rangeHoursMax != null) {
190:       displayValue = `${recovery.rangeHoursMin}–${recovery.rangeHoursMax}`;
191:       unit = "h";
192:       interpretation = `Il reste ${displayValue} h dans la fenêtre de programmation configurée.`;
193:       missingReason = null;
194:     } else missingReason = "Aucune séance récente avec date, heure et statut validé n'est disponible.";
195:   } else if (key === "dataQuality") {
196:     value = Math.min(metrics.observedDays ?? 0, 28);
197:     displayValue = `${value}/28`;
198:     interpretation = metrics.known28
199:       ? "Tous les jours nécessaires sont renseignés : la comparaison peut être lue correctement."
200:       : metrics.known7
201:         ? "Cette semaine est complète, mais il manque encore des jours dans le mois de comparaison."
202:         : "Il manque au moins un jour récent. Confirme les repos et complète les durées et efforts ressentis.";
203:     missingReason = null;
204:   } else if (key === "acwrExperimental") {
205:     value = metrics.acwr;
206:     if (value != null) {
207:       displayValue = Number(value).toFixed(2);
208:       interpretation = `Ratio expérimental observé : ${displayValue}. Aucune catégorie de risque n'est appliquée.`;
209:     } else missingReason = "Le ratio reste masqué tant que 28 jours consécutifs ne sont pas connus ou que l'EWMA longue vaut zéro.";
210:   }
211: 
212:   return {
213:     key,
214:     ...definition,
215:     value,
216:     displayValue,
217:     unit,
218:     available: missingReason == null || value != null,
219:     interpretation,
220:     missingReason,
221:   };
222: }
