229: function formatPercent(value) {
230:   return `${value > 0 ? "+" : ""}${Math.round(value)} %`;
231: }
232: 
233: /**
234:  * Traduit les mesures descriptives en une histoire courte destinée à
235:  * l'athlète. Les seuils servent uniquement à choisir des mots lisibles : ils
236:  * ne définissent ni une zone optimale, ni un danger, ni une prescription.
237:  */
238: export function getAthleteLoadStory(metrics = {}, sessions = [], athleteId, now = new Date()) {
239:   const variation = Number.isFinite(metrics.variationPercent) ? metrics.variationPercent : null;
240:   let headline = "Complète ton historique de charge";
241:   let summary = "Il manque encore quelques jours renseignés pour comparer cette semaine à tes habitudes.";
242:   let tone = "neutral";
243: 
244:   if (variation != null) {
245:     if (variation >= 25) {
246:       headline = "Ta charge est nettement plus élevée que d’habitude";
247:       summary = `Ta moyenne quotidienne a augmenté de ${formatPercent(variation)} par rapport aux 3 semaines précédentes.`;
248:       tone = "up";
249:     } else if (variation >= 10) {
250:       headline = "Ta charge est un peu plus élevée que d’habitude";
251:       summary = `Ta moyenne quotidienne a augmenté de ${formatPercent(variation)} par rapport aux 3 semaines précédentes.`;
252:       tone = "up";
253:     } else if (variation <= -25) {
254:       headline = "Ta charge a nettement diminué cette semaine";
255:       summary = `Ta moyenne quotidienne a diminué de ${Math.abs(Math.round(variation))} % par rapport aux 3 semaines précédentes.`;
256:       tone = "down";
257:     } else if (variation <= -10) {
258:       headline = "Ta charge a un peu diminué cette semaine";
259:       summary = `Ta moyenne quotidienne a diminué de ${Math.abs(Math.round(variation))} % par rapport aux 3 semaines précédentes.`;
260:       tone = "down";
261:     } else {
262:       headline = "Ta charge est stable";
263:       summary = "Ta moyenne quotidienne reste proche de celle de tes 3 semaines précédentes.";
264:       tone = "stable";
265:     }
266:   }
267: 
268:   const end = new Date(now);
269:   end.setHours(23, 59, 59, 999);
270:   const start = new Date(end);
271:   start.setDate(start.getDate() - 6);
272:   start.setHours(0, 0, 0, 0);
273:   const contributions = (sessions ?? [])
274:     .map((session) => {
275:       const validation = session.validations?.find((item) => item.athleteId === athleteId);
276:       const date = session.sessionDate ? new Date(`${String(session.sessionDate).slice(0, 10)}T12:00:00`) : null;
277:       const duration = Number(validation?.actualDurationMinutes);
278:       const rpe = Number(validation?.rpe);
279:       const load = Number.isFinite(duration) && duration > 0 && Number.isFinite(rpe) && rpe >= 0 && rpe <= 10
280:         ? Math.round(duration * rpe)
281:         : null;
282:       return { session, validation, date, load, rpe };
283:     })
284:     .filter((item) => item.date && item.date >= start && item.date <= end && item.load != null)
285:     .sort((a, b) => b.date - a.date);
286: 
287:   const total = contributions.reduce((sum, item) => sum + item.load, 0);
288:   const lastTwo = contributions.slice(0, 2);
289:   const lastTwoShare = total > 0 ? Math.round((lastTwo.reduce((sum, item) => sum + item.load, 0) / total) * 100) : null;
290:   let cause = contributions.length
291:     ? `${contributions.length} séance${contributions.length > 1 ? "s" : ""} renseignée${contributions.length > 1 ? "s" : ""} expliquent la charge de cette semaine.`
292:     : "Renseigne la durée réellement effectuée et ton effort après les séances pour voir ce qui influence la courbe.";
293: 
294:   if (lastTwo.length === 2 && lastTwoShare >= 55) {
295:     cause = `Tes deux dernières séances représentent ${lastTwoShare} % de la charge de cette semaine.`;
296:   }
297: 
298:   const hardSessions = contributions.filter((item) => item.rpe >= 7);
299:   if (hardSessions.length >= 2) {
300:     const gapDays = Math.abs(hardSessions[0].date - hardSessions[1].date) / 86_400_000;
301:     if (gapDays <= 2) {
302:       cause = `Tu as enchaîné ${hardSessions.length} séances ressenties difficiles sur une période courte. Parles-en avec ton coach si ce rythme ne correspond pas au programme.`;
303:     }
304:   }
305: 
306:   return {
307:     headline,
308:     summary,
309:     cause,
310:     tone,
311:     variationLabel: variation == null ? "Comparaison indisponible" : formatPercent(variation),
312:     convention: "AthleteOS considère la charge stable entre −10 % et +10 %. Ces repères servent à expliquer la courbe, pas à définir un risque ou une zone idéale.",
313:   };
314: }  1: // ============================================================
