16: export function ScoreRing({ value, color, label, size = 72 }) {
17:   const radius = 28;
18:   const circumference = 2 * Math.PI * radius;
19:   const dash = (Math.max(0, Math.min(100, value)) / 100) * circumference;
20:   return (
