  3: import { getISOWeekInfo, parseLocalDate } from "./helpers.js";
  4: // AthleteOS — trainingLoad.js
  5: // Calcul de la charge d'entraînement selon la méthode session-RPE
  6: // ============================================================
  7: //
  8: // 📚 RÉFÉRENCES SCIENTIFIQUES (méthode centrale) :
  9: // - Foster C, Florhaug JA, Franklin J, et al. (2001). "A New Approach
 10: //   to Monitoring Exercise Training." Journal of Strength and
 11: //   Conditioning Research, 15(1), 109-115.
 12: // - Foster C. (1998). "Monitoring training in athletes with reference
 13: //   to overtraining syndrome." Medicine & Science in Sports & Exercise,
 14: //   30(7), 1164-1168.
 15: // - Borg G. (1998). Borg's Perceived Exertion and Pain Scales.
 16: //   Human Kinetics. (Origine de l'échelle RPE 0-10 / CR10)
 17: //
 18: // AJOUTS v2.0 :
 19: // - Williams S, Booton T, Watson M, et al. (2017).
 20: //   → EWMA supérieur à la moyenne mobile simple
 21: // - Hasegawa T, et al. (2024). PeerJ 12:e17443.
 22: //   → Mesures aiguës après sprint ; ne valide pas des délais fixes de récupération.
 23: // - Saw AE, Main LC, Gastin PB. (2016). BJSM 50(5), 281-291.
 24: //   → Wellness questionnaire = mesure la plus sensible et fiable
 25: //
 26: // FORMULE CENTRALE (directement issue de Foster et al., validée par
 27: // de nombreuses études en sciences du sport) :
 28: //
 29: //     Charge de séance = Durée (minutes) × RPE (0-10)
 30: //
 31: // Où RPE = Rate of Perceived Exertion, noté par l'athlète lui-même
 32: // sur une échelle de 0 (repos total) à 10 (effort maximal), quelques
 33: // minutes après la fin de la séance.
 34: //
 35: // ⚠️ TRANSPARENCE IMPORTANTE :
 36: // La charge globale n'applique aucun coefficient de catégorie. Les
 37: // contraintes spécifiques sont des dimensions descriptives séparées.
 38: //
 39: // ⚠️ SOURCE CANONIQUE : ces constantes DOIVENT rester identiques
 40: // à la version active de la table Postgres `charge_model_versions`
 41: // (migration 20260727040000_charge_model_versioning.sql) — c'est cette
 42: // table, pas ce fichier, qui fait foi pour le calcul serveur (vue SQL
 43: // weekly_charge) et pour la reproductibilité historique (chaque ligne
 44: // session_athletes garde la version active au moment où son RPE a été
 45: // saisi, jamais recalculée si la version change plus tard). Ce fichier
 46: // reste une copie JS nécessaire au calcul instantané côté client (avant
 47: // même l'enregistrement d'un RPE) — la parité entre les deux est vérifiée
 48: // par test_charge_model_parity.mjs. Changer une valeur ici SANS créer une
 49: // nouvelle version dans charge_model_versions casse cette parité et doit
 50: // être considéré comme un bug, pas une simple config.
 51: // ============================================================
 52: 
 53: export const CURRENT_MODEL_VERSION = "v2-session-rpe-standard";
 54: 
 55: /**
 56:  * Compatibilité avec les formulaires historiques qui enregistrent encore
 57:  * `load_weight`. La charge session-RPE globale n'utilise plus ces valeurs :
 58:  * les contraintes spécifiques sont exposées séparément dans loadAxes.js.
 59:  */
 60: export const LOAD_COEFFICIENTS = {
 61:   force: 1, sprint: 1, haies: 1, lancer: 1, saut: 1,
 62:   endurance: 1, technique: 1, mobilite: 1, recuperation: 1,
 63: };
 64: 
 65: // ─── AJOUT v2.0 : Temps de récupération par catégorie (heures) ───────────────
 66: // Valeurs historiques conservées comme règles d'espacement de programmation.
 67: // Elles sont configurables et ne constituent pas des temps physiologiques.
 68: export const RECOVERY_HOURS = {
 69:   sprint:       72,
 70:   haies:        72,
 71:   force:        72,
 72:   saut:         48,
 73:   lancer:       48,
 74:   endurance:    36,
 75:   technique:    24,
 76:   mobilite:     12,
 77:   recuperation: 12,
 78: };
 79: 
 80: /**
 81:  * Calcule la charge d'UNE séance pour UN athlète.
 82:  * @param {number} durationMinutes - Durée de la séance en minutes
 83:  * @param {number} rpe - Ressenti de l'athlète, 0 à 10 (échelle de Borg CR10)
 84:  * @returns {number|null} Charge arrondie, ou null si données manquantes
 85:  */
 86: export function computeSessionLoad(durationMinutes, rpe) {
 87:   if (durationMinutes == null || rpe == null) return null;
 88:   const duration = Number(durationMinutes);
 89:   const perceivedExertion = Number(rpe);
 90:   if (!Number.isFinite(duration) || duration <= 0) return null;
 91:   if (!Number.isFinite(perceivedExertion) || perceivedExertion < 0 || perceivedExertion > 10) return null;
 92:   return Math.round(duration * perceivedExertion);
 93: }
 94: 
 95: /**
 96:  * Calcule la charge hebdomadaire d'un athlète pour une semaine donnée,
 97:  * en sommant la charge de toutes ses séances de cette semaine où un RPE
 98:  * a été renseigné (les séances sans RPE ne comptent pas — pas de valeur
 99:  * inventée).
100:  */
101: function sessionIsoYear(session) {
102:   const explicit = Number(session?.isoYear ?? session?.iso_year);
103:   if (Number.isInteger(explicit)) return explicit;
104:   const dateValue = session?.sessionDate ?? session?.session_date;
105:   if (typeof dateValue === "string" && /^\d{4}-\d{2}-\d{2}/.test(dateValue)) {
106:     return getISOWeekInfo(parseLocalDate(dateValue.slice(0, 10))).year;
107:   }
108:   return null;
109: }
110: 
111: function sessionWeekKey(session) {
112:   const year = sessionIsoYear(session);
113:   return year == null ? `legacy-${session.week}` : `${year}-W${String(session.week).padStart(2, "0")}`;
114: }
115: 
116: export function computeWeeklyLoadFromSessions(athleteId, week, sessions, isoYear = null) {
117:   const weekSessions = sessions.filter((session) =>
118:     session.week === week
119:     && (isoYear == null || sessionIsoYear(session) == null || sessionIsoYear(session) === isoYear)
120:     && session.athleteIds.includes(athleteId)
121:   );
122: 
123:   let total = 0;
124:   let sessionCount = 0;
125:   let missingRpeCount = 0;
126: 
127:   weekSessions.forEach((s) => {
128:     const validation = s.validations?.find((v) => v.athleteId === athleteId);
129:     const rpe = validation?.rpe;
130:     if (rpe == null) {
131:       missingRpeCount += 1;
132:       return;
133:     }
134:     const duration = validation?.actualDurationMinutes;
135:     const load = computeSessionLoad(duration, rpe);
136:     if (load !== null) {
137:       total += load;
138:       sessionCount += 1;
139:     }
140:   });
141: 
142:   return { total, sessionCount, missingRpeCount };
143: }
144: 
145: /**
146:  * Calcule la charge hebdomadaire de TOUS les athlètes, pour TOUTES les
147:  * semaines présentes dans les séances fournies.
148:  */
149: export function computeAllWeeklyLoads(athletes, sessions) {
150:   const allWeeks = [...new Map(sessions.map((session) => [
151:     sessionWeekKey(session),
152:     { week: session.week, isoYear: sessionIsoYear(session) },
153:   ])).values()].sort((a, b) => (a.isoYear ?? 0) - (b.isoYear ?? 0) || a.week - b.week);
154:   const result = [];
155: 
156:   athletes.forEach((a) => {
157:     allWeeks.forEach(({ week, isoYear }) => {
158:       const { total, sessionCount } = computeWeeklyLoadFromSessions(a.id, week, sessions, isoYear);
159:       if (sessionCount > 0) {
160:         result.push({
161:           athleteId: a.id,
162:           week,
163:           rawLoad: total,
164:           ...(isoYear == null ? {} : { isoYear }),
165:         });
166:       }
167:     });
168:   });
169: 
170:   return result;
171: }
172: 
173: /**
174:  * Ventile la charge du GROUPE par semaine ET par catégorie de séance.
175:  */
176: export function computeWeeklyLoadByCategory(athletes, sessions) {
177:   const allWeeks = [...new Map(sessions.map((session) => [
178:     sessionWeekKey(session),
179:     { key: sessionWeekKey(session), week: session.week, isoYear: sessionIsoYear(session) },
180:   ])).values()].sort((a, b) => (a.isoYear ?? 0) - (b.isoYear ?? 0) || a.week - b.week);
181:   const result = [];
182: 
183:   allWeeks.forEach(({ key, week, isoYear }) => {
184:     const weekSessions = sessions.filter((session) => sessionWeekKey(session) === key);
185:     const byCategory = {};
186: 
187:     weekSessions.forEach((s) => {
188:       s.athleteIds.forEach((athleteId) => {
189:         const validation = s.validations?.find((v) => v.athleteId === athleteId);
190:         const rpe = validation?.rpe;
191:         if (rpe == null) return;
192:         const duration = validation?.actualDurationMinutes;
193:         const load = computeSessionLoad(duration, rpe);
194:         if (load === null) return;
195:         byCategory[s.category] = (byCategory[s.category] ?? 0) + load;
196:       });
197:     });
198: 
199:     Object.entries(byCategory).forEach(([category, total]) => {
200:       result.push({ week, category, total, ...(isoYear == null ? {} : { isoYear }) });
201:     });
202:   });
203: 
204:   return result;
205: }
