207: // ─── AJOUT v2.0 : Interprétation du RPE (Borg CR10) ──────────────────────────
208: // Borg G. (1998). Borg's Perceived Exertion and Pain Scales. Human Kinetics.
209: export function getRPELabel(rpe) {
210:   if (rpe == null) return { label: "Non renseigné", color: "#94a3b8" };
211:   if (rpe === 0)   return { label: "Repos",          color: "#94a3b8" };
212:   if (rpe <= 2)    return { label: "Très facile",    color: "#1D9E75" };
213:   if (rpe <= 4)    return { label: "Facile",         color: "#1D9E75" };
214:   if (rpe <= 6)    return { label: "Modéré",         color: "#EF9F27" };
215:   if (rpe <= 8)    return { label: "Difficile",      color: "#EF9F27" };
216:   if (rpe <= 9)    return { label: "Très difficile", color: "var(--tone-danger)" };
217:   return                  { label: "Maximum",        color: "var(--tone-danger)" };
218: }
219: 
220: // ─── AJOUT v2.0 : EWMA (Exponentially Weighted Moving Average) ───────────────
221: // Williams S, et al. (2017). International Journal of Sports Physiology
222: // and Performance.
223: // λ courte = 2/(7+1) ; λ longue = 2/(28+1). Ces paramètres supposent
224: // strictement un point par JOUR, jamais un total hebdomadaire déguisé.
225: const LAMBDA_ACUTE   = 2 / (7  + 1);
226: const LAMBDA_CHRONIC = 2 / (28 + 1);
227: 
228: export function computeEWMA(dailyLoads) {
229:   const ordered = (dailyLoads ?? [])
230:     .filter((point) => point?.date)
231:     .map((point) => ({ ...point, load: point.load == null ? null : Number(point.load) }))
232:     .sort((a, b) => String(a.date).localeCompare(String(b.date)));
233:   if (!ordered.length) {
234:     return { acute: null, chronic: null, acwr: null, ewmaHistory: [], observedDays: 0, status: "insufficient_data" };
235:   }
236: 
237:   // Une valeur inconnue casse la continuité : l'algorithme reprend au
238:   // prochain point connu, mais aucun ratio n'est publié avant 28 nouveaux
239:   // jours consécutifs. On ne transforme jamais silencieusement null en 0.
240:   let ewmaAcute = null;
241:   let ewmaChronic = null;
242:   let observedDays = 0;
243:   const history   = [];
244: 
245:   for (const { date, load } of ordered) {
246:     if (!Number.isFinite(load) || load < 0) {
247:       ewmaAcute = null;
248:       ewmaChronic = null;
249:       observedDays = 0;
250:       history.push({ date, load: null, acute: null, chronic: null });
251:       continue;
252:     }
253:     if (ewmaAcute == null || ewmaChronic == null) {
254:       ewmaAcute = load;
255:       ewmaChronic = load;
256:     } else {
257:       ewmaAcute   = load * LAMBDA_ACUTE   + ewmaAcute   * (1 - LAMBDA_ACUTE);
258:       ewmaChronic = load * LAMBDA_CHRONIC + ewmaChronic * (1 - LAMBDA_CHRONIC);
259:     }
260:     observedDays += 1;
261:     history.push({ date, load, acute: Math.round(ewmaAcute), chronic: Math.round(ewmaChronic) });
262:   }
263: 
264:   const enoughForExperimentalRatio = observedDays >= 28 && ewmaChronic > 0;
265:   const acwr = enoughForExperimentalRatio ? ewmaAcute / ewmaChronic : null;
266:   return {
267:     acute:       ewmaAcute == null ? null : Math.round(ewmaAcute),
268:     chronic:     ewmaChronic == null ? null : Math.round(ewmaChronic),
269:     acwr:        acwr == null ? null : Math.round(acwr * 100) / 100,
270:     ewmaHistory: history,
271:     observedDays,
272:     status: enoughForExperimentalRatio ? "experimental" : "insufficient_data",
273:   };
274: }
275: 
276: function toDateKey(value) {
277:   if (!value) return null;
278:   const match = String(value).match(/^(\d{4}-\d{2}-\d{2})/u);
279:   return match?.[1] ?? null;
280: }
281: 
282: function addUtcDays(dateKey, amount) {
283:   const date = new Date(`${dateKey}T00:00:00Z`);
284:   date.setUTCDate(date.getUTCDate() + amount);
285:   return date.toISOString().slice(0, 10);
286: }
287: 
288: function isoWeekFromDateKey(dateKey) {
289:   const date = new Date(`${dateKey}T00:00:00Z`);
290:   date.setUTCDate(date.getUTCDate() + 4 - (date.getUTCDay() || 7));
291:   const yearStart = new Date(Date.UTC(date.getUTCFullYear(), 0, 1));
292:   return Math.ceil((((date - yearStart) / 86400000) + 1) / 7);
293: }
294: 
295: function endOfIsoWeek(dateKey) {
296:   const date = new Date(`${dateKey}T00:00:00Z`);
297:   return addUtcDays(dateKey, 7 - (date.getUTCDay() || 7));
298: }
299: 
300: function localTodayKey() {
301:   const today = new Date();
302:   return `${today.getFullYear()}-${String(today.getMonth() + 1).padStart(2, "0")}-${String(today.getDate()).padStart(2, "0")}`;
303: }
304: 
305: /** Construit une série civile continue. Les dates absentes restent `null`. */
306: export function buildContinuousDailyLoadSeries(points, startDate, endDate) {
307:   const normalized = new Map();
308:   (points ?? []).forEach((point) => {
309:     const date = toDateKey(point?.date);
310:     if (!date) return;
311:     const load = point.load == null || point.estimated ? null : Number(point.load);
312:     normalized.set(date, Number.isFinite(load) && load >= 0 ? load : null);
313:   });
314:   const keys = [...normalized.keys()].sort();
315:   const start = toDateKey(startDate) ?? keys[0] ?? null;
316:   const end = toDateKey(endDate) ?? keys.at(-1) ?? null;
317:   if (!start || !end || start > end) return [];
318: 
319:   const series = [];
320:   for (let date = start; date <= end; date = addUtcDays(date, 1)) {
321:     series.push({ date, load: normalized.has(date) ? normalized.get(date) : null });
322:   }
323:   return series;
324: }
325: 
326: /** Extrait les jours détaillés fournis par la vue SQL weekly_charge v2. */
327: export function extractDailyLoads(athleteId, weeklyCharge, currentWeek, cutoffDate = null) {
328:   const rows = (weeklyCharge ?? [])
329:     .filter((row) => row.athleteId === athleteId);
330:   const points = rows.flatMap((row) => row.dailyLoads ?? []);
331:   if (!points.length) return [];
332: 
333:   const today = localTodayKey();
334:   let end = toDateKey(cutoffDate);
335:   if (!end && currentWeek != null) {
336:     const matchingDates = points
337:       .map((point) => toDateKey(point.date))
338:       .filter((date) => date && date <= today && isoWeekFromDateKey(date) === currentWeek)
339:       .sort();
340:     if (matchingDates.length) end = endOfIsoWeek(matchingDates.at(-1));
341:   }
342:   if (!end) end = today;
343:   if (end > today && !cutoffDate) end = today;
344: 
345:   const start = addUtcDays(end, -55);
346:   return buildContinuousDailyLoadSeries(points, start, end);
347: }
348: 
349: export function computeLoadWindows(dailyLoads) {
350:   const last = (dailyLoads ?? []).slice(-28);
351:   const last7 = last.slice(-7);
352:   const known7 = last7.length === 7 && last7.every((point) => Number.isFinite(point.load));
353:   const known28 = last.length === 28 && last.every((point) => Number.isFinite(point.load));
354:   const load7 = known7 ? last7.reduce((sum, point) => sum + point.load, 0) : null;
355:   const load28 = known28 ? last.reduce((sum, point) => sum + point.load, 0) : null;
356:   const previous21 = known28 ? last.slice(0, 21) : [];
357:   const recentDailyAverage = load7 == null ? null : load7 / 7;
358:   const habitualDailyAverage = known28
359:     ? previous21.reduce((sum, point) => sum + point.load, 0) / 21
360:     : null;
361:   const variationPercent = habitualDailyAverage > 0
362:     ? Math.round(((recentDailyAverage - habitualDailyAverage) / habitualDailyAverage) * 100)
363:     : null;
364:   return { load7, load28, recentDailyAverage, habitualDailyAverage, variationPercent, known7, known28 };
365: }
366: 
367: // ─── AJOUT v2.0 : Monotonie et Contrainte ────────────────────────────────────
368: // Foster C. (1998). Medicine & Science in Sports & Exercise, 30(7), 1164-1168.
369: // Monotonie  = charge_moyenne / écart-type
370: // Contrainte = charge_totale × monotonie
371: export function computeMonotonyAndStrain(dailyLoads) {
372:   if (!Array.isArray(dailyLoads) || dailyLoads.length !== 7 || dailyLoads.some((value) => !Number.isFinite(value) || value < 0)) {
373:     return { monotony: null, strain: null, status: "insufficient_data" };
374:   }
375:   const mean = dailyLoads.reduce((a, b) => a + b, 0) / 7;
376:   const sd = Math.sqrt(dailyLoads.reduce((acc, value) => acc + Math.pow(value - mean, 2), 0) / 7);
377:   if (sd === 0) return { monotony: null, strain: null, status: "undefined_zero_variance" };
378:   const monotony = Math.round((mean / sd) * 100) / 100;
379:   return { monotony, strain: Math.round(dailyLoads.reduce((a, b) => a + b, 0) * monotony), status: "available" };
380: }
381: 
382: // AthleteOS Wellness Questionnaire v1 — instrument interne non validé.
383: // Il ne doit pas être présenté comme le Hooper Index, qui utilise quatre
384: // dimensions différentes. Les cinq réponses 1..5 sont normalisées sur 0..100.
385: export function computeWellnessScore(wellness) {
386:   if (!wellness) return null;
387:   const { sleep, energy, soreness, mood, stress } = wellness;
388:   if ([sleep, energy, soreness, mood, stress].some(v => v == null)) return null;
389:   const normalizedMean = (sleep + energy + (6 - soreness) + mood + (6 - stress)) / 5;
390:   const score = ((normalizedMean - 1) / 4) * 100;
391:   return Math.round(Math.max(0, Math.min(100, score)));
392: }
393: 
394: // Règles de programmation configurables — pas des temps physiologiques.
395: // Elles servent uniquement à espacer deux séances ciblant une même
396: // contrainte. Le nom historique est conservé pour compatibilité d'import.
397: export const RECOVERY_HOURS_RANGE = {
398:   sprint:       { min: 48, max: 96 },  // centre historique 72h
399:   haies:        { min: 48, max: 96 },
400:   force:        { min: 48, max: 96 },
401:   saut:         { min: 32, max: 64 },  // centre historique 48h
402:   lancer:       { min: 32, max: 64 },
403:   endurance:    { min: 24, max: 48 },  // centre historique 36h
404:   technique:    { min: 16, max: 32 },  // centre historique 24h
405:   mobilite:     { min: 6,  max: 18 },  // centre historique 12h
406:   recuperation: { min: 6,  max: 18 },
407: };
408: 
409: function sessionEndDate(session, actualDurationMinutes) {
410:   if (!session?.sessionDate || !session?.time) return null;
411:   const time = String(session.time).match(/^(\d{1,2}):(\d{2})/u);
412:   if (!time) return null;
413:   const end = new Date(`${String(session.sessionDate).slice(0, 10)}T00:00:00`);
414:   end.setHours(Number(time[1]), Number(time[2]), 0, 0);
415:   const duration = Number(actualDurationMinutes);
416:   if (Number.isFinite(duration) && duration > 0) end.setMinutes(end.getMinutes() + duration);
417:   return Number.isNaN(end.getTime()) ? null : end;
418: }
419: 
420: /**
421:  * Fenêtre de programmation après la dernière séance. Le paramètre `wellness`
422:  * reste accepté pour ne casser aucun appel, mais n'allonge ni ne raccourcit
423:  * la règle : AthleteOS ne prétend plus estimer une récupération biologique.
424:  */
425: export function estimateRecovery(sessions, athleteId, _wellness = null, now = new Date(), rules = RECOVERY_HOURS_RANGE) {
426:   const doneSessions = (sessions ?? [])
427:     .map(s => {
428:       const v = s.validations?.find(x => x.athleteId === athleteId);
429:       const endAt = v?.status === "done" || v?.status === "partial"
430:         ? sessionEndDate(s, v.actualDurationMinutes)
431:         : null;
432:       return endAt ? { ...s, validation: v, endAt } : null;
433:     })
434:     .filter(Boolean)
435:     .sort((a, b) => b.endAt - a.endAt);
436: 
437:   if (!doneSessions.length) {
438:     return {
439:       status: "insufficient_data", kind: "programming_rule", confidence: null, confidenceScore: null,
440:       rangeHoursMin: null, rangeHoursMax: null, lastSession: null, factors: [], ruleSource: "club_default",
441:     };
442:   }
443: 
444:   const last = doneSessions[0];
445:   const range = rules[last.category] ?? rules.technique ?? { min: 24, max: 48 };
446:   const hoursElapsed = Math.max(0, (now - last.endAt) / 3_600_000);
447:   const rangeHoursMin = Math.max(0, Math.round(range.min - hoursElapsed));
448:   const rangeHoursMax = Math.max(0, Math.round(range.max - hoursElapsed));
449:   const status = rangeHoursMax === 0 ? "window_elapsed" : rangeHoursMin > 0 ? "spacing_active" : "spacing_transition";
450:   return {
451:     status,
452:     kind: "programming_rule",
453:     confidence: null,
454:     confidenceScore: null,
455:     rangeHoursMin,
456:     rangeHoursMax,
457:     lastSession: last,
458:     factors: [{ label: `Règle ${last.category || "générale"} configurée : ${range.min}–${range.max} h`, direction: "neutral" }],
459:     ruleSource: "club_default",
460:   };
461: }  1: // ============================================================
  2: // AthleteOS — src/utils/weeklyReports.js
  3: //
  4: // Logique de calcul des rapports hebdomadaires — utilisée à la fois
  5: // par le module coach (src/modules/Rapports.jsx) et la vue athlète
  6: // (src/athlete/views/MesRapports.jsx), pour ne jamais faire diverger
  7: // les deux. Pas de nouvelle table : tout est recalculé à la volée
  8: // depuis sessions/session_athletes (déjà chargés par les vues
  9: // existantes) + athlete_wellness pour la semaine concernée.
 10: //
 11: // Toutes les charges passent par computeSessionLoad (chargeCalculations.js
 12: // → trainingLoad.js), la même formule que la vue SQL weekly_charge —
 13: // aucun nouveau calcul de charge inventé ici.
 14: // ============================================================
 15: 
 16: import { computeSessionLoad, computeWellnessScore, getAthleteMetricsForWeek } from "./chargeCalculations";
 17: import { CATEGORIES } from "../athlete/shared";
 18: import { getISOWeekInfo, matchesISOWeek, parseLocalDate } from "./helpers.js";
 19: 
 20: // ─── Semaines disponibles ─────────────────────────────────────────────────
 21: // Liste triée (desc) des semaines ISO présentes dans les séances,
 22: // avec la plage de dates réelle (basée sur session_date, pas un calcul
 23: // d'arithmétique de calendrier) et le nombre de séances qu'elle contient.
 24: export function getAvailableWeeks(sessions, athleteId = null) {
 25:   const relevant = athleteId
 26:     ? sessions.filter(s => s.athleteIds?.includes(athleteId))
 27:     : sessions;
 28: 
 29:   const byWeek = new Map();
 30:   relevant.forEach(s => {
 31:     if (!s.sessionDate) return;
 32:     const { week, year } = getISOWeekInfo(parseLocalDate(s.sessionDate));
 33:     const key = `${year}-W${String(week).padStart(2, "0")}`;
 34:     if (!byWeek.has(key)) byWeek.set(key, { week, isoYear: year, sessions: [] });
 35:     byWeek.get(key).sessions.push(s);
 36:   });
 37: 
 38:   return [...byWeek.entries()]
 39:     .map(([key, { week, isoYear, sessions: weekSessions }]) => {
 40:       const dates = weekSessions.map(s => s.sessionDate).filter(Boolean).sort();
 41:       return {
 42:         key, week, isoYear,
 43:         sessionCount: weekSessions.length,
 44:         dateRange: dates.length ? { start: dates[0], end: dates[dates.length - 1] } : null,
 45:       };
 46:     })
 47:     .sort((a, b) => b.key.localeCompare(a.key));
 48: }
 49: 
 50: export function formatWeekLabel(week, dateRange, isoYear = null) {
 51:   if (!dateRange) return `Semaine ${week}${isoYear ? ` · ${isoYear}` : ""}`;
 52:   const opts = { day: "numeric", month: "short" };
 53:   const start = new Date(dateRange.start + "T00:00:00").toLocaleDateString("fr-BE", opts);
 54:   const end   = new Date(dateRange.end   + "T00:00:00").toLocaleDateString("fr-BE", { ...opts, year: "numeric" });
 55:   return `Semaine ${week} — ${start} au ${end}`;
 56: }
