 58: // ─── Résumé texte automatique ─────────────────────────────────────────────
 59: function buildSummaryText({ total, done, partial, none, totalLoad, categoriesWorked, categoriesAbsent, load7, load28, variationPercent }) {
 60:   if (total === 0) return "Aucune séance planifiée cette semaine.";
 61:   const lines = [];
 62: 
 63:   lines.push(
 64:     `${done}/${total} séance${total > 1 ? "s" : ""} réalisée${done > 1 ? "s" : ""}` +
 65:     (partial ? `, ${partial} partielle${partial > 1 ? "s" : ""}` : "") +
 66:     (none ? `, ${none} manquée${none > 1 ? "s" : ""}` : "") + "."
 67:   );
 68: 
 69:   lines.push(`Effort cumulé cette semaine : ${totalLoad} points (durée réelle × effort ressenti).`);
 70: 
 71:   if (categoriesWorked.length) {
 72:     const top = categoriesWorked.slice(0, 2).map(c => CATEGORIES.find(x => x.id === c.id)?.label ?? c.id);
 73:     lines.push(`Catégories les plus travaillées : ${top.join(", ")}.`);
 74:   }
 75:   if (categoriesAbsent.length && categoriesAbsent.length < CATEGORIES.length) {
 76:     const absentLabels = categoriesAbsent.map(id => CATEGORIES.find(c => c.id === id)?.label ?? id);
 77:     lines.push(`Non travaillées : ${absentLabels.join(", ")}.`);
 78:   }
 79: 
 80:   if (load7 != null && load28 != null) {
 81:     const direction = variationPercent == null
 82:       ? "La comparaison avec l'habitude n'est pas encore disponible."
 83:       : variationPercent >= 10
 84:         ? `La charge est plus élevée que l'habitude (+${variationPercent} %).`
 85:         : variationPercent <= -10
 86:           ? `La charge est plus basse que l'habitude (${variationPercent} %).`
 87:           : `La charge est stable par rapport à l'habitude (${variationPercent >= 0 ? "+" : ""}${variationPercent} %).`;
 88:     lines.push(`${direction} Cette semaine : ${load7} points ; quatre dernières semaines : ${load28} points.`);
 89:   }
 90: 
 91:   return lines.join(" ");
 92: }
