 94: // ─── Rapport hebdomadaire d'un athlète ────────────────────────────────────
 95: // @param athleteId    number
 96: // @param week         number (semaine ISO)
 97: // @param sessions     séances mappées (voir Dashboard.jsx / AthleteApp.jsx)
 98: // @param weeklyCharge [{ athleteId, week, rawLoad }]
 99: // @param wellnessRows [{ athleteId, date, sleep, energy, soreness, mood, stress }] — déjà filtré sur la plage de la semaine par l'appelant
100: export function buildWeeklyReport({ athleteId, week, isoYear, sessions, weeklyCharge, wellnessRows = [] }) {
101:   const weekSessions = sessions
102:     .filter(s => matchesISOWeek(s, week, isoYear) && s.athleteIds?.includes(athleteId))
103:     .map(s => {
104:       const v = s.validations?.find(x => x.athleteId === athleteId) ?? {};
105:       const load = v.rpe != null ? computeSessionLoad(v.actualDurationMinutes, v.rpe, s.category) : null;
106:       return {
107:         id: s.id, title: s.title, category: s.category, trainingFocus: s.trainingFocus, day: s.day,
108:         sessionDate: s.sessionDate, durationMinutes: s.durationMinutes,
109:         actualDurationMinutes: v.actualDurationMinutes ?? null,
110:         durationSource: v.durationSource ?? null,
111:         status: v.status ?? null, rpe: v.rpe ?? null, feeling: v.feeling ?? null,
112:         comment: v.comment ?? null, load,
113:       };
114:     })
115:     .sort((a, b) => (a.sessionDate || "").localeCompare(b.sessionDate || ""));
116: 
117:   const total   = weekSessions.length;
118:   const done    = weekSessions.filter(s => s.status === "done").length;
119:   const partial = weekSessions.filter(s => s.status === "partial").length;
120:   const none    = weekSessions.filter(s => s.status === "none").length;
121:   const totalLoad = weekSessions.reduce((sum, s) => sum + (s.load ?? 0), 0);
122: 
123:   const byCategory = {};
124:   weekSessions.forEach(s => { if (s.load) byCategory[s.category] = (byCategory[s.category] ?? 0) + s.load; });
125:   const categoriesWorked = Object.entries(byCategory)
126:     .sort((a, b) => b[1] - a[1])
127:     .map(([id, load]) => ({ id, load, label: CATEGORIES.find(c => c.id === id)?.label ?? id }));
128:   const workedIds = new Set(categoriesWorked.map(c => c.id));
129:   const categoriesAbsent = CATEGORIES.filter(c => !workedIds.has(c.id)).map(c => c.id);
130: 
131:   const wellnessForAthlete = wellnessRows.filter(w => (
132:     w.athleteId === athleteId && w.date && matchesISOWeek(w, week, isoYear)
133:   ));
134:   const wellnessScores = wellnessForAthlete.map(w => computeWellnessScore(w)).filter(v => v != null);
135:   const wellnessAvg = wellnessScores.length
136:     ? Math.round(wellnessScores.reduce((a, b) => a + b, 0) / wellnessScores.length)
137:     : null;
138: 
139:   const dates = weekSessions.map(s => s.sessionDate).filter(Boolean).sort();
140:   const dateRange = dates.length ? { start: dates[0], end: dates[dates.length - 1] } : null;
141:   const cutoffDate = dates.length ? getISOWeekInfo(parseLocalDate(dates[0])).endDate : null;
142:   const athleteSessions = sessions.filter(s => (
143:     s.athleteIds?.includes(athleteId) && (!cutoffDate || !s.sessionDate || s.sessionDate <= cutoffDate)
144:   ));
145:   const chargeThroughWeek = weeklyCharge.filter(row => {
146:     if (row.athleteId !== athleteId) return false;
147:     if (row.isoYear == null) return row.week <= week;
148:     return row.isoYear < isoYear || (row.isoYear === isoYear && row.week <= week);
149:   });
150:   const metrics = getAthleteMetricsForWeek(
151:     athleteId, chargeThroughWeek, week, wellnessForAthlete, athleteSessions, cutoffDate,
152:   );
153: 
154:   const summary = buildSummaryText({
155:     total, done, partial, none, totalLoad, categoriesWorked, categoriesAbsent,
156:     load7: metrics.load7, load28: metrics.load28, variationPercent: metrics.variationPercent,
157:   });
158: 
159:   return {
160:     week, isoYear, dateRange, sessions: weekSessions,
161:     stats: { total, done, partial, none, totalLoad },
162:     categoriesWorked, categoriesAbsent, wellnessAvg, metrics, summary,
163:   };
164: }
