166: // ─── Agrégat "Vue Mois" — 4 dernières semaines, par athlète ───────────────
167: export function buildMonthlyAggregate({ athleteId, weeks, sessions, weeklyCharge, wellnessRows = [] }) {
168:   const sorted = [...weeks].sort((a, b) => a.key.localeCompare(b.key)); // ascendant : plus ancienne → plus récente
169:   const weeklyReports = sorted.map(({ week, isoYear }) => (
170:     buildWeeklyReport({ athleteId, week, isoYear, sessions, weeklyCharge, wellnessRows })
171:   ));
172: 
173:   const totalLoad     = weeklyReports.reduce((s, r) => s + r.stats.totalLoad, 0);
174:   const sessionsTotal = weeklyReports.reduce((s, r) => s + r.stats.total, 0);
175:   const doneTotal     = weeklyReports.reduce((s, r) => s + r.stats.done, 0);
176: 
177:   const byCategory = {};
178:   weeklyReports.forEach(r => r.categoriesWorked.forEach(c => {
179:     byCategory[c.id] = (byCategory[c.id] ?? 0) + c.load;
180:   }));
181:   const categoriesWorked = Object.entries(byCategory)
182:     .sort((a, b) => b[1] - a[1])
183:     .map(([id, load]) => ({ id, load, label: CATEGORIES.find(c => c.id === id)?.label ?? id }));
184: 
185:   const mid = Math.ceil(weeklyReports.length / 2);
186:   const firstHalf  = weeklyReports.slice(0, mid).reduce((s, r) => s + r.stats.totalLoad, 0);
187:   const secondHalf = weeklyReports.slice(mid).reduce((s, r) => s + r.stats.totalLoad, 0);
188:   const trend = weeklyReports.length < 2
189:     ? "flat"
190:     : firstHalf === 0
191:     ? (secondHalf > 0 ? "up" : "flat")
192:     : (secondHalf > firstHalf * 1.1 ? "up" : secondHalf < firstHalf * 0.9 ? "down" : "flat");
193: 
194:   return { weeks: weeklyReports, totalLoad, sessionsTotal, doneTotal, categoriesWorked, trend };
195: }  1: #!/usr/bin/env node
  2: // ============================================================
  3: // AthleteOS — test_private_storage.mjs
  4: //
  5: // Vérifie en conditions réelles que les buckets privés session-pdfs et
  6: // club-branding respectent leurs frontières de club et de rôle :
  7: //   1. Upload coach autorisé (club A, dossier club A).
  8: //   2. Upload athlète autorisé (club A, dossier club A) — mêmes règles
  9: //      que le coach, c'est le comportement existant (auto-planification).
 10: //   3. Téléchargement par un autre club refusé : ni createSignedUrl(),
 11: //      ni .list(), ni l'ancienne URL publique (le bucket n'est plus public).
 12: //   4. Une URL signée expire (TTL 1s) et devient inutilisable après.
 13: //   5. Les pièces jointes usuelles (PDF, images et Word) sont acceptées, tandis
 14: //      qu'un Content-Type hors liste est rejeté par le bucket.
 15: //   + Limite de taille (file_size_limit) appliquée côté serveur.
 16: //   + Round-trip complet : upload → createSignedUrl → fetch → 200.
 17: //   6. club-branding : seul un head coach peut écrire/supprimer ; tous les
 18: //      membres du même club peuvent lire, jamais un autre club.
 19: //   7. club-branding : MIME image et limite de 5 Mo imposés par le bucket.
 20: //
 21: // Note honnête : Supabase Storage ne fait PAS de sniffing du contenu
 22: // réel du fichier, seulement du Content-Type déclaré à l'upload. Un
 23: // fichier renommé avec un Content-Type mensonger passerait le contrôle serveur.
 24: // Le client vérifie désormais les signatures usuelles avant l'envoi ; une
 25: // inspection incontestable demanderait une Edge Function dédiée. Les uploads
 26: // viennent de comptes authentifiés du club (coach/athlète), pas d'un
 27: // dépôt public anonyme (cf. tâche 8 : quarantaine/antivirus seulement
 28: // "si des documents externes sont acceptés à grande échelle" — non le cas).
 29: //
 30: // Crée deux clubs et quatre comptes éphémères, nettoie tout à la fin.
 31: //
 32: // Usage :
 33: //   SUPABASE_SERVICE_ROLE_KEY=... node test_private_storage.mjs
 34: // ============================================================
