 41: function loadDotEnv(filePath) {
 42:   let text;
 43:   try { text = readFileSync(filePath, "utf8"); } catch { return; }
 44:   for (const rawLine of text.split("\n")) {
 45:     const line = rawLine.replace(/\r$/, "");
 46:     const m = line.match(/^([A-Z0-9_]+)=(.*)$/);
 47:     if (m && process.env[m[1]] === undefined) process.env[m[1]] = m[2].trim();
 48:   }
 49: }
 50: loadDotEnv(path.join(path.dirname(fileURLToPath(import.meta.url)), ".env"));
