 79: async function makeUser(email, password, clubId, role, name) {
 80:   const { data: a, error: ea } = await admin.auth.admin.createUser({ email, password, email_confirm: true });
 81:   if (ea) throw new Error(`createUser ${email} : ${ea.message}`);
 82:   const u = await insertOrThrow("users", { club_id: clubId, name, email, role, auth_uid: a.user.id });
 83:   const client = createClient(SUPABASE_URL, ANON_KEY, { auth: { autoRefreshToken: false, persistSession: false } });
 84:   const { error: es } = await client.auth.signInWithPassword({ email, password });
 85:   if (es) throw new Error(`signIn ${email} : ${es.message}`);
 86:   return { auth: a.user, row: u, client };
 87: }
