317:     // storage-js, pas le query builder postgrest-js) — .catch() est valide
318:     // ici, contrairement à admin.from(table)... (déjà rencontré tâches 3/4/14).
319:     if (uploadedPaths.length) await admin.storage.from("session-pdfs").remove(uploadedPaths).catch(() => {});
320:     if (brandingPaths.length) await admin.storage.from("club-branding").remove(brandingPaths).catch(() => {});
321:     for (const u of auths) {
322:       if (!u) continue;
323:       await u.client.auth.signOut().catch(() => {});
324:       await admin.from("athletes").delete().eq("user_id", u.row.id);
325:       await admin.from("users").delete().eq("id", u.row.id);
326:       await admin.auth.admin.deleteUser(u.auth.id).catch(() => {});
327:     }
328:     if (clubA) await admin.from("clubs").delete().eq("id", clubA.id);
329:     if (clubB) await admin.from("clubs").delete().eq("id", clubB.id);
330:   }
331: 
332:   const failed = results.filter((r) => !r.pass);
333:   console.log(`\n${results.length - failed.length}/${results.length} vérifications OK`);
334:   if (failed.length) {
335:     console.error(`\n${failed.length} régression(s) détectée(s) :`);
336:     failed.forEach((f) => console.error(`  - ${f.name}${f.detail ? " : " + f.detail : ""}`));
337:     process.exit(1);
338:   }
339:   console.log("\nStockage privé session-pdfs et club-branding conforme.");
340:   process.exit(0);
341: }
