 36: function Toast({ msg, onDismiss }) {
 37:   useEffect(() => { const t = setTimeout(onDismiss, 4000); return () => clearTimeout(t); }, [onDismiss]);
 38:   return (
 39:     <div style={{ position:"fixed", top:16, left:"50%", transform:"translateX(-50%)", zIndex:9999, maxWidth:340, width:"calc(100% - 32px)", animation:"slide-down 0.25s cubic-bezier(0.16,1,0.3,1)" }}>
 40:       <div style={{ background:"var(--c-surface-3)", border:"1px solid var(--c-border-strong)", borderRadius:14, padding:"12px 14px", display:"flex", alignItems:"center", gap:10, boxShadow:"0 8px 32px rgba(0,0,0,0.50)" }}>
 41:         <div style={{ width:36, height:36, borderRadius:"50%", background:msg.color??"#1D9E75", display:"flex", alignItems:"center", justifyContent:"center", color:"white", fontSize:12, fontWeight:700, flexShrink:0 }}>
 42:           {initialsFromName(msg.name)}
 43:         </div>
 44:         <p style={{ flex:1, fontSize:13, color:"var(--c-text-1)", lineHeight:1.4 }}>
 45:           <span style={{ color:"#1D9E75", fontWeight:600 }}>{msg.name.split(" ")[0]}</span> {msg.action}
 46:         </p>
 47:         <button type="button" aria-label="Fermer la notification" onClick={onDismiss} style={{ width:44, height:44, display:"flex", alignItems:"center", justifyContent:"center", background:"none", border:"none", cursor:"pointer", color:"var(--c-text-2)", padding:0, flexShrink:0 }}><X size={16}/></button>
 48:       </div>
 49:     </div>
 50:   );
 51: }
