 54: const CommentsModal = memo(({ post, athlete, allAthletes, onClose, onCommentAdded }) => {
 55:   const [comments, setComments] = useState([]);
 56:   const [input, setInput]       = useState("");
 57:   const [loading, setLoading]   = useState(true);
 58:   const [sending, setSending]   = useState(false);
 59:   const [error, setError]       = useState(null);
 60:   const endRef = useRef(null);
 61:   const { dialogRef } = useAccessibleDialog({ onClose });
 62: 
 63:   useEffect(() => {
 64:     supabase.from("social_comments").select("*").eq("post_id", post.id).order("created_at", { ascending:true })
 65:       .then(({ data }) => { setComments(data ?? []); setLoading(false); });
 66:   }, [post.id]);
 67: 
 68:   useEffect(() => {
 69:     const ch = supabase.channel(`com-${post.id}`)
 70:       .on("postgres_changes", { event:"INSERT", schema:"public", table:"social_comments", filter:`post_id=eq.${post.id}` },
 71:         p => setComments(prev => prev.some(c => c.id===p.new.id) ? prev : [...prev, p.new]))
 72:       .subscribe();
 73:     return () => supabase.removeChannel(ch);
 74:   }, [post.id]);
 75: 
 76:   useEffect(() => { endRef.current?.scrollIntoView({ behavior:"smooth" }); }, [comments.length]);
 77: 
 78:   const send = async () => {
 79:     const text = input.trim(); if (!text) return;
 80:     setSending(true); setError(null);
 81:     const { data, error: sendError } = await supabase.from("social_comments")
 82:       .insert({ post_id:post.id, athlete_id:athlete.id, content:text }).select().single();
 83:     if (sendError) {
 84:       setError("Le commentaire n’a pas pu être envoyé. Réessaie.");
 85:       setSending(false);
 86:       return;
 87:     }
 88:     if (data) {
 89:       setInput("");
 90:       setComments(prev => prev.some(comment => comment.id === data.id) ? prev : [...prev, data]);
 91:       onCommentAdded();
 92:     }
 93:     setSending(false);
 94:   };
 95: 
 96:   const postAthlete = allAthletes.find(a => a.id===post.athlete_id);
 97: 
 98:   // Portal sur document.body : sinon, sur mobile, un ancêtre en scroll fait
 99:   // dériver ce position:fixed hors de l'écran — même bug déjà rencontré et
100:   // corrigé sur FormeDetailPanel.jsx.
101:   return createPortal(
102:     <div style={{ position:"fixed", inset:0, zIndex:9999, display:"flex", flexDirection:"column", background:"rgba(0,0,0,0.75)", backdropFilter:"blur(12px)" }}
103:       onClick={e => e.target===e.currentTarget && onClose()}>
104:       <div ref={dialogRef} tabIndex={-1} role="dialog" aria-modal="true" aria-labelledby="comments-title" style={{ marginTop:"auto", width:"100%", maxWidth:640, alignSelf:"center", background:"var(--c-surface)", borderRadius:"24px 24px 0 0", border:"1px solid var(--c-border)", display:"flex", flexDirection:"column", maxHeight:"88dvh" }}>
105:         {/* Handle */}
106:         <div style={{ display:"flex", justifyContent:"center", padding:"10px 0 4px" }}>
107:           <div style={{ width:32, height:3, borderRadius:99, background:"var(--c-border-strong)" }}/>
108:         </div>
109: 
110:         {/* Header */}
111:         <div style={{ padding:"8px 16px 10px", borderBottom:"1px solid var(--c-border)", display:"flex", alignItems:"center", justifyContent:"space-between", flexShrink:0 }}>
112:           <div style={{ display:"flex", alignItems:"center", gap:9 }}>
113:             <div style={{ width:36, height:36, borderRadius:"50%", background:avatarColor(allAthletes, post.athlete_id), display:"flex", alignItems:"center", justifyContent:"center", color:"white", fontSize:12, fontWeight:700 }}>
114:               {initialsFromName(postAthlete?.name ?? "?")}
115:             </div>
116:             <div>
117:               <p style={{ fontSize:13, fontWeight:700, color:"var(--c-text-1)" }}>{postAthlete?.name?.split(" ")[0]}</p>
118:               <h2 id="comments-title" style={{ fontSize:12, color:"var(--c-text-2)" }}>Commentaires</h2>
119:             </div>
120:           </div>
121:           <button type="button" aria-label="Fermer" onClick={onClose} style={{ width:44, height:44, display:"flex", alignItems:"center", justifyContent:"center", borderRadius:12, background:"var(--c-surface-2)", border:"1px solid var(--c-border)", cursor:"pointer", color:"var(--c-text-2)" }}><X size={17}/></button>
122:         </div>
123: 
124:         {/* Preview post */}
125:         {post.image_url && (
126:           <div style={{ flexShrink:0, maxHeight:160, overflow:"hidden" }}>
127:             <img src={post.image_url} alt="" style={{ width:"100%", objectFit:"cover", maxHeight:160 }}/>
128:           </div>
129:         )}
130:         {post.content && (
131:           <div style={{ padding:"8px 16px", background:"var(--c-surface-2)", borderBottom:"1px solid var(--c-border)", flexShrink:0 }}>
132:             <p style={{ fontSize:12, color:"var(--c-text-2)", lineHeight:1.4 }} className="line-clamp-2">{post.content}</p>
133:           </div>
134:         )}
135: 
136:         {/* Liste commentaires */}
137:         <div style={{ flex:1, overflowY:"auto", padding:"12px 16px", display:"flex", flexDirection:"column", gap:10 }}>
138:           {loading ? (
139:             <div style={{ textAlign:"center", padding:24 }}><div className="loader-ring" style={{ margin:"0 auto" }}/></div>
140:           ) : comments.length===0 ? (
141:             <p style={{ textAlign:"center", padding:"24px 0", fontSize:13, color:"var(--c-text-2)" }}>Aucun commentaire — sois le premier !</p>
142:           ) : comments.map(c => {
143:             const ca    = allAthletes.find(a => a.id===c.athlete_id);
144:             const isOwn = c.athlete_id===athlete.id;
145:             const diff  = (Date.now()-new Date(c.created_at))/1000;
146:             const ago   = diff<60?"À l'instant":diff<3600?`${Math.floor(diff/60)}min`:`${Math.floor(diff/3600)}h`;
147:             return (
148:               <div key={c.id} style={{ display:"flex", gap:8, flexDirection:isOwn?"row-reverse":"row" }}>
149:                 <div style={{ width:32, height:32, borderRadius:"50%", background:isOwn?"#1D9E75":avatarColor(allAthletes, c.athlete_id), display:"flex", alignItems:"center", justifyContent:"center", color:"white", fontSize:12, fontWeight:700, flexShrink:0 }}>
150:                   {initialsFromName(ca?.name ?? "?")}
151:                 </div>
152:                 <div style={{ maxWidth:"78%" }}>
153:                   <div style={{ background:isOwn?"rgba(29,158,117,0.12)":"var(--c-surface-2)", border:`1px solid ${isOwn?"rgba(29,158,117,0.18)":"var(--c-border)"}`, borderRadius:isOwn?"14px 14px 4px 14px":"14px 14px 14px 4px", padding:"7px 11px" }}>
154:                     {!isOwn && <p style={{ fontSize:12, fontWeight:700, color:avatarColor(allAthletes, c.athlete_id), marginBottom:3 }}>{ca?.name?.split(" ")[0]}</p>}
155:                     <p style={{ fontSize:13, color:"var(--c-text-1)", lineHeight:1.5 }}>{c.content}</p>
156:                   </div>
157:                   <p style={{ fontSize:12, color:"var(--c-text-3)", marginTop:3, paddingLeft:4 }}>{ago}</p>
158:                 </div>
159:               </div>
160:             );
161:           })}
162:           <div ref={endRef}/>
163:         </div>
164: 
165:         {/* Input */}
166:         <div style={{ padding:"10px 12px", paddingBottom:"calc(10px + env(safe-area-inset-bottom))", borderTop:"1px solid var(--c-border)", display:"flex", alignItems:"center", gap:8, background:"var(--c-surface)", flexShrink:0 }}>
167:           <div style={{ width:32, height:32, borderRadius:"50%", background:"#1D9E75", display:"flex", alignItems:"center", justifyContent:"center", color:"white", fontSize:12, fontWeight:700, flexShrink:0 }}>
168:             {initialsFromName(athlete.name)}
169:           </div>
170:           <div style={{ flex:1, background:"var(--c-surface-2)", borderRadius:20, padding:"8px 14px", border:"1px solid var(--c-border)" }}>
171:             <input style={{ width:"100%", background:"none", border:"none", outline:"none", fontSize:13, color:"var(--c-text-1)" }}
172:               placeholder="Ajouter un commentaire…" value={input}
173:               maxLength={300}
174:               onChange={e => setInput(e.target.value)}
175:               onKeyDown={e => { if (e.key==="Enter") { e.preventDefault(); send(); } }}
176:               autoFocus/>
177:           </div>
178:           <button type="button" aria-label="Envoyer le commentaire" onClick={send} disabled={!input.trim()||sending}
179:             style={{ width:44, height:44, borderRadius:"50%", background:"#1D9E75", border:"none", cursor:"pointer", display:"flex", alignItems:"center", justifyContent:"center", opacity:(!input.trim()||sending)?0.35:1, flexShrink:0, boxShadow:"0 2px 8px rgba(29,158,117,0.25)" }}>
180:             <Send size={16} color="white" strokeWidth={2.5}/>
181:           </button>
182:         </div>
183:         {error && <p role="alert" style={{ padding:"0 16px 12px", fontSize:12, color:"var(--tone-danger)" }}>{error}</p>}
184:       </div>
185:     </div>,
186:     document.body
187:   );
188: });
