191: const QuickPostModal = memo(({ session, athlete, allAthletes, clubId, coachUserId, onClose, onPosted }) => {
192:   const [image,    setImage]    = useState(null);
193:   const [preview,  setPreview]  = useState(null);
194:   const [caption,  setCaption]  = useState(session ? `Séance "${session.title}" ✅` : "");
195:   const [posting,  setPosting]  = useState(false);
196:   const [err,      setErr]      = useState(null);
197:   const { dialogRef } = useAccessibleDialog({ onClose, closeDisabled: posting });
198:   const pickImage = e => {
199:     const f = e.target.files?.[0]; if (!f) return;
200:     const validationError = validateSocialImage(f);
201:     if (validationError) {
202:       setImage(null);
203:       setPreview(null);
204:       setErr(validationError);
205:       e.target.value = "";
206:       return;
207:     }
208:     setErr(null);
209:     setImage(f); setPreview(URL.createObjectURL(f));
210:   };
211: 
212:   useEffect(() => () => {
213:     if (preview) URL.revokeObjectURL(preview);
214:   }, [preview]);
215: 
216:  const post = async () => {
217:     setPosting(true); setErr(null);
218:     try {
219:       let imageUrl = null;
220:       if (image) {
221:         const ext  = image.name.split(".").pop() || "jpg";
222:         // Préfixé par club_id — requis par les policies storage scopées par
223:         // club (sinon l'upload est rejeté par RLS).
224:         const path = `${clubId}/${athlete.id}-${Date.now()}.${ext}`;
225:         const { error:ue } = await supabase.storage.from("social-photos").upload(path, image);
226:         if (ue) throw new Error(ue.message);
227:         const { data:ud } = supabase.storage.from("social-photos").getPublicUrl(path);
228:         imageUrl = ud?.publicUrl ?? null;
229:       }
230: 
231:       const { error: postErr } = await supabase.from("social_posts").insert({
232:         athlete_id: athlete.id, club_id: clubId,
233:         session_id: session?.id ?? null,
234:         content:    caption.trim(), // social_posts.content est NOT NULL — jamais null, "" au pire
235:         image_url:  imageUrl,
236:       });
237:       if (postErr) throw new Error(postErr.message);
238: 
239:       // Notifier les autres athlètes (pas le coach)
240:       const otherAthletes = allAthletes.filter(a => a.id !== athlete.id && a.user_id);
241:       if (otherAthletes.length > 0) {
242: 
243:         // 1. Sauvegarde dans ta base de données (Ton Code 2)
244:         const { error: notifErr } = await supabase.from("athlete_notifications").insert(
245:           otherAthletes.map(a => ({
246:             athlete_id:  a.id,
247:             club_id:     clubId,
248:             type:        "social",
249:             title:       `${athlete.name.split(" ")[0]} a partagé une séance`,
250:             description: caption.trim() || `Séance ${session?.title ?? ""}`,
251:             is_read:     false,
252:           }))
253:         );
254:         if (notifErr) console.warn("Notification sociale non enregistrée:", notifErr.message);
255: 
256:         // 2. L'alerte de notification (Ton Code 1) 👇
257:         const otherAthleteIds = otherAthletes.map(a => a.id);
258:         notifyClubNewPost(clubId, athlete.name, otherAthleteIds).catch(console.warn);
259:       }
260: 
261:       await notifyCoachClubPost(clubId, coachUserId, athlete, {
262:         hasPhoto: Boolean(imageUrl),
263:         caption: caption.trim(),
264:       });
265: 
266:       onPosted(); onClose();
267:     } catch(e) {
268:       setErr(e.message);
269:       setPosting(false);
270:     }
271:   };
272: 
273:   // Portal sur document.body : même raison que CommentsModal ci-dessus —
274:   // sans ça, sur mobile, ce position:fixed dérive avec le scroll du fil et
275:   // les boutons "Prendre une photo"/"Choisir dans la galerie" se retrouvent
276:   // tout en bas de la page au lieu de rester à l'écran.
277:   return createPortal(
278:     <div style={{ position:"fixed", inset:0, zIndex:9999, display:"flex", flexDirection:"column", background:preview?"#000":"rgba(0,0,0,0.75)", backdropFilter:preview?"none":"blur(12px)" }}
279:       onClick={e => e.target===e.currentTarget && !posting && onClose()}>
280: 
281:       {preview ? (
282:         /* Mode plein écran photo */
283:         <div ref={dialogRef} tabIndex={-1} role="dialog" aria-modal="true" aria-label="Prévisualiser la publication" style={{ flex:1, display:"flex", flexDirection:"column" }}>
284:           {/* Image plein écran */}
285:           <div style={{ flex:1, position:"relative", overflow:"hidden" }}>
286:             <img src={preview} alt="" style={{ width:"100%", height:"100%", objectFit:"cover" }}/>
287:             {/* Overlay haut */}
288:             <div style={{ position:"absolute", top:0, left:0, right:0, padding:"14px 14px", display:"flex", alignItems:"center", justifyContent:"space-between", background:"linear-gradient(to bottom, rgba(0,0,0,0.55), transparent)" }}>
289:               <button type="button" aria-label="Retirer la photo" onClick={() => { setImage(null); setPreview(null); }}
290:                 style={{ width:44, height:44, borderRadius:"50%", background:"rgba(0,0,0,0.45)", border:"1px solid rgba(255,255,255,0.14)", cursor:"pointer", color:"white", display:"flex", alignItems:"center", justifyContent:"center" }}>
291:                 <X size={18}/>
292:               </button>
293:               <label style={{ minHeight:44, padding:"0 14px", borderRadius:22, background:"rgba(0,0,0,0.45)", border:"1px solid rgba(255,255,255,0.14)", color:"white", fontSize:13, fontWeight:700, cursor:"pointer", display:"flex", alignItems:"center", gap:7 }}>
294:                 <Camera size={15}/> Changer
295:                 <input type="file" accept="image/*" style={{ display:"none" }} onChange={pickImage}/>
296:               </label>
297:             </div>
298:           </div>
299: 
300:           {/* Zone saisie + publier */}
301:           <div style={{ background:"#0D0D0D", padding:"12px 14px", paddingBottom:"calc(12px + env(safe-area-inset-bottom))", display:"flex", flexDirection:"column", gap:10 }}>
302:             {err && <p role="alert" style={{ fontSize:13, color:"var(--tone-danger)" }}>{err}</p>}
303:             {session && (
304:               <div style={{ display:"flex", alignItems:"center", gap:6, padding:"6px 10px", borderRadius:8, background:"rgba(29,158,117,0.12)", border:"1px solid rgba(29,158,117,0.20)" }}>
305:                 <div style={{ width:6, height:6, borderRadius:"50%", background:"#1D9E75", flexShrink:0 }}/>
306:                 <p style={{ fontSize:12, color:"var(--tone-success)", fontWeight:700 }}>{session.title}</p>
307:               </div>
308:             )}
309:             <div style={{ display:"flex", alignItems:"center", gap:10 }}>
310:               <div style={{ width:36, height:36, borderRadius:"50%", background:"#1D9E75", display:"flex", alignItems:"center", justifyContent:"center", color:"white", fontSize:12, fontWeight:700, flexShrink:0 }}>
311:                 {initialsFromName(athlete.name)}
312:               </div>
313:               <input
314:                 style={{ flex:1, background:"rgba(255,255,255,0.10)", border:"none", outline:"none", borderRadius:20, padding:"9px 14px", fontSize:13.5, color:"white", lineHeight:1.4 }}
315:                 placeholder="Ajouter une légende…"
316:                 value={caption} onChange={e => setCaption(e.target.value)}
317:                 maxLength={500}
318:                 autoFocus
319:               />
320:             </div>
321:             <button type="button" onClick={post} disabled={posting}
322:               style={{ width:"100%", minHeight:48, padding:"0 16px", borderRadius:12, background:"#1D9E75", border:"none", cursor:"pointer", color:"white", fontSize:14, fontWeight:700, display:"flex", alignItems:"center", justifyContent:"center", gap:8, boxShadow:"0 4px 14px rgba(29,158,117,0.32)", opacity:posting?0.7:1 }}>
323:               {posting ? <><div style={{ width:16, height:16, border:"2.5px solid rgba(255,255,255,0.3)", borderTopColor:"white", borderRadius:"50%", animation:"spin-smooth 0.65s linear infinite" }}/> Envoi en cours…</> : "Partager avec le club"}
324:             </button>
325:           </div>
326:         </div>
327:       ) : (
328:         /* Mode choix photo */
329:         <div ref={dialogRef} tabIndex={-1} role="dialog" aria-modal="true" aria-labelledby="quick-post-title" style={{ marginTop:"auto", width:"100%", maxWidth:560, alignSelf:"center", background:"var(--c-surface)", borderRadius:"24px 24px 0 0", border:"1px solid var(--c-border)", display:"flex", flexDirection:"column", overflow:"hidden", maxHeight:"82dvh" }}>
330:           <div style={{ display:"flex", justifyContent:"center", padding:"10px 0 4px" }}>
331:             <div style={{ width:32, height:3, borderRadius:99, background:"var(--c-border-strong)" }}/>
332:           </div>
333:           <div style={{ padding:"12px 16px", borderBottom:"1px solid var(--c-border)", display:"flex", alignItems:"center", justifyContent:"space-between" }}>
334:             <div>
335:               <h2 id="quick-post-title" style={{ fontSize:17, fontWeight:700, color:"var(--c-text-1)" }}>Partager avec le club</h2>
336:               {session && <p style={{ fontSize:12, color:"var(--tone-success)", marginTop:3 }}>{session.title}</p>}
337:             </div>
338:             <button type="button" aria-label="Fermer" onClick={onClose} style={{ width:44, height:44, display:"flex", alignItems:"center", justifyContent:"center", borderRadius:12, background:"var(--c-surface-2)", border:"1px solid var(--c-border)", cursor:"pointer", color:"var(--c-text-2)" }}><X size={18}/></button>
339:           </div>
340: 
341:           <div style={{ padding:"20px 16px", display:"flex", flexDirection:"column", gap:10, paddingBottom:"calc(20px + env(safe-area-inset-bottom))" }}>
342:             {err && <p role="alert" style={{ fontSize:13, color:"var(--tone-danger)", background:"rgba(224,82,82,0.08)", borderRadius:10, padding:"10px 12px" }}>{err}</p>}
343: 
344:             <div>
345:               <label htmlFor="club-post-caption" style={{ display:"block", fontSize:12, fontWeight:700, color:"var(--c-text-2)", textTransform:"uppercase", letterSpacing:"0.06em", marginBottom:8 }}>Message</label>
346:               <textarea id="club-post-caption" className="input-premium resize-none" rows={3}
347:                 placeholder="Partage une séance, une sensation ou un encouragement…"
348:                 maxLength={500}
349:                 value={caption} onChange={event => setCaption(event.target.value)} />
350:             </div>
351: 
352:             {/* Bouton caméra — action principale */}
353:             <label style={{ minHeight:52, display:"flex", alignItems:"center", justifyContent:"center", gap:10, padding:"0 18px", borderRadius:14, background:"linear-gradient(135deg, #1D9E75, #16826C)", cursor:"pointer", color:"white", fontSize:15, fontWeight:700, boxShadow:"0 4px 14px rgba(29,158,117,0.28)" }}>
354:               <Camera size={22} color="white"/>
355:               Prendre une photo
356:               <input type="file" accept="image/*" capture="environment" style={{ display:"none" }} onChange={pickImage}/>
357:             </label>
358: 
359:             {/* Galerie */}
360:             <label style={{ minHeight:48, display:"flex", alignItems:"center", justifyContent:"center", gap:8, padding:"0 14px", borderRadius:12, background:"var(--c-surface-2)", border:"1px solid var(--c-border)", cursor:"pointer", color:"var(--c-text-2)", fontSize:13, fontWeight:700 }}>
361:               <Image size={16}/>
362:               Choisir dans la galerie
363:               <input type="file" accept="image/*" style={{ display:"none" }} onChange={pickImage}/>
364:             </label>
365: 
366:             {/* Publier sans photo */}
367:             <button type="button" onClick={post} disabled={posting || !caption.trim()}
368:               style={{ minHeight:48, padding:"0 14px", borderRadius:12, background:"transparent", border:"1px solid var(--c-border)", cursor:"pointer", color:"var(--c-text-2)", fontSize:13, fontWeight:700, opacity:posting || !caption.trim() ? 0.45 : 1 }}>
369:               {posting ? "Envoi…" : "Publier sans photo"}
370:             </button>
371:           </div>
372:         </div>
373:       )}
374:     </div>,
375:     document.body
376:   );
377: });
