379: // ─── Card post Instagram ──────────────────────────────────────────────────────
380: const AUTO_CELEBRATION_CONFIG = {
381:   record: { icon: Trophy, color: "var(--tone-warning)", label: "Nouveau record personnel", gradient: "linear-gradient(135deg, #7B5104 0%, #9A6800 50%, #C8890A 100%)" },
382:   goal:   { icon: Target, color: "#7C67C8", label: "Objectif atteint",         gradient: "linear-gradient(135deg, #362A5C 0%, #4A3780 50%, #7C67C8 100%)" },
383: };
384: 
385: const PostCard = memo(({ post, athlete, allAthletes, sessions, onComment, onReact, onDelete, commentCount }) => {
386:   const postAthlete = allAthletes.find(a => a.id===post.athlete_id);
387:   const isOwn       = post.athlete_id===athlete.id;
388:   const linkedSess  = sessions.find(s => s.id===post.session_id);
389:   const myReaction  = post.social_reactions?.find(r => r.athlete_id===athlete.id);
390:   const totalLikes  = (post.social_reactions ?? []).length;
391:   const color       = avatarColor(allAthletes, post.athlete_id);
392:   const autoCfg     = AUTO_CELEBRATION_CONFIG[post.auto_type] ?? null;
393:   const [confirmDelete, setConfirmDelete] = useState(false);
394: 
395:   const diff    = (Date.now() - new Date(post.created_at)) / 1000;
396:   const timeAgo = diff<60?"À l'instant":diff<3600?`${Math.floor(diff/60)}min`:diff<86400?`${Math.floor(diff/3600)}h`:`${Math.floor(diff/86400)}j`;
397: 
398:   const rxCounts = {};
399:   (post.social_reactions ?? []).forEach(r => { rxCounts[r.emoji] = (rxCounts[r.emoji]??0)+1; });
400:   const topReactions = Object.entries(rxCounts).sort((a,b)=>b[1]-a[1]).slice(0,3);
401: 
402:   return (
403:     <article id={`post-${post.id}`} className="card" style={{ overflow:"hidden", scrollMarginTop:80 }}>
404:       {/* Header auteur — traitement distinct pour les posts auto-générés
405:           (record battu / objectif atteint), pour qu'ils se distinguent
406:           visuellement des photos partagées manuellement */}
407:       {autoCfg ? (
408:         <div className="animate-scale-in" style={{ position:"relative", overflow:"hidden", padding:"18px 16px 16px", background:autoCfg.gradient }}>
409:           {/* Halo décoratif — même langage que les cards héro du dashboard */}
410:           <div style={{ position:"absolute", right:-22, top:-22, width:110, height:110, borderRadius:"50%", background:"rgba(255,255,255,0.08)", pointerEvents:"none" }} />
411:           <div style={{ position:"relative", display:"flex", alignItems:"flex-start", justifyContent:"space-between", gap:12 }}>
412:             <div style={{ display:"flex", alignItems:"center", gap:12 }}>
413:               <div style={{ width:42, height:42, borderRadius:12, background:"rgba(255,255,255,0.14)", display:"flex", alignItems:"center", justifyContent:"center", flexShrink:0 }}>
414:                 <autoCfg.icon size={19} color="white" strokeWidth={1.8} />
415:               </div>
416:               <div>
417:                 <p style={{ fontSize:12, fontWeight:700, letterSpacing:"0.07em", textTransform:"uppercase", color:"rgba(255,255,255,0.72)" }}>{autoCfg.label}</p>
418:                 <p style={{ fontSize:15, fontWeight:700, color:"white", marginTop:4 }}>{postAthlete?.name ?? "Athlète"}</p>
419:               </div>
420:             </div>
421:             {isOwn && (
422:               <button type="button" aria-label="Supprimer la publication" onClick={() => setConfirmDelete(true)} style={{ width:44, height:44, display:"flex", alignItems:"center", justifyContent:"center", background:"rgba(255,255,255,0.10)", border:"1px solid rgba(255,255,255,0.10)", borderRadius:12, cursor:"pointer", color:"rgba(255,255,255,0.82)", flexShrink:0 }}><X size={16}/></button>
423:             )}
424:           </div>
425:           <p style={{ position:"relative", fontSize:15, fontWeight:500, color:"white", marginTop:14, lineHeight:1.4 }}>{post.content}</p>
426:           <p style={{ position:"relative", fontSize:12, color:"rgba(255,255,255,0.68)", marginTop:8 }}>{timeAgo}</p>
427:         </div>
428:       ) : (
429:         <div style={{ padding:16, display:"flex", alignItems:"center", gap:12 }}>
430:           <div style={{ width:40, height:40, borderRadius:"50%", background:color, display:"flex", alignItems:"center", justifyContent:"center", color:"white", fontSize:13, fontWeight:700, flexShrink:0, border:isOwn?"2px solid #1D9E75":"none" }}>
431:             {initialsFromName(postAthlete?.name ?? "?")}
432:           </div>
433:           <div style={{ flex:1, minWidth:0 }}>
434:             <div style={{ display:"flex", alignItems:"center", gap:6 }}>
435:               <p style={{ fontSize:14, fontWeight:700, color:"var(--c-text-1)" }}>{postAthlete?.name ?? "Athlète"}</p>
436:               {isOwn && <span style={{ fontSize:12, fontWeight:700, padding:"2px 7px", borderRadius:6, background:"rgba(29,158,117,0.12)", color:"var(--tone-success)" }}>Moi</span>}
437:             </div>
438:             <div style={{ display:"flex", alignItems:"center", gap:5, marginTop:1 }}>
439:               <p style={{ fontSize:12, color:"var(--c-text-2)" }}>{timeAgo}</p>
440:               {linkedSess && (
441:                 <>
442:                   <span style={{ color:"var(--c-text-3)", fontSize:12 }}>·</span>
443:                   <div style={{ display:"flex", alignItems:"center", gap:3 }}>
444:                     <div style={{ width:5, height:5, borderRadius:"50%", background:colorsFor(linkedSess.category).border }}/>
445:                     <p style={{ fontSize:12, color:"var(--c-text-2)", maxWidth:180, overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>{linkedSess.title}</p>
446:                   </div>
447:                 </>
448:               )}
449:             </div>
450:           </div>
451:           {isOwn && (
452:             <button type="button" aria-label="Supprimer la publication" onClick={() => setConfirmDelete(true)} style={{ width:44, height:44, display:"flex", alignItems:"center", justifyContent:"center", background:"none", border:"none", cursor:"pointer", color:"var(--c-text-3)" }}><X size={16}/></button>
453:           )}
454:         </div>
455:       )}
456: 
457:       {/* Photo */}
458:       {post.image_url && (
459:         <div style={{ width:"100%", position:"relative", cursor:"pointer", background:"var(--c-surface-2)" }} onDoubleClick={() => onReact("❤️")}>
460:           <img src={post.image_url} alt={`Publication de ${postAthlete?.name ?? "un athlète"}`} loading="lazy" style={{ width:"100%", maxHeight:520, objectFit:"cover", display:"block" }}/>
461:           {/* Réactions en overlay sur la photo (style Instagram) plutôt que sous l'image */}
462:           {topReactions.length > 0 && (
463:             <div style={{
464:               position:"absolute", left:10, bottom:10,
465:               display:"flex", alignItems:"center", gap:5,
466:               padding:"5px 10px", borderRadius:99,
467:               background:"rgba(0,0,0,0.55)", backdropFilter:"blur(6px)", WebkitBackdropFilter:"blur(6px)",
468:             }}>
469:               <div style={{ display:"flex" }}>
470:                 {topReactions.map(([emoji], i) => (
471:                   <span key={emoji} style={{ fontSize:13, marginLeft:i>0?-2:0 }}>{emoji}</span>
472:                 ))}
473:               </div>
474:               <p style={{ fontSize:12, color:"white", fontWeight:700 }}>{totalLikes}</p>
475:             </div>
476:           )}
477:         </div>
478:       )}
479: 
480:       {/* Légende (posts manuels uniquement — le texte des posts auto est déjà
481:           affiché dans le header ci-dessus) */}
482:       {!autoCfg && post.content && (
483:         <div style={{ padding:"14px 16px 4px" }}>
484:           <p style={{ fontSize:14, color:"var(--c-text-1)", lineHeight:1.55 }}>
485:             <span style={{ fontWeight:600, color:"var(--c-text-1)", marginRight:5 }}>{postAthlete?.name?.split(" ")[0]}</span>
486:             {post.content}
487:           </p>
488:         </div>
489:       )}
490: 
491:       {/* Actions */}
492:       <div style={{ padding:"12px 16px 16px" }}>
493:         {/* Réactions existantes — seulement si pas de photo (sinon déjà en overlay dessus) */}
494:         {!post.image_url && topReactions.length > 0 && (
495:           <div style={{ display:"flex", alignItems:"center", gap:6, marginBottom:8 }}>
496:             <div style={{ display:"flex" }}>
497:               {topReactions.map(([emoji], i) => (
498:                 <span key={emoji} style={{ fontSize:14, marginLeft:i>0?-2:0 }}>{emoji}</span>
499:               ))}
500:             </div>
501:             <p style={{ fontSize:12, color:"var(--c-text-2)", fontWeight:600 }}>
502:               {totalLikes} réaction{totalLikes>1?"s":""}
503:             </p>
504:           </div>
505:         )}
506: 
507:         {/* Boutons actions */}
508:         <div style={{ display:"flex", alignItems:"center", gap:8, marginBottom:8 }}>
509:           <div style={{ display:"flex", alignItems:"center", gap:4, overflowX:"auto", scrollbarWidth:"none", flex:1 }}>
510:             {QUICK_REACTIONS.map(emoji => (
511:               <button key={emoji} type="button" aria-label={`Réagir ${emoji}`} aria-pressed={myReaction?.emoji===emoji} onClick={() => onReact(emoji)}
512:                 style={{
513:                   width:44, height:44, flexShrink:0, borderRadius:12, fontSize:17, border:`1px solid ${myReaction?.emoji===emoji?"rgba(29,158,117,0.38)":"var(--c-border)"}`,
514:                   background:myReaction?.emoji===emoji?"rgba(29,158,117,0.12)":"var(--c-surface-2)",
515:                   cursor:"pointer", display:"flex", alignItems:"center", justifyContent:"center",
516:                   transform:myReaction?.emoji===emoji?"scale(1.06)":"scale(1)", transition:"transform 0.12s ease",
517:                   boxShadow:myReaction?.emoji===emoji?"0 2px 8px rgba(29,158,117,0.18)":"none",
518:                 }}>
519:                 {emoji}
520:               </button>
521:             ))}
522:           </div>
523:           <button type="button" aria-label="Ouvrir les commentaires" onClick={onComment}
524:             style={{ minWidth:44, height:44, flexShrink:0, display:"flex", alignItems:"center", justifyContent:"center", gap:6, padding:"0 12px", borderRadius:12, background:"var(--c-surface-2)", border:"1px solid var(--c-border)", cursor:"pointer", color:"var(--c-text-2)", fontSize:12, fontWeight:700 }}>
525:             <MessageSquare size={15}/>
526:             {commentCount>0 && <span>{commentCount}</span>}
527:           </button>
528:         </div>
529: 
530:         {/* Double-tap hint si image */}
531:         {post.image_url && (
532:           <p style={{ fontSize:12, color:"var(--c-text-3)" }}>Double-tap sur la photo pour ❤️</p>
533:         )}
534:       </div>
535:       {confirmDelete && (
536:         <div role="alert" style={{ padding:16, borderTop:"1px solid rgba(224,82,82,0.18)", background:"rgba(224,82,82,0.07)", display:"flex", alignItems:"center", gap:12, flexWrap:"wrap" }}>
537:           <p style={{ flex:1, minWidth:180, fontSize:13, fontWeight:700, color:"var(--c-text-1)" }}>Supprimer définitivement cette publication ?</p>
538:           <button type="button" onClick={() => setConfirmDelete(false)} className="btn-secondary">Annuler</button>
539:           <button type="button" onClick={onDelete}
540:             style={{ minHeight:44, padding:"0 14px", borderRadius:12, border:"1px solid rgba(224,82,82,0.24)", background:"rgba(224,82,82,0.12)", color:"var(--tone-danger)", fontSize:13, fontWeight:700, cursor:"pointer" }}>
541:             Supprimer
542:           </button>
543:         </div>
544:       )}
545:     </article>
546:   );
547: });
