549: // ═══════════════════════════════════════════════════════════════════════════════
550: // COMPOSANT PRINCIPAL
551: // ═══════════════════════════════════════════════════════════════════════════════
552: export default function AthleteClub({ athlete, allAthletes, clubId, coachUserId, sessions, clubBrand }) {
553:   const [posts,          setPosts]          = useState([]);
554:   const [loading,        setLoading]        = useState(true);
555:   const [loadingMore,    setLoadingMore]    = useState(false);
556:   const [hasMorePosts,   setHasMorePosts]   = useState(false);
557:   const [activeComments, setActiveComments] = useState(null);
558:   const [quickPost,      setQuickPost]      = useState(null); // session ou true
559:   const [toast,          setToast]          = useState(null);
560:   const [commentCounts,  setCommentCounts]  = useState({});
561:   const [feedFilter,     setFeedFilter]     = useState("all");
562:   const postsCountRef = useRef(0);
563: 
564:   const currentWeek  = getISOWeek(new Date());
565:   const currentWeekInfo = getISOWeekInfo(new Date());
566:   const sevenDaysAgo = useMemo(() => { const d=new Date(); d.setDate(d.getDate()-7); return d.toISOString(); }, []);
567:   const [squadStats, setSquadStats] = useState(null);
568: 
569:   // ── Récap du groupe cette semaine ────────────────────────────────────────
570:   // `sessions` (prop) ne contient que les séances de l'athlète connecté —
571:   // il faut une requête dédiée pour avoir la vue squad-wide (lundi→samedi).
572:   useEffect(() => {
573:     if (!clubId || allAthletes.length === 0) return;
574:     let cancelled = false;
575:     (async () => {
576:       const { data: sess, error: sessionsError } = await supabase.from("sessions")
577:         .select("id")
578:         .eq("club_id", clubId)
579:         .gte("session_date", currentWeekInfo.startDate)
580:         .lte("session_date", currentWeekInfo.endDate)
581:         .neq("lifecycle_status", "cancelled");
582:       if (sessionsError) {
583:         captureError(sessionsError, { operation: "load_club_weekly_sessions" });
584:         return;
585:       }
586:       const ids = (sess ?? []).map(s => s.id);
587:       const perAthlete = {};
588:       allAthletes.forEach(a => { perAthlete[a.id] = { done: 0, total: 0 }; });
589:       let total = 0, done = 0;
590:       if (ids.length > 0) {
591:         const { data: rows, error: rowsError } = await supabase.from("session_athletes")
592:           .select("session_id, athlete_id, status").in("session_id", ids);
593:         if (rowsError) {
594:           captureError(rowsError, { operation: "load_club_weekly_participation" });
595:           return;
596:         }
597:         (rows ?? []).forEach(r => {
598:           if (!perAthlete[r.athlete_id]) return;
599:           perAthlete[r.athlete_id].total++; total++;
600:           if (r.status === "done") { perAthlete[r.athlete_id].done++; done++; }
601:         });
602:       }
603:       if (cancelled) return;
604:       const ranking = allAthletes
605:         .map(a => ({ ...a, ...perAthlete[a.id] }))
606:         .filter(a => a.total > 0)
607:         .sort((a, b) => (b.done / b.total) - (a.done / a.total) || b.done - a.done)
608:         .slice(0, 3);
609:       setSquadStats({ total, done, pct: total > 0 ? Math.round((done / total) * 100) : null, ranking });
610:     })();
611:     return () => { cancelled = true; };
612:   }, [clubId, currentWeekInfo.endDate, currentWeekInfo.startDate, allAthletes]);
