614:   // ── Fetch posts ────────────────────────────────────────────────────────────
615:   // Pagination par page de POSTS_PAGE_SIZE (au lieu d'un .limit(50) fixe qui
616:   // tronquait silencieusement un club actif sans possibilité d'aller plus
617:   // loin) — reset=true recharge depuis le début (nouvelle activité live,
618:   // changement de club…), reset=false ajoute la page suivante.
619:   const fetchPosts = useCallback(async (reset = true) => {
620:     if (!clubId) return;
621:     if (reset) setLoading(true); else setLoadingMore(true);
622:     const offset = reset ? 0 : postsCountRef.current;
623:     const { data, error } = await supabase.from("social_posts")
624:       .select("*, social_reactions(*)")
625:       .eq("club_id", clubId)
626:       .gte("created_at", sevenDaysAgo)
627:       .order("created_at", { ascending:false })
628:       .range(offset, offset + POSTS_PAGE_SIZE - 1);
629: 
630:     if (!error) {
631:       const page = data ?? [];
632:       setPosts(prev => reset ? page : [...prev, ...page]);
633:       setHasMorePosts(page.length === POSTS_PAGE_SIZE);
634: 
635:       const ids = page.map(p => p.id);
636:       if (ids.length > 0) {
637:         const { data:coms } = await supabase.from("social_comments").select("post_id").in("post_id", ids);
638:         const counts = {}; (coms??[]).forEach(c => { counts[c.post_id]=(counts[c.post_id]??0)+1; });
639:         setCommentCounts(prev => reset ? counts : { ...prev, ...counts });
640:       }
641:     }
642:     setLoading(false);
643:     setLoadingMore(false);
644:   }, [clubId, sevenDaysAgo]);
