677:       const filtered  = reactions.filter(r => r.athlete_id!==athlete.id);
678:       return { ...p, social_reactions: [...filtered, { id:`tmp-${Date.now()}`, athlete_id:athlete.id, emoji, post_id:postId }] };
679:     }));
680:     let operationError = null;
681:     if (existing) {
682:       const { error } = await supabase.from("social_reactions").delete().eq("id", existing.id);
683:       operationError = error;
684:     } else {
