181: export function dimColor(metric, val) {
182:   switch (metric) {
183:     case "wellness": return "#A78BFA";
184:     case "ewmaLong": return "#EC4899";
185:     case "ewmaShort": return "#A855F7";
186:     case "spacing": return "#38BDF8";
187:     case "dataQuality": return "#94A3B8";
188:     case "acwrExperimental": return "#8B5CF6";
189:     case "streak": return val >= 3 ? "#378ADD" : "rgba(55,138,221,0.45)";
190:     default: return "#94A3B8";
191:   }
192: }
193: 
194: export function acwrColor() {
195:   return "#8B5CF6";
196: }
197: 
198: export function isSameDay(a, b) {
199:   return a.getFullYear()===b.getFullYear() && a.getMonth()===b.getMonth() && a.getDate()===b.getDate();
200: }
201: 
202: // Inverse de parseLocalDate : Date -> "YYYY-MM-DD" en heure LOCALE.
203: // Ne jamais utiliser .toISOString() sur un Date local ici : ça convertit
204: // en UTC et décale le jour d'un cran dans les fuseaux positifs (ex.
205: // Belgique) — une séance créée pour le 25 s'affichait le 26 dans le
206: // calendrier/la liste alors que la notif (qui lit la string brute en
207: // base) montrait bien le 25.
208: export function toLocalDateStr(d) {
209:   return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
210: }
211: 
212: export function dateToISOWeek(s) { return getISOWeek(parseLocalDate(s)); }
213: export function dateToDayName(s) { return DAYS_FR[(parseLocalDate(s).getDay()+6)%7]; }
214: export function colorsFor(cat) { return SESSION_COLORS[cat] ?? SESSION_COLORS.technique; }
215: 
216: // Parse UNIQUEMENT la valeur numérique d'une performance ("11.20" -> 11.2,
217: // "4:32" -> 272, "7.60m" -> 7.6). Ne devine JAMAIS le sens (plus petit ou
218: // plus grand est meilleur) depuis le FORMAT de la chaîne — un lancer de
219: // poids saisi "14.20" (sans "m") ressemble textuellement à un chrono, et
220: // l'ancienne version de cette fonction s'y trompait. Le sens vient
221: // TOUJOURS de la discipline via getDiscHib(), jamais d'ici (tâche 11).
222: export function parsePerf(str) {
223:   if (!str) return { value: null };
224:   const s = str.toString().trim();
225:   if (/^\d+:\d+/.test(s)) { const [m, sec] = s.split(":").map(Number); return { value: m * 60 + sec }; }
226:   const num = parseFloat(s);
227:   return { value: isNaN(num) ? null : num };
228: }
229: 
230: // getDiscType/getDiscHib délèguent au registre central (domain/disciplines.js,
231: // tâche 9) — signatures inchangées pour ne rien casser côté appelants,
232: // mais résolvent maintenant aussi les alias historiques ("100 m" -> "100m")
233: // au lieu d'un lookup exact sur un seul nom.
234: export function getDiscType(discName) {
235:   return getDisciplineType(discName);
236: }
237: 
238: export function getDiscHib(discName) {
239:   return getDisciplineHib(discName);
240: }
241: 
242: // ─── Moteur central de comparaison de performances (tâche 11) ────────────────
243: // Point unique de vérité pour "est-ce mieux", "quelle est la meilleure
244: // valeur" et "quel pourcentage d'une référence est atteint" — à utiliser
245: // PARTOUT à la place de comparaisons/ratios écrits à la main (Math.max,
246: // v > best, current/target...), qui supposent implicitement "plus grand =
247: // meilleur" et se trompent sur toutes les disciplines chronométrées.
248: 
249: // `a` est-il meilleur ou égal à `b` (nombres déjà parsés, pas des chaînes) ?
250: export function isBetterOrEqual(a, b, discipline) {
251:   if (a == null) return false;
252:   if (b == null) return true;
253:   const higherIsBetter = getDiscHib(discipline);
254:   if (higherIsBetter == null) return false;
255:   return higherIsBetter ? a >= b : a <= b;
256: }
257: 
258: // Comparateur numérique pour .sort() — trie du meilleur au moins bon.
259: // Ex: values.sort((a, b) => compareValues(a, b, "100m"))
260: export function compareValues(a, b, discipline) {
261:   const higherIsBetter = getDiscHib(discipline);
262:   if (higherIsBetter == null) return 0;
263:   return higherIsBetter ? b - a : a - b;
264: }
265: 
266: // % d'accomplissement d'une valeur "current" par rapport à une "reference"
267: // (typiquement le PR pour un résultat de compétition, ou le PR pour un
268: // objectif visé), dans le bon sens selon la discipline, plafonné à 100%.
269: // Sert à la fois pour "% du PR réalisé en compétition" (current=résultat,
270: // reference=PR) et pour "progression vers un objectif" (current=PR,
271: // reference=objectif) — même formule, mêmes garanties, un seul endroit à
272: // corriger si un jour elle doit changer.
273: export function pctOfReference(currentValue, referenceValue, discipline) {
274:   if (currentValue == null || referenceValue == null || referenceValue === 0) return null;
275:   const hib = getDiscHib(discipline);
276:   if (hib == null) return null;
277:   const ratio = hib ? currentValue / referenceValue : referenceValue / currentValue;
278:   return Math.min(100, Math.round(ratio * 1000) / 10);
279: } 1: // ============================================================
