14: const AddRecordModal = memo(({ athleteName, onClose, onAdd }) => {
15:   const [form, setForm]     = useState({ discipline: "", sb: "", pr: "", prDate: "", metadata: createPerformanceMetadata("") });
16:   const [saving, setSaving] = useState(false);
17:   const [err, setErr]       = useState(null);
18:   const { dialogRef, titleId } = useAccessibleDialog({ onClose, closeDisabled: saving });
19:   const set = (k, v) => setForm(f => ({ ...f, [k]: v }));
20: 
21:   const handleSubmit = async () => {
22:     if (!form.discipline.trim() || !form.sb.trim() || !form.pr.trim()) return;
23:     setSaving(true); setErr(null);
24:     try { await onAdd(form); onClose(); }
25:     catch (e) { setErr(e.message ?? "Erreur"); setSaving(false); }
26:   };
27: 
28:   return createPortal(
29:     <div className="fixed inset-0 z-50 flex items-end sm:items-center justify-center sm:p-4 modal-backdrop"
30:       onClick={e => e.target === e.currentTarget && !saving && onClose()}>
31:       <div ref={dialogRef} role="dialog" aria-modal="true" aria-labelledby={titleId} tabIndex={-1}
32:            className="rounded-t-3xl sm:rounded-3xl shadow-2xl w-full max-w-sm max-h-[90vh] flex flex-col overflow-hidden modal-content"
33:            style={{ background: "var(--c-surface)" }}>
34:         <div className="flex justify-center pt-3 pb-1 sm:hidden flex-shrink-0">
35:           <div className="w-10 h-1 rounded-full" style={{ background: "var(--c-border-strong)" }} />
36:         </div>
37:         <div className="px-6 py-5 flex items-center justify-between flex-shrink-0" style={{ borderBottom: "1px solid var(--c-border)" }}>
