 43: export function formatDate(dateStr, opts = {}) {
 44:   return parseLocalDate(dateStr).toLocaleDateString("fr-BE", {
 45:     weekday: "long", day: "numeric", month: "long", year: "numeric",
 46:     ...opts,
 47:   });
 48: }
 49: 
 50: export function formatDateShort(dateStr) {
 51:   return parseLocalDate(dateStr).toLocaleDateString("fr-BE", {
 52:     day: "numeric", month: "short", year: "numeric",
 53:   });
 54: }
 55: 
 56: export function daysUntil(dateStr, referenceDate = new Date()) {
 57:   const today = new Date(referenceDate.getFullYear(), referenceDate.getMonth(), referenceDate.getDate());
 58:   const diff = parseLocalDate(dateStr) - today;
 59:   return Math.round(diff / (1000 * 60 * 60 * 24));
 60: }
 61: 
 62: export function dateToWeek(dateStr) {
 63:   return getISOWeek(parseLocalDate(dateStr));
 64: }
