 66: export function generateResultAnalysis(result, competition, athlete, weeklyCharge) {
 67:   const week    = dateToWeek(competition.date);
 68:   const metrics = getAthleteMetricsForWeek(athlete.id, weeklyCharge, week, [], [], competition.date);
 69:   const { load7, load28, variationPercent, wellnessScore } = metrics;
 70:   const lines = [];
 71: 
 72:   if (load7 != null && load28 != null) {
 73:     const variation = variationPercent == null ? "variation indisponible" : `${variationPercent >= 0 ? "+" : ""}${variationPercent} %`;
 74:     lines.push(`Contexte de charge à cette date : ${load7} unités sur 7 jours, ${load28} unités sur 28 jours (${variation} entre les moyennes quotidiennes). Cette observation ne prédit pas la performance ni le risque de blessure.`);
 75:   } else {
 76:     lines.push("Contexte de charge indisponible : l'historique quotidien n'est pas assez complet à cette date.");
 77:   }
 78: 
 79:   if (wellnessScore != null) {
 80:     lines.push(`Questionnaire de bien-être AthleteOS : ${wellnessScore}/100. Il s'agit d'un retour déclaré, pas d'un diagnostic de récupération.`);
 81:   }
 82: 
 83:   const activeInjuries = athlete.injuries?.filter((inj) => {
 84:     if (inj.status === "résolu" || !inj.startDate) return false;
 85:     const start    = parseLocalDate(inj.startDate);
 86:     const end      = inj.endDate ? parseLocalDate(inj.endDate) : new Date(2099, 0, 1);
 87:     const compDate = parseLocalDate(competition.date);
 88:     return compDate >= start && compDate <= end;
 89:   }) ?? [];
 90: 
 91:   if (activeInjuries.length > 0) {
 92:     lines.push(
 93:       `🩺 Blessure(s) active(s) à cette période : ${activeInjuries.map((i) => i.name).join(", ")}. ` +
 94:       `À prendre en compte dans l'évaluation du résultat.`
 95:     );
 96:   }
 97: 
 98:   return lines;
 99: }
