 32: export default function SignupPage({ onBack, initialInviteCode = "" }) {
 33:   const normalizedInviteCode = normalizeInviteCode(initialInviteCode);
 34:   const [mode, setMode] = useState(normalizedInviteCode ? "join_club" : "create_club");
 35:   const [form, setForm] = useState({ name: "", email: "", password: "", clubName: "", inviteCode: normalizedInviteCode });
 36:   const [loading, setLoading] = useState(false);
 37:   const [error, setError] = useState(null);
