 42:   const setField = (field, value) => {
 43:     setForm((current) => ({ ...current, [field]: value }));
 44:     if (error) setError(null);
 45:   };
 46: 
 47:   const inviteBlocked = inviteCheck && !["active", "loading"].includes(inviteCheck.status);
 48:   const canSubmit = Boolean(
 49:     form.name.trim()
 50:     && form.email.trim()
 51:     && form.password.length >= 8
 52:     && (mode === "create_club" ? form.clubName.trim() : form.inviteCode.trim())
 53:     && !inviteBlocked,
 54:   );
 55: 
 56:   useEffect(() => {
 57:     const code = normalizeInviteCode(form.inviteCode);
 58:     if (mode !== "join_club" || code.length !== 8) {
 59:       setInviteCheck(null);
 60:       return undefined;
 61:     }
 62:     let active = true;
 63:     setInviteCheck({ status: "loading" });
 64:     const timer = globalThis.setTimeout(async () => {
 65:       const { data, error: inspectError } = await supabase.rpc("inspect_club_invitation", { p_code: code });
 66:       if (!active) return;
 67:       if (inspectError) {
