 70:         setInviteCheck(null);
 71:         return;
 72:       }
 73:       setInviteCheck(data ?? { status: "invalid" });
 74:     }, 350);
 75:     return () => {
 76:       active = false;
 77:       globalThis.clearTimeout(timer);
 78:     };
 79:   }, [form.inviteCode, mode]);
