 75: import {
 76:   computeEWMA,
 77:   computeMonotonyAndStrain,
 78:   computeWellnessScore,
 79:   estimateRecovery,
 80:   extractDailyLoads,
 81:   computeLoadWindows,
 82: } from "./trainingLoad.js";
