 84: // ─── Calcul des métriques complètes pour un athlète à une semaine donnée ──────
 85: // Combine : ACWR (EWMA), monotonie, contrainte, wellness, récupération
 86: //
 87: // @param athleteId  : number
 88: // @param weeklyCharge : [{ athleteId, week, rawLoad }]
 89: // @param currentWeek  : number (semaine ISO courante)
 90: // @param wellnessData : [{ date, sleep, energy, soreness, mood, stress }] (optionnel)
 91: // @param sessions     : array de séances (optionnel, pour récupération)
 92: export function getAthleteMetricsForWeek(athleteId, weeklyCharge, currentWeek, wellnessData = [], sessions = [], cutoffDate = null) {
 93:   const myCharge = weeklyCharge
 94:     .filter(w => w.athleteId === athleteId)
 95:     .sort((a, b) => a.week - b.week);
 96:   const dailyLoads = extractDailyLoads(athleteId, myCharge, currentWeek, cutoffDate);
 97:   const { acute, chronic, acwr, ewmaHistory, observedDays, status: acwrStatus } = computeEWMA(dailyLoads);
 98:   const loadWindows = computeLoadWindows(dailyLoads);
 99:   const { monotony, strain, status: monotonyStatus } = computeMonotonyAndStrain(
100:     dailyLoads.slice(-7).map((point) => point.load),
101:   );
102: 
103:   // ── Wellness [5][6] ────────────────────────────────────────────────────────
104:   // Prend le dernier questionnaire disponible (7 derniers jours)
105:   const recentWellness = wellnessData
106:     .filter(w => w.athleteId === athleteId || !w.athleteId)
107:     .filter(w => !cutoffDate || !w.date || String(w.date).slice(0, 10) <= String(cutoffDate).slice(0, 10))
108:     .sort((a, b) => new Date(b.date) - new Date(a.date))[0] ?? null;
109:   const wellnessScore = computeWellnessScore(recentWellness);
110: 
111:   // Règle de programmation du club, pas estimation physiologique.
112:   const recovery = estimateRecovery(sessions, athleteId, recentWellness);
113:   return {
114:     acute, chronic, acwr, acwrStatus, acwrExperimental: true, observedDays,
115:     ewmaHistory,
116:     ...loadWindows,
117:     monotony, strain, monotonyStatus,
118:     wellnessScore,
119:     recovery,
120:     experimental_readiness_v0: null,
121:     hasDailyLoadData: dailyLoads.length > 0,
122:   };
123: }
124: 
125: // Statut du questionnaire AthleteOS Wellness v1 uniquement.
126: export function getWellnessStatus(wellnessScore) {
127:   if (wellnessScore == null) return { label: "Comment te sens-tu aujourd’hui ?", dot: "⚪", color: "#8A9B90" };
128:   if (wellnessScore >= 75) return { label: "Tu te sens bien aujourd’hui", dot: "🟢", color: "#1D9E75" };
129:   if (wellnessScore >= 50) return { label: "Tu te sens plutôt bien", dot: "🟡", color: "#EF9F27" };
130:   if (wellnessScore < 25) return { label: "Ta journée semble difficile", dot: "🟠", color: "var(--tone-danger)" };
131:   return { label: "Ton ressenti est mitigé", dot: "🔵", color: "#378ADD" };
132: }
133: 
134: export function getStatusLabel(wellnessScore) {
135:   return getWellnessStatus(wellnessScore);
136: }
137: // ─── computeChargeChartData ───────────────────────────────────────────────────
138: // Prépare les charges hebdomadaires observées sur les 12 dernières semaines.
139: export function computeChargeChartData(athleteId, weeklyCharge) {
140:   const myCharge = weeklyCharge
141:     .filter(w => w.athleteId === athleteId)
142:     .sort((a, b) => a.week - b.week)
143:     .slice(-12);
144: 
145:   if (!myCharge.length) return [];
146: 
147:   return myCharge.map((week) => ({ label: `S${week.week}`, rawLoad: week.rawLoad }));
148: }
