150: // ─── generateContextAnalysis ──────────────────────────────────────────────────
151: // Génère des phrases d'analyse contextuelle à partir des métriques et de la prochaine compétition.
152: export function generateContextAnalysis(metrics, nextComp) {
153:   const { load7, load28, variationPercent, monotony, monotonyStatus, recovery } = metrics;
154:   const lines = [];
155: 
156:   if (load7 == null || load28 == null) {
157:     lines.push("ℹ️ Historique quotidien incomplet : les charges 7 et 28 jours ne sont pas encore comparables.");
158:   } else {
159:     const variation = variationPercent == null ? "" : ` · variation descriptive ${variationPercent >= 0 ? "+" : ""}${variationPercent}%`;
160:     lines.push(`Charge observée : ${load7} u sur 7 jours et ${load28} u sur 28 jours${variation}.`);
161:   }
162: 
163:   if (monotonyStatus === "undefined_zero_variance") {
164:     lines.push("Monotonie non définie : les sept charges quotidiennes sont identiques.");
165:   } else if (monotony != null) {
166:     lines.push(`Monotonie descriptive sur 7 jours : ${monotony.toFixed(2)}.`);
167:   }
168: 
169:   if (recovery?.status === "insufficient_data") {
170:     lines.push("ℹ️ Pas assez de séances récentes pour estimer la récupération.");
171:   } else if (recovery?.status === "spacing_active" || recovery?.status === "spacing_transition") {
172:     lines.push(`Règle de programmation : encore ${recovery.rangeHoursMin}–${recovery.rangeHoursMax} h dans la fenêtre configurée. Ce n'est pas une estimation physiologique.`);
173:   } else if (recovery?.status === "window_elapsed") {
174:     lines.push("La fenêtre d'espacement configurée est terminée ; cela ne prouve pas une récupération complète.");
175:   }
176: 
177:   if (nextComp) {
178:     const days = Math.round((new Date(nextComp.date) - new Date()) / (1000 * 60 * 60 * 24));
179:     if (days <= 3)       lines.push("🏟️ Compétition dans " + days + "j (" + nextComp.name + ") : activation, réduire la charge.");
180:     else if (days <= 7)  lines.push("🏟️ Compétition dans " + days + "j (" + nextComp.name + ") : semaine d'affûtage, baisser le volume.");
181:     else if (days <= 14) lines.push("🏟️ Compétition dans " + days + "j (" + nextComp.name + ") : maintenir charge, soigner la qualité.");
182:   }
183: 
184:   return lines.length ? lines : ["Pas assez de données pour une analyse contextuelle."];
185: }
