187: // ─── computePerformanceStability ──────────────────────────────────────────────
188: // Mesure la régularité des performances via le coefficient de variation.
189: // Score 0-100 (100 = très régulier). Minimum 3 points requis.
190: export function computePerformanceStability(performanceHistory) {
191:   const values = (performanceHistory ?? [])
192:     .map(p => parseFloat(p.value))
193:     .filter(v => !isNaN(v) && v > 0);
194: 
195:   if (values.length < 3) return null;
196: 
197:   const mean = values.reduce((a, b) => a + b, 0) / values.length;
198:   const sd   = Math.sqrt(values.reduce((acc, v) => acc + Math.pow(v - mean, 2), 0) / values.length);
199:   const cv   = mean > 0 ? (sd / mean) * 100 : 0;
200:   return Math.round(Math.max(0, Math.min(100, 100 - cv * 5)));
201: }  1: import { getTrainingFocus } from "../domain/trainingFocus.js";
  2: 
  3: // Profil descriptif des contraintes AthleteOS.
  4: // Les poids ventilent la charge session-RPE entre six dimensions séparées.
  5: // Ils ne modifient jamais la charge totale et ne prédisent aucun risque.
  6: 
  7: export const CURRENT_AXIS_MODEL_VERSION = "v2-objectifs-declares";
  8: 
  9: export const LOAD_AXES = {
 10:   neuromuscular: { label: "Vitesse", scientificLabel: "Contrainte neuromusculaire", nounPhrase: "de vitesse et d'explosivité", what: "Vitesse, accélération et production rapide de force.", color: "var(--tone-danger)" },
 11:   elastic: { label: "Impacts", scientificLabel: "Contrainte élastique", nounPhrase: "d'impacts et de bonds", what: "Bonds, rebonds et contacts dynamiques avec le sol.", color: "#EF9F27" },
 12:   metabolic: { label: "Effort long", scientificLabel: "Contrainte métabolique", nounPhrase: "d'effort prolongé", what: "Efforts soutenus, répétitions longues et endurance.", color: "#378ADD" },
 13:   muscular: { label: "Muscles", scientificLabel: "Contrainte musculaire", nounPhrase: "musculaire", what: "Travail de force et sollicitation musculaire.", color: "#A855F7" },
 14:   technical: { label: "Geste", scientificLabel: "Contrainte technique", nounPhrase: "technique", what: "Apprentissage, précision et répétition du geste.", color: "#14B8A6" },
 15:   mental: { label: "Attention", scientificLabel: "Exigence attentionnelle perçue", nounPhrase: "d'attention", what: "Concentration et exigences perçues pendant la séance.", color: "#EC4899" },
 16: };
 17: 
 18: const AXIS_IDS = Object.keys(LOAD_AXES);
 19: 
 20: // Convention de coaching configurable. Ces poids ne sont pas des coefficients
 21: // de charge : la somme session-RPE reste durée réelle × RPE.
 22: export const AXIS_WEIGHTS = {
 23:   sprint:       { neuromuscular: 1.0, elastic: 0.7, metabolic: 0.3, muscular: 0.3, technical: 0.5, mental: 0.4 },
 24:   haies:        { neuromuscular: 0.9, elastic: 0.8, metabolic: 0.3, muscular: 0.3, technical: 0.8, mental: 0.5 },
 25:   force:        { neuromuscular: 0.6, elastic: 0.3, metabolic: 0.3, muscular: 1.0, technical: 0.3, mental: 0.3 },
 26:   saut:         { neuromuscular: 0.8, elastic: 1.0, metabolic: 0.3, muscular: 0.4, technical: 0.8, mental: 0.5 },
 27:   lancer:       { neuromuscular: 0.7, elastic: 0.5, metabolic: 0.2, muscular: 0.7, technical: 0.9, mental: 0.4 },
 28:   endurance:    { neuromuscular: 0.2, elastic: 0.2, metabolic: 1.0, muscular: 0.3, technical: 0.2, mental: 0.3 },
 29:   technique:    { neuromuscular: 0.3, elastic: 0.3, metabolic: 0.2, muscular: 0.2, technical: 1.0, mental: 0.3 },
 30:   mobilite:     { neuromuscular: 0.1, elastic: 0.2, metabolic: 0.1, muscular: 0.1, technical: 0.2, mental: 0.2 },
 31:   recuperation: { neuromuscular: 0.05, elastic: 0.05, metabolic: 0.1, muscular: 0.05, technical: 0.05, mental: 0.1 },
 32: };
 33: 
 34: export function computeSessionAxisLoads(actualDurationMinutes, rpe, category, trainingFocus = null) {
 35:   const duration = Number(actualDurationMinutes);
 36:   const effort = Number(rpe);
 37:   if (!Number.isFinite(duration) || duration <= 0 || !Number.isFinite(effort) || effort < 0 || effort > 10) return null;
 38:   const base = duration * effort;
 39:   const focus = trainingFocus ? getTrainingFocus(trainingFocus, category) : null;
 40:   const weights = focus?.weights ?? AXIS_WEIGHTS[category] ?? AXIS_WEIGHTS.technique;
 41:   return Object.fromEntries(AXIS_IDS.map(axis => [axis, Math.round(base * (weights[axis] ?? 0))]));
 42: }
 43: 
 44: export function computeWeeklyAxisLoads(athleteId, sessions) {
 45:   const byWeek = new Map();
 46:   (sessions ?? []).forEach(session => {
 47:     if (!session.athleteIds?.includes(athleteId)) return;
 48:     const validation = session.validations?.find(item => item.athleteId === athleteId);
 49:     const loads = computeSessionAxisLoads(validation?.actualDurationMinutes, validation?.rpe, session.category, session.trainingFocus);
 50:     if (!loads) return;
 51:     if (!byWeek.has(session.week)) byWeek.set(session.week, Object.fromEntries(AXIS_IDS.map(axis => [axis, 0])));
 52:     AXIS_IDS.forEach(axis => { byWeek.get(session.week)[axis] += loads[axis]; });
 53:   });
 54:   return [...byWeek.entries()].sort((a, b) => a[0] - b[0]).map(([week, loads]) => ({ week, loads }));
 55: }
 56: 
 57: export function axisStatus(score) {
 58:   if (score >= 75) return { label: "Dominant", color: "var(--tone-info)" };
 59:   if (score >= 40) return { label: "Présent", color: "var(--tone-success)" };
 60:   return { label: "Secondaire", color: "#94A3B8" };
 61: }
 62: 
 63: function axisDataQuality(weeksOfData) {
 64:   if (weeksOfData >= 8) return "élevée";
 65:   if (weeksOfData >= 4) return "modérée";
 66:   return "faible";
 67: }
 68: 
 69: export function getAthleteAxisProfile(athleteId, sessions, currentWeek) {
 70:   const cutoff = Number.isFinite(currentWeek) ? currentWeek : Infinity;
 71:   const weekly = computeWeeklyAxisLoads(athleteId, sessions).filter(item => item.week <= cutoff);
 72:   if (!weekly.length) return null;
 73: 
 74:   const current = weekly.at(-1);
 75:   const baselineWeeks = weekly.slice(-5, -1);
 76:   const maxCurrentLoad = Math.max(1, ...AXIS_IDS.map(axis => current.loads[axis]));
 77:   const profile = {};
 78:   AXIS_IDS.forEach(axis => {
 79:     const currentLoad = current.loads[axis];
 80:     const habitualLoad = baselineWeeks.length
 81:       ? Math.round(baselineWeeks.reduce((sum, week) => sum + week.loads[axis], 0) / baselineWeeks.length)
 82:       : null;
 83:     const variationPercent = habitualLoad > 0 ? Math.round(((currentLoad - habitualLoad) / habitualLoad) * 100) : null;
 84:     const score = Math.round((currentLoad / maxCurrentLoad) * 100);
 85:     profile[axis] = {
 86:       score, ...axisStatus(score), currentLoad, habitualLoad, variationPercent,
 87:       dataQuality: axisDataQuality(weekly.length), weeksOfData: weekly.length, currentWeek: current.week,
 88:     };
 89:   });
 90:   return profile;
 91: }
 92: 
 93: export function getAxisTopContributors(athleteId, sessions, axis, currentWeek, limit = 3) {
 94:   return (sessions ?? [])
 95:     .filter(session => session.week != null && session.week >= currentWeek - 1 && session.week <= currentWeek)
 96:     .filter(session => session.athleteIds?.includes(athleteId))
 97:     .map(session => {
 98:       const validation = session.validations?.find(item => item.athleteId === athleteId);
 99:       const loads = computeSessionAxisLoads(validation?.actualDurationMinutes, validation?.rpe, session.category, session.trainingFocus);
100:       if (!loads?.[axis]) return null;
101:       const focus = getTrainingFocus(session.trainingFocus, session.category);
102:       return { id: session.id, title: session.title, category: session.category, trainingFocus: session.trainingFocus, focusLabel: focus?.shortLabel, week: session.week, sessionDate: session.sessionDate, axisLoad: loads[axis] };
103:     })
104:     .filter(Boolean)
105:     .sort((a, b) => b.axisLoad - a.axisLoad)
106:     .slice(0, limit);
107: }  1: -- ============================================================
