 35: import { createClient } from "@supabase/supabase-js";
 36: import { readFileSync } from "node:fs";
 37: import { fileURLToPath } from "node:url";
 38: import path from "node:path";
 39: import crypto from "node:crypto";
 40: 
 41: function loadDotEnv(filePath) {
 42:   let text;
 43:   try { text = readFileSync(filePath, "utf8"); } catch { return; }
 44:   for (const rawLine of text.split("\n")) {
 45:     const line = rawLine.replace(/\r$/, "");
 46:     const m = line.match(/^([A-Z0-9_]+)=(.*)$/);
 47:     if (m && process.env[m[1]] === undefined) process.env[m[1]] = m[2].trim();
 48:   }
 49: }
 50: loadDotEnv(path.join(path.dirname(fileURLToPath(import.meta.url)), ".env"));
 51: 
 52: const SUPABASE_URL    = process.env.VITE_SUPABASE_URL;
 53: const ANON_KEY         = process.env.VITE_SUPABASE_ANON_KEY;
 54: const SERVICE_ROLE_KEY = process.env.SUPABASE_SERVICE_ROLE_KEY;
 55: 
 56: if (!SUPABASE_URL || !ANON_KEY || !SERVICE_ROLE_KEY) {
 57:   console.error(
 58:     "Variables manquantes. Requis : VITE_SUPABASE_URL, VITE_SUPABASE_ANON_KEY " +
 59:     "(dans .env) et SUPABASE_SERVICE_ROLE_KEY (variable d'environnement, jamais committée)."
 60:   );
 61:   process.exit(1);
 62: }
