 64: const admin = createClient(SUPABASE_URL, SERVICE_ROLE_KEY, { auth: { autoRefreshToken: false, persistSession: false } });
 65: const publicClient = createClient(SUPABASE_URL, ANON_KEY, { auth: { autoRefreshToken: false, persistSession: false } });
 66: 
 67: const RUN_ID = Date.now();
 68: const results = [];
 69: function record(name, pass, detail) {
 70:   results.push({ name, pass, detail });
 71:   console.log(`${pass ? "✅" : "❌"} ${name}${detail ? " — " + detail : ""}`);
 72: }
