 74: async function insertOrThrow(table, row) {
 75:   const { data, error } = await admin.from(table).insert(row).select().single();
 76:   if (error) throw new Error(`seed ${table} : ${error.message}`);
 77:   return data;
 78: }
 79: 
 80: async function makeUser(email, password, clubId, role, name) {
 81:   const { data: a, error: ea } = await admin.auth.admin.createUser({ email, password, email_confirm: true });
 82:   if (ea) throw new Error(`createUser ${email} : ${ea.message}`);
 83:   const u = await insertOrThrow("users", { club_id: clubId, name, email, role, auth_uid: a.user.id });
 84:   const client = createClient(SUPABASE_URL, ANON_KEY, { auth: { autoRefreshToken: false, persistSession: false } });
 85:   const { error: es } = await client.auth.signInWithPassword({ email, password });
 86:   if (es) throw new Error(`signIn ${email} : ${es.message}`);
 87:   return { auth: a.user, row: u, client };
 88: }
 89: 
 90: async function callAdmin(client, payload) {
 91:   const { data, error } = await client.functions.invoke("admin-actions", { body: payload });
 92:   if (error) return { success: false, error: error.message ?? String(error) };
 93:   return data;
 94: }
