 96: async function main() {
 97:   let clubA, clubB;
 98:   const auths = []; // { auth, row, client } pour nettoyage
 99:   const password = `Admin-Test-${RUN_ID}-Aa!`;
100: 
101:   try {
102:     clubA = await insertOrThrow("clubs", { name: `Admin Test Club A ${RUN_ID}`, invite_code: `AT${RUN_ID}`.slice(0, 8).toUpperCase() });
103:     clubB = await insertOrThrow("clubs", { name: `Admin Test Club B ${RUN_ID}` });
104: 
105:     const headA1 = await makeUser(`admin-test-heada1-${RUN_ID}@example.invalid`, password, clubA.id, "head_coach", "Head A1"); auths.push(headA1);
106:     const headA2 = await makeUser(`admin-test-heada2-${RUN_ID}@example.invalid`, password, clubA.id, "head_coach", "Head A2"); auths.push(headA2);
107:     const coachA = await makeUser(`admin-test-coacha-${RUN_ID}@example.invalid`, password, clubA.id, "coach", "Coach A"); auths.push(coachA);
108:     const athleteA = await makeUser(`admin-test-athletea-${RUN_ID}@example.invalid`, password, clubA.id, "athlete", "Athlete A"); auths.push(athleteA);
109:     const headB = await makeUser(`admin-test-headb-${RUN_ID}@example.invalid`, password, clubB.id, "head_coach", "Head B"); auths.push(headB);
110: 
111:     // ── 1. Coach et athlète refusés sur toutes les actions head coach ──────
112:     for (const [label, client] of [["coach", coachA.client], ["athlète", athleteA.client]]) {
113:       for (const payload of [
114:         { action: "rename_club", clubName: "Triche" },
115:         { action: "update_club_branding", accentColor: "#378ADD" },
116:         { action: "create_club_invitation", recipientName: "Intrusion", expiresInDays: 7 },
117:         { action: "list_club_invitations" },
118:         { action: "regenerate_invite_code" },
119:         { action: "remove_user", userId: athleteA.row.id },
120:         { action: "change_role", userId: athleteA.row.id, role: "coach" },
121:       ]) {
122:         const res = await callAdmin(client, payload);
123:         record(`${payload.action} refusé pour ${label}`, res.success === false, res.success ? "AUTORISÉ !" : res.error);
124:       }
125:     }
126: 
127:     // ── 2. Head coach d'un AUTRE club refusé sur un membre/club qui n'est pas le sien ──
128:     {
129:       const res = await callAdmin(headB.client, { action: "remove_user", userId: athleteA.row.id });
130:       record("remove_user refusé (head coach club B sur athlète club A)", res.success === false, res.success ? "AUTORISÉ !" : res.error);
131:     }
132:     {
133:       const res = await callAdmin(headB.client, { action: "change_role", userId: coachA.row.id, role: "head_coach" });
134:       record("change_role refusé (head coach club B sur coach club A)", res.success === false, res.success ? "AUTORISÉ !" : res.error);
135:     }
136:     {
137:       const res = await callAdmin(headB.client, {
138:         action: "update_club_branding",
139:         logoPath: `${clubA.id}/${RUN_ID}-intrusion.png`,
140:       });
141:       record("update_club_branding refuse le chemin d'un autre club", res.success === false, res.success ? "AUTORISÉ !" : res.error);
142:     }
143: 
144:     // ── 3. Auto-suppression/auto-rétrogradation toujours bloquées, même en
145:     //    étant l'unique head coach — et transfert de propriété fonctionnel ──
146:     // Note honnête : la protection "dernier head coach" dans remove_user et
147:     // change_role ne peut mathématiquement se déclencher QUE si caller ===
148:     // target (seul un head coach peut appeler ces actions ; si le club n'a
149:     // qu'un seul head coach, c'est forcément lui l'appelant) — un cas déjà
150:     // bloqué séparément par le refus d'auto-cible, testé ci-dessous. Gardée
151:     // en défense en profondeur (voir commentaire dans admin-actions/
152:     // index.ts) mais pas indépendamment déclenchable via l'API publique
153:     // aujourd'hui — ce que ces tests prouvent, c'est que le CHEMIN RÉEL de
154:     // départ (transférer à un 2e head coach, puis se faire retirer PAR lui)
155:     // fonctionne de bout en bout.
156:     {
157:       const res = await callAdmin(headA1.client, { action: "remove_user", userId: headA1.row.id });
158:       record("remove_user refusé (auto-suppression, même en étant l'unique head coach)", res.success === false, res.success ? "AUTORISÉ !" : res.error);
159:     }
160:     {
161:       const res = await callAdmin(headA1.client, { action: "change_role", userId: headA1.row.id, role: "coach" });
162:       record("change_role refusé (auto-rétrogradation, même en étant l'unique head coach)", res.success === false, res.success ? "AUTORISÉ !" : res.error);
163:     }
164:     {
165:       // headA1 tente de rétrograder headA2 — OK, il en reste un (headA1).
166:       const res = await callAdmin(headA1.client, { action: "change_role", userId: headA2.row.id, role: "coach" });
167:       record("change_role autorisé (rétrograder un head coach quand un autre reste, positif)", res.success === true, res.error);
168:     }
169:     {
170:       // On re-promeut headA2 pour vérifier le chemin "transfert de propriété"
171:       // avant départ, via headA1, seul head coach actuel.
172:       const res = await callAdmin(headA1.client, { action: "change_role", userId: headA2.row.id, role: "head_coach" });
173:       record("change_role autorisé (transfert : re-promouvoir un 2e head coach, positif)", res.success === true, res.error);
174:     }
175:     {
176:       // Deux head coaches de nouveau : headA2 peut maintenant retirer headA1
177:       // (le chemin réel de "départ du dernier head coach" — via quelqu'un
178:       // d'autre, après transfert).
179:       const res = await callAdmin(headA2.client, { action: "remove_user", userId: headA1.row.id });
180:       record("remove_user autorisé (headA2 retire headA1 après transfert de propriété, positif)", res.success === true, res.error);
181:       if (res.success) auths.splice(auths.indexOf(headA1), 1); // déjà supprimé, ne pas re-nettoyer
182:     }
183: 
184:     // ── 4. Rotation du code invalide l'ancien immédiatement ────────────────
185:     {
186:       const before = await admin.from("clubs").select("invite_code").eq("id", clubA.id).single();
187:       const res = await callAdmin(headA2.client, { action: "regenerate_invite_code" });
188:       const after = await admin.from("clubs").select("invite_code").eq("id", clubA.id).single();
189:       record("regenerate_invite_code change bien le code", res.success === true && after.data.invite_code !== before.data.invite_code, res.error);
190:       const stillValid = await admin.from("clubs").select("id").eq("invite_code", before.data.invite_code).maybeSingle();
191:       record("l'ancien code n'est plus valide après rotation", !stillValid.data, stillValid.data ? "encore trouvé !" : "introuvable, OK");
192:     }
193: 
194:     // ── 5. Invitation individuelle : création, ouverture, suivi, révocation ──
195:     {
196:       const created = await callAdmin(headA2.client, {
197:         action: "create_club_invitation",
198:         recipientName: "Athlète test",
199:         recipientEmail: athleteA.row.email,
200:         expiresInDays: 7,
201:         idempotencyKey: crypto.randomUUID(),
202:       });
203:       record("create_club_invitation crée un lien unique", created.success === true && /^[A-Z2-9]{8}$/.test(created.invitation?.code ?? ""), created.error);
204: 
205:       const inspected = created.invitation?.code
206:         // Le vrai parcours est celui d'un visiteur non connecté. La fonction
207:         // est volontairement accordée à `anon` et ne renvoie ni email ni ID ;
208:         // le client service_role utilisé pour les fixtures n'a, lui, pas ce
209:         // droit après le REVOKE PUBLIC de la migration.
210:         ? await publicClient.rpc("inspect_club_invitation", { p_code: created.invitation.code })
211:         : { data: null, error: new Error("Invitation absente") };
212:       record("inspect_club_invitation valide le lien sans exposer l'email", inspected.data?.status === "active" && inspected.data?.clubName && !Object.hasOwn(inspected.data, "recipientEmail"), inspected.error?.message);
