276:       const r1 = await callAdmin(headA2.client, { action: "rename_club", clubName: nameA, idempotencyKey: key });
277:       const nameB = `Club renommé deux fois ${RUN_ID}`; // si l'idempotence échouait, ce nom serait appliqué
278:       const r2 = await callAdmin(headA2.client, { action: "rename_club", clubName: nameB, idempotencyKey: key });
279:       const { data: club } = await admin.from("clubs").select("name").eq("id", clubA.id).single();
280:       record("rejeu idempotent : les deux appels réussissent", r1.success === true && r2.success === true, `${r1.error ?? ""} ${r2.error ?? ""}`.trim());
