282:     }
283: 
284:     // ── 7. Journal d'audit : au moins une ligne par tentative sensible ──────
285:     {
286:       const { data: logs, error } = await admin.from("audit_logs").select("action, actor_user_id, target_club_id, result").eq("actor_club_id", clubA.id);
287:       record("audit_logs contient des entrées pour le club A", !error && (logs ?? []).length > 0, error?.message ?? `${logs?.length ?? 0} ligne(s)`);
288:       const hasDenied = (logs ?? []).some(l => l.result === "denied");
289:       const hasSuccess = (logs ?? []).some(l => l.result === "success");
290:       record("audit_logs distingue bien success et denied", hasDenied && hasSuccess, `denied=${hasDenied} success=${hasSuccess}`);
291:     }
