295:     // n'implémentent PAS .catch()/.finally() — seul .then() existe (déjà
296:     // rencontré à la tâche 3). On récupère {error} et on l'ignore, plutôt
297:     // que de chaîner .catch() dessus (ça plante avec "catch is not a
298:     // function"). .auth.signOut()/.auth.admin.deleteUser() sont de vraies
299:     // Promises (API Auth, pas postgrest) — .catch() reste valide dessus.
300:     console.log("\nNettoyage...");
301:     for (const u of auths) {
302:       if (!u) continue;
