313:   const failed = results.filter((r) => !r.pass);
314:   console.log(`\n${results.length - failed.length}/${results.length} vérifications OK`);
315:   if (failed.length) {
316:     console.error(`\n${failed.length} régression(s) détectée(s) :`);
317:     failed.forEach((f) => console.error(`  - ${f.name}${f.detail ? " : " + f.detail : ""}`));
318:     process.exit(1);
319:   }
320:   console.log("\nMatrice d'autorisation admin-actions conforme.");
321:   process.exit(0);
322: }
