  2: // ============================================================
  3: // AthleteOS — test_rls_regression.mjs
  4: //
  5: // Suite de non-régression RLS/autorisation (tâches 6 et 7). Cinq profils
  6: // éphémères sur deux clubs : head coach A, head coach B (autre club),
  7: // coach Z (rôle intermédiaire, même club que A), athlète X et athlète Y
  8: // (coéquipiers, même club que A) :
  9: //   1. Un coach authentifié du club A ne doit pouvoir ni lire ni
 10: //      modifier ni supprimer aucune donnée du club B — y compris via des
 11: //      relations enfants forgées (session_athletes/competition_results
 12: //      pointant vers l'id d'une séance/compétition du club B).
 13: //   2. À l'intérieur du MÊME club, un athlète ne doit pouvoir lire/
 14: //      modifier ni le wellness, ni les blessures, ni l'abonnement push
 15: //      d'un coéquipier — uniquement les siens (le coach, lui, garde un
 16: //      accès en lecture à tout le club).
 17: //   3. Un athlète ne peut pas s'auto-attribuer un rôle différent, et un
 18: //      simple coach ne peut ni créer un autre coach/head_coach, ni
 19: //      changer le rôle d'un membre existant (role/club_id verrouillés
 20: //      côté serveur, y compris pour un attaquant qui n'est pas la
 21: //      victime).
 22: //   4. Un compte non-authentifié (anon) ne voit aucune donnée métier.
 23: //   5. Les RPC (get_my_club_id/get_my_role/get_my_athlete_id) renvoient
 24: //      la bonne valeur pour le bon appelant, directement via REST.
 25: //   6. Le stockage de fichiers (storage.objects) refuse l'upload en
 26: //      dehors du dossier du club de l'appelant.
 27: //   7. L'identité visuelle du club est lisible par ses membres, mais ne
 28: //      peut jamais être modifiée directement en contournant admin-actions.
 29: //
 30: // Seed une ligne de test dans chacune des tables couvertes, se connecte
 31: // avec la clé anon (comme le fait vraiment le frontend) sous chaque
 32: // profil, tente les accès interdits, puis nettoie tout (comptes auth,
 33: // lignes DB, fichiers storage) — succès ou échec (try/finally).
 34: //
 35: // Exécuté en CI (.github/workflows/rls-check.yml) contre une instance
 36: // Supabase locale éphémère (Docker), jamais contre la production —
 37: // db reset local + toutes les migrations rejouées à chaque run, donc
 38: // déterministe. Peut aussi être lancé à la main contre le projet distant
 39: // (voir "Usage" ci-dessous) pour une vérification en conditions réelles.
 40: //
 41: // Usage (local, comme en CI — après `supabase start`) :
 42: //   `supabase status -o env` imprime API_URL/ANON_KEY/SERVICE_ROLE_KEY pour
 43: //   l'instance locale — exportez-les dans votre shell puis lancez
 44: //   `node test_rls_regression.mjs` (voir le détail exact de la commande
 45: //   dans .github/workflows/rls-check.yml, non vérifié manuellement ici
 46: //   faute de Docker sur cette machine — voir status.md).
 47: //
 48: // Usage (contre le projet distant, vérification manuelle ponctuelle) :
 49: //   VITE_SUPABASE_URL=... VITE_SUPABASE_ANON_KEY=... \
 50: //   SUPABASE_SERVICE_ROLE_KEY=... node test_rls_regression.mjs
 51: // ============================================================
 52: 
 53: import { createClient } from "@supabase/supabase-js";
 54: import { readFileSync } from "node:fs";
 55: import { fileURLToPath } from "node:url";
 56: import path from "node:path";
 57: 
 58: function loadDotEnv(filePath) {
 59:   let text;
 60:   try { text = readFileSync(filePath, "utf8"); } catch { return; }
 61:   for (const rawLine of text.split("\n")) {
 62:     const line = rawLine.replace(/\r$/, "");
 63:     const m = line.match(/^([A-Z0-9_]+)=(.*)$/);
 64:     if (m && process.env[m[1]] === undefined) process.env[m[1]] = m[2].trim();
 65:   }
 66: }
 67: loadDotEnv(path.join(path.dirname(fileURLToPath(import.meta.url)), ".env"));
 68: 
 69: // En CI (voir .github/workflows/rls-check.yml), la cible est une instance
 70: // Supabase LOCALE démarrée par `supabase start` — les identifiants sont
 71: // injectés via `supabase status -o env`, qui utilise les noms par défaut
 72: // du CLI (API_URL/ANON_KEY/SERVICE_ROLE_KEY), pas les noms VITE_* utilisés
 73: // par le frontend. Les deux formes sont acceptées ici, avec priorité aux
 74: // noms explicites VITE_*/SUPABASE_SERVICE_ROLE_KEY s'ils sont définis
 75: // (usage manuel contre le projet distant, voir "Usage" plus haut).
 76: const SUPABASE_URL      = process.env.VITE_SUPABASE_URL      ?? process.env.API_URL;
 77: const ANON_KEY           = process.env.VITE_SUPABASE_ANON_KEY ?? process.env.ANON_KEY;
 78: const SERVICE_ROLE_KEY   = process.env.SUPABASE_SERVICE_ROLE_KEY ?? process.env.SERVICE_ROLE_KEY;
 79: 
 80: if (!SUPABASE_URL || !ANON_KEY || !SERVICE_ROLE_KEY) {
 81:   console.error(
 82:     "Variables manquantes. Requis : VITE_SUPABASE_URL, VITE_SUPABASE_ANON_KEY " +
 83:     "(dans .env, ou API_URL/ANON_KEY fournis par `supabase status -o env`) et " +
 84:     "SUPABASE_SERVICE_ROLE_KEY/SERVICE_ROLE_KEY (jamais committé)."
 85:   );
 86:   process.exit(1);
 87: }
