  6: import { memo, useState, useMemo } from "react";
  7: import { ArrowLeft, HeartPulse, Pencil, Trash2 } from "lucide-react";
  8: import { getAthleteMetricsForWeek } from "../utils/chargeCalculations";
  9: import { getISOWeek } from "../utils/helpers.js";
 10: import { TABS } from "./athleteListUtils";
 11: import { StatusBadge, ScoreRing } from "./athleteListShared";
 12: import { TabPerformances, TabCharge, TabEntrainements, TabBlessures, TabProfil } from "./AthleteProfileTabs";
 13: import { ConfirmDialog, InlineNotice, SegmentedTabs } from "../components/ui/premium";
 14: 
 15: const AthleteProfile = memo(({ athlete, weeklyCharge, sessions, competitions, onBack, onAddRecord, onEditRequest, onDelete, onAddInjury, onUpdateInjury, onDeleteInjury }) => {
 16:   const [activeTab,      setActiveTab]      = useState("performances");
 17:   const [confirmDelete, setConfirmDelete] = useState(false);
 18:   const [deleting,       setDeleting]       = useState(false);
 19:   const [deleteError,   setDeleteError]   = useState(null);
 20: 
 21:   const metrics        = useMemo(() => getAthleteMetricsForWeek(athlete.id, weeklyCharge, getISOWeek(new Date())), [athlete.id, weeklyCharge]);
 22:   const activeInjuries = athlete.injuries?.filter(i => i.status !== "résolu") ?? [];
 23: 
 24:   const handleDelete = async () => {
 25:     setDeleting(true); setDeleteError(null);
 26:     try { await onDelete(athlete.id); onBack(); }
 27:     catch { setDeleteError("Impossible de supprimer : cet athlète a des données liées."); setDeleting(false); setConfirmDelete(false); }
 28:   };
 29: 
 30:   return (
 31:     <div className="page-container py-4 md:py-6 max-w-6xl mx-auto space-y-5 animate-slide-up">
 32:       {/* Barre actions */}
 33:       <div className="flex items-center justify-between flex-wrap gap-2">
 34:         <button type="button" onClick={onBack}
 35:           className="flex items-center gap-1.5 min-h-10 text-[13px] font-semibold transition-colors tap-feedback" style={{ color: "var(--c-text-2)" }} onMouseEnter={e => e.currentTarget.style.color = "var(--c-text-1)"} onMouseLeave={e => e.currentTarget.style.color = "var(--c-text-2)"}>
 36:           <ArrowLeft size={16} /> Retour à la liste
 37:         </button>
 38:         <div className="flex items-center gap-2">
 39:           <button type="button" onClick={() => onEditRequest(athlete)}
 40:             className="btn-secondary">
 41:             <Pencil size={15} aria-hidden="true" /> Modifier
 42:           </button>
 43:           <button type="button" onClick={() => setConfirmDelete(true)} className="btn-secondary athlete-profile-delete">
 44:             <Trash2 size={15} aria-hidden="true" /> Supprimer
 45:           </button>
 46:         </div>
 47:       </div>
 48: 
 49:       {deleteError && (
 50:         <InlineNotice tone="danger" title="Suppression impossible" onDismiss={() => setDeleteError(null)}>{deleteError}</InlineNotice>
 51:       )}
 52: 
 53:       {/* Hero banner */}
 54:       <div
 55:         className="rounded-3xl p-6 text-white relative overflow-hidden"
 56:         style={{ background: "linear-gradient(135deg, var(--c-accent) 0%, var(--c-accent-dark) 72%, #07120C 150%)" }}
 57:       >
 58:         <div className="absolute -right-10 -top-10 w-48 h-48 rounded-full bg-white/5" />
 59:         <div className="relative flex items-start gap-5 flex-wrap">
 60:           {/* Avatar */}
 61:           <div
 62:             className="w-16 h-16 rounded-2xl flex items-center justify-center text-white text-[20px] font-bold flex-shrink-0 shadow-lg"
 63:             style={{ background: "rgba(255,255,255,0.20)" }}
 64:           >
 65:             {athlete.avatar}
 66:           </div>
 67: 
 68:           <div className="flex-1 min-w-0">
 69:             <div className="flex items-center gap-3 flex-wrap mb-1">
 70:               <h2 className="text-[24px] font-bold text-white tracking-tight">{athlete.name}</h2>
 71:               <StatusBadge wellnessScore={metrics.wellnessScore} />
 72:               {activeInjuries.length > 0 && (
 73:                 <span className="flex items-center gap-1 text-[12px] font-bold px-2.5 py-1 rounded-full text-white" style={{ background: "rgba(239,159,39,0.3)", border: "1px solid rgba(239,159,39,0.4)" }}>
 74:                   <HeartPulse size={11} /> {activeInjuries.length} blessure{activeInjuries.length > 1 ? "s" : ""}
 75:                 </span>
 76:               )}
 77:             </div>
 78:             <p className="text-[13px]" style={{ color: "rgba(255,255,255,0.86)" }}>{athlete.mainDiscipline ?? "Discipline non renseignée"}</p>
 79:             <div className="flex items-center gap-3 flex-wrap text-[12px] mt-1" style={{ color: "rgba(255,255,255,0.72)" }}>
 80:               <span>{athlete.group ?? "—"}</span>
 81:               <span>·</span>
 82:               <span>{athlete.level ?? "—"}</span>
 83:               <span>·</span>
 84:               <span>{athlete.age ? `${athlete.age} ans` : "—"}</span>
 85:             </div>
 86:           </div>
 87: 
 88:           {/* Métriques inline */}
 89:           <div className="flex items-center gap-3 flex-shrink-0">
 90:             <ScoreRing value={metrics.wellnessScore ?? 0} color="white" label="Bien-être" size={80} />
 91:             <div className="space-y-2 text-[12px]">
 92:               <div className="flex items-center justify-between gap-6">
 93:                 <span style={{ color: "rgba(255,255,255,0.76)" }}>Cette semaine</span>
 94:                 <span className="font-bold text-white">{metrics.load7 ?? "—"}</span>
 95:               </div>
 96:               <div className="flex items-center justify-between gap-6">
 97:                 <span style={{ color: "rgba(255,255,255,0.76)" }}>Rythme habituel · 4 sem.</span>
 98:                 <span className="font-bold text-white">{metrics.load28 ?? "—"}</span>
 99:               </div>
100:               <div className="flex items-center justify-between gap-6">
101:                 <span style={{ color: "rgba(255,255,255,0.76)" }}>Variation</span>
102:                 <span className="font-bold text-white">{metrics.variationPercent == null ? "—" : `${metrics.variationPercent >= 0 ? "+" : ""}${metrics.variationPercent}%`}</span>
103:               </div>
104:             </div>
105:           </div>
106:         </div>
107:       </div>
108: 
109:       {/* Tabs pill premium */}
110:       <SegmentedTabs
111:         className="aos-segmented-tabs--fill"
112:         ariaLabel="Sections du profil athlète"
113:         items={TABS.map((tab) => ({
114:           ...tab,
115:           tabId: `coach-athlete-tab-${tab.id}`,
116:           panelId: "coach-athlete-tabpanel",
117:         }))}
118:         value={activeTab}
119:         onChange={setActiveTab}
120:       />
121: 
122:       {/* Contenu onglet */}
123:       <div
124:         id="coach-athlete-tabpanel"
125:         role="tabpanel"
126:         aria-labelledby={`coach-athlete-tab-${activeTab}`}
127:         className="view-transition"
128:       >
129:         {activeTab === "performances"  && <TabPerformances  athlete={athlete} competitions={competitions} onAddRecord={onAddRecord} />}
130:         {activeTab === "charge"        && <TabCharge        athlete={athlete} metrics={metrics} weeklyCharge={weeklyCharge} competitions={competitions} sessions={sessions} />}
131:         {activeTab === "entrainements" && <TabEntrainements athlete={athlete} sessions={sessions} />}
132:         {activeTab === "blessures"     && <TabBlessures     athlete={athlete} onAddInjury={onAddInjury} onUpdateInjury={onUpdateInjury} onDeleteInjury={onDeleteInjury} />}
133:         {activeTab === "profil"        && <TabProfil        athlete={athlete} />}
134:       </div>
135: 
136:       <ConfirmDialog
137:         open={confirmDelete}
138:         title={`Supprimer ${athlete.name} ?`}
139:         description="Le profil et ses données liées seraient retirés du club. Cette action reste volontairement protégée."
140:         confirmLabel="Supprimer le profil"
141:         loadingLabel="Suppression…"
142:         loading={deleting}
143:         onClose={() => setConfirmDelete(false)}
144:         onConfirm={handleDelete}
145:       />
146:     </div>
147:   );
148: });
