  4: 
  5: import { supabase } from "./supabaseClient";
  6: import { captureError } from "./sentry";
  7: import { getISOWeekYear } from "./helpers";
  8: 
  9: // ── Envoi push générique ──────────────────────────────────────
 10: // Supporte athleteIds (pour les athlètes) ET userIds (pour les coaches)
 11: async function sendWebPush(athleteIds, payload, userIds = []) {
 12:   const hasAthletes = athleteIds?.length > 0;
 13:   const hasUsers    = userIds?.length > 0;
 14:   if (!hasAthletes && !hasUsers) return;
 15: 
 16:   try {
 17:     const { error } = await supabase.functions.invoke("send-push", {
 18:       body: {
 19:         athleteIds: athleteIds ?? [],
 20:         userIds:    userIds    ?? [],
 21:         title: payload.title,
 22:         body:  payload.body,
 23:         url:   payload.url ?? "/",
 24:         tag:   payload.tag ?? "athleteos",
 25:       },
 26:     });
 27:     if (error) captureError(error, {
 28:       operation: "send_web_push",
 29:       athleteCount: athleteIds?.length ?? 0,
 30:       userCount: userIds?.length ?? 0,
 31:     });
 32:   } catch (err) {
 33:     captureError(err, {
 34:       operation: "send_web_push",
 35:       athleteCount: athleteIds?.length ?? 0,
 36:       userCount: userIds?.length ?? 0,
 37:     });
 38:   }
 39: }
