 41: export async function checkAndAlertACWR(clubId, athletes, weeklyCharge, currentWeek) {
 42:   // API conservée pour ne pas casser les appels du Dashboard. La génération
 43:   // automatique d'alertes ACWR est volontairement désactivée : ce ratio
 44:   // expérimental ne permet pas d'inférer un risque individuel.
 45:   void clubId;
 46:   void athletes;
 47:   void weeklyCharge;
 48:   void currentWeek;
 49: }
