 51: export async function alertNewInjury(clubId, athlete, injury) {
 52:   await supabase.from("alerts").insert({
 53:     club_id: clubId, athlete_id: athlete.id, type: "blessure",
 54:     title: `🩺 Blessure signalée — ${athlete.name}`,
 55:     description: `${athlete.name} a signalé : ${injury.name} (${injury.location}), intensité ${injury.intensity}/10.`,
 56:     severity: injury.intensity >= 7 ? "élevée" : injury.intensity >= 4 ? "modérée" : "légère",
 57:     is_read: false,
 58:   });
 59: }
 60: 
 61: export async function alertAthleteSession(clubId, athlete, session) {
 62:   await supabase.from("alerts").insert({
 63:     club_id: clubId, athlete_id: athlete.id, type: "performance",
 64:     title: `📋 Séance planifiée par ${athlete.name}`,
 65:     description: `${athlete.name} a planifié "${session.title}" le ${
 66:       new Date(session.sessionDate || Date.now()).toLocaleDateString("fr-BE", { weekday:"long", day:"numeric", month:"long" })
 67:     }.`,
 68:     severity: "légère", is_read: false,
 69:   });
 70: }
 71: 
 72: export async function alertNewRecord(clubId, athlete, discipline, result, compName) {
 73:   await supabase.from("alerts").insert({
 74:     club_id: clubId, athlete_id: athlete.id, type: "performance",
 75:     title: `🏆 Nouveau record — ${athlete.name}`,
 76:     description: `${athlete.name} a établi un nouveau record en ${discipline} : ${result}${compName ? ` lors de "${compName}"` : ""}.`,
 77:     severity: "info", is_read: false,
 78:   });
 79: }
 80: 
 81: // ── Tâche 14 : dispatch de l'outbox de notifications ──────────────────────
 82: // Les RPC create_solo_competition_result/add_competition_result (voir
 83: // migration 20260730010000) écrivent leurs événements dans
 84: // notification_outbox DANS LA MÊME TRANSACTION que le résultat/record —
 85: // ce n'est qu'APRÈS le retour en succès du RPC (donc après COMMIT
 86: // confirmé) qu'on dépêche ici les vraies notifications, puis qu'on marque
 87: // les événements traités (mark_notification_outbox_sent, la seule façon
 88: // autorisée de modifier notification_outbox depuis le client). Un échec
 89: // de dispatch pour un événement (push indisponible, etc.) n'empêche pas
 90: // les autres de partir — chacun est traité indépendamment.
 91: export async function dispatchOutboxNotifications(notifications) {
 92:   if (!notifications?.length) return;
 93:   const sentIds = [];
 94:   for (const evt of notifications) {
 95:     const p = evt.payload ?? {};
 96:     try {
 97:       if (evt.type === "competition_new_record") {
 98:         await alertNewRecord(p.clubId, { id: p.athleteId, name: p.athleteName }, p.discipline, p.result, p.competitionName);
 99:         await postClubCelebration(p.clubId, p.athleteId, "record",
100:           `${p.athleteName?.split(" ")[0] ?? "Un athlète"} a battu son record en ${p.discipline} : ${p.result} !`);
101:       } else if (evt.type === "competition_result_added") {
102:         await notifyAthleteResult(p.clubId, p.athleteId, p.discipline, p.result, p.competitionName ?? "");
103:       }
104:       sentIds.push(evt.outboxId);
105:     } catch (err) {
106:       console.warn("Échec dispatch notification outbox:", evt.type, err.message ?? err);
107:     }
108:   }
109:   if (sentIds.length) {
110:     const { error } = await supabase.rpc("mark_notification_outbox_sent", { p_ids: sentIds });
111:     if (error) console.warn("mark_notification_outbox_sent :", error.message);
112:   }
113: }
