115: export async function checkUpcomingCompetitions(clubId, competitions) {
116:   const today     = new Date();
117:   const in7days   = new Date(today.getTime() + 7*86400000);
118:   const yesterday = new Date(today.getTime() - 86400000);
119:   for (const comp of competitions) {
120:     const compDate = new Date(comp.date);
121:     if (compDate > yesterday && compDate <= in7days) {
122:       const { data: existing } = await supabase.from("alerts").select("id")
123:         .eq("club_id", clubId).eq("type", "competition")
124:         .ilike("title", `%${comp.name}%`)
125:         .gte("created_at", new Date(Date.now() - 86400000).toISOString()).limit(1);
126:       if (!existing?.length) {
127:         const days = Math.round((compDate - today) / 86400000);
128:         await supabase.from("alerts").insert({
129:           club_id: clubId, athlete_id: null, type: "competition",
130:           title: `🏟️ ${comp.name} — dans ${days === 0 ? "aujourd'hui" : `${days} jour${days>1?"s":""}`}`,
131:           description: `${comp.athleteIds?.length ?? 0} athlète${(comp.athleteIds?.length??0)>1?"s":""} engagé${(comp.athleteIds?.length??0)>1?"s":""}. Vérifier l'état de forme du groupe.`,
132:           severity: days <= 2 ? "élevée" : "modérée", is_read: false,
133:         });
134:       }
135:     }
136:   }
137: }
