302: // ── Récap hebdomadaire (lundi → samedi, envoyé le samedi soir) ─────────────
303: // Déclenché côté client (dans fetchAll du dashboard coach et de l'appli
304: // athlète) — pas de vrai cron serveur pour l'instant, donc ça part dès que
305: // quelqu'un ouvre l'app entre samedi 18h et dimanche minuit. Le dédoublonnage
306: // se fait sur le numéro de semaine dans le titre.
307: function isRecapWindow() {
308:   const now = new Date();
309:   const day = now.getDay(); // 0 = dimanche, 6 = samedi
310:   return (day === 6 && now.getHours() >= 18) || day === 0;
311: }
312: 
313: function computeWeeklyStats(athleteId, sessions) {
314:   const relevant = (sessions ?? []).filter(s =>
315:     s.athleteIds?.includes(athleteId) && s.lifecycleStatus !== "cancelled"
316:   );
317:   let done = 0, partial = 0, none = 0;
318:   relevant.forEach(s => {
319:     const v = s.validations?.find(x => x.athleteId === athleteId);
320:     if (v?.status === "done") done++;
321:     else if (v?.status === "partial") partial++;
322:     else if (v?.status === "none") none++;
323:   });
324:   return { total: relevant.length, done, partial, none };
325: }
326: 
327: // Notif individuelle — utilisée à la fois par le récap coach (en boucle,
328: // un par athlète) et par l'appli athlète elle-même (au cas où le coach n'a
329: // pas ouvert son dashboard le samedi soir).
330: export async function notifyAthleteWeeklyRecap(
331:   clubId,
332:   athlete,
333:   sessions,
334:   currentWeek,
335:   isoYear = getISOWeekYear(new Date()),
336: ) {
337:   if (!isRecapWindow()) return;
338:   const stats = computeWeeklyStats(athlete.id, sessions);
339:   if (stats.total === 0) return;
340: 
341:   const weekKey = `${isoYear}-W${String(currentWeek).padStart(2, "0")}`;
342:   const title = `📊 Ta semaine — S${currentWeek} · ${isoYear}`;
343:   const description = `${stats.done}/${stats.total} séance${stats.total > 1 ? "s" : ""} réalisée${stats.done > 1 ? "s" : ""}` +
344:     (stats.partial ? `, ${stats.partial} partielle${stats.partial > 1 ? "s" : ""}` : "") +
345:     (stats.none ? `, ${stats.none} manquée${stats.none > 1 ? "s" : ""}` : "") + ".";
346:   const dedupeKey = `athlete-recap-${weekKey}`;
347:   const { data: inserted, error } = await supabase.from("athlete_notifications").upsert({
348:     athlete_id: athlete.id, club_id: clubId, type: "weekly_recap", title, description,
349:     is_read: false, dedupe_key: dedupeKey,
350:   }, { onConflict: "athlete_id,type,dedupe_key", ignoreDuplicates: true }).select("id");
351:   if (error) throw error;
352:   if (inserted?.length) await sendWebPush([athlete.id], { title, body: description, tag: dedupeKey });
353: }
