355: // Récap squad-wide pour le coach — une alerte + push, plus le récap
356: // individuel de chaque athlète (déjà en boucle ici, pas besoin que chacun
357: // ouvre son appli pour recevoir le sien).
358: export async function checkWeeklyRecap(
359:   clubId,
360:   athletes,
361:   sessions,
362:   currentWeek,
363:   coachUserId,
364:   isoYear = getISOWeekYear(new Date()),
365: ) {
366:   if (!isRecapWindow()) return;
367: 
368:   let totalAll = 0, doneAll = 0;
369:   const concerns = [];
370:   athletes.forEach(a => {
371:     const stats = computeWeeklyStats(a.id, sessions);
372:     totalAll += stats.total; doneAll += stats.done;
373:     if (stats.total > 0 && (stats.partial > 0 || stats.none > 0)) {
374:       concerns.push(`${a.name.split(" ")[0]} (${stats.done}/${stats.total})`);
375:     }
376:   });
377:   if (totalAll > 0) {
378:     const weekKey = `${isoYear}-W${String(currentWeek).padStart(2, "0")}`;
379:     const pct = Math.round((doneAll / totalAll) * 100);
380:     const title = `📊 Récap S${currentWeek} · ${isoYear}`;
381:     const description = `${doneAll}/${totalAll} séances réalisées (${pct}%).` +
382:       (concerns.length ? ` À suivre : ${concerns.join(", ")}.` : " Toute l'équipe est à jour.");
383:     const dedupeKey = `coach-recap-${weekKey}`;
384:     const { data: inserted, error } = await supabase.from("alerts").upsert({
385:       club_id: clubId, athlete_id: null, type: "recap", title, description,
386:       severity: concerns.length ? "modérée" : "info", is_read: false, dedupe_key: dedupeKey,
387:     }, { onConflict: "club_id,type,dedupe_key", ignoreDuplicates: true }).select("id");
388:     if (error) throw error;
389:     if (inserted?.length && coachUserId) {
390:       await sendWebPush([], { title, body: description, tag: dedupeKey }, [coachUserId]);
391:     }
392:   }
393: 
394:   for (const athlete of athletes) {
395:     await notifyAthleteWeeklyRecap(clubId, athlete, sessions, currentWeek, isoYear);
396:   }
397: }
