399: // ── Rapports hebdomadaires (générés à la volée, pas de table dédiée) ───────
400: // Fenêtre de déclenchement dimanche 18h → lundi 6h — distincte de la
401: // fenêtre du récap ci-dessus (samedi 18h → dimanche minuit), ce sont deux
402: // features séparées avec leurs propres types de notif ("weekly_report" vs
403: // "weekly_recap") donc pas de dédoublonnage croisé possible.
404: function isReportWindow() {
405:   const now = new Date();
406:   const day = now.getDay(); // 0 = dimanche, 1 = lundi
407:   return (day === 0 && now.getHours() >= 18) || (day === 1 && now.getHours() < 6);
408: }
