 17: function dailySeries(length, load = 100, start = "2026-01-01") {
 18:   const first = new Date(`${start}T00:00:00Z`);
 19:   return Array.from({ length }, (_, index) => {
 20:     const date = new Date(first);
 21:     date.setUTCDate(first.getUTCDate() + index);
 22:     return { date: date.toISOString().slice(0, 10), load: typeof load === "function" ? load(index) : load };
 23:   });
 24: }
