 66: function readableErrorMessage(error: unknown): string {
 67:   if (error instanceof Error && error.message.trim() && error.message !== "[object Object]") {
 68:     return error.message;
 69:   }
 70:   if (typeof error === "string" && error.trim() && error !== "[object Object]") return error;
 71:   if (error && typeof error === "object") {
 72:     const value = error as Record<string, unknown>;
 73:     const code = typeof value.code === "string" ? value.code : "";
 74:     if (code === "42P01") return "La mise à jour des invitations n’est pas encore appliquée à la base de données.";
 75:     if (code === "23505") return "Ce code d’invitation existe déjà. Réessaie dans un instant.";
 76:     for (const key of ["message", "details", "hint", "error_description"]) {
 77:       const candidate = value[key];
 78:       if (typeof candidate === "string" && candidate.trim() && candidate !== "[object Object]") return candidate;
 79:     }
 80:   }
 81:   return "Une erreur technique est survenue. Réessaie dans un instant.";
 82: }
