 84: // Erreur "attendue" (autorisation refusée, payload invalide, règle
 85: // métier) — distincte d'une exception inattendue, pour choisir le bon
 86: // `result` ('denied' vs 'error') dans le journal d'audit.
 87: class DeniedError extends Error {}
 88: class PayloadTooLargeError extends DeniedError {}
 89: 
 90: function requireString(value: unknown, label: string, { max = 200 } = {}): string {
 91:   if (typeof value !== "string" || !value.trim()) throw new DeniedError(`${label} manquant.`);
 92:   const trimmed = value.trim();
 93:   if (trimmed.length > max) throw new DeniedError(`${label} trop long (max ${max} caractères).`);
 94:   return trimmed;
 95: }
 96: 
 97: function requirePositiveInt(value: unknown, label: string): number {
 98:   const n = Number(value);
 99:   if (!Number.isInteger(n) || n <= 0) throw new DeniedError(`${label} invalide.`);
100:   return n;
101: }
102: 
103: function optionalAccentColor(value: unknown): string | undefined {
104:   if (value === undefined) return undefined;
105:   if (typeof value !== "string") throw new DeniedError("Couleur d'accent invalide.");
106:   const normalized = value.trim().toUpperCase();
107:   if (!HEX_COLOR_PATTERN.test(normalized)) {
108:     throw new DeniedError("Couleur d'accent invalide (format attendu : #RRGGBB).");
109:   }
110:   return normalized;
111: }
112: 
113: function optionalClubImagePath(
114:   value: unknown,
115:   label: string,
116:   clubId: number,
117: ): string | null | undefined {
118:   if (value === undefined) return undefined;
119:   if (value === null) return null;
120: 
121:   const imagePath = requireString(value, label, { max: 500 });
122:   const segments = imagePath.split("/");
123:   const hasUnsafeSegment = segments.some((segment) => !segment || segment === "." || segment === "..");
124:   if (
125:     segments.length < 2
126:     || segments[0] !== String(clubId)
127:     || hasUnsafeSegment
128:     || /[\\?#]/.test(imagePath)
129:     || !CLUB_IMAGE_PATTERN.test(imagePath)
130:   ) {
131:     throw new DeniedError(
132:       `${label} invalide : l'image doit appartenir au dossier du club et être au format PNG, JPEG ou WebP.`,
133:     );
134:   }
135:   return imagePath;
136: }
137: 
138: function decodeBrandImage(value: unknown): Uint8Array {
139:   const encoded = requireString(value, "Image", { max: 7_100_000 });
140:   if (!/^[A-Za-z0-9+/]+={0,2}$/.test(encoded)) throw new DeniedError("Image encodée invalide.");
141:   let binary = "";
142:   try { binary = atob(encoded); } catch { throw new DeniedError("Image encodée invalide."); }
143:   if (!binary.length || binary.length > MAX_BRAND_IMAGE_SIZE) {
144:     throw new DeniedError("L’image doit peser moins de 5 Mo.");
145:   }
146:   return Uint8Array.from(binary, (character) => character.charCodeAt(0));
147: }
