149: async function ensureBrandingBucket(admin: ReturnType<typeof createClient>) {
150:   const { data: bucket } = await admin.storage.getBucket("club-branding");
151:   if (!bucket) {
152:     const { error } = await admin.storage.createBucket("club-branding", {
153:       public: false,
154:       fileSizeLimit: MAX_BRAND_IMAGE_SIZE,
155:       allowedMimeTypes: Object.keys(BRAND_IMAGE_TYPES),
156:     });
157:     if (error && !/already exists/i.test(error.message ?? "")) throw error;
158:     return;
159:   }
160:   const { error } = await admin.storage.updateBucket("club-branding", {
161:     public: false,
162:     fileSizeLimit: MAX_BRAND_IMAGE_SIZE,
163:     allowedMimeTypes: Object.keys(BRAND_IMAGE_TYPES),
164:   });
165:   if (error) throw error;
166: }
