196:   // ── Contexte mutable rempli au fil de l'exécution, utilisé par le SEUL
197:   //    site d'écriture du journal d'audit (succès en fin de bloc try, ou
198:   //    catch) — évite toute double écriture. ──────────────────────────────
199:   let caller: { id: number; club_id: number; role: string; email: string | null } | null = null;
200:   let currentAction: string | null = null;
201:   let idempotencyKey: string | null = null;
202:   let targetUserId: number | null = null;
203:   let targetClubId: number | null = null;
204:   let auditPayload: Record<string, unknown> | null = null;
205: 
206:   async function logAudit(result: "success" | "denied" | "error", errorMessage: string | null) {
207:     if (!currentAction || !SENSITIVE_ACTIONS.includes(currentAction)) return;
208:     const { error } = await admin.from("audit_logs").insert({
209:       actor_user_id: caller?.id ?? null,
210:       actor_club_id: caller?.club_id ?? null,
211:       action: currentAction,
212:       target_user_id: targetUserId,
213:       target_club_id: targetClubId,
214:       payload: auditPayload,
215:       result,
216:       error_message: errorMessage,
217:       idempotency_key: idempotencyKey,
218:     });
219:     // Un échec d'écriture d'audit ne doit jamais faire planter l'action
220:     // elle-même (déjà exécutée ou déjà refusée à ce stade) — juste tracé
221:     // côté serveur pour investigation.
222:     if (error) console.error("audit_logs insert failed:", error.message);
223:   }
224: 
225:   // Ne rejoue PAS une action déjà exécutée avec succès sous la même clé
226:   // d'idempotence (ex: double-clic, retry réseau). Un échec/refus
227:   // précédent avec la même clé peut en revanche être retenté normalement
228:   // (pas d'effet à dupliquer) — voir l'index partiel de la migration
229:   // 20260729010000 (unique seulement sur les lignes result='success').
230:   async function findCachedSuccess(): Promise<Record<string, unknown> | null> {
231:     if (!idempotencyKey || !currentAction) return null;
232:     const { data, error } = await admin
233:       .from("audit_logs")
234:       .select("payload")
235:       .eq("action", currentAction)
236:       .eq("idempotency_key", idempotencyKey)
237:       .eq("result", "success")
238:       .maybeSingle();
239:     if (error) throw error;
240:     return (data?.payload as Record<string, unknown>) ?? null;
241:   }
242: 
243:   try {
244:     // Identifie l'appelant via son propre JWT (transmis automatiquement par
245:     // supabase.functions.invoke) — jamais faire confiance à un id envoyé
246:     // dans le corps de la requête pour savoir "qui appelle".
247:     const authHeader = req.headers.get("Authorization") ?? "";
248:     const callerClient = createClient(SUPABASE_URL, anonKey, {
249:       global: { headers: { Authorization: authHeader } },
250:     });
251:     const { data: { user: authUser }, error: authError } = await callerClient.auth.getUser();
252:     if (authError || !authUser) throw new DeniedError("Non authentifié.");
253: 
254:     const { data: callerRow, error: callerErr } = await admin
255:       .from("users").select("id, club_id, role, email").eq("auth_uid", authUser.id).single();
256:     if (callerErr || !callerRow) throw new DeniedError("Profil introuvable.");
257:     caller = callerRow;
258:     const isHeadCoach = caller.role === "head_coach";
259: 
260:     const rawBody = await req.text();
261:     if (new TextEncoder().encode(rawBody).byteLength > MAX_BODY_BYTES) {
262:       throw new PayloadTooLargeError("Payload trop volumineux.");
263:     }
264:     let body: Record<string, unknown>;
265:     try { body = JSON.parse(rawBody || "{}"); }
266:     catch { throw new DeniedError("Corps de requête invalide."); }
267:     currentAction = typeof body.action === "string" ? body.action : null;
268:     if (!currentAction) throw new DeniedError("Action manquante.");
269:     idempotencyKey =
270:       typeof body.idempotencyKey === "string" && body.idempotencyKey.trim()
271:         ? body.idempotencyKey.trim().slice(0, 100)
272:         : null;
273: 
274:     // ── update_profile : n'importe quel rôle, jamais audité (pas une
275:     //    action structurelle — modifie toujours SA PROPRE ligne, userId
276:     //    du corps ignoré volontairement) ─────────────────────────────────
277:     if (currentAction === "update_profile") {
278:       const name = requireString(body.name, "Nom");
279:       const { error } = await admin.from("users").update({ name }).eq("id", caller.id);
280:       if (error) throw error;
281:       return ok({});
282:     }
283: 
284:     // Un compte déjà existant peut ouvrir un lien d'invitation. Avec le
285:     // modèle actuel (un compte = un club), on confirme son club sans déplacer
286:     // silencieusement ses données vers une autre structure.
287:     if (currentAction === "accept_club_invitation") {
288:       const inviteCode = normalizeInviteCode(body.inviteCode);
289:       if (!/^[A-Z0-9]{8}$/.test(inviteCode)) {
290:         throw new DeniedError("Le code doit contenir 8 caractères.");
291:       }
292:       const { data: individualInvitation, error: individualError } = await admin
293:         .from("club_invitations")
294:         .select("id")
295:         .ilike("code", inviteCode)
296:         .maybeSingle();
297:       if (individualError && individualError.code !== "42P01") throw individualError;
298: 
299:       if (individualInvitation) {
300:         const { data: acceptance, error: acceptError } = await admin.rpc(
301:           "accept_existing_member_club_invitation",
302:           { p_invitation_id: individualInvitation.id, p_user_id: caller.id, p_email: caller.email ?? "" },
303:         );
304:         if (acceptError) throw acceptError;
305:         const status = typeof acceptance?.status === "string" ? acceptance.status : "invalid";
306:         if (status === "revoked") throw new DeniedError("Cette invitation a été révoquée. Demande un nouveau lien à ton coach.");
307:         if (status === "expired") throw new DeniedError("Cette invitation a expiré. Demande un nouveau lien à ton coach.");
308:         if (status === "email_mismatch") throw new DeniedError("Cette invitation a été préparée pour une autre adresse email.");
309:         if (status === "different_club") throw new DeniedError("Ton compte appartient déjà à un autre club. Aucun transfert n’a été effectué ; contacte ton coach pour conserver tes données.");
310:         if (status === "accepted") throw new DeniedError("Cette invitation a déjà été utilisée.");
311:         if (status !== "accepted_by_caller") throw new DeniedError("Cette invitation n’est plus active. Demande un nouveau lien à ton coach.");
312:         return ok({ alreadyMember: true, clubName: acceptance.clubName ?? "Ton club" });
313:       }
314: 
315:       let { data: invitedClub, error: inviteError } = await admin
316:         .from("clubs")
317:         .select("id, name, invite_code_expires_at")
318:         .ilike("invite_code", inviteCode)
319:         .maybeSingle();
320:       if (inviteError?.code === "42703") {
321:         const legacyResult = await admin.from("clubs").select("id, name").ilike("invite_code", inviteCode).maybeSingle();
322:         invitedClub = legacyResult.data;
323:         inviteError = legacyResult.error;
324:       }
325:       if (inviteError) throw inviteError;
326:       if (!invitedClub) throw new DeniedError("Cette invitation n’est plus active. Demande un nouveau lien à ton coach.");
327:       if (invitedClub.invite_code_expires_at && new Date(invitedClub.invite_code_expires_at) <= new Date()) {
328:         throw new DeniedError("Cette invitation a expiré. Demande un nouveau lien à ton coach.");
329:       }
330:       if (Number(invitedClub.id) !== Number(caller.club_id)) {
331:         throw new DeniedError(`Ton compte appartient déjà à un autre club. Aucun transfert n’a été effectué ; contacte ton coach pour conserver tes données.`);
332:       }
333:       return ok({ alreadyMember: true, clubName: invitedClub.name });
334:     }
335: 
336:     // ── Actions réservées au head coach ─────────────────────────────────
337:     if (!isHeadCoach) throw new DeniedError("Action réservée au head coach.");
338: 
339:     if (currentAction === "list_club_invitations") {
340:       const { data: rows, error } = await admin
341:         .from("club_invitations")
342:         .select("id, code, recipient_name, recipient_email, status, expires_at, opened_at, accepted_at, revoked_at, created_at")
343:         .eq("club_id", caller.club_id)
344:         .order("created_at", { ascending: false })
345:         .limit(100);
346:       if (error?.code === "42P01") return ok({ invitations: [], migrationPending: true });
347:       if (error) throw error;
348:       const now = Date.now();
349:       return ok({ invitations: (rows ?? []).map((row) => ({
350:         id: row.id,
351:         code: row.code,
352:         recipientName: row.recipient_name,
353:         recipientEmail: row.recipient_email,
354:         status: row.status === "revoked"
355:           ? "revoked"
356:           : row.accepted_at
357:             ? "accepted"
358:             : row.expires_at && new Date(row.expires_at).getTime() <= now
359:               ? "expired"
360:               : row.opened_at ? "opened" : "sent",
361:         expiresAt: row.expires_at,
362:         openedAt: row.opened_at,
363:         acceptedAt: row.accepted_at,
364:         revokedAt: row.revoked_at,
365:         createdAt: row.created_at,
366:       })) });
367:     }
368: 
369:     if (currentAction === "create_club_invitation") {
370:       targetClubId = caller.club_id;
371:       const cached = await findCachedSuccess();
372:       if (cached?.invitation) return ok(cached);
373:       const recipientName = typeof body.recipientName === "string" && body.recipientName.trim()
374:         ? body.recipientName.trim().slice(0, 100)
375:         : null;
376:       const recipientEmail = typeof body.recipientEmail === "string" && body.recipientEmail.trim()
377:         ? body.recipientEmail.trim().toLowerCase()
378:         : null;
379:       if (recipientEmail && (recipientEmail.length > 254 || !EMAIL_PATTERN.test(recipientEmail))) {
380:         throw new DeniedError("Adresse email du destinataire invalide.");
381:       }
382:       const expiresInDays = body.expiresInDays == null ? 7 : Number(body.expiresInDays);
383:       if (![1, 3, 7, 14, 30].includes(expiresInDays)) throw new DeniedError("Durée d’invitation invalide.");
384:       const expiresAt = new Date(Date.now() + expiresInDays * 86_400_000).toISOString();
385: 
386:       let code = "";
387:       for (let attempt = 0; attempt < 10; attempt++) {
388:         code = genCode();
389:         const [clubLookup, invitationLookup] = await Promise.all([
390:           admin.from("clubs").select("id").eq("invite_code", code).maybeSingle(),
391:           admin.from("club_invitations").select("id").eq("code", code).maybeSingle(),
392:         ]);
393:         if (clubLookup.error) throw clubLookup.error;
394:         if (invitationLookup.error) throw invitationLookup.error;
395:         const clubMatch = clubLookup.data;
396:         const invitationMatch = invitationLookup.data;
397:         if (!clubMatch && !invitationMatch) break;
398:       }
399:       const { data: invitation, error } = await admin.from("club_invitations").insert({
400:         club_id: caller.club_id,
401:         code,
402:         recipient_name: recipientName,
403:         recipient_email: recipientEmail,
404:         expires_at: expiresAt,
405:         created_by: caller.id,
406:       }).select("id, code, recipient_name, recipient_email, expires_at, created_at").single();
407:       if (error || !invitation) throw error ?? new Error("Invitation non créée.");
408:       const responseInvitation = {
409:         id: invitation.id,
410:         code: invitation.code,
411:         recipientName: invitation.recipient_name,
412:         recipientEmail: invitation.recipient_email,
413:         status: "sent",
414:         expiresAt: invitation.expires_at,
415:         createdAt: invitation.created_at,
416:       };
417:       auditPayload = { invitation: responseInvitation };
418:       await logAudit("success", null);
419:       return ok({ invitation: responseInvitation });
420:     }
421: 
422:     if (currentAction === "revoke_club_invitation") {
423:       targetClubId = caller.club_id;
424:       const invitationId = requireString(body.invitationId, "Invitation", { max: 36 });
425:       if (!UUID_PATTERN.test(invitationId)) throw new DeniedError("Invitation invalide.");
426:       const { data: invitation, error: invitationError } = await admin.from("club_invitations")
427:         .select("id, status, accepted_at")
428:         .eq("id", invitationId).eq("club_id", caller.club_id).maybeSingle();
429:       if (invitationError) throw invitationError;
430:       if (!invitation) throw new DeniedError("Invitation introuvable.");
431:       if (invitation.accepted_at) throw new DeniedError("Une invitation acceptée ne peut plus être révoquée.");
432:       if (invitation.status === "revoked") return ok({});
433:       const revokedAt = new Date().toISOString();
434:       const { data: revoked, error } = await admin.from("club_invitations").update({ status: "revoked", revoked_at: revokedAt })
435:         .eq("id", invitationId).eq("club_id", caller.club_id)
436:         .eq("status", "active").is("accepted_at", null)
437:         .select("id").maybeSingle();
438:       if (error) throw error;
439:       if (!revoked) throw new DeniedError("L’invitation a changé d’état. Recharge la liste avant de réessayer.");
440:       auditPayload = { invitationId, revokedAt };
441:       await logAudit("success", null);
442:       return ok({});
443:     }
444: 
445:     if (currentAction === "rename_club") {
446:       targetClubId = caller.club_id;
447:       const cached = await findCachedSuccess();
448:       if (cached) return ok(cached);
449: 
450:       const clubName = requireString(body.clubName, "Nom du club", { max: 100 });
451:       const { error } = await admin.from("clubs").update({ name: clubName }).eq("id", caller.club_id);
452:       if (error) throw error;
453: 
454:       auditPayload = { clubName };
455:       await logAudit("success", null);
456:       return ok({});
457:     }
458: 
459:     if (currentAction === "upload_club_branding") {
460:       targetClubId = caller.club_id;
461:       const kind = requireString(body.kind, "Type d’image", { max: 10 });
462:       if (kind !== "logo" && kind !== "cover") throw new DeniedError("Type d’image invalide.");
463:       const contentType = requireString(body.contentType, "Format d’image", { max: 50 }).toLowerCase();
464:       const extension = BRAND_IMAGE_TYPES[contentType];
465:       if (!extension) throw new DeniedError("Utilise une image PNG, JPEG ou WebP.");
466:       const bytes = decodeBrandImage(body.fileBase64);
467: 
468:       await ensureBrandingBucket(admin);
469:       const path = `${caller.club_id}/${kind}-${crypto.randomUUID()}.${extension}`;
470:       const { error } = await admin.storage.from("club-branding").upload(path, bytes, {
471:         contentType,
472:         cacheControl: "3600",
473:         upsert: false,
474:       });
475:       if (error) throw error;
476: 
477:       auditPayload = { kind, path, size: bytes.byteLength };
478:       await logAudit("success", null);
479:       return ok({ path });
480:     }
481: 
482:     if (currentAction === "update_club_branding") {
483:       targetClubId = caller.club_id;
484:       const cached = await findCachedSuccess();
485:       if (cached) return ok(cached);
486: 
487:       const logoPath = optionalClubImagePath(body.logoPath, "Chemin du logo", caller.club_id);
488:       const coverPath = optionalClubImagePath(body.coverPath, "Chemin de la couverture", caller.club_id);
489:       const accentColor = optionalAccentColor(body.accentColor);
490:       if (logoPath === undefined && coverPath === undefined && accentColor === undefined) {
491:         throw new DeniedError("Aucune personnalisation à mettre à jour.");
492:       }
493: 
494:       const updates: Record<string, string | null> = {};
495:       if (logoPath !== undefined) updates.logo_path = logoPath;
496:       if (coverPath !== undefined) updates.cover_path = coverPath;
497:       if (accentColor !== undefined) updates.accent_color = accentColor;
498: 
499:       const { data: previousClub } = await admin
500:         .from("clubs")
501:         .select("logo_path, cover_path")
502:         .eq("id", caller.club_id)
503:         .single();
504:       const { data: updatedClub, error } = await admin
505:         .from("clubs")
506:         .update(updates)
507:         .eq("id", caller.club_id)
508:         .select("logo_path, cover_path, accent_color")
509:         .single();
510:       if (error || !updatedClub) throw error ?? new Error("Club introuvable.");
511: 
512:       const obsoletePaths = [
513:         previousClub?.logo_path && previousClub.logo_path !== updatedClub.logo_path ? previousClub.logo_path : null,
514:         previousClub?.cover_path && previousClub.cover_path !== updatedClub.cover_path ? previousClub.cover_path : null,
515:       ].filter(Boolean) as string[];
516:       if (obsoletePaths.length) {
517:         const { error: cleanupError } = await admin.storage.from("club-branding").remove(obsoletePaths);
518:         if (cleanupError) console.error("club-branding cleanup failed:", cleanupError.message);
519:       }
520: 
521:       const branding = {
522:         logoPath: updatedClub.logo_path,
523:         coverPath: updatedClub.cover_path,
524:         accentColor: updatedClub.accent_color,
525:       };
526:       auditPayload = { branding };
527:       await logAudit("success", null);
528:       return ok({ branding });
529:     }
530: 
531:     if (currentAction === "regenerate_invite_code") {
532:       targetClubId = caller.club_id;
533:       const cached = await findCachedSuccess();
534:       if (cached) return ok(cached);
535: 
536:       let code = "";
537:       for (let attempt = 0; attempt < 6; attempt++) {
538:         code = genCode();
539:         const [clubLookup, invitationLookup] = await Promise.all([
540:           admin.from("clubs").select("id").eq("invite_code", code).maybeSingle(),
541:           admin.from("club_invitations").select("id").eq("code", code).maybeSingle(),
542:         ]);
543:         if (clubLookup.error && clubLookup.error.code !== "42P01") throw clubLookup.error;
544:         if (invitationLookup.error && invitationLookup.error.code !== "42P01") throw invitationLookup.error;
545:         if (!clubLookup.data && !invitationLookup.data) break;
546:       }
547:       let { error } = await admin.from("clubs").update({
548:         invite_code: code,
549:         invite_code_created_at: new Date().toISOString(),
550:         invite_code_use_count: 0,
551:         invite_code_last_used_at: null,
552:         invite_code_expires_at: null,
553:       }).eq("id", caller.club_id);
554:       if (error?.code === "42703") {
555:         const legacyUpdate = await admin.from("clubs").update({ invite_code: code }).eq("id", caller.club_id);
556:         error = legacyUpdate.error;
557:       }
558:       if (error) throw error;
559: 
560:       auditPayload = { inviteCode: code };
561:       await logAudit("success", null);
562:       return ok({ inviteCode: code });
563:     }
564: 
565:     if (currentAction === "remove_user") {
566:       const cached = await findCachedSuccess();
567:       if (cached) return ok({});
568: 
569:       const userId = requirePositiveInt(body.userId, "Identifiant utilisateur");
570:       const { data: targetRow } = await admin.from("users").select("id, club_id, auth_uid, role, name, email").eq("id", userId).single();
571:       if (!targetRow) throw new DeniedError("Utilisateur introuvable.");
572:       targetClubId = targetRow.club_id;
573:       if (targetRow.club_id !== caller.club_id) throw new DeniedError("Cet utilisateur n'est pas dans ton club.");
574:       if (targetRow.id === caller.id) throw new DeniedError("Tu ne peux pas te retirer toi-même.");
575: 
576:       // Note : comme seul un head coach peut appeler remove_user (voir plus
577:       // haut) et que l'auto-suppression est bloquée juste au-dessus, ce
578:       // garde-fou ne peut se déclencher aujourd'hui QUE si caller === target
579:       // — un cas déjà intercepté avant. Gardé quand même en défense en
580:       // profondeur (le jour où l'auto-suppression serait autorisée, ou pour
581:       // un futur appel service-to-service qui ne passerait pas par cette
582:       // fonction) : si jamais retiré plus tard sans plus y penser, ce
583:       // contrôle protège encore.
584:       if (targetRow.role === "head_coach") {
585:         const { count } = await admin.from("users")
586:           .select("id", { count: "exact", head: true })
587:           .eq("club_id", caller.club_id).eq("role", "head_coach").neq("id", targetRow.id);
588:         if (!count) {
589:           auditPayload = { targetUserId: targetRow.id, targetName: targetRow.name };
590:           throw new DeniedError("Impossible de supprimer le dernier head coach du club. Transfère d'abord le rôle à un autre membre (change_role).");
591:         }
592:       }
593: 
594:       // Snapshot avant suppression : une fois la ligne `users` supprimée,
595:       // target_user_id ne peut plus être référencé par l'audit (contrainte
596:       // de clé étrangère) — on garde l'essentiel dans `payload`.
597:       auditPayload = { targetUserId: targetRow.id, targetName: targetRow.name, targetEmail: targetRow.email, targetRole: targetRow.role };
598: 
599:       const { data: deletion, error: deletionError } = await admin.rpc("remove_club_user_transactional", {
600:         p_actor_user_id: caller.id,
601:         p_target_user_id: targetRow.id,
602:       });
603:       if (deletionError) throw deletionError;
604:       const authUid = deletion?.authUid ?? targetRow.auth_uid;
605:       if (authUid) {
606:         const { error: authDeleteError } = await admin.auth.admin.deleteUser(authUid);
607:         if (authDeleteError) {
608:           auditPayload = { ...auditPayload, authCleanupPending: true };
609:           console.error("Auth user cleanup failed:", authDeleteError.message);
610:         }
611:       }
612: 
613:       await logAudit("success", null);
614:       return ok({});
615:     }
616: 
617:     if (currentAction === "change_role") {
618:       const cached = await findCachedSuccess();
619:       if (cached) return ok({});
620: 
621:       const userId = requirePositiveInt(body.userId, "Identifiant utilisateur");
622:       const role = requireString(body.role, "Rôle", { max: 20 });
623:       if (!VALID_ROLES.includes(role)) throw new DeniedError("Rôle invalide.");
624: 
625:       const { data: targetRow } = await admin.from("users").select("id, club_id, role, name").eq("id", userId).single();
626:       if (!targetRow) throw new DeniedError("Utilisateur introuvable.");
627:       targetUserId = targetRow.id;
628:       targetClubId = targetRow.club_id;
629:       if (targetRow.club_id !== caller.club_id) throw new DeniedError("Cet utilisateur n'est pas dans ton club.");
630:       if (targetRow.id === caller.id) throw new DeniedError("Tu ne peux pas changer ton propre rôle depuis cet écran.");
631:       if (targetRow.role === role) throw new DeniedError("Ce membre a déjà ce rôle.");
632: 
633:       // Même remarque que dans remove_user : avec l'auto-cible déjà bloquée
634:       // juste au-dessus, ce garde-fou ne peut mathématiquement se déclencher
635:       // que si caller === target — déjà intercepté. Gardé en défense en
636:       // profondeur.
637:       if (targetRow.role === "head_coach" && role !== "head_coach") {
638:         const { count } = await admin.from("users")
639:           .select("id", { count: "exact", head: true })
640:           .eq("club_id", caller.club_id).eq("role", "head_coach").neq("id", targetRow.id);
641:         if (!count) {
642:           auditPayload = { targetName: targetRow.name, fromRole: targetRow.role, toRole: role };
643:           throw new DeniedError("Impossible de rétrograder le dernier head coach du club. Promeus d'abord un autre membre.");
644:         }
645:       }
646: 
647:       const { error } = await admin.from("users").update({ role }).eq("id", targetRow.id);
648:       if (error) throw error;
649: 
650:       auditPayload = { targetName: targetRow.name, fromRole: targetRow.role, toRole: role };
651:       await logAudit("success", null);
652:       return ok({});
653:     }
654: 
655:     throw new DeniedError("Action inconnue.");
656:   } catch (err) {
657:     const internalMessage = readableErrorMessage(err);
658:     const denied = err instanceof DeniedError;
659:     const clientMessage = denied ? internalMessage : "Une erreur technique est survenue. Réessaie dans un instant.";
660:     await logAudit(denied ? "denied" : "error", internalMessage).catch((auditError) => {
661:       console.error(
662:         "admin-actions audit failure:",
663:         auditError instanceof Error ? auditError.message : auditError,
664:       );
665:     });
666:     console.error("admin-actions error:", internalMessage);
667:     return new Response(JSON.stringify({ success: false, error: clientMessage }), {
668:       status: 200,
669:       headers: { ...corsHeaders, "Content-Type": "application/json" },
670:     });
671:   }
