 16: import { useState, useMemo, useRef } from "react";
 17: import {
 18:   Plus, ChevronLeft, ChevronRight, Clock, CalendarDays, CheckCircle,
 19: } from "lucide-react";
 20: import { MONTHS_FR, CATEGORIES, isSameDay, toLocalDateStr } from "../shared";
 21: import { getSessionTrainingFocus } from "../../domain/trainingFocus";
 22: import { isSessionArchived } from "../../domain/sessionArchive";
 23: import { parseLocalDate } from "../../utils/helpers";
 24: import { cat, rpeColor } from "./planningUtils";
 25: import { StatusBadge } from "./planningShared";
 26: import CreateSessionModal from "./CreateSessionModal";
 27: import SessionDetailModal from "./SessionDetailModal";
 28: 
 29: // Ré-export — AthleteDashboard.jsx importe SessionDetailModal depuis ce
 30: // fichier (`import { SessionDetailModal } from "./AthletePlanning"`), donc
 31: // on garde ce point d'entrée même si la définition a été déplacée dans son
 32: // propre fichier.
