 35: function SessionCard({ session, athleteId, isPast = false, compact = false, onOpen, onStatusChange }) {
 36:   const c = cat(session.category);
 37:   const val = session.validations?.find(v => v.athleteId === athleteId);
 38:   const status = val?.status ?? "future";
 39:   const rpeNeeded = isPast && val?.rpe == null && status !== "none" && status !== "future";
 40:   const canSwipe = !compact && status !== "done" && status !== "none";
 41:   const [dragX, setDragX] = useState(0);
 42:   const [dragging, setDragging] = useState(false);
 43:   const touchStartX = useRef(0);
 44:   const justSwiped = useRef(false);
 45: 
 46:   const openSession = () => {
 47:     if (justSwiped.current) {
 48:       justSwiped.current = false;
 49:       return;
 50:     }
 51:     onOpen(session);
 52:   };
 53: 
 54:   const handleKeyDown = event => {
 55:     if (event.key === "Enter" || event.key === " ") {
 56:       event.preventDefault();
 57:       openSession();
 58:     }
 59:   };
 60: 
 61:   const onTouchStart = event => {
 62:     if (!canSwipe) return;
 63:     touchStartX.current = event.touches[0].clientX;
 64:     justSwiped.current = false;
 65:     setDragging(true);
 66:   };
 67: 
 68:   const onTouchMove = event => {
 69:     if (!canSwipe || !dragging) return;
 70:     const delta = event.touches[0].clientX - touchStartX.current;
 71:     if (delta > 0) setDragX(Math.min(delta, 110));
 72:   };
 73: 
 74:   const onTouchEnd = () => {
 75:     if (!canSwipe) return;
 76:     setDragging(false);
 77:     if (dragX > 72) {
 78:       justSwiped.current = true;
 79:       onStatusChange(session.id, athleteId, "done");
 80:     }
 81:     setDragX(0);
 82:   };
 83: 
 84:   if (compact) {
 85:     return (
 86:       <div
 87:         role="button"
 88:         tabIndex={0}
 89:         aria-label={`Ouvrir la séance ${session.title}`}
 90:         onClick={event => { event.stopPropagation(); onOpen(session); }}
 91:         onKeyDown={event => {
 92:           event.stopPropagation();
 93:           handleKeyDown(event);
 94:         }}
 95:         className="tap-feedback truncate"
 96:         style={{
 97:           display: "flex", alignItems: "center", gap: 8, minHeight: 32, padding: "6px 8px", borderRadius: 8,
 98:           fontSize: 12, fontWeight: 700, cursor: "pointer",
 99:           background: c.bg, color: c.text, borderLeft: `3px solid ${c.border}`,
100:         }}
101:       >
102:         <span className="truncate" style={{ flex: 1 }}>{session.title}</span>
103:         {status === "done" && <CheckCircle size={12} color="#3DBE8B" style={{ flexShrink: 0 }} aria-hidden="true" />}
104:       </div>
105:     );
106:   }
107: 
108:   return (
109:     <div style={{ position: "relative" }}>
110:       {canSwipe && (
111:         <div aria-hidden="true" style={{
112:           position: "absolute", inset: 0, borderRadius: 16, display: "flex", alignItems: "center", paddingLeft: 20,
113:           background: "linear-gradient(90deg, rgba(29,158,117,0.95), rgba(29,158,117,0.55))",
114:           opacity: Math.min(1, dragX / 55), pointerEvents: "none",
115:         }}>
116:           <CheckCircle size={20} color="white" strokeWidth={2.5} />
117:           <span style={{ color: "white", fontWeight: 800, fontSize: 13, marginLeft: 8 }}>Valider</span>
118:         </div>
119:       )}
120:       <div
121:         role="button"
122:         tabIndex={0}
123:         aria-label={`Ouvrir la séance ${session.title}`}
124:         onClick={openSession}
125:         onKeyDown={handleKeyDown}
126:         onTouchStart={onTouchStart}
127:         onTouchMove={onTouchMove}
128:         onTouchEnd={onTouchEnd}
129:         className="card card-hover tap-feedback"
130:         style={{
131:           overflow: "hidden", cursor: "pointer",
132:           transform: dragX ? `translateX(${dragX}px)` : undefined,
133:           transition: dragging ? "none" : "transform 0.25s cubic-bezier(0.16,1,0.3,1)",
134:           ...(rpeNeeded ? { borderWidth: 2, borderColor: "#EAB308", boxShadow: "0 0 0 3px rgba(234,179,8,0.14)" } : {}),
135:         }}
136:       >
137:         <div style={{ padding: "12px 16px", display: "flex", alignItems: "center", justifyContent: "space-between", gap: 12, background: c.bg, borderBottom: `1px solid ${c.border}40` }}>
138:           <div style={{ display: "flex", alignItems: "center", gap: 8, minWidth: 0, flexWrap: "wrap" }}>
139:             <span style={{ fontSize: 12, fontWeight: 800, textTransform: "uppercase", letterSpacing: "0.06em", padding: "4px 10px", borderRadius: 99, background: c.border, color: "#0A150F" }}>
140:               {CATEGORIES.find(x => x.id === session.category)?.label ?? session.type}
141:             </span>
142:             <span className="chip chip-neutral">{getSessionTrainingFocus(session).shortLabel}</span>
143:             {session.pdfUrl && (
144:               <span style={{ fontSize: 12, fontWeight: 700, padding: "3px 8px", borderRadius: 99, background: "rgba(91,158,245,0.16)", color: "var(--tone-info)" }}>
145:                 Fichier
146:               </span>
147:             )}
148:           </div>
149:           <StatusBadge status={status} size="sm" />
150:         </div>
151:         <div style={{ padding: 16 }}>
152:           <p style={{ fontSize: 15, fontWeight: 800, lineHeight: 1.35, marginBottom: 8, color: "var(--c-text-1)" }}>{session.title}</p>
153:           <div style={{ display: "flex", alignItems: "center", gap: 12, fontSize: 12, color: "var(--c-text-2)", marginBottom: 8, flexWrap: "wrap" }}>
154:             <span style={{ display: "flex", alignItems: "center", gap: 4 }}><Clock size={13} aria-hidden="true" /> {session.time}</span>
155:             {session.durationMinutes && <span>{session.durationMinutes} min</span>}
156:             {val?.rpe != null && <span style={{ fontWeight: 700, color: rpeColor(val.rpe).active }}>RPE {val.rpe}/10</span>}
157:           </div>
158:           {session.instructions && (
159:             <p style={{ fontSize: 13, lineHeight: 1.5, color: "var(--tone-warning)", background: "rgba(234,179,8,0.08)", borderRadius: 12, padding: "8px 12px", marginBottom: 8 }} className="line-clamp-2">
160:               {session.instructions}
161:             </p>
162:           )}
163:           {rpeNeeded && (
164:             <p style={{ fontSize: 12, fontWeight: 700, color: "var(--tone-warning)", display: "flex", alignItems: "center", gap: 8 }}>
165:               <span style={{ width: 6, height: 6, borderRadius: "50%", background: "#EAB308" }} className="animate-pulse-soft" />
166:               Valide ta séance
167:             </p>
168:           )}
169:         </div>
170:       </div>
171:     </div>
172:   );
173: }
