175: // ═══════════════════════════════════════════════════════════════════════════════
176: // COMPOSANT PRINCIPAL — AthletePlanning
177: // ═══════════════════════════════════════════════════════════════════════════════
178: export default function AthletePlanning({
179:   athlete, sessions, allAthletes, clubId, createdBy, coachUserId,
180:   onRpeChange, onStatusChange, onFeelingChange, onCommentChange, onRsvpChange, onRefresh,
181: }) {
182:   const todayKey = toLocalDateStr(new Date());
183:   const today    = useMemo(() => parseLocalDate(todayKey), [todayKey]);
184:   const isMobile = typeof window !== "undefined" && window.innerWidth < 768;
185: 
186:   const [viewYear,      setViewYear]      = useState(today.getFullYear());
187:   const [viewMonth,     setViewMonth]     = useState(today.getMonth());
188:   const [viewMode,      setViewMode]      = useState(isMobile ? "agenda" : "month");
189:   const [selectedDate,  setSelectedDate]  = useState(today);
190:   const [activeSession, setActiveSession] = useState(null);
191:   const [showCreate,    setShowCreate]    = useState(false);
192: 
193:   const sessionsByDate = useMemo(() => {
194:     const map = {};
195:     sessions.forEach(s => {
196:       if (!s.sessionDate) return;
197:       const key = s.sessionDate.slice(0, 10);
198:       if (!map[key]) map[key] = [];
199:       map[key].push(s);
200:     });
201:     return map;
202:   }, [sessions]);
203: 
204:   const calDays = useMemo(() => {
205:     const first    = new Date(viewYear, viewMonth, 1);
206:     const last     = new Date(viewYear, viewMonth + 1, 0);
207:     const startDow = (first.getDay() + 6) % 7;
208:     const days     = [];
209:     for (let i = startDow - 1; i >= 0; i--) days.push({ date: new Date(viewYear, viewMonth, -i), cur: false });
210:     for (let d = 1; d <= last.getDate(); d++) days.push({ date: new Date(viewYear, viewMonth, d), cur: true });
211:     const rem = 7 - (days.length % 7);
212:     if (rem < 7) for (let d = 1; d <= rem; d++) days.push({ date: new Date(viewYear, viewMonth + 1, d), cur: false });
213:     return days;
214:   }, [viewYear, viewMonth]);
215: 
216:   const weekDays = useMemo(() => {
217:     const ref = selectedDate;
218:     const dow = (ref.getDay() + 6) % 7;
219:     const mon = new Date(ref);
220:     mon.setDate(ref.getDate() - dow);
221:     return Array.from({ length: 7 }, (_, i) => {
222:       const d = new Date(mon); d.setDate(mon.getDate() + i); return d;
223:     });
224:   }, [selectedDate]);
225: 
226:   const groupedAgenda = useMemo(() => {
227:     const sorted = [...sessions].filter(s => s.sessionDate && !isSessionArchived(s, today)).sort((a, b) => a.sessionDate.localeCompare(b.sessionDate));
228:     const groups = []; const seen = new Set();
229:     sorted.forEach(s => {
230:       const key = s.sessionDate.slice(0, 10);
231:       if (!seen.has(key)) { seen.add(key); groups.push({ date: key, sessions: [] }); }
232:       groups.find(g => g.date === key).sessions.push(s);
233:     });
234:     return groups;
235:   }, [sessions, today]);
236: 
237:   const groupedArchives = useMemo(() => {
238:     const sorted = [...sessions].filter(s => s.sessionDate && isSessionArchived(s, today)).sort((a, b) => b.sessionDate.localeCompare(a.sessionDate));
239:     const groups = []; const seen = new Set();
240:     sorted.forEach(s => {
241:       const key = s.sessionDate.slice(0, 10);
242:       if (!seen.has(key)) { seen.add(key); groups.push({ date: key, sessions: [] }); }
243:       groups.find(g => g.date === key).sessions.push(s);
244:     });
245:     return groups;
246:   }, [sessions, today]);
247: 
248:   const archivedSessionCount = groupedArchives.reduce((total, group) => total + group.sessions.length, 0);
249:   const displayedAgenda = viewMode === "archive" ? groupedArchives : groupedAgenda;
250: 
251:   const prevMonth = () => { if (viewMonth === 0) { setViewYear(y => y-1); setViewMonth(11); } else setViewMonth(m => m-1); };
252:   const nextMonth = () => { if (viewMonth === 11) { setViewYear(y => y+1); setViewMonth(0); } else setViewMonth(m => m+1); };
253:   const prevWeek  = () => { const d = new Date(selectedDate ?? today); d.setDate(d.getDate()-7); setSelectedDate(d); };
254:   const nextWeek  = () => { const d = new Date(selectedDate ?? today); d.setDate(d.getDate()+7); setSelectedDate(d); };
255:   const goToday   = () => { setViewYear(today.getFullYear()); setViewMonth(today.getMonth()); setSelectedDate(today); };
256: 
257:   const liveActive = activeSession ? sessions.find(s => s.id === activeSession.id) ?? activeSession : null;
258: 
259:   const navLabel = useMemo(() => {
260:     if (viewMode === "month")  return `${MONTHS_FR[viewMonth]} ${viewYear}`;
261:     if (viewMode === "agenda") return "Mes séances";
262:     if (viewMode === "archive") return `Archives · ${archivedSessionCount}`;
263:     const mon = weekDays[0], sun = weekDays[6];
264:     if (mon.getMonth() === sun.getMonth())
265:       return `${mon.getDate()} – ${sun.toLocaleDateString("fr-BE", { day: "numeric", month: "long" })}`;
266:     return `${mon.toLocaleDateString("fr-BE", { day: "numeric", month: "short" })} – ${sun.toLocaleDateString("fr-BE", { day: "numeric", month: "short" })}`;
267:   }, [viewMode, viewMonth, viewYear, weekDays, archivedSessionCount]);
268: 
269:   // ══════════════════════════════════════════════════════════════════════════════
270:   return (
271:     <div className="flex flex-col h-full" style={{ background: "var(--c-bg)" }}>
272: 
273:       <header className="header-glass px-4 md:px-6 py-4 flex-shrink-0 z-10">
274:         <div className="flex flex-col gap-4">
275:           <div className="flex items-start justify-between gap-4">
276:             <div className="min-w-0">
277:               <h1 className="page-title">Mon planning</h1>
278:               <p style={{ fontSize: 13, color: "var(--c-text-2)", marginTop: 4 }}>
279:                 Consulte et valide tes séances d’entraînement.
280:               </p>
281:             </div>
282:             <button type="button" onClick={() => setShowCreate(true)} className="btn-primary" style={{ flexShrink: 0 }}>
283:               <Plus size={16} aria-hidden="true" /><span className="hidden sm:inline">Planifier</span>
284:             </button>
285:           </div>
286: 
287:           <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3">
288:             <div className="flex items-center gap-1 min-w-0">
289:               {!['agenda', 'archive'].includes(viewMode) && (
290:                 <button type="button" aria-label="Période précédente" onClick={viewMode === "month" ? prevMonth : prevWeek}
291:                   className="tap-feedback"
292:                   style={{ width: 44, height: 44, borderRadius: 12, display: "flex", alignItems: "center", justifyContent: "center", background: "var(--c-surface-2)", border: "1px solid var(--c-border)", cursor: "pointer", color: "var(--c-text-2)", flexShrink: 0 }}>
293:                   <ChevronLeft size={18} aria-hidden="true" />
294:                 </button>
295:               )}
296:               <p style={{ fontSize: 15, fontWeight: 800, padding: "0 8px", minWidth: 0, flex: 1, textAlign: ['agenda', 'archive'].includes(viewMode) ? "left" : "center", color: "var(--c-text-1)" }} className="truncate">
297:                 {navLabel}
298:               </p>
299:               {!['agenda', 'archive'].includes(viewMode) && (
300:                 <button type="button" aria-label="Période suivante" onClick={viewMode === "month" ? nextMonth : nextWeek}
301:                   className="tap-feedback"
302:                   style={{ width: 44, height: 44, borderRadius: 12, display: "flex", alignItems: "center", justifyContent: "center", background: "var(--c-surface-2)", border: "1px solid var(--c-border)", cursor: "pointer", color: "var(--c-text-2)", flexShrink: 0 }}>
303:                   <ChevronRight size={18} aria-hidden="true" />
304:                 </button>
305:               )}
306:               {!['agenda', 'archive'].includes(viewMode) && (
307:                 <button type="button" onClick={goToday}
308:                   style={{ minHeight: 44, padding: "0 12px", borderRadius: 12, fontSize: 12, fontWeight: 700, border: "1px solid var(--c-border-strong)", color: "var(--c-text-2)", background: "var(--c-surface-2)", cursor: "pointer", marginLeft: 4 }}>
309:                   <span className="hidden sm:inline">Aujourd’hui</span><span className="sm:hidden">Auj.</span>
310:                 </button>
311:               )}
312:             </div>
313: 
314:             <div role="group" aria-label="Affichage du planning" style={{ display: "grid", gridTemplateColumns: "repeat(4, 1fr)", borderRadius: 12, overflow: "hidden", border: "1px solid var(--c-border-strong)" }}>
315:               {[{ id: "agenda", label: "Liste" }, { id: "month", label: "Mois" }, { id: "week", label: "Semaine" }, { id: "archive", label: `Archives (${archivedSessionCount})` }].map(view => (
316:                 <button key={view.id} type="button" onClick={() => setViewMode(view.id)} aria-pressed={viewMode === view.id}
317:                   style={{
318:                     minHeight: 44, padding: "0 14px", fontSize: 13, fontWeight: 700, border: "none", cursor: "pointer",
319:                     background: viewMode === view.id ? "var(--c-accent)" : "var(--c-surface-2)",
320:                     color: viewMode === view.id ? "#07130F" : "var(--c-text-2)",
321:                   }}>
322:                   {view.label}
323:                 </button>
324:               ))}
325:             </div>
326:           </div>
327:         </div>
328:       </header>
329: 
330:       {/* ══════════════════════════════════════════════════════════════════════
331:           VUE AGENDA
332:          ══════════════════════════════════════════════════════════════════════ */}
333:       {(viewMode === "agenda" || viewMode === "archive") && (
334:         <div className="flex-1 overflow-y-auto">
335:           {displayedAgenda.length === 0 ? (
336:             <div className="flex flex-col items-center justify-center h-full gap-4 p-8">
337:               <div style={{ width: 64, height: 64, borderRadius: 20, background: "var(--c-surface-2)", display: "flex", alignItems: "center", justifyContent: "center" }}>
338:                 <CalendarDays size={28} color="var(--c-text-3)" strokeWidth={1.5} />
339:               </div>
340:               <div style={{ textAlign: "center" }}>
341:                 <p style={{ fontSize: 15, fontWeight: 700, color: "var(--c-text-2)" }}>{viewMode === "archive" ? "Aucune séance archivée" : "Aucune séance planifiée"}</p>
342:                 <p style={{ fontSize: 13, color: "var(--c-text-2)", marginTop: 4 }}>{viewMode === "archive" ? "Les séances de plus de 7 jours apparaîtront ici." : "Ton coach ou toi pouvez planifier des séances"}</p>
343:               </div>
344:               {viewMode !== "archive" && (
