351:             <div className="p-4 md:p-6 space-y-6">
352:               {displayedAgenda.map(({ date, sessions: ds }) => {
353:                 const dateObj = parseLocalDate(date);
354:                 const isToday = isSameDay(dateObj, today);
355:                 const isPast  = toLocalDateStr(dateObj) < toLocalDateStr(today);
356:                 return (
357:                   <div key={date}>
358:                     <div className="flex items-center gap-3 mb-3">
359:                       <div style={{
360:                         width: 48, height: 48, borderRadius: 16, flexShrink: 0, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center",
361:                         background: isToday ? "linear-gradient(135deg, #1D9E75, #16826C)" : "var(--c-surface-2)",
362:                         border: isToday ? "none" : "1px solid var(--c-border)",
363:                       }}>
364:                         <span style={{ fontSize: 12, fontWeight: 800, textTransform: "uppercase", lineHeight: 1, color: isToday ? "rgba(255,255,255,0.82)" : "var(--c-text-2)" }}>
365:                           {dateObj.toLocaleDateString("fr-BE", { weekday: "short" }).replace(".", "")}
366:                         </span>
367:                         <span style={{ fontSize: 18, fontWeight: 800, lineHeight: 1.2, color: isToday ? "white" : (isPast ? "var(--c-text-3)" : "var(--c-text-1)") }}>
368:                           {dateObj.getDate()}
369:                         </span>
370:                       </div>
371:                       <div>
372:                         <p style={{ fontSize: 14, fontWeight: 800, color: isToday ? "#7BD8B4" : (isPast ? "var(--c-text-2)" : "var(--c-text-1)") }}>
373:                           {isToday ? "Aujourd'hui" : dateObj.toLocaleDateString("fr-BE", { weekday: "long", day: "numeric", month: "long" })}
374:                         </p>
375:                         <p style={{ fontSize: 12, color: "var(--c-text-2)", marginTop: 2 }}>
376:                           {ds.length} séance{ds.length > 1 ? "s" : ""}
