381:                       {ds.sort((a, b) => (a.time ?? "").localeCompare(b.time ?? "")).map(s => (
382:                         <SessionCard key={s.id} session={s} athleteId={athlete.id} isPast={isPast} onOpen={setActiveSession} onStatusChange={onStatusChange} />
383:                       ))}
384:                     </div>
385:                   </div>
386:                 );
387:               })}
388:             </div>
389:           )}
390:         </div>
391:       )}
