393:       {/* ══════════════════════════════════════════════════════════════════════
394:           VUE MOIS
395:          ══════════════════════════════════════════════════════════════════════ */}
396:       {viewMode === "month" && (
397:         <div className="flex-1 overflow-y-auto p-4 md:p-6">
398:           <div className="grid grid-cols-7 mb-2">
