400:               <div key={i} style={{ textAlign: "center", fontSize: 12, fontWeight: 800, color: "var(--c-text-2)", textTransform: "uppercase", letterSpacing: "0.07em", padding: "8px 0" }}>
401:                 {d}
402:               </div>
403:             ))}
404:           </div>
