427:                     border: isToday ? "2px solid rgba(29,158,117,0.45)" : isSel ? "2px solid rgba(91,158,245,0.45)" : "1px solid var(--c-border)",
428:                     background: isToday ? "rgba(29,158,117,0.08)" : isSel ? "rgba(91,158,245,0.08)" : cur ? "var(--c-surface)" : "transparent",
429:                     opacity: cur ? 1 : 0.35,
430:                   }}>
431:                   <div className="flex items-start justify-between mb-1">
432:                     <span style={{
433:                       fontSize: 12, fontWeight: 800, width: 24, height: 24, borderRadius: 10, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0,
434:                       background: isToday ? "linear-gradient(135deg, #1D9E75, #16826C)" : "transparent",
435:                       color: isToday ? "white" : (cur ? "var(--c-text-1)" : "var(--c-text-3)"),
436:                     }}>
437:                       {date.getDate()}
438:                     </span>
439:                     {ds.length > 0 && (
