441:                         {ds.slice(0, 3).map(s => (
442:                           <button key={s.id} type="button" aria-label={`Ouvrir ${s.title}`} style={{ width: 12, height: 12, borderRadius: "50%", background: cat(s.category).border, border: "none", padding: 0 }}
443:                             onClick={e => { e.stopPropagation(); setActiveSession(s); }} />
444:                         ))}
445:                       </div>
446:                     )}
447:                   </div>
448:                   <div className="hidden md:block space-y-0.5">
449:                     {ds.slice(0, 3).map(s => <SessionCard key={s.id} session={s} athleteId={athlete.id} compact onOpen={setActiveSession} onStatusChange={onStatusChange} />)}
450:                     {ds.length > 3 && (
451:                       <p style={{ fontSize: 12, fontWeight: 700, color: "var(--c-text-2)", padding: "4px" }}>+{ds.length - 3}</p>
452:                     )}
453:                   </div>
454:                 </div>
455:               );
456:             })}
457:           </div>
458: 
459:           {selectedDate && (() => {
460:             const key = toLocalDateStr(selectedDate);
461:             const ds  = (sessionsByDate[key] ?? []).sort((a, b) => (a.time ?? "").localeCompare(b.time ?? ""));
462:             if (!ds.length) return null;
463:             const isPast = toLocalDateStr(selectedDate) < toLocalDateStr(today);
464:             return (
465:               <div className="mt-5 space-y-2">
466:                 <p style={{ fontSize: 12, fontWeight: 700, color: "var(--c-text-2)", marginBottom: 10, display: "flex", alignItems: "center", gap: 8 }}>
467:                   <span style={{ width: 16, height: 16, borderRadius: 5, background: "#1D9E75", display: "flex", alignItems: "center", justifyContent: "center" }}>
468:                     <CalendarDays size={9} color="white" />
469:                   </span>
470:                   {selectedDate.toLocaleDateString("fr-BE", { weekday: "long", day: "numeric", month: "long" })}
471:                 </p>
472:                 {ds.map(s => <SessionCard key={s.id} session={s} athleteId={athlete.id} isPast={isPast} onOpen={setActiveSession} onStatusChange={onStatusChange} />)}
473:               </div>
474:             );
475:           })()}
476:         </div>
477:       )}
478: 
479:       {/* ══════════════════════════════════════════════════════════════════════
480:           VUE SEMAINE
481:          ══════════════════════════════════════════════════════════════════════ */}
482:       {viewMode === "week" && (
483:         <div className="flex-1 overflow-y-auto flex flex-col">
484:           <div style={{ display: "flex", overflowX: "auto", gap: 6, padding: "12px", background: "var(--c-surface)", borderBottom: "1px solid var(--c-border)", flexShrink: 0, scrollbarWidth: "none" }}>
485:             {weekDays.map((date, i) => {
486:               const isToday = isSameDay(date, today);
487:               const isSel   = isSameDay(date, selectedDate ?? today);
488:               const hasSess = (sessionsByDate[toLocalDateStr(date)] ?? []).length > 0;
489:               return (
490:                 <button key={i} onClick={() => setSelectedDate(date)}
491:                   className="tap-feedback"
492:                   style={{
493:                     flexShrink: 0, display: "flex", flexDirection: "column", alignItems: "center", gap: 2, width: 44, padding: "10px 0", borderRadius: 16, border: "none", cursor: "pointer",
494:                     background: isToday ? "linear-gradient(135deg, #1D9E75, #16826C)" : isSel ? "var(--c-surface-3)" : "transparent",
495:                   }}>
496:                   <span style={{ fontSize: 12, fontWeight: 800, textTransform: "uppercase", letterSpacing: "0.05em", color: (isToday || isSel) ? "rgba(255,255,255,0.82)" : "var(--c-text-2)" }}>
497:                     {["L", "M", "M", "J", "V", "S", "D"][i]}
498:                   </span>
499:                   <span style={{ fontSize: 18, fontWeight: 800, lineHeight: 1.2, color: (isToday || isSel) ? "white" : "var(--c-text-1)" }}>
500:                     {date.getDate()}
501:                   </span>
502:                   <div style={{ width: 6, height: 6, borderRadius: "50%", background: hasSess ? ((isToday || isSel) ? "rgba(255,255,255,0.6)" : "#1D9E75") : "transparent" }} />
503:                 </button>
504:               );
505:             })}
506:           </div>
507: 
508:           <div className="flex-1 overflow-y-auto p-4 md:p-6 space-y-3">
509:             {(() => {
510:               const key     = toLocalDateStr(selectedDate ?? today);
511:               const ds      = (sessionsByDate[key] ?? []).sort((a, b) => (a.time ?? "").localeCompare(b.time ?? ""));
512:               const dateObj = selectedDate ?? today;
513:               const isPast  = toLocalDateStr(dateObj) < toLocalDateStr(today);
514: 
515:               if (ds.length === 0) return (
516:                 <div className="flex flex-col items-center justify-center py-16 gap-3">
517:                   <div style={{ width: 56, height: 56, borderRadius: 20, background: "var(--c-surface-2)", display: "flex", alignItems: "center", justifyContent: "center" }}>
518:                     <CalendarDays size={24} color="var(--c-text-3)" strokeWidth={1.5} />
519:                   </div>
520:                   <p style={{ fontSize: 13, fontWeight: 700, color: "var(--c-text-3)" }}>Repos ce jour</p>
521:                   <button type="button" onClick={() => setShowCreate(true)} style={{ minHeight: 44, padding: "0 12px", fontSize: 13, fontWeight: 700, color: "var(--tone-success)", background: "none", border: "none", cursor: "pointer" }}>
522:                     + Planifier une séance
523:                   </button>
524:                 </div>
525:               );
526: 
527:               return ds.map(s => <SessionCard key={s.id} session={s} athleteId={athlete.id} isPast={isPast} onOpen={setActiveSession} onStatusChange={onStatusChange} />);
528:             })()}
529:           </div>
530:         </div>
531:       )}
532: 
533:       {/* ── MODALS ───────────────────────────────────────────────────────────── */}
534:       {liveActive && (
535:         <SessionDetailModal
536:           session={liveActive}
537:           athlete={athlete}
538:           allAthletes={allAthletes}
539:           onClose={() => setActiveSession(null)}
540:           onSetStatus={onStatusChange}
541:           onSetRpe={onRpeChange}
542:           onSetFeeling={onFeelingChange}
543:           onSetComment={onCommentChange}
544:           onSetRsvp={onRsvpChange}
545:         />
546:       )}
547:       {showCreate && (
548:         <CreateSessionModal
549:           athlete={athlete}
550:           allAthletes={allAthletes}
551:           clubId={clubId}
552:           createdBy={createdBy}
553:           coachUserId={coachUserId}
554:           onClose={() => setShowCreate(false)}
555:           onCreated={onRefresh}
556:         />
557:       )}
558:     </div>
559:   );
