  2: // AthleteOS — src/modules/AddSessionModal.jsx
  3: // Modal création/édition d'une séance (côté coach) — extraite de
  4: // Planning.jsx.
  5: // ============================================================
  6: 
  7: import { memo, useState, useCallback } from "react";
  8: import { X, Plus, CheckCircle } from "lucide-react";
  9: import { useAuth }   from "../hooks/useAuth";
 10: import { CATEGORIES, SESSION_COLORS, EMPTY_FORM, dateToISOWeek, dateToDayName, toLocalDateStr } from "./planningUtils";
 11: import TrainingFocusField from "../components/session/TrainingFocusField";
 12: import { getDefaultTrainingFocus, isTrainingFocusCompatible } from "../domain/trainingFocus";
 13: import { useAccessibleDialog } from "../hooks/useAccessibleDialog";
 14: import { SESSION_ATTACHMENT_ACCEPT, uploadSessionAttachment, validateSessionAttachment } from "../utils/storage";
 15: 
 16: const AddSessionModal = memo(({ athletes, initialData, onClose, onAdd }) => {
 17:   const { clubId } = useAuth();
 18:   const isEdit = !!initialData;
 19:   const today  = toLocalDateStr(new Date());
 20:   const [form, setForm]             = useState(() => {
 21:     const base = initialData ?? { ...EMPTY_FORM, sessionDate: today };
 22:     return {
 23:       ...base,
 24:       trainingFocus: isTrainingFocusCompatible(base.trainingFocus, base.category)
 25:         ? base.trainingFocus
 26:         : getDefaultTrainingFocus(base.category),
 27:     };
 28:   });
 29:   const [saving, setSaving]         = useState(false);
 30:   const [pdfFile, setPdfFile]       = useState(null);
 31:   const [pdfError, setPdfError]     = useState(null);
 32:   const [uploadingPdf, setUploadingPdf] = useState(false);
 33:   const { dialogRef, titleId } = useAccessibleDialog({ onClose, closeDisabled: saving });
 34: 
 35:   const set = useCallback((key, val) => setForm(f => ({ ...f, [key]: val })), []);
 36:   const pickPdf = useCallback(async file => {
 37:     if (!file) { setPdfFile(null); setPdfError(null); return; }
 38:     const validationError = await validateSessionAttachment(file);
 39:     if (validationError) { setPdfFile(null); setPdfError(validationError); return; }
 40:     setPdfError(null); setPdfFile(file);
 41:   }, []);
 42:   const toggleAthlete = useCallback(id => {
 43:     setForm(f => ({
 44:       ...f,
 45:       athleteIds: f.athleteIds.includes(id)
 46:         ? f.athleteIds.filter(x => x !== id)
 47:         : [...f.athleteIds, id],
 48:     }));
 49:   }, []);
 50: 
 51:   const handleSubmit = async () => {
 52:     if (!form.title.trim() || form.athleteIds.length === 0) return;
 53:     setSaving(true);
 54:     try {
 55:       let pdfUrl = form.pdfUrl ?? null;
 56:       if (pdfFile) {
 57:         setUploadingPdf(true);
 58:         // Préfixé par club_id pour les policies RLS. Le chemin privé reste
 59:         // stocké dans la colonne historique pdf_url, quel que soit le format.
 60:         pdfUrl = await uploadSessionAttachment(clubId, pdfFile);
 61:         setUploadingPdf(false);
 62:       }
 63:       const chosenDate = form.sessionDate || today;
 64:       await onAdd({
 65:         ...form,
 66:         week:        dateToISOWeek(chosenDate),
 67:         day:         dateToDayName(chosenDate),
 68:         type:        CATEGORIES.find(c => c.id === form.category)?.label ?? form.category,
 69:         pdfUrl,
 70:         sessionDate: chosenDate,
 71:       });
 72:       onClose();
 73:     } catch (err) {
 74:       console.error("Erreur ajout séance :", err);
 75:       setSaving(false);
 76:       setUploadingPdf(false);
 77:     }
 78:   };
 79: 
 80:   const selCat = SESSION_COLORS[form.category] ?? SESSION_COLORS.technique;
 81:   const labelCls = "block text-[12px] font-bold uppercase tracking-wide mb-1.5";
 82:   const labelStyle = { color: "var(--c-text-3)" };
 83: 
 84:   return (
 85:     <div
 86:       className="fixed inset-0 z-50 flex items-end sm:items-center justify-center sm:p-4 modal-backdrop"
 87:       onClick={e => e.target === e.currentTarget && !saving && onClose()}
 88:     >
 89:       <div ref={dialogRef} role="dialog" aria-modal="true" aria-labelledby={titleId} tabIndex={-1}
 90:         className="rounded-t-3xl sm:rounded-3xl shadow-2xl w-full sm:max-w-lg max-h-[95vh] sm:max-h-[90vh] flex flex-col overflow-hidden modal-content"
 91:         style={{ background: "var(--c-surface)" }}>
 92: 
 93:         <div className="flex justify-center pt-3 pb-1 sm:hidden flex-shrink-0">
 94:           <div className="w-10 h-1 rounded-full" style={{ background: "var(--c-border-strong)" }} />
 95:         </div>
 96: 
 97:         <div
 98:           className="px-6 py-5 flex items-center justify-between flex-shrink-0 transition-colors"
 99:           style={{ background: `${selCat.border}14`, borderBottom: `1px solid ${selCat.border}40` }}
100:         >
101:           <div>
102:             <h2 id={titleId} className="text-[17px] font-bold" style={{ color: selCat.text }}>
103:               {isEdit ? "Modifier la séance" : "Nouvelle séance"}
104:             </h2>
105:             <p className="text-[13px] mt-0.5" style={{ color: "var(--c-text-2)" }}>
106:               {isEdit ? "Modifie les détails" : "Planifie un entraînement"}
107:             </p>
108:           </div>
109:           <button type="button" aria-label="Fermer" onClick={onClose} disabled={saving}
110:             className="p-2 rounded-xl disabled:opacity-40 transition-colors">
111:             <X size={18} style={{ color: selCat.text }} />
112:           </button>
113:         </div>
114: 
115:         <div className="flex-1 overflow-y-auto px-6 py-5 space-y-4">
116: 
117:           <div>
118:             <label className={labelCls} style={labelStyle}>Titre *</label>
119:             <input className="input-premium" placeholder="Ex: Sprint — sorties de blocs"
120:               value={form.title} onChange={e => set("title", e.target.value)} />
121:           </div>
122: 
123:           <div>
124:             <label className={labelCls} style={labelStyle}>Catégorie</label>
125:             <div className="flex flex-wrap gap-1.5">
126:               {CATEGORIES.map(cat => {
127:                 const cc  = SESSION_COLORS[cat.id];
128:                 const sel = form.category === cat.id;
129:                 return (
130:                   <button key={cat.id} type="button" onClick={() => setForm(previous => ({ ...previous, category: cat.id, trainingFocus: getDefaultTrainingFocus(cat.id) }))}
131:                     className="px-3 py-2 rounded-xl text-[12px] font-semibold border-2 transition-all tap-feedback"
132:                     style={sel
133:                       ? { background: cc.border, color: "#0A150F", borderColor: cc.border }
134:                       : { background: `${cc.border}14`, color: cc.text, borderColor: `${cc.border}40` }
135:                     }>
136:                     {cat.label}
137:                   </button>
138:                 );
139:               })}
140:             </div>
141:           </div>
142: 
143:           <TrainingFocusField
144:             category={form.category}
145:             value={form.trainingFocus}
146:             onChange={value => set("trainingFocus", value)}
147:           />
148: 
149:           <div className="grid grid-cols-2 gap-3">
150:             <div>
151:               <label className={labelCls} style={labelStyle}>Date *</label>
152:               <input type="date" className="input-premium"
153:                 value={form.sessionDate} onChange={e => set("sessionDate", e.target.value)} />
154:             </div>
155:             <div>
156:               <label className={labelCls} style={labelStyle}>Heure</label>
157:               <input type="time" className="input-premium"
158:                 value={form.time} onChange={e => set("time", e.target.value)} />
159:             </div>
160:           </div>
161: 
162:           <div>
163:             <label className={labelCls} style={labelStyle}>Durée (minutes)</label>
164:             <input type="number" min="5" step="5" className="input-premium"
165:               value={form.durationMinutes} onChange={e => set("durationMinutes", Number(e.target.value))} />
166:           </div>
167: 
168:           <div>
169:             <label className={labelCls} style={labelStyle}>Description</label>
170:             <textarea className="input-premium resize-none" rows={3}
171:               placeholder="Volume, intensité, objectifs…"
172:               value={form.description} onChange={e => set("description", e.target.value)} />
173:           </div>
174: 
175:           <div>
176:             <label className={labelCls} style={labelStyle}>Consignes spécifiques</label>
177:             <textarea className="input-premium resize-none" rows={2}
178:               placeholder="Instructions particulières…"
179:               value={form.instructions} onChange={e => set("instructions", e.target.value)} />
180:           </div>
181: 
182:           <div>
183:             <label className={labelCls} style={labelStyle}>Pièce jointe (optionnelle)</label>
184:             {isEdit && form.pdfUrl && !pdfFile && (
185:               <p className="text-[12px] mb-1.5" style={{ color: "var(--tone-success)" }}>📎 Fichier déjà joint</p>
186:             )}
187:             <input type="file" accept={SESSION_ATTACHMENT_ACCEPT}
188:               onChange={e => pickPdf(e.target.files?.[0] ?? null)}
189:               className="w-full text-[12px] file:mr-3 file:py-2 file:px-3 file:rounded-xl file:border-0 file:text-[12px] file:font-semibold"
190:               style={{ color: "var(--c-text-3)" }} />
191:             {pdfFile && <p className="meta-text mt-1">📎 {pdfFile.name}</p>}
192:             {pdfError && <p className="text-[12px] mt-1" style={{ color: "var(--tone-danger)" }}>{pdfError}</p>}
193:           </div>
194: 
195:           <div>
196:             <label className={labelCls} style={labelStyle}>
197:               Athlètes * ({form.athleteIds.length} sélectionné{form.athleteIds.length > 1 ? "s" : ""})
198:             </label>
199:             {athletes.length === 0 ? (
200:               <p className="meta-text">Aucun athlète disponible</p>
201:             ) : (
202:               <div className="flex flex-wrap gap-2">
203:                 {athletes.map(a => {
204:                   const sel = form.athleteIds.includes(a.id);
205:                   return (
206:                     <button key={a.id} type="button" onClick={() => toggleAthlete(a.id)}
207:                       className="flex items-center gap-2 px-3 py-2 rounded-xl text-[12px] font-semibold border-2 transition-all tap-feedback"
208:                       style={sel
209:                         ? { background: "rgba(29,158,117,0.14)", borderColor: "#1D9E75", color: "var(--tone-success)" }
210:                         : { background: "var(--c-surface-2)", borderColor: "var(--c-border)", color: "var(--c-text-3)" }}>
