 22: import ErrorState                     from "../components/ui/ErrorState";
 23: import { EmptyState, PageHeader }      from "../components/ui/premium";
 24: import { getAthleteMetricsForWeek }   from "../utils/chargeCalculations";
 25: import { getISOWeek, initialsFromName } from "../utils/helpers.js";
 26: // Tâche 11 : moteur central de comparaison de performances (parsePerf,
 27: // getDiscHib, pctOfReference, compareValues) — ce fichier avait sa PROPRE
 28: // copie de parsePerf() qui devinait le sens ("higherIsBetter") depuis le
 29: // FORMAT de la chaîne plutôt que depuis la discipline. Un lancer de poids
 30: // saisi "14.20" (sans "m") était pris pour un chrono. Supprimée, remplacée
 31: // par athlete/shared.js — seule source de vérité, partagée avec le côté
 32: // athlète, pour que classements et records concordent entre coach et
 33: // athlète (DoD tâche 11).
 34: import { parsePerf, getDiscHib, pctOfReference, compareValues } from "../athlete/shared.js";
 35: 
 36: // ─── Constantes ───────────────────────────────────────────────────────────────
 37: 
 38: const ATHLETE_COLORS = [
 39:   "#1D9E75", "#378ADD", "#A855F7", "#EF9F27",
 40:   "#E24B4A", "#14B8A6", "#F97316", "#EC4899",
 41:   "#0EA5E9", "#84CC16",
 42: ];
 43: 
 44: // ─── Helpers ──────────────────────────────────────────────────────────────────
 45: 
 46: function getAllDisciplines(athletes) {
 47:   const set = new Set();
 48:   athletes.forEach((a) => { Object.keys(a.records ?? {}).forEach((d) => set.add(d)); });
 49:   return [...set].sort();
 50: }
 51: 
 52: function rankAthletes(athletes, discipline) {
 53:   const withRecord = athletes
 54:     .filter((a) => a.records?.[discipline])
 55:     .map((a) => {
 56:       const rec = a.records[discipline];
 57:       const sbP = parsePerf(rec.sb);
 58:       const prP = parsePerf(rec.pr);
 59:       const pct = pctOfReference(sbP.value, prP.value, discipline);
 60:       const idx = athletes.findIndex((x) => x.id === a.id);
 61:       return { athlete: a, rec, sbParsed: sbP, pct, colorIdx: idx % ATHLETE_COLORS.length };
 62:     })
 63:     .filter((e) => e.sbParsed.value !== null);
 64:   return withRecord.sort((a, b) => compareValues(a.sbParsed.value, b.sbParsed.value, discipline));
 65: }
 66: 
 67: function pctColor(pct) {
 68:   if (pct === null) return "var(--c-text-3)";
 69:   if (pct >= 97)   return "#1D9E75";
 70:   if (pct >= 90)   return "#EF9F27";
 71:   return "#E24B4A";
 72: }
 73: 
 74: function generateDisciplineAnalysis(ranked, discipline) {
 75:   if (ranked.length === 0) return [`Aucun athlète n'a de record enregistré pour l'épreuve "${discipline}".`];
 76:   const lines  = [];
 77:   const leader = ranked[0];
 78:   lines.push(`🥇 Leader sur ${discipline} : ${leader.athlete.name} avec un SB à ${leader.rec.sb}${leader.pct !== null ? ` (${leader.pct}% de son PR).` : "."}`);
 79:   const bestPct = [...ranked].filter((r) => r.pct !== null).sort((a, b) => b.pct - a.pct)[0];
 80:   if (bestPct && bestPct.athlete.id !== leader.athlete.id)
 81:     lines.push(`📈 ${bestPct.athlete.name} est l'athlète le plus proche de son record personnel (${bestPct.pct}% du PR).`);
 82:   const inForm = ranked.filter((r) => r.pct !== null && r.pct >= 95);
 83:   if (inForm.length > 1)
 84:     lines.push(`✅ ${inForm.length} athlètes dépassent 95% de leur PR cette saison sur ${discipline} : ` + inForm.map((r) => r.athlete.name.split(" ")[0]).join(", ") + ".");
 85:   const under = ranked.filter((r) => r.pct !== null && r.pct < 85);
 86:   if (under.length > 0)
 87:     lines.push(`⚠️ ${under.map((r) => r.athlete.name.split(" ")[0]).join(", ")} ${under.length > 1 ? "sont" : "est"} en dessous de 85% du PR. Un travail spécifique pourrait être bénéfique.`);
 88:   if (ranked.length === 1)
 89:     lines.push(`ℹ️ Un seul athlète du groupe pratique cette épreuve. Pas de comparaison possible.`);
 90:   return lines;
 91: }
 92: 
 93: // ─── Sous-composants ──────────────────────────────────────────────────────────
 94: 
 95: const ScatterTooltip = ({ active, payload, currentWeek }) => {
 96:   if (!active || !payload?.length) return null;
 97:   const d = payload[0]?.payload;
 98:   if (!d) return null;
 99:   return (
100:     <div className="rounded-xl shadow-lg px-3 py-3 text-[12px] min-w-[170px]" style={{ background: "var(--c-surface-2)", border: "1px solid var(--c-border-strong)" }}>
101:       <div className="flex items-center gap-2 mb-2">
102:         <div className="w-7 h-7 rounded-full flex items-center justify-center text-white text-[12px] font-semibold" style={{ background: d.color }}>{d.avatar}</div>
103:         <span className="font-semibold" style={{ color: "var(--c-text-1)" }}>{d.name}</span>
104:       </div>
105:       <div className="space-y-0.5" style={{ color: "var(--c-text-2)" }}>
106:         <p>Charge S{currentWeek} : <strong style={{ color: "var(--c-text-1)" }}>{d.x} u</strong></p>
107:         <p>% PR atteint : <strong style={{ color: pctColor(d.y) }}>{d.y}%</strong></p>
108:         <p>SB : <strong style={{ color: "var(--c-text-1)" }}>{d.sb}</strong></p>
109:         <p>PR : <strong style={{ color: "var(--tone-success)" }}>{d.pr}</strong></p>
110:       </div>
111:     </div>
112:   );
113: };
114: 
115: const LineTooltip = ({ active, payload, label }) => {
116:   if (!active || !payload?.length) return null;
117:   const d = payload[0].payload;
118:   return (
119:     <div className="rounded-xl shadow-lg px-3 py-3 text-[12px] min-w-[150px]" style={{ background: "var(--c-surface-2)", border: "1px solid var(--c-border-strong)" }}>
120:       <p className="font-semibold mb-1" style={{ color: "var(--c-text-1)" }}>{d.compName}</p>
121:       <p className="text-[12px] mb-2" style={{ color: "var(--c-text-2)" }}>{label}</p>
122:       <p className="text-[15px] font-semibold" style={{ color: "var(--color-success)" }}>{d.resultStr}</p>
123:       {d.context && <p className="text-[12px] mt-1 italic" style={{ color: "var(--c-text-2)" }}>"{d.context}"</p>}
124:     </div>
125:   );
126: };
