128: const Podium = memo(({ ranked }) => {
129:   const top3 = ranked.slice(0, 3);
130:   const podiumConfig = [
131:     { data: top3[1], height: 80,  rank: 2, medal: "🥈", bg: "rgba(148,163,184,0.16)", border: "#94A3B8" },
132:     { data: top3[0], height: 110, rank: 1, medal: "🥇", bg: "rgba(239,159,39,0.18)", border: "#EF9F27" },
133:     { data: top3[2], height: 60,  rank: 3, medal: "🥉", bg: "rgba(249,115,22,0.16)", border: "#F97316" },
