135:   if (ranked.length === 0) return null;
136:   return (
137:     <div className="flex items-end justify-center gap-1 sm:gap-3 pb-4">
138:       {podiumConfig.map(({ data, height, medal, bg, border }) => (
139:         <div key={data.athlete.id} className="flex flex-1 max-w-[120px] min-w-0 flex-col items-center gap-2">
