141:             <div className="w-12 h-12 rounded-2xl flex items-center justify-center text-white text-[13px] font-bold mx-auto mb-1.5 shadow-sm" style={{ background: ATHLETE_COLORS[data.colorIdx] }}>
142:               {data.athlete.avatar}
143:             </div>
144:             <p className="text-[12px] font-bold leading-tight" style={{ color: "var(--c-text-1)" }}>{data.athlete.name.split(" ")[0]}</p>
145:             <p className="text-[12px] font-semibold mt-0.5" style={{ color: "var(--c-text-2)" }}>{data.rec.sb}</p>
146:             {data.pct !== null && <p className="text-[12px] font-semibold mt-0.5" style={{ color: pctColor(data.pct) }}>{data.pct}% PR</p>}
147:           </div>
148:           <div className="w-full rounded-t-xl flex items-start justify-center pt-3 border-t-4" style={{ height, background: bg, borderColor: border }}>
149:             <span className="text-2xl">{medal}</span>
150:           </div>
151:         </div>
152:       ))}
153:     </div>
154:   );
155: });
