157: // ─── Composant principal ──────────────────────────────────────────────────────
158: function Performances() {
159:   const { clubId } = useAuth();
160:   const CURRENT_WEEK = getISOWeek(new Date());
161: 
162:   const [athletes,       setAthletes]       = useState([]);
163:   const [weeklyCharge,   setWeeklyCharge]   = useState([]);
164:   const [historyResults, setHistoryResults] = useState([]);
165:   const [loading,        setLoading]        = useState(true);
166:   const [error,          setError]          = useState(null);
167:   const [viewMode,       setViewMode]       = useState("group");
168:   const [selectedDisc,   setSelectedDisc]   = useState(null);
169:   const [selectedAthleteId, setSelectedAthleteId] = useState(null);
170: 
171:   // ═══ Chargement ═══════════════════════════════════════════════════════════
172:   const fetchAll = useCallback(async () => {
173:     if (!clubId) return;
174:     try {
175:       setLoading(true);
176:       setError(null);
177: 
178:       const athletesRes = await supabase
179:         .from("athletes").select("id, name, main_discipline, profile_data").eq("club_id", clubId);
180:       if (athletesRes.error) throw athletesRes.error;
181: 
182:       const athleteIds = athletesRes.data.map((a) => a.id);
183: 
184:       const [recordsRes, historyRes] = await Promise.all([
185:         athleteIds.length ? supabase.from("records").select("*").in("athlete_id", athleteIds) : Promise.resolve({ data: [] }),
186:         athleteIds.length ? supabase.from("competition_results").select("*, competitions(name, date)").in("athlete_id", athleteIds) : Promise.resolve({ data: [] }),
187:       ]);
188:       if (recordsRes.error)  throw recordsRes.error;
189:       if (historyRes.error)  throw historyRes.error;
190: 
191:       // Charge hebdomadaire calculée côté serveur (vue weekly_charge, voir
192:       // migration 20260726120000) — plus de recalcul JS à partir des séances.
193:       let weeklyChargeComputed = [];
194:       if (athleteIds.length) {
195:         const chargeRes = await supabase.from("weekly_charge").select("*").in("athlete_id", athleteIds);
196:         if (!chargeRes.error) {
197:           weeklyChargeComputed = (chargeRes.data ?? []).map((c) => ({
198:             athleteId: c.athlete_id, week: c.week, isoYear: c.iso_year, rawLoad: c.raw_load,
199:             dailyLoads: c.daily_loads ?? [], knownDays: c.known_days ?? 0,
200:             unknownDays: c.unknown_days ?? 0, estimatedDays: c.estimated_days ?? 0,
201:           }));
202:         }
203:       }
204: 
205:       const assembledAthletes = athletesRes.data.map((a) => {
206:         const recs = {};
207:         (recordsRes.data ?? []).filter((r) => r.athlete_id === a.id).forEach((r) => {
208:           recs[r.discipline] = { sb: r.sb, pr: r.pr, prDate: r.pr_date };
209:         });
210:         return { id: a.id, name: a.name, mainDiscipline: a.main_discipline, avatar: a.profile_data?.avatar ?? initialsFromName(a.name), records: recs };
211:       });
212: 
213:       setAthletes(assembledAthletes);
214:       setWeeklyCharge(weeklyChargeComputed);
215:       setHistoryResults(historyRes.data ?? []);
216: 
217:       const disciplines = getAllDisciplines(assembledAthletes);
218:       setSelectedDisc((prev) => prev ?? disciplines[0] ?? null);
219:       setSelectedAthleteId(athleteIds[0] ?? null);
220:     } catch (err) {
221:       console.error("Performances — chargement :", err);
222:       setError(err.message ?? "Erreur inconnue");
223:     } finally {
224:       setLoading(false);
225:     }
226:   }, [clubId]);
227: 
228:   useEffect(() => { fetchAll(); }, [fetchAll]);
229: 
230:   // ═══ Calculs dérivés ══════════════════════════════════════════════════════
231:   const allDisciplines = useMemo(() => getAllDisciplines(athletes), [athletes]);
232:   const ranked         = useMemo(() => selectedDisc ? rankAthletes(athletes, selectedDisc) : [], [athletes, selectedDisc]);
233:   const analysis       = useMemo(() => selectedDisc ? generateDisciplineAnalysis(ranked, selectedDisc) : [], [ranked, selectedDisc]);
234:   const avgPct         = useMemo(() => {
235:     const valids = ranked.filter((r) => r.pct !== null);
236:     return valids.length ? Math.round(valids.reduce((s, r) => s + r.pct, 0) / valids.length) : null;
237:   }, [ranked]);
238: 
239:   const scatterData = useMemo(() =>
240:     ranked.filter((r) => r.pct !== null).map((r) => {
241:       const metrics = getAthleteMetricsForWeek(r.athlete.id, weeklyCharge, CURRENT_WEEK);
242:       return { x: metrics.rawLoad ?? metrics.acute ?? 0, y: r.pct, name: r.athlete.name, avatar: r.athlete.avatar, color: ATHLETE_COLORS[r.colorIdx], sb: r.rec.sb, pr: r.rec.pr, id: r.athlete.id };
243:     }),
244:   [ranked, weeklyCharge, CURRENT_WEEK]);
245: 
246:   const evolutionData = useMemo(() => {
247:     if (!selectedAthleteId || !selectedDisc) return [];
248:     return historyResults
249:       .filter((r) => r.athlete_id === selectedAthleteId && r.event === selectedDisc && r.competitions?.date)
250:       .sort((a, b) => new Date(a.competitions.date) - new Date(b.competitions.date))
251:       .map((r) => {
252:         const parsed = parsePerf(r.result);
253:         return { date: new Date(r.competitions.date).toLocaleDateString("fr-FR", { day: "2-digit", month: "short" }), fullDate: r.competitions.date, compName: r.competitions.name, resultStr: r.result, resultNum: parsed.value, context: r.context };
254:       })
255:       .filter((d) => d.resultNum !== null);
256:   }, [historyResults, selectedAthleteId, selectedDisc]);
257: 
258:   // Tâche 11 : le sens (chrono ou pas) vient de la discipline sélectionnée,
259:   // pas d'un résultat individuel deviné depuis son format — un seul résultat
260:   // mal formaté ne doit pas inverser l'axe du graphique pour tout le monde.
261:   const isTimeEvent = selectedDisc ? !getDiscHib(selectedDisc) : false;
262:   const bestEvolution = useMemo(() => {
263:     if (!selectedDisc || evolutionData.length === 0) return null;
264:     return evolutionData.reduce((best, result) => (
265:       compareValues(result.resultNum, best.resultNum, selectedDisc) < 0 ? result : best
266:     ));
267:   }, [evolutionData, selectedDisc]);
268: 
269:   // ═══ Render ═══════════════════════════════════════════════════════════════
270:   if (loading) return <LoadingState message="Chargement des performances…" />;
271:   if (error)   return <ErrorState  message={error} onRetry={fetchAll} />;
272: 
273:   if (allDisciplines.length === 0) {
274:     return (
275:       <div className="page-container py-4 md:py-6 max-w-7xl mx-auto space-y-5 animate-slide-up">
276:         <PageHeader
277:           eyebrow="ANALYSE DU GROUPE"
278:           title="Performances"
279:           description="Classements du groupe et progression individuelle."
280:         />
281:         <EmptyState
282:           icon={Trophy}
283:           title="Aucun record enregistré pour l’instant"
284:           description="Les classements et graphiques apparaîtront dès que les premiers records auront été ajoutés aux profils."
285:         />
286:       </div>
287:     );
288:   }
289: 
290:   return (
291:     <div className="page-container py-4 md:py-6 max-w-7xl mx-auto space-y-5 md:space-y-6 animate-slide-up">
292: 
293:       <PageHeader
294:         eyebrow="ANALYSE DU GROUPE"
295:         title="Performances"
296:         description={`${athletes.length} athlète${athletes.length !== 1 ? "s" : ""} · ${allDisciplines.length} épreuve${allDisciplines.length !== 1 ? "s" : ""} suivie${allDisciplines.length !== 1 ? "s" : ""}`}
297:       />
298: 
299:       {/* ── En-tête ──────────────────────────────────────────────────────── */}
300:       <div className="card p-2 flex flex-col md:flex-row md:items-center md:justify-between gap-2">
301:         <div className="grid grid-cols-2 gap-1 p-1 rounded-xl w-full md:w-auto" style={{ background: "var(--c-surface-2)" }} role="group" aria-label="Mode d'analyse">
302:           <button type="button" aria-pressed={viewMode === "group"} onClick={() => setViewMode("group")} className={`min-h-11 px-3 md:px-4 rounded-lg text-[13px] font-semibold transition-colors flex items-center justify-center gap-2 ${viewMode === "group" ? "bg-[rgba(29,158,117,0.15)] text-[var(--color-success)]" : "text-[var(--c-text-2)] hover:bg-[var(--c-surface-3)]"}`}>
303:             <Users size={16} /> Classement
304:           </button>
305:           <button type="button" aria-pressed={viewMode === "evolution"} onClick={() => setViewMode("evolution")} className={`min-h-11 px-3 md:px-4 rounded-lg text-[13px] font-semibold transition-colors flex items-center justify-center gap-2 ${viewMode === "evolution" ? "bg-[rgba(29,158,117,0.15)] text-[var(--color-success)]" : "text-[var(--c-text-2)] hover:bg-[var(--c-surface-3)]"}`}>
306:             <TrendingUp size={16} /> Évolution
307:           </button>
308:         </div>
309: 
310:         <div className="relative w-full md:w-[240px]">
311:           <label htmlFor="performance-discipline" className="sr-only">Épreuve analysée</label>
312:           <Trophy size={16} aria-hidden="true" className="absolute left-3 top-1/2 -translate-y-1/2 pointer-events-none" style={{ color: "var(--color-warning)" }} />
313:           <select id="performance-discipline" value={selectedDisc ?? ""} onChange={(event) => setSelectedDisc(event.target.value)} className="input-premium font-semibold" style={{ paddingLeft: 40 }}>
314:             {allDisciplines.map((discipline) => <option key={discipline} value={discipline}>{discipline}</option>)}
315:           </select>
316:         </div>
317:       </div>
318: 
319:       {/* ── Vue groupe ───────────────────────────────────────────────────── */}
320:       {viewMode === "group" && (
321:         <div className="space-y-6">
322:           <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
323:             {[
324:               { icon: Users, bg: "bg-[rgba(239,159,39,0.15)]", color: "#EF9F27", label: "Athlètes", value: ranked.length, sub: `pratiquent ${selectedDisc}` },
325:               { icon: TrendingUp, bg: "bg-[rgba(29,158,117,0.15)]", color: "#1D9E75", label: "Meilleur SB", value: ranked[0]?.rec.sb ?? "—", sub: ranked[0]?.athlete.name.split(" ")[0] ?? "—", valueColor: "#1D9E75" },
326:               { icon: Zap, bg: "bg-[rgba(55,138,221,0.15)]", color: "#378ADD", label: "% PR moyen groupe", value: avgPct !== null ? `${avgPct}%` : "—", sub: "de leurs records personnels", valueColor: pctColor(avgPct) },
327:             ].map((card) => (
328:               <div key={card.label} className="card p-4 flex items-center gap-3">
329:                 <div className={`w-10 h-10 rounded-xl ${card.bg} flex items-center justify-center flex-shrink-0`}>
330:                   <card.icon size={18} color={card.color} />
331:                 </div>
332:                 <div>
333:                   <p className="metric-label">{card.label}</p>
334:                   <p className="text-[22px] font-bold leading-tight" style={{ color: card.valueColor ?? "var(--c-text-1)" }}>{card.value}</p>
335:                   <p className="meta-text">{card.sub}</p>
336:                 </div>
337:               </div>
338:             ))}
339:           </div>
340: 
341:           {ranked.length === 0 ? (
342:             <div className="card p-16 text-center">
343:               <Trophy size={40} className="mx-auto mb-3" style={{ color: "var(--c-text-3)" }} />
344:               <p className="text-[15px] font-semibold" style={{ color: "var(--c-text-2)" }}>Aucun athlète n'a de record pour « {selectedDisc} »</p>
345:             </div>
346:           ) : (
347:             <>
348:               <div className="grid grid-cols-1 lg:grid-cols-5 gap-4">
349:                 <div className="lg:col-span-2 card p-5">
