 40: function MiniLoadSpark({ data }) {
 41:   if (data.length < 2) return <div style={{ width: 60, height: 24 }} />;
 42:   return (
 43:     <div aria-hidden="true" style={{ width: 60, height: 24 }}>
 44:       <ResponsiveContainer width="100%" height="100%">
