 55:   if (trend === "down") return <span style={{ display: "inline-flex", alignItems: "center", gap: 2, color: "var(--tone-danger)" }}><TrendingDown size={12} /> Baisse</span>;
 56:   return <span style={{ display: "inline-flex", alignItems: "center", gap: 4, color: "var(--c-text-2)" }}><Minus size={12} /> Stable</span>;
