220:                         </div>
221:                         {s.comment && (
222:                           <p className="text-[12px] text-[var(--c-text-2)] italic mt-1">« {s.comment} »</p>
223:                         )}
224:                       </div>
225:                     </div>
226:                   );
227:                 })}
228:               </div>
229:             )}
230:           </div>
231:         </div>
232:       </div>
233:     </div>
234:   );
235: }
236: 
237: // ─── Card athlète — vue Mois ───────────────────────────────────────────────
238: function AthleteMonthCard({ athlete, aggregate }) {
239:   const { totalLoad, sessionsTotal, doneTotal, categoriesWorked, trend, weeks } = aggregate;
240:   const sparkData = weeks.map(w => ({ load: w.stats.totalLoad }));
241: 
242:   return (
243:     <div className="card p-4">
244:       <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 12 }}>
245:         <div className="w-8 h-8 rounded-full flex items-center justify-center text-white text-[12px] font-semibold flex-shrink-0" style={{ background: "linear-gradient(135deg, #378ADD, #2563EB)" }}>
246:           {athlete.avatar}
247:         </div>
248:         <p className="text-[13px] font-semibold text-[var(--c-text-1)] flex-1 truncate">{athlete.name}</p>
249:         <MiniLoadSpark data={sparkData} />
250:       </div>
251:       <div style={{ display: "flex", alignItems: "baseline", gap: 6, marginBottom: 6 }}>
252:         <span style={{ fontSize: 20, fontWeight: 700, color: "var(--c-text-1)" }}>{totalLoad}</span>
253:         <span className="text-[12px] text-[var(--c-text-2)]">points d'effort sur {weeks.length} semaine{weeks.length !== 1 ? "s" : ""}</span>
254:       </div>
255:       <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 10 }}>
256:         <span className="text-[12px] text-[var(--c-text-2)]">{doneTotal}/{sessionsTotal} séances faites</span>
257:         <span className="text-[12px] font-semibold"><TrendArrow trend={trend} /></span>
258:       </div>
259:       {categoriesWorked.length > 0 && (
260:         <div style={{ display: "flex", flexWrap: "wrap", gap: 5 }}>
261:           {categoriesWorked.slice(0, 4).map(c => {
262:             const col = colorsFor(c.id);
263:             return (
264:               <span key={c.id} style={{ fontSize: 12, fontWeight: 600, padding: "3px 8px", borderRadius: 8, background: col.bg, color: col.text }}>
265:                 {c.label}
266:               </span>
267:             );
268:           })}
269:         </div>
270:       )}
271:     </div>
272:   );
273: }
