275: // ─── Composant principal ───────────────────────────────────────────────────
276: export default function Rapports() {
277:   const { clubId, profile } = useAuth();
278:   const now = useMemo(() => new Date(), []);
279:   const currentWeek = getISOWeek(now);
280:   const currentYear = getISOWeekYear(now);
281: 
282:   const [athletes,     setAthletes]     = useState([]);
283:   const [sessions,     setSessions]     = useState([]);
284:   const [weeklyCharge, setWeeklyCharge] = useState([]);
285:   const [wellnessRows, setWellnessRows] = useState([]);
286:   const [loading,      setLoading]      = useState(true);
287:   const [error,        setError]        = useState(null);
288: 
289:   const [viewMode,        setViewMode]        = useState("week"); // "week" | "month"
290:   const [selectedWeek,    setSelectedWeek]    = useState(null);
291:   const [selectedAthlete, setSelectedAthlete] = useState(null);
292: 
293:   const fetchAll = useCallback(async () => {
294:     if (!clubId) return;
295:     try {
296:       setLoading(true); setError(null);
297:       const athletesRes = await supabase.from("athletes").select("id, name, profile_data").eq("club_id", clubId);
298:       if (athletesRes.error) throw athletesRes.error;
299: 
300:       const mappedAthletes = athletesRes.data.map(a => ({
301:         id: a.id, name: a.name, avatar: a.profile_data?.avatar ?? initialsFromName(a.name),
302:       }));
303:       const athleteIds = mappedAthletes.map(a => a.id);
304: 
305:       // weekly_charge est une vue SANS RLS propre (cf. Dashboard.jsx/AthleteApp.jsx) —
306:       // on doit impérativement la scoper par athlete_id nous-mêmes, sinon on
307:       // récupère la charge de TOUS les clubs.
308:       const [sessionsRes, chargeRes, wellnessRes] = await Promise.all([
309:         supabase.from("sessions").select("*, session_athletes(*)").eq("club_id", clubId),
310:         athleteIds.length ? supabase.from("weekly_charge").select("*").in("athlete_id", athleteIds) : Promise.resolve({ data: [] }),
311:         supabase.from("athlete_wellness").select("*").eq("club_id", clubId),
312:       ]);
313:       if (sessionsRes.error) throw sessionsRes.error;
314:       if (chargeRes.error)   throw chargeRes.error;
315:       if (wellnessRes.error) throw wellnessRes.error;
316: 
317:       const mappedSessions = (sessionsRes.data ?? []).map(s => {
318:         const rows = s.session_athletes ?? [];
319:         return {
320:           id: s.id, week: s.week, day: s.day, sessionDate: s.session_date,
321:           category: s.category, trainingFocus: s.training_focus, title: s.title, durationMinutes: s.duration_minutes,
322:           athleteIds:  rows.map(v => v.athlete_id),
323:           validations: rows.map(v => ({ athleteId: v.athlete_id, status: v.status, feeling: v.feeling, rpe: v.rpe, comment: v.comment, actualDurationMinutes: v.actual_duration_minutes, durationSource: v.duration_source })),
324:         };
325:       });
326: 
327:       const mappedCharge = (chargeRes.data ?? [])
328:         .map(c => ({ athleteId: c.athlete_id, week: c.week, isoYear: c.iso_year, rawLoad: c.raw_load, dailyLoads: c.daily_loads ?? [], knownDays: c.known_days ?? 0, unknownDays: c.unknown_days ?? 0, estimatedDays: c.estimated_days ?? 0 }));
329: 
330:       const mappedWellness = (wellnessRes.data ?? []).map(w => ({
331:         athleteId: w.athlete_id, date: w.date, sleep: w.sleep, energy: w.energy,
332:         soreness: w.soreness, mood: w.mood, stress: w.stress,
333:       }));
334: 
335:       setAthletes(mappedAthletes);
336:       setSessions(mappedSessions);
337:       setWeeklyCharge(mappedCharge);
338:       setWellnessRows(mappedWellness);
339: 
340:       if (mappedAthletes.length > 0) {
341:         try {
342:           await checkWeeklyReports(clubId, mappedAthletes, currentWeek, profile?.id ?? null, currentYear);
343:         } catch (notificationError) {
344:           console.error("Rapports — notifications hebdomadaires :", notificationError);
345:         }
346:       }
347:     } catch (err) {
348:       setError(err.message ?? "Erreur inconnue");
349:     } finally { setLoading(false); }
350:   }, [clubId, currentWeek, currentYear, profile?.id]);
351: 
352:   useEffect(() => { fetchAll(); }, [fetchAll]);
353: 
354:   const weeks = useMemo(() => getAvailableWeeks(sessions), [sessions]);
355: 
356:   const weekReports = useMemo(() => {
357:     if (selectedWeek == null) return [];
358:     return athletes.map(athlete => ({
359:       athlete,
360:       report: buildWeeklyReport({ athleteId: athlete.id, week: selectedWeek.week, isoYear: selectedWeek.isoYear, sessions, weeklyCharge, wellnessRows }),
361:     })).sort((a, b) => b.report.stats.total - a.report.stats.total);
362:   }, [selectedWeek, athletes, sessions, weeklyCharge, wellnessRows]);
363: 
364:   const last4Weeks = useMemo(() => weeks.slice(0, 4), [weeks]);
365: 
366:   const monthAggregates = useMemo(() => {
367:     if (viewMode !== "month" || last4Weeks.length === 0) return [];
368:     return athletes.map(athlete => ({
369:       athlete,
370:       aggregate: buildMonthlyAggregate({ athleteId: athlete.id, weeks: last4Weeks, sessions, weeklyCharge, wellnessRows }),
371:     })).sort((a, b) => b.aggregate.totalLoad - a.aggregate.totalLoad);
372:   }, [viewMode, last4Weeks, athletes, sessions, weeklyCharge, wellnessRows]);
373: 
374:   const latestWeekOverview = useMemo(() => {
375:     const latestWeek = weeks[0];
376:     if (!latestWeek) return null;
377:     const reports = athletes.map(athlete => buildWeeklyReport({
378:       athleteId: athlete.id,
379:       week: latestWeek.week,
380:       isoYear: latestWeek.isoYear,
381:       sessions,
382:       weeklyCharge,
383:       wellnessRows,
384:     }));
385:     return {
386:       week: latestWeek.week,
387:       isoYear: latestWeek.isoYear,
388:       planned: reports.reduce((sum, report) => sum + report.stats.total, 0),
389:       done: reports.reduce((sum, report) => sum + report.stats.done, 0),
390:       totalLoad: reports.reduce((sum, report) => sum + report.stats.totalLoad, 0),
391:     };
392:   }, [weeks, athletes, sessions, weeklyCharge, wellnessRows]);
393: 
394:   if (loading) return <LoadingState message="Chargement des rapports…" />;
395:   if (error)   return <ErrorState  message={error} onRetry={fetchAll} />;
396: 
397:   const selectedWeekMeta = weeks.find(w => w.key === selectedWeek?.key);
398:   const selectedAthleteReport = selectedAthlete != null
399:     ? weekReports.find(r => r.athlete.id === selectedAthlete)
400:     : null;
401: 
402:   return (
403:     <div className="page-container py-4 md:py-6 space-y-5 md:space-y-6 max-w-5xl mx-auto animate-slide-up">
404: 
405:       <PageHeader
406:         eyebrow="SUIVI DU GROUPE"
407:         title="Rapports"
408:         description={`${athletes.length} athlète${athletes.length !== 1 ? "s" : ""} · ${weeks.length} semaine${weeks.length !== 1 ? "s" : ""} avec des séances`}
409:         actions={(
410:           <SegmentedTabs
411:             ariaLabel="Période des rapports"
412:             items={[{ id: "week", label: "Semaine" }, { id: "month", label: "Mois" }]}
413:             value={viewMode}
414:             onChange={(mode) => { setViewMode(mode); setSelectedWeek(null); setSelectedAthlete(null); }}
415:           />
416:         )}
417:       />
418: 
419:       {latestWeekOverview && (
420:         <div className="grid grid-cols-1 sm:grid-cols-3 gap-3 md:gap-4">
421:           {[
422:             { label: "Dernier rapport", value: `S${latestWeekOverview.week} · ${latestWeekOverview.isoYear}`, detail: "semaine la plus récente" },
423:             { label: "Séances réalisées", value: `${latestWeekOverview.done}/${latestWeekOverview.planned}`, detail: "cumul du groupe" },
424:             { label: "Charge cumulée", value: latestWeekOverview.totalLoad, detail: "unités arbitraires" },
425:           ].map(item => (
426:             <StatCard key={item.label} label={item.label} value={item.value} helper={item.detail} />
427:           ))}
428:         </div>
429:       )}
430: 
431:       {/* ── VUE SEMAINE ────────────────────────────────────────────────── */}
432:       {viewMode === "week" && selectedWeek == null && (
433:         weeks.length === 0 ? (
434:           <EmptyState
435:             icon={CalendarDays}
436:             title="Aucune séance planifiée"
437:             description="Les rapports apparaîtront automatiquement dès que des séances seront créées et attribuées."
438:           />
439:         ) : (
440:           <div className="space-y-2.5">
441:             {weeks.map(w => (
442:               <WeekCard key={w.key} week={w.week} dateRange={w.dateRange} sessionCount={w.sessionCount}
443:                 onClick={() => setSelectedWeek(w)} />
444:             ))}
445:           </div>
446:         )
447:       )}
448: 
449:       {viewMode === "week" && selectedWeek != null && (
450:         <div className="space-y-3">
451:           <button type="button" onClick={() => setSelectedWeek(null)} className="tap-feedback min-h-11 flex items-center gap-1.5 text-[13px] font-semibold text-[var(--color-success)]">
452:             <ChevronLeft size={15} /> Toutes les semaines
453:           </button>
454:           <div className="card" style={{ overflow: "hidden" }}>
455:             <div style={{ padding: "14px 16px", borderBottom: "1px solid var(--c-border)" }}>
456:               <p className="card-title">{formatWeekLabel(selectedWeek.week, selectedWeekMeta?.dateRange, selectedWeek.isoYear)}</p>
457:             </div>
458:             {weekReports.map(({ athlete, report }) => (
459:               <AthleteWeekRow key={athlete.id} athlete={athlete} report={report} onClick={() => setSelectedAthlete(athlete.id)} />
460:             ))}
461:           </div>
462:         </div>
463:       )}
464: 
465:       {/* ── VUE MOIS ───────────────────────────────────────────────────── */}
466:       {viewMode === "month" && (
467:         last4Weeks.length === 0 ? (
468:           <div className="card p-12 text-center">
469:             <p className="text-[15px] font-semibold text-[var(--c-text-2)]">Pas encore assez de données pour une vue mensuelle</p>
470:           </div>
471:         ) : (
472:           <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
473:             {monthAggregates.map(({ athlete, aggregate }) => (
474:               <AthleteMonthCard key={athlete.id} athlete={athlete} aggregate={aggregate} />
475:             ))}
476:           </div>
477:         )
478:       )}
479: 
480:       {/* ── DÉTAIL ATHLÈTE ─────────────────────────────────────────────── */}
481:       {selectedAthleteReport && (
482:         <AthleteWeekDetail athlete={selectedAthleteReport.athlete} report={selectedAthleteReport.report}
483:           onClose={() => setSelectedAthlete(null)} />
484:       )}
485:     </div>
486:   );
487: }  1: // ============================================================
  2: // AthleteOS — src/utils/coachFeed.js
  3: //
  4: // "Fil du coach" — transforme les métriques descriptives déjà calculées
  5: // (charge, ressenti, blessures, absences, compétitions à venir) en
  6: // phrases priorisées et actionnables, plutôt que de laisser le coach
  7: // relire des chiffres bruts et en déduire lui-même ce qui compte cette
  8: // semaine. Aucun nouveau calcul de charge : ce fichier lit uniquement
  9: // getAthleteMetricsForWeek() (chargeCalculations.js) et applique des
 10: // règles de priorisation.
 11: //
 12: // Pur JS sans dépendance React — même esprit que weeklyReports.js —
 13: // donc facilement lisible/testable indépendamment du rendu.
 14: // ============================================================
 15: 
 16: import { getAthleteMetricsForWeek } from "./chargeCalculations";
 17: import { getAthleteAxisProfile, LOAD_AXES } from "./loadAxes";
 18: import { getISOWeekYear, matchesISOWeek } from "./helpers";
 19: 
 20: // Un item "critical" passe toujours avant un "positive", peu importe
 21: // l'ordre dans lequel les règles ci-dessous ont été évaluées.
 22: const PRIORITY = { critical: 0, warning: 1, info: 2, positive: 3 };
 23: 
 24: function firstName(name) {
 25:   return name?.split(" ")[0] ?? "Athlète";
 26: }
 27: 
 28: function localDateKey(value) {
 29:   if (!value) return null;
 30:   if (value instanceof Date && !Number.isNaN(value.getTime())) {
 31:     return `${value.getFullYear()}-${String(value.getMonth() + 1).padStart(2, "0")}-${String(value.getDate()).padStart(2, "0")}`;
 32:   }
 33:   const text = String(value);
 34:   if (/^\d{4}-\d{2}-\d{2}/u.test(text)) return text.slice(0, 10);
 35:   const parsed = new Date(value);
 36:   return Number.isNaN(parsed.getTime()) ? null : localDateKey(parsed);
 37: }
 38: 
 39: export function buildCoachFeed({
 40:   athletes = [], weeklyCharge = [], sessions = [], injuries = [], competitions = [], alerts = [],
 41:   currentWeek, now = new Date(), currentYear = getISOWeekYear(now),
 42: }) {
 43:   const items = [];
 44:   const todayKey = localDateKey(now);
 45:   const inSevenDays = new Date(now);
 46:   inSevenDays.setDate(inSevenDays.getDate() + 7);
 47:   const inSevenDaysKey = localDateKey(inSevenDays);
 48:   const weekSessions = sessions.filter(session => matchesISOWeek(session, currentWeek, currentYear));
 49: 
 50:   const unreadAlerts = alerts.filter(alert => !alert.is_read);
 51:   if (unreadAlerts.length > 0) {
 52:     const important = unreadAlerts.filter(alert => ["high", "critical", "danger"].includes(String(alert.severity).toLowerCase())).length;
 53:     items.push({
 54:       id: "unread-alerts", priority: important > 0 ? "critical" : "warning", order: 0,
 55:       icon: "alert", color: important > 0 ? "#E24B4A" : "#EF9F27", route: "alerts", label: "Alertes à lire",
 56:       sentence: `${unreadAlerts.length} alerte${unreadAlerts.length > 1 ? "s" : ""} attend${unreadAlerts.length > 1 ? "ent" : ""} ton attention${important > 0 ? `, dont ${important} prioritaire${important > 1 ? "s" : ""}` : ""}.`,
 57:     });
 58:   }
 59: 
 60:   const upcomingSessions = weekSessions.filter(session => {
 61:     const dateKey = localDateKey(session.sessionDate);
 62:     return dateKey && dateKey >= todayKey && dateKey <= inSevenDaysKey;
 63:   });
 64:   const missingResponses = upcomingSessions.reduce((count, session) => (
 65:     count + (session.validations ?? []).filter(validation => !validation.rsvpStatus).length
 66:   ), 0);
 67:   if (missingResponses > 0) {
 68:     items.push({
 69:       id: "missing-rsvp", priority: "warning", order: 10, icon: "users", color: "#EF9F27", route: "planning", label: "Réponses manquantes",
 70:       sentence: `${missingResponses} réponse${missingResponses > 1 ? "s" : ""} de présence manque${missingResponses > 1 ? "nt" : ""} encore pour les prochaines séances.`,
 71:     });
 72:   }
 73: 
 74:   const pendingAthleteSessions = sessions.filter(session => session.createdByAthlete);
 75:   if (pendingAthleteSessions.length > 0) {
 76:     items.push({
 77:       id: "athlete-session-validations", priority: "info", order: 40, icon: "check", color: "var(--tone-info)", route: "planning", label: "Validations",
 78:       sentence: `${pendingAthleteSessions.length} séance${pendingAthleteSessions.length > 1 ? "s" : ""} ajoutée${pendingAthleteSessions.length > 1 ? "s" : ""} par un athlète ${pendingAthleteSessions.length > 1 ? "sont" : "est"} à vérifier.`,
 79:     });
 80:   }
 81: 
 82:   const nextCompetition = [...competitions]
 83:     .filter(competition => localDateKey(competition.date) >= todayKey)
 84:     .sort((a, b) => String(a.date).localeCompare(String(b.date)))[0];
 85:   if (nextCompetition) {
 86:     const competitionDate = new Date(`${localDateKey(nextCompetition.date)}T12:00:00`);
 87:     const days = Math.max(0, Math.round((competitionDate - new Date(`${todayKey}T12:00:00`)) / 86_400_000));
 88:     if (days <= 14) {
 89:       items.push({
 90:         id: `competition-${nextCompetition.id}`, priority: "info", order: 50, icon: "trophy", color: "#A78BFA", route: "competitions", label: "Compétition proche",
 91:         sentence: `${nextCompetition.name} arrive ${days === 0 ? "aujourd'hui" : `dans ${days} jour${days > 1 ? "s" : ""}`}. Vérifie les athlètes et les épreuves prévues.`,
 92:       });
 93:     }
 94:   }
 95: 
 96:   athletes.forEach(athlete => {
 97:     const hasCharge = weeklyCharge.some(row =>
 98:       row.athleteId === athlete.id && matchesISOWeek(row, currentWeek, currentYear)
 99:     );
100:     const name = firstName(athlete.name);
101: 
102:     if (hasCharge) {
103:       const metrics = getAthleteMetricsForWeek(athlete.id, weeklyCharge, currentWeek);
104: 
105:       if (metrics.variationPercent != null && Math.abs(metrics.variationPercent) >= 20) {
106:         const direction = metrics.variationPercent > 0 ? "plus élevée" : "plus basse";
107:         items.push({
108:           id: `load-variation-${athlete.id}`, priority: "info", order: 70, icon: "activity", color: "#378ADD", route: "charge", label: "Charge inhabituelle",
109:           sentence: `La charge de ${name} est ${direction} que d'habitude (${Math.abs(metrics.variationPercent)} % d'écart). Ouvre le détail pour voir quelles séances expliquent ce changement.`,
110:         });
111:       }
112: 
113:       if (metrics.wellnessScore != null && metrics.wellnessScore < 25) {
114:         items.push({
115:           id: `fatigue-${athlete.id}`, priority: "warning", order: 60, icon: "zap", color: "#EF9F27", route: "athletes", label: "Ressenti à discuter",
116:           sentence: `${name} a donné plusieurs réponses basses dans son état du jour — prends contact pour comprendre ce qui pèse aujourd'hui.`,
117:         });
118:       }
119: 
120:       if (metrics.wellnessScore >= 85) {
121:         items.push({
122:           id: `top-${athlete.id}`, priority: "positive", order: 90, icon: "trending", color: "#1D9E75", route: "athletes", label: "Retour positif",
123:           sentence: `${name} décrit un bon ressenti aujourd'hui. Le détail des cinq réponses reste disponible.`,
124:         });
125:       }
126:     }
127: 
128:     // Axe de charge inhabituel : un seul signal par athlète, sur l'axe le
129:     // plus marqué (évite de noyer le coach si plusieurs axes sortent en
130:     // même temps). Volontairement pas de chiffre — juste "quel axe" et
131:     // "ce que ça veut dire", cf. AxisRadarCard.
132:     const axisProfile = getAthleteAxisProfile(athlete.id, weekSessions, currentWeek);
133:     if (axisProfile) {
134:       const worst = Object.entries(axisProfile).sort((a, b) => b[1].score - a[1].score)[0];
135:       if (worst && worst[1].score >= 75) {
136:         const [axisId, axisData] = worst;
137:         const axis = LOAD_AXES[axisId];
138:         items.push({
139:           id: `axis-${athlete.id}`, priority: "info", order: 80, icon: "activity", color: axisData.color, route: "charge", label: "Sollicitation marquée",
140:           sentence: `${name} a surtout travaillé ${axis.nounPhrase} cette semaine — ${axis.what}`,
141:         });
142:       }
143:     }
144: 
145:     // Absences répétées cette semaine.
146:     const athleteWeekSessions = weekSessions.filter(s => s.athleteIds?.includes(athlete.id));
147:     const missed = athleteWeekSessions.filter(s => s.validations?.find(v => v.athleteId === athlete.id && v.status === "none")).length;
148:     if (missed >= 2) {
149:       items.push({
150:         id: `absent-${athlete.id}`, priority: "warning", order: 65, icon: "users", color: "var(--tone-danger)", route: "athletes", label: "Absences répétées",
151:         sentence: `${name} a manqué ${missed} séances cette semaine — vaut le coup de vérifier ce qui se passe.`,
152:       });
153:     }
154:   });
155: 
156:   // Blessures actives.
157:   (injuries ?? []).filter(i => i.status !== "résolu").forEach(inj => {
158:     const athlete = athletes.find(a => a.id === inj.athleteId);
159:     if (!athlete) return;
160:     items.push({
161:       id: `injury-${inj.id}`, priority: inj.intensity >= 6 ? "critical" : "warning", order: 20, icon: "heart", route: "athletes", label: "Blessure active",
162:       color: inj.intensity >= 6 ? "#E24B4A" : "#EF9F27",
163:       sentence: `${firstName(athlete.name)} gère une blessure active (${inj.name}, intensité ${inj.intensity}/10).`,
164:     });
165:   });
166: 
167:   return items.sort((a, b) => (a.order ?? 99) - (b.order ?? 99) || PRIORITY[a.priority] - PRIORITY[b.priority]);
168: }  1: // ============================================================
