  5: 
  6: import { useState, memo } from "react";
  7: import { createPortal } from "react-dom";
  8: import { Plus, X, FileText, Users, AlertCircle, CheckCircle, Zap } from "lucide-react";
  9: import { supabase } from "../../utils/supabaseClient";
