 18: const CreateSessionModal = memo(({ athlete, allAthletes, clubId, createdBy, coachUserId, onClose, onCreated }) => {
 19:   const today = toLocalDateStr(new Date());
 20:   const [form, setForm] = useState({
 21:     title: "", category: "technique", trainingFocus: "technical_general", time: "10:00", durationMinutes: 60,
 22:     description: "", sessionDate: today, invitedAthletes: [],
 23:   });
 24:   const [pdfFile, setPdfFile] = useState(null);
