 27:   const { dialogRef } = useAccessibleDialog({ onClose, closeDisabled: saving });
 28: 
 29:   const set       = (k, v) => setForm(f => ({ ...f, [k]: v }));
 30:   const pickPdf = async file => {
 31:     if (!file) { setPdfFile(null); return; }
 32:     const validationError = await validateSessionAttachment(file);
 33:     if (validationError) { setPdfFile(null); setErr(validationError); return; }
 34:     setErr(null); setPdfFile(file);
 35:   };
 36:   const toggleInv = id => setForm(f => ({
 37:     ...f,
 38:     invitedAthletes: f.invitedAthletes.includes(id)
 39:       ? f.invitedAthletes.filter(x => x !== id)
 40:       : [...f.invitedAthletes, id],
 41:   }));
 42: 
 43:   const c = cat(form.category);
 44:   const labelStyle = { display: "block", fontSize: 12, fontWeight: 700, color: "var(--c-text-2)", textTransform: "uppercase", letterSpacing: "0.07em", marginBottom: 8 };
 45: 
 46:   const handleSubmit = async event => {
 47:     event?.preventDefault();
 48:     if (!form.title.trim()) return;
 49:     setSaving(true); setErr(null);
 50:     try {
 51:       let pdfUrl = null;
 52:       if (pdfFile) {
 53:         // Préfixé par club_id pour les policies RLS. Le chemin privé reste
 54:         // stocké dans la colonne historique pdf_url, quel que soit le format.
 55:         pdfUrl = await uploadSessionAttachment(clubId, pdfFile);
 56:       }
 57:       const catLabel = CATEGORIES.find(x => x.id === form.category)?.label ?? form.category;
 58:       const { data: ns, error: se } = await supabase.from("sessions").insert({
 59:         club_id: clubId, week: dateToISOWeek(form.sessionDate), day: dateToDayName(form.sessionDate),
 60:         session_date: form.sessionDate, time: form.time, type: catLabel, category: form.category,
 61:         title: form.title, description: form.description || null, duration_minutes: form.durationMinutes,
 62:         training_focus: form.trainingFocus,
 63:         load_weight: 1.0, pdf_url: pdfUrl, created_by: createdBy,
 64:       }).select().single();
 65:       if (se) throw se;
 66: 
 67:       const allIds = [athlete.id, ...form.invitedAthletes];
 68:       const { error: assignmentError } = await supabase.from("session_athletes").insert(
 69:         allIds.map(id => ({ session_id: ns.id, athlete_id: id, status: null }))
 70:       );
 71:       if (assignmentError) throw assignmentError;
 72:       await notifyCoachAthleteSession(clubId, coachUserId, athlete, {
 73:         id: ns.id, title: form.title, sessionDate: form.sessionDate,
 74:       });
 75:       onCreated(); onClose();
 76:     } catch (e) { setErr(e.message ?? "Erreur"); setSaving(false); }
 77:   };
 78: 
 79:   const others = allAthletes.filter(a => a.id !== athlete.id);
 80: 
 81:   // Portal sur document.body : ce composant est ouvert depuis des pages qui
 82:   // scrollent (Planning, Dashboard) — sans ça, sur mobile, ce position:fixed
 83:   // dérive avec le scroll au lieu de rester épinglé à l'écran (même bug déjà
 84:   // rencontré et corrigé sur FormeDetailPanel.jsx et AthleteClub.jsx).
 85:   return createPortal(
 86:     <div className="fixed inset-0 z-50 flex items-end sm:items-center justify-center sm:p-4 modal-backdrop"
 87:       onClick={e => e.target === e.currentTarget && !saving && onClose()}>
 88:       <form ref={dialogRef} tabIndex={-1} onSubmit={handleSubmit} role="dialog" aria-modal="true" aria-labelledby="create-session-title"
 89:         className="rounded-t-3xl sm:rounded-3xl shadow-2xl w-full sm:max-w-md max-h-[95vh] flex flex-col overflow-hidden modal-content"
 90:         style={{ background: "var(--c-surface)" }}>
 91: 
 92:         {/* Poignée mobile */}
 93:         <div className="flex justify-center pt-3 pb-1 sm:hidden flex-shrink-0">
 94:           <div style={{ width: 40, height: 4, borderRadius: 99, background: "var(--c-border-strong)" }} />
 95:         </div>
 96: 
 97:         {/* Header coloré réactif à la catégorie */}
 98:         <div className="px-6 py-5 flex items-start justify-between gap-4 flex-shrink-0 transition-colors duration-300"
 99:           style={{ background: c.bg, borderBottom: `2px solid ${c.border}40` }}>
100:           <div>
101:             <div className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full mb-2"
102:               style={{ background: `${c.border}25`, border: `1px solid ${c.border}40` }}>
103:               <Zap size={14} style={{ color: c.border }} aria-hidden="true" />
104:               <h2 id="create-session-title" style={{ fontSize: 15, fontWeight: 800, color: c.text }}>
105:                 Planifier une séance
106:               </h2>
107:             </div>
108:             <p style={{ fontSize: 12, fontWeight: 500, color: "var(--c-text-2)" }}>
109:               Ton coach sera notifié automatiquement
110:             </p>
111:           </div>
112:           <button type="button" aria-label="Fermer" onClick={onClose} disabled={saving}
113:             style={{ width: 44, height: 44, borderRadius: 12, display: "flex", alignItems: "center", justifyContent: "center", background: "rgba(255,255,255,0.06)", border: "1px solid var(--c-border)", cursor: "pointer", flexShrink: 0 }}>
114:             <X size={18} style={{ color: c.text }} aria-hidden="true" />
115:           </button>
116:         </div>
117: 
118:         {/* Corps */}
119:         <div className="flex-1 overflow-y-auto px-6 py-5 space-y-5">
120: 
121:           {err && (
122:             <div role="alert" style={{ display: "flex", alignItems: "flex-start", gap: 10, background: "rgba(239,107,107,0.10)", border: "1px solid rgba(239,107,107,0.25)", borderRadius: 14, padding: "12px 14px" }}>
123:               <AlertCircle size={14} color="#F19A9A" style={{ marginTop: 2, flexShrink: 0 }} />
124:               <p style={{ fontSize: 12, color: "var(--tone-danger)" }}>{err}</p>
125:             </div>
126:           )}
127: 
128:           {/* Titre */}
129:           <div>
130:             <label htmlFor="session-title" style={labelStyle}>Titre *</label>
131:             <input id="session-title" className="input-premium" placeholder="Ex: Footing récup, Technique saut…" required autoFocus
132:               value={form.title} onChange={e => set("title", e.target.value)} />
133:           </div>
134: 
135:           {/* Catégories — chips */}
136:           <div>
137:             <label style={labelStyle}>Type de séance</label>
138:             <div className="flex flex-wrap gap-1.5">
139:               {CATEGORIES.map(({ id, label }) => {
140:                 const cc  = cat(id);
141:                 const sel = form.category === id;
142:                 return (
143:                   <button key={id} type="button" aria-pressed={sel} onClick={() => setForm(previous => ({ ...previous, category: id, trainingFocus: getDefaultTrainingFocus(id) }))}
144:                     className="tap-feedback"
145:                     style={{
146:                       minHeight: 44, padding: "8px 13px", borderRadius: 12, fontSize: 13, fontWeight: 700,
147:                       border: `1.5px solid ${sel ? cc.border : `${cc.border}40`}`,
148:                       background: sel ? cc.border : cc.bg,
149:                       color: sel ? "#0A150F" : cc.text,
150:                       boxShadow: sel ? `0 2px 8px ${cc.glow}` : "none",
151:                       cursor: "pointer",
152:                     }}>
153:                     {label}
154:                   </button>
155:                 );
156:               })}
157:             </div>
158:           </div>
159: 
160:           <TrainingFocusField
161:             category={form.category}
162:             value={form.trainingFocus}
163:             onChange={value => set("trainingFocus", value)}
164:           />
165: 
166:           {/* Date + Heure */}
167:           <div className="grid grid-cols-2 gap-3">
168:             <div>
169:               <label htmlFor="session-date" style={labelStyle}>Date *</label>
170:               <input id="session-date" type="date" className="input-premium" value={form.sessionDate} required
171:                 onChange={e => set("sessionDate", e.target.value)} />
172:             </div>
173:             <div>
174:               <label htmlFor="session-time" style={labelStyle}>Heure</label>
175:               <input id="session-time" type="time" className="input-premium" value={form.time}
176:                 onChange={e => set("time", e.target.value)} />
177:             </div>
178:           </div>
179: 
180:           {/* Durée */}
181:           <div>
182:             <label htmlFor="session-duration" style={labelStyle}>Durée (min)</label>
183:             <input id="session-duration" type="number" min="5" step="5" className="input-premium"
184:               value={form.durationMinutes}
185:               onChange={e => set("durationMinutes", Number(e.target.value))} />
186:           </div>
187: 
188:           {/* Description */}
189:           <div>
190:             <label htmlFor="session-description" style={labelStyle}>Description</label>
191:             <textarea id="session-description" className="input-premium resize-none" rows={3}
192:               placeholder="Objectifs, détails…"
193:               value={form.description} onChange={e => set("description", e.target.value)} />
194:           </div>
195: 
196:           {/* Pièce jointe */}
197:           <div>
198:             <label style={labelStyle}>Pièce jointe (optionnelle)</label>
199:             <label style={{ display: "flex", alignItems: "center", gap: 12, padding: 12, borderRadius: 14, border: "2px dashed var(--c-border-strong)", cursor: "pointer" }}>
200:               <div style={{ width: 32, height: 32, borderRadius: 10, background: "rgba(91,158,245,0.14)", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
201:                 <FileText size={14} color="#5B9EF5" />
202:               </div>
203:               <div style={{ flex: 1, minWidth: 0 }}>
204:                 {pdfFile
205:                   ? <p style={{ fontSize: 13, fontWeight: 600, color: "var(--c-text-1)" }} className="truncate">{pdfFile.name}</p>
206:                   : <p style={{ fontSize: 13, color: "var(--c-text-2)" }}>Photo, PDF, Word, Excel… (30 Mo max)</p>}
207:               </div>
208:               <input type="file" accept={SESSION_ATTACHMENT_ACCEPT} className="sr-only"
209:                 onChange={e => pickPdf(e.target.files?.[0] ?? null)} />
210:             </label>
211:           </div>
212: 
213:           {/* Inviter athlètes */}
214:           {others.length > 0 && (
215:             <div>
216:               <label style={labelStyle}><Users size={14} style={{ display: "inline", marginRight: 5 }} aria-hidden="true" />Inviter d'autres athlètes</label>
217:               <div className="flex flex-wrap gap-2">
218:                 {others.map(a => {
219:                   const sel = form.invitedAthletes.includes(a.id);
220:                   return (
221:                     <button key={a.id} type="button" aria-pressed={sel} onClick={() => toggleInv(a.id)}
222:                       className="tap-feedback"
223:                       style={{
224:                         minHeight: 44, display: "flex", alignItems: "center", gap: 8, padding: "8px 12px", borderRadius: 12,
225:                         fontSize: 13, fontWeight: 600, border: `1.5px solid ${sel ? "#1D9E75" : "var(--c-border-strong)"}`,
226:                         background: sel ? "rgba(29,158,117,0.14)" : "var(--c-surface-2)",
227:                         color: sel ? "#7BD8B4" : "var(--c-text-2)", cursor: "pointer",
228:                       }}>
229:                       <div style={{ width: 24, height: 24, borderRadius: "50%", display: "flex", alignItems: "center", justifyContent: "center", color: "white", fontSize: 12, fontWeight: 800, background: sel ? "#1D9E75" : "var(--c-surface-3)" }}>
230:                         {(a.name?.[0] ?? "?").toUpperCase()}
231:                       </div>
232:                       {a.name.split(" ")[0]}
233:                       {sel && <CheckCircle size={12} color="#3DBE8B" />}
234:                     </button>
235:                   );
236:                 })}
237:               </div>
238:             </div>
239:           )}
240:         </div>
241: 
242:         {/* Footer */}
243:         <div className="px-6 py-4 flex items-center justify-between gap-3 flex-shrink-0" style={{ borderTop: "1px solid var(--c-border)" }}>
244:           <button type="button" onClick={onClose} disabled={saving} className="btn-secondary">Annuler</button>
245:           <button type="submit" disabled={!form.title.trim() || saving} className="btn-primary">
246:             {saving
247:               ? <><div className="loader-ring loader-ring-sm" />Création…</>
248:               : <><Plus size={15} />Planifier</>}
249:           </button>
250:         </div>
251:       </form>
252:     </div>,
253:     document.body
254:   );
255: });
