 32: export const TabPerformances = memo(({ athlete, competitions, onAddRecord }) => {
 33:   const disciplines    = Object.keys(athlete.records ?? {});
 34:   const [selectedDisc, setSelectedDisc]   = useState(disciplines[0]);
 35:   const [showAdd,      setShowAdd]        = useState(false);
 36: 
 37:   const chartData = useMemo(() =>
 38:     (athlete.performanceHistory ?? []).filter(p => p.value !== null).map(p => ({ ...p, label: String(p.month).slice(0,7) })),
 39:   [athlete]);
 40: 
 41:   const compHistory = useMemo(() => {
 42:     const all = [];
 43:     (competitions ?? []).forEach(c => {
 44:       if (!c.athleteIds.includes(athlete.id)) return;
 45:       c.results.filter(r => r.athleteId === athlete.id).forEach(r => all.push({ comp: c, result: r }));
 46:     });
 47:     return all.sort((a,b) => new Date(b.comp.date) - new Date(a.comp.date));
 48:   }, [athlete, competitions]);
 49: 
 50:   const rec = selectedDisc ? athlete.records?.[selectedDisc] : null;
 51: 
 52:   return (
 53:     <div className="space-y-5">
 54:       {/* Records table */}
 55:       <div className="card overflow-hidden">
 56:         <div className="px-5 py-4 flex items-center justify-between" style={{ borderBottom: "1px solid var(--c-border)" }}>
 57:           <div>
 58:             <h3 className="card-title">Records & Season Best</h3>
 59:             <p className="card-subtitle mt-0.5">{disciplines.length} épreuve{disciplines.length > 1 ? "s" : ""}</p>
 60:           </div>
 61:           <button type="button" onClick={() => setShowAdd(true)} className="btn-primary !px-3 !text-[12px]">
 62:             <Plus size={12} /> Ajouter
 63:           </button>
 64:         </div>
 65: 
 66:         {disciplines.length === 0 ? (
 67:           <EmptySection icon={Trophy} title="Aucun record enregistré" sub="Les records apparaîtront ici dès qu'ils seront ajoutés." />
 68:         ) : (
 69:           <div className="overflow-x-auto">
 70:             <table className="w-full text-[12.5px]">
 71:               <thead>
 72:                 <tr style={{ borderBottom: "1px solid var(--c-border)" }}>
 73:                   {["Épreuve","SB","PR","Date PR","Progression"].map(h => (
 74:                     <th key={h} className="text-left px-4 py-3 text-[12px] font-bold uppercase tracking-wide whitespace-nowrap" style={{ color: "var(--c-text-2)" }}>
 75:                       {h}
 76:                     </th>
 77:                   ))}
 78:                 </tr>
 79:               </thead>
 80:               <tbody style={{ divideY: "1px solid var(--c-border)" }}>
 81:                 {disciplines.map((disc, i) => {
 82:                   const r    = athlete.records[disc];
 83:                   // Tâche 11 : parsePerf (pas parseFloat, qui tronque "4:32" à 4) +
 84:                   // pctOfReference (sens correct pour les disciplines chronométrées,
 85:                   // au lieu d'un ratio sb/pr toujours dans le même sens).
 86:                   const sbN  = parsePerf(r.sb).value;
 87:                   const prN  = parsePerf(r.pr).value;
 88:                   const pct  = pctOfReference(sbN, prN, disc);
 89:                   const pc   = pct === null ? "var(--c-text-3)" : pct >= 95 ? "#1D9E75" : pct >= 85 ? "#EF9F27" : "#E24B4A";
 90:                   return (
 91:                     <tr key={disc} style={{ borderTop: i > 0 ? "1px solid var(--c-border)" : "none", transition: "background 0.2s" }} onMouseEnter={e => e.currentTarget.style.background = "var(--c-surface-2)"} onMouseLeave={e => e.currentTarget.style.background = "transparent"}>
 92:                       <td className="px-4 py-3.5 font-bold" style={{ color: "var(--c-text-1)" }}>{disc}</td>
 93:                       <td className="px-4 py-3.5" style={{ color: "var(--c-text-2)" }}>{r.sb}</td>
 94:                       <td className="px-4 py-3.5 font-bold text-[14px]" style={{ color: "#1D9E75" }}>{r.pr}</td>
 95:                       <td className="px-4 py-3.5" style={{ color: "var(--c-text-3)" }}>
 96:                         {r.prDate ? new Date(r.prDate).toLocaleDateString("fr-BE",{day:"numeric",month:"short",year:"numeric"}) : "—"}
 97:                       </td>
 98:                       <td className="px-4 py-3.5">
 99:                         {pct !== null ? (
100:                           <div className="flex items-center gap-2">
101:                             <div className="w-16 h-2 rounded-full overflow-hidden" style={{ background: "var(--c-surface-3)" }}>
102:                               <div className="h-full rounded-full" style={{ width:`${pct}%`, background:pc }} />
103:                             </div>
104:                             <span className="text-[12px] font-bold" style={{ color:pc }}>{pct}%</span>
105:                           </div>
106:                         ) : <span className="meta-text">—</span>}
107:                       </td>
108:                     </tr>
109:                   );
110:                 })}
111:               </tbody>
112:             </table>
113:           </div>
114:         )}
115:       </div>
116: 
117:       {/* Graphique évolution */}
