120:           <div className="flex items-center justify-between flex-wrap gap-3 mb-4">
121:             <div>
122:               <h3 className="card-title">Évolution — {athlete.mainDiscipline}</h3>
123:               <p className="card-subtitle mt-0.5">24 derniers mois</p>
