129:                   style={selectedDisc === d ? { background: "#1D9E75", color: "white", boxShadow: "0 2px 8px rgba(29,158,117,0.3)" } : { background: "var(--c-surface-2)", color: "var(--c-text-3)" }}>
130:                   {d}
131:                 </button>
132:               ))}
133:             </div>
134:           </div>
