173:                    onMouseEnter={e => e.currentTarget.style.background = "var(--c-surface-2)"}
174:                    onMouseLeave={e => e.currentTarget.style.background = "transparent"}>
175:                 <div className="w-10 h-10 rounded-2xl flex items-center justify-center flex-shrink-0" style={{ background: "rgba(239,159,39,0.15)" }}>
176:                   <Trophy size={16} color="#EF9F27" />
177:                 </div>
178:                 <div className="flex-1 min-w-0">
179:                   <div className="flex items-center gap-2 flex-wrap mb-1">
180:                     <span className="text-[13px] font-bold" style={{ color: "var(--c-text-1)" }}>{comp.name}</span>
181:                     <span className="text-[12px] font-semibold px-2 py-0.5 rounded-full" style={{ background: "var(--c-surface-3)", color: "var(--c-text-2)" }}>{comp.type}</span>
182:                   </div>
183:                   <p className="text-[12px]" style={{ color: "var(--c-text-3)" }}>
184:                     {result.event} — <strong className="text-[13px]" style={{ color: "var(--tone-success)" }}>{result.result}</strong>
185:                   </p>
186:                   {result.context && <p className="meta-text italic mt-0.5">{result.context}</p>}
187:                 </div>
188:                 <span className="meta-text whitespace-nowrap">
189:                   {new Date(comp.date).toLocaleDateString("fr-BE",{day:"numeric",month:"short"})}
190:                 </span>
191:               </div>
192:             ))}
193:           </div>
194:         )}
195:       </div>
196: 
197:       {showAdd && <AddRecordModal athleteName={athlete.name} onClose={() => setShowAdd(false)} onAdd={form => onAddRecord(athlete.id, form)} />}
198:     </div>
199:   );
200: });
