202: // ─── Onglet Charge ────────────────────────────────────────────────────────────
203: 
204: export const TabCharge = memo(({ athlete, metrics, weeklyCharge, competitions, sessions }) => {
205:   const { load7, load28, variationPercent, acute, chronic, acwr } = metrics;
206:   const chartData = useMemo(() => computeChargeChartData(athlete.id, weeklyCharge), [athlete.id, weeklyCharge]);
207:   const currentWeek = useMemo(() => getISOWeek(new Date()), []);
208:   const axisProfile = useMemo(
209:     () => getAthleteAxisProfile(athlete.id, sessions ?? [], currentWeek),
210:     [athlete.id, sessions, currentWeek]
211:   );
212:   const nextComp  = useMemo(() => {
213:     const now = new Date();
214:     return (competitions ?? []).filter(c => c.athleteIds.includes(athlete.id) && new Date(c.date) >= now)
215:       .sort((a,b) => new Date(a.date) - new Date(b.date))[0] ?? null;
216:   }, [athlete.id, competitions]);
217:   const analysis  = useMemo(() => generateContextAnalysis(metrics, nextComp), [metrics, nextComp]);
218:   const loadStory = useMemo(() => getAthleteLoadStory(metrics, sessions ?? [], athlete.id), [athlete.id, metrics, sessions]);
219:   const hasCharge = weeklyCharge.some(w => w.athleteId === athlete.id);
220: 
221:   if (!hasCharge) return <EmptySection icon={Activity} title="Aucune charge enregistrée" sub="Les scores apparaîtront dès la première séance saisie." />;
222: 
223:   const scoreCards = [
224:     { label: "Cette semaine", value: load7 ?? "—", color: "#378ADD", hint: "7 derniers jours" },
225:     { label: "Rythme habituel", value: load28 ?? "—", color: "var(--tone-info)", hint: "4 dernières semaines" },
226:     { label: "Tendance récente", value: acute == null ? "—" : Math.round(acute), color: "#14B8A6", hint: "EWMA courte" },
227:     { label: "Tendance stable", value: chronic == null ? "—" : Math.round(chronic), color: "#A855F7", hint: "EWMA longue" },
228:     { label: "Écart à l'habitude", value: variationPercent == null ? "—" : `${variationPercent >= 0 ? "+" : ""}${variationPercent}%`, color: "#EF9F27", hint: "semaine vs habitude" },
229:   ];
230: 
231:   return (
232:     <div className="space-y-5">
233:       <div className="card overflow-hidden" style={{ borderColor: "rgba(91,141,239,0.24)" }}>
234:         <div className="p-5" style={{ background: "linear-gradient(135deg, rgba(91,141,239,0.12), rgba(20,184,166,0.05))" }}>
235:           <span className="chip chip-neutral">Lecture coach</span>
236:           <h3 className="mt-3 text-[17px] font-bold" style={{ color: "var(--c-text-1)" }}>{loadStory.headline}</h3>
237:           <p className="mt-2 text-[13px] leading-6" style={{ color: "var(--c-text-2)" }}>{loadStory.summary}</p>
238:           <p className="mt-3 rounded-xl px-3 py-2 text-[12px] leading-5" style={{ background: "rgba(2,7,12,0.22)", color: "var(--c-text-1)" }}>{loadStory.cause}</p>
239:           <p className="mt-2 text-[12px] leading-5" style={{ color: "var(--c-text-2)" }}>À interpréter avec l'athlète et le contenu prévu de ses séances, jamais comme un risque automatique.</p>
240:         </div>
241:       </div>
242: 
243:       {/* Score rings */}
244:       <div className="grid grid-cols-2 md:grid-cols-5 gap-3">
245:         {scoreCards.map(s => (
246:           <div key={s.label} className="card p-4 flex flex-col items-center gap-2">
247:             <ScoreRing value={s.value} color={s.color} label={s.label} />
248:             <span className="meta-text font-medium">{s.hint}</span>
249:           </div>
250:         ))}
251:       </div>
252: 
253:       {/* ACWR expérimental : jamais utilisé comme cible ou signal de risque. */}
254:       <div className="card px-6 py-5 flex items-center justify-between flex-wrap gap-4">
255:         <div>
256:           <p className="meta-text font-bold uppercase tracking-wide mb-1">Métrique expérimentale · ACWR EWMA</p>
257:           <p className="text-[32px] font-bold leading-none" style={{ color: "#94A3B8" }}>{acwr == null ? "—" : acwr.toFixed(2)}</p>
258:           <p className="meta-text mt-1">Affiché seulement avec 28 jours quotidiens continus connus</p>
259:         </div>
260:         <p className="text-[12px] max-w-md" style={{ color: "var(--c-text-2)" }}>Valeur de recherche descriptive. Elle ne constitue ni une zone optimale, ni une estimation individuelle du risque de blessure, ni une consigne d'entraînement.</p>
261:       </div>
262: 
263:       {/* Graphique charge */}
264:       {chartData.length > 0 && (
265:         <div className="card p-5">
266:           <h3 className="card-title mb-1">Charge observée — 12 semaines</h3>
267:           <p className="card-subtitle mb-4">Durée réelle × RPE CR10 · aucune estimation de forme ou de fatigue</p>
268:           <ResponsiveContainer width="100%" height={220}>
269:             <AreaChart data={chartData} margin={{ top: 10, right: 10, left: -20, bottom: 0 }}>
270:               <defs>
271:                 <linearGradient id="gradCharge2" x1="0" y1="0" x2="0" y2="1">
272:                   <stop offset="5%" stopColor="#378ADD" stopOpacity={0.2} />
273:                   <stop offset="95%" stopColor="#378ADD" stopOpacity={0} />
274:                 </linearGradient>
275:               </defs>
276:               <CartesianGrid strokeDasharray="3 3" stroke="var(--c-border)" />
277:               <XAxis dataKey="label" tick={{ fontSize:12, fill:"var(--c-text-3)" }} axisLine={false} tickLine={false} />
278:               <YAxis tick={{ fontSize:12, fill:"var(--c-text-3)" }} axisLine={false} tickLine={false} width={45} />
279:               <Tooltip content={<ChartTooltip />} />
280:               <Area dataKey="rawLoad" name="Charge brute" stroke="#378ADD" fill="url(#gradCharge2)" strokeWidth={2} />
281:             </AreaChart>
282:           </ResponsiveContainer>
283:         </div>
284:       )}
285: 
286:       {/* Profil de charge (6 axes) */}
287:       <AxisRadarCard
288:         profile={axisProfile} title="Ce que ses séances ont surtout sollicité" subtitle="Lecture descriptive des objectifs déclarés, comparée aux semaines habituelles de l'athlète"
289:         sessions={sessions} athleteId={athlete.id} currentWeek={currentWeek}
290:       />
291: 
292:       {/* Analyse contextuelle */}
293:       <div className="card p-5">
294:         <div className="flex items-center gap-2 mb-3">
295:           <div className="w-8 h-8 rounded-xl flex items-center justify-center flex-shrink-0" style={{ background: "rgba(239,159,39,0.15)" }}>
296:             <Zap size={15} color="#EF9F27" />
297:           </div>
298:           <div>
299:             <h3 className="card-title">Analyse contextuelle</h3>
300:             <p className="meta-text">Règles automatiques · sans IA</p>
301:           </div>
302:         </div>
303:         <div className="space-y-2">
304:           {analysis.map((line, i) => (
305:             <div key={i} className="rounded-2xl px-4 py-3" style={{ background: "var(--c-surface-2)" }}>
306:               <p className="text-[13px] leading-relaxed" style={{ color: "var(--c-text-2)" }}>{line}</p>
307:             </div>
308:           ))}
309:         </div>
310:       </div>
311:     </div>
312:   );
313: });
314: 
315: // ─── Onglet Entraînements ─────────────────────────────────────────────────────
316: 
317: export const TabEntrainements = memo(({ athlete, sessions }) => {
318:   const athleteSessions = useMemo(() => {
319:     if (!sessions.length) return [];
320:     const maxWeek = Math.max(...sessions.map(s => s.week));
321:     return sessions
322:       .filter(s => s.athleteIds.includes(athlete.id) && s.week >= maxWeek - 3)
323:       .sort((a,b) => b.week - a.week || a.day.localeCompare(b.day));
324:   }, [athlete.id, sessions]);
325: 
326:   return (
327:     <div className="space-y-3">
328:       {athleteSessions.length === 0 ? (
329:         <EmptySection icon={Dumbbell} title="Aucune séance enregistrée" sub="Les séances apparaîtront ici une fois programmées." />
330:       ) : (
331:         athleteSessions.map(s => {
332:           const val    = s.validations.find(v => v.athleteId === athlete.id);
333:           const status = val?.status ?? "future";
334:           const iconBg = { done:"rgba(29,158,117,0.15)", partial:"rgba(239,159,39,0.15)", none:"rgba(226,75,74,0.15)", future:"var(--c-surface-2)" }[status] ?? "var(--c-surface-2)";
335:           return (
336:             <div key={s.id} className="card px-5 py-4 flex items-start gap-4">
337:               <div className="w-10 h-10 rounded-2xl flex items-center justify-center flex-shrink-0" style={{ background: iconBg }}>
338:                 {status === "done"    ? <CheckCircle   size={18} color="#1D9E75" /> :
339:                  status === "partial" ? <AlertTriangle size={18} color="#EF9F27" /> :
340:                  status === "none"    ? <AlertTriangle size={18} color="#E24B4A" /> :
341:                  <Clock size={18} style={{ color: "var(--c-text-3)" }} />}
342:               </div>
343:               <div className="flex-1 min-w-0">
344:                 <div className="flex items-center gap-2 flex-wrap mb-1">
345:                   <span className="text-[13.5px] font-bold" style={{ color: "var(--c-text-1)" }}>{s.title}</span>
346:                   <ValidationBadge status={status} />
347:                 </div>
348:                 <p className="meta-text mb-2">
349:                   {s.day} · Semaine {s.week} · {s.time} · {s.type}
350:                 </p>
351:                 {val?.comment && (
352:                   <p className="text-[12px] italic mb-2" style={{ color: "var(--c-text-2)" }}>« {val.comment} »</p>
353:                 )}
354:                 {(val?.feeling != null || val?.fatigue != null) && (
355:                   <div className="flex items-center gap-4 text-[12px]" style={{ color: "var(--c-text-2)" }}>
356:                     {val.feeling != null && <span className="flex items-center gap-1.5">Ressenti <StarRow value={val.feeling} /></span>}
357:                     {val.fatigue != null && <span className="flex items-center gap-1.5">Fatigue <StarRow value={val.fatigue} color="#E24B4A" /></span>}
358:                   </div>
359:                 )}
360:               </div>
361:               <span className="meta-text whitespace-nowrap mt-0.5">S{s.week}</span>
362:             </div>
363:           );
364:         })
365:       )}
366:     </div>
367:   );
368: });
