370: // ─── Onglet Blessures ─────────────────────────────────────────────────────────
371: 
372: export const TabBlessures = memo(({ athlete, onAddInjury, onUpdateInjury, onDeleteInjury }) => {
373:   const injuries = athlete.injuries ?? [];
374:   const [modalTarget,      setModalTarget]      = useState(null);
375:   const [confirmDeleteId, setConfirmDeleteId] = useState(null);
376: 
377:   const statusConfig = {
378:     "chronique": { bg: "rgba(226,75,74,0.15)", color: "var(--tone-danger)", border: "#E24B4A", label: "Chronique" },
379:     "en suivi":  { bg: "rgba(239,159,39,0.15)", color: "var(--tone-warning)", border: "#EF9F27", label: "En suivi"  },
380:     "résolu":    { bg: "rgba(29,158,117,0.15)", color: "var(--tone-success)", border: "#1D9E75", label: "Résolu"    },
381:     "actif":     { bg: "rgba(226,75,74,0.15)", color: "var(--tone-danger)", border: "#E24B4A", label: "Actif"      },
382:   };
383: 
384:   return (
385:     <div className="space-y-4">
386:       <div className="flex justify-end">
387:         <button onClick={() => setModalTarget("create")} className="btn-primary">
388:           <Plus size={13} /> Signaler une blessure
389:         </button>
390:       </div>
391: 
392:       {injuries.length === 0 ? (
393:         <div className="card p-12 text-center">
394:           <CheckCircle size={36} color="#1D9E75" className="mx-auto mb-3" />
395:           <p className="text-[14px] font-bold" style={{ color: "var(--c-text-2)" }}>Aucun antécédent enregistré</p>
396:           <p className="meta-text mt-1">Athlète sans blessure connue</p>
397:         </div>
398:       ) : (
399:         injuries.map(inj => {
400:           const sc     = statusConfig[inj.status] ?? statusConfig["en suivi"];
401:           const active = inj.status !== "résolu";
402:           const pct    = (inj.intensity / 10) * 100;
403:           const iColor = inj.intensity <= 3 ? "#1D9E75" : inj.intensity <= 6 ? "#EF9F27" : "#E24B4A";
404:           return (
405:             <div
406:               key={inj.id}
407:               className={["card overflow-hidden", active ? "border-l-4" : ""].join(" ")}
408:               style={active ? { borderLeftColor: sc.border } : {}}
409:             >
410:               <div className="px-5 py-5">
411:                 <div className="flex items-start justify-between gap-3 flex-wrap mb-3">
412:                   <div>
413:                     <div className="flex items-center gap-2 flex-wrap mb-1">
414:                       <h3 className="text-[15px] font-bold" style={{ color: "var(--c-text-1)" }}>{inj.name}</h3>
415:                       <span className="text-[12px] font-bold px-2 py-0.5 rounded-full" style={{ background: sc.bg, color: sc.color }}>
416:                         {sc.label}
417:                       </span>
418:                     </div>
419:                     <p className="text-[12px]" style={{ color: "var(--c-text-3)" }}>📍 {inj.location}</p>
420:                   </div>
421:                   <div className="text-right">
422:                     <p className="meta-text mb-1.5">Intensité douleur</p>
423:                     <div className="flex items-center gap-1 justify-end">
424:                       {Array.from({ length: 10 }).map((_, i) => (
425:                         <div key={i} className="w-2.5 h-2.5 rounded-sm transition-colors"
426:                           style={{ background: i < inj.intensity ? iColor : "var(--c-surface-3)" }} />
427:                       ))}
428:                       <span className="text-[13px] font-bold ml-1.5" style={{ color: iColor }}>
429:                         {inj.intensity}/10
430:                       </span>
431:                     </div>
432:                   </div>
433:                 </div>
434: 
435:                 {/* Barre intensité */}
436:                 <div className="progress-bar mb-3">
437:                   <div className="progress-fill" style={{ width:`${pct}%`, background:iColor }} />
438:                 </div>
439: 
440:                 <div className="flex items-center gap-4 text-[12px] mb-3 flex-wrap" style={{ color: "var(--c-text-2)" }}>
441:                   {inj.startDate && (
442:                     <span>Début : <strong style={{ color: "var(--c-text-2)" }}>
443:                       {new Date(inj.startDate).toLocaleDateString("fr-BE",{day:"numeric",month:"long",year:"numeric"})}
444:                     </strong></span>
445:                   )}
446:                   {!inj.endDate && active && <span className="font-bold" style={{ color: "#EF9F27" }}>⚡ En cours</span>}
447:                 </div>
448: 
449:                 {inj.notes && (
450:                   <div className="rounded-2xl px-4 py-3 border mb-3" style={{ background: "var(--c-surface-2)", borderColor: "var(--c-border)" }}>
451:                     <p className="meta-text font-bold uppercase tracking-wide mb-1">Notes / suivi</p>
452:                     <p className="text-[12.5px] leading-relaxed" style={{ color: "var(--c-text-2)" }}>{inj.notes}</p>
453:                   </div>
454:                 )}
455: 
456:                 <div className="flex items-center gap-3 pt-3" style={{ borderTop: "1px solid var(--c-border)" }}>
457:                   <button onClick={() => setModalTarget(inj)}
458:                     className="text-[12px] font-semibold transition-colors" style={{ color: "var(--c-text-2)" }} onMouseEnter={e => e.currentTarget.style.color = "var(--c-text-1)"} onMouseLeave={e => e.currentTarget.style.color = "var(--c-text-2)"}>
459:                     ✏️ Modifier
460:                   </button>
461:                   {confirmDeleteId === inj.id ? (
462:                     <span className="flex items-center gap-2">
463:                       <span className="text-[12px] font-semibold" style={{ color: "var(--tone-danger)" }}>Confirmer ?</span>
464:                       <button onClick={async () => { await onDeleteInjury(inj.id); setConfirmDeleteId(null); }}
465:                         className="text-[12px] font-bold text-white rounded-lg px-2 py-0.5" style={{ background: "#E24B4A" }}>Oui</button>
466:                       <button onClick={() => setConfirmDeleteId(null)} className="text-[12px]" style={{ color: "var(--c-text-2)" }}>Non</button>
467:                     </span>
468:                   ) : (
469:                     <button onClick={() => setConfirmDeleteId(inj.id)}
470:                       className="text-[12px] font-semibold transition-colors" style={{ color: "var(--tone-danger)" }} onMouseEnter={e => e.currentTarget.style.color = "#E24B4A"} onMouseLeave={e => e.currentTarget.style.color = "#F19A9A"}>
471:                       🗑️ Supprimer
472:                     </button>
473:                   )}
474:                 </div>
475:               </div>
476:             </div>
477:           );
478:         })
479:       )}
480: 
481:       {modalTarget && (
482:         <AddInjuryModal
483:           athleteName={athlete.name}
484:           initialData={modalTarget === "create" ? null : {
485:             name: modalTarget.name, location: modalTarget.location,
486:             intensity: modalTarget.intensity, status: modalTarget.status,
487:             startDate: modalTarget.startDate ?? "", notes: modalTarget.notes ?? "",
488:           }}
489:           onClose={() => setModalTarget(null)}
490:           onSave={form => modalTarget === "create" ? onAddInjury(athlete.id, form) : onUpdateInjury(modalTarget.id, form)}
491:         />
492:       )}
493:     </div>
494:   );
495: });
496: 
497: // ─── Onglet Profil ────────────────────────────────────────────────────────────
498: 
499: export const TabProfil = memo(({ athlete }) => {
500:   const p = athlete.profile ?? {};
501:   const hasProfile = Object.keys(p).length > 0;
502:   const stabilityScore = computePerformanceStability(athlete.performanceHistory);
503:   const stabilityColor = s => s === null ? "var(--c-text-3)" : s >= 75 ? "#1D9E75" : s >= 50 ? "#EF9F27" : "#E24B4A";
504:   const toleranceColor = v => (v==="très élevée"||v==="élevée") ? "#1D9E75" : (v==="modérée"||v==="normale") ? "#EF9F27" : "#E24B4A";
505: 
506:   const stabilityCard = (
507:     <div className="card px-6 py-5 flex items-center gap-5">
508:       <div className="flex-shrink-0">
509:         <svg width="72" height="72" viewBox="0 0 72 72">
510:           <circle cx="36" cy="36" r="28" fill="none" stroke="var(--c-surface-3)" strokeWidth="7" />
511:           {stabilityScore !== null && (
512:             <circle cx="36" cy="36" r="28" fill="none" stroke={stabilityColor(stabilityScore)} strokeWidth="7"
513:               strokeDasharray={`${(stabilityScore/100)*2*Math.PI*28} ${2*Math.PI*28}`}
514:               strokeLinecap="round" transform="rotate(-90 36 36)" />
515:           )}
516:           <text x="36" y="41" textAnchor="middle" fontSize="14" fontWeight="800" fill={stabilityColor(stabilityScore)}>
517:             {stabilityScore ?? "—"}
518:           </text>
519:         </svg>
520:       </div>
521:       <div>
522:         <p className="card-title">Stabilité de performance</p>
523:         <p className="text-[12px] mt-1 leading-relaxed" style={{ color: "var(--c-text-3)" }}>
524:           {stabilityScore !== null
525:             ? "Régularité des résultats (coefficient de variation)."
526:             : "Pas encore assez de mesures (minimum 3)."}
527:         </p>
528:       </div>
529:     </div>
530:   );
531: 
532:   if (!hasProfile) return <div className="space-y-5">{stabilityCard}<EmptySection icon={User} title="Profil athlétique non complété" sub="L'athlète n'a pas encore renseigné son profil." /></div>;
533: 
534:   const radarData = RADAR_KEYS.map(k => ({ discipline: k.label, value: p[k.key] ?? 0 }));
535:   const infoRows  = [
536:     { label: "Récupération",        value: p.recoveryRate       ?? "—" },
537:     { label: "Tolérance volume",    value: p.volumeTolerance    ?? "—" },
538:     { label: "Tolérance intensité", value: p.intensityTolerance ?? "—" },
539:     { label: "Profil psycho",       value: p.psychProfile       ?? "—" },
540:   ];
541: 
542:   return (
543:     <div className="space-y-5">
544:       {stabilityCard}
545:       <div className="grid grid-cols-1 lg:grid-cols-2 gap-5">
546:         <div className="card p-5">
547:           <h3 className="card-title mb-1">Profil athlétique</h3>
548:           <p className="meta-text mb-4">Scores 0 – 100</p>
549:           <ResponsiveContainer width="100%" height={260}>
550:             <RadarChart data={radarData} cx="50%" cy="50%" outerRadius="70%">
551:               <PolarGrid stroke="var(--c-border)" />
552:               <PolarAngleAxis dataKey="discipline" tick={{ fontSize:12, fill:"var(--c-text-3)", fontWeight:600 }} />
553:               <PolarRadiusAxis angle={90} domain={[0,100]} tick={{ fontSize:12, fill:"var(--c-text-3)" }} tickCount={4} />
554:               <Radar name={athlete.name} dataKey="value" stroke="#1D9E75" fill="#1D9E75" fillOpacity={0.18} strokeWidth={2.5} />
555:               <Tooltip content={<ChartTooltip />} />
556:             </RadarChart>
557:           </ResponsiveContainer>
558:           <div className="grid grid-cols-5 gap-2 mt-2">
559:             {RADAR_KEYS.map(k => (
560:               <div key={k.key} className="text-center">
561:                 <p className="text-[18px] font-bold" style={{ color: scoreColor(p[k.key] ?? 0) }}>{p[k.key] ?? "—"}</p>
562:                 <p className="meta-text">{k.label}</p>
563:               </div>
564:             ))}
565:           </div>
566:         </div>
567:         <div className="space-y-4">
