180: const AthleteLoadDetails = memo(({ item, week }) => {
181:   const { athlete, metrics, loadState } = item;
182:   const reading = describeLoadVariation(metrics.variationPercent);
183:   const toneColor = {
184:     up: "#EF9F27",
185:     down: "#A855F7",
186:     stable: "#14B8A6",
187:     neutral: "#94A3B8",
188:   }[reading.tone];
189:   const monotonyValue = metrics.monotonyStatus === "undefined_zero_variance"
190:     ? "Indéfinie"
191:     : metricValue(metrics.monotony);
192: 
193:   const simpleMeasures = [
194:     {
195:       label: `Charge de la semaine S${week}`,
196:       value: loadState.value == null ? "—" : `${loadState.value} points`,
197:       detail: loadState.detail,
198:     },
199:     {
200:       label: "Charge des 7 derniers jours",
201:       value: metrics.load7 == null ? "—" : `${metrics.load7} points`,
202:       detail: "Somme des durées réelles × efforts ressentis sur 7 jours. Un repos confirmé compte 0 ; un jour inconnu bloque le total.",
203:     },
204:     {
205:       label: "Charge des 28 derniers jours",
206:       value: metrics.load28 == null ? "—" : `${metrics.load28} points`,
207:       detail: "Somme des 4 dernières semaines, utilisée pour construire l'habitude récente — pas une note de forme.",
208:     },
209:     {
210:       label: "Écart avec l'habitude",
211:       value: reading.valueLabel,
212:       detail: reading.summary,
213:     },
214:   ];
215: 
216:   const advancedMeasures = [
217:     {
218:       label: "EWMA courte",
219:       value: metricValue(metrics.acute),
220:       detail: "Moyenne quotidienne lissée qui donne davantage de poids aux jours récents (constante de 7 jours).",
221:     },
222:     {
223:       label: "EWMA longue",
224:       value: metricValue(metrics.chronic),
225:       detail: "Moyenne quotidienne lissée sur un repère plus long (constante de 28 jours).",
226:     },
227:     {
228:       label: "Monotonie descriptive",
