230:       detail: metrics.monotonyStatus === "undefined_zero_variance"
231:         ? "Les 7 charges quotidiennes sont identiques : l'écart-type vaut zéro et le ratio n'est pas calculable."
232:         : "Compare la moyenne et la variabilité des 7 charges quotidiennes. Ce nombre ne prédit pas une blessure.",
233:     },
234:     {
235:       label: "ACWR EWMA expérimental",
236:       value: metrics.acwr == null ? "—" : Number(metrics.acwr).toFixed(2),
237:       detail: "Rapport entre les deux EWMA, affiché seulement avec 28 jours continus connus. AthleteOS n'applique ni zone optimale ni risque individuel.",
238:     },
239:   ];
240: 
241:   return (
242:     <div className="rounded-2xl p-4 md:p-5 space-y-4" style={{ background: "linear-gradient(135deg, rgba(55,138,221,0.10), rgba(20,184,166,0.04))", border: "1px solid rgba(55,138,221,0.20)" }}>
243:       <div className="flex items-start gap-3">
244:         <div className="w-9 h-9 rounded-xl flex items-center justify-center flex-shrink-0" style={{ background: `${toneColor}18` }}>
245:           {reading.tone === "up" ? <TrendingUp size={17} color={toneColor} /> :
246:            reading.tone === "down" ? <TrendingDown size={17} color={toneColor} /> :
247:            reading.tone === "stable" ? <Minus size={17} color={toneColor} /> :
248:            <Info size={17} color={toneColor} />}
249:         </div>
250:         <div>
251:           <p className="text-[12px] font-semibold uppercase tracking-wide" style={{ color: "var(--c-text-3)" }}>Lecture simple · {athlete.name}</p>
252:           <h4 className="text-[15px] font-bold mt-1" style={{ color: "var(--c-text-1)" }}>{reading.label}</h4>
253:           <p className="text-[13px] leading-6 mt-1" style={{ color: "var(--c-text-2)" }}>{reading.summary}</p>
254:         </div>
255:       </div>
256: 
257:       <div className="grid sm:grid-cols-2 xl:grid-cols-4 gap-3">
258:         {simpleMeasures.map((measure) => (
259:           <div key={measure.label} className="rounded-xl p-3.5" style={{ background: "var(--c-surface-2)", border: "1px solid var(--c-border)" }}>
260:             <p className="text-[12px] font-semibold" style={{ color: "var(--c-text-2)" }}>{measure.label}</p>
261:             <p className="text-[17px] font-bold mt-1" style={{ color: "var(--c-text-1)" }}>{measure.value}</p>
262:             <p className="text-[12px] leading-5 mt-2" style={{ color: "var(--c-text-3)" }}>{measure.detail}</p>
263:           </div>
264:         ))}
265:       </div>
266: 
267:       <details className="rounded-xl" style={{ border: "1px solid var(--c-border)" }}>
268:         <summary className="px-4 py-3 cursor-pointer text-[12.5px] font-semibold" style={{ color: "var(--c-text-2)" }}>
269:           Voir le détail scientifique de {athlete.name.split(" ")[0]}
270:         </summary>
271:         <div className="grid sm:grid-cols-2 gap-3 p-3 border-t" style={{ borderColor: "var(--c-border)" }}>
272:           {advancedMeasures.map((measure) => (
273:             <div key={measure.label} className="rounded-xl p-3" style={{ background: "var(--c-surface-2)" }}>
274:               <div className="flex items-baseline justify-between gap-3">
275:                 <p className="text-[12px] font-semibold" style={{ color: "var(--c-text-2)" }}>{measure.label}</p>
276:                 <strong className="text-[13px]" style={{ color: "var(--c-text-1)" }}>{measure.value}</strong>
