325: function ChargeView() {
326:   const { clubId } = useAuth();
327:   const CURRENT_WEEK = getISOWeek(new Date());
328:   const CURRENT_YEAR = getISOWeekYear(new Date());
329:   const previousWeekDate = new Date();
330:   previousWeekDate.setDate(previousWeekDate.getDate() - 7);
331:   const PREVIOUS_WEEK = getISOWeek(previousWeekDate);
332:   const PREVIOUS_YEAR = getISOWeekYear(previousWeekDate);
333: 
334:   const [athletes,             setAthletes]             = useState([]);
335:   const [weeklyCharge,         setWeeklyCharge]         = useState([]);
336:   const [wellnessRows,         setWellnessRows]         = useState([]);
337:   const [sessionsForBreakdown, setSessionsForBreakdown] = useState([]);
338:   const [loading,              setLoading]              = useState(true);
339:   const [error,                setError]                = useState(null);
340:   const [highlightedAthlete,   setHighlightedAthlete]   = useState(null);
341:   const [expandedAthlete,      setExpandedAthlete]      = useState(null);
342:   const [advancedOpen,         setAdvancedOpen]         = useState(false);
343: 
344:   // ═══ Chargement ═══════════════════════════════════════════════════════════
345:   const fetchAll = useCallback(async () => {
346:     if (!clubId) return;
347:     try {
348:       setLoading(true);
349:       setError(null);
350: 
351:       const requestDate = new Date();
352:       const [athletesRes, sessionsRes, wellnessRes] = await Promise.all([
353:         supabase
354:           .from("athletes")
355:           .select("id, name, main_discipline, profile_data")
356:           .eq("club_id", clubId),
357:         supabase
358:           .from("sessions")
359:           .select("id, week, session_date, category, training_focus, duration_minutes")
360:           .eq("club_id", clubId),
361:         supabase
362:           .from("athlete_wellness")
363:           .select("athlete_id, date, sleep, energy, soreness, mood, stress, notes")
364:           .eq("club_id", clubId)
365:           .eq("date", toLocalDateStr(requestDate)),
366:       ]);
367:       if (athletesRes.error) throw athletesRes.error;
368:       if (sessionsRes.error) throw sessionsRes.error;
369:       if (wellnessRes.error) throw wellnessRes.error;
370: 
371:       const athleteRows = athletesRes.data ?? [];
372:       const sessionRows = sessionsRes.data ?? [];
373:       const sessionIds = sessionRows.map((session) => session.id);
374:       const athleteIds = athleteRows.map((athlete) => athlete.id);
375:       const [sessionAthletesRes, weeklyChargeRes] = await Promise.all([
376:         sessionIds.length
377:           ? supabase.from("session_athletes").select("session_id, athlete_id, rpe, actual_duration_minutes, duration_source").in("session_id", sessionIds)
378:           : Promise.resolve({ data: [], error: null }),
379:         // Total hebdomadaire calculé côté serveur (vue weekly_charge, voir
380:         // migration 20260726120000). La ventilation par catégorie ci-dessous
381:         // reste calculée ici : la vue n'expose que le total par athlète/semaine.
382:         athleteIds.length
383:           ? supabase.from("weekly_charge").select("*").in("athlete_id", athleteIds)
384:           : Promise.resolve({ data: [], error: null }),
385:       ]);
386:       if (sessionAthletesRes.error) throw sessionAthletesRes.error;
387:       if (weeklyChargeRes.error) throw weeklyChargeRes.error;
388: 
389:       const remappedAthletes = athleteRows.map((a) => ({
390:         id:             a.id,
391:         name:           a.name,
392:         mainDiscipline: a.main_discipline,
