 66:         athleteIds.length     ? supabase.from("performance_history").select("*").in("athlete_id", athleteIds)  : Promise.resolve({data:[]}),
 67:         sessionIds.length     ? supabase.from("session_athletes").select("*").in("session_id", sessionIds)     : Promise.resolve({data:[]}),
 68:         competitionIds.length ? supabase.from("competition_athletes").select("*").in("competition_id", competitionIds) : Promise.resolve({data:[]}),
