 68:           ? supabase.from("injuries").select("*").in("athlete_id", athleteIds)
 69:           : Promise.resolve({ data: [], error: null }),
 70:       ]);
 71:       if (chargeRes.error)       throw chargeRes.error;
 72:       if (competitionsRes.error) throw competitionsRes.error;
 73:       if (recordsRes.error)      throw recordsRes.error;
 74:       if (injuriesRes.error)     throw injuriesRes.error;
 75: 
 76:       const competitionIds = competitionsRes.data.map((c) => c.id);
 77: 
 78:       const [compAthletesRes, compResultsRes] = await Promise.all([
 79:         competitionIds.length
 80:           ? supabase.from("competition_athletes").select("*").in("competition_id", competitionIds)
 81:           : Promise.resolve({ data: [], error: null }),
