 83:           ? supabase.from("competition_results").select("*").in("competition_id", competitionIds)
 84:           : Promise.resolve({ data: [], error: null }),
 85:       ]);
 86:       if (compAthletesRes.error) throw compAthletesRes.error;
 87:       if (compResultsRes.error)  throw compResultsRes.error;
 88: 
 89:       const remappedAthletes = athletesRes.data.map((a) => ({
 90:         id:             a.id,
 91:         name:           a.name,
 92:         mainDiscipline: a.main_discipline,
 93:         avatar:         a.profile_data?.avatar ?? initialsFromName(a.name),
 94:         injuries:       (injuriesRes.data ?? [])
 95:           .filter((injury) => injury.athlete_id === a.id)
 96:           .map((injury) => ({
 97:             id: injury.id,
 98:             name: injury.name,
 99:             location: injury.location,
100:             intensity: injury.intensity,
101:             status: injury.status,
102:             startDate: injury.start_date,
103:             notes: injury.notes,
104:           })),
105:       }));
106: 
107:       const remappedCharge = chargeRes.data.map((c) => ({
108:         athleteId: c.athlete_id,
109:         week:      c.week,
110:         isoYear:   c.iso_year,
111:         rawLoad:   c.raw_load,
112:         dailyLoads: c.daily_loads ?? [],
113:         knownDays: c.known_days ?? 0,
114:         unknownDays: c.unknown_days ?? 0,
115:         estimatedDays: c.estimated_days ?? 0,
116:       }));
117: 
118:       const remappedCompetitions = competitionsRes.data.map((c) => {
119:         const rows   = compAthletesRes.data.filter((x) => x.competition_id === c.id);
120:         const athIds = rows.map((x) => x.athlete_id);
121:         const plannedEvents = {};
122:         rows.forEach((r) => { plannedEvents[r.athlete_id] = r.planned_event; });
123:         const results = compResultsRes.data
124:           .filter((r) => r.competition_id === c.id)
125:           .map((r) => ({
126:             ...r,
127:             athleteId: r.athlete_id,
128:             event:     r.event,
129:             result:    r.result,
130:             context:   r.context,
131:           }));
132:         return {
133:           id: c.id, name: c.name, date: c.date,
134:           location: c.location, type: c.type,
135:           athleteIds: athIds, plannedEvents, results,
