139:       setAthletes(remappedAthletes);
140:       setWeeklyCharge(remappedCharge);
141:       setCompetitionList(remappedCompetitions);
142:       setRecords(recordsRes.data.map((r) => ({
143:         id:         r.id,
144:         athleteId:  r.athlete_id,
145:         discipline: r.discipline,
146:         sb:         r.sb,
147:         pr:         r.pr,
148:         prDate:     r.pr_date,
149:       })));
150:     } catch (err) {
