162:   // au lieu de deux inserts successifs (compétition, puis participants) —
163:   // avant, une panne entre les deux laissait une compétition sans aucun
164:   // participant, sans qu'on ait aucun moyen simple de le voir/réparer.
165:   // club_id résolu côté serveur (jamais envoyé par le client).
166: 
167:   const createCompetition = useCallback(async (form) => {
168:     const { error } = await supabase.rpc("create_competition_with_athletes", {
169:       p_name:            form.name,
170:       p_date:            form.date,
171:       p_location:        form.location || null,
172:       p_type:            form.type,
173:       p_athlete_entries: form.athleteEntries.map((e) => ({ athleteId: e.athleteId, plannedEvent: e.plannedEvent || null })),
174:       p_idempotency_key: crypto.randomUUID(),
175:     });
176:     if (error) throw error;
177:     await fetchAll();
178:   }, [fetchAll]);
179: 
180:   // ═══ Écriture : ajouter un résultat ══════════════════════════════════════
181:   // Tâche 14 : un seul appel RPC atomique (add_competition_result) —
182:   // résultat + comparaison/mise à jour du record (verrouillée côté serveur
183:   // contre deux résultats concurrents battant le même record) + écriture
184:   // de l'outbox de notifications se font dans LA MÊME transaction SQL.
185:   // Les vraies notifications ne sont dépêchées qu'après le retour en
186:   // succès du RPC (donc après COMMIT confirmé) — avant, une erreur sur la
187:   // mise à jour du record était juste loguée et n'empêchait pas l'envoi
188:   // des notifications malgré l'échec.
189: 
190:   const addResult = useCallback(async (competitionId, athleteId, form) => {
191:     // Tâche 9 : normalise un alias saisi librement ("100 m" -> "100m") vers
192:     // l'identifiant canonique du registre avant d'écrire en base.
193:     const event = resolveDisciplineId(form.event);
194:     const resultValue = parsePerf(form.result).value;
195:     if (resultValue == null) throw new Error("Le résultat doit contenir une valeur numérique valide.");
196:     const metadata = normalizePerformanceMetadata(event, form.metadata);
197:     const metadataIssues = validatePerformanceMetadata(event, metadata);
198:     if (metadataIssues.length) throw new Error(metadataIssues[0]);
199:     const { data, error } = await supabase.rpc("add_competition_result_v2", {
200:       p_competition_id:   competitionId,
201:       p_athlete_id:       athleteId,
202:       p_event:            event,
203:       p_result:           form.result,
204:       p_result_value:     resultValue,
205:       p_higher_is_better: metadata.performance_direction === "higher",
206:       p_context:          form.context || null,
207:       p_idempotency_key:  crypto.randomUUID(),
208:       p_unit:             metadata.unit,
209:       p_metadata:         metadata,
210:     });
211:     if (error) throw error;
212: 
213:     await dispatchOutboxNotifications(data?.notifications);
214:     await fetchAll();
215:   }, [fetchAll]);
216: 
217:   // Synchronise la compétition sélectionnée avec les données fraîches
218:   const liveSelectedComp = selectedComp
219:     ? competitionList.find((c) => c.id === selectedComp.id) ?? selectedComp
220:     : null;
221: 
222:   const sorted = useMemo(
223:     () => [...competitionList].sort((a, b) => a.date.localeCompare(b.date)),
224:     [competitionList]
225:   );
226: 
227:   const pastComps   = sorted.filter((c) => daysUntil(c.date) < 0);
228:   const futureComps = sorted.filter((c) => daysUntil(c.date) >= 0);
229:   const nextComp    = futureComps[0];
230: 
231:   const stats = useMemo(() => ({
232:     total:       competitionList.length,
233:     past:        pastComps.length,
234:     upcoming:    futureComps.length,
235:     withResults: competitionList.filter((c) => c.results?.length > 0).length,
236:   }), [competitionList, pastComps, futureComps]);
237: 
238:   // ═══ Render ═══════════════════════════════════════════════════════════════
239: 
240:   if (loading) return <LoadingState message="Chargement des compétitions…" />;
241:   if (error)   return <ErrorState  message={error} onRetry={fetchAll} />;
242: 
243:   return (
244:     <div className="page-container py-4 md:py-6 max-w-6xl mx-auto space-y-5 md:space-y-6 animate-slide-up">
245: 
246:       {/* ── En-tête ──────────────────────────────────────────────────────── */}
247:       <div className="flex items-start justify-between flex-wrap gap-4">
248:         <div>
249:           <h2 className="page-title">Compétitions</h2>
250:           <p className="secondary-text mt-1">Calendrier de la saison, engagements et résultats</p>
251:         </div>
252:         <button
253:           type="button"
254:           onClick={() => setShowCreateModal(true)}
255:           disabled={athletes.length === 0}
256:           className="btn-primary"
257:           title={athletes.length === 0 ? "Ajoute d'abord un athlète au club" : undefined}
258:         >
259:           <Plus size={16} />
260:           Créer une compétition
261:         </button>
262:       </div>
263: 
264:       {/* ── KPIs ─────────────────────────────────────────────────────────── */}
265:       <div className="grid grid-cols-2 lg:grid-cols-4 gap-3 md:gap-4">
266:         {[
267:           { label: "Total saison",   value: stats.total,       color: "#378ADD", icon: CalendarDays },
268:           { label: "Passées",        value: stats.past,        color: "#94A3B8", icon: Clock        },
269:           { label: "À venir",        value: stats.upcoming,    color: "#1D9E75", icon: TrendingUp   },
270:           { label: "Avec résultats", value: stats.withResults, color: "#EF9F27", icon: Trophy       },
271:         ].map((s) => {
272:           const Icon = s.icon;
273:           return (
274:             <div key={s.label} className="card p-4 flex items-center gap-3">
275:               <div className="w-10 h-10 rounded-xl flex items-center justify-center flex-shrink-0" style={{ background: `${s.color}18` }}>
276:                 <Icon size={16} color={s.color} />
277:               </div>
278:               <div>
279:                 <p className="metric-value text-[var(--c-text-1)]">{s.value}</p>
280:                 <p className="meta-text mt-1">{s.label}</p>
281:               </div>
282:             </div>
283:           );
284:         })}
285:       </div>
286: 
287:       {/* ── Légende types ────────────────────────────────────────────────── */}
288:       <div className="flex flex-wrap gap-x-4 gap-y-2 text-[12px]" aria-label="Types de compétitions">
289:         {Object.entries(TYPE_CONFIG).map(([key, cfg]) => (
290:           <div key={key} className="flex items-center gap-1.5">
291:             <span className="w-3 h-3 rounded-full" style={{ background: cfg.dot }} />
292:             <span className="text-[var(--c-text-2)] font-medium">{cfg.label}</span>
293:           </div>
294:         ))}
295:       </div>
296: 
297:       {/* ── Timeline ─────────────────────────────────────────────────────── */}
298:       {competitionList.length === 0 ? (
299:         <div className="card px-5 py-16 text-center">
300:           <Trophy size={40} className="mx-auto mb-3 text-[var(--c-text-3)]" />
301:           <p className="text-[15px] font-semibold text-[var(--c-text-2)]">Aucune compétition programmée</p>
302:           <p className="meta-text mt-1">
303:             {athletes.length === 0
304:               ? "Ajoute d'abord un athlète au club pour pouvoir préparer son calendrier."
305:               : "Clique sur “Créer une compétition” pour démarrer le calendrier de saison."}
306:           </p>
307:         </div>
308:       ) : (
309:         <div>
310:           {/* Compétitions passées */}
311:           {pastComps.length > 0 && (
312:             <div className="mb-2">
313:               <div className="flex items-center gap-3 mb-4">
314:                 <div className="h-px flex-1 bg-[var(--c-border)]" />
315:                 <span className="metric-label px-2">
316:                   Compétitions passées
317:                 </span>
318:                 <div className="h-px flex-1 bg-[var(--c-border)]" />
319:               </div>
320:               <div>
321:                 {pastComps.map((c) => (
322:                   <CompCard
323:                     key={c.id}
324:                     competition={c}
325:                     athletes={athletes}
326:                     isPast={true}
327:                     isNext={false}
328:                     onClick={setSelectedComp}
329:                   />
330:                 ))}
331:               </div>
332:             </div>
333:           )}
334: 
335:           {/* Séparateur "Aujourd'hui" */}
336:           <div className="flex items-center gap-3 my-6">
337:             <div className="h-px flex-1 bg-[rgba(29,158,117,0.35)]" />
338:             <div className="flex items-center gap-2 bg-[rgba(29,158,117,0.15)] border border-[rgba(29,158,117,0.35)] rounded-full px-4 py-1.5">
339:               <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse" />
340:               <span className="text-[12px] font-semibold text-[var(--color-success)] uppercase tracking-wider">
341:                 Aujourd'hui · {new Date().toLocaleDateString("fr-BE", { day: "numeric", month: "long", year: "numeric" })}
342:               </span>
343:             </div>
344:             <div className="h-px flex-1 bg-[rgba(29,158,117,0.35)]" />
345:           </div>
346: 
347:           {/* Compétitions à venir */}
348:           {futureComps.length > 0 ? (
349:             <div>
350:               <div className="flex items-center gap-3 mb-4">
351:                 <div className="h-px flex-1 bg-[var(--c-border)]" />
352:                 <span className="metric-label px-2">
353:                   À venir
354:                 </span>
355:                 <div className="h-px flex-1 bg-[var(--c-border)]" />
356:               </div>
357:               {futureComps.map((c) => (
358:                 <CompCard
359:                   key={c.id}
360:                   competition={c}
361:                   athletes={athletes}
362:                   isPast={false}
363:                   isNext={c.id === nextComp?.id}
364:                   onClick={setSelectedComp}
365:                 />
366:               ))}
367:             </div>
368:           ) : (
369:             <div className="card p-10 text-center">
370:               <Trophy size={32} className="mx-auto mb-2 text-[var(--c-text-3)]" />
371:               <p className="text-[14px] font-semibold text-[var(--c-text-2)]">Aucune compétition à venir programmée</p>
372:             </div>
373:           )}
374:         </div>
375:       )}
376: 
377:       {/* ── Modals ───────────────────────────────────────────────────────── */}
378:       {liveSelectedComp && (
379:         <CompModal
380:           competition={liveSelectedComp}
381:           athletes={athletes}
382:           weeklyCharge={weeklyCharge}
383:           records={records}
384:           onClose={() => setSelectedComp(null)}
385:           onAddResult={addResult}
386:         />
387:       )}
388: 
389:       {showCreateModal && (
390:         <CreateCompModal
391:           athletes={athletes}
392:           onClose={() => setShowCreateModal(false)}
393:           onCreate={createCompetition}
394:         />
395:       )}
396:     </div>
397:   );
398: }
