400: export default memo(Competitions);  1: name: CI — quality gate
  2: 
  3: on:
  4:   push:
  5:     branches: [main]
  6:   pull_request:
  7:     branches: [main]
  8: 
  9: jobs:
 10:   quality-gate:
 11:     runs-on: ubuntu-latest
 12:     timeout-minutes: 60
 13:     defaults:
 14:       run:
 15:         working-directory: athleteos
 16:     steps:
 17:       - uses: actions/checkout@v4
 18: 
 19:       - uses: actions/setup-node@v4
 20:         with:
 21:           # @supabase/supabase-js initialise toujours un RealtimeClient à la
 22:           # création (même sans usage de Realtime), qui exige le WebSocket
 23:           # natif de Node — absent avant Node 22 ("Node.js detected but
 24:           # native WebSocket not found"), constaté lors d'un run CI (tâche 7).
 25:           node-version: 22
 26:           cache: npm
 27:           cache-dependency-path: athleteos/package-lock.json
 28: 
 29:       - run: npm ci
 30: 
 31:       # ── Portes de qualité rapides, sans base de données (tâche 19) ──────────
 32:       # lint -> typecheck -> tests unitaires + couverture -> build. Le premier
 33:       # échec arrête le job (npm run check s'arrête à la première commande en
 34:       # erreur) — feedback rapide avant de payer le coût de Supabase local.
 35:       - name: npm run check (lint, typecheck, tests unitaires + couverture, build)
 36:         env:
 37:           # Le premier quality gate tourne avant le démarrage de Supabase.
 38:           # Valeurs locales fictives requises uniquement à l'initialisation
 39:           # du SDK dans les tests ; aucune requête de production n'est faite.
 40:           VITE_SUPABASE_URL: http://127.0.0.1:54321
 41:           VITE_SUPABASE_ANON_KEY: unit-test-anon-key
 42:         run: npm run check
 43: 
 44:       - name: Conserver le rapport de couverture
 45:         if: always()
 46:         uses: actions/upload-artifact@v4
 47:         with:
 48:           name: coverage-report
 49:           path: athleteos/coverage
 50:           if-no-files-found: ignore
 51:           retention-days: 14
 52: 
 53:       # ══════════════════════════════════════════════════════════════════════
 54:       # À partir d'ici : instance Supabase locale et jetable (Docker, fournie
 55:       # par le runner) — rejoue TOUTES les migrations dans l'ordre, à partir
 56:       # d'une base vide. Ne touche jamais la production (tâche 7, DoD "ne
 57:       # touchent pas la production"). studio/imgproxy/mailpit/vector/logflare
 58:       # sont exclus. L'Edge Runtime reste actif car les suites signup,
 59:       # send-push et admin-actions testent les vraies fonctions locales.
 60:       # ══════════════════════════════════════════════════════════════════════
 61:       - uses: supabase/setup-cli@v2
 62:         with:
 63:           version: latest
 64:           # Recommandé par setup-cli v2 pour résoudre `latest` sans subir
 65:           # la limite très basse de l'API GitHub non authentifiée.
 66:           github-token: ${{ github.token }}
 67: 
 68:       - name: Start local Supabase (applique toutes les migrations)
 69:         shell: bash
 70:         run: |
 71:           # Conserver le journal complet et remonter les dernières lignes dans
 72:           # une annotation GitHub. Les annotations restent lisibles même quand
 73:           # l'accès au journal brut du job est restreint.
 74:           while IFS='=' read -r secret_name secret_value; do
 75:             export "$secret_name=$secret_value"
 76:           done < <(node ../.github/scripts/generate-test-vapid.mjs)
 77:           export SIGNUP_TEST_MODE=true
 78: 
 79:           set +e
 80:           supabase start -x studio,imgproxy,mailpit,vector,logflare --debug 2>&1 \
 81:             | tee "$RUNNER_TEMP/supabase-start.log"
 82:           start_status=${PIPESTATUS[0]}
 83:           set -e
 84: 
 85:           if [ "$start_status" -ne 0 ]; then
 86:             {
 87:               echo "### Échec du démarrage Supabase"
 88:               echo '```text'
 89:               tail -n 80 "$RUNNER_TEMP/supabase-start.log"
 90:               echo '```'
 91:             } >> "$GITHUB_STEP_SUMMARY"
 92: 
 93:             diagnostic=$(tail -n 40 "$RUNNER_TEMP/supabase-start.log")
 94:             diagnostic=${diagnostic//'%'/'%25'}
 95:             diagnostic=${diagnostic//$'\r'/'%0D'}
 96:             diagnostic=${diagnostic//$'\n'/'%0A'}
 97:             echo "::error title=Supabase local impossible à démarrer::$diagnostic"
 98:             exit "$start_status"
 99:           fi
100: 
101:       # Identifiants de l'instance locale — pas des secrets (clés de démo
102:       # fixes, base jetable détruite à la fin du job). `supabase status -o env`
103:       # sort des valeurs entre guillemets (NAME="value"), retirées avant
104:       # d'écrire dans $GITHUB_ENV. Réexporte aussi API_URL/ANON_KEY sous les
105:       # noms VITE_SUPABASE_* : Vite les embarque dans le bundle AU MOMENT DU
106:       # BUILD (import.meta.env), donc le rebuild plus bas doit les voir sous
107:       # ce nom précis, pas seulement sous le nom brut du CLI Supabase.
108:       - name: Export local Supabase credentials
109:         run: |
110:           supabase status -o env | sed 's/"//g' | grep -E '^[A-Z_]+=' >> "$GITHUB_ENV"
111:           echo "VITE_SUPABASE_URL=$(supabase status -o env | sed 's/"//g' | grep '^API_URL=' | cut -d= -f2-)" >> "$GITHUB_ENV"
112:           echo "VITE_SUPABASE_ANON_KEY=$(supabase status -o env | sed 's/"//g' | grep '^ANON_KEY=' | cut -d= -f2-)" >> "$GITHUB_ENV"
113:           echo "SUPABASE_SERVICE_ROLE_KEY=$(supabase status -o env | sed 's/"//g' | grep '^SERVICE_ROLE_KEY=' | cut -d= -f2-)" >> "$GITHUB_ENV"
114: 
115:       # ── Suite RLS : lancée deux fois de suite (tâche 7, vérification
116:       #    obligatoire) — la suite crée/nettoie ses propres fixtures à
117:       #    chaque exécution, un deuxième passage identique confirme qu'elle
118:       #    est déterministe et ne laisse rien traîner en base. ────────────
119:       - name: RLS regression suite (1/2)
120:         run: bash ../.github/scripts/run-with-diagnostics.sh rls-1 node test_rls_regression.mjs
121:       - name: RLS regression suite (2/2 — déterminisme)
122:         run: bash ../.github/scripts/run-with-diagnostics.sh rls-2 node test_rls_regression.mjs
123: 
124:       # ── Reste de la suite d'intégration (tâches 3, 2, 4, 16, 18, 14, 8, 12) —
125:       #    jamais câblée en CI jusqu'ici (nécessitait des secrets pointant
126:       #    la production, jamais configurés) : tourne désormais contre
127:       #    l'instance locale jetable ci-dessus, sans risque. ──────────────
128:       - name: Reste de la suite d'intégration (contre Supabase local)
129:         run: |
130:           integration_status=0
131:           for test_file in \
132:             test_signup_regression.mjs \
133:             test_send_push_regression.mjs \
134:             test_admin_actions.mjs \
135:             test_import_club_athletes.mjs \
136:             test_charge_model_parity.mjs \
137:             test_axis_model_parity.mjs \
138:             test_competition_transactions.mjs \
139:             test_private_storage.mjs \
140:             test_performance_normalization.mjs
141:           do
142:             bash ../.github/scripts/run-with-diagnostics.sh "$test_file" node "$test_file" \
143:               || integration_status=1
144:           done
145:           exit "$integration_status"
146: 
147:       # ── E2E (Playwright) : rebuild avec les identifiants Supabase LOCAUX
148:       #    (le 1er build, dans npm run check, utilisait des identifiants
149:       #    absents/vides — un smoke test suffit là-bas, pas besoin de
150:       #    Supabase). E2E_WITH_AUTH active global-setup.mjs, qui crée 2
151:       #    comptes réels (coach + athlète) sur cette instance locale. ────
152:       - name: Rebuild avec les identifiants Supabase locaux
153:         run: npm run build
154: 
155:       - name: Install Playwright browsers
156:         run: npx playwright install --with-deps chromium
157: 
158:       - name: E2E (parcours coach/athlète critiques)
159:         env:
160:           E2E_WITH_AUTH: "1"
161:         run: bash ../.github/scripts/run-with-diagnostics.sh e2e npm run test:e2e
162: 
163:       - name: Conserver les preuves Playwright
164:         if: always()
165:         uses: actions/upload-artifact@v4
166:         with:
167:           name: playwright-evidence
168:           path: |
169:             athleteos/playwright-report
170:             athleteos/test-results
171:           if-no-files-found: ignore
172:           retention-days: 14
173: 
174:       - name: Stop local Supabase
175:         if: always()
176:         run: supabase stop  1: // ============================================================
