 31:   const [loadError, setLoadError] = useState("");
 32:   const [rsvpDraft, setRsvpDraft] = useState(val?.rsvpStatus ?? null);
 33:   const [rsvpNote, setRsvpNote] = useState(val?.rsvpNote ?? "");
 34:   const [rsvpSaving, setRsvpSaving] = useState(false);
 35:   const [rsvpFeedback, setRsvpFeedback] = useState("");
 36: 
 37:   const submitRsvp = async () => {
 38:     if (!rsvpDraft || rsvpSaving) return;
 39:     setRsvpSaving(true);
 40:     setRsvpFeedback("");
 41:     try {
 42:       const submittedNote = rsvpDraft === "going" ? "" : rsvpNote.trim();
 43:       await onSetRsvp(session.id, athlete.id, rsvpDraft, submittedNote);
 44:       setRsvpFeedback("Réponse envoyée au coach.");
 45:     } catch {
 46:       setRsvpFeedback("La réponse n’a pas pu être envoyée. Réessaie.");
 47:     } finally {
 48:       setRsvpSaving(false);
 49:     }
 50:   };
 51: 
 52:   const submitRpe = (rpe) => {
 53:     const duration = Number(actualDuration);
 54:     if (!Number.isFinite(duration) || duration <= 0 || duration > 1440) {
 55:       setLoadError("Indique d’abord la durée réellement effectuée (entre 1 et 1 440 minutes).");
 56:       return;
