 62:   const dateStr = session.sessionDate
 63:     ? parseLocalDate(session.sessionDate.slice(0, 10)).toLocaleDateString("fr-BE", {
 64:         weekday: "long", day: "numeric", month: "long", year: "numeric",
 65:       })
