 70:   const canRespond = session.lifecycleStatus !== "completed" && session.sessionDate >= new Date().toISOString().slice(0, 10);
 71:   const labelStyle = { fontSize: 12, fontWeight: 700, color: "var(--c-text-2)", textTransform: "uppercase", letterSpacing: "0.07em", marginBottom: 12, display: "block" };
