 48: function readableAdminError(value, fallback = "Une erreur est survenue. Réessaie dans un instant.") {
 49:   const candidates = value && typeof value === "object"
 50:     ? [value.message, value.error, value.details, value.error_description]
 51:     : [value];
 52:   for (const candidate of candidates) {
 53:     if (typeof candidate === "string" && candidate.trim() && candidate !== "[object Object]") return candidate;
 54:     if (candidate && typeof candidate === "object" && typeof candidate.message === "string"
 55:       && candidate.message.trim() && candidate.message !== "[object Object]") return candidate.message;
 56:   }
 57:   return fallback;
 58: }
 59: const MAX_BRAND_IMAGE_SIZE = 5 * 1024 * 1024;
 60: 
 61: async function fileToBase64(file) {
 62:   const bytes = new Uint8Array(await file.arrayBuffer());
 63:   const chunks = [];
 64:   const chunkSize = 32_768;
 65:   for (let index = 0; index < bytes.length; index += chunkSize) {
 66:     chunks.push(String.fromCharCode(...bytes.subarray(index, index + chunkSize)));
 67:   }
 68:   return btoa(chunks.join(""));
 69: }
