145:         setSavedAccentColor(data.accentColor);
146:       })
147:       .catch(() => {
148:         if (active) setMessage({ type: "error", text: "Les informations du club n’ont pas pu être chargées." });
149:       })
150:       .finally(() => { if (active) setClubLoading(false); });
151:     return () => { active = false; };
152:   }, [clubId]);
