167:   useEffect(() => {
168:     const handleKeyDown = (event) => {
169:       if (event.key === "Escape") {
170:         event.preventDefault();
171:         requestClose();
172:         return;
173:       }
174:       if (event.key !== "Tab" || !dialogRef.current) return;
175: 
176:       const focusable = [...dialogRef.current.querySelectorAll(FOCUSABLE_SELECTOR)];
177:       if (!focusable.length) return;
178:       const first = focusable[0];
179:       const last = focusable[focusable.length - 1];
180:       if (event.shiftKey && document.activeElement === first) {
181:         event.preventDefault();
182:         last.focus();
183:       } else if (!event.shiftKey && document.activeElement === last) {
184:         event.preventDefault();
185:         first.focus();
186:       }
187:     };
188: 
189:     window.addEventListener("keydown", handleKeyDown);
190:     return () => window.removeEventListener("keydown", handleKeyDown);
191:   });
