193:   const callAdmin = useCallback(async (payload) => {
194:     const { data, error } = await supabase.functions.invoke("admin-actions", { body: payload });
195:     if (error) {
196:       if (error.context?.json) {
197:         try {
198:           const body = await error.context.json();
199:           if (body?.error) throw new Error(readableAdminError(body.error));
200:         } catch (contextError) {
201:           if (contextError instanceof Error && contextError.message !== "Unexpected end of JSON input") throw contextError;
202:         }
203:       }
204:       throw new Error(readableAdminError(error));
205:     }
206:     if (!data?.success) throw new Error(readableAdminError(data?.error));
207:     return data;
208:   }, []);
