 11: import { useState, useMemo, useEffect } from "react";
 12: import {
 13:   Plus, Trophy, Target, BarChart2, CheckCircle,
 14:   TrendingUp, TrendingDown, Minus, Activity, Flag, FileText, Sparkles,
 15: } from "lucide-react";
 16: import {
 17:   AreaChart, Area, XAxis, YAxis, Tooltip,
 18:   CartesianGrid, ResponsiveContainer,
 19:   ScatterChart, Scatter, ZAxis, ReferenceArea, ReferenceLine,
 20: } from "recharts";
 21: import { supabase } from "../../utils/supabaseClient";
 22: import { getDiscHib, isBetterOrEqual, parsePerf, toLocalDateStr, getISOWeek, pctOfReference } from "../shared";
 23: import {
 24:   createPerformanceMetadata, normalizePerformanceMetadata, resolveDisciplineId,
 25:   validatePerformanceMetadata,
 26: } from "../../domain/disciplines.js";
 27: import { notifyGoalAchieved, postClubCelebration, dispatchOutboxNotifications } from "../../utils/notifications";
 28: import { getAthleteMetricsForWeek } from "../../utils/chargeCalculations";
 29: import { parseLocalDate } from "../../utils/helpers";
 30: import MesRapports from "./MesRapports";
 31: import { COMBINE_EVENTS, discColor, performanceIndex } from "./perfsShared";
 32: import { ConfettiBurst, PerfTooltip, ProgressRing, RecordCard, GoalProgressBar } from "./PerfsWidgets";
 33: import AddPerfModal from "./AddPerfModal";
 34: import AddGoalModal from "./AddGoalModal";
 35: import AddCompModal from "./AddCompModal";
 36: import { SegmentedTabs } from "../../components/ui/premium";
 37: import PerformanceContextChips from "../../components/performance/PerformanceContextChips.jsx";
 38: 
 39: // ═══════════════════════════════════════════════════════════════════════════════
 40: // COMPOSANT PRINCIPAL
 41: // ═══════════════════════════════════════════════════════════════════════════════
 42: export default function AthletePerfs({ athlete, competitions, myPerformances, myGoals, clubId, weeklyCharge, sessions, onRefresh }) {
 43:   const today = new Date();
 44: 
 45:   const [activeTab,    setActiveTab]    = useState("records");
 46:   const [selectedDisc, setSelectedDisc] = useState(null);
 47:   const [showAddPerf,  setShowAddPerf]  = useState(false);
 48:   const [showAddGoal,  setShowAddGoal]  = useState(false);
 49:   const [savingPerf,   setSavingPerf]   = useState(false);
 50:   const [savingGoal,   setSavingGoal]   = useState(false);
 51:   const [showAddComp,  setShowAddComp]  = useState(false);
 52:   const [savingComp,   setSavingComp]   = useState(false);
 53:   const [showConfetti, setShowConfetti] = useState(false);
 54:   const [performanceError, setPerformanceError] = useState("");
 55:   const [compForm,     setCompForm]     = useState({
 56:     name: "", date: toLocalDateStr(new Date()),
 57:     location: "", type: "Régionale", event: "", result: "", context: "", breakdown: {}, metadata: createPerformanceMetadata(""),
 58:   });
 59: 
 60:   const [perfForm, setPerfForm] = useState({
 61:     discipline: "", value: "", performance_date: toLocalDateStr(today), context: "", breakdown: {}, metadata: createPerformanceMetadata(""),
 62:   });
 63:   const [goalForm, setGoalForm] = useState({
 64:     discipline: "", target_value: "", deadline: "", notes: "",
 65:   });
 66: 
 67:   const [localPerfs, setLocalPerfs] = useState(myPerformances ?? []);
 68:   const [localGoals, setLocalGoals] = useState(myGoals ?? []);
 69: 
 70:   useEffect(() => { setLocalPerfs(myPerformances ?? []); }, [myPerformances]);
 71:   useEffect(() => { setLocalGoals(myGoals ?? []);        }, [myGoals]);
 72: 
 73:   const disciplines = useMemo(() => Object.keys(athlete.records ?? {}), [athlete.records]);
 74: 
 75:   useEffect(() => {
 76:     if (!selectedDisc && disciplines.length > 0) setSelectedDisc(disciplines[0]);
 77:   }, [selectedDisc, disciplines]);
 78: 
 79:   const chartData = useMemo(() => {
 80:     const disc = selectedDisc ?? disciplines[0];
 81:     if (!disc) return [];
 82:     const reference = parsePerf(athlete.records?.[disc]?.pr).value;
 83:     return localPerfs
 84:       .filter(p => p.discipline === disc && p.value != null)
 85:       .sort((a, b) => a.performance_date.localeCompare(b.performance_date))
 86:       .map(p => {
 87:         // Tâche 12 : préfère la valeur canonique déjà stockée (normalized_value)
 88:         // à un parseFloat brut, qui donnait un résultat faux sur un format
 89:         // "minutes:secondes" ("1:52" -> 1 au lieu de 112) — fallback sur
 90:         // parsePerf() pour les lignes pas encore backfillées.
 91:         const value = p.normalized_value ?? parsePerf(p.value).value ?? 0;
 92:         const score = performanceIndex(value, reference, disc) ?? value;
 93:         return {
 94:           date: p.performance_date.slice(0, 10),
 95:           label: parseLocalDate(p.performance_date.slice(0, 10)).toLocaleDateString("fr-BE", { day: "numeric", month: "short" }),
 96:           value,
 97:           score,
 98:           raw: p.value,
 99:           ctx: p.context,
100:           breakdown: p.breakdown,
101:         };
102:       });
103:   }, [localPerfs, selectedDisc, disciplines, athlete.records]);
104: 
105:   // Zone ombrée entre le PR actuel et l'objectif visé sur la discipline
106:   // affichée — visualise d'un coup d'œil l'écart qu'il reste à combler.
107:   const goalZone = useMemo(() => {
108:     const disc = selectedDisc ?? disciplines[0];
109:     if (!disc) return null;
110:     const goal = localGoals.find(g => !g.achieved && g.discipline === disc);
111:     if (!goal) return null;
112:     const targetValue = parsePerf(goal.target_value).value;
113:     if (targetValue == null) return null;
114:     const rec   = athlete.records?.[disc];
115:     const prValue = rec?.pr ? parsePerf(rec.pr).value : null;
116:     if (prValue == null || prValue === 0) return null;
117:     const targetScore = performanceIndex(targetValue, prValue, disc);
118:     if (targetScore == null) return null;
119:     return { target: targetScore, y1: Math.min(100, targetScore), y2: Math.max(100, targetScore) };
120:   }, [selectedDisc, disciplines, localGoals, athlete.records]);
121: 
122:   const compHistory = useMemo(() => {
123:     const all = [];
124:     (competitions ?? []).forEach(c => {
125:       if (!c.athleteIds?.includes(athlete.id)) return;
126:       (c.results ?? []).filter(r => r.athleteId === athlete.id).forEach(r => {
127:         all.push({ comp: c, result: r });
128:       });
129:     });
130:     return all.sort((a, b) => new Date(b.comp.date) - new Date(a.comp.date));
131:   }, [competitions, athlete.id]);
132: 
133:   // Variation de la moyenne quotidienne 7 j vs 28 j au moment de chaque
134:   // compétition. Relation descriptive uniquement, sans causalité supposée.
135:   const chargeVsPerfData = useMemo(() => {
136:     if (!selectedDisc || !weeklyCharge?.length) return [];
137:     const rec = athlete.records?.[selectedDisc];
138:     if (!rec?.pr) return [];
139:     const prP = parsePerf(rec.pr);
140:     if (prP.value == null) return [];
141:     const hib = getDiscHib(selectedDisc);
142:     return compHistory
143:       .filter(({ result }) => result.event === selectedDisc)
144:       .map(({ comp, result }) => {
145:         const resP = parsePerf(result.result);
146:         if (resP.value == null || prP.value === 0) return null;
147:         const pct = hib
148:           ? Math.min(105, Math.round((resP.value / prP.value) * 1000) / 10)
149:           : Math.min(105, Math.round((prP.value / resP.value) * 1000) / 10);
150:         const week    = getISOWeek(parseLocalDate(comp.date.slice(0, 10)));
151:         const metrics = getAthleteMetricsForWeek(athlete.id, weeklyCharge, week, [], [], comp.date);
152:         if (metrics.variationPercent == null) return null;
153:         return { x: metrics.variationPercent, y: pct, compName: comp.name, date: comp.date, resultStr: result.result };
154:       })
155:       .filter(Boolean);
156:   }, [compHistory, selectedDisc, athlete.id, athlete.records, weeklyCharge]);
157: 
158:   // Tâche 11 : "meilleure" performance déterminée via le moteur central
159:   // (isBetterOrEqual, qui consulte getDiscHib) — avant ce fix, un simple
160:   // "v > best.v" retenait systématiquement la plus grande valeur, ce qui
161:   // est faux pour toute discipline chronométrée (un 12.50 aurait été
162:   // "meilleur" qu'un 11.00 sur 100m).
163:   const disciplineStats = useMemo(() => {
164:     const map = {};
165:     localPerfs.forEach(p => {
166:       if (!map[p.discipline]) map[p.discipline] = { count: 0, best: null, last: null, series: [] };
167:       map[p.discipline].count++;
168:       const v = parsePerf(p.value).value;
169:       if (v != null) {
170:         map[p.discipline].series.push({ value: v, date: p.performance_date, raw: p.value });
171:         if (!map[p.discipline].best || isBetterOrEqual(v, map[p.discipline].best.v, p.discipline))
172:           map[p.discipline].best = { v, date: p.performance_date, raw: p.value };
173:         map[p.discipline].last = { v, date: p.performance_date, raw: p.value };
174:       }
175:     });
176:     Object.values(map).forEach(stats => {
177:       stats.series.sort((a, b) => a.date.localeCompare(b.date));
178:       stats.last = stats.series.at(-1) ?? null;
179:     });
180:     return map;
181:   }, [localPerfs]);
182: 
183:   const activeGoals   = localGoals.filter(g => !g.achieved);
184:   const achievedGoals = localGoals.filter(g =>  g.achieved);
185: 
186:   // ── Handlers ───────────────────────────────────────────────────────────
187:   const handleAddPerf = async () => {
188:     if (!perfForm.discipline.trim() || !perfForm.value.trim()) return;
189:     setPerformanceError("");
190:     setSavingPerf(true);
191:     try {
192:       // Tâche 9 : normalise un alias saisi librement ("100 m" -> "100m")
193:       // vers l'identifiant canonique avant d'écrire en base — une
194:       // discipline personnalisée qui ne correspond à rien de connu passe
195:       // telle quelle (trim uniquement), le registre officiel n'est jamais
196:       // pollué par une saisie libre.
197:       const disc = resolveDisciplineId(perfForm.discipline);
198:       const isCombine = !!COMBINE_EVENTS[disc];
199:       const cleanBreakdown = isCombine
200:         ? Object.fromEntries(Object.entries(perfForm.breakdown).filter(([, v]) => v?.trim()))
201:         : null;
202:       // Tâche 12 : valeur canonique + unité + discipline résolue, calculées
203:       // ici (le client reste la seule source de vérité pour le parsing,
204:       // tâche 11) — une valeur non interprétable est quand même enregistrée
205:       // (on ne bloque pas la saisie manuelle d'un athlète) mais marquée pour
206:       // ne pas fausser silencieusement un tri/calcul ultérieur.
207:       const normalizedValue = parsePerf(perfForm.value).value;
208:       if (normalizedValue == null) throw new Error("Le résultat doit contenir une valeur numérique valide.");
209:       const metadata = normalizePerformanceMetadata(disc, perfForm.metadata);
210:       const metadataIssues = validatePerformanceMetadata(disc, metadata);
211:       if (metadataIssues.length) throw new Error(metadataIssues[0]);
212: 
213:       const { data, error } = await supabase.rpc("add_athlete_performance", {
214:         p_discipline: disc,
215:         p_value: perfForm.value.trim(),
216:         p_result_value: normalizedValue,
217:         p_performance_date: perfForm.performance_date,
218:         p_context: perfForm.context || null,
219:         p_breakdown: cleanBreakdown && Object.keys(cleanBreakdown).length ? cleanBreakdown : null,
220:         p_metadata: metadata,
221:         p_idempotency_key: crypto.randomUUID(),
222:       });
223:       if (error) throw error;
224:       setLocalPerfs(prev => [...prev, {
225:         id: data?.performanceId, athlete_id: athlete.id, club_id: clubId,
226:         discipline: disc, discipline_type: disc, value: perfForm.value,
227:         performance_date: perfForm.performance_date, context: perfForm.context || null,
228:         breakdown: cleanBreakdown, normalized_value: normalizedValue, ...metadata,
229:       }]);
230:       if (data?.isNewRecord) {
231:         setShowConfetti(true);
232:         postClubCelebration(
233:           clubId,
234:           athlete.id,
235:           "record",
236:           `${athlete.name.split(" ")[0]} a battu son record en ${disc} : ${perfForm.value} !`,
237:         ).catch(console.warn);
238:       }
239: 
240:       // Bascule l'onglet Évolution sur la discipline qu'on vient de saisir —
241:       // sinon elle reste affichée sur l'ancienne sélection et la nouvelle
242:       // discipline ajoutée (ex: Décathlon) semble "ne rien afficher" alors
243:       // qu'elle est bien enregistrée, juste pas sélectionnée.
244:       setSelectedDisc(disc);
245: 
246:       setPerfForm({ discipline: disc, value: "", performance_date: toLocalDateStr(today), context: "", breakdown: {}, metadata: createPerformanceMetadata(disc) });
247:       setShowAddPerf(false);
248:       onRefresh?.();
249:     } catch (e) {
250:       console.error("Erreur ajout perf:", e);
251:       setPerformanceError(e.message ?? "Impossible d'enregistrer la performance.");
252:     } finally {
253:       setSavingPerf(false);
254:     }
255:   };
256: 
257:   const handleAddGoal = async () => {
258:     if (!goalForm.discipline.trim() || !goalForm.target_value.trim()) return;
259:     setSavingGoal(true);
260:     try {
261:       const { data, error } = await supabase
262:         .from("athlete_goals")
263:         .insert({
264:           athlete_id:   athlete.id,
265:           club_id:      clubId,
266:           discipline:   resolveDisciplineId(goalForm.discipline), // tâche 9 : alias -> id canonique
267:           target_value: goalForm.target_value,
268:           deadline:     goalForm.deadline || null,
269:           description:  goalForm.notes || null,
270:           achieved:     false,
271:         })
272:         .select().single();
273:       if (error) throw error;
274:       setLocalGoals(prev => [data, ...prev]);
275:       setGoalForm({ discipline: "", target_value: "", deadline: "", notes: "" });
276:       setShowAddGoal(false);
277:       onRefresh?.();
278:     } catch (e) {
279:       console.error("Erreur ajout objectif:", e);
280:     } finally {
281:       setSavingGoal(false);
282:     }
283:   };
284: 
285:   const handleMarkGoalDone = async (goalId) => {
286:     const goal = localGoals.find(g => g.id === goalId);
287:     setLocalGoals(prev => prev.map(g => g.id === goalId ? { ...g, achieved: true } : g));
288:     await supabase.from("athlete_goals").update({ achieved: true }).eq("id", goalId);
289:     if (goal) {
290:       notifyGoalAchieved(clubId, athlete.id, goal.discipline, goal.target_value).catch(console.warn);
291:       postClubCelebration(clubId, athlete.id, "goal",
292:         `${athlete.name.split(" ")[0]} a atteint son objectif en ${goal.discipline} : ${goal.target_value} !`).catch(console.warn);
293:     }
294:     onRefresh?.();
295:   };
296: 
297:   const handleDeleteGoal = async (goalId) => {
298:     setLocalGoals(prev => prev.filter(g => g.id !== goalId));
299:     await supabase.from("athlete_goals").delete().eq("id", goalId);
300:     onRefresh?.();
301:   };
302: 
303:   const handleDeletePerf = async (perfId) => {
304:     setLocalPerfs(prev => prev.filter(p => p.id !== perfId));
305:     await supabase.from("athlete_performances").delete().eq("id", perfId);
306:   };
307: 
308:   // Tâche 14 : un seul appel RPC atomique (create_solo_competition_result)
309:   // au lieu de jusqu'à 5 écritures successives (compétition, lien,
310:   // résultat, performance, record) — avant, une panne entre deux étapes
311:   // laissait par exemple une compétition sans aucun résultat, ou un
312:   // résultat enregistré sans que le record ne soit mis à jour. La
313:   // comparaison/mise à jour du record est aussi verrouillée côté serveur
314:   // contre deux soumissions concurrentes qui battraient le même record.
315:   const handleAddComp = async () => {
316:     if (!compForm.name.trim() || !compForm.date || !compForm.event.trim() || !compForm.result.trim()) return;
317:     setPerformanceError("");
318:     setSavingComp(true);
319:     try {
320:       // Tâche 9 : normalise un alias saisi librement avant d'écrire en base.
321:       const event = resolveDisciplineId(compForm.event);
322:       const isCombine = !!COMBINE_EVENTS[event];
323:       const cleanBreakdown = isCombine
324:         ? Object.fromEntries(Object.entries(compForm.breakdown).filter(([, v]) => v?.trim()))
325:         : null;
326:       const normalizedValue = parsePerf(compForm.result).value;
327:       if (normalizedValue == null) throw new Error("Le résultat doit contenir une valeur numérique valide.");
328:       const metadata = normalizePerformanceMetadata(event, compForm.metadata);
329:       const metadataIssues = validatePerformanceMetadata(event, metadata);
330:       if (metadataIssues.length) throw new Error(metadataIssues[0]);
331: 
332:       const { data, error } = await supabase.rpc("create_solo_competition_result_v2", {
333:         p_name:             compForm.name.trim(),
334:         p_date:             compForm.date,
335:         p_location:         compForm.location || null,
336:         p_type:             compForm.type,
337:         p_event:            event,
338:         p_result:           compForm.result,
339:         p_result_value:     normalizedValue,
340:         p_higher_is_better: metadata.performance_direction === "higher",
341:         p_context:          compForm.context || null,
342:         p_idempotency_key:  crypto.randomUUID(),
343:         p_breakdown:        cleanBreakdown && Object.keys(cleanBreakdown).length ? cleanBreakdown : null,
344:         p_unit:             metadata.unit,
345:         p_metadata:         metadata,
346:       });
347:       if (error) throw error;
348: 
349:       // Reflète tout de suite le nouveau résultat dans l'onglet Évolution
350:       // (le rafraîchissement complet via onRefresh arrive juste après,
351:       // mais ceci évite un flash "vide" en attendant).
352:       if (data?.performanceId) {
353:         setLocalPerfs(prev => [...prev, {
354:           id: data.performanceId, athlete_id: athlete.id, club_id: clubId,
355:           discipline: event, discipline_type: event, value: compForm.result,
356:           performance_date: compForm.date, context: compForm.name.trim(),
357:           breakdown: cleanBreakdown && Object.keys(cleanBreakdown).length ? cleanBreakdown : null,
358:           normalized_value: normalizedValue, ...metadata,
359:         }]);
360:       }
361:       if (data?.isNewRecord) setShowConfetti(true);
362: 
363:       await dispatchOutboxNotifications(data?.notifications);
364: 
365:       // Idem que pour "Saisir une performance" : bascule Évolution sur la
366:       // discipline qu'on vient d'ajouter, sinon elle reste sur l'ancienne
367:       // sélection et semble vide alors qu'elle est bien enregistrée.
368:       setSelectedDisc(event);
369: 
370:       setCompForm({ name: "", date: toLocalDateStr(new Date()), location: "", type: "Régionale", event: "", result: "", context: "", breakdown: {}, metadata: createPerformanceMetadata("") });
371:       setShowAddComp(false);
372:       onRefresh?.();
373:     } catch (e) {
374:       console.error("Erreur ajout compétition:", e);
375:       setPerformanceError(e.message ?? "Impossible d'enregistrer la compétition.");
376:     } finally {
377:       setSavingComp(false);
378:     }
379:   };
380: 
381:   const PERF_TABS = [
382:     { id: "records",   label: "Records", icon: Trophy },
383:     { id: "evolution", label: "Évolution", icon: Activity },
384:     { id: "objectifs", label: activeGoals.length > 0 ? `Objectifs (${activeGoals.length})` : "Objectifs", icon: Target },
385:     { id: "comps",     label: "Compétitions", icon: Flag },
386:     { id: "rapports",  label: "Rapports", icon: FileText },
387:   ];
388: 
389:   // ══════════════════════════════════════════════════════════════════════════
390:   return (
391:     <div className="p-4 md:p-6 space-y-6 max-w-5xl mx-auto animate-slide-up">
392: 
393:       <section className="card" style={{ position: "relative", overflow: "hidden", padding: 20, background: "linear-gradient(145deg, rgba(var(--club-accent-rgb, 29, 158, 117), 0.11), var(--c-surface) 48%, rgba(91,158,245,0.05))" }}>
394:         <div aria-hidden="true" style={{ position: "absolute", width: 260, height: 260, right: -110, top: -150, borderRadius: "50%", background: "radial-gradient(circle, rgba(var(--club-accent-rgb, 29, 158, 117), 0.16), transparent 68%)" }} />
395:         <div style={{ position: "relative", display: "flex", alignItems: "flex-start", justifyContent: "space-between", gap: 16, flexWrap: "wrap" }}>
396:           <div style={{ minWidth: 0 }}>
397:             <div style={{ display: "inline-flex", alignItems: "center", gap: 6, padding: "4px 9px", borderRadius: 99, background: "rgba(29,158,117,0.10)", border: "1px solid rgba(77,201,160,0.18)", marginBottom: 12 }}>
398:               <Sparkles size={13} color="#7BD8B4" aria-hidden="true" />
399:               <span style={{ fontSize: 12, fontWeight: 700, color: "var(--tone-success)", letterSpacing: "0.05em", textTransform: "uppercase" }}>Performance lab</span>
400:             </div>
401:             <h1 className="page-title">Mes performances</h1>
402:             <p style={{ fontSize: 13, lineHeight: 1.5, color: "var(--c-text-2)", marginTop: 6 }}>
403:               Lis ta progression, comprends tes tendances et transforme chaque mesure en repère.
404:             </p>
405:           </div>
406:           <button type="button" onClick={() => { setPerformanceError(""); setShowAddPerf(true); }} className="btn-primary" style={{ flexShrink: 0 }}>
407:             <Plus size={16} aria-hidden="true" /> Saisir une performance
408:           </button>
409:         </div>
410: 
411:         <div style={{ position: "relative", display: "grid", gridTemplateColumns: "repeat(3, minmax(0, 1fr))", marginTop: 20, paddingTop: 16, borderTop: "1px solid var(--c-border)" }}>
412:           {[
413:             { value: disciplines.length, label: "Records suivis" },
414:             { value: localPerfs.length, label: "Mesures" },
415:             { value: activeGoals.length, label: "Objectifs actifs" },
416:           ].map((item, index) => (
417:             <div key={item.label} style={{ paddingInline: index === 0 ? 0 : 16, borderLeft: index === 0 ? "none" : "1px solid var(--c-border)" }}>
418:               <p style={{ fontSize: 22, fontWeight: 700, lineHeight: 1, color: "var(--c-text-1)", fontVariantNumeric: "tabular-nums" }}>{item.value}</p>
419:               <p style={{ fontSize: 12, color: "var(--c-text-2)", marginTop: 6 }}>{item.label}</p>
420:             </div>
421:           ))}
422:         </div>
423:       </section>
424: 
425:       {/* ── TAB BAR ──────────────────────────────────────────────────────────── */}
426:       <SegmentedTabs
427:         className="aos-segmented-tabs--fill"
428:         ariaLabel="Sections des performances"
429:         items={PERF_TABS.map((tab) => ({
430:           ...tab,
431:           tabId: `athlete-perfs-tab-${tab.id}`,
432:           panelId: "athlete-perfs-panel",
433:         }))}
434:         value={activeTab}
435:         onChange={setActiveTab}
436:       />
437: 
438:       {/* key={activeTab} force un remount à chaque changement d'onglet, ce qui
439:           déclenche .view-transition (fondu+glissement) au lieu d'un switch
440:           instantané — évite l'effet "ça saute" en cliquant sur les tabs. */}
441:       <div
442:         key={activeTab}
443:         id="athlete-perfs-panel"
444:         role="tabpanel"
445:         aria-labelledby={`athlete-perfs-tab-${activeTab}`}
446:         className="view-transition"
447:       >
448:       {/* ══════════════════════════════════════════════════════════════════════
449:           ONGLET RECORDS
450:          ══════════════════════════════════════════════════════════════════════ */}
451:       {activeTab === "records" && (
