628:                         const hi = goalZone ? Math.max(max, goalZone.y2) : max;
629:                         const padding = Math.max(1.5, (hi - lo) * 0.14);
630:                         return [Math.floor(lo - padding), Math.ceil(hi + padding)];
631:                       }}
632:                       tickCount={5} />
633:                     <Tooltip content={<PerfTooltip />} />
634:                     {goalZone && (
