665:               <ResponsiveContainer width="100%" height={260}>
666:                 <ScatterChart margin={{ top: 12, right: 16, bottom: 12, left: 0 }}>
667:                   <CartesianGrid vertical={false} stroke="rgba(255,255,255,0.07)" />
668:                   <XAxis dataKey="x" type="number" domain={([min, max]) => [Math.min(-20, min), Math.max(20, max)]} tickFormatter={value => `${value}%`} tick={{ fontSize: 12, fill: "var(--c-text-3)" }} axisLine={false} tickLine={false} />
669:                   <YAxis dataKey="y" type="number" domain={[70, 105]} tickFormatter={value => `${value}%`} tick={{ fontSize: 12, fill: "var(--c-text-3)" }} axisLine={false} tickLine={false} width={46} />
670:                   <ZAxis range={[90, 90]} />
671:                   <Tooltip content={({ active, payload }) => {
672:                     if (!active || !payload?.length) return null;
673:                     const d = payload[0].payload;
