678:                         <p style={{ fontSize: 12, color: "var(--c-text-2)" }}>Résultat : <strong style={{ color: "var(--tone-success)" }}>{d.resultStr}</strong></p>
679:                         <p style={{ fontSize: 12, color: "var(--c-text-2)", marginTop: 3 }}>Écart à l'habitude : <strong>{d.x >= 0 ? "+" : ""}{d.x}%</strong> · Niveau : <strong>{d.y}% du record</strong></p>
680:                       </div>
681:                     );
682:                   }} />
683:                   <Scatter data={chargeVsPerfData} fill="#1D9E75" shape={(props) => {
684:                     const { cx, cy, payload } = props;
685:                     const col = payload.y >= 95 ? "#1D9E75" : payload.y >= 85 ? "#E8A020" : "#E05252";
686:                     return (
687:                       <g>
688:                         <circle cx={cx} cy={cy} r={10} fill={col} fillOpacity={0.13} />
689:                         <circle cx={cx} cy={cy} r={5.5} fill={col} fillOpacity={0.94} stroke="var(--c-surface)" strokeWidth={2} />
690:                       </g>
691:                     );
692:                   }} />
693:                 </ScatterChart>
694:               </ResponsiveContainer>
695:               <div style={{ display: "flex", alignItems: "center", gap: 8, marginTop: 12, fontSize: 12, color: "var(--c-text-2)" }}>
696:                 <span style={{ width: 10, height: 10, borderRadius: 3, background: "rgba(29,158,117,0.16)", border: "1px solid rgba(29,158,117,0.35)" }} />
697:                 <span>Chaque point relie une compétition à la charge observée avant celle-ci. Le graphique montre une relation possible, pas une zone idéale ni une cause.</span>
698:               </div>
699:             </div>
700:           )}
701: 
702:           {chartData.length > 0 && (
703:             <div className="card overflow-hidden">
704:               <div style={{ padding: 16, display: "flex", alignItems: "center", justifyContent: "space-between", gap: 12, borderBottom: "1px solid var(--c-border)" }}>
705:                 <p style={{ fontSize: 14, fontWeight: 700, color: "var(--c-text-1)" }}>
706:                   Toutes les mesures — {selectedDisc}
707:                 </p>
708:                 <span style={{ fontSize: 12, color: "var(--c-text-2)", flexShrink: 0 }}>{chartData.length} entrée{chartData.length > 1 ? "s" : ""}</span>
709:               </div>
710:               <div style={{ maxHeight: 320, overflowY: "auto" }}>
711:                 {[...localPerfs].filter(p => p.discipline === selectedDisc).sort((a,b) => b.performance_date.localeCompare(a.performance_date)).map((p, i) => (
712:                   <div key={p.id} className="group" style={{ padding: 16, display: "flex", alignItems: "center", justifyContent: "space-between", gap: 12, borderTop: i > 0 ? "1px solid var(--c-border)" : "none" }}>
