730:                       </p>
731:                       <button
732:                         type="button"
733:                         aria-label={`Supprimer la performance ${p.value}`}
734:                         onClick={() => handleDeletePerf(p.id)}
735:                         className="tap-feedback"
736:                         style={{ minHeight: 40, padding: "0 10px", borderRadius: 10, background: "rgba(224,82,82,0.08)", border: "1px solid rgba(224,82,82,0.12)", cursor: "pointer", color: "var(--tone-danger)", fontSize: 12, fontWeight: 700 }}>
737:                         Supprimer
738:                       </button>
739:                     </div>
740:                   </div>
741:                 ))}
742:               </div>
743:             </div>
