747: 
748:       {/* ══════════════════════════════════════════════════════════════════════
749:           ONGLET OBJECTIFS
750:          ══════════════════════════════════════════════════════════════════════ */}
751:       {activeTab === "objectifs" && (
752:         <div className="space-y-5">
753:           <div className="flex items-end justify-between gap-4">
754:             <div>
755:               <h2 className="section-title">Objectifs</h2>
756:               <p style={{ fontSize: 13, color: "var(--c-text-2)", marginTop: 4 }}>Des repères concrets entre ton niveau actuel et ta prochaine étape.</p>
757:             </div>
758:             <button type="button" onClick={() => setShowAddGoal(true)} className="btn-primary">
759:               <Plus size={16} aria-hidden="true" /> Ajouter
760:             </button>
761:           </div>
762: 
763:           {activeGoals.length === 0 && achievedGoals.length === 0 ? (
764:             <div className="card p-12 text-center">
765:               <div style={{ width: 56, height: 56, borderRadius: 18, display: "flex", alignItems: "center", justifyContent: "center", margin: "0 auto 14px", background: "rgba(234,179,8,0.10)" }}>
766:                 <Target size={26} color="#EAB308" strokeWidth={1.5} />
767:               </div>
768:               <p style={{ fontSize: 15, fontWeight: 700, color: "var(--c-text-1)" }}>Aucun objectif défini</p>
769:               <p style={{ fontSize: 13, color: "var(--c-text-2)", marginTop: 4 }}>Fixe-toi une prochaine étape pour guider ta progression.</p>
770:               <button type="button" onClick={() => setShowAddGoal(true)} className="btn-primary" style={{ marginTop: 20, marginInline: "auto" }}>
771:                 <Plus size={16} aria-hidden="true" /> Définir un objectif
772:               </button>
773:             </div>
774:           ) : (
775:             <>
776:               {activeGoals.length > 0 && (
777:                 <div className="space-y-3">
778:                   <p style={{ fontSize: 12, fontWeight: 700, color: "var(--c-text-2)", textTransform: "uppercase", letterSpacing: "0.07em" }}>
779:                     En cours ({activeGoals.length})
780:                   </p>
781:                   {activeGoals.map(g => {
782:                     const daysLeft = g.deadline
783:                       ? Math.round((parseLocalDate(g.deadline.slice(0, 10)) - today) / (1000 * 60 * 60 * 24))
784:                       : null;
785:                     const isUrgent = daysLeft !== null && daysLeft <= 14;
786:                     const col      = discColor(g.discipline);
787:                     const pr  = athlete.records?.[g.discipline]?.pr;
788:                     // Tâche 11 : parsePerf (pas parseFloat, qui tronque "4:32" à 4)
789:                     // + pctOfReference (pas un ratio PR/target écrit à la main, faux
790:                     // sens pour un objectif chronométré plus rapide que le PR).
791:                     const prN  = parsePerf(pr).value;
792:                     const tgN  = parsePerf(g.target_value).value;
793:                     const pct  = pctOfReference(prN, tgN, g.discipline);
794: 
795:                     return (
796:                       <div key={g.id} className="card" style={{ display: "flex", gap: 16, alignItems: "flex-start", padding: 20 }}>
797:                         <ProgressRing pct={pct} color={isUrgent ? "#EAB308" : col} size={56} stroke={4} />
798:                         <div style={{ flex: 1, minWidth: 0 }}>
799:                           <div style={{ display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap", marginBottom: 4 }}>
800:                             <p style={{ fontSize: 15, fontWeight: 700, color: "var(--c-text-1)" }}>{g.discipline}</p>
801:                             {daysLeft !== null && (
802:                               <span style={{ fontSize: 12, fontWeight: 700, padding: "4px 9px", borderRadius: 99, background: isUrgent ? "rgba(234,179,8,0.14)" : "var(--c-surface-2)", color: isUrgent ? "#F0CB61" : "var(--c-text-2)" }}>
803:                                 {daysLeft > 0 ? `J-${daysLeft}` : daysLeft === 0 ? "Aujourd'hui !" : "Échu"}
804:                               </span>
805:                             )}
