 15: const SessionModal = memo(({
 16:   session, athletes, onClose, onEditRequest, onDeleteSession,
 17:   onSetCoachNote, onSetLifecycle, onRemindFeedback,
 18: }) => {
 19:   const [deleting,    setDeleting]    = useState(false);
 20:   const [deleteError, setDeleteError] = useState(null);
 21:   const [confirmDel,  setConfirmDel]  = useState(false);
 22:   const { dialogRef, titleId } = useAccessibleDialog({ onClose, closeDisabled: deleting });
 23:   const c      = colors(session.category);
 24:   const trainingFocus = getSessionTrainingFocus(session);
 25:   const status = sessionStatus(session);
 26: 
 27:   const dateStr = session.sessionDate
 28:     ? new Date(session.sessionDate).toLocaleDateString("fr-BE", { weekday: "long", day: "numeric", month: "long", year: "numeric" })
 29:     : `${session.day} · S${session.week}`;
 30: 
 31:   const handleDelete = async () => {
 32:     setDeleting(true);
 33:     try { await onDeleteSession(session.id); onClose(); }
 34:     catch { setDeleteError("Impossible de supprimer."); setDeleting(false); }
 35:   };
 36: 
 37:   return (
 38:     <div
 39:       className="fixed inset-0 z-50 flex items-end sm:items-center justify-center sm:p-4 modal-backdrop"
 40:       onClick={e => e.target === e.currentTarget && !deleting && onClose()}
 41:     >
 42:       <div ref={dialogRef} role="dialog" aria-modal="true" aria-labelledby={titleId} tabIndex={-1}
 43:         className="rounded-t-3xl sm:rounded-3xl shadow-2xl w-full sm:max-w-lg max-h-[95vh] sm:max-h-[90vh] flex flex-col overflow-hidden modal-content"
 44:         style={{ background: "var(--c-surface)" }}>
 45: 
 46:         {/* Handle mobile */}
 47:         <div className="flex justify-center pt-3 pb-1 sm:hidden flex-shrink-0">
 48:           <div className="w-10 h-1 rounded-full" style={{ background: "var(--c-border-strong)" }} />
 49:         </div>
 50: 
 51:         {/* Header coloré — fill faible opacité, pas de blanc */}
 52:         <div
 53:           className="px-6 py-5 flex items-start justify-between gap-4 flex-shrink-0"
 54:           style={{ background: `${c.border}14`, borderBottom: `2px solid ${c.border}40` }}
 55:         >
 56:           <div className="flex-1 min-w-0">
 57:             <div className="flex items-center gap-2 mb-2 flex-wrap">
 58:               <span
 59:                 className="text-[12px] font-bold uppercase tracking-wide px-2.5 py-1 rounded-full"
 60:                 style={{ background: c.border, color: "#0A150F" }}
 61:               >
 62:                 {CATEGORIES.find(x => x.id === session.category)?.label ?? session.type}
 63:               </span>
 64:               <span className="text-[12px] font-semibold px-2.5 py-1 rounded-full" style={{ background: "rgba(255,255,255,0.06)", border: "1px solid var(--c-border)", color: "var(--c-text-1)" }}>
 65:                 Objectif · {trainingFocus.shortLabel}
 66:               </span>
 67:               {session.createdByAthlete && (
 68:                 <span className="text-[12px] font-bold px-2 py-0.5 rounded-full"
 69:                   style={{ background: "rgba(168,85,247,0.16)", color: "var(--tone-mental)" }}>
 70:                   📋 Proposé par un athlète
 71:                 </span>
 72:               )}
 73:               <StatusIcon status={status} size={14} />
 74:             </div>
 75:             <h2 id={titleId} className="text-[20px] font-bold leading-tight" style={{ color: c.text }}>
 76:               {session.title}
 77:             </h2>
 78:             <p className="text-[12px] mt-1.5 font-medium" style={{ color: "var(--c-text-2)" }}>
 79:               📅 {dateStr}
 80:               {session.time && ` · ⏰ ${session.time}`}
 81:               {session.durationMinutes && ` · ${session.durationMinutes} min`}
 82:             </p>
 83:           </div>
 84:           <button
 85:             type="button"
 86:             aria-label="Fermer"
 87:             onClick={onClose}
 88:             disabled={deleting}
 89:             className="p-2 rounded-xl flex-shrink-0 transition-colors"
 90:             style={{ background: "transparent" }}
 91:             onMouseEnter={e => e.currentTarget.style.background = "rgba(255,255,255,0.08)"}
 92:             onMouseLeave={e => e.currentTarget.style.background = "transparent"}
 93:           >
 94:             <X size={18} style={{ color: c.text }} />
 95:           </button>
 96:         </div>
 97: 
 98:         <div className="flex-1 overflow-y-auto px-6 py-5 space-y-5">
 99: 
100:           <CoachSessionDayPanel
101:             session={session}
