113:                 <span className="meta-text font-bold uppercase tracking-wide">Description</span>
114:               </div>
115:               <p className="text-[13px] leading-relaxed" style={{ color: "var(--c-text-2)" }}>{session.description}</p>
116:             </div>
117:           )}
118: 
119:           {/* Consignes */}
120:           {session.instructions && (
121:             <div className="rounded-2xl overflow-hidden" style={{ border: "1px solid rgba(234,179,8,0.30)", background: "rgba(234,179,8,0.06)" }}>
122:               <div className="px-4 py-2.5 flex items-center gap-2" style={{ borderBottom: "1px solid rgba(234,179,8,0.20)" }}>
123:                 <AlertCircle size={13} color="#EAB308" />
124:                 <span className="text-[12px] font-bold uppercase tracking-wide" style={{ color: "var(--tone-warning)" }}>Consignes du coach</span>
125:               </div>
126:               <p className="px-4 py-3 text-[13px] leading-relaxed" style={{ color: "#E6D189" }}>{session.instructions}</p>
127:             </div>
128:           )}
129: 
130:       {/* Pièce jointe */}
131:           {session.pdfUrl && (
132:         <button type="button" onClick={() => openSessionAttachment(session.pdfUrl)}
133:               className="w-full flex items-center gap-3 px-4 py-3.5 rounded-2xl text-[13px] font-semibold transition-colors"
134:               style={{ background: "rgba(91,158,245,0.10)", border: "1px solid rgba(91,158,245,0.25)", color: "var(--tone-info)" }}>
135:               <span className="text-[18px]">📄</span>
136:           Voir la pièce jointe
137:             </button>
138:           )}
139: 
140:           {/* Athlètes */}
141:           <div>
142:             <div className="flex items-center gap-2 mb-3">
143:               <Users size={13} style={{ color: "var(--c-text-3)" }} />
144:               <span className="meta-text font-bold uppercase tracking-wide">
145:                 Participants ({session.athleteIds.length})
146:               </span>
147:             </div>
148:             {session.athleteIds.length === 0 ? (
149:               <p className="meta-text">Aucun athlète assigné</p>
150:             ) : (
151:               <div className="space-y-2">
152:                 {session.athleteIds.map(id => {
153:                   const a  = athletes.find(x => x.id === id);
154:                   const v  = session.validations?.find(val => val.athleteId === id);
155:                   const st = v?.status ?? "future";
156:                   if (!a) return null;
157:                   return (
158:                     <div key={id} className="card flex items-start gap-3 p-3.5">
159:                       <div className="w-9 h-9 rounded-xl flex items-center justify-center text-[12px] font-bold flex-shrink-0"
160:                         style={{ background: c.border, color: "#0A150F" }}>
161:                         {a.avatar}
162:                       </div>
163:                       <div className="flex-1 min-w-0">
164:                         <div className="flex items-center gap-2 flex-wrap mb-1">
165:                           <span className="text-[13px] font-bold" style={{ color: "var(--c-text-1)" }}>{a.name}</span>
166:                           <ValidationBadge status={st} />
167:                           {v?.rpe != null && (
168:                             <span className="text-[12px] font-bold px-2 py-0.5 rounded-full"
169:                               style={{ background: "var(--c-surface-3)", color: "var(--c-text-2)" }}>
170:                               RPE {v.rpe}
171:                             </span>
172:                           )}
173:                         </div>
174:                         {v?.feeling != null && (
175:                           <div className="flex gap-0.5 mb-1">
176:                             {[1,2,3,4,5].map(n => (
177:                               <Star key={n} size={11}
178:                                 fill={v.feeling >= n ? "#EAB308" : "none"}
179:                                 color={v.feeling >= n ? "#EAB308" : "var(--c-border-strong)"} />
180:                             ))}
181:                           </div>
182:                         )}
183:                         {v?.comment && (
184:                           <p className="meta-text italic">« {v.comment} »</p>
185:                         )}
186:                       </div>
187:                     </div>
188:                   );
189:                 })}
190:               </div>
191:             )}
192:           </div>
193: 
194:           {deleteError && (
195:             <p className="text-[12px] rounded-xl px-3 py-2" style={{ color: "var(--tone-danger)", background: "rgba(239,107,107,0.10)" }}>{deleteError}</p>
196:           )}
197:         </div>
198: 
199:         {/* Footer */}
200:         <div className="px-6 py-4 flex items-center justify-between gap-3 flex-shrink-0" style={{ borderTop: "1px solid var(--c-border)" }}>
201:           <div className="flex items-center gap-3">
202:             {!confirmDel ? (
203:               <button onClick={() => setConfirmDel(true)} disabled={deleting}
204:                 className="text-[12px] font-semibold transition-colors"
205:                 style={{ color: "var(--tone-danger)" }}>
206:                 Supprimer
207:               </button>
208:             ) : (
209:               <span className="flex items-center gap-2">
210:                 <span className="text-[12px] font-semibold" style={{ color: "var(--tone-danger)" }}>Confirmer ?</span>
211:                 <button onClick={handleDelete} disabled={deleting}
212:                   className="text-[12px] font-bold rounded-lg px-2.5 py-1 tap-feedback"
213:                   style={{ background: "#EF6B6B", color: "#0A150F" }}>
214:                   {deleting ? "…" : "Oui"}
215:                 </button>
216:                 <button onClick={() => setConfirmDel(false)} className="text-[12px]" style={{ color: "var(--c-text-3)" }}>Non</button>
217:               </span>
218:             )}
219:           </div>
220:           <button onClick={() => onEditRequest(session)} disabled={deleting} className="btn-primary">
221:             ✏️ Modifier
222:           </button>
223:         </div>
224:       </div>
225:     </div>
226:   );
227: });
