  72: 
  73:   /* ── Dimensions sémantiques ── */
  74:   --c-dim-forme:   var(--color-success);
  75:   --c-dim-charge:  var(--color-info);
  76:   --c-dim-mental:  #9B84F0;
  77:   --c-dim-alerte:  var(--color-warning);
  78:   --c-dim-danger:  var(--color-danger);
  79: 
  80:   /* ── Fond & surfaces — dark vert-noir ── */
  81:   --c-bg:           var(--color-bg);
  82:   --c-surface:      var(--color-surface);
  83:   --c-surface-2:    var(--color-surface-raised);
  84:   --c-surface-3:    var(--color-surface-interactive);
  85:   --c-surface-dark: var(--color-surface-sunken);
  86: 
  87:   /* ── Bordures — quasi invisibles ── */
  88:   --c-border:        var(--color-border);
  89:   --c-border-strong: var(--color-border-strong);
  90: 
  91:   /* ── Texte — hiérarchie 4 niveaux sur fond sombre ── */
  92:   --c-text-1: var(--color-text);
  93:   --c-text-2: var(--color-text-secondary);
  94:   --c-text-3: var(--color-text-muted);
  95:   --c-text-4: var(--color-text-subtle);
  96: 
  97:   /* ── Ombres — sur fond sombre, ombres vertes subtiles ── */
  98:   --shadow-xs: 0 1px 2px rgba(0,0,0,0.30);
  99:   --shadow-sm: 0 1px 3px rgba(0,0,0,0.35), 0 4px 12px rgba(0,0,0,0.25);
 100:   --shadow-md: 0 2px 8px rgba(0,0,0,0.40), 0 8px 24px rgba(0,0,0,0.30);
 101:   --shadow-lg: 0 4px 16px rgba(0,0,0,0.45), 0 16px 40px rgba(0,0,0,0.35);
 102:   --shadow-xl: 0 8px 32px rgba(0,0,0,0.50), 0 24px 64px rgba(0,0,0,0.40);
 103: 
 104:   /* ── Glassmorphism dark ── */
 105:   --glass-bg:    rgba(15,32,23,0.88);
 106:   --glass-blur:  20px;
 107: 
 108:   /* ── Chrome / surfaces recessées — theme-aware, voir override [data-theme="light"] ── */
 109:   --surface-chrome:          rgba(9,21,14,0.90);
 110:   --surface-chrome-strong:   rgba(9,21,14,0.94);
 111:   --surface-recessed:        rgba(14,30,21,0.72);
 112:   --surface-recessed-strong: rgba(5,13,8,0.46);
 113:   --surface-auth-card:       rgba(14,30,21,0.94);
 114:   --scrollbar-thumb:         rgba(255,255,255,0.10);
 115: 
 116:   /* ── Teintes de statut (texte) — pastel sur fond sombre, assombries
 117:        automatiquement en clair pour rester lisibles sur blanc ── */
 118:   --tone-success: #7BD8B4;
 119:   --tone-danger:  #F19A9A;
 120:   --tone-warning: #F0CB61;
 121:   --tone-info:    #A9CBFB;
 122:   --tone-mental:  #9B84F0;
 123: 
 124:   /* ── Radius — 4 valeurs fixes ── */
 125:   --r-sm:   8px;
 126:   --r-md:   12px;
 127:   --r-lg:   16px;
 128:   --r-xl:   24px;
 129:   --r-full: 999px;
 130: 
 131:   /* Aliases */
 132:   --radius-sm: var(--r-sm); --radius-md: var(--r-md);
 133:   --radius-lg: var(--r-lg); --radius-xl: var(--r-xl);
 134:   --radius-2xl: var(--r-xl); --radius-full: var(--r-full);
 135: 
 136:   /* ── Touch & safe areas ── */
 137:   --touch:        44px;
 138:   --touch-target: 44px;
 139:   --safe-top:    env(safe-area-inset-top, 0px);
 140:   --safe-bottom: env(safe-area-inset-bottom, 0px);
 141:   --safe-left:   env(safe-area-inset-left, 0px);
 142:   --safe-right:  env(safe-area-inset-right, 0px);
 143: 
 144:   /* ── Transitions ── */
 145:   --spring:   cubic-bezier(0.16, 1, 0.3, 1);
 146:   --ease-out: cubic-bezier(0, 0, 0.2, 1);
 147:   --dur-fast: 150ms;
 148:   --dur-base: 220ms;
 149:   --dur-slow: 350ms;
 150: 
 151: }
 152: 
 153: /* ═══════════════════════════════════════════════════════════════════════════════
 154:    AthleteOS — Design System v5 LIGHT (override)
 155:    Même hiérarchie sémantique, palette claire — activé via [data-theme="light"]
 156:    sur <html>, piloté par le hook useTheme.
 157:    ═══════════════════════════════════════════════════════════════════════════════ */
 158: :root[data-theme="light"] {
 159:   color-scheme: light;
 160:   --color-bg:                  #F3F6F4;
 161:   --color-surface:             #FFFFFF;
 162:   --color-surface-raised:      #F6F9F7;
 163:   --color-surface-interactive: #ECF2EE;
 164:   --color-surface-sunken:      #E6EDE9;
 165: 
 166:   --color-border:        rgba(14,30,21,0.10);
 167:   --color-border-strong: rgba(14,30,21,0.18);
 168: 
 169:   --color-text:           #0E1B14;
 170:   --color-text-secondary: #414F47;
 171:   --color-text-muted:     #64726B;
 172:   --color-text-subtle:    #7C8880;
 173:   --color-text-disabled:  #A6B0AA;
 174: 
 175:   --color-accent:        #1C8F6C;
 176:   --color-accent-strong: #146F55;
 177:   --color-success:       #1C9A73;
 178:   --color-warning:       #B87309;
 179:   --color-danger:        #C6403F;
 180:   --color-info:          #3B67C4;
 181: 
 182:   --shadow-xs: 0 1px 2px rgba(14,30,21,0.06);
 183:   --shadow-sm: 0 1px 3px rgba(14,30,21,0.05), 0 4px 12px rgba(14,30,21,0.05);
 184:   --shadow-md: 0 2px 8px rgba(14,30,21,0.06), 0 8px 24px rgba(14,30,21,0.06);
 185:   --shadow-lg: 0 4px 16px rgba(14,30,21,0.07), 0 16px 40px rgba(14,30,21,0.07);
 186:   --shadow-xl: 0 8px 32px rgba(14,30,21,0.09), 0 24px 64px rgba(14,30,21,0.08);
 187: 
 188:   --glass-bg: rgba(255,255,255,0.88);
 189: 
 190:   --surface-chrome:          rgba(255,255,255,0.90);
 191:   --surface-chrome-strong:   rgba(255,255,255,0.94);
 192:   --surface-recessed:        rgba(230,238,233,0.75);
 193:   --surface-recessed-strong: rgba(219,229,223,0.65);
 194:   --surface-auth-card:       rgba(255,255,255,0.94);
 195:   --scrollbar-thumb:         rgba(14,30,21,0.16);
 196: 
 197:   /* Mêmes teintes, assombries/saturées pour rester ≥ 4.5:1 sur blanc. */
 198:   --tone-success: #0E7A56;
 199:   --tone-danger:  #B91C1C;
 200:   --tone-warning: #92600A;
 201:   --tone-info:    #1D4ED8;
 202:   --tone-mental:  #6D28D9;
 203: }
 204: 
 205: /* ─── Reset ─────────────────────────────────────────────────────────────────── */
 206: *, *::before, *::after { box-sizing: border-box; }
 207: html, body, #root { height: 100%; margin: 0; padding: 0; }
 208: html { overscroll-behavior: none; text-size-adjust: 100%; -webkit-text-size-adjust: 100%; }
 209: 
 210: body {
 211:   font-family: "DM Sans", system-ui, -apple-system, sans-serif;
 212:   background-color: var(--c-bg);
 213:   /* Glow ambiant très léger derrière toute l'appli — donne une matière
 214:      "premium" au fond plutôt qu'un aplat pur, sans jamais être perceptible
 215:      consciemment. Un seul endroit pour toute l'appli (coach + athlète). */
 216:   background-image: radial-gradient(ellipse 900px 600px at 12% -8%, rgba(29,158,117,0.06) 0%, transparent 60%);
 217:   background-repeat: no-repeat;
 218:   color: var(--c-text-1);
 219:   -webkit-font-smoothing: antialiased;
 220:   -moz-osx-font-smoothing: grayscale;
 221:   text-rendering: optimizeLegibility;
 222:   -webkit-tap-highlight-color: transparent;
 223:   touch-action: manipulation;
 224:   font-size: var(--text-body);
 225:   line-height: var(--leading-body);
 226:   font-weight: 400;
 227: }
 228: 
 229: @media (min-width: 768px) {
 230:   :root { --page-gutter: var(--space-6); --card-padding: var(--space-5); --card-padding-comfortable: var(--space-6); }
 231: }
 232: 
 233: /* ─── Scrollbar ──────────────────────────────────────────────────────────────── */
 234: ::-webkit-scrollbar { width: 3px; height: 3px; }
 235: ::-webkit-scrollbar-track { background: transparent; }
 236: ::-webkit-scrollbar-thumb { background: var(--scrollbar-thumb); border-radius: 99px; }
 237: * { scrollbar-width: thin; scrollbar-color: var(--scrollbar-thumb) transparent; }
 238: 
 239: /* ─── Sélection ─────────────────────────────────────────────────────────────── */
 240: ::selection { background: rgba(29,158,117,0.25); color: #fff; }
 241: 
 242: /* ─── Focus ─────────────────────────────────────────────────────────────────── */
 243: :focus-visible { outline: 2px solid var(--c-accent); outline-offset: 2px; border-radius: 4px; }
 244: :focus:not(:focus-visible) { outline: none; }
 245: 
 246: /* ─── Reduced motion ─────────────────────────────────────────────────────────── */
 247: @media (prefers-reduced-motion: reduce) {
 248:   *, *::before, *::after {
 249:     animation-duration: 0.01ms !important;
 250:     animation-iteration-count: 1 !important;
 251:     transition-duration: 0.01ms !important;
 252:   }
 253: }
 254: 
 255: /* ═══════════════════════════════════════════════════════════════════════════════
 256:    CARDS — dark, bordure subtile, légère lueur verte au hover
 257:    ═══════════════════════════════════════════════════════════════════════════════ */
 258: 
 259: .card {
 260:   /* Léger dégradé vertical (2-3% d'opacité) + bordure du haut plus claire
 261:      que le reste — simule une lumière qui vient d'en haut, comme les
 262:      cards iOS. Change la "matière" perçue sans changer une seule couleur. */
 263:   background: linear-gradient(180deg, rgba(255,255,255,0.025) 0%, rgba(255,255,255,0) 55%), var(--c-surface);
 264:   border-radius: var(--r-lg);
 265:   border: 1px solid var(--c-border);
 266:   border-top-color: rgba(255,255,255,0.11);
 267:   box-shadow: var(--shadow-sm);
 268:   transition:
 269:     box-shadow var(--dur-base) var(--spring),
 270:     transform  var(--dur-base) var(--spring),
 271:     border-color var(--dur-base) var(--ease-out);
 272: }
 273: 
 274: .card-hover { cursor: pointer; }
 275: .card-hover:hover {
 276:   box-shadow: var(--shadow-md), 0 0 0 1px rgba(29,158,117,0.15);
 277:   border-color: rgba(29,158,117,0.18);
 278:   transform: translateY(-1px);
 279: }
 280: .card-hover:active {
 281:   transform: scale(0.988);
 282:   box-shadow: var(--shadow-xs);
 283:   transition-duration: 80ms;
 284: }
 285: 
 286: /* Glassmorphism dark */
 287: .card-glass {
 288:   background: var(--glass-bg);
 289:   backdrop-filter: blur(var(--glass-blur)) saturate(140%);
 290:   -webkit-backdrop-filter: blur(var(--glass-blur)) saturate(140%);
 291:   border: 1px solid var(--c-border);
 292:   box-shadow: var(--shadow-sm);
 293: }
 294: 
 295: .shimmer-hover { position: relative; overflow: hidden; }
 296: .shimmer-hover::after {
 297:   content: '';
 298:   position: absolute; inset: 0;
 299:   background: linear-gradient(105deg, transparent 40%, rgba(255,255,255,0.04) 50%, transparent 60%);
 300:   background-size: 200% 100%;
 301:   opacity: 0; pointer-events: none;
 302:   transition: opacity 0.15s ease;
 303: }
 304: .shimmer-hover:hover::after { opacity: 1; animation: shimmer 0.55s ease; }
 305: 
 306: /* ═══════════════════════════════════════════════════════════════════════════════
 307:    BOUTONS
 308:    ═══════════════════════════════════════════════════════════════════════════════ */
 309: 
 310: .btn-primary {
 311:   display: inline-flex; align-items: center; justify-content: center; gap: 6px;
 312:   min-height: var(--touch); padding: 0 18px;
 313:   background: linear-gradient(135deg, var(--c-accent), var(--c-accent-dark));
 314:   color: #fff; border: none; border-radius: var(--r-md);
 315:   font-family: inherit; font-size: 14px; font-weight: 600;
 316:   letter-spacing: -0.01em; cursor: pointer; white-space: nowrap;
 317:   box-shadow: 0 0 0 1px rgba(29,158,117,0.30), 0 4px 16px rgba(29,158,117,0.25);
 318:   transition: all var(--dur-base) var(--spring);
 319:   user-select: none; -webkit-user-select: none;
 320:   position: relative; overflow: hidden;
 321: }
 322: .btn-primary::after { content: ''; position: absolute; inset: 0; background: transparent; transition: background var(--dur-fast) ease; }
 323: .btn-primary:hover  { transform: translateY(-1px); box-shadow: 0 0 0 1px rgba(29,158,117,0.40), 0 6px 20px rgba(29,158,117,0.35); }
 324: .btn-primary:hover::after  { background: rgba(255,255,255,0.08); }
 325: .btn-primary:active { transform: scale(0.97); transition-duration: 70ms; }
 326: .btn-primary:disabled { opacity: 0.35; cursor: not-allowed; transform: none; box-shadow: none; }
 327: 
 328: .btn-secondary {
 329:   display: inline-flex; align-items: center; justify-content: center; gap: 6px;
 330:   min-height: var(--touch); padding: 0 16px;
 331:   background: var(--c-surface-2); color: var(--c-text-2);
 332:   border: 1px solid var(--c-border); border-radius: var(--r-md);
 333:   font-family: inherit; font-size: 14px; font-weight: 500; cursor: pointer;
 334:   transition: all var(--dur-base) var(--spring); user-select: none; white-space: nowrap;
 335: }
 336: .btn-secondary:hover  { background: var(--c-surface-3); color: var(--c-text-1); border-color: var(--c-border-strong); }
 337: .btn-secondary:active { transform: scale(0.97); transition-duration: 70ms; }
 338: .btn-secondary:disabled { opacity: 0.35; cursor: not-allowed; }
 339: 
 340: .btn-ghost {
 341:   display: inline-flex; align-items: center; gap: 5px;
 342:   min-height: var(--touch); padding: 0 8px;
 343:   background: none; border: none; color: var(--c-accent);
 344:   font-family: inherit; font-size: var(--text-secondary); font-weight: 600; cursor: pointer;
 345:   border-radius: var(--r-md); transition: all var(--dur-fast) ease;
 346: }
 347: .btn-ghost:hover  { background: var(--c-accent-light); }
 348: .btn-ghost:active { opacity: 0.7; transform: scale(0.97); }
 349: 
 350: .icon-btn {
 351:   width: var(--touch); height: var(--touch); padding: 0; flex-shrink: 0;
 352:   display: inline-flex; align-items: center; justify-content: center;
 353:   border: 1px solid var(--c-border); border-radius: var(--r-md);
 354:   background: var(--c-surface-2); color: var(--c-text-2); cursor: pointer;
 355:   transition: color var(--dur-fast) ease, background var(--dur-fast) ease, border-color var(--dur-fast) ease, transform var(--dur-fast) var(--spring);
 356: }
 357: .icon-btn:hover:not(:disabled) { color: var(--c-text-1); background: var(--c-surface-3); border-color: var(--c-border-strong); }
 358: .icon-btn:active:not(:disabled) { transform: scale(0.94); }
 359: .icon-btn:disabled { opacity: 0.38; cursor: not-allowed; }
 360: 
 361: /* ═══════════════════════════════════════════════════════════════════════════════
 362:    NAVIGATION SIDEBAR — dark
 363:    ═══════════════════════════════════════════════════════════════════════════════ */
 364: 
 365: .sidebar-premium {
 366:   background: var(--c-surface);
 367:   border-right: 1px solid var(--c-border);
 368:   display: flex; flex-direction: column;
 369: }
 370: 
 371: /* Navigation coach : le style premium ne doit jamais annuler son masquage mobile. */
 372: #coach-sidebar {
 373:   display: none;
 374: }
 375: 
 376: @media (min-width: 768px) {
 377:   #coach-sidebar {
 378:     display: flex;
 379:   }
 380: }
 381: 
 382: .nav-item {
 383:   position: relative; display: flex; align-items: center; gap: 10px;
 384:   min-height: var(--touch); padding: 0 12px;
 385:   font-size: 13px; font-weight: 400; color: var(--c-text-2);
 386:   border-radius: var(--r-md); margin: 1px 6px; cursor: pointer;
 387:   transition: all var(--dur-base) var(--spring);
 388:   border: 1px solid transparent; user-select: none;
 389: }
 390: .nav-item:hover { background: var(--c-surface-2); color: var(--c-text-1); }
 391: .nav-item.active {
 392:   background: rgba(29,158,117,0.08);
 393:   color: var(--c-accent); font-weight: 500;
 394:   border-color: rgba(29,158,117,0.12);
 395: }
 396: .nav-item.active::before {
 397:   content: '';
 398:   position: absolute; left: -6px; top: 50%; transform: translateY(-50%);
 399:   width: 2px; height: 14px;
 400:   background: var(--c-accent); border-radius: 0 2px 2px 0;
 401: }
 402: 
 403: /* ═══════════════════════════════════════════════════════════════════════════════
 404:    NAVIGATION BOTTOM (mobile) — dark glassmorphism
 405:    ═══════════════════════════════════════════════════════════════════════════════ */
 406: 
 407: .bottom-nav {
 408:   background: var(--surface-chrome-strong);
 409:   backdrop-filter: blur(24px) saturate(160%);
 410:   -webkit-backdrop-filter: blur(24px) saturate(160%);
 411:   border-top: 1px solid var(--c-border);
 412:   box-shadow: 0 -1px 0 var(--c-border);
 413:   padding-bottom: var(--safe-bottom);
 414:   height: calc(60px + var(--safe-bottom));
 415:   display: flex; align-items: flex-start; z-index: 50;
 416: }
 417: 
 418: .bottom-nav-item {
 419:   display: flex; flex-direction: column; align-items: center;
 420:   justify-content: center; gap: 3px; flex: 1;
 421:   min-height: 60px; min-width: var(--touch); padding: 7px 2px 0;
 422:   color: var(--c-text-3); font-family: inherit;
 423:   transition: color var(--dur-fast) var(--spring), transform var(--dur-fast) var(--spring);
 424:   border: none; background: none; cursor: pointer; position: relative;
 425:   -webkit-tap-highlight-color: transparent;
 426: }
 427: .bottom-nav-item.active { color: var(--c-accent); }
 428: .bottom-nav-item.active::before {
 429:   content: ''; position: absolute; top: 0; left: 50%; transform: translateX(-50%);
 430:   width: 20px; height: 2px; background: var(--c-accent);
 431:   border-radius: 0 0 2px 2px;
 432:   animation: fade-in var(--dur-fast) ease both;
 433: }
 434: .bottom-nav-item:active { transform: scale(0.88); transition-duration: 70ms; }
 435: 
 436: .bottom-nav-label {
 437:   max-width: 100%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
 438:   font-size: var(--text-meta); font-weight: 500; letter-spacing: 0; line-height: 1;
 439: }
 440: .mobile-nav-badge {
 441:   position: absolute; top: -7px; right: -10px;
 442:   min-width: 20px; height: 20px; padding: 0 5px;
 443:   display: inline-flex; align-items: center; justify-content: center;
 444:   border-radius: 999px; border: 2px solid var(--c-bg);
 445:   background: var(--color-danger); color: #fff;
 446:   font-size: var(--text-meta); line-height: 1; font-weight: 700;
 447:   font-variant-numeric: tabular-nums;
 448:   animation: bounce-in var(--dur-base) var(--spring) both;
 449: }
 450: 
 451: .mobile-header-action {
 452:   position: relative; width: var(--touch); height: var(--touch);
 453:   display: inline-flex; align-items: center; justify-content: center;
 454:   border: 1px solid var(--c-border); border-radius: var(--r-md);
 455:   background: var(--c-surface); color: var(--c-text-2); cursor: pointer;
 456:   transition: color var(--dur-fast) ease, border-color var(--dur-fast) ease, background var(--dur-fast) ease;
 457: }
 458: .mobile-header-action.active {
 459:   color: var(--c-accent); border-color: rgba(29,158,117,0.30);
 460:   background: rgba(29,158,117,0.10);
 461: }
 462: .mobile-account-action {
 463:   width: var(--touch); height: var(--touch); flex-shrink: 0;
 464:   display: inline-flex; align-items: center; justify-content: center;
 465:   border: 1px solid rgba(36,168,125,0.24); border-radius: 50%;
 466:   background: linear-gradient(135deg, rgba(36,168,125,0.24), rgba(25,139,109,0.16));
 467:   color: #B9F0DB; font: inherit; font-size: var(--text-meta); line-height: 1; font-weight: 700; cursor: pointer;
 468:   transition: transform var(--dur-fast) var(--spring), border-color var(--dur-fast) ease;
 469: }
 470: .mobile-account-action:active { transform: scale(0.94); }
 471: .mobile-account-action:hover { border-color: rgba(36,168,125,0.44); }
 472: .mobile-header-badge {
 473:   position: absolute; top: 2px; right: 1px;
 474:   min-width: 20px; height: 20px; padding: 0 5px;
 475:   display: inline-flex; align-items: center; justify-content: center;
 476:   border-radius: 999px; border: 2px solid var(--c-surface);
 477:   background: var(--color-danger); color: #fff;
 478:   font-size: var(--text-meta); line-height: 1; font-weight: 700;
 479:   font-variant-numeric: tabular-nums;
 480:   animation: bounce-in var(--dur-base) var(--spring) both;
 481: }
 482: 
 483: /* ═══════════════════════════════════════════════════════════════════════════════
 484:    HEADER — dark glassmorphism
 485:    ═══════════════════════════════════════════════════════════════════════════════ */
 486: 
 487: .header-glass {
 488:   background: var(--surface-chrome);
 489:   backdrop-filter: blur(24px) saturate(160%);
 490:   -webkit-backdrop-filter: blur(24px) saturate(160%);
 491:   border-bottom: 1px solid var(--c-border);
 492:   padding-top: var(--safe-top);
 493: }
 494: 
 495: /* ═══════════════════════════════════════════════════════════════════════════════
 496:    MODALS & BOTTOM SHEET — dark
 497:    ═══════════════════════════════════════════════════════════════════════════════ */
 498: 
 499: .modal-backdrop {
 500:   background: rgba(0,0,0,0.70);
 501:   backdrop-filter: blur(10px); -webkit-backdrop-filter: blur(10px);
 502:   animation: fade-in var(--dur-base) ease both;
 503: }
 504: .modal-content { animation: scale-in var(--dur-slow) var(--spring) both; }
 505: 
 506: .bottom-sheet-backdrop {
 507:   position: fixed; inset: 0; z-index: 100;
 508:   background: rgba(0,0,0,0.72);
 509:   backdrop-filter: blur(10px); -webkit-backdrop-filter: blur(10px);
 510:   animation: fade-in var(--dur-base) ease both;
 511: }
 512: .bottom-sheet {
 513:   position: fixed; left: 0; right: 0; bottom: 0; z-index: 101;
 514:   background: var(--c-surface); border-radius: 20px 20px 0 0;
 515:   border-top: 1px solid var(--c-border);
 516:   box-shadow: var(--shadow-xl);
 517:   padding-bottom: calc(16px + var(--safe-bottom));
 518:   max-height: 90dvh; overflow-y: auto; overscroll-behavior: contain;
 519:   animation: sheet-up var(--dur-slow) var(--spring) both;
 520: }
 521: .bottom-sheet-handle {
 522:   width: 30px; height: 3px;
 523:   background: var(--c-border-strong);
 524:   border-radius: 99px; margin: 10px auto 0; flex-shrink: 0;
 525: }
 526: 
 527: .coach-more-sheet { padding-bottom: calc(20px + var(--safe-bottom)); }
 528: .mobile-more-item {
 529:   min-height: 88px; padding: 14px;
 530:   display: flex; align-items: center; gap: 12px;
 531:   border: 1px solid var(--c-border); border-radius: var(--r-lg);
 532:   background: var(--c-surface-2); color: var(--c-text-2); cursor: pointer;
 533:   transition: transform var(--dur-fast) var(--spring), border-color var(--dur-fast) ease, background var(--dur-fast) ease;
 534: }
 535: .mobile-more-item:active { transform: scale(0.97); }
 536: .mobile-more-item.active {
 537:   border-color: rgba(29,158,117,0.34); background: rgba(29,158,117,0.09);
 538: }
 539: .mobile-more-icon {
 540:   width: 38px; height: 38px; flex-shrink: 0;
 541:   display: inline-flex; align-items: center; justify-content: center;
 542:   border-radius: 12px; background: var(--c-surface-3); color: var(--c-text-2);
 543: }
 544: .mobile-more-item.active .mobile-more-icon {
 545:   background: rgba(29,158,117,0.14); color: var(--c-accent);
 546: }
 547: .mobile-more-label {
 548:   display: block; color: var(--c-text-1);
 549:   font-size: var(--text-card-title); line-height: 1.2; font-weight: 600;
 550: }
 551: .mobile-more-description {
 552:   display: block; margin-top: 4px; color: var(--c-text-3);
 553:   font-size: var(--text-meta); line-height: 1.3;
 554: }
 555: .mobile-more-count {
 556:   min-width: 22px; height: 22px; padding: 0 6px;
 557:   display: inline-flex; align-items: center; justify-content: center;
 558:   border-radius: 999px; background: var(--color-danger); color: #fff;
 559:   font-size: var(--text-meta); line-height: 1; font-weight: 700;
 560:   font-variant-numeric: tabular-nums;
 561: }
 562: 
 563: @media (max-width: 379px) {
 564:   .coach-more-sheet nav { grid-template-columns: minmax(0, 1fr); }
 565:   .coach-more-sheet .mobile-more-item {
 566:     grid-column: span 1 / span 1;
 567:     min-height: 72px;
 568:   }
 569: }
 570: 
 571: /* ═══════════════════════════════════════════════════════════════════════════════
 572:    AUTHENTIFICATION — shell et contrôles partagés
 573:    ════════════════════════════════════════════════════════════════════════════════ */
 574: 
 575: .auth-shell {
 576:   position: relative; min-height: 100dvh; overflow-x: hidden;
 577:   color: var(--c-text-1); background:
 578:     radial-gradient(circle at 12% 12%, rgba(36,168,125,0.13), transparent 32%),
 579:     radial-gradient(circle at 88% 88%, rgba(107,159,242,0.08), transparent 28%),
 580:     linear-gradient(145deg, var(--c-bg), var(--color-surface-sunken));
 581: }
 582: .auth-shell::before {
 583:   content: ''; position: absolute; inset: 0; pointer-events: none; opacity: 0.22;
 584:   background-image:
 585:     linear-gradient(rgba(255,255,255,0.025) 1px, transparent 1px),
 586:     linear-gradient(90deg, rgba(255,255,255,0.025) 1px, transparent 1px);
 587:   background-size: 40px 40px;
 588:   mask-image: linear-gradient(to bottom, rgba(0,0,0,0.7), transparent 82%);
 589: }
 590: .auth-orbit {
 591:   position: absolute; border: 1px solid rgba(36,168,125,0.10);
 592:   border-radius: 50%; pointer-events: none;
 593: }
 594: .auth-orbit-one { width: 380px; height: 380px; top: -210px; right: -110px; }
 595: .auth-orbit-two { width: 240px; height: 240px; bottom: -150px; left: -90px; }
 596: .auth-layout {
 597:   position: relative; z-index: 1; width: min(1180px, 100%); min-height: 100dvh;
 598:   margin: 0 auto; display: grid; align-items: center;
 599: }
 600: .auth-story { display: none; }
 601: .auth-workspace {
 602:   width: 100%; max-width: 480px; margin: 0 auto;
 603:   padding: calc(24px + var(--safe-top)) 16px calc(24px + var(--safe-bottom));
 604: }
 605: .auth-mobile-brand { display: flex; justify-content: center; margin-bottom: 24px; }
 606: .auth-card {
 607:   padding: 24px 20px; border: 1px solid var(--c-border-strong); border-top-color: rgba(255,255,255,0.14);
 608:   border-radius: var(--r-xl); background:
 609:     linear-gradient(180deg, rgba(255,255,255,0.025), transparent 38%),
 610:     var(--surface-auth-card);
 611:   box-shadow: var(--shadow-xl); backdrop-filter: blur(24px); -webkit-backdrop-filter: blur(24px);
 612: }
 613: .auth-card-header { margin-bottom: 24px; }
 614: .auth-kicker {
 615:   color: var(--c-accent); font-size: var(--text-meta); line-height: var(--leading-meta);
 616:   font-weight: 700; letter-spacing: 0.10em; text-transform: uppercase;
 617: }
 618: .auth-card-header h1 {
 619:   margin-top: 6px; color: var(--c-text-1); font-size: var(--text-screen-title);
 620:   line-height: var(--leading-title); font-weight: 700; letter-spacing: -0.03em;
 621: }
 622: .auth-card-header > p:last-child {
 623:   margin-top: 8px; color: var(--c-text-2); font-size: var(--text-secondary);
 624:   line-height: var(--leading-small);
 625: }
 626: .auth-form { display: flex; flex-direction: column; gap: 16px; }
 627: .auth-field { min-width: 0; }
 628: .auth-field > label {
 629:   display: block; margin-bottom: 8px; color: var(--c-text-2);
 630:   font-size: var(--text-meta); line-height: var(--leading-meta); font-weight: 600;
 631: }
 632: .auth-input-wrap { position: relative; }
 633: .auth-input-icon {
 634:   position: absolute; left: 14px; top: 50%; z-index: 1;
 635:   transform: translateY(-50%); color: var(--c-text-3); pointer-events: none;
 636: }
 637: .auth-input {
 638:   width: 100%; min-height: 52px; padding: 0 48px 0 44px;
 639:   border: 1px solid var(--c-border-strong); border-radius: var(--r-md);
 640:   background: var(--c-surface-2); color: var(--c-text-1);
 641:   font: inherit; font-size: var(--text-body); line-height: var(--leading-body);
 642:   outline: none; appearance: none; -webkit-appearance: none;
 643:   transition: border-color var(--dur-fast) ease, box-shadow var(--dur-fast) ease, background var(--dur-fast) ease;
 644: }
 645: .auth-input:hover:not(:disabled) { border-color: rgba(235,247,239,0.25); }
 646: .auth-input:focus {
 647:   border-color: var(--c-accent); background: var(--color-surface-interactive);
 648:   box-shadow: 0 0 0 3px rgba(36,168,125,0.14);
 649: }
 650: .auth-input::placeholder { color: var(--c-text-4); opacity: 1; }
 651: .auth-input:disabled { color: var(--color-text-disabled); cursor: not-allowed; opacity: 0.72; }
 652: .auth-input-wrap.has-error .auth-input {
 653:   border-color: rgba(239,106,106,0.65); box-shadow: 0 0 0 3px rgba(239,106,106,0.10);
 654: }
 655: .auth-password-toggle {
 656:   position: absolute; right: 4px; top: 4px; width: 44px; height: 44px;
 657:   display: inline-flex; align-items: center; justify-content: center;
 658:   border: 0; border-radius: 10px; background: transparent; color: var(--c-text-3); cursor: pointer;
 659: }
 660: .auth-password-toggle:hover { color: var(--c-text-1); background: rgba(255,255,255,0.04); }
 661: .auth-field-hint, .auth-field-error {
 662:   margin-top: 6px; font-size: var(--text-meta); line-height: var(--leading-meta);
 663: }
 664: .auth-field-hint { color: var(--c-text-3); }
 665: .auth-field-error { color: #F59A9A; }
 666: .auth-feedback {
 667:   display: flex; align-items: flex-start; gap: 10px; padding: 12px 14px;
 668:   border: 1px solid; border-radius: var(--r-md);
 669:   font-size: var(--text-secondary); line-height: var(--leading-small);
 670: }
 671: .auth-feedback > svg { flex-shrink: 0; margin-top: 1px; }
 672: .auth-feedback.error { color: #F6A7A7; border-color: rgba(239,106,106,0.25); background: rgba(239,106,106,0.09); }
 673: .auth-feedback.success { color: #78DDB8; border-color: rgba(67,201,155,0.25); background: rgba(67,201,155,0.09); }
 674: .auth-submit {
 675:   width: 100%; min-height: 52px; padding: 0 18px;
 676:   display: inline-flex; align-items: center; justify-content: center; gap: 9px;
 677:   border: 1px solid rgba(255,255,255,0.10); border-radius: var(--r-md);
 678:   background: linear-gradient(135deg, var(--c-accent), var(--c-accent-dark)); color: #fff;
 679:   box-shadow: 0 8px 24px rgba(36,168,125,0.20);
 680:   font: inherit; font-size: var(--text-body); font-weight: 700; cursor: pointer;
 681:   transition: transform var(--dur-fast) var(--spring), filter var(--dur-fast) ease, opacity var(--dur-fast) ease;
 682: }
 683: .auth-submit:hover:not(:disabled) { filter: brightness(1.08); }
 684: .auth-submit:active:not(:disabled) { transform: scale(0.985); }
 685: .auth-submit:disabled { opacity: 0.45; cursor: not-allowed; box-shadow: none; }
 686: .auth-text-action {
 687:   min-height: var(--touch); padding: 0 4px; border: 0; background: transparent;
 688:   display: inline-flex; align-items: center; justify-content: center; gap: 6px;
 689:   color: var(--c-accent); font: inherit; font-size: var(--text-secondary); font-weight: 600; cursor: pointer;
 690: }
 691: .auth-text-action.subtle { color: var(--c-text-2); }
 692: .auth-text-action:hover { color: #74D9B5; }
 693: .auth-forgot-link { min-height: 36px; margin-top: 4px; padding: 0; }
 694: .auth-footer {
 695:   display: flex; justify-content: center; margin-top: 16px;
 696:   color: var(--c-text-2); text-align: center;
 697: }
 698: .auth-trust-note {
 699:   display: flex; align-items: flex-start; gap: 9px; padding-top: 4px;
 700:   color: var(--c-text-3); font-size: var(--text-meta); line-height: var(--leading-meta);
 701: }
 702: .auth-trust-note svg { flex-shrink: 0; color: var(--c-accent); }
 703: .password-strength { margin-top: 8px; }
 704: .password-strength-track { display: grid; grid-template-columns: repeat(4, 1fr); gap: 4px; }
 705: .password-strength-track span { height: 3px; border-radius: 99px; background: var(--c-border-strong); }
 706: .password-strength-track span.weak { background: var(--color-danger); }
 707: .password-strength-track span.fair { background: var(--color-warning); }
 708: .password-strength-track span.good, .password-strength-track span.strong { background: var(--color-success); }
 709: .password-strength-copy {
 710:   display: flex; justify-content: space-between; gap: 12px; margin-top: 6px;
 711:   color: var(--c-text-3); font-size: var(--text-meta); line-height: var(--leading-meta);
 712: }
 713: .auth-role-fieldset { min-width: 0; margin: 0 0 24px; padding: 0 0 24px; border: 0; border-bottom: 1px solid var(--c-border); }
 714: .auth-role-fieldset > legend {
 715:   margin-bottom: 10px; color: var(--c-text-2);
 716:   font-size: var(--text-meta); line-height: var(--leading-meta); font-weight: 600;
 717: }
 718: .auth-role-picker { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px; }
 719: .auth-role-option {
 720:   min-height: 72px; padding: 10px;
 721:   display: flex; align-items: center; gap: 10px; min-width: 0;
 722:   border: 1px solid var(--c-border); border-radius: var(--r-md);
 723:   background: var(--c-surface-2); color: var(--c-text-2); text-align: left; cursor: pointer;
 724:   transition: border-color var(--dur-fast) ease, background var(--dur-fast) ease, transform var(--dur-fast) var(--spring);
 725: }
 726: .auth-role-option:active { transform: scale(0.98); }
 727: .auth-role-option.active { border-color: rgba(36,168,125,0.40); background: rgba(36,168,125,0.10); }
 728: .auth-role-icon {
 729:   width: 36px; height: 36px; flex-shrink: 0; display: inline-flex; align-items: center; justify-content: center;
 730:   border-radius: 11px; background: var(--c-surface-3); color: var(--c-text-3);
 731: }
 732: .auth-role-option.active .auth-role-icon { background: rgba(36,168,125,0.16); color: var(--c-accent); }
 733: .auth-role-option strong, .auth-role-option small { display: block; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
 734: .auth-role-option strong { color: var(--c-text-1); font-size: var(--text-secondary); line-height: var(--leading-small); font-weight: 700; }
 735: .auth-role-option small { margin-top: 1px; color: var(--c-text-3); font-size: var(--text-meta); line-height: var(--leading-meta); }
 736: .auth-role-description {
 737:   margin-top: 10px; color: var(--c-text-3);
 738:   font-size: var(--text-meta); line-height: var(--leading-meta);
 739: }
 740: .auth-honeypot {
 741:   position: absolute; left: -9999px; width: 1px; height: 1px; overflow: hidden;
 742: }
 743: 
 744: @media (min-width: 640px) {
 745:   .auth-workspace { padding-left: 24px; padding-right: 24px; }
 746:   .auth-card { padding: 32px; }
 747: }
 748: 
 749: @media (min-width: 960px) {
 750:   .auth-layout { grid-template-columns: minmax(0, 1fr) 480px; gap: 72px; padding: 40px; }
 751:   .auth-story {
 752:     min-height: 640px; padding: 24px 12px; display: flex; flex-direction: column;
 753:   }
 754:   .auth-story-copy { margin-top: auto; max-width: 560px; }
 755:   .auth-story-copy h2 {
 756:     max-width: 540px; margin-top: 12px; color: var(--c-text-1);
 757:     font-size: clamp(38px, 4vw, 56px); line-height: 1.04; font-weight: 700; letter-spacing: -0.045em;
 758:   }
 759:   .auth-story-copy > p:last-child {
 760:     max-width: 520px; margin-top: 20px; color: var(--c-text-2);
 761:     font-size: 16px; line-height: 24px;
 762:   }
 763:   .auth-product-points { display: grid; gap: 12px; margin-top: 32px; max-width: 540px; }
 764:   .auth-product-point {
 765:     display: flex; align-items: center; gap: 12px; color: var(--c-text-2);
 766:     font-size: var(--text-secondary); line-height: var(--leading-small);
 767:   }
 768:   .auth-product-point > span {
 769:     width: 36px; height: 36px; flex-shrink: 0; display: inline-flex; align-items: center; justify-content: center;
 770:     border: 1px solid rgba(36,168,125,0.18); border-radius: 11px;
 771:     background: rgba(36,168,125,0.08); color: var(--c-accent);
 772:   }
 773:   .auth-story-footnote {
 774:     margin-top: auto; padding-top: 40px; color: var(--c-text-3);
 775:     font-size: var(--text-meta); line-height: var(--leading-meta); letter-spacing: 0.04em;
 776:   }
 777:   .auth-mobile-brand { display: none; }
 778:   .auth-workspace { max-width: 480px; padding: 0; }
 779: }
 780: 
 781: /* Réglages partagés coach / athlète. */
 782: .account-settings-backdrop {
 783:   position: fixed; inset: 0; z-index: 120;
 784:   display: flex; align-items: flex-end; justify-content: center;
 785: }
 786: .account-settings-dialog {
 787:   width: 100%; max-height: min(92dvh, 780px); min-height: min(76dvh, 620px);
 788:   display: flex; flex-direction: column; overflow: hidden;
 789:   border: 1px solid var(--c-border-strong); border-bottom: 0;
 790:   border-radius: 24px 24px 0 0; background: var(--c-surface); box-shadow: var(--shadow-xl);
 791:   padding-bottom: var(--safe-bottom);
 792: }
 793: .account-settings-header {
 794:   padding: 18px 20px; flex-shrink: 0;
 795:   display: flex; align-items: flex-start; justify-content: space-between; gap: 16px;
 796:   border-bottom: 1px solid var(--c-border);
 797:   background: linear-gradient(145deg, rgba(36,168,125,0.07), transparent 65%);
 798: }
 799: .account-settings-heading { display: flex; align-items: flex-start; gap: 12px; min-width: 0; }
 800: .account-settings-heading > span {
 801:   width: 40px; height: 40px; flex-shrink: 0; display: inline-flex; align-items: center; justify-content: center;
 802:   border: 1px solid rgba(36,168,125,0.18); border-radius: 12px;
 803:   background: rgba(36,168,125,0.10); color: var(--c-accent);
 804: }
 805: .account-settings-heading h2 {
 806:   margin-top: 2px; color: var(--c-text-1);
 807:   font-size: var(--text-section-title); line-height: var(--leading-section); font-weight: 700;
 808: }
 809: .account-settings-heading > div > p:last-child {
 810:   margin-top: 3px; color: var(--c-text-3);
 811:   font-size: var(--text-meta); line-height: var(--leading-meta);
 812: }
 813: .account-settings-tabs {
 814:   flex-shrink: 0; padding: 8px 12px; display: grid; grid-template-columns: repeat(2, 1fr); gap: 8px;
 815:   border-bottom: 1px solid var(--c-border); background: var(--c-surface-dark);
 816: }
 817: .account-settings-tabs button {
 818:   min-height: var(--touch); padding: 0 14px; display: inline-flex; align-items: center; justify-content: center; gap: 8px;
 819:   border: 1px solid transparent; border-radius: var(--r-md); background: transparent;
 820:   color: var(--c-text-3); font: inherit; font-size: var(--text-secondary); font-weight: 600; cursor: pointer;
 821: }
 822: .account-settings-tabs button.active {
 823:   border-color: rgba(36,168,125,0.22); background: rgba(36,168,125,0.10); color: var(--c-accent);
 824: }
 825: .account-settings-content {
 826:   flex: 1; overflow-y: auto; overscroll-behavior: contain;
 827:   padding: 20px 16px calc(20px + var(--safe-bottom));
 828: }
 829: .account-settings-content > .auth-feedback { margin-bottom: 20px; }
 830: .settings-panel { display: flex; flex-direction: column; gap: 24px; }
 831: .settings-section-header { display: flex; align-items: flex-start; gap: 12px; }
 832: .settings-section-header > span {
 833:   width: 38px; height: 38px; flex-shrink: 0; display: inline-flex; align-items: center; justify-content: center;
 834:   border-radius: 12px; background: var(--c-surface-2); color: var(--c-text-2);
 835: }
 836: .settings-section-header h3 {
 837:   color: var(--c-text-1); font-size: var(--text-card-title); line-height: var(--leading-card); font-weight: 700;
 838: }
 839: .settings-section-header p {
 840:   margin-top: 3px; color: var(--c-text-3); font-size: var(--text-meta); line-height: var(--leading-meta);
 841: }
 842: .settings-action-row {
 843:   padding: 16px; display: grid; gap: 12px;
 844:   border: 1px solid var(--c-border); border-radius: var(--r-lg); background: var(--c-surface-dark);
 845: }
 846: .settings-action-row > .btn-secondary { width: 100%; min-height: var(--touch); }
 847: .pwa-install-quick {
 848:   width: 100%; min-height: 40px; padding: 0 11px; display: flex; align-items: center; justify-content: center; gap: 9px;
 849:   overflow: hidden; white-space: nowrap; border: 1px solid rgba(var(--club-accent-rgb, 29, 158, 117), 0.24);
 850:   border-radius: var(--r-md); background: rgba(var(--club-accent-rgb, 29, 158, 117), 0.10);
 851:   color: var(--c-accent); font: inherit; font-size: var(--text-meta); font-weight: 700; cursor: pointer;
 852: }
 853: .pwa-install-quick:hover { background: rgba(var(--club-accent-rgb, 29, 158, 117), 0.16); }
 854: .pwa-install-quick.compact { width: 40px; min-width: 40px; padding: 0; }
 855: .pwa-access-card {
 856:   padding: 18px; display: flex; flex-direction: column; gap: 16px;
 857:   border: 1px solid rgba(var(--club-accent-rgb, 29, 158, 117), 0.24); border-radius: var(--r-lg);
 858:   background: linear-gradient(145deg, rgba(var(--club-accent-rgb, 29, 158, 117), 0.09), var(--c-surface-dark) 62%);
 859: }
 860: .pwa-access-heading { display: flex; align-items: flex-start; gap: 12px; }
 861: .pwa-access-heading > span {
 862:   width: 40px; height: 40px; flex-shrink: 0; display: inline-flex; align-items: center; justify-content: center;
 863:   border-radius: 12px; background: rgba(var(--club-accent-rgb, 29, 158, 117), 0.13); color: var(--c-accent);
 864: }
 865: .pwa-access-heading h3 { color: var(--c-text-1); font-size: var(--text-card-title); line-height: var(--leading-card); font-weight: 700; }
 866: .pwa-access-heading p, .pwa-manual-guidance p {
 867:   margin-top: 4px; color: var(--c-text-3); font-size: var(--text-meta); line-height: var(--leading-meta);
 868: }
 869: .pwa-installed-status, .pwa-manual-guidance {
 870:   min-height: 44px; padding: 11px 13px; display: flex; align-items: center; gap: 9px;
 871:   border-radius: var(--r-md); font-size: var(--text-meta); line-height: var(--leading-meta);
 872: }
 873: .pwa-installed-status { background: rgba(var(--club-accent-rgb, 29, 158, 117), 0.12); color: var(--c-accent); font-weight: 600; }
 874: .pwa-manual-guidance { align-items: flex-start; border: 1px solid var(--c-border); background: var(--c-surface-2); color: var(--c-text-2); }
 875: .pwa-manual-guidance p { margin: 0; color: inherit; }
 876: .pwa-access-actions { display: grid; gap: 8px; }
 877: .pwa-access-actions > button, .pwa-access-card > .btn-primary { width: 100%; justify-content: center; }
 878: .pwa-access-feedback { margin: -4px 0 0; color: var(--c-accent); font-size: var(--text-meta); line-height: var(--leading-meta); }
 879: .settings-signout-card {
 880:   padding: 16px; display: flex; flex-direction: column; align-items: stretch; gap: 14px;
 881:   border: 1px solid rgba(224,82,82,0.20); border-radius: var(--r-lg); background: rgba(224,82,82,0.055);
 882: }
 883: .settings-signout-card h3 { color: var(--c-text-1); font-size: var(--text-card-title); line-height: var(--leading-card); font-weight: 700; }
 884: .settings-signout-card p { margin-top: 4px; color: var(--c-text-3); font-size: var(--text-meta); line-height: var(--leading-meta); }
 885: .settings-signout-button { justify-content: center; color: var(--tone-danger); border-color: rgba(224,82,82,0.25); }
 886: .settings-loading {
 887:   min-height: 160px; display: flex; align-items: center; justify-content: center; gap: 10px;
 888:   color: var(--c-text-3); font-size: var(--text-secondary); line-height: var(--leading-small);
 889: }
 890: .settings-invite-card {
 891:   padding: 16px; border: 1px solid var(--c-border); border-radius: var(--r-lg);
 892:   background: var(--c-surface-dark);
 893: }
 894: .settings-invite-copy { display: flex; align-items: flex-start; gap: 12px; }
 895: .settings-invite-copy > span {
 896:   width: 38px; height: 38px; flex-shrink: 0; display: inline-flex; align-items: center; justify-content: center;
 897:   border-radius: 12px; background: rgba(36,168,125,0.10); color: var(--c-accent);
 898: }
 899: .settings-invite-copy h4, .settings-confirm h4 {
 900:   color: var(--c-text-1); font-size: var(--text-card-title); line-height: var(--leading-card); font-weight: 700;
 901: }
 902: .settings-invite-copy p, .settings-confirm p {
 903:   margin-top: 3px; color: var(--c-text-3); font-size: var(--text-meta); line-height: var(--leading-meta);
 904: }
 905: .settings-code-row { display: grid; grid-template-columns: minmax(0, 1fr) 44px 44px; gap: 8px; margin-top: 16px; }
 906: .settings-code-row output {
 907:   min-height: var(--touch); padding: 0 12px; display: flex; align-items: center; justify-content: center;
 908:   overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
 909:   border: 1px solid var(--c-border-strong); border-radius: var(--r-md); background: var(--c-surface-2);
 910:   color: var(--c-text-1); font-size: 16px; line-height: 20px; font-weight: 700; letter-spacing: 0.10em;
 911: }
 912: .settings-confirm {
 913:   padding: 16px; display: flex; flex-direction: column; gap: 16px;
 914:   border: 1px solid rgba(240,180,77,0.26); border-radius: var(--r-lg); background: rgba(240,180,77,0.07);
 915: }
 916: .settings-confirm > div:last-child { display: flex; flex-direction: column-reverse; gap: 8px; }
 917: 
 918: @media (min-width: 640px) {
 919:   .account-settings-backdrop { align-items: center; padding: 24px; }
 920:   .account-settings-dialog {
