 42: // Date -> "YYYY-MM-DD" en heure locale (pas .toISOString(), qui convertit en
 43: // UTC et peut faire tomber la date un jour trop tôt/tard selon le fuseau).
 44: function toLocalDateStr(d) {
 45:   return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
 46: }
