 48: // Système sémantique : couleur = dimension mesurée, pas le statut.
 49: // Vert → forme/récup | Bleu → charge/ACWR | Ambre → fatigue/alerte | Rouge → danger
 50: function getGreeting() {
 51:   const h = new Date().getHours();
 52:   if (h < 12) return "Bonjour";
 53:   if (h < 18) return "Bon après-midi";
 54:   return "Bonsoir";
 55: }
