132: // Mini-courbe des 4-6 dernières semaines de charge — on voit la tendance
133: // d'un coup d'œil au lieu d'un seul chiffre statique.
134: const MiniSparkline = memo(({ data, color }) => {
135:   if (data.length < 2) return null;
136:   return (
137:     <div style={{ width: "100%", height: 22 }}>
138:       <ResponsiveContainer width="100%" height="100%">
139:         <LineChart data={data} margin={{ top: 2, right: 2, bottom: 2, left: 2 }}>
140:           <Line type="monotone" dataKey="v" stroke={color} strokeWidth={1.5} dot={false} isAnimationActive={false} />
141:         </LineChart>
142:       </ResponsiveContainer>
143:     </div>
144:   );
145: });
