147: function AthleteStatusCard({ athlete, weeklyCharge, currentWeek, currentYear, injuries, sessions, wellnessToday, onNavigate }) {
148:   const metrics   = useMemo(
149:     () => getAthleteMetricsForWeek(athlete.id, weeklyCharge, currentWeek, wellnessToday ? [wellnessToday] : [], sessions),
150:     [athlete.id, weeklyCharge, currentWeek, wellnessToday, sessions]
151:   );
152:   const status    = useMemo(
153:     () => buildDailyState({ wellness: wellnessToday, metrics }),
154:     [wellnessToday, metrics]
155:   );
156:   const activeInj = (injuries ?? []).filter(i => i.athleteId === athlete.id && i.status !== "résolu");
157:   const weekSess = sessions.filter(s =>
158:     matchesISOWeek(s, currentWeek, currentYear) && s.athleteIds?.includes(athlete.id)
159:   );
160:   const doneCount = weekSess.filter(s => s.validations?.find(v => v.athleteId === athlete.id && v.status === "done")).length;
161:   const hasCharge = weeklyCharge.some(row =>
162:     row.athleteId === athlete.id && matchesISOWeek(row, currentWeek, currentYear)
163:   );
164:   const isAtRisk  = false;
165: 
166:   const readColor = status.color;
167:   const acwrCol   = "#378ADD";
168:   const fatCol    = "#14B8A6";
169: 
170:   const sparkData = useMemo(() =>
171:     weeklyCharge.filter(w => w.athleteId === athlete.id).sort((a, b) => a.week - b.week).slice(-6).map(w => ({ v: w.rawLoad })),
172:   [weeklyCharge, athlete.id]);
173: 
174:   return (
175:     <div
176:       className={["card card-hover tap-feedback p-3.5 flex flex-col gap-2.5 cursor-pointer", isAtRisk ? "pulse-danger-bg" : ""].join(" ")}
177:       onClick={() => onNavigate("athletes")}
178:     >
179:       {/* Header avec avatar en dégradé */}
180:       <div className="flex items-center gap-2.5">
181:         <div
182:           className="w-9 h-9 rounded-xl flex items-center justify-center text-white text-[12px] font-bold flex-shrink-0 shadow-sm"
183:           style={{ background: `linear-gradient(135deg, ${status.color} 0%, ${status.color}CC 100%)` }}
184:         >
185:           {initialsFromName(athlete.name)}
186:         </div>
187:         <div className="flex-1 min-w-0">
188:           <p className="text-[12.5px] font-semibold truncate leading-tight" style={{ color: "var(--c-text-1)" }}>
189:             {athlete.name.split(" ")[0]}
190:           </p>
191:           <p className="meta-text truncate">{athlete.mainDiscipline ?? "—"}</p>
192:         </div>
193:         {/* Dot statut */}
194:         <div
195:           className="w-2 h-2 rounded-full flex-shrink-0"
196:           style={{ background: status.color, boxShadow: `0 0 5px ${status.color}` }}
197:         />
198:       </div>
199: 
200:       <div className="rounded-xl px-3 py-2" style={{ background: `${status.color}0D`, border: `1px solid ${status.color}20` }}>
201:         <p className="text-[12px] font-semibold leading-5" style={{ color: "var(--c-text-1)" }}>{status.plainHeadline ?? status.label}</p>
202:         {status.score != null && <p className="mt-0.5 text-[12px] leading-4" style={{ color: "var(--c-text-2)" }}>{status.watch?.[0] ?? status.helps?.[0] ?? "Ressenti renseigné aujourd'hui."}</p>}
203:       </div>
204: 
205:       {/* Métriques — 3 valeurs + mini barres */}
206:       {(hasCharge || status.score != null) ? (
207:         <div className="grid grid-cols-3 gap-1.5">
208:           {[
209:             { lbl: "Ressenti", val: status.score ?? "—", col: readColor, pct: status.score ?? 0 },
210:             { lbl: "Semaine", val: metrics.load7 ?? "—", col: acwrCol, pct: metrics.load7 && metrics.load28 ? Math.min(100, (metrics.load7 / metrics.load28) * 100) : 0 },
211:             { lbl: "Habitude", val: metrics.load28 ?? "—", col: fatCol, pct: metrics.load28 ? 100 : 0 },
212:           ].map(s => (
213:             <div key={s.lbl} className="bg-[var(--c-surface-2)] rounded-xl px-1.5 py-2 text-center">
214:               <p
215:                 className="text-[14px] font-bold leading-none"
216:                 style={{ color: s.col, fontVariantNumeric: "tabular-nums" }}
217:               >
218:                 {s.val}
219:               </p>
220:               <p className="text-[12px] font-bold uppercase tracking-wide mt-1" style={{ color: "var(--c-text-2)" }}>
221:                 {s.lbl}
222:               </p>
223:               <div className="mt-1.5 h-0.5 bg-[var(--c-surface-3)] rounded-full overflow-hidden">
224:                 <div
225:                   className="h-full rounded-full transition-all duration-500"
226:                   style={{ width: `${Math.max(3, s.pct)}%`, background: s.col, opacity: 0.75 }}
227:                 />
228:               </div>
229:             </div>
230:           ))}
231:         </div>
232:       ) : (
233:         <div className="bg-[var(--c-surface-2)] rounded-xl px-3 py-2 text-center">
234:           <p className="meta-text font-medium">Pas encore de données</p>
235:         </div>
236:       )}
237: 
238:       <p className="text-[12px] font-medium leading-snug" style={{ color: "var(--c-text-2)" }}>
239:         {status.loadContext ?? status.summary}
240:       </p>
241: 
242:       {/* Tendance charge — 6 dernières semaines */}
243:       {hasCharge && sparkData.length >= 2 && <MiniSparkline data={sparkData} color={acwrCol} />}
244: 
245:       {/* Badges blessure / séances */}
246:       {(activeInj.length > 0 || weekSess.length > 0) && (
247:         <div className="flex items-center gap-1.5 flex-wrap">
248:           {activeInj.length > 0 && (
249:             <span
250:               className="flex items-center gap-1 text-[12px] font-bold border px-2 py-0.5 rounded-full"
251:               style={{ color: "var(--tone-warning)", background: "rgba(239,159,39,0.15)", borderColor: "#EF9F27" }}
252:             >
253:               <HeartPulse size={8} /> {activeInj.length} blessure{activeInj.length > 1 ? "s" : ""}
254:             </span>
255:           )}
256:           {weekSess.length > 0 && (
257:             <span
258:               className="flex items-center gap-1 text-[12px] font-semibold border px-2 py-0.5 rounded-full"
259:               style={{ color: "var(--c-text-2)", background: "var(--c-surface-3)", borderColor: "var(--c-border)" }}
260:             >
261:               <CheckCircle size={9} /> {doneCount}/{weekSess.length}
262:             </span>
263:           )}
264:         </div>
265:       )}
266:     </div>
267:   );
268: }
