295:           <p className="card-subtitle mt-0.5">
296:             {items.length > 0 ? "Commence par le haut : chaque ligne ouvre directement le bon écran." : "Aucune action urgente pour le moment"}
297:           </p>
298:         </div>
299:         {items.length > 0 && (
300:           <span className="text-[12px] font-bold px-2 py-0.5 rounded-full chip chip-warning">
301:             {items.length} action{items.length > 1 ? "s" : ""}
302:           </span>
303:         )}
304:       </div>
305:       {shown.length === 0 ? (
306:         <div className="px-5 py-8 flex items-center gap-3">
307:           <div className="w-9 h-9 rounded-xl flex items-center justify-center flex-shrink-0" style={{ background: "rgba(29,158,117,0.08)" }}>
308:             <CheckCircle size={16} color="#1D9E75" strokeWidth={2} />
309:           </div>
310:           <p className="text-[12.5px] font-medium" style={{ color: "var(--c-text-2)" }}>
311:             Les alertes, réponses, présences, validations et compétitions proches sont à jour.
312:           </p>
313:         </div>
314:       ) : (
315:         <div className="divide-y divide-[color:var(--c-border)]">
316:           {shown.map(item => (
