321:               className="w-full px-5 py-3.5 flex items-start gap-3 text-left hover:bg-[var(--c-surface-2)] transition-colors border-l-4"
322:               style={{ borderLeftColor: item.color }}
323:             >
324:               <div className="w-8 h-8 rounded-xl flex items-center justify-center flex-shrink-0 mt-0.5" style={{ background: `${item.color}18` }}>
325:                 <CoachFeedIcon icon={item.icon} color={item.color} />
326:               </div>
327:               <span className="flex-1 min-w-0">
328:                 <span className="block text-[13px] font-semibold" style={{ color: "var(--c-text-1)" }}>{item.label ?? "À vérifier"}</span>
329:                 <span className="block text-[12.5px] leading-relaxed mt-0.5" style={{ color: "var(--c-text-2)" }}>{item.sentence}</span>
330:               </span>
331:               <ChevronRight size={14} className="flex-shrink-0 mt-1" style={{ color: "var(--c-text-3)" }} />
332:             </button>
333:           ))}
334:         </div>
335:       )}
336:       {items.length > limit && (
337:         <button
338:           type="button"
