343:           {expanded
344:             ? "Réduire la liste"
345:             : `Voir ${items.length - limit} autre${items.length - limit > 1 ? "s" : ""} action${items.length - limit > 1 ? "s" : ""}`}
346:         </button>
347:       )}
348:     </div>
349:   );
350: }
