352: // ─── Composant principal ──────────────────────────────────────────────────────
353: function Dashboard({
354:   onNavigate,
355:   club,
356:   clubLoading = false,
357:   onOpenClubSettings,
358:   onInvite,
359:   onDemo,
360: }) {
361:   const { clubId, profile } = useAuth();
362:   const today       = new Date();
363:   const currentWeek = getISOWeek(today);
364:   const currentYear = getISOWeekYear(today);
365:   const previousWeekDate = new Date(today);
366:   previousWeekDate.setDate(previousWeekDate.getDate() - 7);
367:   const previousWeek = getISOWeek(previousWeekDate);
368:   const previousYear = getISOWeekYear(previousWeekDate);
369: 
370:   const [athletes,     setAthletes]     = useState([]);
371:   const [weeklyCharge, setWeeklyCharge] = useState([]);
372:   const [sessions,     setSessions]     = useState([]);
373:   const [alerts,       setAlerts]       = useState([]);
374:   const [competitions, setCompetitions] = useState([]);
375:   const [injuries,     setInjuries]     = useState([]);
376:   const [goals,        setGoals]        = useState([]);
377:   const [wellnessRows, setWellnessRows] = useState([]);
378:   const [loading,      setLoading]      = useState(true);
379:   const [error,        setError]        = useState(null);
380: 
381:   // ═══ Chargement (identique à l'original — aucune requête modifiée) ═════════
382:   const fetchAll = useCallback(async () => {
383:     if (!clubId) return;
384:     try {
385:       setLoading(true); setError(null);
386:       const requestDate = new Date();
387: 
388:       const [athletesRes, sessionsRes, alertsRes, compsRes, injuriesRes, goalsRes, wellnessRes] = await Promise.all([
389:         supabase.from("athletes").select("id, name, main_discipline, profile_data, group_name, user_id").eq("club_id", clubId),
390:         supabase.from("sessions").select("*, session_athletes(*)").eq("club_id", clubId),
391:         supabase.from("alerts").select("id, is_read, severity, type").eq("club_id", clubId),
392:         supabase.from("competitions").select("id, name, date, competition_athletes(athlete_id)").eq("club_id", clubId).gte("date", toLocalDateStr(requestDate)).order("date").limit(3),
393:         supabase.from("injuries").select("id, athlete_id, name, intensity, status, location").eq("status", "actif"),
394:         supabase.from("athlete_goals").select("*").eq("club_id", clubId).eq("achieved", false),
395:         supabase.from("athlete_wellness").select("athlete_id, date, sleep, energy, soreness, mood, stress, notes").eq("club_id", clubId).eq("date", toLocalDateStr(requestDate)),
396:       ]);
397: 
398:       if (athletesRes.error) throw athletesRes.error;
399: 
400:       const athleteIds = athletesRes.data.map(a => a.id);
401:       // Charge hebdomadaire calculée côté serveur (vue weekly_charge, voir
402:       // migration 20260726120000) — plus de recalcul JS à partir des séances.
403:       const chargeRes  = athleteIds.length
404:         ? await supabase.from("weekly_charge").select("*").in("athlete_id", athleteIds)
405:         : { data: [] };
406: 
407:       const mappedSessions = (sessionsRes.data ?? []).map(s => {
408:         const rows = s.session_athletes ?? [];
409:         return {
410:           id: s.id, week: s.week, day: s.day, sessionDate: s.session_date,
411:           time: s.time, type: s.type, category: s.category, trainingFocus: s.training_focus, title: s.title,
412:           durationMinutes: s.duration_minutes, createdBy: s.created_by,
413:           lifecycleStatus: s.lifecycle_status ?? "planned",
414:           createdByAthlete: s.created_by != null && athletesRes.data.some(a => a.user_id === s.created_by),
415:           athleteIds:   rows.map(v => v.athlete_id),
416:           validations:  rows.map(v => ({ athleteId: v.athlete_id, status: v.status, feeling: v.feeling, rpe: v.rpe, comment: v.comment, actualDurationMinutes: v.actual_duration_minutes, durationSource: v.duration_source, rsvpStatus: v.rsvp_status, rsvpNote: v.rsvp_note, coachNote: v.coach_note })),
417:         };
418:       });
419: 
420:       const charge = (chargeRes.data ?? []).map(c => ({
421:         athleteId: c.athlete_id, week: c.week, isoYear: c.iso_year, rawLoad: c.raw_load,
422:         dailyLoads: c.daily_loads ?? [], knownDays: c.known_days ?? 0,
423:         unknownDays: c.unknown_days ?? 0, estimatedDays: c.estimated_days ?? 0,
424:       }));
425: 
426:       const mappedAthletes = athletesRes.data.map(a => ({
427:         id: a.id, name: a.name, mainDiscipline: a.main_discipline,
428:         avatar: a.profile_data?.avatar ?? initialsFromName(a.name),
429:         group: a.group_name,
430:       }));
431:       setAthletes(mappedAthletes);
432:       setWeeklyCharge(charge);
433:       setSessions(mappedSessions);
434:       setAlerts(alertsRes.data ?? []);
435: 
436:       const mappedComps = (compsRes.data ?? []).map(c => ({
437:         id: c.id, name: c.name, date: c.date,
438:         athleteIds: (c.competition_athletes ?? []).map(x => x.athlete_id),
439:       }));
440:       setCompetitions(mappedComps);
441:       // Les lignes brutes de Supabase sont en snake_case (athlete_id) —
442:       // sans ce mapping, AthleteStatusCard (i.athleteId) et le fil du coach
443:       // ne matchaient jamais aucun athlète : le badge "blessure" sur les
444:       // cartes du groupe ne s'affichait donc jamais, silencieusement.
445:       setInjuries((injuriesRes.data ?? []).map(i => ({
446:         id: i.id, athleteId: i.athlete_id, name: i.name,
447:         intensity: i.intensity, status: i.status, location: i.location,
448:       })));
449:       setGoals(goalsRes.data ?? []);
450:       setWellnessRows((wellnessRes.data ?? []).map(row => ({
451:         ...row,
452:         athleteId: row.athlete_id,
453:       })));
454: 
455:       if (mappedComps.length > 0) {
456:         await checkUpcomingCompetitions(clubId, mappedComps);
457:         const in7days = new Date(Date.now() + 7 * 86400000);
458:         for (const comp of mappedComps) {
459:           if (new Date(comp.date) <= in7days) {
460:             await notifyAthleteCompetitionReminder(clubId, comp);
461:           }
462:         }
463:       }
464:       if (mappedAthletes.length > 0 && charge.length > 0) {
465:         await checkAndAlertACWR(clubId, mappedAthletes, charge, currentWeek);
466:       }
467:       if (mappedAthletes.length > 0) {
468:         await checkWeeklyRecap(clubId, mappedAthletes, mappedSessions, currentWeek, profile?.id ?? null, currentYear);
469:         await checkWeeklyReports(clubId, mappedAthletes, currentWeek, profile?.id ?? null, currentYear);
470:       }
471:     } catch (err) {
472:       setError(err.message ?? "Erreur inconnue");
473:     } finally { setLoading(false); }
474:   }, [clubId, currentWeek, currentYear, profile?.id]);
475: 
476:   useEffect(() => { fetchAll(); }, [fetchAll]);
477: 
478:   // ═══ Métriques (identique à l'original) ════════════════════════════════════
479:   const metrics = useMemo(() => {
480:     const currentCharges = weeklyCharge.filter(row => matchesISOWeek(row, currentWeek, currentYear));
481:     const avgCharge = currentCharges.length > 0
482:       ? Math.round(currentCharges.reduce((s, w) => s + w.rawLoad, 0) / currentCharges.length)
483:       : null;
484:     const prevCharges = weeklyCharge.filter(row => matchesISOWeek(row, previousWeek, previousYear));
485:     const prevAvg = prevCharges.length > 0
486:       ? Math.round(prevCharges.reduce((s, w) => s + w.rawLoad, 0) / prevCharges.length)
487:       : null;
488:     const trend = avgCharge && prevAvg ? Math.round(((avgCharge - prevAvg) / prevAvg) * 100) : null;
489:     const actifs = currentCharges.length;
490:     const unreadAlerts = alerts.filter(a => !a.is_read).length;
491:     const weekSessions = sessions.filter(session => matchesISOWeek(session, currentWeek, currentYear));
492:     const totalExpected = weekSessions.reduce((s, sess) => s + sess.athleteIds.length, 0);
493:     const totalDone = weekSessions.reduce((s, sess) => s + (sess.validations?.filter(v => v.status === "done").length ?? 0), 0);
494:     const validationRate = totalExpected > 0 ? Math.round((totalDone / totalExpected) * 100) : null;
495:     const pendingAthleteSession = sessions.filter(s => s.createdByAthlete).length;
496:     return { avgCharge, trend, actifs, unreadAlerts, validationRate, pendingAthleteSession };
497:   }, [weeklyCharge, sessions, alerts, currentWeek, currentYear, previousWeek, previousYear]);
498: 
499:   // Les anciens blocs "surcharge"/"blessés" (chiffres bruts) sont remplacés
500:   // par ce fil narrativisé et priorisé — voir src/utils/coachFeed.js.
501:   const coachFeed = useMemo(
502:     () => buildCoachFeed({ athletes, weeklyCharge, sessions, injuries, competitions, alerts, currentWeek, currentYear }),
503:     [athletes, weeklyCharge, sessions, injuries, competitions, alerts, currentWeek, currentYear]
504:   );
505: 
506:   const groupDailyState = useMemo(
507:     () => buildGroupDailyState(athletes, wellnessRows),
508:     [athletes, wellnessRows]
509:   );
510: 
511:   const setupProgress = useMemo(() => getClubSetupProgress(buildClubSetupSteps({
512:     club,
513:     athleteCount: athletes.length,
514:     sessionCount: sessions.length,
515:   })), [athletes.length, club, sessions.length]);
516: 
517:   const visibleAthletes = useMemo(() => athletes.slice(0, 6), [athletes]);
518:   const hiddenAthleteCount = Math.max(0, athletes.length - visibleAthletes.length);
519: 
520:   const recentFeedbacks = useMemo(() => {
521:     const results = [];
522:     sessions.forEach(s => {
523:       (s.validations ?? []).forEach(v => {
524:         if (!v.status) return;
525:         const athlete = athletes.find(a => a.id === v.athleteId);
526:         if (!athlete) return;
527:         results.push({ session: s, validation: v, athlete });
528:       });
529:     });
530:     return results.filter(f => f.validation.feeling || f.validation.comment).slice(0, 5);
531:   }, [sessions, athletes]);
532: 
533:   const firstName = profile?.name?.split(" ")[0] ?? "Coach";
534: 
535:   if (loading) return <LoadingState message="Chargement du dashboard…" />;
536:   if (error)   return <ErrorState  message={error} onRetry={fetchAll} />;
537: 
538:   return (
539:     <div className="page-container py-4 md:py-6 space-y-4 md:space-y-5 max-w-7xl mx-auto animate-slide-up">
540:       <PageHeader
541:         eyebrow="VUE COACH"
542:         title={`${getGreeting()}, ${firstName}`}
543:         description="Les priorités et l’état de ton groupe en un coup d’œil."
544:         actions={(
545:           <button type="button" className="btn-primary" onClick={() => onNavigate("planning")}>
546:             Planifier une séance
547:             <ChevronRight size={16} aria-hidden="true" />
548:           </button>
549:         )}
550:       />
551: 
552:       {profile?.role === "head_coach" && !clubLoading && setupProgress < 100 && (
553:         <ClubOnboardingCard
554:           club={club}
555:           athleteCount={athletes.length}
556:           sessionCount={sessions.length}
557:           onBranding={onOpenClubSettings}
558:           onInvite={onInvite}
559:           onPlanning={() => onNavigate("planning")}
560:           onDemo={onDemo}
561:         />
562:       )}
563: 
564:       {/* Le coach voit d'abord ce qui demande une action. Les statistiques
565:           restent entièrement disponibles juste après. */}
566:       {/* ── Synthèse de la semaine ────────────────────────────────────────── */}
567:       <div
568:         className="rounded-3xl overflow-hidden relative"
569:         style={{ background: "#0A1810" }}
570:       >
571:         {/* Halo vert décoratif */}
572:         <div
573:           className="absolute -right-12 -top-12 w-48 h-48 rounded-full pointer-events-none"
574:           style={{ background: "radial-gradient(circle, rgba(29,158,117,0.15) 0%, transparent 70%)" }}
575:         />
576:         {/* Grille fine déco */}
577:         <div
578:           className="absolute inset-0 opacity-[0.04] pointer-events-none"
579:           style={{
580:             backgroundImage: "linear-gradient(rgba(29,158,117,0.8) 1px, transparent 1px), linear-gradient(90deg, rgba(29,158,117,0.8) 1px, transparent 1px)",
581:             backgroundSize: "40px 40px",
582:           }}
583:         />
584: 
585:         <div className="relative p-5 md:p-6">
586:           {/* Ligne de contexte */}
587:           <div className="flex items-start justify-between gap-4 flex-wrap mb-5">
588:             <div>
589:               <p className="text-[12px] font-bold uppercase tracking-[0.12em] mb-1" style={{ color: "rgba(255,255,255,0.68)" }}>
590:                 {today.toLocaleDateString("fr-BE", { weekday: "long", day: "numeric", month: "long" })}
591:               </p>
592:               <h2 className="text-[20px] md:text-[22px] font-bold text-white tracking-tight leading-tight">Synthèse de la semaine</h2>
593:               <p className="text-[12px] font-medium mt-1" style={{ color: "rgba(255,255,255,0.68)" }}>
594:                 Semaine {currentWeek} · {athletes.length} athlète{athletes.length > 1 ? "s" : ""} suivi{athletes.length > 1 ? "s" : ""}
595:               </p>
596:             </div>
597: 
598:             {/* Badge séances en attente */}
599:             {metrics.pendingAthleteSession > 0 && (
600:               <button
601:                 onClick={() => onNavigate("planning")}
602:                 className="flex items-center gap-2 px-3 py-2 rounded-xl text-[12px] font-semibold transition-all tap-feedback"
603:                 style={{
604:                   background: "rgba(255,255,255,0.07)",
605:                   border: "0.5px solid rgba(255,255,255,0.12)",
606:                   color: "rgba(255,255,255,0.75)",
607:                 }}
608:               >
609:                 {metrics.pendingAthleteSession} à valider
610:                 <ChevronRight size={13} />
611:               </button>
612:             )}
613:           </div>
614: 
615:           {/* 3 stats inline dans le hero */}
616:           <div className="grid grid-cols-3 gap-2">
617:             {[
618:               {
619:                 label: "Check-ins du jour",
620:                 value: `${groupDailyState.completed}/${athletes.length}`,
621:                 color: "#1D9E75",
622:               },
623:               {
624:                 label: "Bon ressenti",
625:                 value: groupDailyState.favorable,
626:                 color: "var(--tone-success)",
627:                 sub: "d'après leurs réponses",
628:               },
629:               {
630:                 label: "À discuter",
631:                 value: groupDailyState.attention,
632:                 color: groupDailyState.attention > 0 ? "#F2C46D" : "#69C5F7",
633:                 sub: "sans prédire un risque",
634:               },
635:             ].map(s => (
636:               <div
637:                 key={s.label}
638:                 className="rounded-2xl px-3 py-3 text-center"
639:                 style={{
640:                   background: "rgba(255,255,255,0.04)",
641:                   border: "0.5px solid rgba(255,255,255,0.07)",
642:                 }}
643:               >
644:                 <p
645:                   className="text-[20px] font-bold leading-none"
646:                   style={{ color: s.color, fontVariantNumeric: "tabular-nums", letterSpacing: "-0.03em" }}
647:                 >
648:                   {s.value}
649:                 </p>
650:                 <p className="text-[12px] font-bold uppercase tracking-[0.07em] mt-1.5" style={{ color: "rgba(255,255,255,0.72)" }}>
651:                   {s.label}
652:                 </p>
653:                 {s.sub && (
654:                   <p className="text-[12px] mt-0.5" style={{ color: "rgba(255,255,255,0.62)" }}>{s.sub}</p>
655:                 )}
656:               </div>
657:             ))}
658:           </div>
659:         </div>
660:       </div>
661: 
662:       {/* ── Priorités coach ──────────────────────────────────────────────── */}
663:       {/* ── KPIs — icône + liseré + glow au survol ────────────────────────── */}
664:       <div data-dashboard-priority-queue>
665:         <CoachFeedSection items={coachFeed} onNavigate={onNavigate} limit={4} />
666:       </div>
667: 
668:       <section className="space-y-3" aria-labelledby="overview-title">
669:         <div>
670:           <h2 id="overview-title" className="section-title">Vue d'ensemble</h2>
671:           <p className="secondary-text mt-0.5">Les indicateurs essentiels de la semaine.</p>
672:         </div>
673:         <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
674:           <MetricCard
675:             icon={Users} label="Athlètes actifs" color="#1D9E75"
676:             value={metrics.actifs} sub={`/${athletes.length} total`}
677:             onClick={() => onNavigate("athletes")}
678:           />
679:           <MetricCard
680:             icon={Zap} label="Effort moyen du groupe" color="#378ADD"
681:             value={metrics.avgCharge ?? "—"}
682:             sub={metrics.trend == null ? "Comparaison indisponible" : metrics.trend > 10 ? `Plus que la semaine passée (+${metrics.trend} %)` : metrics.trend < -10 ? `Moins que la semaine passée (${metrics.trend} %)` : "Proche de la semaine passée"}
683:             badge={metrics.trend > 20 ? { label: "Hausse nette", color: "#D18A24" } : metrics.trend < -20 ? { label: "Baisse nette", color: "#378ADD" } : undefined}
684:           />
685:           <MetricCard
686:             icon={Bell} label="Alertes non lues" color="#E24B4A"
687:             value={metrics.unreadAlerts} sub="à traiter"
688:             onClick={() => onNavigate("alerts")}
689:           />
690:           <MetricCard
691:             icon={CheckCircle} label="Taux de validation" color="#EF9F27"
692:             value={metrics.validationRate != null ? `${metrics.validationRate}%` : "—"}
693:             sub="séances cette semaine"
694:           />
695:         </div>
696:       </section>
697: 
698:       {/* ── Layout 2 colonnes ─────────────────────────────────────────────── */}
699:       <div className="grid grid-cols-1 lg:grid-cols-3 gap-5">
700: 
701:         {/* ── État du groupe ─────────────────────────────────────────────── */}
702:         <div className="lg:col-span-2 space-y-3">
703:           <div className="flex items-center justify-between">
704:             <div>
705:               <h2 className="section-title">
706:                 État du groupe
707:               </h2>
708:               <p className="secondary-text mt-0.5">
709:                 Semaine {currentWeek} · données en temps réel
710:               </p>
711:             </div>
712:             <button
713:               onClick={() => onNavigate("charge")}
714:               className="flex items-center gap-1 text-[12px] font-semibold text-emerald-600 hover:text-emerald-700 transition-colors"
715:             >
716:               Détail <ArrowUpRight size={13} />
717:             </button>
718:           </div>
719: 
720:           {athletes.length === 0 ? (
721:             <div className="card p-10 text-center">
722:               <Users size={32} className="mx-auto mb-3" strokeWidth={1.5} style={{ color: "var(--c-text-4)" }} />
723:               <p className="text-[13px] font-semibold" style={{ color: "var(--c-text-2)" }}>Aucun athlète enregistré</p>
724:             </div>
725:           ) : (
726:             <div className="grid grid-cols-2 sm:grid-cols-3 gap-3">
727:               {visibleAthletes.map(a => (
728:                 <AthleteStatusCard
729:                   key={a.id}
730:                   athlete={a}
731:                   weeklyCharge={weeklyCharge}
732:                   currentWeek={currentWeek}
733:                   currentYear={currentYear}
734:                   injuries={injuries}
735:                   sessions={sessions}
736:                   wellnessToday={wellnessRows.find(row => row.athleteId === a.id)}
737:                   onNavigate={onNavigate}
738:                 />
739:               ))}
740:             </div>
741:           )}
742:           {hiddenAthleteCount > 0 && (
743:             <button
744:               type="button"
745:               onClick={() => onNavigate("athletes")}
746:               className="btn-secondary w-full sm:w-auto justify-center"
747:             >
748:               Voir les {athletes.length} athlètes
749:               <ArrowUpRight size={14} aria-hidden="true" />
750:             </button>
751:           )}
752:         </div>
753: 
754:         {/* ── Colonne droite ─────────────────────────────────────────────── */}
755:         <div className="space-y-4">
756: 
757:           {/* Prochaines compétitions */}
758:           {competitions.length > 0 && (
759:             <div className="card overflow-hidden">
760:               <div className="px-5 py-4 border-b border-[color:var(--c-border)] flex items-center justify-between">
761:                 <h3 className="card-title">Compétitions</h3>
762:                 <button
763:                   onClick={() => onNavigate("competitions")}
764:                   className="text-[12px] font-semibold text-emerald-600 hover:text-emerald-700 transition-colors flex items-center gap-1"
765:                 >
766:                   Voir tout <ArrowUpRight size={11} />
767:                 </button>
768:               </div>
769:               <div className="divide-y divide-[color:var(--c-border)]">
770:                 {competitions.map(c => {
771:                   const days = Math.round((new Date(c.date) - today) / (1000 * 60 * 60 * 24));
772:                   const isUrgent = days <= 7;
773:                   return (
774:                     <div key={c.id} className="px-5 py-3.5 flex items-center gap-3 hover:bg-[var(--c-surface-2)] transition-colors">
775:                       <div
776:                         className="w-10 h-10 rounded-2xl flex items-center justify-center flex-shrink-0"
777:                         style={{ background: isUrgent ? "rgba(226,75,74,0.08)" : "rgba(29,158,117,0.08)" }}
778:                       >
779:                         <Trophy size={15} color={isUrgent ? "#E24B4A" : "#1D9E75"} strokeWidth={2} />
780:                       </div>
781:                       <div className="flex-1 min-w-0">
782:                         <p className="text-[12.5px] font-semibold truncate" style={{ color: "var(--c-text-1)" }}>{c.name}</p>
783:                         <p className="meta-text mt-0.5">
784:                           {new Date(c.date).toLocaleDateString("fr-BE", { day: "numeric", month: "short" })}
785:                           {" · "}{c.athleteIds.length} athlète{c.athleteIds.length > 1 ? "s" : ""}
786:                         </p>
787:                       </div>
788:                       <span
789:                         className="text-[12px] font-bold px-2.5 py-1 rounded-xl flex-shrink-0"
790:                         style={{
791:                           background: isUrgent ? "rgba(224,82,82,0.15)" : "rgba(29,158,117,0.15)",
792:                           color:      isUrgent ? "#E24B4A" : "#1D9E75",
793:                         }}
794:                       >
795:                         {days === 0 ? "Auj." : `J-${days}`}
796:                       </span>
797:                     </div>
798:                   );
799:                 })}
800:               </div>
801:             </div>
802:           )}
803: 
804:           {/* Objectifs saison */}
805:           {goals.length > 0 && (
806:             <div className="card overflow-hidden">
807:               <div className="px-5 py-4 border-b border-[color:var(--c-border)] flex items-center justify-between">
808:                 <h3 className="card-title">Objectifs saison</h3>
809:                 <span className="text-[12px] font-bold px-2 py-0.5 rounded-full chip chip-success">
810:                   {goals.length} actif{goals.length > 1 ? "s" : ""}
811:                 </span>
812:               </div>
813:               <div className="divide-y divide-[color:var(--c-border)]">
814:                 {goals.slice(0, 5).map(g => {
815:                   const athlete  = athletes.find(a => a.id === g.athlete_id);
816:                   const daysLeft = g.deadline ? Math.round((new Date(g.deadline) - today) / (1000 * 60 * 60 * 24)) : null;
817:                   return (
818:                     <div key={g.id} className="px-5 py-3.5 flex items-center gap-3 hover:bg-[var(--c-surface-2)] transition-colors">
819:                       <div className="w-10 h-10 rounded-2xl flex items-center justify-center flex-shrink-0" style={{ background: "rgba(29,158,117,0.08)" }}>
820:                         <Target size={15} color="#1D9E75" strokeWidth={2} />
821:                       </div>
822:                       <div className="flex-1 min-w-0">
823:                         <div className="flex items-center gap-1.5 mb-0.5">
824:                           <p className="text-[12px] font-semibold" style={{ color: "var(--c-text-1)" }}>{athlete?.name?.split(" ")[0] ?? "?"}</p>
825:                           <span className="meta-text">·</span>
826:                           <p className="meta-text truncate" style={{ color: "var(--c-text-2)" }}>{g.discipline}</p>
827:                         </div>
828:                         <p className="text-[15px] font-bold text-emerald-600 leading-tight">{g.target_value}</p>
829:                       </div>
830:                       {daysLeft !== null && (
831:                         <span className="meta-text font-semibold flex-shrink-0">
832:                           {daysLeft > 0 ? `J-${daysLeft}` : "Échu"}
833:                         </span>
834:                       )}
835:                     </div>
836:                   );
837:                 })}
838:               </div>
839:             </div>
840:           )}
841: 
842:           {/* Feedbacks récents */}
843:           {recentFeedbacks.length > 0 && (
844:             <div className="card overflow-hidden">
845:               <div className="px-5 py-4 border-b border-[color:var(--c-border)]">
846:                 <h3 className="card-title">Feedbacks récents</h3>
847:                 <p className="card-subtitle mt-0.5">{recentFeedbacks.length} retour{recentFeedbacks.length > 1 ? "s" : ""} athlète</p>
848:               </div>
849:               <div className="divide-y divide-[color:var(--c-border)]">
850:                 {recentFeedbacks.map(({ session, validation, athlete }, i) => (
851:                   <div key={i} className="px-5 py-3.5 flex items-start gap-3 hover:bg-[var(--c-surface-2)] transition-colors">
852:                     {/* Avatar avec dégradé */}
853:                     <div
854:                       className="w-8 h-8 rounded-full flex items-center justify-center text-white text-[12px] font-bold flex-shrink-0 shadow-sm"
855:                       style={{ background: "linear-gradient(135deg, #1D9E75, #16826C)" }}
856:                     >
857:                       {initialsFromName(athlete.name)}
858:                     </div>
859:                     <div className="flex-1 min-w-0">
860:                       <div className="flex items-center gap-2 flex-wrap mb-1">
861:                         <span className="text-[12px] font-semibold" style={{ color: "var(--c-text-1)" }}>{athlete.name.split(" ")[0]}</span>
862:                         <span className="meta-text truncate max-w-[100px]">{session.title}</span>
863:                         <ValidationBadge status={validation.status} />
864:                       </div>
865:                       {validation.feeling != null && (
866:                         <div className="flex items-center gap-0.5 mb-1">
867:                           {Array.from({ length: 5 }).map((_, j) => (
868:                             <Star
869:                               key={j} size={10}
870:                               fill={j < validation.feeling ? "#EF9F27" : "none"}
871:                               color={j < validation.feeling ? "#EF9F27" : "rgba(255,255,255,0.18)"}
872:                             />
873:                           ))}
874:                         </div>
875:                       )}
876:                       {validation.comment && (
877:                         <p className="meta-text italic truncate">« {validation.comment} »</p>
878:                       )}
879:                     </div>
880:                     {validation.rpe != null && (
881:                       <span className="text-[12px] font-bold px-2 py-0.5 rounded-lg flex-shrink-0" style={{ background: "var(--c-surface-3)", color: "var(--c-text-2)" }}>
882:                         RPE {validation.rpe}
883:                       </span>
884:                     )}
885:                   </div>
886:                 ))}
887:               </div>
888:             </div>
889:           )}
890: 
891:           {/* État vide */}
892:           {competitions.length === 0 && goals.length === 0 && recentFeedbacks.length === 0 && (
893:             <div className="card p-8 text-center">
894:               <BarChart2 size={28} className="mx-auto mb-3" strokeWidth={1.5} style={{ color: "var(--c-text-4)" }} />
895:               <p className="text-[12px] font-semibold" style={{ color: "var(--c-text-2)" }}>Les données apparaîtront ici</p>
896:               <p className="meta-text mt-1">
897:                 Compétitions, objectifs et feedbacks s'afficheront au fur et à mesure.
898:               </p>
899:             </div>
900:           )}
901:         </div>
902:       </div>
903:     </div>
904:   );
905: }
