907: export default memo(Dashboard);  1: // ============================================================
  2: // AthleteOS — src/modules/Planning.jsx  ★ DESIGN PREMIUM DARK
  3: // Rendu adapté au dark mode : plus de bg-white / text-slate-*
  4: // hardcodés. Couleurs de catégorie recalibrées pour rester
  5: // lisibles et subtiles sur fond sombre (fill faible opacité +
  6: // texte clair teinté, jamais blanc pur sur noir).
