  8: 
  9: import { memo, useState, useMemo, useCallback, useEffect } from "react";
 10: import {
 11:   ChevronLeft, ChevronRight, Plus, X,
 12:   Clock, CalendarDays,
 13: } from "lucide-react";
 14: import { supabase }  from "../utils/supabaseClient";
 15: import { useAuth }   from "../hooks/useAuth";
 16: import LoadingState  from "../components/ui/LoadingState";
 17: import ErrorState    from "../components/ui/ErrorState";
 18: import { SegmentedTabs } from "../components/ui/premium";
 19: import { initialsFromName } from "../utils/helpers.js";
 20: import { captureError } from "../utils/sentry";
 21: import {
 22:   notifyAthleteNewSession,
 23:   notifyAthleteSessionUpdated,
 24:   notifyAthleteFeedbackReminder,
 25: } from "../utils/notifications";
 26: import {
 27:   DAYS_FR, DAYS_SHORT, MONTHS_FR, CATEGORIES,
 28:   toLocalDateStr, isSameDay, sessionStatus, colors, getCalendarDays,
 29: } from "./planningUtils";
 30: import { StatusIcon } from "./planningShared";
 31: import { getSessionTrainingFocus } from "../domain/trainingFocus";
 32: import SessionModal from "./SessionModal";
 33: import AddSessionModal from "./AddSessionModal";
 34: 
 35: // ─── Composant principal ──────────────────────────────────────────────────────
 36: 
 37: function Planning() {
 38:   const { clubId } = useAuth();
 39:   const today   = new Date();
 40:   const isMobile = typeof window !== "undefined" && window.innerWidth < 768;
 41: 
 42:   const [viewYear,  setViewYear]  = useState(today.getFullYear());
 43:   const [viewMonth, setViewMonth] = useState(today.getMonth());
 44:   const [viewMode,  setViewMode]  = useState(isMobile ? "week" : "month");
 45: 
 46:   const [athletes,           setAthletes]           = useState([]);
 47:   const [sessionList,        setSessionList]         = useState([]);
 48:   const [activeSession,      setActiveSession]       = useState(null);
 49:   const [sessionModalTarget, setSessionModalTarget]  = useState(null);
 50:   const [selectedDate,       setSelectedDate]        = useState(null);
 51:   const [filterMode,         setFilterMode]          = useState("all");
 52:   const [loading,            setLoading]             = useState(true);
 53:   const [error,              setError]               = useState(null);
 54: 
 55:   // ═══ Chargement ═══════════════════════════════════════════════════════════
 56:   const fetchAll = useCallback(async () => {
 57:     if (!clubId) return;
 58:     try {
 59:       setLoading(true); setError(null);
 60:       const [athletesRes, sessionsRes] = await Promise.all([
 61:         supabase.from("athletes").select("id, name, main_discipline, profile_data, user_id").eq("club_id", clubId),
 62:         supabase.from("sessions").select("*").eq("club_id", clubId),
 63:       ]);
 64:       if (athletesRes.error) throw athletesRes.error;
 65:       if (sessionsRes.error) throw sessionsRes.error;
 66: 
 67:       const sessionIds = sessionsRes.data.map(s => s.id);
 68:       const saRes = sessionIds.length
 69:         ? await supabase.from("session_athletes").select("*").in("session_id", sessionIds)
 70:         : { data: [], error: null };
 71:       if (saRes.error) throw saRes.error;
 72: 
 73:       setAthletes(athletesRes.data.map(a => ({
 74:         id: a.id, name: a.name, mainDiscipline: a.main_discipline,
 75:         avatar: a.profile_data?.avatar ?? initialsFromName(a.name),
 76:       })));
 77: 
 78:       setSessionList(sessionsRes.data.map(s => {
 79:         const rows = saRes.data.filter(v => v.session_id === s.id);
 80:         return {
 81:           id: s.id, week: s.week, day: s.day,
 82:           sessionDate:     s.session_date,
 83:           time:            s.time,
 84:           type:            s.type,
 85:           category:        s.category,
 86:           trainingFocus:   s.training_focus,
 87:           title:           s.title,
 88:           description:     s.description,
 89:           instructions:    s.instructions,
 90:           durationMinutes: s.duration_minutes,
 91:           pdfUrl:          s.pdf_url,
 92:           createdBy:       s.created_by,
 93:           lifecycleStatus: s.lifecycle_status ?? "planned",
 94:           startedAt:       s.started_at,
 95:           closedAt:        s.closed_at,
 96:           createdByAthlete: s.created_by != null && athletesRes.data.some(a => a.user_id === s.created_by),
 97:           athleteIds:  rows.map(v => v.athlete_id),
 98:           validations: rows.map(v => ({
 99:             athleteId: v.athlete_id, status: v.status,
100:             feeling: v.feeling, fatigue: v.fatigue,
101:             comment: v.comment, rpe: v.rpe,
102:             actualDurationMinutes: v.actual_duration_minutes,
103:             durationSource: v.duration_source,
104:             rsvpStatus: v.rsvp_status,
105:             rsvpNote: v.rsvp_note,
106:             rsvpUpdatedAt: v.rsvp_updated_at,
107:             coachNote: v.coach_note,
108:             feedbackSubmittedAt: v.feedback_submitted_at,
109:           })),
110:         };
111:       }));
112:     } catch (err) {
113:       setError(err.message ?? "Erreur inconnue");
114:     } finally {
115:       setLoading(false);
116:     }
117:   }, [clubId]);
118: 
119:   useEffect(() => { fetchAll(); }, [fetchAll]);
120: 
121:   // ═══ Écritures ════════════════════════════════════════════════════════════
122: 
123:   const addSession = useCallback(async (form) => {
124:     const { data: newSession, error: sessionError } = await supabase
125:       .from("sessions")
126:       .insert({
127:         club_id: clubId, week: form.week, day: form.day,
128:         session_date: form.sessionDate, time: form.time,
129:         type: form.type, category: form.category, title: form.title,
130:         training_focus: form.trainingFocus,
131:         description: form.description || null,
132:         instructions: form.instructions || null,
133:         duration_minutes: form.durationMinutes,
134:         load_weight: 1.0,
135:         pdf_url: form.pdfUrl ?? null,
136:       })
137:       .select().single();
138:     if (sessionError) throw sessionError;
139: 
140:     const { error: linkErr } = await supabase.from("session_athletes").insert(
141:       form.athleteIds.map(id => ({ session_id: newSession.id, athlete_id: id, status: null, feeling: null, fatigue: null, comment: null }))
142:     );
143:     if (linkErr) throw linkErr;
144: 
145:     await notifyAthleteNewSession(clubId, form.athleteIds, { title: form.title, sessionDate: form.sessionDate, day: form.day });
146:     await fetchAll();
147:   }, [clubId, fetchAll]);
148: 
149:   const updateSession = useCallback(async (sessionId, form) => {
150:     const { error: sessionError } = await supabase.from("sessions").update({
151:       week: form.week, day: form.day, session_date: form.sessionDate,
152:       time: form.time, type: form.type, category: form.category, title: form.title,
153:       training_focus: form.trainingFocus,
154:       description: form.description || null, instructions: form.instructions || null,
155:       duration_minutes: form.durationMinutes,
156:       load_weight: 1.0,
157:       pdf_url: form.pdfUrl ?? null,
158:     }).eq("id", sessionId);
159:     if (sessionError) throw sessionError;
160: 
161:     const existing    = sessionList.find(s => s.id === sessionId);
162:     const previousIds = existing?.athleteIds ?? [];
163:     const toAdd       = form.athleteIds.filter(id => !previousIds.includes(id));
164:     const toRemove    = previousIds.filter(id => !form.athleteIds.includes(id));
165:     if (toAdd.length)    { const { error: e } = await supabase.from("session_athletes").insert(toAdd.map(id => ({ session_id: sessionId, athlete_id: id, status: null, feeling: null, fatigue: null, comment: null, rpe: null }))); if (e) throw e; }
166:     if (toRemove.length) { const { error: e } = await supabase.from("session_athletes").delete().eq("session_id", sessionId).in("athlete_id", toRemove); if (e) throw e; }
167:     const retainedIds = form.athleteIds.filter(id => previousIds.includes(id));
168:     if (retainedIds.length) await notifyAthleteSessionUpdated(clubId, retainedIds, { id: sessionId, title: form.title, sessionDate: form.sessionDate, time: form.time });
169:     if (toAdd.length) await notifyAthleteNewSession(clubId, toAdd, { id: sessionId, title: form.title, sessionDate: form.sessionDate, day: form.day });
170:     await fetchAll();
171:   }, [clubId, fetchAll, sessionList]);
172: 
173:   const deleteSession = useCallback(async (sessionId) => {
174:     const existing = sessionList.find(s => s.id === sessionId);
175:     const { error: assignmentsError } = await supabase.from("session_athletes").delete().eq("session_id", sessionId);
176:     if (assignmentsError) throw assignmentsError;
177:     const { error: e } = await supabase.from("sessions").delete().eq("id", sessionId);
178:     if (e) throw e;
179:     // Évite d'orpheliner la pièce jointe privée une fois la séance
180:     // supprimée (échec d'écriture ici non bloquant : la séance est déjà
181:     // supprimée, le fichier orphelin est un problème mineur, pas une erreur
182:     // utilisateur à faire remonter).
183:     if (existing?.pdfUrl) {
184:       const { error: pdfDeleteError } = await supabase.storage.from("session-pdfs").remove([existing.pdfUrl]);
185:       if (pdfDeleteError) captureError(pdfDeleteError, { operation: "delete_session_pdf", sessionId });
186:     }
187:     await fetchAll();
188:   }, [fetchAll, sessionList]);
189: 
190:   const setCoachNote = useCallback(async (sessionId, athleteId, coachNote) => {
191:     const { error: updateError } = await supabase.from("session_athletes").update({ coach_note: coachNote || null })
192:       .eq("session_id", sessionId).eq("athlete_id", athleteId);
193:     if (updateError) throw updateError;
194:     setSessionList(previous => previous.map(session => session.id !== sessionId ? session : {
195:       ...session,
196:       validations: session.validations.map(validation => validation.athleteId === athleteId ? { ...validation, coachNote } : validation),
197:     }));
198:   }, []);
199: 
200:   const remindFeedback = useCallback(async (session) => {
201:     const targetIds = session.validations.filter(validation => (
202:       validation.status !== "none"
203:       && (validation.rpe == null || validation.durationSource !== "reported")
204:     )).map(validation => validation.athleteId);
205:     await notifyAthleteFeedbackReminder(clubId, targetIds, session);
206:   }, [clubId]);
207: 
208:   const setLifecycle = useCallback(async (sessionId, lifecycleStatus) => {
209:     const now = new Date().toISOString();
210:     const updates = { lifecycle_status: lifecycleStatus };
211:     if (lifecycleStatus === "live") { updates.started_at = now; updates.closed_at = null; }
212:     if (lifecycleStatus === "completed") updates.closed_at = now;
213:     const { error: updateError } = await supabase.from("sessions").update(updates).eq("id", sessionId);
214:     if (updateError) throw updateError;
215:     const current = sessionList.find(session => session.id === sessionId);
216:     setSessionList(previous => previous.map(session => session.id === sessionId ? {
217:       ...session, lifecycleStatus, startedAt: updates.started_at ?? session.startedAt, closedAt: updates.closed_at ?? null,
218:     } : session));
219:     if (lifecycleStatus === "completed" && current) await remindFeedback(current);
220:   }, [remindFeedback, sessionList]);
221: 
222:   // ═══ Dérivés calendrier ═══════════════════════════════════════════════════
223: 
224:   const calendarDays = useMemo(() => getCalendarDays(viewYear, viewMonth), [viewYear, viewMonth]);
225: 
226:   const filteredSessions = useMemo(() => {
227:     if (filterMode === "athlete") return sessionList.filter(s => s.createdByAthlete);
228:     if (filterMode === "coach")   return sessionList.filter(s => !s.createdByAthlete);
229:     return sessionList;
230:   }, [sessionList, filterMode]);
231: 
232:   const sessionsByDate = useMemo(() => {
233:     const map = {};
234:     filteredSessions.forEach(s => {
235:       if (!s.sessionDate) return;
236:       const key = s.sessionDate.slice(0, 10);
237:       if (!map[key]) map[key] = [];
238:       map[key].push(s);
239:     });
240:     return map;
241:   }, [filteredSessions]);
242: 
243:   const selectedDaySessions = useMemo(() => {
244:     if (!selectedDate) return [];
245:     return (sessionsByDate[toLocalDateStr(selectedDate)] ?? [])
246:       .sort((a, b) => (a.time ?? "").localeCompare(b.time ?? ""));
247:   }, [selectedDate, sessionsByDate]);
248: 
249:   const weekReference = selectedDate ?? today;
250:   const weekStart = new Date(weekReference);
251:   weekStart.setDate(weekReference.getDate() - ((weekReference.getDay() + 6) % 7));
252:   const weekDays = Array.from({ length: 7 }, (_, i) => {
253:     const date = new Date(weekStart);
254:     date.setDate(weekStart.getDate() + i);
255:     return date;
256:   });
257: 
258:   const prevMonth = () => {
259:     if (viewMonth === 0) { setViewYear(y => y - 1); setViewMonth(11); }
260:     else setViewMonth(m => m - 1);
261:     setSelectedDate(null);
262:   };
263:   const nextMonth = () => {
264:     if (viewMonth === 11) { setViewYear(y => y + 1); setViewMonth(0); }
265:     else setViewMonth(m => m + 1);
266:     setSelectedDate(null);
267:   };
268:   const prevWeek = () => {
269:     const d = new Date(selectedDate ?? today);
270:     d.setDate(d.getDate() - 7);
271:     setSelectedDate(d);
272:   };
273:   const nextWeek = () => {
274:     const d = new Date(selectedDate ?? today);
275:     d.setDate(d.getDate() + 7);
276:     setSelectedDate(d);
277:   };
278:   const goToday = () => {
279:     setViewYear(today.getFullYear());
280:     setViewMonth(today.getMonth());
281:     setSelectedDate(today);
282:   };
283: 
284:   const liveActiveSession = activeSession
285:     ? sessionList.find(s => s.id === activeSession.id) ?? activeSession
286:     : null;
287: 
288:   function buildFormFromSession(s) {
289:     return {
290:       title: s.title, type: s.type, category: s.category, trainingFocus: s.trainingFocus,
291:       day: s.day, time: s.time, week: s.week,
292:       durationMinutes: s.durationMinutes ?? "",
293:       description: s.description ?? "", instructions: s.instructions ?? "",
294:       athleteIds: s.athleteIds, pdfUrl: s.pdfUrl ?? null,
295:       sessionDate: s.sessionDate?.slice(0, 10) ?? "",
296:     };
297:   }
298: 
299:   const navLabel = useMemo(() => {
300:     if (viewMode === "month") return `${MONTHS_FR[viewMonth]} ${viewYear}`;
301:     const mon = weekDays[0], sun = weekDays[6];
302:     if (mon.getMonth() === sun.getMonth())
303:       return `${mon.getDate()} – ${sun.toLocaleDateString("fr-BE", { day: "numeric", month: "long" })}`;
304:     return `${mon.toLocaleDateString("fr-BE", { day: "numeric", month: "short" })} – ${sun.toLocaleDateString("fr-BE", { day: "numeric", month: "short" })}`;
305:   }, [viewMode, viewMonth, viewYear, weekDays]);
306: 
307:   // ═══ Render ═══════════════════════════════════════════════════════════════
308: 
309:   if (loading) return <LoadingState message="Chargement du planning…" />;
310:   if (error)   return <ErrorState  message={error} onRetry={fetchAll} />;
311: 
312:   const athleteSessionCount = sessionList.filter(s => s.createdByAthlete).length;
313: 
314:   return (
315:     <div className="flex flex-col h-full min-h-0" style={{ background: "var(--c-bg)" }}>
316: 
317:       {/* ── Header glassmorphism ─────────────────────────────────────────── */}
318:       <div className="header-glass px-4 md:px-6 py-3 md:py-4 flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3 flex-shrink-0 z-10">
319: 
320:         <div className="flex items-center gap-1 w-full sm:w-auto">
321:           <button
322:             type="button"
323:             aria-label={viewMode === "month" ? "Mois précédent" : "Semaine précédente"}
324:             onClick={viewMode === "month" ? prevMonth : prevWeek}
325:             className="w-10 h-10 rounded-xl flex items-center justify-center transition-all tap-feedback"
326:             style={{ background: "var(--c-surface-2)", color: "var(--c-text-2)" }}
327:           >
328:             <ChevronLeft size={16} />
329:           </button>
330:           <div className="text-center px-2 flex-1 sm:flex-none min-w-[120px] md:min-w-[180px]">
331:             <p className="meta-text font-bold uppercase tracking-[0.08em] mb-0.5">Période affichée</p>
332:             <p className="text-[15px] md:text-[17px] font-bold tracking-tight truncate" style={{ color: "var(--c-text-1)" }}>
333:               {navLabel}
334:             </p>
335:           </div>
336:           <button
337:             type="button"
338:             aria-label={viewMode === "month" ? "Mois suivant" : "Semaine suivante"}
339:             onClick={viewMode === "month" ? nextMonth : nextWeek}
340:             className="w-10 h-10 rounded-xl flex items-center justify-center transition-all tap-feedback"
341:             style={{ background: "var(--c-surface-2)", color: "var(--c-text-2)" }}
342:           >
343:             <ChevronRight size={16} />
344:           </button>
345:           <button type="button" onClick={goToday}
346:             className="min-h-10 px-3 rounded-xl text-[12px] font-bold transition-all ml-1"
347:             style={{ background: "var(--c-surface-2)", border: "1px solid var(--c-border)", color: "var(--c-text-2)" }}>
348:             Auj.
349:           </button>
350:         </div>
351: 
352:         <div className="flex items-center justify-between sm:justify-end gap-2 w-full sm:w-auto">
353: 
354:           {/* Toggle vue */}
355:           <SegmentedTabs
356:             ariaLabel="Mode d’affichage du planning"
357:             items={[{ id: "month", label: "Mois" }, { id: "week", label: "Sem." }]}
358:             value={viewMode}
359:             onChange={setViewMode}
360:           />
361: 
362:           {/* Filtre séances athlètes — desktop */}
363:           {athleteSessionCount > 0 && (
364:             <div className="hidden lg:block">
365:               <SegmentedTabs
366:                 ariaLabel="Origine des séances"
367:                 items={[
368:                   { id: "all", label: "Toutes" },
369:                   { id: "coach", label: "Coach" },
370:                   { id: "athlete", label: "Athlètes", badge: athleteSessionCount },
371:                 ]}
372:                 value={filterMode}
373:                 onChange={setFilterMode}
374:               />
375:             </div>
376:           )}
377: 
378:           <button
379:             type="button"
380:             aria-label="Ajouter une séance"
381:             onClick={() => setSessionModalTarget("create")}
382:             disabled={athletes.length === 0}
383:             className="btn-primary disabled:opacity-40 !px-3 md:!px-4"
384:           >
385:             <Plus size={14} />
386:             <span className="hidden sm:inline">Ajouter</span>
387:           </button>
388:         </div>
389:       </div>
390: 
391:       <div className="flex flex-1 overflow-hidden">
392: 
393:         <div className="flex-1 overflow-auto">
394: 
395:           {/* ── VUE SEMAINE ── */}
396:           {viewMode === "week" && (
397:             <div className="p-4 md:p-6 space-y-3">
398:               {weekDays.map((date, i) => {
399:                 const key     = toLocalDateStr(date);
400:                 const ds      = (sessionsByDate[key] ?? []).sort((a, b) => (a.time ?? "").localeCompare(b.time ?? ""));
401:                 const isToday = isSameDay(date, today);
402:                 const isPast  = toLocalDateStr(date) < toLocalDateStr(today);
403: 
404:                 return (
405:                   <div
406:                     key={i}
407:                     className="rounded-2xl overflow-hidden border transition-all"
408:                     style={isToday
409:                       ? { borderColor: "rgba(29,158,117,0.45)", boxShadow: "0 0 0 1px rgba(29,158,117,0.20)" }
410:                       : { borderColor: "var(--c-border)" }}
411:                   >
412:                     {/* Header jour */}
413:                     <div
414:                       className="px-4 py-3 flex items-center justify-between"
415:                       style={{ background: isToday ? "rgba(29,158,117,0.08)" : "var(--c-surface)" }}
416:                     >
417:                       <div className="flex items-center gap-3">
418:                         <div
419:                           className="w-10 h-10 rounded-2xl flex items-center justify-center font-bold text-[16px] flex-shrink-0"
420:                           style={isToday
421:                             ? { background: "linear-gradient(135deg, #1D9E75, #16826C)", color: "white" }
422:                             : { background: "var(--c-surface-2)", color: isPast ? "var(--c-text-3)" : "var(--c-text-2)" }}
423:                         >
424:                           {date.getDate()}
425:                         </div>
426:                         <div>
427:                           <p className="text-[14px] font-bold"
428:                             style={{ color: isToday ? "#3DBE8B" : isPast ? "var(--c-text-2)" : "var(--c-text-1)" }}>
429:                             {DAYS_FR[i]}
430:                           </p>
431:                           <p className="meta-text">
432:                             {date.toLocaleDateString("fr-BE", { day: "numeric", month: "long" })}
433:                           </p>
434:                         </div>
435:                       </div>
436: 
437:                       <div className="flex items-center gap-2">
438:                         {ds.length > 0 && (
439:                           <span className="text-[12px] font-bold px-2 py-0.5 rounded-full"
440:                             style={isToday
441:                               ? { background: "rgba(29,158,117,0.16)", color: "var(--tone-success)" }
442:                               : { background: "var(--c-surface-2)", color: "var(--c-text-2)" }}>
443:                             {ds.length} séance{ds.length > 1 ? "s" : ""}
444:                           </span>
445:                         )}
446:                         <button
447:                           type="button"
448:                           aria-label={`Ajouter une séance le ${date.toLocaleDateString("fr-BE")}`}
449:                           onClick={() => { setSelectedDate(date); setSessionModalTarget("create"); }}
450:                           className="w-7 h-7 rounded-lg flex items-center justify-center transition-all"
451:                           style={{ background: "var(--c-surface-2)", color: "var(--c-text-3)" }}
452:                         >
453:                           <Plus size={13} />
454:                         </button>
455:                       </div>
456:                     </div>
457: 
458:                     {/* Séances du jour */}
459:                     {ds.length > 0 ? (
460:                       <div style={{ background: "var(--c-surface)" }}>
461:                         {ds.map((s, idx) => {
462:                           const c  = colors(s.category);
463:                           const st = sessionStatus(s);
464:                           const missingStatus = s.athleteIds.filter(id => {
465:                             const v = s.validations?.find(val => val.athleteId === id);
