 78: // ─── Résolution de la vue active ──────────────────────────────────────────────
 79: function ActiveView({ view, onNavigate, club, clubLoading, coachActions }) {
 80:   switch (view) {
 81:     case "dashboard":    return (
 82:       <Dashboard
 83:         onNavigate={onNavigate}
 84:         club={club}
 85:         clubLoading={clubLoading}
 86:         onOpenClubSettings={coachActions.onOpenClubSettings}
 87:         onInvite={coachActions.onInvite}
 88:         onDemo={coachActions.onDemo}
 89:       />
 90:     );
 91:     case "planning":     return <Planning     />;
 92:     case "athletes":     return <AthleteList  onNavigate={onNavigate} />;
 93:     case "performances": return <Performances />;
 94:     case "charge":       return <ChargeView   />;
 95:     case "rapports":     return <Rapports     />;
 96:     case "competitions": return <Competitions />;
 97:     case "alerts":       return <AlertsView onNavigate={onNavigate} />;
 98:     case "messaging":    return <Messaging    />;
 99:     default:             return <Dashboard onNavigate={onNavigate} club={club} clubLoading={clubLoading} {...coachActions} />;
100:   }
101: }
