152:   const fetchUnreadCount = useCallback(async () => {
153:     if (!clubId) return;
154:     const { count } = await supabase
155:       .from("alerts")
156:       .select("id", { count: "exact", head: true })
157:       .eq("club_id", clubId)
158:       .eq("is_read", false);
159:     setUnreadAlerts(count ?? 0);
