161: 
162:   useEffect(() => { fetchUnreadCount(); }, [fetchUnreadCount]);
163: 
164:   useEffect(() => {
165:     if (!clubId) return undefined;
166:     const channel = supabase
167:       .channel(`coach-alert-counter-${clubId}`)
168:       .on("postgres_changes", {
169:         event: "*", schema: "public", table: "alerts", filter: `club_id=eq.${clubId}`,
170:       }, () => { fetchUnreadCount(); })
171:       .subscribe();
172:     return () => { supabase.removeChannel(channel); };
173:   }, [clubId, fetchUnreadCount]);
