 39: // ─── Helpers ─────────────────────────────────────────────────────────────────
 40: function getDiscType(discName) {
 41:   const MAP = {
 42:     "100m":"sprint","200m":"sprint","400m":"sprint","800m":"endurance","1500m":"endurance",
 43:     "60m haies":"sprint","100m haies":"sprint","110m haies":"sprint","400m haies":"sprint",
 44:     "Longueur":"saut","Triple saut":"saut","Hauteur":"saut","Perche":"saut",
 45:     "Poids":"lancer","Disque":"lancer","Javelot":"lancer","Marteau":"lancer",
 46:     "Décathlon":"combine","Heptathlon":"combine",
 47:   };
 48:   return MAP[discName] ?? "sprint";
 49: }
