 51: // ─── Badges — zéro emoji, icônes lucide ──────────────────────────────────────
 52: function computeBadges({ athlete, weeklyCharge, sessions, competitions, myPerformances, streak }) {
 53:   const badges = [];
 54:   const myComps   = (competitions ?? []).filter(c => c.athleteIds?.includes(athlete.id));
 55:   const myPerfs   = myPerformances ?? [];
 56:   const myRecords = Object.keys(athlete.records ?? {});
 57:   const totalDone = (sessions ?? []).reduce((acc, s) =>
 58:     acc + (s.validations?.filter(v => v.athleteId === athlete.id && v.status === "done").length ?? 0), 0);
 59: 
 60:   const add = (id, label, desc, color, icon = "zap") =>
 61:     badges.push({ id, label, desc, color, icon, unlocked: true });
 62:   const addLocked = (id, label, desc) =>
 63:     badges.push({ id, label, desc, color: "var(--c-text-4)", icon: "lock", unlocked: false });
 64: 
 65:   if (streak >= 1)  add("s1",  "Premier feu",  "1 sem. consécutive",   "#C8890A", "zap");
 66:   if (streak >= 3)  add("s3",  "En feu",       "3 sem. consécutives",  "#C8890A", "zap");
 67:   if (streak >= 5)  add("s5",  "Inarrêtable",  "5 sem. consécutives",  "#C0392B", "zap");
 68:   if (streak >= 10) add("s10", "Légende",      "10 sem. consécutives", "#7C67C8", "star");
 69:   if (totalDone >= 1)   add("d1",  "Premier pas", "1 séance",    "#1D9E75", "check");
 70:   if (totalDone >= 10)  add("d10", "Régulier",    "10 séances",  "#1D9E75", "check");
 71:   if (totalDone >= 25)  add("d25", "Bosseur",     "25 séances",  "#4B7BDB", "trending");
 72:   if (totalDone >= 50)  add("d50", "Acharné",     "50 séances",  "#7C67C8", "trending");
 73:   if (totalDone >= 100) add("d100","Élite",       "100 séances", "#C8890A", "trophy");
 74:   if (myComps.length >= 1) add("c1","Compétiteur","1ère compétition", "#C0392B", "trophy");
 75:   if (myComps.length >= 5) add("c5","Guerrier",   "5 compétitions",   "#C0392B", "trophy");
 76: 
 77:   const prBeat = myPerfs.filter(p => {
 78:     const rec = athlete.records?.[p.discipline]; if (!rec) return false;
 79:     const hib = getDiscHib(p.discipline);
 80:     const pv = parsePerf(p.value), prv = parsePerf(rec.pr);
 81:     if (!pv.value || !prv.value) return false;
 82:     return hib ? pv.value >= prv.value : pv.value <= prv.value;
 83:   }).length;
 84:   if (prBeat >= 1) add("pr1","Record battu","1 PR amélioré",  "#C8890A","trophy");
 85:   if (prBeat >= 3) add("pr3","Recordman",   "3 PR améliorés", "#C8890A","star");
 86: 
 87:   const discCount = [...new Set([...myRecords,...myPerfs.map(p=>p.discipline)])].length;
 88:   if (discCount >= 1) add("dc1","Spécialiste", "1 discipline",    "#4B7BDB","star");
 89:   if (discCount >= 3) add("dc3","Polyvalent",  "3 disciplines",   "#7C67C8","star");
 90:   if (discCount >= 5) add("dc5","Décathlonien","5+ disciplines",  "#C0392B","star");
 91:   if (myPerfs.length >= 5)  add("p5", "Analytique", "5 perfs",  "#1D9E75","trending");
 92:   if (myPerfs.length >= 20) add("p20","Data driven","20 perfs", "#4B7BDB","trending");
 93: 
 94:   const optW = (weeklyCharge.filter(w=>w.athleteId===athlete.id)).filter(w => {
 95:     const m = getAthleteMetricsForWeek(athlete.id, weeklyCharge, w.week);
 96:     return m.variationPercent != null && Math.abs(m.variationPercent) <= 20;
 97:   }).length;
 98:   if (optW >= 3) add("aw3","Régulier","3 fenêtres stables","#1D9E75","check");
 99:   if (optW >= 8) add("aw8","Maestro", "8 fenêtres stables","#7C67C8","star");
100: 
101:   if (streak < 3)         addLocked("l1","En feu",      `${3-streak} sem. de plus`);
102:   if (totalDone < 10)     addLocked("l2","Régulier",    `${10-totalDone} séance(s)`);
103:   if (myComps.length < 1) addLocked("l3","Compétiteur", "Participe à une compét.");
104: 
105:   return badges;
106: }
