108: // ─── Icône badge sans emoji ───────────────────────────────────────────────────
109: function BadgeIcon({ icon, color, size = 14 }) {
110:   const props = { size, color, strokeWidth: 1.8 };
111:   if (icon === "trophy")   return <Trophy   {...props} />;
112:   if (icon === "star")     return <Star     {...props} />;
113:   if (icon === "check")    return <CheckCircle {...props} />;
114:   if (icon === "trending") return <TrendingUp  {...props} />;
115:   return <Zap {...props} />;
116: }
