223:           <div style={{
224:             padding: "var(--space-4)", borderRadius: "var(--r-lg)",
225:             background: `color-mix(in srgb, ${presentation.color} 7%, transparent)`,
226:             border: `1px solid color-mix(in srgb, ${presentation.color} 20%, transparent)`,
227:           }}>
228:             <div className="flex items-start gap-3">
229:               <div style={{
230:                 width: 44, height: 44, borderRadius: 14, flexShrink: 0,
231:                 display: "flex", alignItems: "center", justifyContent: "center",
232:                 color: presentation.color, background: `color-mix(in srgb, ${presentation.color} 12%, transparent)`,
233:               }}>
234:                 <FocusIcon size={20} strokeWidth={2} aria-hidden="true" />
235:               </div>
236:               <div className="min-w-0">
237:                 <p className="metric-label" style={{ color: presentation.color }}>{presentation.eyebrow}</p>
238:                 <p className="card-title" style={{ marginTop: "var(--space-1)", fontSize: 17 }}>{presentation.title}</p>
239:                 <p className="secondary-text" style={{ marginTop: "var(--space-1)" }}>{presentation.description}</p>
240:               </div>
241:             </div>
242:             <button type="button" onClick={presentation.action} className="btn-primary" style={{ width: "100%", marginTop: "var(--space-4)" }}>
243:               {presentation.cta}<ChevronRight size={15} aria-hidden="true" />
244:             </button>
245:           </div>
246: 
247:           <div style={{ borderRadius: "var(--r-lg)", overflow: "hidden", border: "1px solid var(--c-border)", background: "rgba(2,7,12,0.16)" }}>
248:             {[
249:               {
250:                 key: "checkin", icon: Activity, label: "Ton check-in",
251:                 value: wellnessCompleted ? (dailyState?.plainHeadline ?? "Complété") : "30 secondes pour le faire",
252:                 color: wellnessCompleted ? dailyState?.color : "var(--color-warning)", action: wellnessCompleted ? onOpenDailyState : onOpenWellness,
253:               },
254:               {
255:                 key: "session", icon: CalendarDays, label: "Ta séance",
256:                 value: session?.title ?? completedSessionLabel,
257:                 detail: session ? completedSessionLabel : null,
258:                 color: session ? presentation.color : "var(--c-text-2)", action: session ? onOpenSession : onOpenPlanning,
259:               },
260:               {
261:                 key: "progress", icon: TrendingUp, label: "Ta progression",
262:                 value: loadStory?.headline ?? "Ton historique se construit",
263:                 color: "var(--color-info)", action: onOpenLoadDetail,
264:               },
265:             ].map((item, index) => {
266:               const ItemIcon = item.icon;
267:               return (
268:                 <button key={item.key} type="button" onClick={item.action} className="tap-feedback" style={{
269:                   width: "100%", minHeight: 58, display: "flex", alignItems: "center", gap: 10,
270:                   background: "transparent", border: 0, borderBottom: index < 2 ? "1px solid var(--c-border)" : 0,
271:                   padding: "10px 12px", color: "inherit", cursor: "pointer", textAlign: "left",
272:                 }}>
273:                   <ItemIcon size={16} color={item.color} aria-hidden="true" />
274:                   <span style={{ flex: 1, minWidth: 0 }}>
275:                     <span className="metric-label" style={{ display: "block" }}>{item.label}</span>
276:                     <span className="secondary-text line-clamp-1" style={{ display: "block", marginTop: 2, color: "var(--c-text-1)", fontWeight: 600 }}>{item.value}</span>
277:                     {item.detail && <span className="meta-text" style={{ display: "block", marginTop: 2 }}>{item.detail}</span>}
278:                   </span>
279:                   <ChevronRight size={14} color="var(--c-text-3)" aria-hidden="true" />
280:                 </button>
281:               );
282:             })}
283:           </div>
284:         </div>
285: 
286:         {nextCompetition && (
287:           <p className="meta-text" style={{ marginTop: "auto", paddingTop: "var(--space-3)" }}>
288:             Prochain cap · <span style={{ color: "var(--c-text-2)", fontWeight: 600 }}>{nextCompetition.name}</span>
289:           </p>
290:         )}
291:       </div>
292:     </section>
293:   );
294: });
295: 
296: // ═══════════════════════════════════════════════════════════════════════════════
297: // COMPOSANT PRINCIPAL
298: // ═══════════════════════════════════════════════════════════════════════════════
299: export default function AthleteDashboard({
300:   athlete, weeklyCharge, sessions, competitions, lastMessages,
301:   coachName, myPerformances, onNavigate, wellnessToday, wellnessHistory = [], onOpenWellness,
302:   confirmedRestDays = [], onConfirmRestDay,
303:   onOpenInjuryReport, allAthletes, onRpeChange, onStatusChange,
304:   onFeelingChange, onCommentChange, onRsvpChange,
305: }) {
306:   // Une référence stable évite de recalculer tous les indicateurs à chaque rendu.
307:   const today       = useMemo(() => new Date(), []);
308:   const currentWeek = getISOWeek(today);
309:   const currentYear = getISOWeekYear(today);
310:   const [openTodaySessionId, setOpenTodaySessionId] = useState(null);
311:   const [activeMetric, setActiveMetric] = useState(null);
312:   const [showDailyState, setShowDailyState] = useState(false);
313: 
314:   const metrics = useMemo(() =>
315:     getAthleteMetricsForWeek(athlete.id, weeklyCharge, currentWeek, wellnessToday ? [wellnessToday] : [], sessions),
316:   [athlete.id, weeklyCharge, currentWeek, wellnessToday, sessions]);
317: 
318:   // Les 5 jauges circulaires (ressenti, charge, condition physique,
319:   // préparation, sollicitation récente) sont l'affichage principal ; les
320:   // chiffres scientifiques bruts qui les nourrissent restent disponibles en
321:   // second niveau, repliés, pour qui veut aller plus loin.
322:   const advancedMonitoring = useMemo(() => ["wellness", "load7", "load28", "variation", "spacing", "dataQuality", "ewmaAcute", "ewmaChronic", "monotony", "acwrExperimental"]
323:     .map((key) => getMonitoringReading(key, metrics)), [metrics]);
324:   const loadStory = useMemo(
325:     () => getAthleteLoadStory(metrics, sessions, athlete.id),
326:     [metrics, sessions, athlete.id],
327:   );
328: 
329:   const dailyState = useMemo(
330:     () => buildDailyState({ wellness: wellnessToday, history: wellnessHistory, metrics }),
331:     [wellnessHistory, wellnessToday, metrics],
332:   );
333:   const status = { label: dailyState.label, color: dailyState.color };
334: 
335:   const trainingGauges = useMemo(() => [...TRAINING_GAUGE_KEYS].map((key) =>
336:     getTrainingGaugeReading(key, { metrics, dailyState, sessions, athleteId: athlete.id, currentWeek }),
337:   ), [metrics, dailyState, sessions, athlete.id, currentWeek]);
338: 
339:   const nextComp = competitions
340:     .filter(c => c.athleteIds.includes(athlete.id) && new Date(c.date) >= today)
341:     .sort((a, b) => new Date(a.date) - new Date(b.date))[0] ?? null;
342: 
343:   const weekSessions = useMemo(() =>
344:     sessions
345:       .filter(session => matchesISOWeek(session, currentWeek, currentYear))
346:       .sort((a, b) => (a.time ?? "").localeCompare(b.time ?? "")),
347:   [sessions, currentWeek, currentYear]);
348: 
349:   // Séance(s) du jour — la plus importante info de l'écran, mise en avant
350:   // juste sous le ring plutôt que noyée dans la liste de la semaine.
351:   const todaySessions = weekSessions
352:     .filter(s => s.sessionDate && isSameDay(parseLocalDate(s.sessionDate), today));
353:   const todayFocus = getTodayFocus({
354:     wellnessCompleted: Boolean(wellnessToday),
355:     restConfirmed: confirmedRestDays.includes(toLocalDateStr(today)),
356:     todaySessions, athleteId: athlete.id,
357:   });
358:   const focusSession = todayFocus.focusSession;
359:   const openedTodaySession = todaySessions.find(session => session.id === openTodaySessionId) ?? null;
360: 
361:   const topRecords     = Object.entries(athlete.records ?? {}).slice(0, 4);
362:   const activeInjuries = (athlete.injuries ?? []).filter(i => i.status !== "résolu");
363: 
364:   const streak = useMemo(() => {
365:     let count = 0;
366:     for (let offset = 0; offset <= 20; offset++) {
367:       const weekDate = new Date(today);
368:       weekDate.setDate(weekDate.getDate() - offset * 7);
369:       const info = getISOWeekInfo(weekDate);
370:       const completed = sessions
371:         .filter(session => matchesISOWeek(session, info.week, info.year))
372:         .some(session => session.validations?.some(
373:           validation => validation.athleteId === athlete.id && validation.status === "done"
374:         ));
375:       if (completed) count += 1;
376:       else break;
377:     }
378:     return count;
379:   }, [sessions, athlete.id, today]);
380: 
381: 
382:   const axisProfile = useMemo(
383:     () => getAthleteAxisProfile(athlete.id, weekSessions, currentWeek),
384:     [athlete.id, weekSessions, currentWeek]
385:   );
386: 
387:   const badges = useMemo(() =>
388:     computeBadges({ athlete, weeklyCharge, sessions, competitions, myPerformances, streak }),
389:   [athlete, weeklyCharge, sessions, competitions, myPerformances, streak]);
390: 
391:   const unlockedBadges = badges.filter(b =>  b.unlocked);
392:   const lockedBadges   = badges.filter(b => !b.unlocked);
393: 
394:   const latestPR = useMemo(() => {
395:     const ago = new Date(); ago.setDate(ago.getDate() - 7);
396:     return (myPerformances ?? []).find(p => {
397:       const rec = athlete.records?.[p.discipline];
398:       if (!rec || !p.performance_date || new Date(p.performance_date) < ago) return false;
399:       const hib = getDiscHib(p.discipline);
400:       const pv = parsePerf(p.value), prv = parsePerf(rec.pr);
401:       if (!pv.value || !prv.value) return false;
402:       return hib ? pv.value >= prv.value : pv.value <= prv.value;
403:     }) ?? null;
404:   }, [myPerformances, athlete.records]);
405: 
406:   const doneThisWeek = weekSessions.filter(s =>
407:     s.validations?.find(v => v.athleteId === athlete.id && v.status === "done")).length;
408: 
409:   const statusColor = dailyState.color;
410: 
411:   // ══════════════════════════════════════════════════════════════════════════
412:   return (
413:     <div className="page-container py-4 md:py-5 space-y-4 md:space-y-5 max-w-5xl mx-auto animate-slide-up">
414: 
415:       <header className="flex items-end justify-between gap-4">
416:         <div>
417:           <p className="meta-text mb-1">Aujourd’hui</p>
418:           <h1 className="page-title">Bonjour {athlete.name.split(" ")[0]}</h1>
419:           <p className="secondary-text mt-1">Voici ce qui compte pour ton entraînement.</p>
420:         </div>
421:         <span className="meta-text hidden sm:block">Semaine {currentWeek}</span>
422:       </header>
423: 
424:       {/* L'action du jour occupe seule le premier niveau de lecture. Les
425:           explications et chiffres restent juste après, sans être supprimés. */}
426:       <div className="grid grid-cols-1 xl:grid-cols-2 gap-4 md:gap-5 items-stretch">
427:         <DailyFocusCard
428:           focus={todayFocus}
429:           todaySessions={todaySessions}
430:           nextCompetition={nextComp}
431:           dailyState={dailyState}
432:           loadStory={loadStory}
433:           onOpenWellness={onOpenWellness}
434:           onOpenSession={() => focusSession && setOpenTodaySessionId(focusSession.id)}
435:           onOpenPlanning={() => onNavigate("planning")}
436:           onConfirmRestDay={() => onConfirmRestDay?.(toLocalDateStr(today))}
437:           onOpenDailyState={() => setShowDailyState(true)}
438:           onOpenLoadDetail={() => setActiveMetric("weeklyLoad")}
439:         />
440: 
441:         <div className="xl:col-span-2" style={{ paddingTop: "var(--space-2)" }}>
442:           <h2 className="section-title">Mieux comprendre ta journée</h2>
443:           <p className="secondary-text" style={{ marginTop: "var(--space-1)" }}>Ton ressenti et tes chiffres restent disponibles, avec une explication simple avant le détail scientifique.</p>
444:         </div>
445: 
446:         <section className="rounded-2xl overflow-hidden select-none border xl:col-span-2" aria-labelledby="wellness-title"
447:           style={{ position: "relative", background: "linear-gradient(160deg, var(--c-surface) 0%, var(--c-surface-2) 55%, var(--c-bg) 100%)", borderColor: "var(--c-border)" }}>
448:           {/* Grille décorative — très subtile */}
449:           <div className="absolute pointer-events-none" aria-hidden="true" style={{
450:             inset: 0,
451:             backgroundImage: "linear-gradient(rgba(29,158,117,0.03) 1px, transparent 1px), linear-gradient(90deg, rgba(29,158,117,0.03) 1px, transparent 1px)",
452:             backgroundSize: "24px 24px",
453:           }} />
454:           <div style={{ position: "relative", padding: "var(--card-padding-comfortable)" }}>
455:           {/* Identité */}
456:           <div className="flex items-start justify-between gap-3 mb-5">
457:             <div className="flex items-center gap-3">
458:               <div style={{
459:                 width: 40, height: 40, borderRadius: 10, flexShrink: 0,
460:                 background: "rgba(29,158,117,0.14)", border: "1px solid rgba(29,158,117,0.22)",
461:                 display: "flex", alignItems: "center", justifyContent: "center",
462:               }}>
463:                 <span style={{ fontSize: 14, fontWeight: 600, color: "white", letterSpacing: "-0.02em" }}>
464:                   {initialsFromName(athlete.name)}
465:                 </span>
466:               </div>
467:               <div>
468:                 <p className="meta-text" style={{ fontWeight: 600, letterSpacing: "0.07em", textTransform: "uppercase", marginBottom: "var(--space-1)" }}>
469:                   Comment tu te sens · S{currentWeek}
470:                 </p>
471:                 <p id="wellness-title" className="section-title">{status.label}</p>
472:                 <p className="meta-text" style={{ marginTop: "var(--space-1)" }}>
473:                   {athlete.mainDiscipline ?? "Athlète"}{athlete.group ? ` · ${athlete.group}` : ""}
474:                 </p>
475:               </div>
476:             </div>
477:             {/* Pill statut — discret */}
478:             <div style={{
479:               display: "flex", alignItems: "center", gap: 5,
480:               padding: "4px 10px", borderRadius: 99, flexShrink: 0,
481:               background: `${statusColor}12`, border: `1px solid ${statusColor}22`,
482:             }}>
483:               <div style={{ width: 5, height: 5, borderRadius: "50%", background: statusColor, flexShrink: 0 }} />
484:               <span style={{ fontSize: "var(--text-meta)", fontWeight: 600, color: statusColor }}>{dailyState.score == null ? "À renseigner" : "5 réponses résumées"}</span>
485:             </div>
486:           </div>
487: 
488:           {/* 5 jauges : un mot de statut simple, jamais un chiffre brut en
489:               face avant. Le détail scientifique complet reste à un tap. */}
490:           <div className="flex gap-2.5 overflow-x-auto -mx-1 px-1 pb-1 sm:grid sm:grid-cols-5 sm:gap-3 sm:overflow-visible sm:mx-0 sm:px-0"
491:             style={{ scrollSnapType: "x proximity" }}>
492:             {trainingGauges.map((gauge) => (
493:               <TrainingGauge key={gauge.key}
494:                 value={gauge.fillPercent} color={gauge.color} statusWord={gauge.statusWord}
495:                 label={gauge.shortLabel}
496:                 onClick={() => (gauge.key === "form" ? setShowDailyState(true) : setActiveMetric(gauge.key))} />
497:             ))}
498:           </div>
499:           </div>
500:         </section>
501: 
502:       </div>
503: 
504:       {/* ══════════════════════════════════════════════════════════════════════
505:           WELLNESS
506:          ══════════════════════════════════════════════════════════════════════ */}
507:       {wellnessToday && (
508:         <div className="card p-4">
509:           <div className="flex items-center justify-between mb-3">
510:             <div className="flex items-center gap-2.5">
511:               <div style={{ width: 32, height: 32, borderRadius: 8, background: "rgba(29,158,117,0.09)", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
512:                 <CheckCircle size={14} color="#1D9E75" strokeWidth={2} />
513:               </div>
514:               <div>
515:                 <p className="card-title">Ton état du jour</p>
516:                 <p className="card-subtitle">Tes cinq réponses sont enregistrées</p>
517:               </div>
518:             </div>
519:             {metrics.wellnessScore !== null && (
520:               <div style={{ padding: "4px 10px", borderRadius: 8, background: "rgba(124,103,200,0.08)" }}>
521:                 <span style={{ fontSize: 16, fontWeight: 600, color: "#7C67C8", fontVariantNumeric: "tabular-nums", letterSpacing: "-0.02em" }}>
522:                   {metrics.wellnessScore}
523:                 </span>
524:                 <span style={{ fontSize: "var(--text-meta)", color: "var(--tone-mental)", marginLeft: 2 }}>/100</span>
525:               </div>
526:             )}
527:           </div>
528:           <div className="grid grid-cols-5 gap-2">
529:             {WELLNESS_QUESTIONS.map(q => {
530:               const val  = wellnessToday[q.key];
531:               const Icon = q.icon;
532:               const good = q.inverted ? val <= 2 : val >= 4;
533:               const bad  = q.inverted ? val >= 4 : val <= 2;
534:               const col  = good ? "#1D9E75" : bad ? "#C0392B" : "#C8890A";
535:               return (
536:                 <div key={q.key} style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: "var(--space-1)", padding: "var(--space-2) var(--space-1)", borderRadius: 8, background: "var(--c-surface-2)" }}>
537:                   <Icon size={13} color={q.color} strokeWidth={2} />
538:                   <span style={{ fontSize: 15, fontWeight: 600, color: col, fontVariantNumeric: "tabular-nums", lineHeight: 1 }}>{val}</span>
539:                   <span style={{ fontSize: "var(--text-meta)", color: "var(--c-text-3)", textAlign: "center", lineHeight: "var(--leading-meta)" }}>{q.label.split(" ")[0]}</span>
540:                 </div>
541:               );
542:             })}
543:           </div>
544:           {wellnessToday.notes && (
545:             <p className="meta-text" style={{ marginTop: "var(--space-3)", fontStyle: "italic", borderTop: "1px solid var(--c-border)", paddingTop: "var(--space-3)" }}>
546:               {wellnessToday.notes}
547:             </p>
548:           )}
549:           <button onClick={onOpenWellness} className="btn-ghost" style={{ marginTop: "var(--space-2)", minHeight: 36, paddingInline: 0 }}>
550:             Modifier
551:           </button>
552:         </div>
553:       )}
554: 
555:       {/* ══════════════════════════════════════════════════════════════════════
556:           GRILLE PRINCIPALE
557:          ══════════════════════════════════════════════════════════════════════ */}
558:       <section aria-labelledby="athlete-progress-title">
559:         <h2 id="athlete-progress-title" className="section-title">Ta progression</h2>
560:         <p className="secondary-text mt-1">D'abord ce qui a changé et pourquoi. Les nombres et les formules restent accessibles si tu veux aller plus loin.</p>
561:       </section>
562:       <div className="grid grid-cols-1 lg:grid-cols-3 gap-4 md:gap-5">
563:         <div className="lg:col-span-2 space-y-4 md:space-y-5">
564: 
565:           {/* ── Profil de charge (6 axes) ───────────────────────────────────── */}
566:           <AxisRadarCard
567:             profile={axisProfile} title="Ce que tes séances ont surtout sollicité"
568:             subtitle="Une lecture simple de tes objectifs de séance ; ouvre une ligne pour voir la méthode."
569:             sessions={sessions} athleteId={athlete.id} currentWeek={currentWeek}
570:           />
571: 
572:           <details className="card p-4">
573:             <summary className="tap-feedback" style={{ cursor: "pointer", color: "var(--c-text-2)", fontSize: 13, fontWeight: 600 }}>
574:               Voir le détail scientifique de chaque mesure
575:             </summary>
576:             <p className="card-subtitle mt-2 mb-3">La formule et les limites de chaque mesure restent accessibles au toucher.</p>
577:             <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
578:               {advancedMonitoring.map((reading) => (
579:                 <button type="button" key={reading.key} onClick={() => setActiveMetric(reading.key)} className="tap-feedback"
580:                   style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 12, width: "100%", padding: "11px 12px", textAlign: "left", borderRadius: 10, border: "1px solid var(--c-border)", background: "var(--c-surface-2)" }}>
581:                   <span>
582:                     <span style={{ display: "block", fontSize: 13, fontWeight: 600, color: "var(--c-text-1)" }}>{reading.shortLabel}</span>
583:                     <span className="meta-text">{reading.athleteMeaning}</span>
584:                   </span>
585:                   <span className="flex items-center gap-1.5" style={{ color: reading.color, fontSize: 13, fontWeight: 600, flexShrink: 0 }}>
586:                     {reading.displayValue}{reading.unit ? ` ${reading.unit}` : ""}<ChevronRight size={14} />
587:                   </span>
588:                 </button>
589:               ))}
590:             </div>
591:           </details>
592: 
593:           {/* ── Séances cette semaine ───────────────────────────────────────── */}
594:           <div className="card overflow-hidden">
595:             <div style={{ padding: "12px 16px 12px", borderBottom: "1px solid var(--c-border)", display: "flex", alignItems: "center", justifyContent: "space-between" }}>
596:               <div>
597:                 <p className="card-title">Cette semaine</p>
598:                 <p className="card-subtitle">{doneThisWeek}/{weekSessions.length} réalisée{weekSessions.length > 1 ? "s" : ""}</p>
599:               </div>
600:               <button onClick={() => onNavigate("planning")} className="btn-ghost" style={{ minHeight: 36, padding: 0 }}>
601:                 Voir tout
602:               </button>
603:             </div>
604:             {weekSessions.length === 0 ? (
605:               <div style={{ padding: "32px 16px", textAlign: "center" }}>
606:                 <CalendarDays size={20} color="var(--c-text-3)" strokeWidth={1.5} style={{ margin: "0 auto 8px" }} />
607:                 <p style={{ fontSize: 12, color: "var(--c-text-3)" }}>Aucune séance cette semaine</p>
608:               </div>
609:             ) : weekSessions.map((s, idx) => {
610:               const c   = colorsFor(s.category);
611:               const val = s.validations?.find(v => v.athleteId === athlete.id);
612:               const st  = val?.status ?? "future";
613:               const stCfg = {
614:                 done:    { label: "Fait",    bg: "rgba(29,158,117,0.15)",  color: "var(--tone-success)" },
615:                 partial: { label: "Partiel", bg: "rgba(232,160,32,0.15)",  color: "var(--tone-warning)" },
616:                 none:    { label: "Absent",  bg: "rgba(224,82,82,0.15)",   color: "var(--tone-danger)" },
617:                 future:  { label: "À venir", bg: "rgba(255,255,255,0.08)", color: "var(--c-text-3)" },
618:               }[st] ?? { label: "À venir", bg: "rgba(255,255,255,0.08)", color: "var(--c-text-3)" };
619:               return (
620:                 <div key={s.id} style={{ display: "flex", alignItems: "center", gap: 10, padding: "10px 16px", borderTop: idx > 0 ? "1px solid var(--c-border)" : "none" }}>
621:                   {/* Liseré catégorie 2px */}
622:                   <div style={{ width: 2, alignSelf: "stretch", borderRadius: 2, flexShrink: 0, background: c.border }} />
623:                   <div style={{ flex: 1, minWidth: 0 }}>
624:                     <p style={{ fontSize: 12.5, fontWeight: 500, color: "var(--c-text-1)" }} className="truncate">{s.title}</p>
625:                     <p className="meta-text" style={{ marginTop: "var(--space-1)" }}>
626:                       {s.sessionDate
627:                         ? new Date(s.sessionDate).toLocaleDateString("fr-BE", { weekday: "short", day: "numeric", month: "short" })
628:                         : s.day} · {s.time}
629:                     </p>
