115:         supabase.from("records").select("*").eq("athlete_id",athleteId),
116:         supabase.from("injuries").select("*").eq("athlete_id",athleteId),
117:         supabase.from("performance_history").select("*").eq("athlete_id",athleteId),
118:         supabase.from("sessions").select("*, session_athletes(*)").eq("club_id",clubId),
119:         supabase.from("competitions").select("*, competition_athletes(*), competition_results(*)").eq("club_id",clubId),
120:         supabase.from("users").select("id, name").eq("club_id",clubId).eq("role","head_coach").single(),
121:         supabase.from("athletes").select("id, name, profile_data, user_id").eq("club_id",clubId),
122:         supabase.from("athlete_performances").select("*").eq("athlete_id",athleteId).order("performance_date",{ascending:true}),
123:         supabase.from("athlete_goals").select("*").eq("athlete_id",athleteId).order("created_at",{ascending:false}),
124:         supabase.from("athlete_notifications").select("*").eq("athlete_id",athleteId).order("created_at",{ascending:false}).limit(20),
125:         supabase.from("athlete_wellness").select("*").eq("athlete_id",athleteId).gte("date",toLocalDateStr(wellnessStart)).order("date",{ascending:false}),
126:         // Charge hebdomadaire calculée côté serveur (vue weekly_charge, voir
127:         // migration 20260726120000) — plus de recalcul JS à partir des séances.
128:         supabase.from("weekly_charge").select("*").eq("athlete_id",athleteId),
129:         supabase.from("athlete_daily_load_days").select("load_date").eq("athlete_id",athleteId).eq("state","rest_confirmed"),
130:       ]);
131: 
132:       setMyPerformances(myPerfsRes.data ?? []);
133:       setMyGoals(goalsRes.data ?? []);
134:       setMyNotifs(notifsRes?.data ?? []);
135:       const wellnessRows = wellnessRes.data ?? [];
136:       setWellnessHistory(wellnessRows);
137:       setWellnessToday(wellnessRows.find(row => String(row.date).slice(0, 10) === todayStr) ?? null);
138:       setConfirmedRestDays((restDaysRes.data ?? []).map(row => row.load_date));
139: 
140:       const coachId = coachRes.data?.id ?? null;
141:       setCoachUserId(coachId); setCoachName(coachRes.data?.name ?? null);
142: 
143:       if (coachId) {
144:         const {data:msgs} = await supabase.from("messages").select("*")
145:           .or(`and(sender_id.eq.${coachId},receiver_id.eq.${profile.id}),and(sender_id.eq.${profile.id},receiver_id.eq.${coachId})`)
146:           .order("created_at",{ascending:false}).limit(3);
147:         setLastMessages((msgs??[]).filter(m=>m.sender_id===coachId));
148:       }
149: 
150:       setAllAthletes((allAthletesRes.data??[]).map(a=>({id:a.id,name:a.name,user_id:a.user_id,avatar:a.profile_data?.avatar??initialsFromName(a.name)})));
151: 
152:       const pd   = a.profile_data ?? {};
153:       const recs = {};
154:       (recordsRes.data??[]).forEach(r=>{ recs[r.discipline]={...r,sb:r.sb,pr:r.pr,prDate:r.pr_date}; });
155: 
156:       setAthlete({
157:         id:a.id, name:a.name, age:a.age,
158:         avatar:pd.avatar??initialsFromName(a.name),
159:         mainDiscipline:a.main_discipline,
160:         secondaryDisciplines:pd.secondary_disciplines??[],
161:         group:a.group_name, level:pd.level??null,
162:         records:recs,
163:         injuries:(injuriesRes.data??[]).map(i=>({id:i.id,name:i.name,location:i.location,intensity:i.intensity,status:i.status,startDate:i.start_date,endDate:i.end_date,notes:i.notes})),
164:         performanceHistory:(perfHistRes.data??[]).sort((x,y)=>x.month.localeCompare(y.month)),
165:         profile:pd.profile??{},
166:       });
167: 
168:       const allSessions = (sessionsRes.data??[]).map(s=>{
169:         const rows = s.session_athletes??[];
170:         return {
171:           id:s.id, week:s.week, day:s.day, sessionDate:s.session_date, time:s.time,
172:           type:s.type, category:s.category, trainingFocus:s.training_focus, title:s.title, description:s.description,
173:           instructions:s.instructions, durationMinutes:s.duration_minutes, pdfUrl:s.pdf_url,
174:           createdBy:s.created_by,
175:           lifecycleStatus:s.lifecycle_status ?? "planned", startedAt:s.started_at, closedAt:s.closed_at,
176:           athleteIds:rows.map(v=>v.athlete_id),
177:           validations:rows.map(v=>({
178:             athleteId:v.athlete_id,status:v.status,feeling:v.feeling,fatigue:v.fatigue,
179:             comment:v.comment,rpe:v.rpe,actualDurationMinutes:v.actual_duration_minutes,
180:             durationSource:v.duration_source,
181:             rsvpStatus:v.rsvp_status,rsvpNote:v.rsvp_note,rsvpUpdatedAt:v.rsvp_updated_at,
182:             coachNote:v.coach_note,feedbackSubmittedAt:v.feedback_submitted_at,
183:           })),
184:         };
185:       }).filter(s=>s.athleteIds.includes(athleteId));
186: 
187:       const allComps = (compsRes.data??[]).map(c=>({
188:         id:c.id, name:c.name, date:c.date, location:c.location, type:c.type,
189:         athleteIds:(c.competition_athletes??[]).map(x=>x.athlete_id),
190:         plannedEvents:Object.fromEntries((c.competition_athletes??[]).map(x=>[x.athlete_id,x.planned_event])),
191:         results:(c.competition_results??[]).map(r=>({...r,athleteId:r.athlete_id,event:r.event,result:r.result,context:r.context})),
192:       })).filter(c=>c.athleteIds.includes(athleteId));
193: 
194:       const charge = (weeklyChargeRes.data??[]).map(c=>({
195:         athleteId:c.athlete_id,week:c.week,isoYear:c.iso_year,rawLoad:c.raw_load,
196:         dailyLoads:c.daily_loads??[],knownDays:c.known_days??0,
197:         unknownDays:c.unknown_days??0,estimatedDays:c.estimated_days??0,
198:       }));
199: 
200:       setWeeklyCharge(charge);
201:       setSessions(allSessions);
202:       setCompetitions(allComps);
203: 
204:       // Récap perso samedi soir — au cas où le coach n'a pas encore ouvert
205:       // son dashboard (qui envoie aussi celui-ci en boucle sur tout le club).
206:       await notifyAthleteWeeklyRecap(
207:         clubId,
208:         { id: athleteId, name: a.name },
209:         allSessions,
210:         getISOWeek(new Date()),
211:         getISOWeekYear(new Date()),
212:       );
213:       // Rapport hebdomadaire — même fallback, au cas où le coach n'a pas
214:       // encore ouvert son Dashboard (qui envoie aussi celui-ci pour tout
215:       // le club via checkWeeklyReports).
216:       await notifyAthleteWeeklyReport(
217:         clubId,
218:         { id: athleteId, name: a.name },
219:         getISOWeek(new Date()),
220:         getISOWeekYear(new Date()),
221:       );
222:     } catch(err) {
223:       console.error("AthleteApp:", err);
224:       setError(err.message ?? "Erreur inconnue");
225:     } finally { setLoading(false); }
226:   }, [clubId, profile?.id]);
227: 
228:   useEffect(() => { fetchAll(); }, [fetchAll]);
229: 
230:   const wellnessShownRef = useRef(false);
231:   useEffect(() => {
232:     if (!athlete || loading) return;
233:     // Si déjà rempli aujourd'hui -> jamais afficher
234:     if (wellnessToday) return;
235:     // Clé unique par jour — évite le réaffichage au rechargement de page
236:     const today = toLocalDateStr(new Date());
237:     const ssKey = `wellness_shown_${athlete.id}_${today}`;
238:     if (sessionStorage.getItem(ssKey)) return;
239:     if (wellnessShownRef.current) return;
240:     wellnessShownRef.current = true;
241:     sessionStorage.setItem(ssKey, "1");
242:     setShowWellness(true);
243:   }, [athlete, wellnessToday, loading]);
244: 
245:   // Le push navigateur reste inchangé. Cette écoute ajoute uniquement le
246:   // retour visuel instantané quand l'application est déjà ouverte.
247:   useEffect(() => {
248:     if (!athlete?.id) return undefined;
249:     const channel = supabase.channel(`athlete-notifications-${athlete.id}`)
250:       .on("postgres_changes", {
251:         event:"INSERT", schema:"public", table:"athlete_notifications",
252:         filter:`athlete_id=eq.${athlete.id}`,
253:       }, payload => {
254:         setMyNotifs(previous => mergeIncomingNotification(previous, payload.new));
255:         setIncomingNotification(payload.new);
256:       })
257:       .subscribe();
258:     return () => supabase.removeChannel(channel);
259:   }, [athlete?.id]);
260: 
261:   const dismissIncomingNotification = useCallback(() => setIncomingNotification(null), []);
262: 
263:   const openNotification = useCallback(async notification => {
264:     const presentation = getNotificationPresentation(notification);
265:     const wasUnread = !notification.is_read;
266:     setIncomingNotification(current => current?.id === notification.id ? null : current);
267:     setShowNotifs(false);
268:     if (wasUnread) {
269:       setMyNotifs(previous => previous.map(item => item.id === notification.id ? { ...item, is_read:true } : item));
270:     }
271:     navigate(presentation.destination);
272:     if (!wasUnread) return;
273:     const { error:updateError } = await supabase.from("athlete_notifications")
274:       .update({ is_read:true })
275:       .eq("id", notification.id)
276:       .eq("athlete_id", notification.athlete_id);
277:     if (updateError) {
278:       console.error("AthleteApp — notification lue :", updateError);
279:       setMyNotifs(previous => previous.map(item => item.id === notification.id ? { ...item, is_read:false } : item));
280:     }
281:   }, [navigate]);
282: 
283:   const markAllNotificationsRead = useCallback(async () => {
284:     if (!athlete?.id) return false;
285:     const unreadIds = myNotifs.filter(notification => !notification.is_read).map(notification => notification.id);
286:     if (!unreadIds.length) return true;
287:     const unreadSet = new Set(unreadIds);
288:     setMyNotifs(previous => previous.map(notification => unreadSet.has(notification.id) ? { ...notification, is_read:true } : notification));
289:     const { error:updateError } = await supabase.from("athlete_notifications")
290:       .update({ is_read:true })
291:       .eq("athlete_id", athlete.id)
292:       .eq("is_read", false);
293:     if (!updateError) return true;
294:     console.error("AthleteApp — toutes notifications lues :", updateError);
295:     setMyNotifs(previous => previous.map(notification => unreadSet.has(notification.id) ? { ...notification, is_read:false } : notification));
296:     return false;
297:   }, [athlete?.id, myNotifs]);
298: 
299:   const handleRpe = useCallback(async (sid,aid,rpe,actualDurationMinutes) => {
300:     const duration = Number(actualDurationMinutes);
301:     if (!Number.isFinite(duration) || duration <= 0 || duration > 1440) return;
302:     setSessions(p=>p.map(s=>s.id!==sid?s:{...s,validations:s.validations.map(v=>v.athleteId===aid?{
303:       ...v,rpe,actualDurationMinutes:duration,durationSource:"reported",
304:     }:v)}));
305:     await supabase.from("session_athletes").update({
306:       rpe, actual_duration_minutes:duration, duration_source:"reported", feedback_submitted_at:new Date().toISOString(),
307:     }).eq("session_id",sid).eq("athlete_id",aid);
308:   }, []);
309:   const confirmRestDay = useCallback(async (date = toLocalDateStr(new Date())) => {
310:     if (!athlete?.id) return false;
311:     const { error: restError } = await supabase.from("athlete_daily_load_days").upsert({
312:       athlete_id: athlete.id, load_date: date, state: "rest_confirmed", updated_at: new Date().toISOString(),
313:     }, { onConflict: "athlete_id,load_date" });
314:     if (restError) {
315:       console.error("AthleteApp — confirmation repos :", restError);
316:       return false;
317:     }
318:     setConfirmedRestDays(previous => previous.includes(date) ? previous : [...previous, date]);
319:     const week = getISOWeek(new Date(`${date}T00:00:00`));
320:     const isoYear = getISOWeekYear(new Date(`${date}T00:00:00`));
321:     setWeeklyCharge(previous => {
322:       const index = previous.findIndex(row =>
323:         row.athleteId === athlete.id && matchesISOWeek(row, week, isoYear)
324:       );
325:       const point = { date, load: 0, estimated: false, complete: true };
326:       if (index < 0) return [...previous, { athleteId: athlete.id, week, isoYear, rawLoad: 0, dailyLoads: [point], knownDays: 1, unknownDays: 0, estimatedDays: 0 }];
327:       const next = [...previous];
328:       const row = next[index];
329:       const alreadyPresent = (row.dailyLoads ?? []).some(day => day.date === date);
330:       next[index] = alreadyPresent ? row : { ...row, dailyLoads: [...(row.dailyLoads ?? []), point], knownDays: (row.knownDays ?? 0) + 1 };
331:       return next;
332:     });
333:     return true;
334:   }, [athlete?.id]);
335:   const handleStatus = useCallback(async (sid,aid,status) => {
336:     setSessions(p=>p.map(s=>s.id!==sid?s:{...s,validations:s.validations.map(v=>v.athleteId===aid?{...v,status}:v)}));
337:     await supabase.from("session_athletes").update({status}).eq("session_id",sid).eq("athlete_id",aid);
338:   }, []);
339:   const handleFeeling = useCallback(async (sid,aid,feeling) => {
340:     setSessions(p=>p.map(s=>s.id!==sid?s:{...s,validations:s.validations.map(v=>v.athleteId===aid?{...v,feeling}:v)}));
341:     await supabase.from("session_athletes").update({feeling}).eq("session_id",sid).eq("athlete_id",aid);
342:   }, []);
343:   const handleComment = useCallback(async (sid,aid,comment) => {
344:     setSessions(p=>p.map(s=>s.id!==sid?s:{...s,validations:s.validations.map(v=>v.athleteId===aid?{...v,comment}:v)}));
345:     await supabase.from("session_athletes").update({comment}).eq("session_id",sid).eq("athlete_id",aid);
346:   }, []);
347:   const handleRsvp = useCallback(async (sid, aid, rsvpStatus, rsvpNote = "") => {
348:     const updatedAt = new Date().toISOString();
349:     const cleanNote = rsvpNote.trim().slice(0, 500);
350:     setSessions(previous => previous.map(session => session.id !== sid ? session : {
351:       ...session,
352:       validations: session.validations.map(validation => validation.athleteId === aid
353:         ? { ...validation, rsvpStatus, rsvpNote: cleanNote, rsvpUpdatedAt: updatedAt }
354:         : validation),
355:     }));
356:     const { error: responseError } = await supabase.from("session_athletes")
357:       .update({ rsvp_status: rsvpStatus, rsvp_note: cleanNote || null, rsvp_updated_at: updatedAt })
358:       .eq("session_id", sid).eq("athlete_id", aid);
359:     if (responseError) { await fetchAll(); throw responseError; }
360:     const session = sessions.find(item => item.id === sid);
361:     if (session) await notifyCoachSessionResponse(clubId, coachUserId, athlete, session, rsvpStatus, cleanNote);
362:   }, [athlete, clubId, coachUserId, fetchAll, sessions]);
363: 
