365:   if (loading) return (
366:     <div className="min-h-screen flex flex-col items-center justify-center gap-5"
367:       style={{ background: "var(--c-bg)" }}>
368:       <AthleteOSBadge size={56} />
369:       <div className="flex flex-col items-center gap-2">
370:         <div className="loader-ring" />
371:         <span style={{ fontSize: 12, color: "var(--c-text-3)", letterSpacing: "0.02em" }}>
372:           Chargement de ton espace…
373:         </span>
374:       </div>
375:     </div>
376:   );
377: 
378:   if (error || !athlete) return (
379:     <div className="min-h-screen flex items-center justify-center p-6"
380:       style={{ background: "var(--c-bg)" }}>
381:       <div className="card p-8 max-w-sm w-full text-center">
382:         <p style={{ fontSize: 15, fontWeight: 500, color: "var(--c-text-1)", marginBottom: 4 }}>
383:           Profil introuvable
384:         </p>
385:         <p style={{ fontSize: 12.5, color: "var(--c-text-3)", marginBottom: 24, lineHeight: 1.6 }}>
386:           {error}
387:         </p>
388:         <button onClick={signOut}
389:           style={{ fontSize: 12, fontWeight: 500, color: "var(--tone-danger)", background: "none", border: "none", cursor: "pointer" }}>
390:           Se déconnecter
391:         </button>
392:       </div>
393:     </div>
394:   );
