504:       {/* ── ZONE PRINCIPALE ── */}
505:       <div className="flex-1 flex flex-col min-w-0 overflow-hidden">
506: 
507:         {/* Header */}
508:         <header className="header-glass flex items-center gap-3 px-4 flex-shrink-0 z-10"
509:           style={{ height: 56 }}>
510:           {/* Logo mobile */}
511:           <div className="flex md:hidden items-center gap-2.5">
512:             {clubBrand?.logoUrl ? (
513:               <img className="club-shell-mark" src={clubBrand.logoUrl} alt={`Logo ${clubBrand.name || "du club"}`} />
514:             ) : (
515:               <AthleteOSBadge size={28} title={null} />
516:             )}
517:             <AthleteOSWordmark size={14} />
518:           </div>
519:           {/* Titre vue — desktop */}
520:           <div className="hidden md:flex items-center gap-2.5">
521:             {(() => {
522:               const Icon = currentNav?.icon;
523:               return Icon ? (
524:                 <div className="w-7 h-7 rounded-lg flex items-center justify-center flex-shrink-0"
525:                   style={{ background: "rgba(29,158,117,0.12)" }}>
526:                   <Icon size={14} color="#1D9E75" strokeWidth={1.8} />
527:                 </div>
528:               ) : null;
529:             })()}
530:             <h1 style={{ fontSize: 15, fontWeight: 500, color: "var(--c-text-1)", letterSpacing: "-0.01em" }}>
531:               {currentNav?.label ?? "Mon espace"}
532:             </h1>
533:           </div>
534:           <div className="flex-1" />
535:           <div className="md:hidden">
536:             <PwaInstallButton expanded={false} onOpenHelp={() => { setSettingsSection("application"); setShowSettings(true); }} />
537:           </div>
538:           <ThemeToggleButton theme={theme} onToggle={toggleTheme} compact />
539:           <button
540:             type="button"
541:             onClick={() => setShowNotifs(true)}
542:             className={["mobile-header-action md:hidden", showNotifs ? "active" : ""].join(" ")}
543:             aria-label={`Notifications${unreadCount > 0 ? `, ${unreadCount} non lue${unreadCount > 1 ? "s" : ""}` : ""}`}
544:             aria-expanded={showNotifs}
545:             aria-haspopup="dialog"
546:           >
547:             <Bell size={19} strokeWidth={showNotifs ? 2.1 : 1.7} aria-hidden="true" />
548:             {unreadCount > 0 && (
549:               <span className="mobile-header-badge" aria-hidden="true">
550:                 {unreadCount > 99 ? "99+" : unreadCount}
551:               </span>
552:             )}
553:           </button>
554:           <button
555:             type="button"
556:             onClick={() => { setSettingsSection("account"); setShowSettings(true); }}
557:             className="mobile-account-action md:hidden"
558:             aria-label="Ouvrir les réglages du compte"
559:           >
560:             {initialsFromName(athlete.name)}
561:           </button>
562:           <div className="hidden md:block">
563:             <PushToggleButton subscribed={subscribed} onToggle={subscribe} permissionState={permissionState} />
564:           </div>
565:         </header>
566: 
567:         {/* Main */}
568:         <main className="flex-1 overflow-y-auto pb-20 md:pb-0">
569:           <div key={viewKey} className="view-transition">
570:           <Suspense fallback={<ViewLoader />}>
571:             {activeView === "dashboard" && (
572:               <AthleteDashboard
573:                 athlete={athlete} weeklyCharge={weeklyCharge} sessions={sessions}
574:                 competitions={competitions} lastMessages={lastMessages} coachName={coachName}
575:                 myPerformances={myPerformances} onNavigate={navigate}
576:                 wellnessToday={wellnessToday} wellnessHistory={wellnessHistory} onOpenWellness={() => setShowWellness(true)}
577:                 confirmedRestDays={confirmedRestDays} onConfirmRestDay={confirmRestDay}
578:                 onOpenInjuryReport={() => setShowInjuryReport(true)}
579:                 allAthletes={allAthletes}
580:                 onRpeChange={handleRpe} onStatusChange={handleStatus}
581:                 onFeelingChange={handleFeeling} onCommentChange={handleComment} onRsvpChange={handleRsvp}
582:               />
583:             )}
584:             {activeView === "planning" && (
585:               <AthletePlanning
586:                 athlete={athlete} sessions={sessions} allAthletes={allAthletes}
587:                 clubId={clubId} createdBy={profile?.id} coachUserId={coachUserId}
588:                 onRpeChange={handleRpe} onStatusChange={handleStatus}
589:                 onFeelingChange={handleFeeling} onCommentChange={handleComment} onRsvpChange={handleRsvp}
590:                 onRefresh={fetchAll}
591:               />
592:             )}
593:             {activeView === "performances" && (
594:               <AthletePerfs
595:                 athlete={athlete} competitions={competitions}
596:                 myPerformances={myPerformances} myGoals={myGoals}
597:                 clubId={clubId} weeklyCharge={weeklyCharge} sessions={sessions} onRefresh={fetchAll}
598:               />
599:             )}
600:             {activeView === "messagerie" && (
601:               <AthleteMsgerie
602:                 athlete={athlete} coachUserId={coachUserId}
603:                 athleteUserId={profile?.id} clubId={clubId}
604:               />
605:             )}
606:             {activeView === "social" && (
607:               <AthleteClub
608:                 athlete={athlete} allAthletes={allAthletes}
609:                 clubId={clubId} coachUserId={coachUserId} sessions={sessions} clubBrand={clubBrand}
610:               />
611:             )}
612:           </Suspense>
613:           </div>
614:         </main>
615:       </div>
616: 
617:       {/* ── BOTTOM NAV MOBILE ── */}
618:       <MobileBottomNav
619:         ariaLabel="Navigation athlète"
620:         items={ATHLETE_MOBILE_NAV_ITEMS.map((item) => ({
621:           ...item,
622:           label: item.shortLabel ?? item.label,
623:           badge: item.id === "messagerie" ? msgUnread : 0,
624:         }))}
625:         activeId={activeView}
626:         onSelect={navigate}
627:       />
628: 
629:       {showNotifs && (
630:         <NotificationCenter
631:           notifications={myNotifs}
632:           subscribed={subscribed}
633:           onSubscribe={subscribe}
634:           permissionState={permissionState}
635:           onClose={() => setShowNotifs(false)}
636:           onOpen={openNotification}
637:           onMarkAllRead={markAllNotificationsRead}
638:         />
639:       )}
640: 
641:       {showWellness && athlete && (
642:         <WellnessModal
643:           athlete={athlete} clubId={clubId}
644:           onClose={() => setShowWellness(false)}
645:           onSaved={(data) => {
646:             // Un seul batch React : ferme ET met à jour
647:             setShowWellness(false);
648:             setWellnessToday(data);
649:             setWellnessHistory(previous => [data, ...previous.filter(row => String(row.date).slice(0, 10) !== String(data.date).slice(0, 10))]);
650:           }}
651:         />
652:       )}
653: 
654:       {showInjuryReport && athlete && (
655:         <InjuryReportModal
656:           athlete={athlete} clubId={clubId}
657:           onClose={() => setShowInjuryReport(false)}
658:           onSaved={() => { setShowInjuryReport(false); fetchAll(); }}
659:         />
660:       )}
661: 
662:       {showSettings && <AccountSettingsModal initialSection={settingsSection} onClose={() => setShowSettings(false)} />}
663:     </div>
664:   );
665: }
